INSERT INTO public.exercises
  (user_id, name, name_vi, name_en, name_es, muscle_group, equipment, exercise_kind, source, source_ref,
   instructions_en, image_paths, search_text)
VALUES
  (NULL, '3/4 Sit-Up', 'Gập bụng 3/4', '3/4 Sit-Up', 'Abdominales 3/4', 'abs', 'bodyweight', 'bodyweight', 'free_exercise_db', '3_4_Sit-Up', ARRAY['Lie down on the floor and secure your feet. Your legs should be bent at the knees.', 'Place your hands behind or to the side of your head. You will begin with your back on the ground. This will be your starting position.', 'Flex your hips and spine to raise your torso toward your knees.', 'At the top of the contraction your torso should be perpendicular to the ground. Reverse the motion, going only ¾ of the way down.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['3_4_Sit-Up/0.jpg', '3_4_Sit-Up/1.jpg']::text[], '3/4 sit-up gap bung 3/4 abdominales 3/4'),
  (NULL, '90/90 Hamstring', 'Giãn đùi sau 90/90', '90/90 Hamstring', 'Estiramiento de isquios 90/90', 'legs', 'bodyweight', 'timed', 'free_exercise_db', '90_90_Hamstring', ARRAY['Lie on your back, with one leg extended straight out.', 'With the other leg, bend the hip and knee to 90 degrees. You may brace your leg with your hands if necessary. This will be your starting position.', 'Extend your leg straight into the air, pausing briefly at the top. Return the leg to the starting position.', 'Repeat for 10-20 repetitions, and then switch to the other leg.']::text[], ARRAY['90_90_Hamstring/0.jpg', '90_90_Hamstring/1.jpg']::text[], '90/90 hamstring gian dui sau 90/90 estiramiento de isquios 90/90'),
  (NULL, 'Ab Crunch Machine', 'Ab Crunch Machine', 'Ab Crunch Machine', 'Crunch en máquina', 'abs', 'machine', 'isolation', 'free_exercise_db', 'Ab_Crunch_Machine', ARRAY['Select a light resistance and sit down on the ab machine placing your feet under the pads provided and grabbing the top handles. Your arms should be bent at a 90 degree angle as you rest the triceps on the pads provided. This will be your starting position.', 'At the same time, begin to lift the legs up as you crunch your upper torso. Breathe out as you perform this movement. Tip: Be sure to use a slow and controlled motion. Concentrate on using your abs to move the weight while relaxing your legs and feet.', 'After a second pause, slowly return to the starting position as you breathe in.', 'Repeat the movement for the prescribed amount of repetitions.']::text[], ARRAY['Ab_Crunch_Machine/0.jpg', 'Ab_Crunch_Machine/1.jpg']::text[], 'ab crunch machine gap bung may crunch en maquina'),
  (NULL, 'Ab Roller', 'Lăn bánh xe bụng', 'Ab Roller', 'Rueda abdominal', 'abs', 'other', 'compound', 'free_exercise_db', 'Ab_Roller', ARRAY['Hold the Ab Roller with both hands and kneel on the floor.', 'Now place the ab roller on the floor in front of you so that you are on all your hands and knees (as in a kneeling push up position). This will be your starting position.', 'Slowly roll the ab roller straight forward, stretching your body into a straight position. Tip: Go down as far as you can without touching the floor with your body. Breathe in during this portion of the movement.', 'After a pause at the stretched position, start pulling yourself back to the starting position as you breathe out. Tip: Go slowly and keep your abs tight at all times.']::text[], ARRAY['Ab_Roller/0.jpg', 'Ab_Roller/1.jpg']::text[], 'ab roller lan banh xe bung rueda abdominal'),
  (NULL, 'Adductor', 'Lăn giãn đùi trong', 'Adductor', 'Liberación de aductores con rodillo', 'legs', 'foam roll', 'timed', 'free_exercise_db', 'Adductor', ARRAY['Lie face down with one leg on a foam roll.', 'Rotate the leg so that the foam roll contacts against your inner thigh. Shift as much weight onto the foam roll as can be tolerated.', 'While trying to relax the muscles if the inner thigh, roll over the foam between your hip and knee, holding points of tension for 10-30 seconds. Repeat with the other leg.']::text[], ARRAY['Adductor/0.jpg', 'Adductor/1.jpg']::text[], 'adductor lan gian dui trong liberacion de aductores con rodillo'),
  (NULL, 'Adductor/Groin', 'Giãn đùi trong và háng', 'Adductor/Groin', 'Estiramiento de aductores e ingle', 'legs', 'other', 'timed', 'free_exercise_db', 'Adductor_Groin', ARRAY['Lie on your back with your feet raised towards the ceiling.', 'Have your partner hold your feet or ankles. Abduct your legs as far as you can. This will be your starting position.', 'Attempt to squeeze your legs together for 10 or more seconds, while your partner prevents you from doing so.', 'Now, relax the muscles in your legs as your partner pushes your feet apart, stretching as far as is comfortable for you. Be sure to let your partner know when the stretch is adequate to prevent overstretching or injury.']::text[], ARRAY['Adductor_Groin/0.jpg', 'Adductor_Groin/1.jpg']::text[], 'adductor/groin gian dui trong va hang estiramiento de aductores e ingle'),
  (NULL, 'Advanced Kettlebell Windmill', 'Cối xay gió kettlebell nâng cao', 'Advanced Kettlebell Windmill', 'Molino avanzado con pesa rusa', 'abs', 'kettlebell', 'isolation', 'free_exercise_db', 'Advanced_Kettlebell_Windmill', ARRAY['Clean and press a kettlebell overhead with one arm.', 'Keeping the kettlebell locked out at all times, push your butt out in the direction of the locked out kettlebell. Keep the non-working arm behind your back and turn your feet out at a forty-five degree angle from the arm with the kettlebell.', 'Lower yourself as far as possible.', 'Pause for a second and reverse the motion back to the starting position.']::text[], ARRAY['Advanced_Kettlebell_Windmill/0.jpg', 'Advanced_Kettlebell_Windmill/1.jpg']::text[], 'advanced kettlebell windmill coi xay gio kettlebell nang cao molino avanzado con pesa rusa'),
  (NULL, 'Air Bike', 'Gập bụng đạp xe', 'Air Bike', 'Abdominales bicicleta', 'abs', 'bodyweight', 'bodyweight', 'free_exercise_db', 'Air_Bike', ARRAY['Lie flat on the floor with your lower back pressed to the ground. For this exercise, you will need to put your hands beside your head. Be careful however to not strain with the neck as you perform it. Now lift your shoulders into the crunch position.', 'Bring knees up to where they are perpendicular to the floor, with your lower legs parallel to the floor. This will be your starting position.', 'Now simultaneously, slowly go through a cycle pedal motion kicking forward with the right leg and bringing in the knee of the left leg. Bring your right elbow close to your left knee by crunching to the side, as you breathe out.', 'Go back to the initial position as you breathe in.', 'Crunch to the opposite side as you cycle your legs and bring closer your left elbow to your right knee and exhale.', 'Continue alternating in this manner until all of the recommended repetitions for each side have been completed.']::text[], ARRAY['Air_Bike/0.jpg', 'Air_Bike/1.jpg']::text[], 'air bike gap bung dap xe abdominales bicicleta'),
  (NULL, 'All Fours Quad Stretch', 'Giãn đùi trước tư thế bò', 'All Fours Quad Stretch', 'Estiramiento de cuádriceps en cuadrupedia', 'legs', 'bodyweight', 'timed', 'free_exercise_db', 'All_Fours_Quad_Stretch', ARRAY['Start off on your hands and knees, then lift your leg off the floor and hold the foot with your hand.', 'Use your hand to hold the foot or ankle, keeping the knee fully flexed, stretching the quadriceps and hip flexors.', 'Focus on extending your hips, thrusting them towards the floor. Hold for 10-20 seconds and then switch sides.']::text[], ARRAY['All_Fours_Quad_Stretch/0.jpg', 'All_Fours_Quad_Stretch/1.jpg']::text[], 'all fours quad stretch gian dui truoc tu the bo estiramiento de cuadriceps en cuadrupedia'),
  (NULL, 'Alternate Hammer Curl', 'Alternate Hammer Curl', 'Alternate Hammer Curl', 'Curl martillo alterno', 'biceps', 'dumbbell', 'isolation', 'free_exercise_db', 'Alternate_Hammer_Curl', ARRAY['Stand up with your torso upright and a dumbbell in each hand being held at arms length. The elbows should be close to the torso.', 'The palms of the hands should be facing your torso. This will be your starting position.', 'While holding the upper arm stationary, curl the right weight forward while contracting the biceps as you breathe out. Continue the movement until your biceps is fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a second as you squeeze the biceps. Tip: Only the forearms should move.', 'Slowly begin to bring the dumbbells back to starting position as your breathe in.', 'Repeat the movement with the left hand. This equals one repetition.', 'Continue alternating in this manner for the recommended amount of repetitions.']::text[], ARRAY['Alternate_Hammer_Curl/0.jpg', 'Alternate_Hammer_Curl/1.jpg']::text[], 'alternate hammer curl cuon bua luan phien curl martillo alterno'),
  (NULL, 'Alternate Heel Touchers', 'Chạm gót luân phiên', 'Alternate Heel Touchers', 'Toques de talón alternos', 'abs', 'bodyweight', 'bodyweight', 'free_exercise_db', 'Alternate_Heel_Touchers', ARRAY['Lie on the floor with the knees bent and the feet on the floor around 18-24 inches apart. Your arms should be extended by your side. This will be your starting position.', 'Crunch over your torso forward and up about 3-4 inches to the right side and touch your right heel as you hold the contraction for a second. Exhale while performing this movement.', 'Now go back slowly to the starting position as you inhale.', 'Now crunch over your torso forward and up around 3-4 inches to the left side and touch your left heel as you hold the contraction for a second. Exhale while performing this movement and then go back to the starting position as you inhale. Now that both heels have been touched, that is considered 1 repetition.', 'Continue alternating sides in this manner until all prescribed repetitions are done.']::text[], ARRAY['Alternate_Heel_Touchers/0.jpg', 'Alternate_Heel_Touchers/1.jpg']::text[], 'alternate heel touchers cham got luan phien toques de talon alternos'),
  (NULL, 'Alternate Incline Dumbbell Curl', 'Alternate Incline Dumbbell Curl', 'Alternate Incline Dumbbell Curl', 'Curl inclinado alterno con mancuernas', 'biceps', 'dumbbell', 'isolation', 'free_exercise_db', 'Alternate_Incline_Dumbbell_Curl', ARRAY['Sit down on an incline bench with a dumbbell in each hand being held at arms length. Tip: Keep the elbows close to the torso.This will be your starting position.', 'While holding the upper arm stationary, curl the right weight forward while contracting the biceps as you breathe out. As you do so, rotate the hand so that the palm is facing up. Continue the movement until your biceps is fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a second as you squeeze the biceps. Tip: Only the forearms should move.', 'Slowly begin to bring the dumbbell back to starting position as your breathe in.', 'Repeat the movement with the left hand. This equals one repetition.', 'Continue alternating in this manner for the recommended amount of repetitions.']::text[], ARRAY['Alternate_Incline_Dumbbell_Curl/0.jpg', 'Alternate_Incline_Dumbbell_Curl/1.jpg']::text[], 'alternate incline dumbbell curl cuon ta don ghe doc luan phien curl inclinado alterno con mancuernas'),
  (NULL, 'Alternate Leg Diagonal Bound', 'Bật xa chéo luân phiên', 'Alternate Leg Diagonal Bound', 'Saltos diagonales alternos', 'legs', 'other', 'bodyweight', 'free_exercise_db', 'Alternate_Leg_Diagonal_Bound', ARRAY['Assume a comfortable stance with one foot slightly in front of the other.', 'Begin by pushing off with the front leg, driving the opposite knee forward and as high as possible before landing. Attempt to cover as much distance to each side with each bound.', 'It may help to use a line on the ground to guage distance from side to side.', 'Repeat the sequence with the other leg.']::text[], ARRAY['Alternate_Leg_Diagonal_Bound/0.jpg', 'Alternate_Leg_Diagonal_Bound/1.jpg']::text[], 'alternate leg diagonal bound bat xa cheo luan phien saltos diagonales alternos'),
  (NULL, 'Alternating Cable Shoulder Press', 'Đẩy vai cáp luân phiên', 'Alternating Cable Shoulder Press', 'Press de hombros alterno en polea', 'shoulders', 'cable', 'compound', 'free_exercise_db', 'Alternating_Cable_Shoulder_Press', ARRAY['Move the cables to the bottom of the tower and select an appropriate weight.', 'Grasp the cables and hold them at shoulder height, palms facing forward. This will be your starting position.', 'Keeping your head and chest up, extend through the elbow to press one side directly over head.', 'After pausing at the top, return to the starting position and repeat on the opposite side.']::text[], ARRAY['Alternating_Cable_Shoulder_Press/0.jpg', 'Alternating_Cable_Shoulder_Press/1.jpg']::text[], 'alternating cable shoulder press day vai cap luan phien press de hombros alterno en polea'),
  (NULL, 'Alternating Deltoid Raise', 'Nâng vai luân phiên', 'Alternating Deltoid Raise', 'Elevación de deltoides alterna', 'shoulders', 'dumbbell', 'isolation', 'free_exercise_db', 'Alternating_Deltoid_Raise', ARRAY['In a standing position, hold a pair of dumbbells at your side.', 'Keeping your elbows slightly bent, raise the weights directly in front of you to shoulder height, avoiding any swinging or cheating.', 'Return the weights to your side.', 'On the next repetition, raise the weights laterally, raising them out to your side to about shoulder height.', 'Return the weights to the starting position and continue alternating to the front and side.']::text[], ARRAY['Alternating_Deltoid_Raise/0.jpg', 'Alternating_Deltoid_Raise/1.jpg']::text[], 'alternating deltoid raise nang vai luan phien elevacion de deltoides alterna'),
  (NULL, 'Alternating Floor Press', 'Đẩy sàn kettlebell luân phiên', 'Alternating Floor Press', 'Press en el suelo alterno con pesa rusa', 'chest', 'kettlebell', 'compound', 'free_exercise_db', 'Alternating_Floor_Press', ARRAY['Lie on the floor with two kettlebells next to your shoulders.', 'Position one in place on your chest and then the other, gripping the kettlebells on the handle with the palms facing forward.', 'Extend both arms, so that the kettlebells are being held above your chest. Lower one kettlebell, bringing it to your chest and turn the wrist in the direction of the locked out kettlebell.', 'Raise the kettlebell and repeat on the opposite side.']::text[], ARRAY['Alternating_Floor_Press/0.jpg', 'Alternating_Floor_Press/1.jpg']::text[], 'alternating floor press day san kettlebell luan phien press en el suelo alterno con pesa rusa'),
  (NULL, 'Alternating Hang Clean', 'Alternating Hang Clean', 'Alternating Hang Clean', 'Cargada colgante alterna con pesa rusa', 'legs', 'kettlebell', 'compound', 'free_exercise_db', 'Alternating_Hang_Clean', ARRAY['Place two kettlebells between your feet. To get in the starting position, push your butt back and look straight ahead.', 'Clean one kettlebell to your shoulder and hold on to the other kettlebell in a hanging position. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulders. Rotate your wrist as you do so.', 'Lower the cleaned kettlebell to a hanging position and clean the alternate kettlebell. Repeat.']::text[], ARRAY['Alternating_Hang_Clean/0.jpg', 'Alternating_Hang_Clean/1.jpg']::text[], 'alternating hang clean hang clean kettlebell luan phien cargada colgante alterna con pesa rusa'),
  (NULL, 'Alternating Kettlebell Press', 'Đẩy vai kettlebell luân phiên', 'Alternating Kettlebell Press', 'Press alterno con pesa rusa', 'shoulders', 'kettlebell', 'compound', 'free_exercise_db', 'Alternating_Kettlebell_Press', ARRAY['Clean two kettlebells to your shoulders. Clean the kettlebells to your shoulders by extending through the legs and hips as you pull the kettlebells towards your shoulders. Rotate your wrists as you do so.', 'Press one directly overhead by extending through the elbow, turning it so the palm faces forward while holding the other kettlebell stationary .', 'Lower the pressed kettlebell to the starting position and immediately press with your other arm.']::text[], ARRAY['Alternating_Kettlebell_Press/0.jpg', 'Alternating_Kettlebell_Press/1.jpg']::text[], 'alternating kettlebell press day vai kettlebell luan phien press alterno con pesa rusa'),
  (NULL, 'Alternating Kettlebell Row', 'Chèo kettlebell luân phiên', 'Alternating Kettlebell Row', 'Remo alterno con pesa rusa', 'back', 'kettlebell', 'isolation', 'free_exercise_db', 'Alternating_Kettlebell_Row', ARRAY['Place two kettlebells in front of your feet. Bend your knees slightly and push your butt out as much as possible. As you bend over to get into the starting position grab both kettlebells by the handles.', 'Pull one kettlebell off of the floor while holding on to the other kettlebell. Retract the shoulder blade of the working side, as you flex the elbow, drawing the kettlebell towards your stomach or rib cage.', 'Lower the kettlebell in the working arm and repeat with your other arm.']::text[], ARRAY['Alternating_Kettlebell_Row/0.jpg', 'Alternating_Kettlebell_Row/1.jpg']::text[], 'alternating kettlebell row cheo kettlebell luan phien remo alterno con pesa rusa'),
  (NULL, 'Alternating Renegade Row', 'Chèo renegade luân phiên', 'Alternating Renegade Row', 'Remo renegado alterno', 'back', 'kettlebell', 'compound', 'free_exercise_db', 'Alternating_Renegade_Row', ARRAY['Place two kettlebells on the floor about shoulder width apart. Position yourself on your toes and your hands as though you were doing a pushup, with the body straight and extended. Use the handles of the kettlebells to support your upper body. You may need to position your feet wide for support.', 'Push one kettlebell into the floor and row the other kettlebell, retracting the shoulder blade of the working side as you flex the elbow, pulling it to your side.', 'Then lower the kettlebell to the floor and begin the kettlebell in the opposite hand. Repeat for several reps.']::text[], ARRAY['Alternating_Renegade_Row/0.jpg', 'Alternating_Renegade_Row/1.jpg']::text[], 'alternating renegade row cheo renegade luan phien remo renegado alterno'),
  (NULL, 'Ankle Circles', 'Xoay cổ chân', 'Ankle Circles', 'Círculos de tobillo', 'calves', 'other', 'timed', 'free_exercise_db', 'Ankle_Circles', ARRAY['Use a sturdy object like a squat rack to hold yourself.', 'Lift the right leg in the air (just around 2 inches from the floor) and perform a circular motion with the big toe. Pretend that you are drawing a big circle with it. Tip: One circle equals 1 repetition. Breathe normally as you perform the movement.', 'When you are done with the right foot, then repeat with the left leg.']::text[], ARRAY['Ankle_Circles/0.jpg', 'Ankle_Circles/1.jpg']::text[], 'ankle circles xoay co chan circulos de tobillo'),
  (NULL, 'Ankle On The Knee', 'Giãn mông cổ chân trên gối', 'Ankle On The Knee', 'Estiramiento de glúteo tobillo sobre rodilla', 'glutes', 'other', 'timed', 'free_exercise_db', 'Ankle_On_The_Knee', ARRAY['From a lying position, bend your knees and keep your feet on the floor.', 'Place your ankle of one foot on your opposite knee.', 'Grasp the thigh or knee of the bottom leg and pull both of your legs into the chest. Relax your neck and shoulders. Hold for 10-20 seconds and then switch sides.']::text[], ARRAY['Ankle_On_The_Knee/0.jpg', 'Ankle_On_The_Knee/1.jpg']::text[], 'ankle on the knee gian mong co chan tren goi estiramiento de gluteo tobillo sobre rodilla'),
  (NULL, 'Anterior Tibialis-SMR', 'Lăn giãn cơ chày trước', 'Anterior Tibialis-SMR', 'Liberación del tibial anterior', 'calves', 'other', 'timed', 'free_exercise_db', 'Anterior_Tibialis-SMR', ARRAY['Begin seated on the ground with your legs bent and your feet on the floor.', 'Using a Muscle Roller or a rolling pin, apply pressure to the muscles on the outside of your shins. Work from just below the knee to above the ankle, pausing at points of tension for 10-30 seconds. Repeat on the other leg.']::text[], ARRAY['Anterior_Tibialis-SMR/0.jpg', 'Anterior_Tibialis-SMR/1.jpg']::text[], 'anterior tibialis-smr lan gian co chay truoc liberacion del tibial anterior'),
  (NULL, 'Anti-Gravity Press', 'Đẩy vai chống trọng lực', 'Anti-Gravity Press', 'Press antigravedad', 'shoulders', 'barbell', 'compound', 'free_exercise_db', 'Anti-Gravity_Press', ARRAY['Place a bar on the ground behind the head of an incline bench.', 'Lay on the bench face down. With a pronated grip, pick the barbell up from the floor. Flex the elbows, performing a reverse curl to bring the bar near your chest. This will be your starting position.', 'To begin, press the barbell out in front of your head by extending your elbows. Keep your arms parallel to the ground throughout the movement.', 'Return to the starting position and repeat to complete the set.']::text[], ARRAY['Anti-Gravity_Press/0.jpg', 'Anti-Gravity_Press/1.jpg']::text[], 'anti-gravity press day vai chong trong luc press antigravedad'),
  (NULL, 'Arm Circles', 'Xoay tay', 'Arm Circles', 'Círculos de brazos', 'shoulders', 'other', 'timed', 'free_exercise_db', 'Arm_Circles', ARRAY['Stand up and extend your arms straight out by the sides. The arms should be parallel to the floor and perpendicular (90-degree angle) to your torso. This will be your starting position.', 'Slowly start to make circles of about 1 foot in diameter with each outstretched arm. Breathe normally as you perform the movement.', 'Continue the circular motion of the outstretched arms for about ten seconds. Then reverse the movement, going the opposite direction.']::text[], ARRAY['Arm_Circles/0.jpg', 'Arm_Circles/1.jpg']::text[], 'arm circles xoay tay circulos de brazos'),
  (NULL, 'Arnold Dumbbell Press', 'Arnold Dumbbell Press', 'Arnold Dumbbell Press', 'Press Arnold con mancuernas', 'shoulders', 'dumbbell', 'compound', 'free_exercise_db', 'Arnold_Dumbbell_Press', ARRAY['Sit on an exercise bench with back support and hold two dumbbells in front of you at about upper chest level with your palms facing your body and your elbows bent. Tip: Your arms should be next to your torso. The starting position should look like the contracted portion of a dumbbell curl.', 'Now to perform the movement, raise the dumbbells as you rotate the palms of your hands until they are facing forward.', 'Continue lifting the dumbbells until your arms are extended above you in straight arm position. Breathe out as you perform this portion of the movement.', 'After a second pause at the top, begin to lower the dumbbells to the original position by rotating the palms of your hands towards you. Tip: The left arm will be rotated in a counter clockwise manner while the right one will be rotated clockwise. Breathe in as you perform this portion of the movement.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Arnold_Dumbbell_Press/0.jpg', 'Arnold_Dumbbell_Press/1.jpg']::text[], 'arnold dumbbell press day vai arnold ta don press arnold con mancuernas'),
  (NULL, 'Around The Worlds', 'Vòng quanh thế giới tạ đơn', 'Around The Worlds', 'Vueltas al mundo con mancuernas', 'chest', 'dumbbell', 'compound', 'free_exercise_db', 'Around_The_Worlds', ARRAY['Lay down on a flat bench holding a dumbbell in each hand with the palms of the hands facing towards the ceiling. Tip: Your arms should be parallel to the floor and next to your thighs. To avoid injury, make sure that you keep your elbows slightly bent. This will be your starting position.', 'Now move the dumbbells by creating a semi-circle as you displace them from the initial position to over the head. All of the movement should happen with the arms parallel to the floor at all times. Breathe in as you perform this portion of the movement.', 'Reverse the movement to return the weight to the starting position as you exhale.']::text[], ARRAY['Around_The_Worlds/0.jpg', 'Around_The_Worlds/1.jpg']::text[], 'around the worlds vong quanh the gioi ta don vueltas al mundo con mancuernas'),
  (NULL, 'Atlas Stone Trainer', 'Tập nâng đá Atlas', 'Atlas Stone Trainer', 'Entrenador de piedra Atlas', 'back', 'other', 'compound', 'free_exercise_db', 'Atlas_Stone_Trainer', ARRAY['This trainer is effective for developing Atlas Stone strength for those who don''t have access to stones, and are typically made from bar ends or heavy pipe.', 'Begin by loading the desired weight onto the bar. Straddle the weight, wrapping your arms around the implement, bending at the hips.', 'Begin by pulling the weight up past the knees, extending through the hips. As the weight clears the knees, it can be lapped by resting it on your thighs and sitting back, hugging it tightly to your chest.', 'Finish the movement by extending through your hips and knees to raise the weight as high as possible. The weight can be returned to the lap or to the ground for successive repetitions.']::text[], ARRAY['Atlas_Stone_Trainer/0.jpg', 'Atlas_Stone_Trainer/1.jpg']::text[], 'atlas stone trainer tap nang da atlas entrenador de piedra atlas'),
  (NULL, 'Atlas Stones', 'Nâng đá Atlas', 'Atlas Stones', 'Piedras Atlas', 'back', 'other', 'compound', 'free_exercise_db', 'Atlas_Stones', ARRAY['Begin with the atlas stone between your feet. Bend at the hips to wrap your arms vertically around the Atlas Stone, attempting to get your fingers underneath the stone. Many stones will have a small flat portion on the bottom, which will make the stone easier to hold.', 'Pulling the stone into your torso, drive through the back half of your feet to pull the stone from the ground.', 'As the stone passes the knees, lap it by sitting backward, pulling the stone on top of your thighs.', 'Sit low, getting the stone high onto your chest as you change your grip to reach over the stone. Stand, driving through with your hips. Close distance to the loading platform, and lean back, extending the hips to get the stone as high as possible.']::text[], ARRAY['Atlas_Stones/0.jpg', 'Atlas_Stones/1.jpg']::text[], 'atlas stones nang da atlas piedras atlas'),
  (NULL, 'Axle Deadlift', 'Axle Deadlift', 'Axle Deadlift', 'Peso muerto con eje', 'back', 'other', 'compound', 'free_exercise_db', 'Axle_Deadlift', ARRAY['Approach the bar so that it is centered over your feet. You feet should be about hip width apart. Bend at the hip to grip the bar at shoulder width, allowing your shoulder blades to protract. Typically, you would use an over/under grip.', 'With your feet and your grip set, take a big breath and then lower your hips and flex the knees until your shins contact the bar. Look forward with your head, keep your chest up and your back arched, and begin driving through the heels to move the weight upward.', 'After the bar passes the knees, aggressively pull the bar back, pulling your shoulder blades together as you drive your hips forward into the bar.', 'Lower the bar by bending at the hips and guiding it to the floor.']::text[], ARRAY['Axle_Deadlift/0.jpg', 'Axle_Deadlift/1.jpg']::text[], 'axle deadlift deadlift thanh truc peso muerto con eje'),
  (NULL, 'Back Flyes - With Bands', 'Back Flyes - With Bands', 'Back Flyes - With Bands', 'Aperturas posteriores con banda', 'shoulders', 'band', 'compound', 'free_exercise_db', 'Back_Flyes_-_With_Bands', ARRAY['Run a band around a stationary post like that of a squat rack.', 'Grab the band by the handles and stand back so that the tension in the band rises.', 'Extend and lift the arms straight in front of you. Tip: Your arms should be straight and parallel to the floor while perpendicular to your torso. Your feet should be firmly planted on the floor spread at shoulder width. This will be your starting position.', 'As you exhale, move your arms to the sides and back. Keep your arms extended and parallel to the floor. Continue the movement until the arms are extended to your sides.', 'After a pause, go back to the original position as you inhale.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Back_Flyes_-_With_Bands/0.jpg', 'Back_Flyes_-_With_Bands/1.jpg']::text[], 'back flyes - with bands bay vai sau day khang luc aperturas posteriores con banda'),
  (NULL, 'Backward Drag', 'Kéo xe lùi', 'Backward Drag', 'Arrastre hacia atrás', 'legs', 'other', 'compound', 'free_exercise_db', 'Backward_Drag', ARRAY['Load a sled with the desired weight, attaching a rope or straps to the sled that you can hold onto.', 'Begin the exercise by moving backwards for a given distance. Leaning back, extend through the legs for short steps to move as quickly as possible.']::text[], ARRAY['Backward_Drag/0.jpg', 'Backward_Drag/1.jpg']::text[], 'backward drag keo xe lui arrastre hacia atras'),
  (NULL, 'Backward Medicine Ball Throw', 'Ném bóng tạ ra sau', 'Backward Medicine Ball Throw', 'Lanzamiento de balón medicinal hacia atrás', 'shoulders', 'medicine ball', 'compound', 'free_exercise_db', 'Backward_Medicine_Ball_Throw', ARRAY['This exercise is best done with a partner. If you lack a partner, the ball can be thrown and retrieved or thrown against a wall.', 'Begin standing a few meters in front of your partner, both facing the same direction. Begin holding the ball between your legs.', 'Squat down and then forcefully reverse direction, coming to full extension and you toss the ball over your head to your partner.', 'Your partner can then roll the ball back to you. Repeat for the desired number of repetitions.']::text[], ARRAY['Backward_Medicine_Ball_Throw/0.jpg', 'Backward_Medicine_Ball_Throw/1.jpg']::text[], 'backward medicine ball throw nem bong ta ra sau lanzamiento de balon medicinal hacia atras'),
  (NULL, 'Balance Board', 'Thăng bằng trên ván', 'Balance Board', 'Tabla de equilibrio', 'calves', 'other', 'compound', 'free_exercise_db', 'Balance_Board', ARRAY['Place a balance board in front of you.', 'Stand up on it and try to balance yourself.', 'Hold the balance for as long as desired.']::text[], ARRAY['Balance_Board/0.jpg', 'Balance_Board/1.jpg']::text[], 'balance board thang bang tren van tabla de equilibrio'),
  (NULL, 'Ball Leg Curl', 'Ball Leg Curl', 'Ball Leg Curl', 'Curl femoral con fitball', 'legs', 'exercise ball', 'isolation', 'free_exercise_db', 'Ball_Leg_Curl', ARRAY['Begin on the floor laying on your back with your feet on top of the ball.', 'Position the ball so that when your legs are extended your ankles are on top of the ball. This will be your starting position.', 'Raise your hips off of the ground, keeping your weight on the shoulder blades and your feet.', 'Flex the knees, pulling the ball as close to you as you can, contracting the hamstrings.', 'After a brief pause, return to the starting position.']::text[], ARRAY['Ball_Leg_Curl/0.jpg', 'Ball_Leg_Curl/1.jpg']::text[], 'ball leg curl cuon dui sau voi bong tap curl femoral con fitball'),
  (NULL, 'Band Assisted Pull-Up', 'Hít xà có dây hỗ trợ', 'Band Assisted Pull-Up', 'Dominadas asistidas con banda', 'back', 'other', 'compound', 'free_exercise_db', 'Band_Assisted_Pull-Up', ARRAY['Choke the band around the center of the pullup bar. You can use different bands to provide varying levels of assistance.', 'Pull the end of the band down, and place one bent knee into the loop, ensuring it won''t slip out. Take a medium to wide grip on the bar. This will be your starting position.', 'Pull yourself upward by contracting the lats as you flex the elbow. The elbow should be driven to your side. Pull to the front, attempting to get your chin over the bar. Avoid swinging or jerking movements.', 'After a brief pause, return to the starting position.']::text[], ARRAY['Band_Assisted_Pull-Up/0.jpg', 'Band_Assisted_Pull-Up/1.jpg']::text[], 'band assisted pull-up hit xa co day ho tro dominadas asistidas con banda'),
  (NULL, 'Band Good Morning', 'Band Good Morning', 'Band Good Morning', 'Buenos días con banda', 'legs', 'band', 'compound', 'free_exercise_db', 'Band_Good_Morning', ARRAY['Using a 41 inch band, stand on one end, spreading your feet a small amount. Bend at the hips to loop the end of the band behind your neck. This will be your starting position.', 'Keeping your legs straight, extend through the hips to come to a near vertical position.', 'Ensure that you do not round your back as you go down back to the starting position.']::text[], ARRAY['Band_Good_Morning/0.jpg', 'Band_Good_Morning/1.jpg']::text[], 'band good morning good morning day khang luc buenos dias con banda'),
  (NULL, 'Band Good Morning (Pull Through)', 'Band Good Morning (Pull Through)', 'Band Good Morning (Pull Through)', 'Buenos días con banda (pull through)', 'legs', 'band', 'compound', 'free_exercise_db', 'Band_Good_Morning_Pull_Through', ARRAY['Loop the band around a post. Standing a little ways away, loop the opposite end around the neck. Your hands can help hold the band in position.', 'Begin by bending at the hips, getting your butt back as far as possible. Keep your back flat and bend forward to about 90 degrees. Your knees should be only slightly bent.', 'Return to the starting position be driving through with the hips to come back to a standing position.']::text[], ARRAY['Band_Good_Morning_Pull_Through/0.jpg', 'Band_Good_Morning_Pull_Through/1.jpg']::text[], 'band good morning (pull through) good morning keo day qua chan buenos dias con banda (pull through)'),
  (NULL, 'Band Hip Adductions', 'Khép đùi dây kháng lực', 'Band Hip Adductions', 'Aducción de cadera con banda', 'legs', 'band', 'isolation', 'free_exercise_db', 'Band_Hip_Adductions', ARRAY['Anchor a band around a solid post or other object.', 'Stand with your left side to the post, and put your right foot through the band, getting it around the ankle.', 'Stand up straight and hold onto the post if needed. This will be your starting position.', 'Keeping the knee straight, raise your right legs out to the side as far as you can.', 'Return to the starting position and repeat for the desired rep count.', 'Switch sides.']::text[], ARRAY['Band_Hip_Adductions/0.jpg', 'Band_Hip_Adductions/1.jpg']::text[], 'band hip adductions khep dui day khang luc aduccion de cadera con banda'),
  (NULL, 'Band Pull Apart', 'Kéo giãn dây kháng lực', 'Band Pull Apart', 'Separación de banda', 'shoulders', 'band', 'isolation', 'free_exercise_db', 'Band_Pull_Apart', ARRAY['Begin with your arms extended straight out in front of you, holding the band with both hands.', 'Initiate the movement by performing a reverse fly motion, moving your hands out laterally to your sides.', 'Keep your elbows extended as you perform the movement, bringing the band to your chest. Ensure that you keep your shoulders back during the exercise.', 'Pause as you complete the movement, returning to the starting position under control.']::text[], ARRAY['Band_Pull_Apart/0.jpg', 'Band_Pull_Apart/1.jpg']::text[], 'band pull apart keo gian day khang luc separacion de banda'),
  (NULL, 'Band Skull Crusher', 'Band Skull Crusher', 'Band Skull Crusher', 'Rompecráneos con banda', 'triceps', 'band', 'isolation', 'free_exercise_db', 'Band_Skull_Crusher', ARRAY['Secure a band to the base of a rack or the bench. Lay on the bench so that the band is lined up with your head.', 'Take hold of the band, raising your elbows so that the upper arm is perpendicular to the floor. With the elbow flexed, the band should be above your head. This will be your starting position.', 'Extend through the elbow to straighten your arm, keeping your upper arm in place. Pause at the top of the motion, and return to the starting position.']::text[], ARRAY['Band_Skull_Crusher/0.jpg', 'Band_Skull_Crusher/1.jpg']::text[], 'band skull crusher skull crusher day khang luc rompecraneos con banda'),
  (NULL, 'Barbell Ab Rollout', 'Lăn bụng tạ đòn', 'Barbell Ab Rollout', 'Rueda abdominal con barra', 'abs', 'barbell', 'compound', 'free_exercise_db', 'Barbell_Ab_Rollout', ARRAY['For this exercise you will need to get into a pushup position, but instead of having your hands of the floor, you will be grabbing on to an Olympic barbell (loaded with 5-10 lbs on each side) instead. This will be your starting position.', 'While keeping a slight arch on your back, lift your hips and roll the barbell towards your feet as you exhale. Tip: As you perform the movement, your glutes should be coming up, you should be keeping the abs tight and should maintain your back posture at all times. Also your arms should be staying perpendicular to the floor throughout the movement. If you don''t, you will work out your shoulders and back more than the abs.', 'After a second contraction at the top, start to roll the barbell back forward to the starting position slowly as you inhale.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Barbell_Ab_Rollout/0.jpg', 'Barbell_Ab_Rollout/1.jpg']::text[], 'barbell ab rollout lan bung ta don rueda abdominal con barra'),
  (NULL, 'Barbell Ab Rollout - On Knees', 'Lăn bụng tạ đòn chống gối', 'Barbell Ab Rollout - On Knees', 'Rueda abdominal con barra de rodillas', 'abs', 'barbell', 'compound', 'free_exercise_db', 'Barbell_Ab_Rollout_-_On_Knees', ARRAY['Hold an Olympic barbell loaded with 5-10lbs on each side and kneel on the floor.', 'Now place the barbell on the floor in front of you so that you are on all your hands and knees (as in a kneeling push up position). This will be your starting position.', 'Slowly roll the barbell straight forward, stretching your body into a straight position. Tip: Go down as far as you can without touching the floor with your body. Breathe in during this portion of the movement.', 'After a second pause at the stretched position, start pulling yourself back to the starting position as you breathe out. Tip: Go slowly and keep your abs tight at all times.']::text[], ARRAY['Barbell_Ab_Rollout_-_On_Knees/0.jpg', 'Barbell_Ab_Rollout_-_On_Knees/1.jpg']::text[], 'barbell ab rollout - on knees lan bung ta don chong goi rueda abdominal con barra de rodillas'),
  (NULL, 'Barbell Bench Press - Medium Grip', 'Barbell Bench Press - Medium Grip', 'Barbell Bench Press - Medium Grip', 'Press de banca con barra agarre medio', 'chest', 'barbell', 'compound', 'free_exercise_db', 'Barbell_Bench_Press_-_Medium_Grip', ARRAY['Lie back on a flat bench. Using a medium width grip (a grip that creates a 90-degree angle in the middle of the movement between the forearms and the upper arms), lift the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.', 'From the starting position, breathe in and begin coming down slowly until the bar touches your middle chest.', 'After a brief pause, push the bar back to the starting position as you breathe out. Focus on pushing the bar using your chest muscles. Lock your arms and squeeze your chest in the contracted position at the top of the motion, hold for a second and then start coming down slowly again. Tip: Ideally, lowering the weight should take about twice as long as raising it.', 'Repeat the movement for the prescribed amount of repetitions.', 'When you are done, place the bar back in the rack.']::text[], ARRAY['Barbell_Bench_Press_-_Medium_Grip/0.jpg', 'Barbell_Bench_Press_-_Medium_Grip/1.jpg']::text[], 'barbell bench press - medium grip day nguc ta don nam vua press de banca con barra agarre medio'),
  (NULL, 'Barbell Curl', 'Barbell Curl', 'Barbell Curl', 'Curl con barra', 'biceps', 'barbell', 'isolation', 'free_exercise_db', 'Barbell_Curl', ARRAY['Stand up with your torso upright while holding a barbell at a shoulder-width grip. The palm of your hands should be facing forward and the elbows should be close to the torso. This will be your starting position.', 'While holding the upper arms stationary, curl the weights forward while contracting the biceps as you breathe out. Tip: Only the forearms should move.', 'Continue the movement until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a second and squeeze the biceps hard.', 'Slowly begin to bring the bar back to starting position as your breathe in.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Barbell_Curl/0.jpg', 'Barbell_Curl/1.jpg']::text[], 'barbell curl cuon ta don curl con barra'),
  (NULL, 'Barbell Curls Lying Against An Incline', 'Barbell Curls Lying Against An Incline', 'Barbell Curls Lying Against An Incline', 'Curl con barra tumbado en banco inclinado', 'biceps', 'barbell', 'isolation', 'free_exercise_db', 'Barbell_Curls_Lying_Against_An_Incline', ARRAY['Lie against an incline bench, with your arms holding a barbell and hanging down in a horizontal line. This will be your starting position.', 'While keeping the upper arms stationary, curl the weight up as high as you can while squeezing the biceps. Breathe out as you perform this portion of the movement. Tip: Only the forearms should move. Do not swing the arms.', 'After a second contraction, slowly go back to the starting position as you inhale. Tip: Make sure that you go all of the way down.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Barbell_Curls_Lying_Against_An_Incline/0.jpg', 'Barbell_Curls_Lying_Against_An_Incline/1.jpg']::text[], 'barbell curls lying against an incline cuon ta don nam ghe doc curl con barra tumbado en banco inclinado'),
  (NULL, 'Barbell Deadlift', 'Barbell Deadlift', 'Barbell Deadlift', 'Peso muerto con barra', 'back', 'barbell', 'compound', 'free_exercise_db', 'Barbell_Deadlift', ARRAY['Stand in front of a loaded barbell.', 'While keeping the back as straight as possible, bend your knees, bend forward and grasp the bar using a medium (shoulder width) overhand grip. This will be the starting position of the exercise. Tip: If it is difficult to hold on to the bar with this grip, alternate your grip or use wrist straps.', 'While holding the bar, start the lift by pushing with your legs while simultaneously getting your torso to the upright position as you breathe out. In the upright position, stick your chest out and contract the back by bringing the shoulder blades back. Think of how the soldiers in the military look when they are in standing in attention.', 'Go back to the starting position by bending at the knees while simultaneously leaning the torso forward at the waist while keeping the back straight. When the weights on the bar touch the floor you are back at the starting position and ready to perform another repetition.', 'Perform the amount of repetitions prescribed in the program.']::text[], ARRAY['Barbell_Deadlift/0.jpg', 'Barbell_Deadlift/1.jpg']::text[], 'barbell deadlift deadlift ta don peso muerto con barra'),
  (NULL, 'Barbell Full Squat', 'Barbell Full Squat', 'Barbell Full Squat', 'Sentadilla profunda con barra', 'legs', 'barbell', 'compound', 'free_exercise_db', 'Barbell_Full_Squat', ARRAY['This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack just above shoulder level. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.', 'Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.', 'Step away from the rack and position your legs using a shoulder-width medium stance with the toes slightly pointed out. Keep your head up at all times and maintain a straight back. This will be your starting position.', 'Begin to slowly lower the bar by bending the knees and sitting back with your hips as you maintain a straight posture with the head up. Continue down until your hamstrings are on your calves. Inhale as you perform this portion of the movement.', 'Begin to raise the bar as you exhale by pushing the floor with the heel or middle of your foot as you straighten the legs and extend the hips to go back to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Barbell_Full_Squat/0.jpg', 'Barbell_Full_Squat/1.jpg']::text[], 'barbell full squat squat sau ta don sentadilla profunda con barra'),
  (NULL, 'Barbell Glute Bridge', 'Barbell Glute Bridge', 'Barbell Glute Bridge', 'Puente de glúteos con barra', 'glutes', 'barbell', 'compound', 'free_exercise_db', 'Barbell_Glute_Bridge', ARRAY['Begin seated on the ground with a loaded barbell over your legs. Using a fat bar or having a pad on the bar can greatly reduce the discomfort caused by this exercise. Roll the bar so that it is directly above your hips, and lay down flat on the floor.', 'Begin the movement by driving through with your heels, extending your hips vertically through the bar. Your weight should be supported by your upper back and the heels of your feet.', 'Extend as far as possible, then reverse the motion to return to the starting position.']::text[], ARRAY['Barbell_Glute_Bridge/0.jpg', 'Barbell_Glute_Bridge/1.jpg']::text[], 'barbell glute bridge cau mong ta don puente de gluteos con barra'),
  (NULL, 'Barbell Guillotine Bench Press', 'Barbell Guillotine Bench Press', 'Barbell Guillotine Bench Press', 'Press de banca guillotina', 'chest', 'barbell', 'compound', 'free_exercise_db', 'Barbell_Guillotine_Bench_Press', ARRAY['Using a medium width grip (a grip that creates a 90-degree angle in the middle of the movement between the forearms and the upper arms), lift the bar from the rack and hold it straight over your neck with your arms locked. This will be your starting position.', 'As you breathe in, bring the bar down slowly until it is about 1 inch from your neck.', 'After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles. Lock your arms and squeeze your chest in the contracted position, hold for a second and then start coming down slowly again. It should take at least twice as long to go down than to come up.', 'Repeat the movement for the prescribed amount of repetitions.', 'When you are done, place the bar back in the rack.']::text[], ARRAY['Barbell_Guillotine_Bench_Press/0.jpg', 'Barbell_Guillotine_Bench_Press/1.jpg']::text[], 'barbell guillotine bench press day nguc ta don kieu may chem press de banca guillotina'),
  (NULL, 'Barbell Hack Squat', 'Barbell Hack Squat', 'Barbell Hack Squat', 'Sentadilla hack con barra', 'legs', 'barbell', 'compound', 'free_exercise_db', 'Barbell_Hack_Squat', ARRAY['Stand up straight while holding a barbell behind you at arms length and your feet at shoulder width. Tip: A shoulder width grip is best with the palms of your hands facing back. You can use wrist wraps for this exercise for a better grip. This will be your starting position.', 'While keeping your head and eyes up and back straight, squat until your upper thighs are parallel to the floor. Breathe in as you slowly go down.', 'Pressing mainly with the heel of the foot and squeezing the thighs, go back up as you breathe out.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Barbell_Hack_Squat/0.jpg', 'Barbell_Hack_Squat/1.jpg']::text[], 'barbell hack squat hack squat ta don sentadilla hack con barra'),
  (NULL, 'Barbell Hip Thrust', 'Barbell Hip Thrust', 'Barbell Hip Thrust', 'Empuje de cadera con barra', 'glutes', 'barbell', 'compound', 'free_exercise_db', 'Barbell_Hip_Thrust', ARRAY['Begin seated on the ground with a bench directly behind you. Have a loaded barbell over your legs. Using a fat bar or having a pad on the bar can greatly reduce the discomfort caused by this exercise.', 'Roll the bar so that it is directly above your hips, and lean back against the bench so that your shoulder blades are near the top of it.', 'Begin the movement by driving through your feet, extending your hips vertically through the bar. Your weight should be supported by your shoulder blades and your feet. Extend as far as possible, then reverse the motion to return to the starting position.']::text[], ARRAY['Barbell_Hip_Thrust/0.jpg', 'Barbell_Hip_Thrust/1.jpg']::text[], 'barbell hip thrust day hong ta don empuje de cadera con barra'),
  (NULL, 'Barbell Incline Bench Press - Medium Grip', 'Barbell Incline Bench Press - Medium Grip', 'Barbell Incline Bench Press - Medium Grip', 'Press inclinado con barra agarre medio', 'chest', 'barbell', 'compound', 'free_exercise_db', 'Barbell_Incline_Bench_Press_-_Medium_Grip', ARRAY['Lie back on an incline bench. Using a medium-width grip (a grip that creates a 90-degree angle in the middle of the movement between the forearms and the upper arms), lift the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.', 'As you breathe in, come down slowly until you feel the bar on you upper chest.', 'After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles. Lock your arms in the contracted position, squeeze your chest, hold for a second and then start coming down slowly again. Tip: it should take at least twice as long to go down than to come up.', 'Repeat the movement for the prescribed amount of repetitions.', 'When you are done, place the bar back in the rack.']::text[], ARRAY['Barbell_Incline_Bench_Press_-_Medium_Grip/0.jpg', 'Barbell_Incline_Bench_Press_-_Medium_Grip/1.jpg']::text[], 'barbell incline bench press - medium grip day nguc doc len ta don nam vua press inclinado con barra agarre medio'),
  (NULL, 'Barbell Incline Shoulder Raise', 'Nâng vai ghế dốc tạ đòn', 'Barbell Incline Shoulder Raise', 'Elevación de hombros inclinado con barra', 'shoulders', 'barbell', 'compound', 'free_exercise_db', 'Barbell_Incline_Shoulder_Raise', ARRAY['Lie back on an Incline Bench. Using a medium width grip (a grip that is slightly wider than shoulder width), lift the bar from the rack and hold it straight over you with your arms straight. This will be your starting position.', 'While keeping the arms straight, lift the bar by protracting your shoulder blades, raising the shoulders from the bench as you breathe out.', 'Bring back the bar to the starting position as you breathe in.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Barbell_Incline_Shoulder_Raise/0.jpg', 'Barbell_Incline_Shoulder_Raise/1.jpg']::text[], 'barbell incline shoulder raise nang vai ghe doc ta don elevacion de hombros inclinado con barra'),
  (NULL, 'Barbell Lunge', 'Barbell Lunge', 'Barbell Lunge', 'Zancada con barra', 'legs', 'barbell', 'compound', 'free_exercise_db', 'Barbell_Lunge', ARRAY['This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack just below shoulder level. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.', 'Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.', 'Step away from the rack and step forward with your right leg and squat down through your hips, while keeping the torso upright and maintaining balance. Inhale as you go down. Note: Do not allow your knee to go forward beyond your toes as you come down, as this will put undue stress on the knee joint. li>', 'Using mainly the heel of your foot, push up and go back to the starting position as you exhale.', 'Repeat the movement for the recommended amount of repetitions and then perform with the left leg.']::text[], ARRAY['Barbell_Lunge/0.jpg', 'Barbell_Lunge/1.jpg']::text[], 'barbell lunge chung chan ta don zancada con barra'),
  (NULL, 'Barbell Rear Delt Row', 'Chèo vai sau tạ đòn', 'Barbell Rear Delt Row', 'Remo para deltoides posterior con barra', 'shoulders', 'barbell', 'compound', 'free_exercise_db', 'Barbell_Rear_Delt_Row', ARRAY['Stand up straight while holding a barbell using a wide (higher than shoulder width) and overhand (palms facing your body) grip.', 'Bend knees slightly and bend over as you keep the natural arch of your back. Let the arms hang in front of you as they hold the bar. Once your torso is parallel to the floor, flare the elbows out and away from your body. Tip: Your torso and your arms should resemble the letter "T". Now you are ready to begin the exercise.', 'While keeping the upper arms perpendicular to the torso, pull the barbell up towards your upper chest as you squeeze the rear delts and you breathe out. Tip: When performed correctly, this exercise should resemble a bench press in reverse. Also, refrain from using your biceps to do the work. Focus on targeting the rear delts; the arms should only act as hooks.', 'Slowly go back to the initial position as you breathe in.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Barbell_Rear_Delt_Row/0.jpg', 'Barbell_Rear_Delt_Row/1.jpg']::text[], 'barbell rear delt row cheo vai sau ta don remo para deltoides posterior con barra'),
  (NULL, 'Barbell Rollout from Bench', 'Lăn bụng tạ đòn từ ghế', 'Barbell Rollout from Bench', 'Rueda abdominal con barra desde banco', 'abs', 'barbell', 'compound', 'free_exercise_db', 'Barbell_Rollout_from_Bench', ARRAY['Place a loaded barbell on the ground, near the end of a bench. Kneel with both legs on the bench, and take a medium to narrow grip on the barbell. This will be your starting position.', 'To begin, extend through the hips to slowly roll the bar forward. As you roll out, flex the shoulder to roll the bar above your head. Ensure that your arms remain extended throughout the movement.', 'When the bar has been moved as far forward as possible, return to the starting position.']::text[], ARRAY['Barbell_Rollout_from_Bench/0.jpg', 'Barbell_Rollout_from_Bench/1.jpg']::text[], 'barbell rollout from bench lan bung ta don tu ghe rueda abdominal con barra desde banco'),
  (NULL, 'Barbell Seated Calf Raise', 'Nhón bắp chân ngồi tạ đòn', 'Barbell Seated Calf Raise', 'Elevación de gemelos sentado con barra', 'calves', 'barbell', 'isolation', 'free_exercise_db', 'Barbell_Seated_Calf_Raise', ARRAY['Place a block about 12 inches in front of a flat bench.', 'Sit on the bench and place the ball of your feet on the block.', 'Have someone place a barbell over your upper thighs about 3 inches above your knees and hold it there. This will be your starting position.', 'Raise up on your toes as high as possible as you squeeze the calves and as you breathe out.', 'After a second contraction, slowly go back to the starting position. Tip: To get maximum benefit stretch your calves as far as you can.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Barbell_Seated_Calf_Raise/0.jpg', 'Barbell_Seated_Calf_Raise/1.jpg']::text[], 'barbell seated calf raise nhon bap chan ngoi ta don elevacion de gemelos sentado con barra'),
  (NULL, 'Barbell Shoulder Press', 'Đẩy vai tạ đòn', 'Barbell Shoulder Press', 'Press de hombros con barra', 'shoulders', 'barbell', 'compound', 'free_exercise_db', 'Barbell_Shoulder_Press', ARRAY['Sit on a bench with back support in a squat rack. Position a barbell at a height that is just above your head. Grab the barbell with a pronated grip (palms facing forward).', 'Once you pick up the barbell with the correct grip width, lift the bar up over your head by locking your arms. Hold at about shoulder level and slightly in front of your head. This is your starting position.', 'Lower the bar down to the shoulders slowly as you inhale.', 'Lift the bar back up to the starting position as you exhale.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Barbell_Shoulder_Press/0.jpg', 'Barbell_Shoulder_Press/1.jpg']::text[], 'barbell shoulder press day vai ta don press de hombros con barra'),
  (NULL, 'Barbell Shrug', 'Barbell Shrug', 'Barbell Shrug', 'Encogimiento de hombros con barra', 'shoulders', 'barbell', 'isolation', 'free_exercise_db', 'Barbell_Shrug', ARRAY['Stand up straight with your feet at shoulder width as you hold a barbell with both hands in front of you using a pronated grip (palms facing the thighs). Tip: Your hands should be a little wider than shoulder width apart. You can use wrist wraps for this exercise for a better grip. This will be your starting position.', 'Raise your shoulders up as far as you can go as you breathe out and hold the contraction for a second. Tip: Refrain from trying to lift the barbell by using your biceps.', 'Slowly return to the starting position as you breathe in.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Barbell_Shrug/0.jpg', 'Barbell_Shrug/1.jpg']::text[], 'barbell shrug nhun vai ta don encogimiento de hombros con barra'),
  (NULL, 'Barbell Shrug Behind The Back', 'Barbell Shrug Behind The Back', 'Barbell Shrug Behind The Back', 'Encogimiento con barra por detrás', 'shoulders', 'barbell', 'isolation', 'free_exercise_db', 'Barbell_Shrug_Behind_The_Back', ARRAY['Stand up straight with your feet at shoulder width as you hold a barbell with both hands behind your back using a pronated grip (palms facing back). Tip: Your hands should be a little wider than shoulder width apart. You can use wrist wraps for this exercise for better grip. This will be your starting position.', 'Raise your shoulders up as far as you can go as you breathe out and hold the contraction for a second. Tip: Refrain from trying to lift the barbell by using your biceps. The arms should remain stretched out at all times.', 'Slowly return to the starting position as you breathe in.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Barbell_Shrug_Behind_The_Back/0.jpg', 'Barbell_Shrug_Behind_The_Back/1.jpg']::text[], 'barbell shrug behind the back nhun vai ta don sau lung encogimiento con barra por detras'),
  (NULL, 'Barbell Side Bend', 'Nghiêng lườn tạ đòn', 'Barbell Side Bend', 'Flexión lateral con barra', 'abs', 'barbell', 'isolation', 'free_exercise_db', 'Barbell_Side_Bend', ARRAY['Stand up straight while holding a barbell placed on the back of your shoulders (slightly below the neck). Your feet should be shoulder width apart. This will be your starting position.', 'While keeping your back straight and your head up, bend only at the waist to the right as far as possible. Breathe in as you bend to the side. Then hold for a second and come back up to the starting position as you exhale. Tip: Keep the rest of the body stationary.', 'Now repeat the movement but bending to the left instead. Hold for a second and come back to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Barbell_Side_Bend/0.jpg', 'Barbell_Side_Bend/1.jpg']::text[], 'barbell side bend nghieng luon ta don flexion lateral con barra'),
  (NULL, 'Barbell Side Split Squat', 'Barbell Side Split Squat', 'Barbell Side Split Squat', 'Sentadilla lateral con barra', 'legs', 'barbell', 'compound', 'free_exercise_db', 'Barbell_Side_Split_Squat', ARRAY['Stand up straight while holding a barbell placed on the back of your shoulders (slightly below the neck). Your feet should be placed wide apart with the foot of the lead leg angled out to the side. This will be your starting position.', 'Lower your body towards the side of your angled foot by bending the knee and hip of your lead leg and while keeping the opposite leg only slightly bent. Breathe in as you lower your body.', 'Return to the starting position by extending the hip and knee of the lead leg. Breathe out as you perform this movement.', 'After performing the recommended amount of reps, repeat the movement with the opposite leg.']::text[], ARRAY['Barbell_Side_Split_Squat/0.jpg', 'Barbell_Side_Split_Squat/1.jpg']::text[], 'barbell side split squat squat tach chan ngang ta don sentadilla lateral con barra'),
  (NULL, 'Barbell Squat To A Bench', 'Barbell Squat To A Bench', 'Barbell Squat To A Bench', 'Sentadilla con barra al banco', 'legs', 'barbell', 'compound', 'free_exercise_db', 'Barbell_Squat_To_A_Bench', ARRAY['This exercise is best performed inside a squat rack for safety purposes. To begin, first place a flat bench or a box behind you. The flat bench is used to teach you to set your hips back and to hit depth.', '', 'Then, set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.', 'Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.', 'Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance and also maintain a straight back. This will be your starting position. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances discussed in the foot stances section).', 'Begin to slowly lower the bar by bending the knees and sitting your hips back as you maintain a straight posture with the head up. Continue down until you slightly touch the bench behind you. Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.', 'Begin to raise the bar as you exhale by pushing the floor with the heel of your foot as you straighten the legs and extend the hips to go back to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Barbell_Squat_To_A_Bench/0.jpg', 'Barbell_Squat_To_A_Bench/1.jpg']::text[], 'barbell squat to a bench squat ta don xuong ghe sentadilla con barra al banco'),
  (NULL, 'Barbell Step Ups', 'Bước bục tạ đòn', 'Barbell Step Ups', 'Subida al cajón con barra', 'legs', 'barbell', 'compound', 'free_exercise_db', 'Barbell_Step_Ups', ARRAY['Stand up straight while holding a barbell placed on the back of your shoulders (slightly below the neck) and stand upright behind an elevated platform (such as the one used for spotting behind a flat bench). This is your starting position.', 'Place the right foot on the elevated platform. Step on the platform by extending the hip and the knee of your right leg. Use the heel mainly to lift the rest of your body up and place the foot of the left leg on the platform as well. Breathe out as you execute the force required to come up.', 'Step down with the left leg by flexing the hip and knee of the right leg as you inhale. Return to the original standing position by placing the right foot of to next to the left foot on the initial position.', 'Repeat with the right leg for the recommended amount of repetitions and then perform with the left leg.']::text[], ARRAY['Barbell_Step_Ups/0.jpg', 'Barbell_Step_Ups/1.jpg']::text[], 'barbell step ups buoc buc ta don subida al cajon con barra'),
  (NULL, 'Barbell Walking Lunge', 'Barbell Walking Lunge', 'Barbell Walking Lunge', 'Zancadas caminando con barra', 'legs', 'barbell', 'compound', 'free_exercise_db', 'Barbell_Walking_Lunge', ARRAY['Begin standing with your feet shoulder width apart and a barbell across your upper back.', 'Step forward with one leg, flexing the knees to drop your hips. Descend until your rear knee nearly touches the ground. Your posture should remain upright, and your front knee should stay above the front foot.', 'Drive through the heel of your lead foot and extend both knees to raise yourself back up.', 'Step forward with your rear foot, repeating the lunge on the opposite leg.']::text[], ARRAY['Barbell_Walking_Lunge/0.jpg', 'Barbell_Walking_Lunge/1.jpg']::text[], 'barbell walking lunge chung chan buoc di ta don zancadas caminando con barra'),
  (NULL, 'Battling Ropes', 'Quăng dây thừng', 'Battling Ropes', 'Cuerdas de batalla', 'shoulders', 'other', 'compound', 'free_exercise_db', 'Battling_Ropes', ARRAY['For this exercise you will need a heavy rope anchored at its center 15-20 feet away. Standing in front of the rope, take an end in each hand with your arms extended at your side. This will be your starting position.', 'Initiate the movement by rapidly raising one arm to shoulder level as quickly as you can.', 'As you let that arm drop to the starting position, raise the opposite side.', 'Continue alternating your left and right arms, whipping the ropes up and down as fast as you can.']::text[], ARRAY['Battling_Ropes/0.jpg', 'Battling_Ropes/1.jpg']::text[], 'battling ropes quang day thung cuerdas de batalla'),
  (NULL, 'Bear Crawl Sled Drags', 'Bò gấu kéo xe trượt', 'Bear Crawl Sled Drags', 'Arrastre de trineo gateando', 'legs', 'other', 'compound', 'free_exercise_db', 'Bear_Crawl_Sled_Drags', ARRAY['Wearing either a harness or a loose weight belt, attach the chain to the back so that you will be facing away from the sled. Bend down so that your hands are on the ground. Your back should be flat and knees bent. This is your starting position.', 'Begin by driving with legs, alternating left and right. Use your hands to maintain balance and to help pull. Try to keep your back flat as you move over a given distance.']::text[], ARRAY['Bear_Crawl_Sled_Drags/0.jpg', 'Bear_Crawl_Sled_Drags/1.jpg']::text[], 'bear crawl sled drags bo gau keo xe truot arrastre de trineo gateando'),
  (NULL, 'Behind Head Chest Stretch', 'Giãn ngực tay sau đầu', 'Behind Head Chest Stretch', 'Estiramiento de pecho detrás de la cabeza', 'chest', 'other', 'timed', 'free_exercise_db', 'Behind_Head_Chest_Stretch', ARRAY['Sit upright on the floor with your partner behind you.', 'Place your hands behind your hand, and push your elbows back as far as you can. Your partner should hold your elbows. This will be your starting position.', 'Gently attempt to pull your elbows forward with your hands still behind your head for 10 or more seconds. Your partner should prevent your elbows from moving.', 'Now, relax your muscles and have your partner gently pull the elbows back as far as it comfortable for you. Be sure to let your partner know when the stretch is adequate to prevent overstretching or injury.']::text[], ARRAY['Behind_Head_Chest_Stretch/0.jpg', 'Behind_Head_Chest_Stretch/1.jpg']::text[], 'behind head chest stretch gian nguc tay sau dau estiramiento de pecho detras de la cabeza'),
  (NULL, 'Bench Dips', 'Bench Dips', 'Bench Dips', 'Fondos en banco', 'triceps', 'bodyweight', 'bodyweight', 'free_exercise_db', 'Bench_Dips', ARRAY['For this exercise you will need to place a bench behind your back. With the bench perpendicular to your body, and while looking away from it, hold on to the bench on its edge with the hands fully extended, separated at shoulder width. The legs will be extended forward, bent at the waist and perpendicular to your torso. This will be your starting position.', 'Slowly lower your body as you inhale by bending at the elbows until you lower yourself far enough to where there is an angle slightly smaller than 90 degrees between the upper arm and the forearm. Tip: Keep the elbows as close as possible throughout the movement. Forearms should always be pointing down.', 'Using your triceps to bring your torso up again, lift yourself back to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Bench_Dips/0.jpg', 'Bench_Dips/1.jpg']::text[], 'bench dips dips tren ghe fondos en banco'),
  (NULL, 'Bench Jump', 'Bật nhảy qua ghế', 'Bench Jump', 'Salto al banco', 'legs', 'bodyweight', 'bodyweight', 'free_exercise_db', 'Bench_Jump', ARRAY['Begin with a box or bench 1-2 feet in front of you. Stand with your feet shoulder width apart. This will be your starting position.', 'Perform a short squat in preparation for the jump; swing your arms behind you.', 'Rebound out of this position, extending through the hips, knees, and ankles to jump as high as possible. Swing your arms forward and up.', 'Jump over the bench, landing with the knees bent, absorbing the impact through the legs.', 'Turn around and face the opposite direction, then jump back over the bench.']::text[], ARRAY['Bench_Jump/0.jpg', 'Bench_Jump/1.jpg']::text[], 'bench jump bat nhay qua ghe salto al banco'),
  (NULL, 'Bench Press - Powerlifting', 'Bench Press - Powerlifting', 'Bench Press - Powerlifting', 'Press de banca powerlifting', 'triceps', 'barbell', 'compound', 'free_exercise_db', 'Bench_Press_-_Powerlifting', ARRAY['Begin by lying on the bench, getting your head beyond the bar if possible. Tuck your feet underneath you and arch your back. Using the bar to help support your weight, lift your shoulder off the bench and retract them, squeezing the shoulder blades together. Use your feet to drive your traps into the bench. Maintain this tight body position throughout the movement.', 'However wide your grip, it should cover the ring on the bar. Pull the bar out of the rack without protracting your shoulders. Focus on squeezing the bar and trying to pull it apart.', 'Lower the bar to your lower chest or upper stomach. The bar, wrist, and elbow should stay in line at all times.', 'Pause when the barbell touches your torso, and then drive the bar up with as much force as possible. The elbows should be tucked in until lockout.']::text[], ARRAY['Bench_Press_-_Powerlifting/0.jpg', 'Bench_Press_-_Powerlifting/1.jpg']::text[], 'bench press - powerlifting day nguc kieu powerlifting press de banca powerlifting'),
  (NULL, 'Bench Press - With Bands', 'Bench Press - With Bands', 'Bench Press - With Bands', 'Press de banca con bandas', 'chest', 'band', 'compound', 'free_exercise_db', 'Bench_Press_-_With_Bands', ARRAY['Using a flat bench secure a band under the leg of the bench that is nearest to your head.', 'Once the band is secure, grab it by both handles and lie down on the bench.', 'Extend your arms so that you are holding the band handles in front of you at shoulder width.', 'Once at shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. This will be your starting position.', 'Bring down the handles slowly until your elbow forms a 90 degree angle. Keep full control at all times.', 'As you breathe out, bring the handles up using your pectoral muscles. Lock your arms in the contracted position, squeeze your chest, hold for a second and then start coming down slowly. Tip: It should take at least twice as long to go down than to come up.', 'Repeat the movement for the prescribed amount of repetitions of your training program.']::text[], ARRAY['Bench_Press_-_With_Bands/0.jpg', 'Bench_Press_-_With_Bands/1.jpg']::text[], 'bench press - with bands day nguc day khang luc press de banca con bandas'),
  (NULL, 'Bench Press with Chains', 'Bench Press with Chains', 'Bench Press with Chains', 'Press de banca con cadenas', 'triceps', 'barbell', 'compound', 'free_exercise_db', 'Bench_Press_with_Chains', ARRAY['Adjust the leader chain, shortening it to the desired length.Place the chains on the sleeves of the bar.', 'Lying on the bench, get your head beyond the bar if possible. Tuck your feet underneath you and arch your back. Using the bar to help support your weight, lift your shoulder off the bench and retract them, squeezing the shoulder blades together. Use your feet to drive your traps into the bench. Maintain this tight body position throughout the movement. However wide your grip, it should cover the ring on the bar.', 'Pull the bar out of the rack without protracting your shoulders. Focus on squeezing the bar and trying to pull it apart. Lower the bar to your lower chest or upper stomach. The bar, wrist, and elbow should stay in line at all times.', 'Pause when the barbell touches your torso, and then drive the bar up with as much force as possible. The elbows should be tucked in until lockout.']::text[], ARRAY['Bench_Press_with_Chains/0.jpg', 'Bench_Press_with_Chains/1.jpg']::text[], 'bench press with chains day nguc co xich press de banca con cadenas'),
  (NULL, 'Bench Sprint', 'Chạy nước rút lên ghế', 'Bench Sprint', 'Sprint al banco', 'legs', 'other', 'compound', 'free_exercise_db', 'Bench_Sprint', ARRAY['Stand on the ground with one foot resting on a bench or box with your heel close to the edge.', 'Push off with your foot on top of the bench, extending through the hip and knee.', 'Land with the opposite foot on top of the box, returning your other foot back to the start position.', 'Continue alternating from one foot to another to complete the set.']::text[], ARRAY['Bench_Sprint/0.jpg', 'Bench_Sprint/1.jpg']::text[], 'bench sprint chay nuoc rut len ghe sprint al banco'),
  (NULL, 'Bent-Arm Barbell Pullover', 'Bent-Arm Barbell Pullover', 'Bent-Arm Barbell Pullover', 'Pullover con barra brazos flexionados', 'back', 'barbell', 'compound', 'free_exercise_db', 'Bent-Arm_Barbell_Pullover', ARRAY['Lie on a flat bench with a barbell using a shoulder grip width.', 'Hold the bar straight over your chest with a bend in your arms. This will be your starting position.', 'While keeping your arms in the bent arm position, lower the weight slowly in an arc behind your head while breathing in until you feel a stretch on the chest.', 'At that point, bring the barbell back to the starting position using the arc through which the weight was lowered and exhale as you perform this movement.', 'Hold the weight on the initial position for a second and repeat the motion for the prescribed number of repetitions.']::text[], ARRAY['Bent-Arm_Barbell_Pullover/0.jpg', 'Bent-Arm_Barbell_Pullover/1.jpg']::text[], 'bent-arm barbell pullover keo ta don qua dau tay cong pullover con barra brazos flexionados'),
  (NULL, 'Bent-Arm Dumbbell Pullover', 'Bent-Arm Dumbbell Pullover', 'Bent-Arm Dumbbell Pullover', 'Pullover con mancuerna brazos flexionados', 'chest', 'dumbbell', 'compound', 'free_exercise_db', 'Bent-Arm_Dumbbell_Pullover', ARRAY['Place a dumbbell standing up on a flat bench.', 'Ensuring that the dumbbell stays securely placed at the top of the bench, lie perpendicular to the bench (torso across it as in forming a cross) with only your shoulders lying on the surface. Hips should be below the bench and legs bent with feet firmly on the floor. The head will be off the bench as well.', 'Grasp the dumbbell with both hands and hold it straight over your chest with a bend in your arms. Both palms should be pressing against the underside one of the sides of the dumbbell. This will be your starting position. Caution: Always ensure that the dumbbell used for this exercise is secure. Using a dumbbell with loose plates can result in the dumbbell falling apart and falling on your face.', 'While keeping your arms locked in the bent arm position, lower the weight slowly in an arc behind your head while breathing in until you feel a stretch on the chest.', 'At that point, bring the dumbbell back to the starting position using the arc through which the weight was lowered and exhale as you perform this movement.', 'Hold the weight on the initial position for a second and repeat the motion for the prescribed number of repetitions.']::text[], ARRAY['Bent-Arm_Dumbbell_Pullover/0.jpg', 'Bent-Arm_Dumbbell_Pullover/1.jpg']::text[], 'bent-arm dumbbell pullover keo ta don qua dau tay cong pullover con mancuerna brazos flexionados'),
  (NULL, 'Bent-Knee Hip Raise', 'Nâng hông gối cong', 'Bent-Knee Hip Raise', 'Elevación de cadera con rodillas flexionadas', 'abs', 'bodyweight', 'bodyweight', 'free_exercise_db', 'Bent-Knee_Hip_Raise', ARRAY['Lay flat on the floor with your arms next to your sides.', 'Now bend your knees at around a 75 degree angle and lift your feet off the floor by around 2 inches.', 'Using your lower abs, bring your knees in towards you as you maintain the 75 degree angle bend in your legs. Continue this movement until you raise your hips off of the floor by rolling your pelvis backward. Breathe out as you perform this portion of the movement. Tip: At the end of the movement your knees will be over your chest.', 'Squeeze your abs at the top of the movement for a second and then return to the starting position slowly as you breathe in. Tip: Maintain a controlled motion at all times.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Bent-Knee_Hip_Raise/0.jpg', 'Bent-Knee_Hip_Raise/1.jpg']::text[], 'bent-knee hip raise nang hong goi cong elevacion de cadera con rodillas flexionadas'),
  (NULL, 'Bent Over Barbell Row', 'Chèo cúi người tạ đòn', 'Bent Over Barbell Row', 'Remo inclinado con barra', 'back', 'barbell', 'compound', 'free_exercise_db', 'Bent_Over_Barbell_Row', ARRAY['Holding a barbell with a pronated grip (palms facing down), bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Tip: Make sure that you keep the head up. The barbell should hang directly in front of you as your arms hang perpendicular to the floor and your torso. This is your starting position.', 'Now, while keeping the torso stationary, breathe out and lift the barbell to you. Keep the elbows close to the body and only use the forearms to hold the weight. At the top contracted position, squeeze the back muscles and hold for a brief pause.', 'Then inhale and slowly lower the barbell back to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Bent_Over_Barbell_Row/0.jpg', 'Bent_Over_Barbell_Row/1.jpg']::text[], 'bent over barbell row cheo cui nguoi ta don remo inclinado con barra'),
  (NULL, 'Bent Over Dumbbell Rear Delt Raise With Head On Bench', 'Nâng vai sau tạ đơn tựa đầu ghế', 'Bent Over Dumbbell Rear Delt Raise With Head On Bench', 'Elevación posterior con mancuernas apoyando la cabeza', 'shoulders', 'dumbbell', 'isolation', 'free_exercise_db', 'Bent_Over_Dumbbell_Rear_Delt_Raise_With_Head_On_Bench', ARRAY['Stand up straight while holding a dumbbell in each hand and with an incline bench in front of you.', 'While keeping your back straight and maintaining the natural arch of your back, lean forward until your forehead touches the bench in front of you. Let the arms hang in front of you perpendicular to the ground. The palms of your hands should be facing each other and your torso should be parallel to the floor. This will be your starting position.', 'Keeping your torso forward and stationary, and the arms straight with a slight bend at the elbows, lift the dumbbells straight to the side until both arms are parallel to the floor. Exhale as you lift the weights. Caution: avoid swinging the torso or bringing the arms back as opposed to the side.', 'After a one second contraction at the top, slowly lower the dumbbells back to the starting position.', 'Repeat the recommended amount of repetitions.']::text[], ARRAY['Bent_Over_Dumbbell_Rear_Delt_Raise_With_Head_On_Bench/0.jpg', 'Bent_Over_Dumbbell_Rear_Delt_Raise_With_Head_On_Bench/1.jpg']::text[], 'bent over dumbbell rear delt raise with head on bench nang vai sau ta don tua dau ghe elevacion posterior con mancuernas apoyando la cabeza'),
  (NULL, 'Bent Over Low-Pulley Side Lateral', 'Nâng ngang cáp thấp cúi người', 'Bent Over Low-Pulley Side Lateral', 'Elevación lateral inclinado en polea baja', 'shoulders', 'cable', 'isolation', 'free_exercise_db', 'Bent_Over_Low-Pulley_Side_Lateral', ARRAY['Select a weight and hold the handle of the low pulley with your right hand.', 'Bend at the waist until your torso is nearly parallel to the floor. Your legs should be slightly bent with your left hand placed on your lower left thigh. Your right arm should be hanging from your shoulder in front of you and with a slight bend at the elbow. This will be your starting position.', 'Raise your right arm, elbow slightly bent, to the side until the arm is parallel to the floor and in line with your right ear. Breathe out as you perform this step.', 'Slowly lower the weight back to the starting position as you breathe in.', 'Repeat for the recommended amount of repetitions and repeat the movement with the other arm.']::text[], ARRAY['Bent_Over_Low-Pulley_Side_Lateral/0.jpg', 'Bent_Over_Low-Pulley_Side_Lateral/1.jpg']::text[], 'bent over low-pulley side lateral nang ngang cap thap cui nguoi elevacion lateral inclinado en polea baja'),
  (NULL, 'Bent Over One-Arm Long Bar Row', 'Chèo thanh dài một tay cúi người', 'Bent Over One-Arm Long Bar Row', 'Remo con barra larga a una mano', 'back', 'barbell', 'compound', 'free_exercise_db', 'Bent_Over_One-Arm_Long_Bar_Row', ARRAY['Put weight on one of the ends of an Olympic barbell. Make sure that you either place the other end of the barbell in the corner of two walls; or put a heavy object on the ground so the barbell cannot slide backward.', 'Bend forward until your torso is as close to parallel with the floor as you can and keep your knees slightly bent.', 'Now grab the bar with one arm just behind the plates on the side where the weight was placed and put your other hand on your knee. This will be your starting position.', 'Pull the bar straight up with your elbow in (to maximize back stimulation) until the plates touch your lower chest. Squeeze the back muscles as you lift the weight up and hold for a second at the top of the movement. Breathe out as you lift the weight. Tip: Do not allow for any swinging of the torso. Only the arm should move.', 'Slowly lower the bar to the starting position getting a nice stretch on the lats. Tip: Do not let the plates touch the floor. To ensure the best range of motion, I recommend using small plates (25-lb ones) as opposed to larger plates (like 35-45lb ones).', 'Repeat for the recommended amount of repetitions and switch arms.']::text[], ARRAY['Bent_Over_One-Arm_Long_Bar_Row/0.jpg', 'Bent_Over_One-Arm_Long_Bar_Row/1.jpg']::text[], 'bent over one-arm long bar row cheo thanh dai mot tay cui nguoi remo con barra larga a una mano'),
  (NULL, 'Bent Over Two-Arm Long Bar Row', 'Chèo thanh dài hai tay', 'Bent Over Two-Arm Long Bar Row', 'Remo con barra larga a dos manos', 'back', 'barbell', 'compound', 'free_exercise_db', 'Bent_Over_Two-Arm_Long_Bar_Row', ARRAY['Put weight on one of the ends of an Olympic barbell. Make sure that you either place the other end of the barbell in the corner of two walls; or put a heavy object on the ground so the barbell cannot slide backward.', 'Bend forward until your torso is as close to parallel with the floor as you can and keep your knees slightly bent.', 'Now grab the bar with both arms just behind the plates on the side where the weight was placed and put your other hand on your knee. This will be your starting position.', 'Pull the bar straight up with your elbows in (to maximize back stimulation) until the plates touch your lower chest. Squeeze the back muscles as you lift the weight up and hold for a second at the top of the movement. Breathe out as you lift the weight. Tip: Use a stirrup or double handle cable attachment by hooking it under the end of the bar.', 'Slowly lower the bar to the starting position getting a nice stretch on the lats. Tip: Do not let the plates touch the floor. To ensure the best range of motion, I recommend using small plates (25-lb ones) as opposed to larger plates (like 35-45lb ones).', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Bent_Over_Two-Arm_Long_Bar_Row/0.jpg', 'Bent_Over_Two-Arm_Long_Bar_Row/1.jpg']::text[], 'bent over two-arm long bar row cheo thanh dai hai tay remo con barra larga a dos manos'),
  (NULL, 'Bent Over Two-Dumbbell Row', 'Chèo cúi người hai tạ đơn', 'Bent Over Two-Dumbbell Row', 'Remo inclinado con dos mancuernas', 'back', 'dumbbell', 'compound', 'free_exercise_db', 'Bent_Over_Two-Dumbbell_Row', ARRAY['With a dumbbell in each hand (palms facing your torso), bend your knees slightly and bring your torso forward by bending at the waist; as you bend make sure to keep your back straight until it is almost parallel to the floor. Tip: Make sure that you keep the head up. The weights should hang directly in front of you as your arms hang perpendicular to the floor and your torso. This is your starting position.', 'While keeping the torso stationary, lift the dumbbells to your side (as you breathe out), keeping the elbows close to the body (do not exert any force with the forearm other than holding the weights). On the top contracted position, squeeze the back muscles and hold for a second.', 'Slowly lower the weight again to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Bent_Over_Two-Dumbbell_Row/0.jpg', 'Bent_Over_Two-Dumbbell_Row/1.jpg']::text[], 'bent over two-dumbbell row cheo cui nguoi hai ta don remo inclinado con dos mancuernas'),
  (NULL, 'Bent Over Two-Dumbbell Row With Palms In', 'Chèo cúi người tạ đơn lòng bàn tay hướng vào', 'Bent Over Two-Dumbbell Row With Palms In', 'Remo inclinado con mancuernas agarre neutro', 'back', 'dumbbell', 'compound', 'free_exercise_db', 'Bent_Over_Two-Dumbbell_Row_With_Palms_In', ARRAY['With a dumbbell in each hand (palms facing each other), bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Tip: Make sure that you keep the head up. The weights should hang directly in front of you as your arms hang perpendicular to the floor and your torso. This is your starting position.', 'While keeping the torso stationary, lift the dumbbells to your side as you breathe out, squeezing your shoulder blades together. On the top contracted position, squeeze the back muscles and hold for a second.', 'Slowly lower the weight again to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Bent_Over_Two-Dumbbell_Row_With_Palms_In/0.jpg', 'Bent_Over_Two-Dumbbell_Row_With_Palms_In/1.jpg']::text[], 'bent over two-dumbbell row with palms in cheo cui nguoi ta don long ban tay huong vao remo inclinado con mancuernas agarre neutro'),
  (NULL, 'Bent Press', 'Bent press kettlebell', 'Bent Press', 'Press doblado con pesa rusa', 'abs', 'kettlebell', 'compound', 'free_exercise_db', 'Bent_Press', ARRAY['Clean a kettlebell to your shoulder. Clean the kettlebell to your shoulders by extending through the legs and hips as you raise the kettlebell towards your shoulder. The wrist should rotate as you do so. This will be your starting position.', 'Begin my leaning to the side opposite the kettlebell, continuing until you are able to touch the ground with your free hand, keeping your eyes on the kettlebell. As you do so, press the weight vertically be extending through the elbow, keeping your arm perpendicular to the ground.', 'Return to an upright position, with the kettlebell above your head. Return the kettlebell to the shoulder and repeat for the desired number of repetitions.']::text[], ARRAY['Bent_Press/0.jpg', 'Bent_Press/1.jpg']::text[], 'bent press bent press kettlebell press doblado con pesa rusa'),
  (NULL, 'Bicycling', 'Đạp xe', 'Bicycling', 'Ciclismo', 'cardio', 'other', 'timed', 'free_exercise_db', 'Bicycling', ARRAY['To begin, seat yourself on the bike and adjust the seat to your height.']::text[], ARRAY['Bicycling/0.jpg', 'Bicycling/1.jpg']::text[], 'bicycling dap xe ciclismo'),
  (NULL, 'Bicycling, Stationary', 'Đạp xe tại chỗ', 'Bicycling, Stationary', 'Bicicleta estática', 'cardio', 'machine', 'timed', 'free_exercise_db', 'Bicycling_Stationary', ARRAY['To begin, seat yourself on the bike and adjust the seat to your height.', 'Select the desired option from the menu. You may have to start pedaling to turn it on. You can use the manual setting, or you can select a program to use. Typically, you can enter your age and weight to estimate the amount of calories burned during exercise. The level of resistance can be changed throughout the workout. The handles can be used to monitor your heart rate to help you stay at an appropriate intensity.']::text[], ARRAY['Bicycling_Stationary/0.jpg', 'Bicycling_Stationary/1.jpg']::text[], 'bicycling, stationary dap xe tai cho bicicleta estatica'),
  (NULL, 'Board Press', 'Đẩy ngực với ván', 'Board Press', 'Press con tabla', 'triceps', 'barbell', 'compound', 'free_exercise_db', 'Board_Press', ARRAY['Begin by lying on the bench, getting your head beyond the bar if possible. One to five boards, made out of 2x6''s, can be screwed together and held in place by a training partner, bands, or just tucked under your shirt.', 'Tuck your feet underneath you and arch your back. Using the bar to help support your weight, lift your shoulder off the bench and retract them, squeezing the shoulder blades together. Use your feet to drive your traps into the bench. Maintain this tight body position throughout the movement.', 'You can take a standard bench grip, or shoulder width to focus on the triceps. Pull the bar out of the rack without protracting your shoulders. The bar, wrist, and elbow should stay in line at all times. Focus on squeezing the bar and trying to pull it apart.', 'Lower the bar to the boards, and then drive the bar up with as much force as possible. The elbows should be tucked in until lockout.']::text[], ARRAY['Board_Press/0.jpg', 'Board_Press/1.jpg']::text[], 'board press day nguc voi van press con tabla'),
  (NULL, 'Body-Up', 'Body-up chống tay', 'Body-Up', 'Body-up', 'triceps', 'bodyweight', 'bodyweight', 'free_exercise_db', 'Body-Up', ARRAY['Assume a plank position on the ground. You should be supporting your bodyweight on your toes and forearms, keeping your torso straight. Your forearms should be shoulder-width apart. This will be your starting position.', 'Pressing your palms firmly into the ground, extend through the elbows to raise your body from the ground. Keep your torso rigid as you perform the movement.', 'Slowly lower your forearms back to the ground by allowing the elbows to flex.', 'Repeat.']::text[], ARRAY['Body-Up/0.jpg', 'Body-Up/1.jpg']::text[], 'body-up body-up chong tay body-up'),
  (NULL, 'Body Tricep Press', 'Đẩy tay sau bằng thân người', 'Body Tricep Press', 'Press de tríceps con peso corporal', 'triceps', 'bodyweight', 'bodyweight', 'free_exercise_db', 'Body_Tricep_Press', ARRAY['Position a bar in a rack at chest height.', 'Standing, take a shoulder width grip on the bar and step a yard or two back, feet together and arms extended so that you are leaning on the bar. This will be your starting position.', 'Begin by flexing the elbow, lowering yourself towards the bar.', 'Pause, and then reverse the motion by extending the elbows.', 'Progress from bodyweight by adding chains over your shoulders.']::text[], ARRAY['Body_Tricep_Press/0.jpg', 'Body_Tricep_Press/1.jpg']::text[], 'body tricep press day tay sau bang than nguoi press de triceps con peso corporal'),
  (NULL, 'Bodyweight Flyes', 'Bodyweight Flyes', 'Bodyweight Flyes', 'Aperturas con peso corporal', 'chest', 'ez bar', 'isolation', 'free_exercise_db', 'Bodyweight_Flyes', ARRAY['Position two equally loaded EZ bars on the ground next to each other. Ensure they are able to roll.', 'Assume a push-up position over the bars, supporting your weight on your toes and hands with your arms extended and body straight.', 'Place your hands on the bars. This will be your starting position.', 'Using a slow and controlled motion, move your hands away from the midline of your body, rolling the bars apart. Inhale during this portion of the motion.', 'After moving the bars as far apart as you can, return to the starting position by pulling them back together. Exhale as you perform this movement.']::text[], ARRAY['Bodyweight_Flyes/0.jpg', 'Bodyweight_Flyes/1.jpg']::text[], 'bodyweight flyes ep nguc bang trong luong co the aperturas con peso corporal'),
  (NULL, 'Bodyweight Mid Row', 'Chèo kéo người', 'Bodyweight Mid Row', 'Remo con peso corporal', 'back', 'other', 'compound', 'free_exercise_db', 'Bodyweight_Mid_Row', ARRAY['Begin by taking a medium to wide grip on a pull-up apparatus with your palms facing away from you. From a hanging position, tuck your knees to your chest, leaning back and getting your legs over your side of the pull-up apparatus. This will be your starting position.', 'Beginning with your arms straight, flex the elbows and retract the shoulder blades to raise your body up until your legs contact the pull-up apparatus.', 'After a brief pause, return to the starting position.']::text[], ARRAY['Bodyweight_Mid_Row/0.jpg', 'Bodyweight_Mid_Row/1.jpg']::text[], 'bodyweight mid row cheo keo nguoi remo con peso corporal'),
  (NULL, 'Bodyweight Squat', 'Bodyweight Squat', 'Bodyweight Squat', 'Sentadilla sin peso', 'legs', 'bodyweight', 'bodyweight', 'free_exercise_db', 'Bodyweight_Squat', ARRAY['Stand with your feet shoulder width apart. You can place your hands behind your head. This will be your starting position.', 'Begin the movement by flexing your knees and hips, sitting back with your hips.', 'Continue down to full depth if you are able,and quickly reverse the motion until you return to the starting position. As you squat, keep your head and chest up and push your knees out.']::text[], ARRAY['Bodyweight_Squat/0.jpg', 'Bodyweight_Squat/1.jpg']::text[], 'bodyweight squat squat khong ta sentadilla sin peso'),
  (NULL, 'Bodyweight Walking Lunge', 'Bodyweight Walking Lunge', 'Bodyweight Walking Lunge', 'Zancadas caminando sin peso', 'legs', 'other', 'bodyweight', 'free_exercise_db', 'Bodyweight_Walking_Lunge', ARRAY['Begin standing with your feet shoulder width apart and your hands on your hips.', 'Step forward with one leg, flexing the knees to drop your hips. Descend until your rear knee nearly touches the ground. Your posture should remain upright, and your front knee should stay above the front foot.', 'Drive through the heel of your lead foot and extend both knees to raise yourself back up.', 'Step forward with your rear foot, repeating the lunge on the opposite leg.']::text[], ARRAY['Bodyweight_Walking_Lunge/0.jpg', 'Bodyweight_Walking_Lunge/1.jpg']::text[], 'bodyweight walking lunge chung chan buoc di khong ta zancadas caminando sin peso'),
  (NULL, 'Bosu Ball Cable Crunch With Side Bends', 'Bosu Ball Cable Crunch With Side Bends', 'Bosu Ball Cable Crunch With Side Bends', 'Crunch en polea sobre Bosu con flexión lateral', 'abs', 'cable', 'isolation', 'free_exercise_db', 'Bosu_Ball_Cable_Crunch_With_Side_Bends', ARRAY['Connect a standard handle to each arm of a cable machine, and position them in the most downward position.', 'Grab a Bosu Ball and position it in front and center of the cable machine.', 'Lie down on the Bosu Ball with the small of your back arched around the ball. Your rear end should be close to the floor without touching it.', 'With both hands, reach back and grab the handle of each cable.', 'With your feet positioned in a wide stance, extend your arms straight out in front of you and in between your knees. Your hands should be at knee level.', 'Keep your arms straight and in-line with the upward angle of the cable. Elevate your torso in a crunching motion without dropping or bending your arms.', 'Maintain the rigid position with your arms. Slowly descend back to the starting position with your back arched around the Bosu Ball and your abdominals elongated.', 'Repeat the same series of movements to failure.', 'Once you reach failure, keep your abs tight and raise your torso into plank position so your back is elevated off the Bosu Ball.', 'Lower your arms down to your side; keep them straight. Start doing alternating side bends; reach for your heels! This finishing movement will focus on your obliques.']::text[], ARRAY['Bosu_Ball_Cable_Crunch_With_Side_Bends/0.jpg', 'Bosu_Ball_Cable_Crunch_With_Side_Bends/1.jpg']::text[], 'bosu ball cable crunch with side bends gap bung cap tren bong bosu kem nghieng luon crunch en polea sobre bosu con flexion lateral'),
  (NULL, 'Bottoms-Up Clean From The Hang Position', 'Bottoms-Up Clean From The Hang Position', 'Bottoms-Up Clean From The Hang Position', 'Cargada invertida con pesa rusa', 'biceps', 'kettlebell', 'compound', 'free_exercise_db', 'Bottoms-Up_Clean_From_The_Hang_Position', ARRAY['Initiate the exercise by standing upright with a kettlebell in one hand.', 'Swing the kettlebell back forcefully and then reverse the motion forcefully. Crush the kettlebell handle as hard as possible and raise the kettlebell to your shoulder.']::text[], ARRAY['Bottoms-Up_Clean_From_The_Hang_Position/0.jpg', 'Bottoms-Up_Clean_From_The_Hang_Position/1.jpg']::text[], 'bottoms-up clean from the hang position clean kettlebell up nguoc tu the treo cargada invertida con pesa rusa'),
  (NULL, 'Bottoms Up', 'Nâng hông ngược', 'Bottoms Up', 'Elevación de cadera invertida', 'abs', 'bodyweight', 'bodyweight', 'free_exercise_db', 'Bottoms_Up', ARRAY['Begin by lying on your back on the ground. Your legs should be straight and your arms at your side. This will be your starting position.', 'To perform the movement, tuck the knees toward your chest by flexing the hips and knees. Following this, extend your legs directly above you so that they are perpendicular to the ground. Rotate and elevate your pelvis to raise your glutes from the floor.', 'After a brief pause, return to the starting position.']::text[], ARRAY['Bottoms_Up/0.jpg', 'Bottoms_Up/1.jpg']::text[], 'bottoms up nang hong nguoc elevacion de cadera invertida'),
  (NULL, 'Box Jump (Multiple Response)', 'Box Jump (Multiple Response)', 'Box Jump (Multiple Response)', 'Saltos al cajón continuos', 'legs', 'other', 'compound', 'free_exercise_db', 'Box_Jump_Multiple_Response', ARRAY['Assume a relaxed stance facing the box or platform approximately an arm''s length away. Arms should be down at the sides and legs slightly bent.', 'Using the arms to aid in the initial burst, jump upward and forward, landing with feet simultaneously on top of the box or platform.', 'Immediately drop or jump back down to the original starting place; then repeat the sequence.']::text[], ARRAY['Box_Jump_Multiple_Response/0.jpg', 'Box_Jump_Multiple_Response/1.jpg']::text[], 'box jump (multiple response) bat nhay len buc lien tuc saltos al cajon continuos'),
  (NULL, 'Box Skip', 'Nhảy chân sáo lên bục', 'Box Skip', 'Saltos alternos al cajón', 'legs', 'other', 'compound', 'free_exercise_db', 'Box_Skip', ARRAY['You will need several boxes lined up about 8 feet apart.', 'Begin facing the first box with one leg slightly behind the other.', 'Drive off the back leg, attempting to gain as much height with the hips as possible.', 'Immediately upon landing on the box, drive the other leg forward and upward to gain height and distance, leaping from the box. Land between the first two boxes with the same leg that landed on the first box.', 'Then, step to the next box and repeat.']::text[], ARRAY['Box_Skip/0.jpg', 'Box_Skip/1.jpg']::text[], 'box skip nhay chan sao len buc saltos alternos al cajon'),
  (NULL, 'Box Squat', 'Box Squat', 'Box Squat', 'Sentadilla al cajón', 'legs', 'barbell', 'compound', 'free_exercise_db', 'Box_Squat', ARRAY['The box squat allows you to squat to desired depth and develop explosive strength in the squat movement. Begin in a power rack with a box at the appropriate height behind you. Typically, you would aim for a box height that brings you to a parallel squat, but you can train higher or lower if desired.', 'Begin by stepping under the bar and placing it across the back of the shoulders. Squeeze your shoulder blades together and rotate your elbows forward, attempting to bend the bar across your shoulders. Remove the bar from the rack, creating a tight arch in your lower back, and step back into position. Place your feet wider for more emphasis on the back, glutes, adductors, and hamstrings, or closer together for more quad development. Keep your head facing forward.', 'With your back, shoulders, and core tight, push your knees and butt out and you begin your descent. Sit back with your hips until you are seated on the box. Ideally, your shins should be perpendicular to the ground. Pause when you reach the box, and relax the hip flexors. Never bounce off of a box.', 'Keeping the weight on your heels and pushing your feet and knees out, drive upward off of the box as you lead the movement with your head. Continue upward, maintaining tightness head to toe.']::text[], ARRAY['Box_Squat/0.jpg', 'Box_Squat/1.jpg']::text[], 'box squat squat xuong buc sentadilla al cajon'),
  (NULL, 'Box Squat with Bands', 'Box Squat with Bands', 'Box Squat with Bands', 'Sentadilla al cajón con bandas', 'legs', 'barbell', 'compound', 'free_exercise_db', 'Box_Squat_with_Bands', ARRAY['Begin in a power rack with a box at the appropriate height behind you. Set up the bands on the sleeves, secured to either band pegs, the rack, or dumbbells so that there is appropriate tension. If dumbbells are used, secure them so that they don''t move. Also, ensure that the dumbbells you are using are heavy enough for the bands that you are using. Additional plates can be used to hold the dumbbells down. If more tension is needed, you can either widen the base on the floor or choke the bands. Typically, you would aim for a box height that brings you to a parallel squat, but you can train higher or lower if desired.', 'Begin by stepping under the bar and placing it across the back of the shoulders. Squeeze your shoulder blades together and rotate your elbows forward, attempting to bend the bar across your shoulders. Remove the bar from the rack, creating a tight arch in your lower back, and step back into position. Place your feet wider for more emphasis on the back, glutes, adductors, and hamstrings, or closer together for more quad development. Keep your head facing forward.', 'With your back, shoulders, and core tight, push your knees and butt out and you begin your descent. Sit back with your hips until you are seated on the box. Ideally, your shins should be perpendicular to the ground. Pause when you reach the box, and relax the hip flexors. Never bounce off of a box.', 'Keeping the weight on your heels and pushing your feet and knees out, drive upward off of the box as you lead the movement with your head. Continue upward, maintaining tightness head to toe. Use care to return the barbell to the rack.']::text[], ARRAY['Box_Squat_with_Bands/0.jpg', 'Box_Squat_with_Bands/1.jpg']::text[], 'box squat with bands squat xuong buc day khang luc sentadilla al cajon con bandas'),
  (NULL, 'Box Squat with Chains', 'Box Squat with Chains', 'Box Squat with Chains', 'Sentadilla al cajón con cadenas', 'legs', 'barbell', 'compound', 'free_exercise_db', 'Box_Squat_with_Chains', ARRAY['Begin in a power rack with a box at the appropriate height behind you. Typically, you would aim for a box height that brings you to a parallel squat, but you can train higher or lower if desired.', 'To set up the chains, begin by looping the leader chain over the sleeves of the bar. The heavy chain should be attached using a snap hook. Adjust the length of the lead chain so that a few links are still on the floor at the top of the movement.', 'Begin by stepping under the bar and placing it across the back of the shoulders. Squeeze your shoulder blades together and rotate your elbows forward, attempting to bend the bar across your shoulders. Remove the bar from the rack, creating a tight arch in your lower back, and step back into position. Place your feet wider for more emphasis on the back, glutes, adductors, and hamstrings, or closer together for more quad development. Keep your head facing forward.', 'With your back, shoulders, and core tight, push your knees and butt out and you begin your descent. Sit back with your hips until you are seated on the box. Ideally, your shins should be perpendicular to the ground. Pause when you reach the box, and relax the hip flexors. Never bounce off of a box.', 'Keeping the weight on your heels and pushing your feet and knees out, drive upward off of the box as you lead the movement with your head. Continue upward, maintaining tightness head to toe.']::text[], ARRAY['Box_Squat_with_Chains/0.jpg', 'Box_Squat_with_Chains/1.jpg']::text[], 'box squat with chains squat xuong buc co xich sentadilla al cajon con cadenas'),
  (NULL, 'Brachialis-SMR', 'Lăn giãn cơ cánh tay', 'Brachialis-SMR', 'Liberación del braquial', 'biceps', 'foam roll', 'timed', 'free_exercise_db', 'Brachialis-SMR', ARRAY['Lie on your side, with your upper arm against the foam roller. The upper arm should be more or less aligned with your body, with the outside of the bicep pressed against the foam roller.', 'Raise your hips off of the floor, supporting your weight on your arm and on your feet. Hold for 10-30 seconds, and then switch sides.']::text[], ARRAY['Brachialis-SMR/0.jpg', 'Brachialis-SMR/1.jpg']::text[], 'brachialis-smr lan gian co canh tay liberacion del braquial'),
  (NULL, 'Bradford/Rocky Presses', 'Đẩy vai Bradford', 'Bradford/Rocky Presses', 'Press Bradford', 'shoulders', 'barbell', 'compound', 'free_exercise_db', 'Bradford_Rocky_Presses', ARRAY['Sit on a Military Press Bench with a bar at shoulder level with a pronated grip (palms facing forward). Tip: Your grip should be wider than shoulder width and it should create a 90-degree angle between the forearm and the upper arm as the barbell goes down. This is your starting position.', 'Once you pick up the barbell with the correct grip, lift the bar up over your head by locking your arms.', 'Now lower the bar down to the back of the head slowly as you inhale.', 'Lift the bar back up to the starting position as you exhale.', 'Lower the bar down to the starting position slowly as you inhale. This is one repetition.', 'Alternate in this manner until you complete the recommended amount of repetitions.']::text[], ARRAY['Bradford_Rocky_Presses/0.jpg', 'Bradford_Rocky_Presses/1.jpg']::text[], 'bradford/rocky presses day vai bradford press bradford'),
  (NULL, 'Butt-Ups', 'Nâng mông chống tay', 'Butt-Ups', 'Elevaciones de glúteos en plancha', 'abs', 'bodyweight', 'bodyweight', 'free_exercise_db', 'Butt-Ups', ARRAY['Begin a pushup position but with your elbows on the ground and resting on your forearms. Your arms should be bent at a 90 degree angle.', 'Arch your back slightly out rather than keeping your back completely straight.', 'Raise your glutes toward the ceiling, squeezing your abs tightly to close the distance between your ribcage and hips. The end result will be that you''ll end up in a high bridge position. Exhale as you perform this portion of the movement.', 'Lower back down slowly to your starting position as you breathe in. Tip: Don''t let your back sag downwards.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Butt-Ups/0.jpg', 'Butt-Ups/1.jpg']::text[], 'butt-ups nang mong chong tay elevaciones de gluteos en plancha'),
  (NULL, 'Butt Lift (Bridge)', 'Nâng mông (cầu)', 'Butt Lift (Bridge)', 'Elevación de glúteos (puente)', 'glutes', 'bodyweight', 'bodyweight', 'free_exercise_db', 'Butt_Lift_Bridge', ARRAY['Lie flat on the floor on your back with the hands by your side and your knees bent. Your feet should be placed around shoulder width. This will be your starting position.', 'Pushing mainly with your heels, lift your hips off the floor while keeping your back straight. Breathe out as you perform this part of the motion and hold at the top for a second.', 'Slowly go back to the starting position as you breathe in.']::text[], ARRAY['Butt_Lift_Bridge/0.jpg', 'Butt_Lift_Bridge/1.jpg']::text[], 'butt lift (bridge) nang mong (cau) elevacion de gluteos (puente)'),
  (NULL, 'Butterfly', 'Ép ngực máy (butterfly)', 'Butterfly', 'Mariposa en máquina', 'chest', 'machine', 'isolation', 'free_exercise_db', 'Butterfly', ARRAY['Sit on the machine with your back flat on the pad.', 'Take hold of the handles. Tip: Your upper arms should be positioned parallel to the floor; adjust the machine accordingly. This will be your starting position.', 'Push the handles together slowly as you squeeze your chest in the middle. Breathe out during this part of the motion and hold the contraction for a second.', 'Return back to the starting position slowly as you inhale until your chest muscles are fully stretched.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Butterfly/0.jpg', 'Butterfly/1.jpg']::text[], 'butterfly ep nguc may (butterfly) mariposa en maquina'),
  (NULL, 'Cable Chest Press', 'Đẩy ngực cáp', 'Cable Chest Press', 'Press de pecho en polea', 'chest', 'cable', 'compound', 'free_exercise_db', 'Cable_Chest_Press', ARRAY['Adjust the weight to an appropriate amount and be seated, grasping the handles. Your upper arms should be about 45 degrees to the body, with your head and chest up. The elbows should be bent to about 90 degrees. This will be your starting position.', 'Begin by extending through the elbow, pressing the handles together straight in front of you. Keep your shoulder blades retracted as you execute the movement.', 'After pausing at full extension, return to th starting position, keeping tension on the cables.', 'You can also execute this movement with your back off the pad, at an incline or decline, or alternate hands.']::text[], ARRAY['Cable_Chest_Press/0.jpg', 'Cable_Chest_Press/1.jpg']::text[], 'cable chest press day nguc cap press de pecho en polea'),
  (NULL, 'Cable Crossover', 'Cable Crossover', 'Cable Crossover', 'Cruce de poleas', 'chest', 'cable', 'isolation', 'free_exercise_db', 'Cable_Crossover', ARRAY['To get yourself into the starting position, place the pulleys on a high position (above your head), select the resistance to be used and hold the pulleys in each hand.', 'Step forward in front of an imaginary straight line between both pulleys while pulling your arms together in front of you. Your torso should have a small forward bend from the waist. This will be your starting position.', 'With a slight bend on your elbows in order to prevent stress at the biceps tendon, extend your arms to the side (straight out at both sides) in a wide arc until you feel a stretch on your chest. Breathe in as you perform this portion of the movement. Tip: Keep in mind that throughout the movement, the arms and torso should remain stationary; the movement should only occur at the shoulder joint.', 'Return your arms back to the starting position as you breathe out. Make sure to use the same arc of motion used to lower the weights.', 'Hold for a second at the starting position and repeat the movement for the prescribed amount of repetitions.']::text[], ARRAY['Cable_Crossover/0.jpg', 'Cable_Crossover/1.jpg']::text[], 'cable crossover ep nguc cap cheo cruce de poleas'),
  (NULL, 'Cable Crunch', 'Cable Crunch', 'Cable Crunch', 'Crunch en polea', 'abs', 'cable', 'isolation', 'free_exercise_db', 'Cable_Crunch', ARRAY['Kneel below a high pulley that contains a rope attachment.', 'Grasp cable rope attachment and lower the rope until your hands are placed next to your face.', 'Flex your hips slightly and allow the weight to hyperextend the lower back. This will be your starting position.', 'With the hips stationary, flex the waist as you contract the abs so that the elbows travel towards the middle of the thighs. Exhale as you perform this portion of the movement and hold the contraction for a second.', 'Slowly return to the starting position as you inhale. Tip: Make sure that you keep constant tension on the abs throughout the movement. Also, do not choose a weight so heavy that the lower back handles the brunt of the work.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Cable_Crunch/0.jpg', 'Cable_Crunch/1.jpg']::text[], 'cable crunch gap bung cap crunch en polea'),
  (NULL, 'Cable Deadlifts', 'Cable Deadlifts', 'Cable Deadlifts', 'Peso muerto en polea', 'legs', 'cable', 'compound', 'free_exercise_db', 'Cable_Deadlifts', ARRAY['Move the cables to the bottom of the towers and select an appropriate weight. Stand directly in between the uprights.', 'To begin, squat down be flexing your hips and knees until you can reach the handles.', 'After grasping them, begin your ascent. Driving through your heels extend your hips and knees keeping your hands hanging at your side. Keep your head and chest up throughout the movement.', 'After reaching a full standing position, Return to the starting position and repeat.']::text[], ARRAY['Cable_Deadlifts/0.jpg', 'Cable_Deadlifts/1.jpg']::text[], 'cable deadlifts deadlift cap peso muerto en polea'),
  (NULL, 'Cable Hammer Curls - Rope Attachment', 'Cable Hammer Curls - Rope Attachment', 'Cable Hammer Curls - Rope Attachment', 'Curl martillo en polea con cuerda', 'biceps', 'cable', 'isolation', 'free_exercise_db', 'Cable_Hammer_Curls_-_Rope_Attachment', ARRAY['Attach a rope attachment to a low pulley and stand facing the machine about 12 inches away from it.', 'Grasp the rope with a neutral (palms-in) grip and stand straight up keeping the natural arch of the back and your torso stationary.', 'Put your elbows in by your side and keep them there stationary during the entire movement. Tip: Only the forearms should move; not your upper arms. This will be your starting position.', 'Using your biceps, pull your arms up as you exhale until your biceps touch your forearms. Tip: Remember to keep the elbows in and your upper arms stationary.', 'After a 1 second contraction where you squeeze your biceps, slowly start to bring the weight back to the original position.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Cable_Hammer_Curls_-_Rope_Attachment/0.jpg', 'Cable_Hammer_Curls_-_Rope_Attachment/1.jpg']::text[], 'cable hammer curls - rope attachment cuon bua cap day thung curl martillo en polea con cuerda'),
  (NULL, 'Cable Hip Adduction', 'Khép đùi cáp', 'Cable Hip Adduction', 'Aducción de cadera en polea', 'legs', 'cable', 'isolation', 'free_exercise_db', 'Cable_Hip_Adduction', ARRAY['Stand in front of a low pulley facing forward with one leg next to the pulley and the other one away.', 'Attach the ankle cuff to the cable and also to the ankle of the leg that is next to the pulley.', 'Now step out and away from the stack with a wide stance and grasp the bar of the pulley system.', 'Stand on the foot that does not have the ankle cuff (the far foot) and allow the leg with the cuff to be pulled towards the low pulley. This will be your starting position.', 'Now perform the movement by moving the leg with the ankle cuff in front of the far leg by using the inner thighs to abduct the hip. Breathe out during this portion of the movement.', 'Slowly return to the starting position as you breathe in.', 'Repeat for the recommended amount of repetitions and then repeat the same movement with the opposite leg.']::text[], ARRAY['Cable_Hip_Adduction/0.jpg', 'Cable_Hip_Adduction/1.jpg']::text[], 'cable hip adduction khep dui cap aduccion de cadera en polea'),
  (NULL, 'Cable Incline Pushdown', 'Kéo cáp xuống ghế dốc', 'Cable Incline Pushdown', 'Jalón inclinado en polea', 'back', 'cable', 'isolation', 'free_exercise_db', 'Cable_Incline_Pushdown', ARRAY['Lie on incline an bench facing away from a high pulley machine that has a straight bar attachment on it.', 'Grasp the straight bar attachment overhead with a pronated (overhand; palms down) shoulder width grip and extend your arms in front of you. The bar should be around 2 inches away from your upper thighs. This will be your starting position.', 'Keeping the upper arms stationary, lift your arms back in a semi circle until the bar is straight over your head. Breathe in during this portion of the movement.', 'Slowly go back to the starting position using your lats and hold the contraction once you reach the starting position. Breathe out during the execution of this movement.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Cable_Incline_Pushdown/0.jpg', 'Cable_Incline_Pushdown/1.jpg']::text[], 'cable incline pushdown keo cap xuong ghe doc jalon inclinado en polea'),
  (NULL, 'Cable Incline Triceps Extension', 'Duỗi tay sau cáp ghế dốc', 'Cable Incline Triceps Extension', 'Extensión de tríceps inclinado en polea', 'triceps', 'cable', 'isolation', 'free_exercise_db', 'Cable_Incline_Triceps_Extension', ARRAY['Lie on incline an bench facing away from a high pulley machine that has a straight bar attachment on it.', 'Grasp the straight bar attachment overhead with a pronated (overhand; palms down) narrow grip (less than shoulder width) and keep your elbows tucked in to your sides. Your upper arms should create around a 25 degree angle when measured from the floor.', 'Keeping the upper arms stationary, extend the arms as you flex the triceps. Breathe out during this portion of the movement and hold the contraction for a second.', 'Slowly go back to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Cable_Incline_Triceps_Extension/0.jpg', 'Cable_Incline_Triceps_Extension/1.jpg']::text[], 'cable incline triceps extension duoi tay sau cap ghe doc extension de triceps inclinado en polea'),
  (NULL, 'Cable Internal Rotation', 'Xoay vai trong cáp', 'Cable Internal Rotation', 'Rotación interna en polea', 'shoulders', 'cable', 'compound', 'free_exercise_db', 'Cable_Internal_Rotation', ARRAY['Sit next to a low pulley sideways (with legs stretched in front of you or crossed) and grasp the single hand cable attachment with the arm nearest to the cable. Tip: If you can adjust the pulley''s height, you can use a flat bench to sit on instead.', 'Position the elbow against your side with the elbow bent at 90° and the arm pointing towards the pulley. This will be your starting position.', 'Pull the single hand cable attachment toward your body by internally rotating your shoulder until your forearm is across your abs. You will be creating an imaginary semi-circle. Tip: The forearm should be perpendicular to your torso at all times.', 'Slowly go back to the initial position.', 'Repeat for the recommended amount of repetitions and then repeat the movement with the next arm.']::text[], ARRAY['Cable_Internal_Rotation/0.jpg', 'Cable_Internal_Rotation/1.jpg']::text[], 'cable internal rotation xoay vai trong cap rotacion interna en polea'),
  (NULL, 'Cable Iron Cross', 'Thập tự sắt cáp', 'Cable Iron Cross', 'Cruz de hierro en polea', 'chest', 'cable', 'isolation', 'free_exercise_db', 'Cable_Iron_Cross', ARRAY['Begin by moving the pulleys to the high position, select the resistance to be used, and take a handle in each hand.', 'Stand directly between both pulleys with your arms extended out to your sides. Your head and chest should be up while your arms form a "T". This will be your starting position.', 'Keeping the elbows extended, pull your arms straight to your sides.', 'Return your arms back to the starting position after a pause at the peak contraction.', 'Continue the movement for the prescribed number of repetitions.']::text[], ARRAY['Cable_Iron_Cross/0.jpg', 'Cable_Iron_Cross/1.jpg']::text[], 'cable iron cross thap tu sat cap cruz de hierro en polea'),
  (NULL, 'Cable Judo Flip', 'Lật judo cáp', 'Cable Judo Flip', 'Giro judo en polea', 'abs', 'cable', 'compound', 'free_exercise_db', 'Cable_Judo_Flip', ARRAY['Connect a rope attachment to a tower, and move the cable to the lowest pulley position. Stand with your side to the cable with a wide stance, and grab the rope with both hands.', 'Twist your body away from the pulley as you bring the rope over your shoulder like you''re performing a judo flip.', 'Shift your weight between your feet as you twist and crunch forward, pulling the cable downward.', 'Return to the starting position and repeat until failure.', 'Then, reposition and repeat the same series of movements on the opposite side.']::text[], ARRAY['Cable_Judo_Flip/0.jpg', 'Cable_Judo_Flip/1.jpg']::text[], 'cable judo flip lat judo cap giro judo en polea'),
  (NULL, 'Cable Lying Triceps Extension', 'Duỗi tay sau cáp nằm', 'Cable Lying Triceps Extension', 'Extensión de tríceps tumbado en polea', 'triceps', 'cable', 'isolation', 'free_exercise_db', 'Cable_Lying_Triceps_Extension', ARRAY['Lie on a flat bench and grasp the straight bar attachment of a low pulley with a narrow overhand grip. Tip: The easiest way to do this is to have someone hand you the bar as you lay down.', 'With your arms extended, position the bar over your torso. Your arms and your torso should create a 90-degree angle. This will be your starting position.', 'Lower the bar by bending at the elbow while keeping the upper arms stationary and elbows in. Go down until the bar lightly touches your forehead. Breathe in as you perform this portion of the movement.', 'Flex the triceps as you lift the bar back to its starting position. Exhale as you perform this portion of the movement.', 'Hold for a second at the contracted position and repeat for the recommended amount of repetitions.']::text[], ARRAY['Cable_Lying_Triceps_Extension/0.jpg', 'Cable_Lying_Triceps_Extension/1.jpg']::text[], 'cable lying triceps extension duoi tay sau cap nam extension de triceps tumbado en polea'),
  (NULL, 'Cable One Arm Tricep Extension', 'Duỗi tay sau cáp một tay', 'Cable One Arm Tricep Extension', 'Extensión de tríceps a una mano en polea', 'triceps', 'cable', 'isolation', 'free_exercise_db', 'Cable_One_Arm_Tricep_Extension', ARRAY['With your right hand, grasp a single handle attached to the high-cable pulley using a supinated (underhand; palms facing up) grip. You should be standing directly in front of the weight stack.', 'Now pull the handle down so that your upper arm and elbow are locked in to the side of your body. Your upper arm and forearm should form an acute angle (less than 90-degrees). You can keep the other arm by the waist and you can have one leg in front of you and the other one back for better balance. This will be your starting position.', 'As you contract the triceps, move the single handle attachment down to your side until your arm is straight. Breathe out as you perform this movement. Tip: Only the forearms should move. Your upper arms should remain stationary at all times.', 'Squeeze the triceps and hold for a second in this contracted position.', 'Slowly return the handle to the starting position.', 'Repeat for the recommended amount of repetitions and then perform the same movement with the other arm.']::text[], ARRAY['Cable_One_Arm_Tricep_Extension/0.jpg', 'Cable_One_Arm_Tricep_Extension/1.jpg']::text[], 'cable one arm tricep extension duoi tay sau cap mot tay extension de triceps a una mano en polea'),
  (NULL, 'Cable Preacher Curl', 'Cable Preacher Curl', 'Cable Preacher Curl', 'Curl predicador en polea', 'biceps', 'cable', 'isolation', 'free_exercise_db', 'Cable_Preacher_Curl', ARRAY['Place a preacher bench about 2 feet in front of a pulley machine.', 'Attach a straight bar to the low pulley.', 'Sit at the preacher bench with your elbow and upper arms firmly on top of the bench pad and have someone hand you the bar from the low pulley.', 'Grab the bar and fully extend your arms on top of the preacher bench pad. This will be your starting position.', 'Now start pilling the weight up towards your shoulders and squeeze the biceps hard at the top of the movement. Exhale as you perform this motion. Also, hold for a second at the top.', 'Now slowly lower the weight to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Cable_Preacher_Curl/0.jpg', 'Cable_Preacher_Curl/1.jpg']::text[], 'cable preacher curl cuon tay truoc cap ghe doc curl predicador en polea'),
  (NULL, 'Cable Rear Delt Fly', 'Cable Rear Delt Fly', 'Cable Rear Delt Fly', 'Aperturas posteriores en polea', 'shoulders', 'cable', 'isolation', 'free_exercise_db', 'Cable_Rear_Delt_Fly', ARRAY['Adjust the pulleys to the appropriate height and adjust the weight. The pulleys should be above your head.', 'Grab the left pulley with your right hand and the right pulley with your left hand, crossing them in front of you. This will be your starting position.', 'Initiate the movement by moving your arms back and outward, keeping your arms straight as you execute the movement.', 'Pause at the end of the motion before returning the handles to the start position.']::text[], ARRAY['Cable_Rear_Delt_Fly/0.jpg', 'Cable_Rear_Delt_Fly/1.jpg']::text[], 'cable rear delt fly bay vai sau cap aperturas posteriores en polea'),
  (NULL, 'Cable Reverse Crunch', 'Cable Reverse Crunch', 'Cable Reverse Crunch', 'Crunch inverso en polea', 'abs', 'cable', 'isolation', 'free_exercise_db', 'Cable_Reverse_Crunch', ARRAY['Connect an ankle strap attachment to a low pulley cable and position a mat on the floor in front of it.', 'Sit down with your feet toward the pulley and attach the cable to your ankles.', 'Lie down, elevate your legs and bend your knees at a 90-degree angle. Your legs and the cable should be aligned. If not, adjust the pulley up or down until they are.', 'With your hands behind your head, bring your knees inward to your torso and elevate your hips off the floor.', 'Pause for a moment and in a slow and controlled manner drop your hips and bring your legs back to the starting 90-degree angle. You should still have tension on your abs in the resting position.', 'Repeat the same movement to failure.']::text[], ARRAY['Cable_Reverse_Crunch/0.jpg', 'Cable_Reverse_Crunch/1.jpg']::text[], 'cable reverse crunch gap bung nguoc cap crunch inverso en polea'),
  (NULL, 'Cable Rope Overhead Triceps Extension', 'Duỗi tay sau qua đầu cáp dây thừng', 'Cable Rope Overhead Triceps Extension', 'Extensión de tríceps sobre la cabeza con cuerda', 'triceps', 'cable', 'isolation', 'free_exercise_db', 'Cable_Rope_Overhead_Triceps_Extension', ARRAY['Attach a rope to the bottom pulley of the pulley machine.', 'Grasping the rope with both hands, extend your arms with your hands directly above your head using a neutral grip (palms facing each other). Your elbows should be in close to your head and the arms should be perpendicular to the floor with the knuckles aimed at the ceiling. This will be your starting position.', 'Slowly lower the rope behind your head as you hold the upper arms stationary. Inhale as you perform this movement and pause when your triceps are fully stretched.', 'Return to the starting position by flexing your triceps as you breathe out.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Cable_Rope_Overhead_Triceps_Extension/0.jpg', 'Cable_Rope_Overhead_Triceps_Extension/1.jpg']::text[], 'cable rope overhead triceps extension duoi tay sau qua dau cap day thung extension de triceps sobre la cabeza con cuerda'),
  (NULL, 'Cable Rope Rear-Delt Rows', 'Chèo vai sau cáp dây thừng', 'Cable Rope Rear-Delt Rows', 'Remo para deltoides posterior con cuerda', 'shoulders', 'cable', 'compound', 'free_exercise_db', 'Cable_Rope_Rear-Delt_Rows', ARRAY['Sit in the same position on a low pulley row station as you would if you were doing seated cable rows for the back.', 'Attach a rope to the pulley and grasp it with an overhand grip. Your arms should be extended and parallel to the floor with the elbows flared out.', 'Keep your lower back upright and slide your hips back so that your knees are slightly bent. This will be your starting position.', 'Pull the cable attachment towards your upper chest, just below the neck, as you keep your elbows up and out to the sides. Continue this motion as you exhale until the elbows travel slightly behind the back. Tip: Keep your upper arms horizontal, perpendicular to the torso and parallel to the floor throughout the motion.', 'Go back to the initial position where the arms are extended and the shoulders are stretched forward. Inhale as you perform this portion of the movement.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Cable_Rope_Rear-Delt_Rows/0.jpg', 'Cable_Rope_Rear-Delt_Rows/1.jpg']::text[], 'cable rope rear-delt rows cheo vai sau cap day thung remo para deltoides posterior con cuerda'),
  (NULL, 'Cable Russian Twists', 'Cable Russian Twists', 'Cable Russian Twists', 'Giro ruso en polea', 'abs', 'cable', 'compound', 'free_exercise_db', 'Cable_Russian_Twists', ARRAY['Connect a standard handle attachment, and position the cable to a middle pulley position.', 'Lie on a stability ball perpendicular to the cable and grab the handle with one hand. You should be approximately arm''s length away from the pulley, with the tension of the weight on the cable.', 'Grab the handle with both hands and fully extend your arms above your chest. You hands should be directly in-line with the pulley. If not, adjust the pulley up or down until they are.', 'Keep your hips elevated and abs engaged. Rotate your torso away from the pulley for a full-quarter rotation. Your body should be flat from head to knees.', 'Pause for a moment and in a slow and controlled manner reset to the starting position. You should still have side tension on the cable in the resting position.', 'Repeat the same movement to failure.', 'Then, reposition and repeat the same series of movements on the opposite side.']::text[], ARRAY['Cable_Russian_Twists/0.jpg', 'Cable_Russian_Twists/1.jpg']::text[], 'cable russian twists xoay nguoi kieu nga cap giro ruso en polea'),
  (NULL, 'Cable Seated Crunch', 'Cable Seated Crunch', 'Cable Seated Crunch', 'Crunch sentado en polea', 'abs', 'cable', 'isolation', 'free_exercise_db', 'Cable_Seated_Crunch', ARRAY['Seat on a flat bench with your back facing a high pulley.', 'Grasp the cable rope attachment with both hands (with the palms of the hands facing each other) and place your hands securely over both shoulders. Tip: Allow the weight to hyperextend the lower back slightly. This will be your starting position.', 'With the hips stationary, flex the waist so the elbows travel toward the hips. Breathe out as you perform this step.', 'As you inhale, go back to the initial position slowly.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Cable_Seated_Crunch/0.jpg', 'Cable_Seated_Crunch/1.jpg']::text[], 'cable seated crunch gap bung cap ngoi crunch sentado en polea'),
  (NULL, 'Cable Seated Lateral Raise', 'Nâng tạ ngang cáp ngồi', 'Cable Seated Lateral Raise', 'Elevación lateral sentado en polea', 'shoulders', 'cable', 'isolation', 'free_exercise_db', 'Cable_Seated_Lateral_Raise', ARRAY['Stand in the middle of two low pulleys that are opposite to each other and place a flat bench right behind you (in perpendicular fashion to you; the narrow edge of the bench should be the one behind you). Select the weight to be used on each pulley.', 'Now sit at the edge of the flat bench behind you with your feet placed in front of your knees.', 'Bend forward while keeping your back flat and rest your torso on the thighs.', 'Have someone give you the single handles attached to the pulleys. Grasp the left pulley with the right hand and the right pulley with the left after you select your weight. The pulleys should run under your knees and your arms will be extended with palms facing each other and a slight bend at the elbows. This will be the starting position.', 'While keeping the arms stationary, raise the upper arms to the sides until they are parallel to the floor and at shoulder height. Exhale during the execution of this movement and hold the contraction for a second.', 'Slowly lower your arms to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions. Tip: Maintain upper arms perpendicular to torso and a fixed elbow position (10 degree to 30 degree angle) throughout exercise.']::text[], ARRAY['Cable_Seated_Lateral_Raise/0.jpg', 'Cable_Seated_Lateral_Raise/1.jpg']::text[], 'cable seated lateral raise nang ta ngang cap ngoi elevacion lateral sentado en polea'),
  (NULL, 'Cable Shoulder Press', 'Đẩy vai cáp', 'Cable Shoulder Press', 'Press de hombros en polea', 'shoulders', 'cable', 'compound', 'free_exercise_db', 'Cable_Shoulder_Press', ARRAY['Move the cables to the bottom of the towers and select an appropriate weight.', 'Stand directly in between the uprights. Grasp the cables and hold them at shoulder height, palms facing forward. This will be your starting position.', 'Keeping your head and chest up, extend through the elbow to press the handles directly over head.', 'After pausing at the top, return to the starting position and repeat.']::text[], ARRAY['Cable_Shoulder_Press/0.jpg', 'Cable_Shoulder_Press/1.jpg']::text[], 'cable shoulder press day vai cap press de hombros en polea'),
  (NULL, 'Cable Shrugs', 'Cable Shrugs', 'Cable Shrugs', 'Encogimientos de hombros en polea', 'shoulders', 'cable', 'isolation', 'free_exercise_db', 'Cable_Shrugs', ARRAY['Grasp a cable bar attachment that is attached to a low pulley with a shoulder width or slightly wider overhand (palms facing down) grip.', 'Stand erect close to the pulley with your arms extended in front of you holding the bar. This will be your starting position.', 'Lift the bar by elevating the shoulders as high as possible as you exhale. Hold the contraction at the top for a second. Tip: The arms should remain extended at all times. Refrain from using the biceps to help lift the bar. Only the shoulders should be moving up and down.', 'Lower the bar back to the original position.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Cable_Shrugs/0.jpg', 'Cable_Shrugs/1.jpg']::text[], 'cable shrugs nhun vai cap encogimientos de hombros en polea'),
  (NULL, 'Cable Wrist Curl', 'Cable Wrist Curl', 'Cable Wrist Curl', 'Curl de muñeca en polea', 'biceps', 'cable', 'isolation', 'free_exercise_db', 'Cable_Wrist_Curl', ARRAY['Start out by placing a flat bench in front of a low pulley cable that has a straight bar attachment.', 'Use your arms to grab the cable bar with a narrow to shoulder width supinated grip (palms up) and bring them up so that your forearms are resting against the top of your thighs. Your wrists should be hanging just beyond your knees.', 'Start out by curling your wrist upwards and exhaling. Keep the contraction for a second.', 'Slowly lower your wrists back down to the starting position while inhaling.', 'Your forearms should be stationary as your wrist is the only movement needed to perform this exercise.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Cable_Wrist_Curl/0.jpg', 'Cable_Wrist_Curl/1.jpg']::text[], 'cable wrist curl cuon co tay cap curl de muneca en polea'),
  (NULL, 'Calf-Machine Shoulder Shrug', 'Calf-Machine Shoulder Shrug', 'Calf-Machine Shoulder Shrug', 'Encogimiento en máquina de gemelos', 'shoulders', 'machine', 'isolation', 'free_exercise_db', 'Calf-Machine_Shoulder_Shrug', ARRAY['Position yourself on the calf machine so that the shoulder pads are above your shoulders. Your torso should be straight with the arms extended normally by your side. This will be your starting position.', 'Raise your shoulders up towards your ears as you exhale and hold the contraction for a full second.', 'Slowly return to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Calf-Machine_Shoulder_Shrug/0.jpg', 'Calf-Machine_Shoulder_Shrug/1.jpg']::text[], 'calf-machine shoulder shrug nhun vai may nhon bap chan encogimiento en maquina de gemelos'),
  (NULL, 'Calf Press', 'Đạp bắp chân', 'Calf Press', 'Prensa de gemelos', 'calves', 'machine', 'isolation', 'free_exercise_db', 'Calf_Press', ARRAY['Adjust the seat so that your legs are only slightly bent in the start position. The balls of your feet should be firmly on the platform.', 'Select an appropriate weight, and grasp the handles. This will be your starting position.', 'Straighten the legs by extending the knees, just barely lifting the weight from the stack. Your ankle should be fully flexed, toes pointing up. Execute the movement by pressing downward through the balls of your feet as far as possible.', 'After a brief pause, reverse the motion and repeat.']::text[], ARRAY['Calf_Press/0.jpg', 'Calf_Press/1.jpg']::text[], 'calf press dap bap chan prensa de gemelos'),
  (NULL, 'Calf Press On The Leg Press Machine', 'Calf Press On The Leg Press Machine', 'Calf Press On The Leg Press Machine', 'Gemelos en prensa de piernas', 'calves', 'machine', 'isolation', 'free_exercise_db', 'Calf_Press_On_The_Leg_Press_Machine', ARRAY['Using a leg press machine, sit down on the machine and place your legs on the platform directly in front of you at a medium (shoulder width) foot stance.', 'Lower the safety bars holding the weighted platform in place and press the platform all the way up until your legs are fully extended in front of you without locking your knees. (Note: In some leg press units you can leave the safety bars on for increased safety. If your leg press unit allows for this, then this is the preferred method of performing the exercise.) Your torso and the legs should make perfect 90-degree angle. Now carefully place your toes and balls of your feet on the lower portion of the platform with the heels extending off. Toes should be facing forward, outwards or inwards as described at the beginning of the chapter. This will be your starting position.', 'Press on the platform by raising your heels as you breathe out by extending your ankles as high as possible and flexing your calf. Ensure that the knee is kept stationary at all times. There should be no bending at any time. Hold the contracted position by a second before you start to go back down.', 'Go back slowly to the starting position as you breathe in by lowering your heels as you bend the ankles until calves are stretched.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Calf_Press_On_The_Leg_Press_Machine/0.jpg', 'Calf_Press_On_The_Leg_Press_Machine/1.jpg']::text[], 'calf press on the leg press machine dap bap chan tren may dap dui gemelos en prensa de piernas'),
  (NULL, 'Calf Raise On A Dumbbell', 'Nhón bắp chân trên tạ đơn', 'Calf Raise On A Dumbbell', 'Elevación de gemelos sobre mancuerna', 'calves', 'dumbbell', 'isolation', 'free_exercise_db', 'Calf_Raise_On_A_Dumbbell', ARRAY['Hang on to a sturdy object for balance and stand on a dumbbell handle, preferably one with round plates so that it rolls as in this manner you have to work harder to stabilize yourself; thus increasing the effectiveness of the exercise.', 'Now roll your foot slightly forward so that you can get a nice stretch of the calf. This will be your starting position.', 'Lift the calf as you roll your foot over the top of the handle so that you get a full extension. Exhale during the execution of this movement. Contract the calf hard at the top and hold for a second. Tip: As you come up, roll the dumbbell slightly backward.', 'Now inhale as you roll the dumbbell slightly forward as you come down to get a better stretch.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Calf_Raise_On_A_Dumbbell/0.jpg', 'Calf_Raise_On_A_Dumbbell/1.jpg']::text[], 'calf raise on a dumbbell nhon bap chan tren ta don elevacion de gemelos sobre mancuerna'),
  (NULL, 'Calf Raises - With Bands', 'Nhón bắp chân dây kháng lực', 'Calf Raises - With Bands', 'Elevación de gemelos con banda', 'calves', 'band', 'isolation', 'free_exercise_db', 'Calf_Raises_-_With_Bands', ARRAY['Grab an exercise band and stand on it with your toes making sure that the length of the band between the foot and the arms is the same for both sides.', 'While holding the handles of the band, raise the arms to the side of your head as if you were getting ready to perform a shoulder press. The palms should be facing forward with the elbows bent and to the sides. This movement will create tension on the band. This will be your starting position.', 'Keeping the hands by your shoulder, stand up on your toes as you exhale and contract the calves hard at the top of the movement.', 'After a one second contraction, slowly go back down to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Calf_Raises_-_With_Bands/0.jpg', 'Calf_Raises_-_With_Bands/1.jpg']::text[], 'calf raises - with bands nhon bap chan day khang luc elevacion de gemelos con banda'),
  (NULL, 'Calf Stretch Elbows Against Wall', 'Giãn bắp chân tì khuỷu tay vào tường', 'Calf Stretch Elbows Against Wall', 'Estiramiento de gemelos con codos en la pared', 'calves', 'other', 'timed', 'free_exercise_db', 'Calf_Stretch_Elbows_Against_Wall', ARRAY['Stand facing a wall from a couple feet away.', 'Lean against the wall, placing your weight on your forearms.', 'Attempt to keep your heels on the ground. Hold for 10-20 seconds. You may move further or closer the wall, making it more or less difficult, respectively.']::text[], ARRAY['Calf_Stretch_Elbows_Against_Wall/0.jpg', 'Calf_Stretch_Elbows_Against_Wall/1.jpg']::text[], 'calf stretch elbows against wall gian bap chan ti khuyu tay vao tuong estiramiento de gemelos con codos en la pared'),
  (NULL, 'Calf Stretch Hands Against Wall', 'Giãn bắp chân chống tay vào tường', 'Calf Stretch Hands Against Wall', 'Estiramiento de gemelos con manos en la pared', 'calves', 'other', 'timed', 'free_exercise_db', 'Calf_Stretch_Hands_Against_Wall', ARRAY['Stand facing a wall from several feet away. Stagger your stance, placing one foot forward.', 'Lean forward and rest your hands on the wall, keeping your heel, hip and head in a straight line.', 'Attempt to keep your heel on the ground. Hold for 10-20 seconds and then switch sides.']::text[], ARRAY['Calf_Stretch_Hands_Against_Wall/0.jpg', 'Calf_Stretch_Hands_Against_Wall/1.jpg']::text[], 'calf stretch hands against wall gian bap chan chong tay vao tuong estiramiento de gemelos con manos en la pared'),
  (NULL, 'Calves-SMR', 'Lăn giãn bắp chân', 'Calves-SMR', 'Liberación de gemelos con rodillo', 'calves', 'foam roll', 'timed', 'free_exercise_db', 'Calves-SMR', ARRAY['Begin seated on the floor. Place a foam roller underneath your lower leg. Your other leg can either be crossed over the opposite or be placed on the floor, supporting some of your weight. This will be your starting position.', 'Place your hands to your side or just behind you, and press down to raise your hips off of the floor, placing much of your weight against your calf muscle. Roll from below the knee to above the ankle, pausing at points of tension for 10-30 seconds. Repeat for the other leg.']::text[], ARRAY['Calves-SMR/0.jpg', 'Calves-SMR/1.jpg']::text[], 'calves-smr lan gian bap chan liberacion de gemelos con rodillo'),
  (NULL, 'Car Deadlift', 'Car Deadlift', 'Car Deadlift', 'Peso muerto de coche', 'legs', 'other', 'compound', 'free_exercise_db', 'Car_Deadlift', ARRAY['This event apparatus typically has neutral grip handles, however some have a straight bar that you can approach like a normal deadlift. The apparatus can be loaded with a vehicle or other heavy objects such as tractor tires or kegs.', 'Center yourself between the handles if you are a strong squatter, or back a couple inches if you are a strong deadlifter. You feet should be about hip width apart. Bend at the hip to grip the handles. With your feet and your grip set, take a big breath and then lower your hips and flex the knees.', 'Look forward with your head, keep your chest up and your back arched, and begin driving through the heels to move the weight upward. As the weight comes up, pull your shoulder blades together as you drive your hips forward.', 'Lower the weight by bending at the hips and guiding it to the floor.']::text[], ARRAY['Car_Deadlift/0.jpg', 'Car_Deadlift/1.jpg']::text[], 'car deadlift deadlift nang xe peso muerto de coche'),
  (NULL, 'Car Drivers', 'Xoay vô lăng với đĩa tạ', 'Car Drivers', 'Volante con disco', 'shoulders', 'barbell', 'isolation', 'free_exercise_db', 'Car_Drivers', ARRAY['While standing upright, hold a barbell plate in both hands at the 3 and 9 o''clock positions. Your palms should be facing each other and your arms should be extended straight out in front of you. This will be your starting position.', 'Initiate the movement by rotating the plate as far to one side as possible. Use the same type of movement you would use to turn a steering wheel to one side.', 'Reverse the motion, turning it all the way to the opposite side.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Car_Drivers/0.jpg', 'Car_Drivers/1.jpg']::text[], 'car drivers xoay vo lang voi dia ta volante con disco'),
  (NULL, 'Carioca Quick Step', 'Bước chéo nhanh carioca', 'Carioca Quick Step', 'Carioca rápida', 'legs', 'other', 'bodyweight', 'free_exercise_db', 'Carioca_Quick_Step', ARRAY['Begin with your feet a few inches apart and your left arm up in a relaxed, athletic position.', 'With your right foot, quick step behind and pull the knee up.', 'Fire your arms back up when you pull the right knee, being sure that your knee goes straight up and down. Avoid turning your feet as you move and continue to look forward as you move to the side.']::text[], ARRAY['Carioca_Quick_Step/0.jpg', 'Carioca_Quick_Step/1.jpg']::text[], 'carioca quick step buoc cheo nhanh carioca carioca rapida'),
  (NULL, 'Cat Stretch', 'Giãn lưng tư thế con mèo', 'Cat Stretch', 'Estiramiento del gato', 'back', 'other', 'timed', 'free_exercise_db', 'Cat_Stretch', ARRAY['Position yourself on the floor on your hands and knees.', 'Pull your belly in and round your spine, lower back, shoulders, and neck, letting your head drop.', 'Hold for 15 seconds.']::text[], ARRAY['Cat_Stretch/0.jpg', 'Cat_Stretch/1.jpg']::text[], 'cat stretch gian lung tu the con meo estiramiento del gato'),
  (NULL, 'Catch and Overhead Throw', 'Bắt và ném bóng qua đầu', 'Catch and Overhead Throw', 'Atrapar y lanzar sobre la cabeza', 'back', 'medicine ball', 'compound', 'free_exercise_db', 'Catch_and_Overhead_Throw', ARRAY['Begin standing while facing a wall or a partner.', 'Using both hands, position the ball behind your head, stretching as much as possible, and forcefully throw the ball forward.', 'Ensure that you follow your throw through, being prepared to receive your rebound from your throw. If you are throwing against the wall, make sure that you stand close enough to the wall to receive the rebound, and aim a little higher than you would with a partner.']::text[], ARRAY['Catch_and_Overhead_Throw/0.jpg', 'Catch_and_Overhead_Throw/1.jpg']::text[], 'catch and overhead throw bat va nem bong qua dau atrapar y lanzar sobre la cabeza'),
  (NULL, 'Chain Handle Extension', 'Duỗi tay sau tay cầm xích', 'Chain Handle Extension', 'Extensión con asas de cadena', 'triceps', 'other', 'isolation', 'free_exercise_db', 'Chain_Handle_Extension', ARRAY['You will need two cable handle attachments and a flat bench, as well as chains, for this exercise. Clip the middle of the chains to the handles, and position yourself on the flat bench. Your elbows should be pointing straight up.', 'Begin by extending through the elbow, keeping your upper arm still, with your wrists pronated.', 'Pause at the lockout, and reverse the motion to return to the starting position.']::text[], ARRAY['Chain_Handle_Extension/0.jpg', 'Chain_Handle_Extension/1.jpg']::text[], 'chain handle extension duoi tay sau tay cam xich extension con asas de cadena'),
  (NULL, 'Chain Press', 'Đẩy ngực với tay cầm xích', 'Chain Press', 'Press con cadenas', 'chest', 'other', 'compound', 'free_exercise_db', 'Chain_Press', ARRAY['Begin by connecting the chains to the cable handle attachments. Position yourself on the flat bench in the same position as for a dumbbell press. Your wrists should be pronated and arms perpendicular to the floor. This will be your starting position.', 'Lower the chains by flexing the elbows, unloading some of the chain onto the floor.', 'Continue until your elbow forms a 90 degree angle, and then reverse the motion by extending through the elbow to lockout.']::text[], ARRAY['Chain_Press/0.jpg', 'Chain_Press/1.jpg']::text[], 'chain press day nguc voi tay cam xich press con cadenas'),
  (NULL, 'Chair Leg Extended Stretch', 'Giãn đùi sau duỗi chân trên ghế', 'Chair Leg Extended Stretch', 'Estiramiento de isquios con pierna en silla', 'legs', 'other', 'timed', 'free_exercise_db', 'Chair_Leg_Extended_Stretch', ARRAY['Sit upright in a chair and grip the seat on the sides.', 'Raise one leg, extending the knee, flexing the ankle as you do so.', 'Slowly move that leg outward as far as you can, and then back to the center and down.', 'Repeat for your other leg.']::text[], ARRAY['Chair_Leg_Extended_Stretch/0.jpg', 'Chair_Leg_Extended_Stretch/1.jpg']::text[], 'chair leg extended stretch gian dui sau duoi chan tren ghe estiramiento de isquios con pierna en silla'),
  (NULL, 'Chair Lower Back Stretch', 'Giãn lưng dưới trên ghế', 'Chair Lower Back Stretch', 'Estiramiento lumbar en silla', 'back', 'other', 'timed', 'free_exercise_db', 'Chair_Lower_Back_Stretch', ARRAY['Sit upright on a chair.', 'Bend to one side with your arm over your head. You can hold onto the chair with your free hand.', 'Hold for 10 seconds, and repeat for your other side.']::text[], ARRAY['Chair_Lower_Back_Stretch/0.jpg', 'Chair_Lower_Back_Stretch/1.jpg']::text[], 'chair lower back stretch gian lung duoi tren ghe estiramiento lumbar en silla'),
  (NULL, 'Chair Squat', 'Chair Squat', 'Chair Squat', 'Sentadilla en silla', 'legs', 'machine', 'compound', 'free_exercise_db', 'Chair_Squat', ARRAY['To begin, first set the bar to a position that best matches your height. Once the bar is loaded, step under it and position it across the back of your shoulders.', 'Take the bar with your hands facing forward, unlock it and lift it off the rack by extending your legs.', 'Move your feet forward about 18 inches in front of the bar. Position your legs using a shoulder width stance with the toes slightly pointed out. Look forward at all times and maintain a neutral or slightly arched spine. This will be your starting position.', 'Slowly lower the bar by bending the knees as you maintain a straight posture with the head up. Continue down until the angle between the upper and lower leg breaks 90 degrees.', 'Begin to raise the bar as you exhale by pushing the floor with the heels of your feet, extending the knees and returning to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Chair_Squat/0.jpg', 'Chair_Squat/1.jpg']::text[], 'chair squat squat ghe sentadilla en silla'),
  (NULL, 'Chair Upper Body Stretch', 'Giãn thân trên với ghế', 'Chair Upper Body Stretch', 'Estiramiento de tren superior en silla', 'shoulders', 'other', 'timed', 'free_exercise_db', 'Chair_Upper_Body_Stretch', ARRAY['Sit on the edge of a chair, gripping the back of it.', 'Straighten your arms, keeping your back straight, and pull your upper body forward so you feel a stretch. Hold for 20-30 seconds.']::text[], ARRAY['Chair_Upper_Body_Stretch/0.jpg', 'Chair_Upper_Body_Stretch/1.jpg']::text[], 'chair upper body stretch gian than tren voi ghe estiramiento de tren superior en silla'),
  (NULL, 'Chest And Front Of Shoulder Stretch', 'Giãn ngực và vai trước', 'Chest And Front Of Shoulder Stretch', 'Estiramiento de pecho y hombro frontal', 'chest', 'other', 'timed', 'free_exercise_db', 'Chest_And_Front_Of_Shoulder_Stretch', ARRAY['Start off by standing with your legs together, holding a bodybar or a broomstick.', 'Take a slightly wider than shoulder width grip on the pole and hold it in front of you with your palms facing down.', 'Carefully lift the pole up and behind your head.']::text[], ARRAY['Chest_And_Front_Of_Shoulder_Stretch/0.jpg', 'Chest_And_Front_Of_Shoulder_Stretch/1.jpg']::text[], 'chest and front of shoulder stretch gian nguc va vai truoc estiramiento de pecho y hombro frontal'),
  (NULL, 'Chest Push from 3 point stance', 'Đẩy bóng tạ từ thế 3 điểm', 'Chest Push from 3 point stance', 'Empuje de pecho desde posición de 3 apoyos', 'chest', 'medicine ball', 'compound', 'free_exercise_db', 'Chest_Push_from_3_point_stance', ARRAY['Begin in a three point stance, squatted down with your back flat and one hand on the ground. Place the medicine ball directly in front of you.', 'To begin, take your first step as you pull the ball to your chest, positioning both hands to prepare for the throw.', 'As you execute the second step, explosively release the ball forward as hard as possible.']::text[], ARRAY['Chest_Push_from_3_point_stance/0.jpg', 'Chest_Push_from_3_point_stance/1.jpg']::text[], 'chest push from 3 point stance day bong ta tu the 3 diem empuje de pecho desde posicion de 3 apoyos'),
  (NULL, 'Chest Push (multiple response)', 'Đẩy bóng tạ ngực liên tục', 'Chest Push (multiple response)', 'Empuje de pecho continuo', 'chest', 'medicine ball', 'compound', 'free_exercise_db', 'Chest_Push_multiple_response', ARRAY['Begin in a kneeling position facing a wall or utilize a partner. Hold the ball with both hands tight into the chest.', 'Execute the pass by exploding forward and outward with the hips while pushing the ball as hard as possible.', 'Follow through by falling forward, catching yourself with your hands.', 'Immediately return to an upright position. Repeat for the desired number of repetitions.']::text[], ARRAY['Chest_Push_multiple_response/0.jpg', 'Chest_Push_multiple_response/1.jpg']::text[], 'chest push (multiple response) day bong ta nguc lien tuc empuje de pecho continuo'),
  (NULL, 'Chest Push (single response)', 'Đẩy bóng tạ ngực một lần', 'Chest Push (single response)', 'Empuje de pecho simple', 'chest', 'medicine ball', 'compound', 'free_exercise_db', 'Chest_Push_single_response', ARRAY['Begin in a kneeling position holding the medicine ball with both hands tightly into the chest.', 'Execute the pass by exploding forward and outward with the hips while pushing the ball as far as possible.', 'Follow through by falling forward, catching yourself with your hands.']::text[], ARRAY['Chest_Push_single_response/0.jpg', 'Chest_Push_single_response/1.jpg']::text[], 'chest push (single response) day bong ta nguc mot lan empuje de pecho simple'),
  (NULL, 'Chest Push with Run Release', 'Đẩy bóng tạ ngực rồi chạy', 'Chest Push with Run Release', 'Empuje de pecho con salida en carrera', 'chest', 'medicine ball', 'compound', 'free_exercise_db', 'Chest_Push_with_Run_Release', ARRAY['Begin in an athletic stance with the knees bent, hips back, and back flat. Hold the medicine ball near your legs. This will be your starting position.', 'While taking your first step draw the medicine ball into your chest.', 'As you take the second step, explosively push the ball forward, immediately sprinting for 10 yards after the release. If you are really fast, you can catch your own pass!']::text[], ARRAY['Chest_Push_with_Run_Release/0.jpg', 'Chest_Push_with_Run_Release/1.jpg']::text[], 'chest push with run release day bong ta nguc roi chay empuje de pecho con salida en carrera'),
  (NULL, 'Chest Stretch on Stability Ball', 'Giãn ngực trên bóng tập', 'Chest Stretch on Stability Ball', 'Estiramiento de pecho en fitball', 'chest', 'exercise ball', 'timed', 'free_exercise_db', 'Chest_Stretch_on_Stability_Ball', ARRAY['Get on your hands and knees next to an exercise ball.', 'Place your elbows on top of the ball, keeping your arm out to your side. This will be your starting position.', 'Lower your torso towards the floor, keeping your elbow on top of the ball. Hold the stretch for 20-30 seconds, and repeat with the other arm.']::text[], ARRAY['Chest_Stretch_on_Stability_Ball/0.jpg', 'Chest_Stretch_on_Stability_Ball/1.jpg']::text[], 'chest stretch on stability ball gian nguc tren bong tap estiramiento de pecho en fitball'),
  (NULL, 'Child''s Pose', 'Tư thế em bé', 'Child''s Pose', 'Postura del niño', 'back', 'other', 'timed', 'free_exercise_db', 'Childs_Pose', ARRAY['Get on your hands and knees, walk your hands in front of you.', 'Lower your buttocks down to sit on your heels. Let your arms drag along the floor as you sit back to stretch your entire spine.', 'Once you settle onto your heels, bring your hands next to your feet and relax. "breathe" into your back. Rest your forehead on the floor. Avoid this position if you have knee problems.']::text[], ARRAY['Childs_Pose/0.jpg', 'Childs_Pose/1.jpg']::text[], 'child''s pose tu the em be postura del nino'),
  (NULL, 'Chin-Up', 'Hít xà ngửa tay', 'Chin-Up', 'Dominadas supinas', 'back', 'bodyweight', 'bodyweight', 'free_exercise_db', 'Chin-Up', ARRAY['Grab the pull-up bar with the palms facing your torso and a grip closer than the shoulder width.', 'As you have both arms extended in front of you holding the bar at the chosen grip width, keep your torso as straight as possible while creating a curvature on your lower back and sticking your chest out. This is your starting position. Tip: Keeping the torso as straight as possible maximizes biceps stimulation while minimizing back involvement.', 'As you breathe out, pull your torso up until your head is around the level of the pull-up bar. Concentrate on using the biceps muscles in order to perform the movement. Keep the elbows close to your body. Tip: The upper torso should remain stationary as it moves through space and only the arms should move. The forearms should do no other work other than hold the bar.', 'After a second of squeezing the biceps in the contracted position, slowly lower your torso back to the starting position; when your arms are fully extended. Breathe in as you perform this portion of the movement.', 'Repeat this motion for the prescribed amount of repetitions.']::text[], ARRAY['Chin-Up/0.jpg', 'Chin-Up/1.jpg']::text[], 'chin-up hit xa ngua tay dominadas supinas'),
  (NULL, 'Chin To Chest Stretch', 'Giãn cổ cằm chạm ngực', 'Chin To Chest Stretch', 'Estiramiento barbilla al pecho', 'shoulders', 'other', 'timed', 'free_exercise_db', 'Chin_To_Chest_Stretch', ARRAY['Get into a seated position on the floor.', 'Place both hands at the rear of your head, fingers interlocked, thumbs pointing down and elbows pointing straight ahead. Slowly pull your head down to your chest. Hold for 20-30 seconds.']::text[], ARRAY['Chin_To_Chest_Stretch/0.jpg', 'Chin_To_Chest_Stretch/1.jpg']::text[], 'chin to chest stretch gian co cam cham nguc estiramiento barbilla al pecho'),
  (NULL, 'Circus Bell', 'Nâng chuông xiếc', 'Circus Bell', 'Campana de circo', 'shoulders', 'other', 'compound', 'free_exercise_db', 'Circus_Bell', ARRAY['The circus bell is an oversized dumbbell with a thick handle. Begin with the dumbbell between your feet, and grip the handle with both hands.', 'Clean the dumbbell by extending through your hips and knees to deliver the implement to the desired shoulder, letting go with the extra hand.', 'Ensure that you get one of the dumbbell heads behind the shoulder to keep from being thrown off balance. To raise it overhead, dip by flexing the knees, and the drive upwards as you extend the dumbbell overhead, leaning slightly away from it as you do so.', 'Carefully guide the bell back to the floor, keeping it under control as much as possible. It is best to perform this event on a thick rubber mat to prevent damage to the floor.']::text[], ARRAY['Circus_Bell/0.jpg', 'Circus_Bell/1.jpg']::text[], 'circus bell nang chuong xiec campana de circo'),
  (NULL, 'Clean', 'Clean', 'Clean', 'Cargada', 'legs', 'barbell', 'compound', 'free_exercise_db', 'Clean', ARRAY['With a barbell on the floor close to the shins, take an overhand (or hook) grip just outside the legs. Lower your hips with the weight focused on the heels, back straight, head facing forward, chest up, with your shoulders just in front of the bar. This will be your starting position.', '', 'Begin the first pull by driving through the heels, extending your knees. Your back angle should stay the same, and your arms should remain straight. Move the weight with control as you continue to above the knees.', 'Next comes the second pull, the main source of acceleration for the clean. As the bar approaches the mid-thigh position, begin extending through the hips. In a jumping motion, accelerate by extending the hips, knees, and ankles, using speed to move the bar upward. There should be no need to actively pull through the arms to accelerate the weight; at the end of the second pull, the body should be fully extended, leaning slightly back, with the arms still extended.', 'As full extension is achieved, transition into the third pull by aggressively shrugging and flexing the arms with the elbows up and out. At peak extension, aggressively pull yourself down, rotating your elbows under the bar as you do so. Receive the bar in a front squat position, the depth of which is dependent upon the height of the bar at the end of the third pull. The bar should be racked onto the protracted shoulders, lightly touching the throat with the hands relaxed. Continue to descend to the bottom squat position, which will help in the recovery.', 'Immediately recover by driving through the heels, keeping the torso upright and elbows up. Continue until you have risen to a standing position.']::text[], ARRAY['Clean/0.jpg', 'Clean/1.jpg']::text[], 'clean clean cargada'),
  (NULL, 'Clean Deadlift', 'Clean Deadlift', 'Clean Deadlift', 'Peso muerto de cargada', 'legs', 'barbell', 'compound', 'free_exercise_db', 'Clean_Deadlift', ARRAY['Begin standing with a barbell close to your shins. Your feet should be directly under your hips with your feet turned out slightly. Grip the bar with a double overhand grip or hook grip, about shoulder width apart. Squat down to the bar. Your spine should be in full extension, with a back angle that places your shoulders in front of the bar and your back as vertical as possible.', 'Begin by driving through the floor through the front of your heels. As the bar travels upward, maintain a constant back angle. Flare your knees out to the side to help keep them out of the bar''s path.', 'After the bar crosses the knees, complete the lift by driving the hips into the bar until your hips and knees are extended.']::text[], ARRAY['Clean_Deadlift/0.jpg', 'Clean_Deadlift/1.jpg']::text[], 'clean deadlift deadlift kieu clean peso muerto de cargada'),
  (NULL, 'Clean Pull', 'Clean Pull', 'Clean Pull', 'Tirón de cargada', 'legs', 'barbell', 'compound', 'free_exercise_db', 'Clean_Pull', ARRAY['With a barbell on the floor close to the shins, take an overhand or hook grip just outside the legs. Lower your hips with the weight focused on the heels, back straight, head facing forward, chest up, with your shoulders just in front of the bar. This will be your starting position.', 'Begin the first pull by driving through the heels, extending your knees. Your back angle should stay the same, and your arms should remain straight and elbows out. Move the weight with control as you continue to above the knees.', 'Next comes the second pull, the main source of acceleration for the clean. As the bar approaches the mid-thigh position, begin extending through the hips. In a jumping motion, accelerate by extending the hips, knees, and ankles, using speed to move the bar upward. There should be no need to actively pull through the arms to accelerate the weight; at the end of the second pull, the body should be fully extended, leaning slightly back, with the arms still extended. Full extension should be violent and abrupt, and ensure that you do not prolong the extension for longer than necessary.']::text[], ARRAY['Clean_Pull/0.jpg', 'Clean_Pull/1.jpg']::text[], 'clean pull keo clean tiron de cargada'),
  (NULL, 'Clean Shrug', 'Clean Shrug', 'Clean Shrug', 'Encogimiento de cargada', 'shoulders', 'barbell', 'compound', 'free_exercise_db', 'Clean_Shrug', ARRAY['Begin with a shoulder width, double overhand or hook grip, with the bar hanging at the mid thigh position. Your back should be straight and inclined slightly forward.', 'Shrug your shoulders towards your ears. While this exercise can usually by loaded with heavier weight than a clean, avoid overloading to the point that the execution slows down.']::text[], ARRAY['Clean_Shrug/0.jpg', 'Clean_Shrug/1.jpg']::text[], 'clean shrug nhun vai kieu clean encogimiento de cargada'),
  (NULL, 'Clean and Jerk', 'Clean and Jerk', 'Clean and Jerk', 'Dos tiempos', 'shoulders', 'barbell', 'compound', 'free_exercise_db', 'Clean_and_Jerk', ARRAY['With a barbell on the floor close to the shins, take an overhand or hook grip just outside the legs. Lower your hips with the weight focused on the heels, back straight, head facing forward, chest up, with your shoulders just in front of the bar. This will be your starting position.', 'Begin the first pull by driving through the heels, extending your knees. Your back angle should stay the same, and your arms should remain straight. Move the weight with control as you continue to above the knees.', 'Next comes the second pull, the main source of acceleration for the clean. As the bar approaches the mid-thigh position, begin extending through the hips. In a jumping motion, accelerate by extending the hips, knees, and ankles, using speed to move the bar upward. There should be no need to actively pull through the arms to accelerate the weight; at the end of the second pull, the body should be fully extended, leaning slightly back, with the arms still extended.', 'As full extension is achieved, transition into the third pull by aggressively shrugging and flexing the arms with the elbows up and out. At peak extension, aggressively pull yourself down, rotating your elbows under the bar as you do so. Receive the bar in a front squat position, the depth of which is dependent upon the height of the bar at the end of the third pull. The bar should be racked onto the protracted shoulders, lightly touching the throat with the hands relaxed. Continue to descend to the bottom squat position, which will help in the recovery.', 'Immediately recover by driving through the heels, keeping the torso upright and elbows up. Continue until you have risen to a standing position.', 'The second phase is the jerk, which raises the weight overhead. Standing with the weight racked on the front of the shoulders, begin with the dip. With your feet directly under your hips, flex the knees without moving the hips backward. Go down only slightly, and reverse direction as powerfully as possible.', 'Drive through the heels create as much speed and force as possible, and be sure to move your head out of the way as the bar leaves the shoulders.', 'At this moment as the feet leave the floor, the feet must be placed into the receiving position as quickly as possible. In the brief moment the feet are not actively driving against the platform, the athletes effort to push the bar up will drive them down. The feet should be split, with one foot forward, and one foot back. Receive the bar with the arms locked out overhead. Return to a standing position.']::text[], ARRAY['Clean_and_Jerk/0.jpg', 'Clean_and_Jerk/1.jpg']::text[], 'clean and jerk clean and jerk dos tiempos'),
  (NULL, 'Clean and Press', 'Clean and Press', 'Clean and Press', 'Cargada y press', 'shoulders', 'barbell', 'compound', 'free_exercise_db', 'Clean_and_Press', ARRAY['Assume a shoulder-width stance, with knees inside the arms. Now while keeping the back flat, bend at the knees and hips so that you can grab the bar with the arms fully extended and a pronated grip that is slightly wider than shoulder width. Point the elbows out to sides. The bar should be close to the shins. Position the shoulders over or slightly ahead of the bar. Establish a flat back posture. This will be your starting position.', 'Begin to pull the bar by extending the knees. Move your hips forward and raise the shoulders at the same rate while keeping the angle of the back constant; continue to lift the bar straight up while keeping it close to your body.', 'As the bar passes the knee, extend at the ankles, knees, and hips forcefully, similar to a jumping motion. As you do so, continue to guide the bar with your hands, shrugging your shoulders and using the momentum from your movement to pull the bar as high as possible. The bar should travel close to your body, and you should keep your elbows out.', 'At maximum elevation, your feet should clear the floor and you should start to pull yourself under the bar. The mechanics of this could change slightly, depending on the weight used. You should descend into a squatting position as you pull yourself under the bar.', 'As the bar hits terminal height, rotate your elbows around and under the bar. Rack the bar across the front of the shoulders while keeping the torso erect and flexing the hips and knees to absorb the weight of the bar.', 'Stand to full height, holding the bar in the clean position.', 'Without moving your feet, press the bar overhead as you exhale. Lower the bar under control .']::text[], ARRAY['Clean_and_Press/0.jpg', 'Clean_and_Press/1.jpg']::text[], 'clean and press clean and press cargada y press'),
  (NULL, 'Clean from Blocks', 'Clean from Blocks', 'Clean from Blocks', 'Cargada desde bloques', 'legs', 'barbell', 'compound', 'free_exercise_db', 'Clean_from_Blocks', ARRAY['With a barbell on boxes or stands of the desired height, take an overhand or hook grip just outside the legs. Lower your hips with the weight focused on the heels, back straight, head facing forward, chest up, with your shoulders just in front of the bar. This will be your starting position.', 'Begin the first pull by driving through the heels, extending your knees. Your back angle should stay the same, and your arms should remain straight with the elbows pointed out.', 'As full extension is achieved, transition into the receiving position by aggressively shrugging and flexing the arms with the elbows up and out. Aggressively pull yourself down, rotating your elbows under the bar as you do so. Receive the bar in a front squat position, the depth of which is dependent upon the height of the bar at the end of the third pull. The bar should be racked onto the protracted shoulders, lightly touching the throat with the hands relaxed. Continue to descend to the bottom squat position, which will help in the recovery.', 'Immediately recover by driving through the heels, keeping the torso upright and elbows up. Continue until you have risen to a standing position. Return the weight to the boxes for the next rep.']::text[], ARRAY['Clean_from_Blocks/0.jpg', 'Clean_from_Blocks/1.jpg']::text[], 'clean from blocks clean tu buc cargada desde bloques'),
  (NULL, 'Clock Push-Up', 'Hít đất xoay vòng', 'Clock Push-Up', 'Flexiones de reloj', 'chest', 'bodyweight', 'bodyweight', 'free_exercise_db', 'Clock_Push-Up', ARRAY['Move into a prone position on the floor, supporting your weight on your hands and toes.', 'Your arms should be fully extended with the hands around shoulder width. Keep your body straight throughout the movement. This will be your starting position.', 'Descend by flexing at the elbow, lowering your chest toward the ground.', 'At the bottom, reverse the motion by pushing yourself up through elbow extension as quickly as possible until you are air borne. Aim to "jump" 12-18 inches to one side.', 'As you accelerate up, move your outside foot away from your direction of travel. Leaving the ground, shift your body about 30 degrees for the next repetition.', 'Return to the starting position and repeat the exercise, working all the way around until you are back where you started.']::text[], ARRAY['Clock_Push-Up/0.jpg', 'Clock_Push-Up/1.jpg']::text[], 'clock push-up hit dat xoay vong flexiones de reloj'),
  (NULL, 'Close-Grip Barbell Bench Press', 'Close-Grip Barbell Bench Press', 'Close-Grip Barbell Bench Press', 'Press de banca con barra agarre cerrado', 'triceps', 'barbell', 'compound', 'free_exercise_db', 'Close-Grip_Barbell_Bench_Press', ARRAY['Lie back on a flat bench. Using a close grip (around shoulder width), lift the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.', 'As you breathe in, come down slowly until you feel the bar on your middle chest. Tip: Make sure that - as opposed to a regular bench press - you keep the elbows close to the torso at all times in order to maximize triceps involvement.', 'After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your triceps muscles. Lock your arms in the contracted position, hold for a second and then start coming down slowly again. Tip: It should take at least twice as long to go down than to come up.', 'Repeat the movement for the prescribed amount of repetitions.', 'When you are done, place the bar back in the rack.']::text[], ARRAY['Close-Grip_Barbell_Bench_Press/0.jpg', 'Close-Grip_Barbell_Bench_Press/1.jpg']::text[], 'close-grip barbell bench press day nguc ta don nam hep press de banca con barra agarre cerrado'),
  (NULL, 'Close-Grip Dumbbell Press', 'Đẩy tạ đơn nắm hẹp', 'Close-Grip Dumbbell Press', 'Press con mancuernas agarre cerrado', 'triceps', 'dumbbell', 'compound', 'free_exercise_db', 'Close-Grip_Dumbbell_Press', ARRAY['Place a dumbbell standing up on a flat bench.', 'Ensuring that the dumbbell stays securely placed at the top of the bench, lie perpendicular to the bench with only your shoulders lying on the surface. Hips should be below the bench and your legs bent with your feet firmly on the floor.', 'Grasp the dumbbell with both hands and hold it straight over your chest at arm''s length. Both palms should be pressing against the underside of the sides of the dumbbell. This will be your starting position.', 'Initiate the movement by lowering the dumbbell to your chest.', 'Return to the starting position by extending the elbows.']::text[], ARRAY['Close-Grip_Dumbbell_Press/0.jpg', 'Close-Grip_Dumbbell_Press/1.jpg']::text[], 'close-grip dumbbell press day ta don nam hep press con mancuernas agarre cerrado'),
  (NULL, 'Close-Grip EZ-Bar Curl with Band', 'Close-Grip EZ-Bar Curl with Band', 'Close-Grip EZ-Bar Curl with Band', 'Curl con barra EZ agarre cerrado y banda', 'biceps', 'ez bar', 'isolation', 'free_exercise_db', 'Close-Grip_EZ-Bar_Curl_with_Band', ARRAY['Attach a band to each end of the bar. Take the bar, placing a foot on the middle of the band. Stand upright with a narrow, supinated grip on the EZ bar. The elbows should be close to the torso. This will be your starting position.', 'While keeping the upper arms in place, flex the elbows to execute the curl. Exhale as the weight is lifted.', 'Continue the movement until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a second and squeeze the biceps hard.', 'Slowly begin to bring the bar back to starting position as your breathe in.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Close-Grip_EZ-Bar_Curl_with_Band/0.jpg', 'Close-Grip_EZ-Bar_Curl_with_Band/1.jpg']::text[], 'close-grip ez-bar curl with band cuon thanh ez nam hep voi day khang luc curl con barra ez agarre cerrado y banda'),
  (NULL, 'Close-Grip EZ-Bar Press', 'Đẩy thanh EZ nắm hẹp', 'Close-Grip EZ-Bar Press', 'Press con barra EZ agarre cerrado', 'triceps', 'ez bar', 'compound', 'free_exercise_db', 'Close-Grip_EZ-Bar_Press', ARRAY['Lie on a flat bench with an EZ bar loaded to an appropriate weight.', 'Using a narrow grip lift the bar and hold it straight over your torso with your elbows in. The arms should be perpendicular to the floor. This will be your starting position.', 'Now lower the bar down to your lower chest as you breathe in. Keep the elbows in as you perform this movement.', 'Using the triceps to push the bar back up, press it back to the starting position by extending the elbows as you exhale.', 'Repeat.']::text[], ARRAY['Close-Grip_EZ-Bar_Press/0.jpg', 'Close-Grip_EZ-Bar_Press/1.jpg']::text[], 'close-grip ez-bar press day thanh ez nam hep press con barra ez agarre cerrado'),
  (NULL, 'Close-Grip EZ Bar Curl', 'Close-Grip EZ Bar Curl', 'Close-Grip EZ Bar Curl', 'Curl con barra EZ agarre cerrado', 'biceps', 'barbell', 'isolation', 'free_exercise_db', 'Close-Grip_EZ_Bar_Curl', ARRAY['Stand up with your torso upright while holding an E-Z Curl Bar at the closer inner handle. The palm of your hands should be facing forward and they should be slightly tilted inwards due to the shape of the bar. The elbows should be close to the torso. This will be your starting position.', 'While holding the upper arms stationary, curl the weights forward while contracting the biceps as you breathe out. Tip: Only the forearms should move.', 'Continue the movement until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a second and squeeze the biceps hard.', 'Slowly begin to bring the bar back to starting position as your breathe in.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Close-Grip_EZ_Bar_Curl/0.jpg', 'Close-Grip_EZ_Bar_Curl/1.jpg']::text[], 'close-grip ez bar curl cuon thanh ez nam hep curl con barra ez agarre cerrado'),
  (NULL, 'Close-Grip Front Lat Pulldown', 'Close-Grip Front Lat Pulldown', 'Close-Grip Front Lat Pulldown', 'Jalón al pecho agarre cerrado', 'back', 'cable', 'compound', 'free_exercise_db', 'Close-Grip_Front_Lat_Pulldown', ARRAY['Sit down on a pull-down machine with a wide bar attached to the top pulley. Make sure that you adjust the knee pad of the machine to fit your height. These pads will prevent your body from being raised by the resistance attached to the bar.', 'Grab the bar with the palms facing forward using the prescribed grip. Note on grips: For a wide grip, your hands need to be spaced out at a distance wider than your shoulder width. For a medium grip, your hands need to be spaced out at a distance equal to your shoulder width and for a close grip at a distance smaller than your shoulder width.', 'As you have both arms extended in front of you - while holding the bar at the chosen grip width - bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.', 'As you breathe out, bring the bar down until it touches your upper chest by drawing the shoulders and the upper arms down and back. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary (only the arms should move). The forearms should do no other work except for holding the bar; therefore do not try to pull the bar down using the forearms.', 'After a second in the contracted position, while squeezing your shoulder blades together, slowly raise the bar back to the starting position when your arms are fully extended and the lats are fully stretched. Inhale during this portion of the movement.', '6. Repeat this motion for the prescribed amount of repetitions.']::text[], ARRAY['Close-Grip_Front_Lat_Pulldown/0.jpg', 'Close-Grip_Front_Lat_Pulldown/1.jpg']::text[], 'close-grip front lat pulldown keo xa xuong phia truoc nam hep jalon al pecho agarre cerrado'),
  (NULL, 'Close-Grip Push-Up off of a Dumbbell', 'Hít đất nắm hẹp trên tạ đơn', 'Close-Grip Push-Up off of a Dumbbell', 'Flexiones agarre cerrado sobre mancuerna', 'triceps', 'bodyweight', 'bodyweight', 'free_exercise_db', 'Close-Grip_Push-Up_off_of_a_Dumbbell', ARRAY['Lie on the floor and place your hands on an upright dumbbell. Supporting your weight on your toes and hands, keep your torso rigid and your elbows in with your arms straight. This will be your starting position.', 'Lower your body, allowing the elbows to flex while you inhale. Keep your body straight, not allowing your hips to rise or sag.', 'Press yourself back up to the starting position by extending the elbows. Breathe out as you perform this step.', 'After a pause at the contracted position, repeat the movement for the prescribed amount of repetitions.']::text[], ARRAY['Close-Grip_Push-Up_off_of_a_Dumbbell/0.jpg', 'Close-Grip_Push-Up_off_of_a_Dumbbell/1.jpg']::text[], 'close-grip push-up off of a dumbbell hit dat nam hep tren ta don flexiones agarre cerrado sobre mancuerna'),
  (NULL, 'Close-Grip Standing Barbell Curl', 'Close-Grip Standing Barbell Curl', 'Close-Grip Standing Barbell Curl', 'Curl de pie con barra agarre cerrado', 'biceps', 'barbell', 'isolation', 'free_exercise_db', 'Close-Grip_Standing_Barbell_Curl', ARRAY['Hold a barbell with both hands, palms up and a few inches apart.', 'Stand with your torso straight and your head up. Your feet should be about shoulder width and your elbows close to your torso. This will be your starting position. Tip: You will keep your upper arms and elbows stationary throughout the movement.', 'Curl the bar up in a semicircular motion until the forearms touch your biceps. Exhale as you perform this portion of the movement and contract your biceps hard for a second at the top. Tip: Avoid bending the back or using swinging motions as you lift the weight. Only the forearms should move.', 'Slowly go back down to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Close-Grip_Standing_Barbell_Curl/0.jpg', 'Close-Grip_Standing_Barbell_Curl/1.jpg']::text[], 'close-grip standing barbell curl cuon ta don dung nam hep curl de pie con barra agarre cerrado'),
  (NULL, 'Cocoons', 'Gập bụng con kén', 'Cocoons', 'Capullos', 'abs', 'bodyweight', 'bodyweight', 'free_exercise_db', 'Cocoons', ARRAY['Begin by lying on your back on the ground. Your legs should be straight and your arms extended behind your head. This will be your starting position.', 'To perform the movement, tuck the knees toward your chest, rotating your pelvis to lift your glutes from the floor. As you do so, flex the spine, bringing your arms back over your head to perform a simultaneous crunch motion.', 'After a brief pause, return to the starting position.']::text[], ARRAY['Cocoons/0.jpg', 'Cocoons/1.jpg']::text[], 'cocoons gap bung con ken capullos'),
  (NULL, 'Conan''s Wheel', 'Bánh xe Conan', 'Conan''s Wheel', 'Rueda de Conan', 'legs', 'other', 'compound', 'free_exercise_db', 'Conans_Wheel', ARRAY['With the weight loaded, take a zurcher hold on the end of the implement. Place the bar in the crook of the elbow and hold onto your wrist. Try to keep the weight off of the forearms.', 'Begin by lifting the weight from the ground. Keep a tight, upright posture as you being to walk, taking short, fast steps. Look up and away as you turn in a circle. Do not hold your breath during the event. Continue walking until you complete one or more complete turns.']::text[], ARRAY['Conans_Wheel/0.jpg', 'Conans_Wheel/1.jpg']::text[], 'conan''s wheel banh xe conan rueda de conan'),
  (NULL, 'Concentration Curls', 'Concentration Curls', 'Concentration Curls', 'Curl concentrado', 'biceps', 'dumbbell', 'isolation', 'free_exercise_db', 'Concentration_Curls', ARRAY['Sit down on a flat bench with one dumbbell in front of you between your legs. Your legs should be spread with your knees bent and feet on the floor.', 'Use your right arm to pick the dumbbell up. Place the back of your right upper arm on the top of your inner right thigh. Rotate the palm of your hand until it is facing forward away from your thigh. Tip: Your arm should be extended and the dumbbell should be above the floor. This will be your starting position.', 'While holding the upper arm stationary, curl the weights forward while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the dumbbells are at shoulder level. Tip: At the top of the movement make sure that the little finger of your arm is higher than your thumb. This guarantees a good contraction. Hold the contracted position for a second as you squeeze the biceps.', 'Slowly begin to bring the dumbbells back to starting position as your breathe in. Caution: Avoid swinging motions at any time.', 'Repeat for the recommended amount of repetitions. Then repeat the movement with the left arm.']::text[], ARRAY['Concentration_Curls/0.jpg', 'Concentration_Curls/1.jpg']::text[], 'concentration curls cuon tay truoc tap trung curl concentrado'),
  (NULL, 'Cross-Body Crunch', 'Cross-Body Crunch', 'Cross-Body Crunch', 'Crunch cruzado', 'abs', 'bodyweight', 'bodyweight', 'free_exercise_db', 'Cross-Body_Crunch', ARRAY['Lie flat on your back and bend your knees about 60 degrees.', 'Keep your feet flat on the floor and place your hands loosely behind your head. This will be your starting position.', 'Now curl up and bring your right elbow and shoulder across your body while bring your left knee in toward your left shoulder at the same time. Reach with your elbow and try to touch your knee. Exhale as you perform this movement. Tip: Try to bring your shoulder up towards your knee rather than just your elbow and remember that the key is to contract the abs as you perform the movement; not just to move the elbow.', 'Now go back down to the starting position as you inhale and repeat with the left elbow and the right knee.', 'Continue alternating in this manner until all prescribed repetitions are done.']::text[], ARRAY['Cross-Body_Crunch/0.jpg', 'Cross-Body_Crunch/1.jpg']::text[], 'cross-body crunch gap bung cheo nguoi crunch cruzado'),
  (NULL, 'Cross Body Hammer Curl', 'Cross Body Hammer Curl', 'Cross Body Hammer Curl', 'Curl martillo cruzado', 'biceps', 'dumbbell', 'isolation', 'free_exercise_db', 'Cross_Body_Hammer_Curl', ARRAY['Stand up straight with a dumbbell in each hand. Your hands should be down at your side with your palms facing in.', 'While keeping your palms facing in and without twisting your arm, curl the dumbbell of the right arm up towards your left shoulder as you exhale. Touch the top of the dumbbell to your shoulder and hold the contraction for a second.', 'Slowly lower the dumbbell along the same path as you inhale and then repeat the same movement for the left arm.', 'Continue alternating in this fashion until the recommended amount of repetitions is performed for each arm.']::text[], ARRAY['Cross_Body_Hammer_Curl/0.jpg', 'Cross_Body_Hammer_Curl/1.jpg']::text[], 'cross body hammer curl cuon bua cheo nguoi curl martillo cruzado'),
  (NULL, 'Cross Over - With Bands', 'Ép ngực chéo dây kháng lực', 'Cross Over - With Bands', 'Cruce con bandas', 'chest', 'band', 'compound', 'free_exercise_db', 'Cross_Over_-_With_Bands', ARRAY['Secure an exercise band around a stationary post.', 'While facing away from the post, grab the handles on both ends of the band and step forward enough to create tension on the band.', 'Raise your arms to the sides, parallel to the floor, perpendicular to your torso (your torso and the arms should resemble the letter "T") and with the palms facing forward. Have them extended with a slight bend at the elbows. This will be your starting position.', 'While keeping your arms straight, bring them across your chest in a semicircular motion to the front as you exhale and flex your pecs. Hold the contraction for a second.', 'Slowly return to the starting position as you inhale.', 'Perform for the recommended amount of repetitions.']::text[], ARRAY['Cross_Over_-_With_Bands/0.jpg', 'Cross_Over_-_With_Bands/1.jpg']::text[], 'cross over - with bands ep nguc cheo day khang luc cruce con bandas'),
  (NULL, 'Crossover Reverse Lunge', 'Crossover Reverse Lunge', 'Crossover Reverse Lunge', 'Zancada inversa cruzada', 'back', 'other', 'timed', 'free_exercise_db', 'Crossover_Reverse_Lunge', ARRAY['Stand with your feet shoulder width apart. This will be your starting position.', 'Perform a rear lunge by stepping back with one foot and flexing the hips and front knee. As you do so, rotate your torso across the front leg.', 'After a brief pause, return to the starting position and repeat on the other side, continuing in an alternating fashion.']::text[], ARRAY['Crossover_Reverse_Lunge/0.jpg', 'Crossover_Reverse_Lunge/1.jpg']::text[], 'crossover reverse lunge chung chan lui bat cheo zancada inversa cruzada'),
  (NULL, 'Crucifix', 'Giữ tạ chữ thập', 'Crucifix', 'Crucifijo', 'shoulders', 'other', 'isolation', 'free_exercise_db', 'Crucifix', ARRAY['In the crucifix, you statically hold weights out to the side for time. While the event can be practiced using dumbbells, it is best to practice with one of the various implements used, such as axes and hammers, as it feels different.', 'Begin standing, and raise your arms out to the side holding the implements. Your arms should be parallel to the ground. In competition, judges or sensors are used to let you know when you break parallel. Hold for as long as you can. Typically, the weights should be heavy enough that you fail in 30-60 seconds.']::text[], ARRAY['Crucifix/0.jpg', 'Crucifix/1.jpg']::text[], 'crucifix giu ta chu thap crucifijo'),
  (NULL, 'Crunch - Hands Overhead', 'Crunch - Hands Overhead', 'Crunch - Hands Overhead', 'Crunch con brazos sobre la cabeza', 'abs', 'bodyweight', 'bodyweight', 'free_exercise_db', 'Crunch_-_Hands_Overhead', ARRAY['Lie on the floor with your back flat and knees bent with around a 60-degree angle between the hamstrings and the calves.', 'Keep your feet flat on the floor and stretch your arms overhead with your palms crossed. This will be your starting position.', 'Curl your upper body forward and bring your shoulder blades just off the floor. At all times, keep your arms aligned with your head, neck and shoulder. Don''t move them forward from that position. Exhale as you perform this portion of the movement and hold the contraction for a second.', 'Slowly lower down to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Crunch_-_Hands_Overhead/0.jpg', 'Crunch_-_Hands_Overhead/1.jpg']::text[], 'crunch - hands overhead gap bung tay qua dau crunch con brazos sobre la cabeza'),
  (NULL, 'Crunch - Legs On Exercise Ball', 'Crunch - Legs On Exercise Ball', 'Crunch - Legs On Exercise Ball', 'Crunch con piernas sobre fitball', 'abs', 'bodyweight', 'bodyweight', 'free_exercise_db', 'Crunch_-_Legs_On_Exercise_Ball', ARRAY['Lie flat on your back with your feet resting on an exercise ball and your knees bent at a 90 degree angle.', 'Place your feet three to four inches apart and point your toes inward so they touch.', 'Place your hands lightly on either side of your head keeping your elbows in. Tip: Don''t lock your fingers behind your head.', 'Push the small of your back down in the floor in order to better isolate your abdominal muscles. This will be your starting position.', 'Begin to roll your shoulders off the floor and continue to push down as hard as you can with your lower back. Your shoulders should come up off the floor only about four inches, and your lower back should remain on the floor. Breathe out as you execute this portion of the movement. Squeeze your abdominals hard at the top of the contraction and hold for a second. Tip: Focus on a slow, controlled movement. Refrain from using momentum at any time.', 'Slowly go back down to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Crunch_-_Legs_On_Exercise_Ball/0.jpg', 'Crunch_-_Legs_On_Exercise_Ball/1.jpg']::text[], 'crunch - legs on exercise ball gap bung chan gac bong tap crunch con piernas sobre fitball'),
  (NULL, 'Crunches', 'Crunches', 'Crunches', 'Abdominales', 'abs', 'bodyweight', 'bodyweight', 'free_exercise_db', 'Crunches', ARRAY['Lie flat on your back with your feet flat on the ground, or resting on a bench with your knees bent at a 90 degree angle. If you are resting your feet on a bench, place them three to four inches apart and point your toes inward so they touch.', 'Now place your hands lightly on either side of your head keeping your elbows in. Tip: Don''t lock your fingers behind your head.', 'While pushing the small of your back down in the floor to better isolate your abdominal muscles, begin to roll your shoulders off the floor.', 'Continue to push down as hard as you can with your lower back as you contract your abdominals and exhale. Your shoulders should come up off the floor only about four inches, and your lower back should remain on the floor. At the top of the movement, contract your abdominals hard and keep the contraction for a second. Tip: Focus on slow, controlled movement - don''t cheat yourself by using momentum.', 'After the one second contraction, begin to come down slowly again to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Crunches/0.jpg', 'Crunches/1.jpg']::text[], 'crunches gap bung abdominales'),
  (NULL, 'Cuban Press', 'Đẩy vai kiểu Cuba', 'Cuban Press', 'Press cubano', 'shoulders', 'dumbbell', 'compound', 'free_exercise_db', 'Cuban_Press', ARRAY['Take a dumbbell in each hand with a pronated grip in a standing position. Raise your upper arms so that they are parallel to the floor, allowing your lower arms to hang in the "scarecrow" position. This will be your starting position.', 'To initiate the movement, externally rotate the shoulders to move the upper arm 180 degrees. Keep the upper arms in place, rotating the upper arms until the wrists are directly above the elbows, the forearms perpendicular to the floor.', 'Now press the dumbbells by extending at the elbows, straightening your arms overhead.', 'Return to the starting position as you breathe in by reversing the steps.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Cuban_Press/0.jpg', 'Cuban_Press/1.jpg']::text[], 'cuban press day vai kieu cuba press cubano'),
  (NULL, 'Dancer''s Stretch', 'Giãn cơ tư thế vũ công', 'Dancer''s Stretch', 'Estiramiento de bailarín', 'back', 'other', 'timed', 'free_exercise_db', 'Dancers_Stretch', ARRAY['Sit up on the floor.', 'Cross your right leg over your left, keeping the knee bent. Your left leg is straight and down on the floor.', 'Place your left arm on your right leg and your right hand on the floor.', 'Rotate your upper body to the right, and hold for 10-20 seconds. Switch sides.']::text[], ARRAY['Dancers_Stretch/0.jpg', 'Dancers_Stretch/1.jpg']::text[], 'dancer''s stretch gian co tu the vu cong estiramiento de bailarin'),
  (NULL, 'Dead Bug', 'Bọ chết (dead bug)', 'Dead Bug', 'Bicho muerto', 'abs', 'bodyweight', 'bodyweight', 'free_exercise_db', 'Dead_Bug', ARRAY['Begin lying on your back with your hands extended above you toward the ceiling.', 'Bring your feet, knees, and hips up to 90 degrees.', 'Exhale hard to bring your ribcage down and flatten your back onto the floor, rotating your pelvis up and squeezing your glutes. Hold this position throughout the movement. This will be your starting position.', 'Initiate the exercise by extending one leg, straightening the knee and hip to bring the leg just above the ground.', 'Maintain the position of your lumbar and pelvis as you perform the movement, as your back is going to want to arch.', 'Stay tight and return the working leg to the starting position.', 'Repeat on the opposite side, alternating until the set is complete.']::text[], ARRAY['Dead_Bug/0.jpg', 'Dead_Bug/1.jpg']::text[], 'dead bug bo chet (dead bug) bicho muerto'),
  (NULL, 'Deadlift with Bands', 'Deadlift with Bands', 'Deadlift with Bands', 'Peso muerto con bandas', 'back', 'barbell', 'compound', 'free_exercise_db', 'Deadlift_with_Bands', ARRAY['To deadlift with short bands, simply loop them over the bar before you start, and step into them to set up. For long bands, they will need to be anchored to a secure base, such as heavy dumbbells or a rack.', 'With your feet, and your grip set, take a big breath and then lower your hips and bend the knees until your shins contact the bar. Look forward with your head, keep your chest up and your back arched, and begin driving through the heels to move the weight upward. After the bar passes the knees, aggressively pull the bar back, pulling your shoulder blades together as you drive your hips forward into the bar.', 'Lower the bar by bending at the hips and guiding it to the floor.']::text[], ARRAY['Deadlift_with_Bands/0.jpg', 'Deadlift_with_Bands/1.jpg']::text[], 'deadlift with bands deadlift day khang luc peso muerto con bandas'),
  (NULL, 'Deadlift with Chains', 'Deadlift with Chains', 'Deadlift with Chains', 'Peso muerto con cadenas', 'back', 'barbell', 'compound', 'free_exercise_db', 'Deadlift_with_Chains', ARRAY['You can attach the chains to the sleeves of the bar, or just drape the middle over the bar so there is a greater weight increase as you lift.', 'Approach the bar so that it is centered over your feet. You feet should be about hip width apart. Bend at the hip to grip the bar at shoulder width, allowing your shoulder blades to protract. Typically, you would use an overhand grip or an over/under grip on heavier sets. With your feet, and your grip set, take a big breath and then lower your hips and bend the knees until your shins contact the bar.', 'Look forward with your head, keep your chest up and your back arched, and begin driving through the heels to move the weight upward. After the bar passes the knees, aggressively pull the bar back, pulling your shoulder blades together as you drive your hips forward into the bar.', 'Lower the bar by bending at the hips and guiding it to the floor.']::text[], ARRAY['Deadlift_with_Chains/0.jpg', 'Deadlift_with_Chains/1.jpg']::text[], 'deadlift with chains deadlift co xich peso muerto con cadenas'),
  (NULL, 'Decline Barbell Bench Press', 'Decline Barbell Bench Press', 'Decline Barbell Bench Press', 'Press declinado con barra', 'chest', 'barbell', 'compound', 'free_exercise_db', 'Decline_Barbell_Bench_Press', ARRAY['Secure your legs at the end of the decline bench and slowly lay down on the bench.', 'Using a medium width grip (a grip that creates a 90-degree angle in the middle of the movement between the forearms and the upper arms), lift the bar from the rack and hold it straight over you with your arms locked. The arms should be perpendicular to the floor. This will be your starting position. Tip: In order to protect your rotator cuff, it is best if you have a spotter help you lift the barbell off the rack.', 'As you breathe in, come down slowly until you feel the bar on your lower chest.', 'After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles. Lock your arms and squeeze your chest in the contracted position, hold for a second and then start coming down slowly again. Tip: It should take at least twice as long to go down than to come up).', 'Repeat the movement for the prescribed amount of repetitions.', 'When you are done, place the bar back in the rack.']::text[], ARRAY['Decline_Barbell_Bench_Press/0.jpg', 'Decline_Barbell_Bench_Press/1.jpg']::text[], 'decline barbell bench press day nguc doc xuong ta don press declinado con barra'),
  (NULL, 'Decline Close-Grip Bench To Skull Crusher', 'Decline Close-Grip Bench To Skull Crusher', 'Decline Close-Grip Bench To Skull Crusher', 'Press declinado agarre cerrado a rompecráneos', 'triceps', 'barbell', 'compound', 'free_exercise_db', 'Decline_Close-Grip_Bench_To_Skull_Crusher', ARRAY['Secure your legs at the end of the decline bench and slowly lay down on the bench.', 'Using a close grip (a grip that is slightly less than shoulder width), lift the bar from the rack and hold it straight over you with your arms locked and elbows in. The arms should be perpendicular to the floor. This will be your starting position. Tip: In order to protect your rotator cuff, it is best if you have a spotter help you lift the barbell off the rack.', 'Now lower the bar down to your lower chest as you breathe in. Keep the elbows in as you perform this movement.', 'Using the triceps to push the bar back up, press it back to the starting position as you exhale.', 'As you breathe in and you keep the upper arms stationary, bring the bar down slowly by moving your forearms in a semicircular motion towards you until you feel the bar slightly touch your forehead. Breathe in as you perform this portion of the movement.', 'Lift the bar back to the starting position by contracting the triceps and exhaling.', 'Repeat steps 3-6 until the recommended amount of repetitions is performed.']::text[], ARRAY['Decline_Close-Grip_Bench_To_Skull_Crusher/0.jpg', 'Decline_Close-Grip_Bench_To_Skull_Crusher/1.jpg']::text[], 'decline close-grip bench to skull crusher day nguc doc xuong nam hep kem skull crusher press declinado agarre cerrado a rompecraneos'),
  (NULL, 'Decline Crunch', 'Decline Crunch', 'Decline Crunch', 'Crunch declinado', 'abs', 'bodyweight', 'bodyweight', 'free_exercise_db', 'Decline_Crunch', ARRAY['Secure your legs at the end of the decline bench and lie down.', 'Now place your hands lightly on either side of your head keeping your elbows in. Tip: Don''t lock your fingers behind your head.', 'While pushing the small of your back down in the bench to better isolate your abdominal muscles, begin to roll your shoulders off it.', 'Continue to push down as hard as you can with your lower back as you contract your abdominals and exhale. Your shoulders should come up off the bench only about four inches, and your lower back should remain on the bench. At the top of the movement, contract your abdominals hard and keep the contraction for a second. Tip: Focus on slow, controlled movement - don''t cheat yourself by using momentum.', 'After the one second contraction, begin to come down slowly again to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Decline_Crunch/0.jpg', 'Decline_Crunch/1.jpg']::text[], 'decline crunch gap bung ghe doc xuong crunch declinado'),
  (NULL, 'Decline Dumbbell Bench Press', 'Decline Dumbbell Bench Press', 'Decline Dumbbell Bench Press', 'Press declinado con mancuernas', 'chest', 'dumbbell', 'compound', 'free_exercise_db', 'Decline_Dumbbell_Bench_Press', ARRAY['Secure your legs at the end of the decline bench and lie down with a dumbbell on each hand on top of your thighs. The palms of your hand will be facing each other.', 'Once you are laying down, move the dumbbells in front of you at shoulder width.', 'Once at shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. This will be your starting position.', 'Bring down the weights slowly to your side as you breathe out. Keep full control of the dumbbells at all times. Tip: Throughout the motion, the forearms should always be perpendicular to the floor.', 'As you breathe out, push the dumbbells up using your pectoral muscles. Lock your arms in the contracted position, squeeze your chest, hold for a second and then start coming down slowly. Tip: It should take at least twice as long to go down than to come up..', 'Repeat the movement for the prescribed amount of repetitions of your training program.']::text[], ARRAY['Decline_Dumbbell_Bench_Press/0.jpg', 'Decline_Dumbbell_Bench_Press/1.jpg']::text[], 'decline dumbbell bench press day nguc doc xuong ta don press declinado con mancuernas'),
  (NULL, 'Decline Dumbbell Flyes', 'Decline Dumbbell Flyes', 'Decline Dumbbell Flyes', 'Aperturas declinadas con mancuernas', 'chest', 'dumbbell', 'compound', 'free_exercise_db', 'Decline_Dumbbell_Flyes', ARRAY['Secure your legs at the end of the decline bench and lie down with a dumbbell on each hand on top of your thighs. The palms of your hand will be facing each other.', 'Once you are laying down, move the dumbbells in front of you at shoulder width. The palms of the hands should be facing each other and the arms should be perpendicular to the floor and fully extended. This will be your starting position.', 'With a slight bend on your elbows in order to prevent stress at the biceps tendon, lower your arms out at both sides in a wide arc until you feel a stretch on your chest. Breathe in as you perform this portion of the movement. Tip: Keep in mind that throughout the movement, the arms should remain stationary; the movement should only occur at the shoulder joint.', 'Return your arms back to the starting position as you squeeze your chest muscles and breathe out. Tip: Make sure to use the same arc of motion used to lower the weights.', 'Hold for a second at the contracted position and repeat the movement for the prescribed amount of repetitions.']::text[], ARRAY['Decline_Dumbbell_Flyes/0.jpg', 'Decline_Dumbbell_Flyes/1.jpg']::text[], 'decline dumbbell flyes ep nguc doc xuong ta don aperturas declinadas con mancuernas'),
  (NULL, 'Decline Dumbbell Triceps Extension', 'Duỗi tay sau dốc xuống tạ đơn', 'Decline Dumbbell Triceps Extension', 'Extensión de tríceps declinado con mancuernas', 'triceps', 'dumbbell', 'isolation', 'free_exercise_db', 'Decline_Dumbbell_Triceps_Extension', ARRAY['Secure your legs at the end of the decline bench and lie down with a dumbbell on each hand on top of your thighs. The palms of your hand will be facing each other.', 'Once you are laying down, move the dumbbells in front of you at shoulder width. The palms of the hands should be facing each other and the arms should be perpendicular to the floor and fully extended. This will be your starting position.', 'As you breathe in and you keep the upper arms stationary (and elbows in), bring the dumbbells down slowly by moving your forearms in a semicircular motion towards you until your thumbs are next to your ears. Breathe in as you perform this portion of the movement.', 'Lift the dumbbells back to the starting position by contracting the triceps and exhaling.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Decline_Dumbbell_Triceps_Extension/0.jpg', 'Decline_Dumbbell_Triceps_Extension/1.jpg']::text[], 'decline dumbbell triceps extension duoi tay sau doc xuong ta don extension de triceps declinado con mancuernas'),
  (NULL, 'Decline EZ Bar Triceps Extension', 'Duỗi tay sau dốc xuống thanh EZ', 'Decline EZ Bar Triceps Extension', 'Extensión de tríceps declinado con barra EZ', 'triceps', 'barbell', 'isolation', 'free_exercise_db', 'Decline_EZ_Bar_Triceps_Extension', ARRAY['Secure your legs at the end of the decline bench and slowly lay down on the bench.', 'Using a close grip (a grip that is slightly less than shoulder width), lift the EZ bar from the rack and hold it straight over you with your arms locked and elbows in. The arms should be perpendicular to the floor. This will be your starting position. Tip: In order to protect your rotator cuff, it is best if you have a spotter help you lift the barbell off the rack.', 'As you breathe in and you keep the upper arms stationary, bring the bar down slowly by moving your forearms in a semicircular motion towards you until you feel the bar slightly touch your forehead. Breathe in as you perform this portion of the movement.', 'Lift the bar back to the starting position by contracting the triceps and exhaling.', 'Repeat until the recommended amount of repetitions is performed.']::text[], ARRAY['Decline_EZ_Bar_Triceps_Extension/0.jpg', 'Decline_EZ_Bar_Triceps_Extension/1.jpg']::text[], 'decline ez bar triceps extension duoi tay sau doc xuong thanh ez extension de triceps declinado con barra ez'),
  (NULL, 'Decline Oblique Crunch', 'Decline Oblique Crunch', 'Decline Oblique Crunch', 'Crunch oblicuo declinado', 'abs', 'bodyweight', 'bodyweight', 'free_exercise_db', 'Decline_Oblique_Crunch', ARRAY['Secure your legs at the end of the decline bench and slowly lay down on the bench.', 'Raise your upper body off the bench until your torso is about 35-45 degrees if measured from the floor.', 'Put one hand beside your head and the other on your thigh. This will be your starting position.', 'Raise your upper body slowly from the starting position while turning your torso to the left. Continue crunching up as you exhale until your right elbow touches your left knee. Hold this contracted position for a second. Tip: Focus on keeping your abs tight and keeping the movement slow and controlled.', 'Lower your body back down slowly to the starting position as you inhale.', 'After completing one set on the right for the recommended amount of repetitions, switch to your left side. Tip: Focus on really twisting your torso and feeling the contraction when you are in the up position.']::text[], ARRAY['Decline_Oblique_Crunch/0.jpg', 'Decline_Oblique_Crunch/1.jpg']::text[], 'decline oblique crunch gap bung xien ghe doc xuong crunch oblicuo declinado'),
  (NULL, 'Decline Push-Up', 'Hít đất chân trên cao', 'Decline Push-Up', 'Flexiones declinadas', 'chest', 'other', 'bodyweight', 'free_exercise_db', 'Decline_Push-Up', ARRAY['Lie on the floor face down and place your hands about 36 inches apart while holding your torso up at arms length. Move your feet up to a box or bench. This will be your starting position.', 'Next, lower yourself downward until your chest almost touches the floor as you inhale.', 'Now breathe out and press your upper body back up to the starting position while squeezing your chest.', 'After a brief pause at the top contracted position, you can begin to lower yourself downward again for as many repetitions as needed.']::text[], ARRAY['Decline_Push-Up/0.jpg', 'Decline_Push-Up/1.jpg']::text[], 'decline push-up hit dat chan tren cao flexiones declinadas'),
  (NULL, 'Decline Reverse Crunch', 'Decline Reverse Crunch', 'Decline Reverse Crunch', 'Crunch inverso declinado', 'abs', 'bodyweight', 'bodyweight', 'free_exercise_db', 'Decline_Reverse_Crunch', ARRAY['Lie on your back on a decline bench and hold on to the top of the bench with both hands. Don''t let your body slip down from this position.', 'Hold your legs parallel to the floor using your abs to hold them there while keeping your knees and feet together. Tip: Your legs should be fully extended with a slight bend on the knee. This will be your starting position.', 'While exhaling, move your legs towards the torso as you roll your pelvis backwards and you raise your hips off the bench. At the end of this movement your knees will be touching your chest.', 'Hold the contraction for a second and move your legs back to the starting position while inhaling.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Decline_Reverse_Crunch/0.jpg', 'Decline_Reverse_Crunch/1.jpg']::text[], 'decline reverse crunch gap bung nguoc ghe doc xuong crunch inverso declinado'),
  (NULL, 'Decline Smith Press', 'Đẩy ngực dốc xuống máy Smith', 'Decline Smith Press', 'Press declinado en máquina Smith', 'chest', 'machine', 'compound', 'free_exercise_db', 'Decline_Smith_Press', ARRAY['Place a decline bench underneath the Smith machine. Now place the barbell at a height that you can reach when lying down and your arms are almost fully extended. Using a pronated grip that is wider than shoulder width, unlock the bar from the rack and hold it straight over you with your arms extended. This will be your starting position.', 'As you inhale, lower the bar under control by allowing the elbows to flex, lightly contacting the torso.', 'After a brief pause, bring the bar back to the starting position by extending the elbows, exhaling as you do so.', 'Repeat the movement for the prescribed amount of repetitions.', 'When the set is complete, lock the bar back in the rack.']::text[], ARRAY['Decline_Smith_Press/0.jpg', 'Decline_Smith_Press/1.jpg']::text[], 'decline smith press day nguc doc xuong may smith press declinado en maquina smith'),
  (NULL, 'Deficit Deadlift', 'Deficit Deadlift', 'Deficit Deadlift', 'Peso muerto en déficit', 'back', 'barbell', 'compound', 'free_exercise_db', 'Deficit_Deadlift', ARRAY['Begin by having a platform or weight plates that you can stand on, usually 1-3 inches in height. Approach the bar so that it is centered over your feet. You feet should be about hip width apart. Bend at the hip to grip the bar at shoulder width, allowing your shoulder blades to protract. Typically, you would use an overhand grip or an over/under grip on heavier sets.', 'With your feet, and your grip set, take a big breath and then lower your hips and bend the knees until your shins contact the bar. Look forward with your head, keep your chest up and your back arched, and begin driving through the heels to move the weight upward. After the bar passes the knees, aggressively pull the bar back, pulling your shoulder blades together as you drive your hips forward into the bar.', 'Lower the bar by bending at the hips and guiding it to the floor.']::text[], ARRAY['Deficit_Deadlift/0.jpg', 'Deficit_Deadlift/1.jpg']::text[], 'deficit deadlift deadlift dung tren buc peso muerto en deficit'),
  (NULL, 'Depth Jump Leap', 'Nhảy sâu rồi bật xa', 'Depth Jump Leap', 'Salto en profundidad con zancada', 'legs', 'other', 'compound', 'free_exercise_db', 'Depth_Jump_Leap', ARRAY['For this drill you will need two boxes or benches, one 12 to 16 inches high and the other 22 to 26 inches high.', 'Stand on one of the two boxes with arms at the sides; feet should be together and slightly off the edge as in the depth jump. Place the other box approximately two or three feet in front of and facing the performer.', 'Begin by dropping off the initial box, landing and simultaneously taking off with both feet.', 'Rebound by driving upward and outward as intensely as possible, using the arms and full extension of the body to jump onto the higher box. Again, allow the legs to absorb the impact.']::text[], ARRAY['Depth_Jump_Leap/0.jpg', 'Depth_Jump_Leap/1.jpg']::text[], 'depth jump leap nhay sau roi bat xa salto en profundidad con zancada'),
  (NULL, 'Dip Machine', 'Dip Machine', 'Dip Machine', 'Fondos en máquina', 'triceps', 'machine', 'compound', 'free_exercise_db', 'Dip_Machine', ARRAY['Sit securely in a dip machine, select the weight and firmly grasp the handles.', 'Now keep your elbows in at your sides in order to place emphasis on the triceps. The elbows should be bent at a 90 degree angle.', 'As you contract the triceps, extend your arms downwards as you exhale. Tip: At the bottom of the movement, focus on keeping a little bend in your arms to keep tension on the triceps muscle.', 'Now slowly let your arms come back up to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Dip_Machine/0.jpg', 'Dip_Machine/1.jpg']::text[], 'dip machine dips may fondos en maquina'),
  (NULL, 'Dips - Chest Version', 'Dips - Chest Version', 'Dips - Chest Version', 'Fondos para pecho', 'chest', 'other', 'compound', 'free_exercise_db', 'Dips_-_Chest_Version', ARRAY['For this exercise you will need access to parallel bars. To get yourself into the starting position, hold your body at arms length (arms locked) above the bars.', 'While breathing in, lower yourself slowly with your torso leaning forward around 30 degrees or so and your elbows flared out slightly until you feel a slight stretch in the chest.', 'Once you feel the stretch, use your chest to bring your body back to the starting position as you breathe out. Tip: Remember to squeeze the chest at the top of the movement for a second.', 'Repeat the movement for the prescribed amount of repetitions.']::text[], ARRAY['Dips_-_Chest_Version/0.jpg', 'Dips_-_Chest_Version/1.jpg']::text[], 'dips - chest version dips xa kep (nguc) fondos para pecho'),
  (NULL, 'Dips - Triceps Version', 'Dips - Triceps Version', 'Dips - Triceps Version', 'Fondos para tríceps', 'triceps', 'bodyweight', 'bodyweight', 'free_exercise_db', 'Dips_-_Triceps_Version', ARRAY['To get into the starting position, hold your body at arm''s length with your arms nearly locked above the bars.', 'Now, inhale and slowly lower yourself downward. Your torso should remain upright and your elbows should stay close to your body. This helps to better focus on tricep involvement. Lower yourself until there is a 90 degree angle formed between the upper arm and forearm.', 'Then, exhale and push your torso back up using your triceps to bring your body back to the starting position.', 'Repeat the movement for the prescribed amount of repetitions.']::text[], ARRAY['Dips_-_Triceps_Version/0.jpg', 'Dips_-_Triceps_Version/1.jpg']::text[], 'dips - triceps version dips xa kep (tay sau) fondos para triceps'),
  (NULL, 'Donkey Calf Raises', 'Nhón bắp chân kiểu con lừa', 'Donkey Calf Raises', 'Elevación de gemelos tipo burro', 'calves', 'other', 'isolation', 'free_exercise_db', 'Donkey_Calf_Raises', ARRAY['For this exercise you will need access to a donkey calf raise machine. Start by positioning your lower back and hips under the padded lever provided. The tailbone area should be the one making contact with the pad.', 'Place both of your arms on the side handles and place the balls of your feet on the calf block with the heels extending off. Align the toes forward, inward or outward, depending on the area you wish to target, and straighten the knees without locking them. This will be your starting position.', 'Raise your heels as you breathe out by extending your ankles as high as possible and flexing your calf. Ensure that the knee is kept stationary at all times. There should be no bending at any time. Hold the contracted position by a second before you start to go back down.', 'Go back slowly to the starting position as you breathe in by lowering your heels as you bend the ankles until calves are stretched.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Donkey_Calf_Raises/0.jpg', 'Donkey_Calf_Raises/1.jpg']::text[], 'donkey calf raises nhon bap chan kieu con lua elevacion de gemelos tipo burro'),
  (NULL, 'Double Kettlebell Alternating Hang Clean', 'Double Kettlebell Alternating Hang Clean', 'Double Kettlebell Alternating Hang Clean', 'Cargada colgante alterna con dos pesas rusas', 'legs', 'kettlebell', 'compound', 'free_exercise_db', 'Double_Kettlebell_Alternating_Hang_Clean', ARRAY['Place two kettlebells between your feet. To get in the starting position, push your butt back and look straight ahead.', 'Clean one kettlebell to your shoulder and hold on to the other kettlebell.', 'With a fluid motion, lower the top kettlebell while driving the bottom kettlebell up.']::text[], ARRAY['Double_Kettlebell_Alternating_Hang_Clean/0.jpg', 'Double_Kettlebell_Alternating_Hang_Clean/1.jpg']::text[], 'double kettlebell alternating hang clean hang clean hai kettlebell luan phien cargada colgante alterna con dos pesas rusas'),
  (NULL, 'Double Kettlebell Jerk', 'Double Kettlebell Jerk', 'Double Kettlebell Jerk', 'Envión con dos pesas rusas', 'shoulders', 'kettlebell', 'compound', 'free_exercise_db', 'Double_Kettlebell_Jerk', ARRAY['Hold a kettlebell by the handle in each hand.', 'Clean the kettlebells to your shoulders by extending through the legs and hips as you pull the kettlebells towards your shoulders. Rotate your wrists as you do so, so that the palms face forward. This will be your starting position.', 'Dip your body by bending the knees, keeping your torso upright.', 'Immediately reverse direction, driving through the heels, in essence jumping to create momentum.', 'As you do so, press the kettlebells overhead to lockout by extending the arms, using your body''s momentum to move the weights.', 'Return your feet to the ground in a split fashion, with one foot forward and one foot back.', 'Keeping the weights overhead, return to a standing position, bringing your feet together. Lower the weights to perform the next repetition.']::text[], ARRAY['Double_Kettlebell_Jerk/0.jpg', 'Double_Kettlebell_Jerk/1.jpg']::text[], 'double kettlebell jerk jerk hai kettlebell envion con dos pesas rusas'),
  (NULL, 'Double Kettlebell Push Press', 'Double Kettlebell Push Press', 'Double Kettlebell Push Press', 'Push press con dos pesas rusas', 'shoulders', 'kettlebell', 'compound', 'free_exercise_db', 'Double_Kettlebell_Push_Press', ARRAY['Clean two kettlebells to your shoulders.', 'Squat down a few inches and reverse the motion rapidly. Use the momentum from the legs to drive the kettlebells overhead.', 'Once the kettlebells are locked out, lower the kettlebells to your shoulders and repeat.']::text[], ARRAY['Double_Kettlebell_Push_Press/0.jpg', 'Double_Kettlebell_Push_Press/1.jpg']::text[], 'double kettlebell push press push press hai kettlebell push press con dos pesas rusas'),
  (NULL, 'Double Kettlebell Snatch', 'Double Kettlebell Snatch', 'Double Kettlebell Snatch', 'Arrancada con dos pesas rusas', 'shoulders', 'kettlebell', 'compound', 'free_exercise_db', 'Double_Kettlebell_Snatch', ARRAY['Place two kettlebells behind your feet. Bend your knees and sit back to pick up the kettlebells.', 'Swing the kettlebells between your legs forcefully and reverse the direction.', 'Drive through with your hips and lock the ketttlebells overhead in one uninterrupted motion.']::text[], ARRAY['Double_Kettlebell_Snatch/0.jpg', 'Double_Kettlebell_Snatch/1.jpg']::text[], 'double kettlebell snatch snatch hai kettlebell arrancada con dos pesas rusas'),
  (NULL, 'Double Kettlebell Windmill', 'Cối xay gió hai kettlebell', 'Double Kettlebell Windmill', 'Molino con dos pesas rusas', 'abs', 'kettlebell', 'compound', 'free_exercise_db', 'Double_Kettlebell_Windmill', ARRAY['Place a kettlebell in front of your front foot and clean and press a kettlebell overhead with your opposite arm. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulders. Rotate your wrist as you do so, so that the palm faces forward.', 'Keeping the kettlebell locked out at all times, push your butt out in the direction of the locked out kettlebell. Turn your feet out at a forty-five degree angle from the arm with the locked out kettlebell.', 'Bending at the hip to one side, sticking your butt out, slowly lean until you can retrieve the kettlebell from the floor. Keep your eyes on the kettlebell that you hold over your head at all times.', 'Pause for a second after retrieving the kettlebell from the ground and reverse the motion back to the starting position.']::text[], ARRAY['Double_Kettlebell_Windmill/0.jpg', 'Double_Kettlebell_Windmill/1.jpg']::text[], 'double kettlebell windmill coi xay gio hai kettlebell molino con dos pesas rusas'),
  (NULL, 'Double Leg Butt Kick', 'Đá gót chạm mông hai chân', 'Double Leg Butt Kick', 'Patadas de talón al glúteo', 'legs', 'bodyweight', 'bodyweight', 'free_exercise_db', 'Double_Leg_Butt_Kick', ARRAY['Begin standing with your knees slightly bent.', 'Quickly squat a short distance, flexing the hips and knees, and immediately extend to jump for maximum vertical height.', 'As you go up, tuck your heels by flexing the knees, attempting to touch the buttocks.', 'Finish the motion by landing with the knees only partially bent, using your legs to absorb the impact.']::text[], ARRAY['Double_Leg_Butt_Kick/0.jpg', 'Double_Leg_Butt_Kick/1.jpg']::text[], 'double leg butt kick da got cham mong hai chan patadas de talon al gluteo'),
  (NULL, 'Downward Facing Balance', 'Thăng bằng úp người trên bóng', 'Downward Facing Balance', 'Equilibrio boca abajo en fitball', 'glutes', 'exercise ball', 'isolation', 'free_exercise_db', 'Downward_Facing_Balance', ARRAY['Lie facedown on top of an exercise ball.', 'While resting on your stomach on the ball, walk your hands forward along the floor and lift your legs, extending your elbows and knees.']::text[], ARRAY['Downward_Facing_Balance/0.jpg', 'Downward_Facing_Balance/1.jpg']::text[], 'downward facing balance thang bang up nguoi tren bong equilibrio boca abajo en fitball'),
  (NULL, 'Drag Curl', 'Drag Curl', 'Drag Curl', 'Curl de arrastre con barra', 'biceps', 'barbell', 'compound', 'free_exercise_db', 'Drag_Curl', ARRAY['Grab a barbell with a supinated grip (palms facing forward) and get your elbows close to your torso and back. This will be your starting position.', 'As you exhale, curl the bar up while keeping the elbows to the back as you "Drag" the bar up by keeping it in contact with your torso. Tip: As you can see, you will not be keeping the elbows pinned to your sides, but instead you will be bringing them back. Also, do not lift your shoulders.', 'Slowly go back to the starting position as you keep the bar in contact with the torso at all times.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Drag_Curl/0.jpg', 'Drag_Curl/1.jpg']::text[], 'drag curl cuon ta don keo sat nguoi curl de arrastre con barra'),
  (NULL, 'Drop Push', 'Hít đất thả rơi', 'Drop Push', 'Flexiones con caída', 'chest', 'other', 'compound', 'free_exercise_db', 'Drop_Push', ARRAY['Position low boxes or other platforms 2-3 feet apart.', 'Move to a pushup position between them, supporting yourself by placing your hands on the boxes.', 'With good posture, drop from the platforms by pressing up and moving your hands to shoulder width, cushioning your landing by absorbing the impact through the arm.']::text[], ARRAY['Drop_Push/0.jpg', 'Drop_Push/1.jpg']::text[], 'drop push hit dat tha roi flexiones con caida'),
  (NULL, 'Dumbbell Alternate Bicep Curl', 'Dumbbell Alternate Bicep Curl', 'Dumbbell Alternate Bicep Curl', 'Curl de bíceps alterno con mancuernas', 'biceps', 'dumbbell', 'isolation', 'free_exercise_db', 'Dumbbell_Alternate_Bicep_Curl', ARRAY['Stand (torso upright) with a dumbbell in each hand held at arms length. The elbows should be close to the torso and the palms of your hand should be facing your thighs.', 'While holding the upper arm stationary, curl the right weight as you rotate the palm of the hands until they are facing forward. At this point continue contracting the biceps as you breathe out until your biceps is fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a second as you squeeze the biceps. Tip: Only the forearms should move.', 'Slowly begin to bring the dumbbell back to the starting position as your breathe in. Tip: Remember to twist the palms back to the starting position (facing your thighs) as you come down.', 'Repeat the movement with the left hand. This equals one repetition.', 'Continue alternating in this manner for the recommended amount of repetitions.']::text[], ARRAY['Dumbbell_Alternate_Bicep_Curl/0.jpg', 'Dumbbell_Alternate_Bicep_Curl/1.jpg']::text[], 'dumbbell alternate bicep curl cuon tay truoc ta don luan phien curl de biceps alterno con mancuernas'),
  (NULL, 'Dumbbell Bench Press', 'Dumbbell Bench Press', 'Dumbbell Bench Press', 'Press de banca con mancuernas', 'chest', 'dumbbell', 'compound', 'free_exercise_db', 'Dumbbell_Bench_Press', ARRAY['Lie down on a flat bench with a dumbbell in each hand resting on top of your thighs. The palms of your hands will be facing each other.', 'Then, using your thighs to help raise the dumbbells up, lift the dumbbells one at a time so that you can hold them in front of you at shoulder width.', 'Once at shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. The dumbbells should be just to the sides of your chest, with your upper arm and forearm creating a 90 degree angle. Be sure to maintain full control of the dumbbells at all times. This will be your starting position.', 'Then, as you breathe out, use your chest to push the dumbbells up. Lock your arms at the top of the lift and squeeze your chest, hold for a second and then begin coming down slowly. Tip: Ideally, lowering the weight should take about twice as long as raising it.', 'Repeat the movement for the prescribed amount of repetitions of your training program.']::text[], ARRAY['Dumbbell_Bench_Press/0.jpg', 'Dumbbell_Bench_Press/1.jpg']::text[], 'dumbbell bench press day nguc ta don press de banca con mancuernas'),
  (NULL, 'Dumbbell Bench Press with Neutral Grip', 'Dumbbell Bench Press with Neutral Grip', 'Dumbbell Bench Press with Neutral Grip', 'Press con mancuernas agarre neutro', 'chest', 'dumbbell', 'compound', 'free_exercise_db', 'Dumbbell_Bench_Press_with_Neutral_Grip', ARRAY['Take a dumbbell in each hand and lay back onto a flat bench. Your feet should be flat on the floor and your shoulder blades retracted.', 'Maintaining a neutral grip, palms facing each other, begin with your arms extended directly above you, perpendicular to the floor. This will be your starting position.', 'Begin the movement by flexing the elbow, lowering the upper arms to the side. Descend until the dumbbells are to your torso.', 'Pause, then extend the elbow and return to the starting position.']::text[], ARRAY['Dumbbell_Bench_Press_with_Neutral_Grip/0.jpg', 'Dumbbell_Bench_Press_with_Neutral_Grip/1.jpg']::text[], 'dumbbell bench press with neutral grip day nguc ta don nam trung tinh press con mancuernas agarre neutro'),
  (NULL, 'Dumbbell Bicep Curl', 'Dumbbell Bicep Curl', 'Dumbbell Bicep Curl', 'Curl de bíceps con mancuernas', 'biceps', 'dumbbell', 'isolation', 'free_exercise_db', 'Dumbbell_Bicep_Curl', ARRAY['Stand up straight with a dumbbell in each hand at arm''s length. Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward. This will be your starting position.', 'Now, keeping the upper arms stationary, exhale and curl the weights while contracting your biceps. Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps.', 'Then, inhale and slowly begin to lower the dumbbells back to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Dumbbell_Bicep_Curl/0.jpg', 'Dumbbell_Bicep_Curl/1.jpg']::text[], 'dumbbell bicep curl cuon tay truoc ta don curl de biceps con mancuernas'),
  (NULL, 'Dumbbell Clean', 'Dumbbell Clean', 'Dumbbell Clean', 'Cargada con mancuernas', 'legs', 'dumbbell', 'compound', 'free_exercise_db', 'Dumbbell_Clean', ARRAY['Begin standing with a dumbbell in each hand with your feet shoulder width apart.', 'Lower the weights to the floor by flexing at the hips and knees, pushing your hips back until the dumbbells reach the floor. This will be your starting position.', 'To initiate the movement, violently jump upward by extending the hips, knees, and ankles to acclerate the weights upward. Maintaining a neutral grip on the dumbbells, keep the arms straight until full extension is reached.', 'After full extension, rebend the hips and knees to receive the weight in a squat position. Allow the arms to bend, guiding the dumbbells to your shoulders.', 'Upon receiving the weight in the squat position, extend the hips and knees to finish in a standing position with the weights on your shoulders.']::text[], ARRAY['Dumbbell_Clean/0.jpg', 'Dumbbell_Clean/1.jpg']::text[], 'dumbbell clean clean ta don cargada con mancuernas'),
  (NULL, 'Dumbbell Floor Press', 'Đẩy sàn tạ đơn', 'Dumbbell Floor Press', 'Press en el suelo con mancuernas', 'triceps', 'dumbbell', 'compound', 'free_exercise_db', 'Dumbbell_Floor_Press', ARRAY['Lay on the floor holding dumbbells in your hands. Your knees can be bent. Begin with the weights fully extended above you.', 'Lower the weights until your upper arm comes in contact with the floor. You can tuck your elbows to emphasize triceps size and strength, or to focus on your chest angle your arms to the side.', 'Pause at the bottom, and then bring the weight together at the top by extending through the elbows.']::text[], ARRAY['Dumbbell_Floor_Press/0.jpg', 'Dumbbell_Floor_Press/1.jpg']::text[], 'dumbbell floor press day san ta don press en el suelo con mancuernas'),
  (NULL, 'Dumbbell Flyes', 'Dumbbell Flyes', 'Dumbbell Flyes', 'Aperturas con mancuernas', 'chest', 'dumbbell', 'isolation', 'free_exercise_db', 'Dumbbell_Flyes', ARRAY['Lie down on a flat bench with a dumbbell on each hand resting on top of your thighs. The palms of your hand will be facing each other.', 'Then using your thighs to help raise the dumbbells, lift the dumbbells one at a time so you can hold them in front of you at shoulder width with the palms of your hands facing each other. Raise the dumbbells up like you''re pressing them, but stop and hold just before you lock out. This will be your starting position.', 'With a slight bend on your elbows in order to prevent stress at the biceps tendon, lower your arms out at both sides in a wide arc until you feel a stretch on your chest. Breathe in as you perform this portion of the movement. Tip: Keep in mind that throughout the movement, the arms should remain stationary; the movement should only occur at the shoulder joint.', 'Return your arms back to the starting position as you squeeze your chest muscles and breathe out. Tip: Make sure to use the same arc of motion used to lower the weights.', 'Hold for a second at the contracted position and repeat the movement for the prescribed amount of repetitions.']::text[], ARRAY['Dumbbell_Flyes/0.jpg', 'Dumbbell_Flyes/1.jpg']::text[], 'dumbbell flyes ep nguc bay ta don aperturas con mancuernas'),
  (NULL, 'Dumbbell Incline Row', 'Chèo tạ đơn nằm ghế dốc', 'Dumbbell Incline Row', 'Remo inclinado con mancuernas en banco', 'back', 'dumbbell', 'compound', 'free_exercise_db', 'Dumbbell_Incline_Row', ARRAY['Using a neutral grip, lean into an incline bench.', 'Take a dumbbell in each hand with a neutral grip, beginning with the arms straight. This will be your starting position.', 'Retract the shoulder blades and flex the elbows to row the dumbbells to your side.', 'Pause at the top of the motion, and then return to the starting position.']::text[], ARRAY['Dumbbell_Incline_Row/0.jpg', 'Dumbbell_Incline_Row/1.jpg']::text[], 'dumbbell incline row cheo ta don nam ghe doc remo inclinado con mancuernas en banco'),
  (NULL, 'Dumbbell Incline Shoulder Raise', 'Nâng vai ghế dốc tạ đơn', 'Dumbbell Incline Shoulder Raise', 'Elevación de hombros inclinado con mancuernas', 'shoulders', 'dumbbell', 'isolation', 'free_exercise_db', 'Dumbbell_Incline_Shoulder_Raise', ARRAY['Sit on an Incline Bench while holding a dumbbell on each hand on top of your thighs.', 'Lift your legs up to kick the weights to your shoulders and lean back. Position the dumbbells above your shoulders with your arms extended. The arms should be perpendicular to the floor with your palms facing forward and knuckles pointing towards the ceiling. This will be your starting position.', 'While keeping the arms straight and locked, lift the dumbbells by raising the shoulders from the bench as you breathe out.', 'Bring back the dumbbells to the starting position as you breathe in.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Dumbbell_Incline_Shoulder_Raise/0.jpg', 'Dumbbell_Incline_Shoulder_Raise/1.jpg']::text[], 'dumbbell incline shoulder raise nang vai ghe doc ta don elevacion de hombros inclinado con mancuernas'),
  (NULL, 'Dumbbell Lunges', 'Dumbbell Lunges', 'Dumbbell Lunges', 'Zancadas con mancuernas', 'legs', 'dumbbell', 'compound', 'free_exercise_db', 'Dumbbell_Lunges', ARRAY['Stand with your torso upright holding two dumbbells in your hands by your sides. This will be your starting position.', 'Step forward with your right leg around 2 feet or so from the foot being left stationary behind and lower your upper body down, while keeping the torso upright and maintaining balance. Inhale as you go down. Note: As in the other exercises, do not allow your knee to go forward beyond your toes as you come down, as this will put undue stress on the knee joint. Make sure that you keep your front shin perpendicular to the ground.', 'Using mainly the heel of your foot, push up and go back to the starting position as you exhale.', 'Repeat the movement for the recommended amount of repetitions and then perform with the left leg.']::text[], ARRAY['Dumbbell_Lunges/0.jpg', 'Dumbbell_Lunges/1.jpg']::text[], 'dumbbell lunges chung chan ta don zancadas con mancuernas'),
  (NULL, 'Dumbbell Lying One-Arm Rear Lateral Raise', 'Nâng vai sau một tay nằm tạ đơn', 'Dumbbell Lying One-Arm Rear Lateral Raise', 'Elevación posterior a una mano tumbado', 'shoulders', 'dumbbell', 'isolation', 'free_exercise_db', 'Dumbbell_Lying_One-Arm_Rear_Lateral_Raise', ARRAY['While holding a dumbbell in one hand, lay with your chest down on a slightly inclined (around 15 degrees when measured from the floor) adjustable bench. The other hand can be used to hold to the leg of the bench for stability.', 'Position the palm of the hand that is holding the dumbbell in a neutral manner (palms facing your torso) as you keep the arm extended with the elbow slightly bent. This will be your starting position.', 'Now raise the arm with the dumbbell to the side until your elbow is at shoulder height and your arm is roughly parallel to the floor as you exhale. Tip: Maintain your arm perpendicular to the torso while keeping your arm extended throughout the movement. Also, keep the contraction at the top for a second.', 'Slowly lower the dumbbell to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Dumbbell_Lying_One-Arm_Rear_Lateral_Raise/0.jpg', 'Dumbbell_Lying_One-Arm_Rear_Lateral_Raise/1.jpg']::text[], 'dumbbell lying one-arm rear lateral raise nang vai sau mot tay nam ta don elevacion posterior a una mano tumbado'),
  (NULL, 'Dumbbell Lying Pronation', 'Xoay cẳng tay úp nằm tạ đơn', 'Dumbbell Lying Pronation', 'Pronación tumbado con mancuerna', 'biceps', 'dumbbell', 'isolation', 'free_exercise_db', 'Dumbbell_Lying_Pronation', ARRAY['Lie on a flat bench face down with one arm holding a dumbbell and the other hand on top of the bench folded so that you can rest your head on it.', 'Bend the elbows of the arm holding the dumbbell so that it creates a 90-degree angle between the upper arm and the forearm.', 'Now raise the upper arm so that the forearm is perpendicular to the floor and the upper arm is perpendicular to your torso. Tip: The upper arm should be parallel to the floor and also creating a 90-degree angle with your torso. This will be your starting position.', 'As you breathe out, externally rotate your forearm so that the dumbbell is lifted forward as you maintain the 90 degree angle bend between the upper arms and the forearm. You will continue this external rotation until the forearm is parallel to the floor. At this point you will hold the contraction for a second.', 'As you breathe in, slowly go back to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Dumbbell_Lying_Pronation/0.jpg', 'Dumbbell_Lying_Pronation/1.jpg']::text[], 'dumbbell lying pronation xoay cang tay up nam ta don pronacion tumbado con mancuerna'),
  (NULL, 'Dumbbell Lying Rear Lateral Raise', 'Nâng vai sau nằm tạ đơn', 'Dumbbell Lying Rear Lateral Raise', 'Elevación posterior tumbado con mancuernas', 'shoulders', 'dumbbell', 'isolation', 'free_exercise_db', 'Dumbbell_Lying_Rear_Lateral_Raise', ARRAY['While holding a dumbbell in each hand, lay with your chest down on a slightly inclined (around 15 degrees when measured from the floor) adjustable bench.', 'Position the palms of the hands in a neutral manner (palms facing your torso) as you keep the arms extended with the elbows slightly bent. This will be your starting position.', 'Now raise the arms to the side until your elbows are at shoulder height and your arms are roughly parallel to the floor as you exhale. Tip: Maintain your arms perpendicular to the torso while keeping them extended throughout the movement. Also, keep the contraction at the top for a second.', 'Slowly lower the dumbbells to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions and then switch to the other arm.']::text[], ARRAY['Dumbbell_Lying_Rear_Lateral_Raise/0.jpg', 'Dumbbell_Lying_Rear_Lateral_Raise/1.jpg']::text[], 'dumbbell lying rear lateral raise nang vai sau nam ta don elevacion posterior tumbado con mancuernas'),
  (NULL, 'Dumbbell Lying Supination', 'Xoay cẳng tay ngửa nằm tạ đơn', 'Dumbbell Lying Supination', 'Supinación tumbado con mancuerna', 'biceps', 'dumbbell', 'isolation', 'free_exercise_db', 'Dumbbell_Lying_Supination', ARRAY['Lie sideways on a flat bench with one arm holding a dumbbell and the other hand on top of the bench folded so that you can rest your head on it.', 'Bend the elbows of the arm holding the dumbbell so that it creates a 90-degree angle between the upper arm and the forearm.', 'Now raise the upper arm so that the forearm is parallel to the floor and perpendicular to your torso (Tip: So the forearm will be directly in front of you). The upper arm will be stationary by your torso and should be parallel to the floor (aligned with your torso at all times). This will be your starting position.', 'As you breathe out, externally rotate your forearm so that the dumbbell is lifted up in a semicircle motion as you maintain the 90 degree angle bend between the upper arms and the forearm. You will continue this external rotation until the forearm is perpendicular to the floor and the torso pointing towards the ceiling. At this point you will hold the contraction for a second.', 'As you breathe in, slowly go back to the starting position.', 'Repeat for the recommended amount of repetitions and then switch to the other arm.']::text[], ARRAY['Dumbbell_Lying_Supination/0.jpg', 'Dumbbell_Lying_Supination/1.jpg']::text[], 'dumbbell lying supination xoay cang tay ngua nam ta don supinacion tumbado con mancuerna'),
  (NULL, 'Dumbbell One-Arm Shoulder Press', 'Đẩy vai một tay tạ đơn', 'Dumbbell One-Arm Shoulder Press', 'Press de hombro a una mano con mancuerna', 'shoulders', 'dumbbell', 'compound', 'free_exercise_db', 'Dumbbell_One-Arm_Shoulder_Press', ARRAY['Grab a dumbbell and either sit on a military press bench or a utility bench that has a back support on it as you place the dumbbells upright on top of your thighs or stand up straight.', 'Clean the dumbbell up to bring it to shoulder height. The other hand can be kept fully extended to the side, by the waist or grabbing a fixed surface.', 'Rotate the wrist so that the palm of your hand is facing forward. This is your starting position.', 'As you exhale, push the dumbbell up until your arm is fully extended.', 'After a second pause, slowly come down back to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions and then switch arms.']::text[], ARRAY['Dumbbell_One-Arm_Shoulder_Press/0.jpg', 'Dumbbell_One-Arm_Shoulder_Press/1.jpg']::text[], 'dumbbell one-arm shoulder press day vai mot tay ta don press de hombro a una mano con mancuerna'),
  (NULL, 'Dumbbell One-Arm Triceps Extension', 'Duỗi tay sau một tay tạ đơn', 'Dumbbell One-Arm Triceps Extension', 'Extensión de tríceps a una mano con mancuerna', 'triceps', 'dumbbell', 'isolation', 'free_exercise_db', 'Dumbbell_One-Arm_Triceps_Extension', ARRAY['Grab a dumbbell and either sit on a military press bench or a utility bench that has a back support on it as you place the dumbbells upright on top of your thighs or stand up straight.', 'Clean the dumbbell up to bring it to shoulder height and then extend the arm over your head so that the whole arm is perpendicular to the floor and next to your head. The dumbbell should be on top of you. The other hand can be kept fully extended to the side, by the waist, supporting the upper arm that has the dumbbell or grabbing a fixed surface.', 'Rotate the wrist so that the palm of your hand is facing forward and the pinkie is facing the ceiling. This will be your starting position.', 'Slowly lower the dumbbell behind your head as you hold the upper arm stationary. Inhale as you perform this movement and pause when your triceps are fully stretched.', 'Return to the starting position by flexing your triceps as you breathe out. Tip: It is imperative that only the forearm moves. The upper arm should remain at all times stationary next to your head.', 'Repeat for the recommended amount of repetitions and switch arms.']::text[], ARRAY['Dumbbell_One-Arm_Triceps_Extension/0.jpg', 'Dumbbell_One-Arm_Triceps_Extension/1.jpg']::text[], 'dumbbell one-arm triceps extension duoi tay sau mot tay ta don extension de triceps a una mano con mancuerna'),
  (NULL, 'Dumbbell One-Arm Upright Row', 'Kéo thẳng đứng một tay tạ đơn', 'Dumbbell One-Arm Upright Row', 'Remo al mentón a una mano con mancuerna', 'shoulders', 'dumbbell', 'compound', 'free_exercise_db', 'Dumbbell_One-Arm_Upright_Row', ARRAY['Grab a dumbbell and stand up straight with your arm extended in front of you with a slight bend at the elbows and your back straight. This will be your starting position. Tip: The dumbbell should be resting on top of your thigh with the palm of your hands facing your thighs.', 'Keep the other hand can be kept fully extended to the side, by the waist or grabbing a fixed surface. This will be your starting position.', 'Use your side shoulders to lift the dumbbell as you exhale. The dumbbell should be close to the body as you move it up. Continue to lift it until the dumbbell is nearly in line with your chin. Tip: Your elbows should drive the motion. As you lift the dumbbell, your elbow should always be higher than your forearm. Also, keep your torso stationary and pause for a second at the top of the movement.', 'Lower the dumbbell back down slowly to the starting position. Inhale as you perform this portion of the movement.', 'Repeat for the recommended amount of repetitions and switch arms.']::text[], ARRAY['Dumbbell_One-Arm_Upright_Row/0.jpg', 'Dumbbell_One-Arm_Upright_Row/1.jpg']::text[], 'dumbbell one-arm upright row keo thang dung mot tay ta don remo al menton a una mano con mancuerna'),
  (NULL, 'Dumbbell Prone Incline Curl', 'Dumbbell Prone Incline Curl', 'Dumbbell Prone Incline Curl', 'Curl prono en banco inclinado con mancuernas', 'biceps', 'dumbbell', 'isolation', 'free_exercise_db', 'Dumbbell_Prone_Incline_Curl', ARRAY['Grab a dumbbell on each hand and lie face down on an incline bench with your shoulders near top of the incline. Your knees can rest on the seat or your legs can be straddled to the sides (my preferred way).', 'Let your arms extend and hang naturally in front of you so that they are perpendicular to the floor.', 'Now keep your elbows in by your side and face the palms forward. This will be your starting position.', 'Raise the dumbbells by contracting the biceps until your arms are fully flexed. Exhale as you perform this portion of the movement and ensure that only the forearms move. The upper arms should remain stationary at all times.', 'Lower the dumbbells until your arms are fully extended.', 'Repeat for the recommended amount of times.']::text[], ARRAY['Dumbbell_Prone_Incline_Curl/0.jpg', 'Dumbbell_Prone_Incline_Curl/1.jpg']::text[], 'dumbbell prone incline curl cuon ta don nam sap ghe doc curl prono en banco inclinado con mancuernas'),
  (NULL, 'Dumbbell Raise', 'Nâng tạ đơn', 'Dumbbell Raise', 'Elevación con mancuernas', 'shoulders', 'dumbbell', 'compound', 'free_exercise_db', 'Dumbbell_Raise', ARRAY['Grab a dumbbell in each arm and stand up straight with your arms extended by your sides with a slight bend at the elbows and your back straight. This will be your starting position. Tip: The dumbbell should be next to your thighs with the palm of your hands facing back.', 'Use your side shoulders to lift the dumbbells as you exhale. The dumbbells should be to the side of the body as you move them up. Continue to lift it until the dumbbells are nearly in line with your chin. Tip: Your elbows should drive the motion. As you lift the dumbbell, your elbow should always be higher than your forearm. Also, keep your torso stationary and pause for a second at the top of the movement.', 'Lower the dumbbells back down slowly to the starting position. Inhale as you perform this portion of the movement.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Dumbbell_Raise/0.jpg', 'Dumbbell_Raise/1.jpg']::text[], 'dumbbell raise nang ta don elevacion con mancuernas'),
  (NULL, 'Dumbbell Rear Lunge', 'Dumbbell Rear Lunge', 'Dumbbell Rear Lunge', 'Zancada inversa con mancuernas', 'legs', 'dumbbell', 'compound', 'free_exercise_db', 'Dumbbell_Rear_Lunge', ARRAY['Stand with your torso upright holding two dumbbells in your hands by your sides. This will be your starting position.', 'Step backward with your right leg around two feet or so from the left foot and lower your upper body down, while keeping the torso upright and maintaining balance. Inhale as you go down. Tip: As in the other exercises, do not allow your knee to go forward beyond your toes as you come down, as this will put undue stress on the knee joint. Make sure that you keep your front shin perpendicular to the ground. Keep the torso upright during the lunge; flexible hip flexors are important. A long lunge emphasizes the Gluteus Maximus; a short lunge emphasizes Quadriceps.', 'Push up and go back to the starting position as you exhale. Tip: Use the ball of your feet to push in order to accentuate the quadriceps. To focus on the glutes, press with your heels.', 'Now repeat with the opposite leg.']::text[], ARRAY['Dumbbell_Rear_Lunge/0.jpg', 'Dumbbell_Rear_Lunge/1.jpg']::text[], 'dumbbell rear lunge chung chan lui ta don zancada inversa con mancuernas'),
  (NULL, 'Dumbbell Scaption', 'Nâng tạ chữ Y (scaption)', 'Dumbbell Scaption', 'Elevación en escápula con mancuernas', 'shoulders', 'dumbbell', 'isolation', 'free_exercise_db', 'Dumbbell_Scaption', ARRAY['This corrective exercise strengthens the muscles that stabilize your shoulder blade. Hold a light weight in each hand, hanging at your sides. Your thumbs should pointing up.', 'Begin the movement raising your arms out in front of you, about 30 degrees off center. Your arms should be fully extended as you perform the movement.', 'Continue until your arms are parallel to the ground, and then return to the starting position.']::text[], ARRAY['Dumbbell_Scaption/0.jpg', 'Dumbbell_Scaption/1.jpg']::text[], 'dumbbell scaption nang ta chu y (scaption) elevacion en escapula con mancuernas'),
  (NULL, 'Dumbbell Seated Box Jump', 'Dumbbell Seated Box Jump', 'Dumbbell Seated Box Jump', 'Salto al cajón sentado con mancuernas', 'legs', 'dumbbell', 'compound', 'free_exercise_db', 'Dumbbell_Seated_Box_Jump', ARRAY['Position a box a couple feet to the side of a bench. Hold a dumbbell to your chest with both hands and seat yourself on the bench facing the box. This will be your starting position.', 'Plant your feet firmly on the ground as you lean forward, extending through the hips and knees to jump up and forward.', 'Land on the box with both feet, absorbing the impact by allowing the hips and knees to bend.', 'Step down and return to the starting position.']::text[], ARRAY['Dumbbell_Seated_Box_Jump/0.jpg', 'Dumbbell_Seated_Box_Jump/1.jpg']::text[], 'dumbbell seated box jump bat nhay len buc tu ghe voi ta don salto al cajon sentado con mancuernas'),
  (NULL, 'Dumbbell Seated One-Leg Calf Raise', 'Nhón bắp chân một chân ngồi tạ đơn', 'Dumbbell Seated One-Leg Calf Raise', 'Elevación de gemelo sentado a una pierna con mancuerna', 'calves', 'dumbbell', 'isolation', 'free_exercise_db', 'Dumbbell_Seated_One-Leg_Calf_Raise', ARRAY['Place a block on the floor about 12 inches from a flat bench.', 'Sit on a flat bench and place a dumbbell on your upper left thigh about 3 inches above your knee.', 'Now place the ball of your left foot on the block. This will be your starting position.', 'Raise your toes up as high as possible as you exhale and you contract your calf muscle. Hold the contraction for a second.', 'Slowly return to the starting position, stretching as far down as possible.', 'Repeat for your prescribed number of repetitions and then repeat with the right leg.']::text[], ARRAY['Dumbbell_Seated_One-Leg_Calf_Raise/0.jpg', 'Dumbbell_Seated_One-Leg_Calf_Raise/1.jpg']::text[], 'dumbbell seated one-leg calf raise nhon bap chan mot chan ngoi ta don elevacion de gemelo sentado a una pierna con mancuerna'),
  (NULL, 'Dumbbell Shoulder Press', 'Đẩy vai tạ đơn', 'Dumbbell Shoulder Press', 'Press de hombros con mancuernas', 'shoulders', 'dumbbell', 'compound', 'free_exercise_db', 'Dumbbell_Shoulder_Press', ARRAY['While holding a dumbbell in each hand, sit on a military press bench or utility bench that has back support. Place the dumbbells upright on top of your thighs.', 'Now raise the dumbbells to shoulder height one at a time using your thighs to help propel them up into position.', 'Make sure to rotate your wrists so that the palms of your hands are facing forward. This is your starting position.', 'Now, exhale and push the dumbbells upward until they touch at the top.', 'Then, after a brief pause at the top contracted position, slowly lower the weights back down to the starting position while inhaling.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Dumbbell_Shoulder_Press/0.jpg', 'Dumbbell_Shoulder_Press/1.jpg']::text[], 'dumbbell shoulder press day vai ta don press de hombros con mancuernas'),
  (NULL, 'Dumbbell Shrug', 'Dumbbell Shrug', 'Dumbbell Shrug', 'Encogimiento de hombros con mancuernas', 'shoulders', 'dumbbell', 'isolation', 'free_exercise_db', 'Dumbbell_Shrug', ARRAY['Stand erect with a dumbbell on each hand (palms facing your torso), arms extended on the sides.', 'Lift the dumbbells by elevating the shoulders as high as possible while you exhale. Hold the contraction at the top for a second. Tip: The arms should remain extended at all times. Refrain from using the biceps to help lift the dumbbells. Only the shoulders should be moving up and down.', 'Lower the dumbbells back to the original position.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Dumbbell_Shrug/0.jpg', 'Dumbbell_Shrug/1.jpg']::text[], 'dumbbell shrug nhun vai ta don encogimiento de hombros con mancuernas'),
  (NULL, 'Dumbbell Side Bend', 'Nghiêng lườn tạ đơn', 'Dumbbell Side Bend', 'Flexión lateral con mancuerna', 'abs', 'dumbbell', 'isolation', 'free_exercise_db', 'Dumbbell_Side_Bend', ARRAY['Stand up straight while holding a dumbbell on the left hand (palms facing the torso) as you have the right hand holding your waist. Your feet should be placed at shoulder width. This will be your starting position.', 'While keeping your back straight and your head up, bend only at the waist to the right as far as possible. Breathe in as you bend to the side. Then hold for a second and come back up to the starting position as you exhale. Tip: Keep the rest of the body stationary.', 'Now repeat the movement but bending to the left instead. Hold for a second and come back to the starting position.', 'Repeat for the recommended amount of repetitions and then change hands.']::text[], ARRAY['Dumbbell_Side_Bend/0.jpg', 'Dumbbell_Side_Bend/1.jpg']::text[], 'dumbbell side bend nghieng luon ta don flexion lateral con mancuerna'),
  (NULL, 'Dumbbell Squat', 'Dumbbell Squat', 'Dumbbell Squat', 'Sentadilla con mancuernas', 'legs', 'dumbbell', 'compound', 'free_exercise_db', 'Dumbbell_Squat', ARRAY['Stand up straight while holding a dumbbell on each hand (palms facing the side of your legs).', 'Position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance and also maintain a straight back. This will be your starting position. Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances discussed in the foot stances section.', 'Begin to slowly lower your torso by bending the knees as you maintain a straight posture with the head up. Continue down until your thighs are parallel to the floor. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.', 'Begin to raise your torso as you exhale by pushing the floor with the heel of your foot mainly as you straighten the legs again and go back to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Dumbbell_Squat/0.jpg', 'Dumbbell_Squat/1.jpg']::text[], 'dumbbell squat squat ta don sentadilla con mancuernas'),
  (NULL, 'Dumbbell Squat To A Bench', 'Dumbbell Squat To A Bench', 'Dumbbell Squat To A Bench', 'Sentadilla con mancuernas al banco', 'legs', 'dumbbell', 'compound', 'free_exercise_db', 'Dumbbell_Squat_To_A_Bench', ARRAY['Stand up straight with a flat bench behind you while holding a dumbbell on each hand (palms facing the side of your legs).', 'Position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance and also maintain a straight back. This will be your starting position. Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances discussed in the foot stances section.', 'Begin to slowly lower your torso by bending the knees as you maintain a straight posture with the head up. Continue down until you slightly touch the bench behind you. Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.', 'Begin to raise the bar as you exhale by pushing the floor with the heel of your foot mainly as you straighten the legs again and go back to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Dumbbell_Squat_To_A_Bench/0.jpg', 'Dumbbell_Squat_To_A_Bench/1.jpg']::text[], 'dumbbell squat to a bench squat ta don xuong ghe sentadilla con mancuernas al banco'),
  (NULL, 'Dumbbell Step Ups', 'Bước bục tạ đơn', 'Dumbbell Step Ups', 'Subida al cajón con mancuernas', 'legs', 'dumbbell', 'compound', 'free_exercise_db', 'Dumbbell_Step_Ups', ARRAY['Stand up straight while holding a dumbbell on each hand (palms facing the side of your legs).', 'Place the right foot on the elevated platform. Step on the platform by extending the hip and the knee of your right leg. Use the heel mainly to lift the rest of your body up and place the foot of the left leg on the platform as well. Breathe out as you execute the force required to come up.', 'Step down with the left leg by flexing the hip and knee of the right leg as you inhale. Return to the original standing position by placing the right foot of to next to the left foot on the initial position.', 'Repeat with the right leg for the recommended amount of repetitions and then perform with the left leg.']::text[], ARRAY['Dumbbell_Step_Ups/0.jpg', 'Dumbbell_Step_Ups/1.jpg']::text[], 'dumbbell step ups buoc buc ta don subida al cajon con mancuernas'),
  (NULL, 'Dumbbell Tricep Extension -Pronated Grip', 'Duỗi tay sau tạ đơn nắm úp', 'Dumbbell Tricep Extension -Pronated Grip', 'Extensión de tríceps con mancuernas agarre prono', 'triceps', 'dumbbell', 'isolation', 'free_exercise_db', 'Dumbbell_Tricep_Extension_-Pronated_Grip', ARRAY['Lie down on a flat bench holding two dumbbells directly above your shoulders. Your arms should be fully extended and form a 90 degree angle from your torso and the floor.', 'The palms of your hands should be facing forward, and your elbows should be tucked in. This will be your starting position.', 'Now, inhale and slowly lower the dumbbells until they are near your ears. Be sure to keep your upper arms stationary and your elbows tucked in.', 'Then, exhale and use your triceps to return the weight to the starting position.']::text[], ARRAY['Dumbbell_Tricep_Extension_-Pronated_Grip/0.jpg', 'Dumbbell_Tricep_Extension_-Pronated_Grip/1.jpg']::text[], 'dumbbell tricep extension -pronated grip duoi tay sau ta don nam up extension de triceps con mancuernas agarre prono'),
  (NULL, 'Dynamic Back Stretch', 'Giãn lưng động', 'Dynamic Back Stretch', 'Estiramiento dinámico de espalda', 'back', 'other', 'timed', 'free_exercise_db', 'Dynamic_Back_Stretch', ARRAY['Stand with your feet shoulder width apart. This will be your starting position.', 'Keeping your arms straight, swing them straight up in front of you 5-10 times, increasing the range of motion each time until your arms are above your head.']::text[], ARRAY['Dynamic_Back_Stretch/0.jpg', 'Dynamic_Back_Stretch/1.jpg']::text[], 'dynamic back stretch gian lung dong estiramiento dinamico de espalda'),
  (NULL, 'Dynamic Chest Stretch', 'Giãn ngực động', 'Dynamic Chest Stretch', 'Estiramiento dinámico de pecho', 'chest', 'other', 'timed', 'free_exercise_db', 'Dynamic_Chest_Stretch', ARRAY['Stand with your hands together, arms extended directly in front of you. This will be your starting position.', 'Keeping your arms straight, quickly move your arms back as far as possible and back in again, similar to an exaggerated clapping motion. Repeat 5-10 times, increasing speed as you do so.']::text[], ARRAY['Dynamic_Chest_Stretch/0.jpg', 'Dynamic_Chest_Stretch/1.jpg']::text[], 'dynamic chest stretch gian nguc dong estiramiento dinamico de pecho'),
  (NULL, 'EZ-Bar Curl', 'EZ-Bar Curl', 'EZ-Bar Curl', 'Curl con barra EZ', 'biceps', 'ez bar', 'isolation', 'free_exercise_db', 'EZ-Bar_Curl', ARRAY['Stand up straight while holding an EZ curl bar at the wide outer handle. The palms of your hands should be facing forward and slightly tilted inward due to the shape of the bar. Keep your elbows close to your torso. This will be your starting position.', 'Now, while keeping your upper arms stationary, exhale and curl the weights forward while contracting the biceps. Focus on only moving your forearms.', 'Continue to raise the weight until your biceps are fully contracted and the bar is at shoulder level. Hold the top contracted position for a moment and squeeze the biceps.', 'Then inhale and slowly lower the bar back to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['EZ-Bar_Curl/0.jpg', 'EZ-Bar_Curl/1.jpg']::text[], 'ez-bar curl cuon thanh ez curl con barra ez'),
  (NULL, 'EZ-Bar Skullcrusher', 'EZ-Bar Skullcrusher', 'EZ-Bar Skullcrusher', 'Rompecráneos con barra EZ', 'triceps', 'ez bar', 'isolation', 'free_exercise_db', 'EZ-Bar_Skullcrusher', ARRAY['Using a close grip, lift the EZ bar and hold it with your elbows in as you lie on the bench. Your arms should be perpendicular to the floor. This will be your starting position.', 'Keeping the upper arms stationary, lower the bar by allowing the elbows to flex. Inhale as you perform this portion of the movement. Pause once the bar is directly above the forehead.', 'Lift the bar back to the starting position by extending the elbow and exhaling.', 'Repeat.']::text[], ARRAY['EZ-Bar_Skullcrusher/0.jpg', 'EZ-Bar_Skullcrusher/1.jpg']::text[], 'ez-bar skullcrusher skull crusher thanh ez rompecraneos con barra ez'),
  (NULL, 'Elbow Circles', 'Xoay khuỷu tay', 'Elbow Circles', 'Círculos de codo', 'shoulders', 'other', 'timed', 'free_exercise_db', 'Elbow_Circles', ARRAY['Sit or stand with your feet slightly apart.', 'Place your hands on your shoulders with your elbows at shoulder level and pointing out.', 'Slowly make a circle with your elbows. Breathe out as you start the circle and breathe in as you complete the circle.']::text[], ARRAY['Elbow_Circles/0.jpg', 'Elbow_Circles/1.jpg']::text[], 'elbow circles xoay khuyu tay circulos de codo'),
  (NULL, 'Elbow to Knee', 'Khuỷu tay chạm gối', 'Elbow to Knee', 'Codo a rodilla', 'abs', 'bodyweight', 'bodyweight', 'free_exercise_db', 'Elbow_to_Knee', ARRAY['Lie on the floor, crossing your right leg across your bent left knee. Clasp your hands behind your head, beginning with your shoulder blades on the ground. This will be your starting position.', 'Perform the motion by flexing the spine and rotating your torso to bring the left elbow to the right knee.', 'Return to the starting position and repeat the movement for the desired number of repetitions before switching sides.']::text[], ARRAY['Elbow_to_Knee/0.jpg', 'Elbow_to_Knee/1.jpg']::text[], 'elbow to knee khuyu tay cham goi codo a rodilla'),
  (NULL, 'Elbows Back', 'Kéo khuỷu tay ra sau', 'Elbows Back', 'Codos hacia atrás', 'chest', 'other', 'timed', 'free_exercise_db', 'Elbows_Back', ARRAY['Stand up straight.', 'Place both hands on your lower back, fingers pointing downward and elbows out.', 'Then gently pull your elbows back aiming to touch them together.']::text[], ARRAY['Elbows_Back/0.jpg', 'Elbows_Back/1.jpg']::text[], 'elbows back keo khuyu tay ra sau codos hacia atras'),
  (NULL, 'Elevated Back Lunge', 'Elevated Back Lunge', 'Elevated Back Lunge', 'Zancada inversa elevada', 'legs', 'barbell', 'compound', 'free_exercise_db', 'Elevated_Back_Lunge', ARRAY['Position a bar onto a rack at shoulder height loaded to an appropriate weight. Place a short, raised platform behind you.', 'Rack the bar onto your upper back, keeping your back arched and tight. Step onto your raised platform with both feet. This will be your starting position.', 'Begin by stepping backwards with one leg. Descend by flexing your hips and knees until your knee touches the floor.', 'Pause, and extend through the hips and knees to rise up, returning all the way to the starting position before alternating.']::text[], ARRAY['Elevated_Back_Lunge/0.jpg', 'Elevated_Back_Lunge/1.jpg']::text[], 'elevated back lunge chung chan lui tren buc zancada inversa elevada'),
  (NULL, 'Elevated Cable Rows', 'Chèo cáp đứng trên bục', 'Elevated Cable Rows', 'Remo en polea elevado', 'back', 'cable', 'compound', 'free_exercise_db', 'Elevated_Cable_Rows', ARRAY['Get a platform of some sort (it can be an aerobics or calf raise platform) that is around 4-6 inches in height.', 'Place it on the seat of the cable row machine.', 'Sit down on the machine and place your feet on the front platform or crossbar provided making sure that your knees are slightly bent and not locked.', 'Lean over as you keep the natural alignment of your back and grab the V-bar handles.', 'With your arms extended pull back until your torso is at a 90-degree angle from your legs. Your back should be slightly arched and your chest should be sticking out. You should be feeling a nice stretch on your lats as you hold the bar in front of you. This is the starting position of the exercise.', 'Keeping the torso stationary, pull the handles back towards your torso while keeping the arms close to it until you touch the abdominals. Breathe out as you perform that movement. At that point you should be squeezing your back muscles hard. Hold that contraction for a second and slowly go back to the original position while breathing in.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Elevated_Cable_Rows/0.jpg', 'Elevated_Cable_Rows/1.jpg']::text[], 'elevated cable rows cheo cap dung tren buc remo en polea elevado'),
  (NULL, 'Elliptical Trainer', 'Máy elliptical', 'Elliptical Trainer', 'Elíptica', 'cardio', 'machine', 'timed', 'free_exercise_db', 'Elliptical_Trainer', ARRAY['To begin, step onto the elliptical and select the desired option from the menu. Most ellipticals have a manual setting, or you can select a program to run. Typically, you can enter your age and weight to estimate the amount of calories burned during exercise. Elevation can be adjusted to change the intensity of the workout.', 'The handles can be used to monitor your heart rate to help you stay at an appropriate intensity.']::text[], ARRAY['Elliptical_Trainer/0.jpg', 'Elliptical_Trainer/1.jpg']::text[], 'elliptical trainer may elliptical eliptica'),
  (NULL, 'Exercise Ball Crunch', 'Exercise Ball Crunch', 'Exercise Ball Crunch', 'Crunch en fitball', 'abs', 'exercise ball', 'isolation', 'free_exercise_db', 'Exercise_Ball_Crunch', ARRAY['Lie on an exercise ball with your lower back curvature pressed against the spherical surface of the ball. Your feet should be bent at the knee and pressed firmly against the floor. The upper torso should be hanging off the top of the ball. The arms should either be kept alongside the body or crossed on top of your chest as these positions avoid neck strains (as opposed to the hands behind the back of the head position).', 'Lower your torso into a stretch position keeping the neck stationary at all times. This will be your starting position.', 'With the hips stationary, flex the waist by contracting the abdominals and curl the shoulders and trunk upward until you feel a nice contraction on your abdominals. The arms should simply slide up the side of your legs if you have them at the side or just stay on top of your chest if you have them crossed. The lower back should always stay in contact with the ball. Exhale as you perform this movement and hold the contraction for a second.', 'As you inhale, go back to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Exercise_Ball_Crunch/0.jpg', 'Exercise_Ball_Crunch/1.jpg']::text[], 'exercise ball crunch gap bung tren bong tap crunch en fitball'),
  (NULL, 'Exercise Ball Pull-In', 'Kéo gối trên bóng tập', 'Exercise Ball Pull-In', 'Encogimiento de rodillas en fitball', 'abs', 'exercise ball', 'compound', 'free_exercise_db', 'Exercise_Ball_Pull-In', ARRAY['Place an exercise ball nearby and lay on the floor in front of it with your hands on the floor shoulder width apart in a push-up position.', 'Now place your lower shins on top of an exercise ball. Tip: At this point your legs should be fully extended with the shins on top of the ball and the upper body should be in a push-up type of position being supported by your two extended arms in front of you. This will be your starting position.', 'While keeping your back completely straight and the upper body stationary, pull your knees in towards your chest as you exhale, allowing the ball to roll forward under your ankles. Squeeze your abs and hold that position for a second.', 'Now slowly straighten your legs, rolling the ball back to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Exercise_Ball_Pull-In/0.jpg', 'Exercise_Ball_Pull-In/1.jpg']::text[], 'exercise ball pull-in keo goi tren bong tap encogimiento de rodillas en fitball'),
  (NULL, 'Extended Range One-Arm Kettlebell Floor Press', 'Đẩy sàn kettlebell một tay biên độ rộng', 'Extended Range One-Arm Kettlebell Floor Press', 'Press en el suelo a una mano con pesa rusa rango amplio', 'chest', 'kettlebell', 'compound', 'free_exercise_db', 'Extended_Range_One-Arm_Kettlebell_Floor_Press', ARRAY['Lie on the floor and position a kettlebell for one arm to press. The kettlebell should be held by the handle. The leg on the same side that you are pressing should be bent, with the knee crossing over the midline of the body.', 'Press the kettlebell by extending the elbow and adducting the arm, pressing it above your body. Return to the starting position.']::text[], ARRAY['Extended_Range_One-Arm_Kettlebell_Floor_Press/0.jpg', 'Extended_Range_One-Arm_Kettlebell_Floor_Press/1.jpg']::text[], 'extended range one-arm kettlebell floor press day san kettlebell mot tay bien do rong press en el suelo a una mano con pesa rusa rango amplio'),
  (NULL, 'External Rotation', 'Xoay vai ngoài', 'External Rotation', 'Rotación externa', 'shoulders', 'dumbbell', 'isolation', 'free_exercise_db', 'External_Rotation', ARRAY['Lie sideways on a flat bench with one arm holding a dumbbell and the other hand on top of the bench folded so that you can rest your head on it.', 'Bend the elbows of the arm holding the dumbbell so that it creates a 90-degree angle between the upper arm and the forearm. Tip: Keep the arm parallel to your torso.', 'Now bend the elbow while keeping the upper arm stationary. In this manner, the forearm will be parallel to the floor and perpendicular to your torso (Tip: So the forearm will be directly in front of you). The upper arm will be stationary by your torso and should be parallel to the floor (aligned with your torso at all times). This will be your starting position.', 'As you breathe out, externally rotate your forearm so that the dumbbell is lifted up in a semicircle motion as you maintain the 90 degree angle bend between the upper arms and the forearm. You will continue this external rotation until the forearm is perpendicular to the floor and the torso pointing towards the ceiling. At this point you will hold the contraction for a second.', 'As you breathe in, slowly go back to the starting position.', 'Repeat for the recommended amount of repetitions and then switch to the other arm.']::text[], ARRAY['External_Rotation/0.jpg', 'External_Rotation/1.jpg']::text[], 'external rotation xoay vai ngoai rotacion externa'),
  (NULL, 'External Rotation with Band', 'Xoay vai ngoài dây kháng lực', 'External Rotation with Band', 'Rotación externa con banda', 'shoulders', 'band', 'compound', 'free_exercise_db', 'External_Rotation_with_Band', ARRAY['Choke the band around a post. The band should be at the same height as your elbow. Stand with your left side to the band a couple of feet away.', 'Grasp the end of the band with your right hand, and keep your elbow pressed firmly to your side. We recommend you hold a pad or foam roll in place with your elbow to keep it firmly in position.', 'With your upper arm in position, your elbow should be flexed to 90 degrees with your hand reaching across the front of your torso. This will be your starting position.', 'Execute the movement by rotating your arm in a backhand motion, keeping your elbow in place.', 'Continue as far as you are able, pause, and then return to the starting position.']::text[], ARRAY['External_Rotation_with_Band/0.jpg', 'External_Rotation_with_Band/1.jpg']::text[], 'external rotation with band xoay vai ngoai day khang luc rotacion externa con banda'),
  (NULL, 'External Rotation with Cable', 'Xoay vai ngoài cáp', 'External Rotation with Cable', 'Rotación externa en polea', 'shoulders', 'cable', 'isolation', 'free_exercise_db', 'External_Rotation_with_Cable', ARRAY['Adjust the cable to the same height as your elbow. Stand with your left side to the band a couple of feet away.', 'Grasp the handle with your right hand, and keep your elbow pressed firmly to your side. We recommend you hold a pad or foam roll in place with your elbow to keep it firmly in position.', 'With your upper arm in position, your elbow should be flexed to 90 degrees with your hand reaching across the front of your torso. This will be your starting position.', 'Execute the movement by rotating your arm in a backhand motion, keeping your elbow in place.']::text[], ARRAY['External_Rotation_with_Cable/0.jpg', 'External_Rotation_with_Cable/1.jpg']::text[], 'external rotation with cable xoay vai ngoai cap rotacion externa en polea'),
  (NULL, 'Face Pull', 'Face Pull', 'Face Pull', 'Face pull', 'shoulders', 'cable', 'compound', 'free_exercise_db', 'Face_Pull', ARRAY['Facing a high pulley with a rope or dual handles attached, pull the weight directly towards your face, separating your hands as you do so. Keep your upper arms parallel to the ground.']::text[], ARRAY['Face_Pull/0.jpg', 'Face_Pull/1.jpg']::text[], 'face pull keo cap ve mat (face pull) face pull'),
  (NULL, 'Farmer''s Walk', 'Farmer''s Walk', 'Farmer''s Walk', 'Paseo del granjero', 'biceps', 'other', 'compound', 'free_exercise_db', 'Farmers_Walk', ARRAY['There are various implements that can be used for the farmers walk. These can also be performed with heavy dumbbells or short bars if these implements aren''t available. Begin by standing between the implements.', 'After gripping the handles, lift them up by driving through your heels, keeping your back straight and your head up.', 'Walk taking short, quick steps, and don''t forget to breathe. Move for a given distance, typically 50-100 feet, as fast as possible.']::text[], ARRAY['Farmers_Walk/0.jpg', 'Farmers_Walk/1.jpg']::text[], 'farmer''s walk xach ta di bo paseo del granjero'),
  (NULL, 'Fast Skipping', 'Nhảy chân sáo nhanh', 'Fast Skipping', 'Saltos rápidos', 'legs', 'bodyweight', 'bodyweight', 'free_exercise_db', 'Fast_Skipping', ARRAY['Start in a relaxed position with one leg slightly forward. This will be your starting position.', 'Skip by executing a step-hop pattern of right-right-step to left-left-step, and so on, alternating back and forth.', 'Perform fast skips by maintaining close contact with the ground and reduce air time, moving as quickly as possible.']::text[], ARRAY['Fast_Skipping/0.jpg', 'Fast_Skipping/1.jpg']::text[], 'fast skipping nhay chan sao nhanh saltos rapidos'),
  (NULL, 'Finger Curls', 'Finger Curls', 'Finger Curls', 'Curl de dedos con barra', 'biceps', 'barbell', 'isolation', 'free_exercise_db', 'Finger_Curls', ARRAY['Hold a barbell with both hands and your palms facing up; hands spaced about shoulder width.', 'Place your feet flat on the floor, at a distance that is slightly wider than shoulder width apart. This will be your starting position.', 'Lower the bar as far as possible by extending the fingers. Allowing the bar to roll down the hands, catch the bar with the final joint in the fingers.', 'Now curl bar up as high as possible by closing your hands while exhaling. Hold the contraction at the top.']::text[], ARRAY['Finger_Curls/0.jpg', 'Finger_Curls/1.jpg']::text[], 'finger curls cuon ngon tay ta don curl de dedos con barra'),
  (NULL, 'Flat Bench Cable Flyes', 'Flat Bench Cable Flyes', 'Flat Bench Cable Flyes', 'Aperturas en polea en banco plano', 'chest', 'cable', 'isolation', 'free_exercise_db', 'Flat_Bench_Cable_Flyes', ARRAY['Position a flat bench between two low pulleys so that when you are laying on it, your chest will be lined up with the cable pulleys.', 'Lay flat on the bench and keep your feet on the ground.', 'Have someone hand you the handles on each hand. You will grab each single handle attachment with a palms up grip.', 'Extend your arms by your side with a slight bend on your elbows. Tip: You will keep this bend constant through the whole movement. Your arms should be parallel to the floor. This is your starting position.', 'Now start lifting the arms in a semi-circle motion directly in front of you by pulling the cables together until both hands meet at the top of the movement. Squeeze your chest as you perform this motion and breathe out during this movement. Also, hold the contraction for a second at the top. Tip: When performed correctly, at the top position of this movement, your arms should be perpendicular to your torso and the floor touching above your chest.', 'Slowly come back to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Flat_Bench_Cable_Flyes/0.jpg', 'Flat_Bench_Cable_Flyes/1.jpg']::text[], 'flat bench cable flyes ep nguc cap ghe phang aperturas en polea en banco plano'),
  (NULL, 'Flat Bench Leg Pull-In', 'Kéo gối trên ghế phẳng', 'Flat Bench Leg Pull-In', 'Encogimiento de piernas en banco plano', 'abs', 'bodyweight', 'bodyweight', 'free_exercise_db', 'Flat_Bench_Leg_Pull-In', ARRAY['Lie on an exercise mat or a flat bench with your legs off the end.', 'Place your hands either under your glutes with your palms down or by the sides holding on to the bench (or with palms down by the side on an exercise mat). Also extend your legs straight out. This will be your starting position.', 'Bend your knees and pull your upper thighs into your midsection as you breathe out. Continue this movement until your knees are near your chest. Hold the contracted position for a second.', 'As you breathe in, slowly return to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Flat_Bench_Leg_Pull-In/0.jpg', 'Flat_Bench_Leg_Pull-In/1.jpg']::text[], 'flat bench leg pull-in keo goi tren ghe phang encogimiento de piernas en banco plano'),
  (NULL, 'Flat Bench Lying Leg Raise', 'Nâng chân nằm ghế phẳng', 'Flat Bench Lying Leg Raise', 'Elevación de piernas tumbado en banco plano', 'abs', 'bodyweight', 'bodyweight', 'free_exercise_db', 'Flat_Bench_Lying_Leg_Raise', ARRAY['Lie with your back flat on a bench and your legs extended in front of you off the end.', 'Place your hands either under your glutes with your palms down or by the sides holding on to the bench. This will be your starting position.', 'As you keep your legs extended, straight as possible with your knees slightly bent but locked raise your legs until they make a 90-degree angle with the floor. Exhale as you perform this portion of the movement and hold the contraction at the top for a second.', 'Now, as you inhale, slowly lower your legs back down to the starting position.']::text[], ARRAY['Flat_Bench_Lying_Leg_Raise/0.jpg', 'Flat_Bench_Lying_Leg_Raise/1.jpg']::text[], 'flat bench lying leg raise nang chan nam ghe phang elevacion de piernas tumbado en banco plano'),
  (NULL, 'Flexor Incline Dumbbell Curls', 'Flexor Incline Dumbbell Curls', 'Flexor Incline Dumbbell Curls', 'Curl inclinado con mancuernas para flexores', 'biceps', 'dumbbell', 'isolation', 'free_exercise_db', 'Flexor_Incline_Dumbbell_Curls', ARRAY['Hold the dumbbell towards the side farther from you so that you have more weight on the side closest to you. (This can be done for a good effect on all bicep dumbbell exercises). Now do a normal incline dumbbell curl, but keep your wrists as far back as possible so as to neutralize any stress that is placed on them.', 'Sit on an incline bench that is angled at 45-degrees while holding a dumbbell on each hand.', 'Let your arms hang down on your sides, with the elbows in, and turn the palms of your hands forward with the thumbs pointing away from the body. Tip: You will keep this hand position throughout the movement as there should not be any twisting of the hands as they come up. This will be your starting position.', 'Curl up the two dumbbells at the same time until your biceps are fully contracted and exhale. Tip: Do not swing the arms or use momentum. Keep a controlled motion at all times. Hold the contracted position for a second at the top.', 'As you inhale, slowly go back to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Flexor_Incline_Dumbbell_Curls/0.jpg', 'Flexor_Incline_Dumbbell_Curls/1.jpg']::text[], 'flexor incline dumbbell curls cuon ta don ghe doc (co gap) curl inclinado con mancuernas para flexores'),
  (NULL, 'Floor Glute-Ham Raise', 'Nâng thân đùi sau trên sàn', 'Floor Glute-Ham Raise', 'Glute-ham en el suelo', 'legs', 'other', 'bodyweight', 'free_exercise_db', 'Floor_Glute-Ham_Raise', ARRAY['You can use a partner for this exercise or brace your feet under something stable.', 'Begin on your knees with your upper legs and torso upright. If using a partner, they will firmly hold your feet to keep you in position. This will be your starting position.', 'Lower yourself by extending at the knee, taking care to NOT flex the hips as you go forward.', 'Place your hands in front of you as you reach the floor. This movement is very difficult and you may be unable to do it unaided. Use your arms to lightly push off the floor to aid your return to the starting position.']::text[], ARRAY['Floor_Glute-Ham_Raise/0.jpg', 'Floor_Glute-Ham_Raise/1.jpg']::text[], 'floor glute-ham raise nang than dui sau tren san glute-ham en el suelo'),
  (NULL, 'Floor Press', 'Đẩy sàn tạ đòn', 'Floor Press', 'Press en el suelo con barra', 'triceps', 'barbell', 'compound', 'free_exercise_db', 'Floor_Press', ARRAY['Adjust the j-hooks so they are at the appropriate height to rack the bar. Begin lying on the floor with your head near the end of a power rack. Keeping your shoulder blades pulled together; pull the bar off of the hooks.', 'Lower the bar towards the bottom of your chest or upper stomach, squeezing the bar and attempting to pull it apart as you do so. Ensure that you tuck your elbows throughout the movement. Lower the bar until your upper arm contacts the ground and pause, preventing any slamming or bouncing of the weight.', 'Press the bar back up as fast as you can, keeping the bar, your wrists, and elbows in line as you do so.']::text[], ARRAY['Floor_Press/0.jpg', 'Floor_Press/1.jpg']::text[], 'floor press day san ta don press en el suelo con barra'),
  (NULL, 'Floor Press with Chains', 'Đẩy sàn tạ đòn có xích', 'Floor Press with Chains', 'Press en el suelo con cadenas', 'triceps', 'barbell', 'compound', 'free_exercise_db', 'Floor_Press_with_Chains', ARRAY['Adjust the j-hooks so they are at the appropriate height to rack the bar. For this exercise, drape the chains directly over the end of the bar, trying to keep the ends away from the plates.', 'Begin lying on the floor with your head near the end of a power rack. Keeping your shoulder blades pulled together, pull the bar off of the hooks.', 'Lower the bar towards the bottom of your chest or upper stomach, squeezing the bar and attempting to pull it apart as you do so. Ensure that you tuck your elbows throughout the movement. Lower the bar until your upper arm contacts the ground and pause, preventing any slamming or bouncing of the weight.', 'Press the bar back up as fast as you can, keeping the bar, your wrists, and elbows in line as you do so.']::text[], ARRAY['Floor_Press_with_Chains/0.jpg', 'Floor_Press_with_Chains/1.jpg']::text[], 'floor press with chains day san ta don co xich press en el suelo con cadenas'),
  (NULL, 'Flutter Kicks', 'Đá chân vẫy', 'Flutter Kicks', 'Patadas de aleteo', 'glutes', 'bodyweight', 'bodyweight', 'free_exercise_db', 'Flutter_Kicks', ARRAY['On a flat bench lie facedown with the hips on the edge of the bench, the legs straight with toes high off the floor and with the arms on top of the bench holding on to the front edge.', 'Squeeze your glutes and hamstrings and straighten the legs until they are level with the hips. This will be your starting position.', 'Start the movement by lifting the left leg higher than the right leg.', 'Then lower the left leg as you lift the right leg.', 'Continue alternating in this manner (as though you are doing a flutter kick in water) until you have done the recommended amount of repetitions for each leg. Make sure that you keep a controlled movement at all times. Tip: You will breathe normally as you perform this movement.']::text[], ARRAY['Flutter_Kicks/0.jpg', 'Flutter_Kicks/1.jpg']::text[], 'flutter kicks da chan vay patadas de aleteo'),
  (NULL, 'Foot-SMR', 'Lăn giãn lòng bàn chân', 'Foot-SMR', 'Liberación de la planta del pie', 'calves', 'other', 'timed', 'free_exercise_db', 'Foot-SMR', ARRAY['This exercise stretches the fascia of the muscles in the feet. Start off seated with your shoes removed. Using a foot roller or a similar object, such as a small section of pvc pipe, place your foot against the roller across the arch of your foot. This will be your starting position.', 'Press down firmly, rolling across the arch of your foot. Hold for 10-30 seconds, and then switch feet.']::text[], ARRAY['Foot-SMR/0.jpg', 'Foot-SMR/1.jpg']::text[], 'foot-smr lan gian long ban chan liberacion de la planta del pie'),
  (NULL, 'Forward Drag with Press', 'Kéo xe tiến kèm đẩy', 'Forward Drag with Press', 'Arrastre hacia delante con press', 'chest', 'other', 'compound', 'free_exercise_db', 'Forward_Drag_with_Press', ARRAY['Attach a dual handled chain or rope attachment to the sled. You should be facing away from the sled, holding a handle in each hand.', 'Begin the movement by moving forward for one step. Leaning forward, extend through the legs and hips to move, pausing with each step to extend through the elbows, pressing your hands forward. Step forward until you return to the start position prepared to press.']::text[], ARRAY['Forward_Drag_with_Press/0.jpg', 'Forward_Drag_with_Press/1.jpg']::text[], 'forward drag with press keo xe tien kem day arrastre hacia delante con press'),
  (NULL, 'Frankenstein Squat', 'Frankenstein Squat', 'Frankenstein Squat', 'Sentadilla Frankenstein', 'legs', 'barbell', 'compound', 'free_exercise_db', 'Frankenstein_Squat', ARRAY['This drill teaches you the proper positioning of both the bar and your body during the clean and front squat.', 'Place the barbell on the front of the shoulders, releasing your grip and extending your arms out in front of you. The shoulders should be pushed forward to create a shelf, and the bar should be in contact with the throat. Ensure that you only move your shoulder blades forward; don''t round the thoracic spine.', 'Squat by flexing the knees and hips, sitting in between your legs. Keep the torso upright, the arms up, and the shoulders forward, and the bar should stay in place. Go to the bottom of the squat, until your hamstrings contact your calves.', 'Return to the upright position by driving through the front of the heel and extending the knees and hips.']::text[], ARRAY['Frankenstein_Squat/0.jpg', 'Frankenstein_Squat/1.jpg']::text[], 'frankenstein squat squat frankenstein sentadilla frankenstein'),
  (NULL, 'Freehand Jump Squat', 'Freehand Jump Squat', 'Freehand Jump Squat', 'Sentadilla con salto sin peso', 'legs', 'bodyweight', 'bodyweight', 'free_exercise_db', 'Freehand_Jump_Squat', ARRAY['Cross your arms over your chest.', 'With your head up and your back straight, position your feet at shoulder width.', 'Keeping your back straight and chest up, squat down as you inhale until your upper thighs are parallel, or lower, to the floor.', 'Now pressing mainly with the ball of your feet, jump straight up in the air as high as possible, using the thighs like springs. Exhale during this portion of the movement.', 'When you touch the floor again, immediately squat down and jump again.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Freehand_Jump_Squat/0.jpg', 'Freehand_Jump_Squat/1.jpg']::text[], 'freehand jump squat squat bat nhay tay khong sentadilla con salto sin peso'),
  (NULL, 'Frog Hops', 'Bật nhảy ếch', 'Frog Hops', 'Saltos de rana', 'legs', 'other', 'timed', 'free_exercise_db', 'Frog_Hops', ARRAY['Stand with your hands behind your head, and squat down keeping your torso upright and your head up. This will be your starting position.', 'Jump forward several feet, avoiding jumping unnecessarily high. As your feet contact the ground, absorb the impact through your legs, and jump again. Repeat this action 5-10 times.']::text[], ARRAY['Frog_Hops/0.jpg', 'Frog_Hops/1.jpg']::text[], 'frog hops bat nhay ech saltos de rana'),
  (NULL, 'Frog Sit-Ups', 'Gập bụng tư thế ếch', 'Frog Sit-Ups', 'Abdominales de rana', 'abs', 'bodyweight', 'bodyweight', 'free_exercise_db', 'Frog_Sit-Ups', ARRAY['Lie with your back flat on the floor (or exercise mat) and your legs extended in front of you.', 'Now bend at the knees and place your outer thighs by the floor (or mat) as you make the soles of your feet touch each other.', 'Now try pushing both soles and bringing them up as near you as possible while you keep the outer thighs on the floor (or at least almost touching it). Tip: In this position your legs should create a diamond shape.', 'Now, cross your arms in front of you by touching the opposite shoulders. This will be your starting position.', 'As you exhale flatten your lower back to the floor while curling the torso upwards. Tip: This will be like performing the first 1/4 movement of a sit up. Hold at the top position for a second.', 'As you inhale, slowly lower back to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Frog_Sit-Ups/0.jpg', 'Frog_Sit-Ups/1.jpg']::text[], 'frog sit-ups gap bung tu the ech abdominales de rana'),
  (NULL, 'Front Barbell Squat', 'Front Barbell Squat', 'Front Barbell Squat', 'Sentadilla frontal con barra', 'legs', 'barbell', 'compound', 'free_exercise_db', 'Front_Barbell_Squat', ARRAY['This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, bring your arms up under the bar while keeping the elbows high and the upper arm slightly above parallel to the floor. Rest the bar on top of the deltoids and cross your arms while grasping the bar for total control.', 'Lift the bar off the rack by first pushing with your legs and at the same time straightening your torso.', 'Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance and also maintain a straight back. This will be your starting position. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances described in the foot positioning section).', 'Begin to slowly lower the bar by bending the knees as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to the floor). Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.', 'Begin to raise the bar as you exhale by pushing the floor mainly with the middle of your foot as you straighten the legs again and go back to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Front_Barbell_Squat/0.jpg', 'Front_Barbell_Squat/1.jpg']::text[], 'front barbell squat squat truoc ta don sentadilla frontal con barra'),
  (NULL, 'Front Barbell Squat To A Bench', 'Front Barbell Squat To A Bench', 'Front Barbell Squat To A Bench', 'Sentadilla frontal con barra al banco', 'legs', 'barbell', 'compound', 'free_exercise_db', 'Front_Barbell_Squat_To_A_Bench', ARRAY['This exercise is best performed inside a squat rack for safety purposes. To begin, first set a flat bench behind you and set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, bring your arms up under the bar while keeping the elbows high and the upper arm slightly above parallel to the floor. Rest the bar on top of the deltoids and cross your arms while grasping the bar for total control.', 'Lift the bar off the rack by first pushing with your legs and at the same time straightening your torso.', 'Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance and also maintain a straight back. This will be your starting position. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances described in the foot positioning section).', 'Begin to slowly lower the bar by bending the knees as you maintain a straight posture with the head up. Continue down until you touch the bench with your glutes. Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.', 'Begin to raise the bar as you exhale by pushing the floor mainly with the heel of your foot as you straighten the legs again and go back to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Front_Barbell_Squat_To_A_Bench/0.jpg', 'Front_Barbell_Squat_To_A_Bench/1.jpg']::text[], 'front barbell squat to a bench squat truoc ta don xuong ghe sentadilla frontal con barra al banco'),
  (NULL, 'Front Box Jump', 'Front Box Jump', 'Front Box Jump', 'Salto al cajón frontal', 'legs', 'other', 'compound', 'free_exercise_db', 'Front_Box_Jump', ARRAY['Begin with a box of an appropriate height 1-2 feet in front of you. Stand with your feet should width apart. This will be your starting position.', 'Perform a short squat in preparation for jumping, swinging your arms behind you.', 'Rebound out of this position, extending through the hips, knees, and ankles to jump as high as possible. Swing your arms forward and up.', 'Land on the box with the knees bent, absorbing the impact through the legs. You can jump from the box back to the ground, or preferably step down one leg at a time.']::text[], ARRAY['Front_Box_Jump/0.jpg', 'Front_Box_Jump/1.jpg']::text[], 'front box jump bat nhay len buc phia truoc salto al cajon frontal'),
  (NULL, 'Front Cable Raise', 'Nâng tạ trước cáp', 'Front Cable Raise', 'Elevación frontal en polea', 'shoulders', 'cable', 'isolation', 'free_exercise_db', 'Front_Cable_Raise', ARRAY['Select the weight on a low pulley machine and grasp the single hand cable attachment that is attached to the low pulley with your left hand.', 'Face away from the pulley and put your arm straight down with the hand cable attachment in front of your thighs at arms'' length with the palms of the hand facing your thighs. This will be your starting position.', 'While maintaining the torso stationary (no swinging), lift the left arm to the front with a slight bend on the elbow and the palms of the hand always faces down. Continue to go up until you arm is slightly above parallel to the floor. Exhale as you execute this portion of the movement and pause for a second at the top.', 'Now as you inhale lower the arm back down slowly to the starting position.', 'Once all of the recommended amount of repetitions have been performed for this arm, switch arms and perform the exercise with the right one.']::text[], ARRAY['Front_Cable_Raise/0.jpg', 'Front_Cable_Raise/1.jpg']::text[], 'front cable raise nang ta truoc cap elevacion frontal en polea'),
  (NULL, 'Front Cone Hops (or hurdle hops)', 'Bật nhảy qua cọc (hoặc rào)', 'Front Cone Hops (or hurdle hops)', 'Saltos de conos (o vallas)', 'legs', 'other', 'compound', 'free_exercise_db', 'Front_Cone_Hops_or_hurdle_hops', ARRAY['Set up a row of cones or other small barriers, placing them a few feet apart.', 'Stand in front of the first cone with your feet shoulder width apart. This will be your starting position.', 'Begin by jumping with both feet over the first cone, swinging both arms as you jump.', 'Absorb the impact of landing by bending the knees, rebounding out of the first leap by jumping over the next cone.', 'Continue until you have jumped over all of the cones.']::text[], ARRAY['Front_Cone_Hops_or_hurdle_hops/0.jpg', 'Front_Cone_Hops_or_hurdle_hops/1.jpg']::text[], 'front cone hops (or hurdle hops) bat nhay qua coc (hoac rao) saltos de conos (o vallas)'),
  (NULL, 'Front Dumbbell Raise', 'Nâng tạ trước tạ đơn', 'Front Dumbbell Raise', 'Elevación frontal con mancuerna', 'shoulders', 'dumbbell', 'isolation', 'free_exercise_db', 'Front_Dumbbell_Raise', ARRAY['Pick a couple of dumbbells and stand with a straight torso and the dumbbells on front of your thighs at arms length with the palms of the hand facing your thighs. This will be your starting position.', 'While maintaining the torso stationary (no swinging), lift the left dumbbell to the front with a slight bend on the elbow and the palms of the hands always facing down. Continue to go up until you arm is slightly above parallel to the floor. Exhale as you execute this portion of the movement and pause for a second at the top. Inhale after the second pause.', 'Now lower the dumbbell back down slowly to the starting position as you simultaneously lift the right dumbbell.', 'Continue alternating in this fashion until all of the recommended amount of repetitions have been performed for each arm.']::text[], ARRAY['Front_Dumbbell_Raise/0.jpg', 'Front_Dumbbell_Raise/1.jpg']::text[], 'front dumbbell raise nang ta truoc ta don elevacion frontal con mancuerna'),
  (NULL, 'Front Incline Dumbbell Raise', 'Nâng tạ trước tạ đơn ghế dốc', 'Front Incline Dumbbell Raise', 'Elevación frontal inclinado con mancuerna', 'shoulders', 'dumbbell', 'isolation', 'free_exercise_db', 'Front_Incline_Dumbbell_Raise', ARRAY['Sit down on an incline bench with the incline set anywhere between 30 to 60 degrees while holding a dumbbell on each hand. Tip: You can change the angle to hit the muscle a little differently each time.', 'Extend your arms straight in front of you and have your palms facing down with the dumbbells raised about 1 inch above your thighs. This will be your starting position.', 'Slowly raise the dumbbells straight up until they are slightly above your shoulders, while keeping your elbows locked. Squeeze at the top for a second and make sure you breathe out during this portion of the movement. Tip: Keep your head resting down against the bench and your legs on the floor at all times.', 'Lower the arms back to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Front_Incline_Dumbbell_Raise/0.jpg', 'Front_Incline_Dumbbell_Raise/1.jpg']::text[], 'front incline dumbbell raise nang ta truoc ta don ghe doc elevacion frontal inclinado con mancuerna'),
  (NULL, 'Front Leg Raises', 'Đá chân ra trước', 'Front Leg Raises', 'Elevaciones de pierna al frente', 'legs', 'bodyweight', 'timed', 'free_exercise_db', 'Front_Leg_Raises', ARRAY['Stand next to a chair or other support, holding on with one hand.', 'Swing your leg forward, keeping the leg straight. Continue with a downward swing, bringing the leg as far back as your flexibility allows. Repeat 5-10 times, and then switch legs.']::text[], ARRAY['Front_Leg_Raises/0.jpg', 'Front_Leg_Raises/1.jpg']::text[], 'front leg raises da chan ra truoc elevaciones de pierna al frente'),
  (NULL, 'Front Plate Raise', 'Nâng đĩa tạ trước', 'Front Plate Raise', 'Elevación frontal con disco', 'shoulders', 'other', 'isolation', 'free_exercise_db', 'Front_Plate_Raise', ARRAY['While standing straight, hold a barbell plate in both hands at the 3 and 9 o''clock positions. Your palms should be facing each other and your arms should be extended and locked with a slight bend at the elbows and the plate should be down near your waist in front of you as far as you can go. Tip: The arms will remain in this position throughout the exercise. This will be your starting position.', 'Slowly raise the plate as you exhale until it is a little above shoulder level. Hold the contraction for a second. Tip: make sure that you do not swing the weight or bend at the elbows. Your torso should remain stationary throughout the movement as well.', 'As you inhale, slowly lower the plate back down to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Front_Plate_Raise/0.jpg', 'Front_Plate_Raise/1.jpg']::text[], 'front plate raise nang dia ta truoc elevacion frontal con disco'),
  (NULL, 'Front Raise And Pullover', 'Front Raise And Pullover', 'Front Raise And Pullover', 'Elevación frontal y pullover', 'chest', 'barbell', 'compound', 'free_exercise_db', 'Front_Raise_And_Pullover', ARRAY['Lie on a flat bench while holding a barbell using a palms down grip that is about 15 inches apart.', 'Place the bar on your upper thighs, extend your arms and lock them while keeping a slight bend on the elbows. This will be your starting position.', 'Now raise the weight using a semicircular motion and keeping your arms straight as you inhale. Continue the same movement until the bar is on the other side above your head . (Tip: the bar will travel approximately 180-degrees). At this point your arms should be parallel to the floor with the palms of your hands facing the ceiling.', 'Now return the barbell to the starting position by reversing the motion as you exhale.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Front_Raise_And_Pullover/0.jpg', 'Front_Raise_And_Pullover/1.jpg']::text[], 'front raise and pullover nang ta truoc kem keo qua dau elevacion frontal y pullover'),
  (NULL, 'Front Squat (Clean Grip)', 'Front Squat (Clean Grip)', 'Front Squat (Clean Grip)', 'Sentadilla frontal (agarre de cargada)', 'legs', 'barbell', 'compound', 'free_exercise_db', 'Front_Squat_Clean_Grip', ARRAY['To begin, first set the bar in a rack slightly below shoulder level. Rest the bar on top of the deltoids, pushing into the clavicles, and lightly touching the throat. Your hands should be in a clean grip, touching the bar only with your fingers to help keep it in position.', 'Lift the bar off the rack by first pushing with your legs and at the same time straightening your torso. Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head and elbows up at all times. This will be your starting position.', 'Bend at the knees, sitting down between your legs. Continue down until your hamstrings are on your calves. Keep your knees aligned with your feet by consciously using your abductors to push your knees out as you squat.', 'Begin to raise the bar as you exhale by pushing the floor mainly with the heel or middle of your foot as you straighten the legs again and return to the starting position.']::text[], ARRAY['Front_Squat_Clean_Grip/0.jpg', 'Front_Squat_Clean_Grip/1.jpg']::text[], 'front squat (clean grip) squat truoc (nam kieu clean) sentadilla frontal (agarre de cargada)'),
  (NULL, 'Front Squats With Two Kettlebells', 'Front Squats With Two Kettlebells', 'Front Squats With Two Kettlebells', 'Sentadilla frontal con dos pesas rusas', 'legs', 'kettlebell', 'compound', 'free_exercise_db', 'Front_Squats_With_Two_Kettlebells', ARRAY['Clean two kettlebells to your shoulders. Clean the kettlebells to your shoulders by extending through the legs and hips as you pull the kettlebells towards your shoulders. Rotate your wrists as you do so.', 'Looking straight ahead at all times, squat as low as you can and pause at the bottom. As you squat down, push your knees out. You should squat between your legs, keeping an upright torso, with your head and chest up.', 'Rise back up by driving through your heels and repeat.']::text[], ARRAY['Front_Squats_With_Two_Kettlebells/0.jpg', 'Front_Squats_With_Two_Kettlebells/1.jpg']::text[], 'front squats with two kettlebells squat truoc hai kettlebell sentadilla frontal con dos pesas rusas'),
  (NULL, 'Front Two-Dumbbell Raise', 'Nâng tạ trước hai tạ đơn', 'Front Two-Dumbbell Raise', 'Elevación frontal con dos mancuernas', 'shoulders', 'dumbbell', 'isolation', 'free_exercise_db', 'Front_Two-Dumbbell_Raise', ARRAY['Pick a couple of dumbbells and stand with a straight torso and the dumbbells on front of your thighs at arms length with the palms of the hand facing your thighs. This will be your starting position.', 'While maintaining the torso stationary (no swinging), lift the dumbbells to the front with a slight bend on the elbow and the palms of the hands always facing down. Continue to go up until you arms are slightly above parallel to the floor. Exhale as you execute this portion of the movement and pause for a second at the top.', 'As you inhale, lower the dumbbells back down slowly to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Front_Two-Dumbbell_Raise/0.jpg', 'Front_Two-Dumbbell_Raise/1.jpg']::text[], 'front two-dumbbell raise nang ta truoc hai ta don elevacion frontal con dos mancuernas'),
  (NULL, 'Full Range-Of-Motion Lat Pulldown', 'Full Range-Of-Motion Lat Pulldown', 'Full Range-Of-Motion Lat Pulldown', 'Jalón al pecho rango completo', 'back', 'cable', 'compound', 'free_exercise_db', 'Full_Range-Of-Motion_Lat_Pulldown', ARRAY['Either standing or seated on a high bench, grasp two stirrup cables that are attached to the high pulleys. Grab with the opposing hand so your arms are crisscrossed about you and your palms are facing forward.', 'Keeping your chest up and maintaining a slight arch in your lower back, pull the handles down as if you were doing a regular pulldown. The range of motion will be more of an arc. During the movement, rotate your hands so that in the bottom position your palms face each other rather than forward. Return slowly to the starting position and repeat.']::text[], ARRAY['Full_Range-Of-Motion_Lat_Pulldown/0.jpg', 'Full_Range-Of-Motion_Lat_Pulldown/1.jpg']::text[], 'full range-of-motion lat pulldown keo xa xuong bien do day du jalon al pecho rango completo'),
  (NULL, 'Gironda Sternum Chins', 'Hít xà Gironda chạm ức', 'Gironda Sternum Chins', 'Dominadas Gironda al esternón', 'back', 'other', 'compound', 'free_exercise_db', 'Gironda_Sternum_Chins', ARRAY['Grasp the pull-up bar with a shoulder width underhand grip.', 'Now hang with your arms fully extended and stick your chest out and lean back. Tip: You will be leaning back throughout the entire movement. This will be your starting position.', 'Start pulling yourself towards the bar with your spine arched throughout the movement and your head leaning back as far away from the bar as possible. Exhale as you perform this portion of the movement. Tip: At the upper end of the movement, your hips and legs will be at about a 45-degree angle to the floor.', 'Keep pulling until your collarbone passes the bar and your lower chest or sternum area touches it. Hold that contraction for a second. Tip: By the time you''ve completed this portion of the movement; your head will be parallel to the floor.', 'Slowly start going back to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Gironda_Sternum_Chins/0.jpg', 'Gironda_Sternum_Chins/1.jpg']::text[], 'gironda sternum chins hit xa gironda cham uc dominadas gironda al esternon'),
  (NULL, 'Glute Ham Raise', 'Nâng thân đùi sau (máy)', 'Glute Ham Raise', 'Glute-ham en máquina', 'legs', 'machine', 'compound', 'free_exercise_db', 'Glute_Ham_Raise', ARRAY['Begin by adjusting the equipment to fit your body. Place your feet against the footplate in between the rollers as you lie facedown. Your knees should be just behind the pad.', 'Start from the bottom of the movement. Keep your back arched as you begin the movement by flexing the knees. Drive your toes into the foot plate as you do so. Keep your upper body straight, and continue until your body is upright.', 'Return to the starting position, keeping your descent under control.']::text[], ARRAY['Glute_Ham_Raise/0.jpg', 'Glute_Ham_Raise/1.jpg']::text[], 'glute ham raise nang than dui sau (may) glute-ham en maquina'),
  (NULL, 'Glute Kickback', 'Đá chân sau tập mông', 'Glute Kickback', 'Patada de glúteo', 'glutes', 'bodyweight', 'bodyweight', 'free_exercise_db', 'Glute_Kickback', ARRAY['Kneel on the floor or an exercise mat and bend at the waist with your arms extended in front of you (perpendicular to the torso) in order to get into a kneeling push-up position but with the arms spaced at shoulder width. Your head should be looking forward and the bend of the knees should create a 90-degree angle between the hamstrings and the calves. This will be your starting position.', 'As you exhale, lift up your right leg until the hamstrings are in line with the back while maintaining the 90-degree angle bend. Contract the glutes throughout this movement and hold the contraction at the top for a second. Tip: At the end of the movement the upper leg should be parallel to the floor while the calf should be perpendicular to it.', 'Go back to the initial position as you inhale and now repeat with the left leg.', 'Continue to alternate legs until all of the recommended repetitions have been performed.']::text[], ARRAY['Glute_Kickback/0.jpg', 'Glute_Kickback/1.jpg']::text[], 'glute kickback da chan sau tap mong patada de gluteo'),
  (NULL, 'Goblet Squat', 'Goblet Squat', 'Goblet Squat', 'Sentadilla goblet', 'legs', 'kettlebell', 'compound', 'free_exercise_db', 'Goblet_Squat', ARRAY['Stand holding a light kettlebell by the horns close to your chest. This will be your starting position.', 'Squat down between your legs until your hamstrings are on your calves. Keep your chest and head up and your back straight.', 'At the bottom position, pause and use your elbows to push your knees out. Return to the starting position, and repeat for 10-20 repetitions.']::text[], ARRAY['Goblet_Squat/0.jpg', 'Goblet_Squat/1.jpg']::text[], 'goblet squat squat goblet sentadilla goblet'),
  (NULL, 'Good Morning', 'Good Morning', 'Good Morning', 'Buenos días', 'legs', 'barbell', 'compound', 'free_exercise_db', 'Good_Morning', ARRAY['Begin with a bar on a rack at shoulder height. Rack the bar across the rear of your shoulders as you would a power squat, not on top of your shoulders. Keep your back tight, shoulder blades pinched together, and your knees slightly bent. Step back from the rack.', 'Begin by bending at the hips, moving them back as you bend over to near parallel. Keep your back arched and your cervical spine in proper alignment.', 'Reverse the motion by extending through the hips with your glutes and hamstrings. Continue until you have returned to the starting position.']::text[], ARRAY['Good_Morning/0.jpg', 'Good_Morning/1.jpg']::text[], 'good morning good morning buenos dias'),
  (NULL, 'Good Morning off Pins', 'Good Morning off Pins', 'Good Morning off Pins', 'Buenos días desde soportes', 'legs', 'barbell', 'compound', 'free_exercise_db', 'Good_Morning_off_Pins', ARRAY['Begin with a bar on a rack at about the same height as your stomach. Bend over underneath the bar and rack the bar across the rear of your shoulders as you would a power squat, not on top of your shoulders. At the proper height, you should be near parallel to the floor when bent over. Keep your back tight, shoulder blades pinched together, and your knees slightly bent. Keep your back arched and your cervical spine in proper alignment.', 'Begin the motion by extending through the hips with your glutes and hamstrings, and you are standing with the weight. Slowly lower the weight back to the pins returning to the starting position.']::text[], ARRAY['Good_Morning_off_Pins/0.jpg', 'Good_Morning_off_Pins/1.jpg']::text[], 'good morning off pins good morning tu gia do buenos dias desde soportes'),
  (NULL, 'Gorilla Chin/Crunch', 'Gorilla Chin/Crunch', 'Gorilla Chin/Crunch', 'Crunch gorila colgado', 'abs', 'bodyweight', 'bodyweight', 'free_exercise_db', 'Gorilla_Chin_Crunch', ARRAY['Hang from a chin-up bar using an underhand grip (palms facing you) that is slightly wider than shoulder width.', 'Now bend your knees at a 90 degree angle so that the calves are parallel to the floor while the thighs remain perpendicular to it. This will be your starting position.', 'As you exhale, pull yourself up while crunching your knees up at the same time until your knees are at chest level. You will stop going up as soon as your nose is at the same level as the bar. Tip: When you get to this point you should also be finishing the crunch at the same time.', 'Slowly start to inhale as you return to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Gorilla_Chin_Crunch/0.jpg', 'Gorilla_Chin_Crunch/1.jpg']::text[], 'gorilla chin/crunch gap bung treo xa kieu gorilla crunch gorila colgado'),
  (NULL, 'Groin and Back Stretch', 'Giãn háng và lưng', 'Groin and Back Stretch', 'Estiramiento de ingle y espalda', 'legs', 'other', 'timed', 'free_exercise_db', 'Groin_and_Back_Stretch', ARRAY['Sit on the floor with your knees bent and feet together.', 'Interlock your fingers behind your head. This will be your starting position.', 'Curl downwards, bringing your elbows to the inside of your thighs. After a brief pause, return to the starting position with your head up and your back straight. Repeat for 10-20 repetitions.']::text[], ARRAY['Groin_and_Back_Stretch/0.jpg', 'Groin_and_Back_Stretch/1.jpg']::text[], 'groin and back stretch gian hang va lung estiramiento de ingle y espalda'),
  (NULL, 'Groiners', 'Bước háng từ thế plank', 'Groiners', 'Groiners', 'legs', 'bodyweight', 'timed', 'free_exercise_db', 'Groiners', ARRAY['Begin in a pushup position on the floor. This will be your starting position.', 'Using both legs, jump forward landing with your feet next to your hands. Keep your head up as you do so.', 'Return to the starting position and immediately repeat the movement, continuing for 10-20 repetitions.']::text[], ARRAY['Groiners/0.jpg', 'Groiners/1.jpg']::text[], 'groiners buoc hang tu the plank groiners'),
  (NULL, 'Hack Squat', 'Hack Squat', 'Hack Squat', 'Sentadilla hack en máquina', 'legs', 'machine', 'compound', 'free_exercise_db', 'Hack_Squat', ARRAY['Place the back of your torso against the back pad of the machine and hook your shoulders under the shoulder pads provided.', 'Position your legs in the platform using a shoulder width medium stance with the toes slightly pointed out. Tip: Keep your head up at all times and also maintain the back on the pad at all times.', 'Place your arms on the side handles of the machine and disengage the safety bars (which on most designs is done by moving the side handles from a facing front position to a diagonal position).', 'Now straighten your legs without locking the knees. This will be your starting position. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances described in the foot positioning section).', 'Begin to slowly lower the unit by bending the knees as you maintain a straight posture with the head up (back on the pad at all times). Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to the floor). Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.', 'Begin to raise the unit as you exhale by pushing the floor with mainly with the heel of your foot as you straighten the legs again and go back to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Hack_Squat/0.jpg', 'Hack_Squat/1.jpg']::text[], 'hack squat hack squat may sentadilla hack en maquina'),
  (NULL, 'Hammer Curls', 'Hammer Curls', 'Hammer Curls', 'Curl martillo', 'biceps', 'dumbbell', 'isolation', 'free_exercise_db', 'Hammer_Curls', ARRAY['Stand up with your torso upright and a dumbbell on each hand being held at arms length. The elbows should be close to the torso.', 'The palms of the hands should be facing your torso. This will be your starting position.', 'Now, while holding your upper arm stationary, exhale and curl the weight forward while contracting the biceps. Continue to raise the weight until the biceps are fully contracted and the dumbbell is at shoulder level. Hold the contracted position for a brief moment as you squeeze the biceps. Tip: Focus on keeping the elbow stationary and only moving your forearm.', 'After the brief pause, inhale and slowly begin the lower the dumbbells back down to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Hammer_Curls/0.jpg', 'Hammer_Curls/1.jpg']::text[], 'hammer curls cuon bua curl martillo'),
  (NULL, 'Hammer Grip Incline DB Bench Press', 'Hammer Grip Incline DB Bench Press', 'Hammer Grip Incline DB Bench Press', 'Press inclinado con mancuernas agarre martillo', 'chest', 'dumbbell', 'compound', 'free_exercise_db', 'Hammer_Grip_Incline_DB_Bench_Press', ARRAY['Lie back on an incline bench with a dumbbell on each hand on top of your thighs. The palms of your hand will be facing each other.', 'By using your thighs to help you get the dumbbells up, clean the dumbbells one arm at a time so that you can hold them at shoulder width.', 'Once at shoulder width, keep the palms of your hands with a neutral grip (palms facing each other). Keep your elbows flared out with the upper arms in line with the shoulders (perpendicular to the torso) and the elbows bent creating a 90-degree angle between the upper arm and the forearm. This will be your starting position.', 'Now bring down the weights slowly to your side as you breathe in. Keep full control of the dumbbells at all times.', 'As you breathe out, push the dumbbells up using your pectoral muscles. Lock your arms in the contracted position, hold for a second and then start coming down slowly. Tip: It should take at least twice as long to go down than to come up.', 'Repeat the movement for the prescribed amount of repetitions.', 'When you are done, place the dumbbells back in your thighs and then on the floor. This is the safest manner to dispose of the dumbbells.']::text[], ARRAY['Hammer_Grip_Incline_DB_Bench_Press/0.jpg', 'Hammer_Grip_Incline_DB_Bench_Press/1.jpg']::text[], 'hammer grip incline db bench press day nguc doc len ta don nam bua press inclinado con mancuernas agarre martillo'),
  (NULL, 'Hamstring-SMR', 'Lăn giãn đùi sau', 'Hamstring-SMR', 'Liberación de isquios con rodillo', 'legs', 'foam roll', 'timed', 'free_exercise_db', 'Hamstring-SMR', ARRAY['In a seated position, extend your legs over a foam roll so that it is position on the back of the upper legs. Place your hands to the side or behind you to help support your weight. This will be your starting position.', 'Using your hands, lift your hips off of the floor and shift your weight on the foam roll to one leg. Relax the hamstrings of the leg you are stretching.', 'Roll over the foam from below the hip to above the back of the knee, pausing at points of tension for 10-30 seconds. Repeat for the other leg.']::text[], ARRAY['Hamstring-SMR/0.jpg', 'Hamstring-SMR/1.jpg']::text[], 'hamstring-smr lan gian dui sau liberacion de isquios con rodillo'),
  (NULL, 'Hamstring Stretch', 'Giãn đùi sau', 'Hamstring Stretch', 'Estiramiento de isquiotibiales', 'legs', 'other', 'timed', 'free_exercise_db', 'Hamstring_Stretch', ARRAY['Lie on your back with one leg extended above you, with the hip at ninety degrees. Keep the other leg flat on the floor.', 'Loop a belt, band, or rope over the ball of your foot. This will be your starting position.', 'Pull on the belt to create tension in the calves and hamstrings. Hold this stretch for 10-30 seconds, and repeat with the other leg.']::text[], ARRAY['Hamstring_Stretch/0.jpg', 'Hamstring_Stretch/1.jpg']::text[], 'hamstring stretch gian dui sau estiramiento de isquiotibiales'),
  (NULL, 'Handstand Push-Ups', 'Hít đất trồng chuối', 'Handstand Push-Ups', 'Flexiones en pino', 'shoulders', 'bodyweight', 'bodyweight', 'free_exercise_db', 'Handstand_Push-Ups', ARRAY['With your back to the wall bend at the waist and place both hands on the floor at shoulder width.', 'Kick yourself up against the wall with your arms straight. Your body should be upside down with the arms and legs fully extended. Keep your whole body as straight as possible. Tip: If doing this for the first time, have a spotter help you. Also, make sure that you keep facing the wall with your head, rather than looking down.', 'Slowly lower yourself to the ground as you inhale until your head almost touches the floor. Tip: It is of utmost importance that you come down slow in order to avoid head injury.', 'Push yourself back up slowly as you exhale until your elbows are nearly locked.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Handstand_Push-Ups/0.jpg', 'Handstand_Push-Ups/1.jpg']::text[], 'handstand push-ups hit dat trong chuoi flexiones en pino'),
  (NULL, 'Hang Clean', 'Hang Clean', 'Hang Clean', 'Cargada colgante', 'legs', 'barbell', 'compound', 'free_exercise_db', 'Hang_Clean', ARRAY['Begin with a shoulder width, double overhand or hook grip, with the bar hanging at the mid thigh position. Your back should be straight and inclined slightly forward.', 'Begin by aggressively extending through the hips, knees and ankles, driving the weight upward. As you do so, shrug your shoulders towards your ears.', 'Immediately recover by driving through the heels, keeping the torso upright and elbows up. Continue until you have risen to a standing position.']::text[], ARRAY['Hang_Clean/0.jpg', 'Hang_Clean/1.jpg']::text[], 'hang clean hang clean cargada colgante'),
  (NULL, 'Hang Clean - Below the Knees', 'Hang Clean - Below the Knees', 'Hang Clean - Below the Knees', 'Cargada colgante bajo rodillas', 'legs', 'barbell', 'compound', 'free_exercise_db', 'Hang_Clean_-_Below_the_Knees', ARRAY['Begin with a shoulder width, double overhand or hook grip, with the bar hanging just below the knees. Your back should be straight and inclined slightly forward.', 'Begin by aggressively extending through the hips, knees and ankles, driving the weight upward. As you do so, shrug your shoulders towards your ears. As full extension is achieved, transition into the third pull by aggressively shrugging and flexing the arms with the elbows up and out.', 'At peak extension, aggressively pull yourself down, rotating your elbows under the bar as you do so. Receive the bar in a front squat position, the depth of which is dependent upon the height of the bar at the end of the third pull. The bar should be racked onto the protracted shoulders, lightly touching the throat with the hands relaxed. Continue to descend to the bottom squat position, which will help in the recovery.', 'Immediately recover by driving through the heels, keeping the torso upright and elbows up. Continue until you have risen to a standing position.']::text[], ARRAY['Hang_Clean_-_Below_the_Knees/0.jpg', 'Hang_Clean_-_Below_the_Knees/1.jpg']::text[], 'hang clean - below the knees hang clean duoi goi cargada colgante bajo rodillas'),
  (NULL, 'Hang Snatch', 'Hang Snatch', 'Hang Snatch', 'Arrancada colgante', 'legs', 'barbell', 'compound', 'free_exercise_db', 'Hang_Snatch', ARRAY['Begin with a wide grip on the bar, with an overhand or hook grip. The feet should be directly below the hips with the feet turned out. Your knees should be slightly bent, and the torso inclined forward. The spine should be fully extended and the head facing forward. The bar should be at the hips. This will be your starting position.', 'Aggressively extend through the legs and hips. At peak extension, shrug the shoulders and allow the elbows to flex to the side.', 'As you move your feet into the receiving position, forcefully pull yourself below the bar as you elevate the bar overhead. Receive the bar with your body as low as possible and the arms fully extended overhead.', 'Return to a standing position with the weight overhead. Follow by returning the weight to the ground under control.']::text[], ARRAY['Hang_Snatch/0.jpg', 'Hang_Snatch/1.jpg']::text[], 'hang snatch hang snatch arrancada colgante'),
  (NULL, 'Hang Snatch - Below Knees', 'Hang Snatch - Below Knees', 'Hang Snatch - Below Knees', 'Arrancada colgante bajo rodillas', 'legs', 'barbell', 'compound', 'free_exercise_db', 'Hang_Snatch_-_Below_Knees', ARRAY['Begin with a wide grip on the bar, with an overhand or hook grip. The feet should be directly below the hips with the feet turned out. Your knees should be slightly bent, and the torso inclined forward. The spine should be fully extended and the head facing forward. The bar should be just below the knees. This will be your starting position.', 'Aggressively extend through the legs and hips. At peak extension, shrug the shoulders and allow the elbows to flex to the side.', 'As you move your feet into the receiving position, forcefully pull yourself below the bar as you elevate the bar overhead. Receive the bar with your body as low as possible and the arms fully extended overhead.', 'Return to a standing position with the weight overhead, and then return the weight to the floor under control.']::text[], ARRAY['Hang_Snatch_-_Below_Knees/0.jpg', 'Hang_Snatch_-_Below_Knees/1.jpg']::text[], 'hang snatch - below knees hang snatch duoi goi arrancada colgante bajo rodillas'),
  (NULL, 'Hanging Bar Good Morning', 'Hanging Bar Good Morning', 'Hanging Bar Good Morning', 'Buenos días con barra colgante', 'legs', 'barbell', 'compound', 'free_exercise_db', 'Hanging_Bar_Good_Morning', ARRAY['Begin with a bar on a rack at about the same height as your stomach. Suspend the bar using chains or suspension straps.', 'Bend over underneath the bar and rack the bar across the rear of your shoulders as you would a power squat, not on top of your traps. At the proper height, you should be near parallel to the floor when bent over. Keep your back tight, shoulder blades pinched together, and your knees slightly bent. Keep your back arched and your cervical spine in proper alignment.', 'Begin the motion by extending through the hips with your glutes and hamstrings, and you are standing with the weight.', 'Slowly lower the weight back to the starting position, where it is supported by the chains.']::text[], ARRAY['Hanging_Bar_Good_Morning/0.jpg', 'Hanging_Bar_Good_Morning/1.jpg']::text[], 'hanging bar good morning good morning ta treo buenos dias con barra colgante'),
  (NULL, 'Hanging Leg Raise', 'Nâng chân treo xà', 'Hanging Leg Raise', 'Elevación de piernas colgado', 'abs', 'bodyweight', 'bodyweight', 'free_exercise_db', 'Hanging_Leg_Raise', ARRAY['Hang from a chin-up bar with both arms extended at arms length in top of you using either a wide grip or a medium grip. The legs should be straight down with the pelvis rolled slightly backwards. This will be your starting position.', 'Raise your legs until the torso makes a 90-degree angle with the legs. Exhale as you perform this movement and hold the contraction for a second or so.', 'Go back slowly to the starting position as you breathe in.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Hanging_Leg_Raise/0.jpg', 'Hanging_Leg_Raise/1.jpg']::text[], 'hanging leg raise nang chan treo xa elevacion de piernas colgado'),
  (NULL, 'Hanging Pike', 'Gập người chữ V treo xà', 'Hanging Pike', 'Pike colgado', 'abs', 'bodyweight', 'bodyweight', 'free_exercise_db', 'Hanging_Pike', ARRAY['Hang from a chin-up bar with your legs and feet together using an overhand grip (palms facing away from you) that is slightly wider than shoulder width. Tip: You may use wrist wraps in order to facilitate holding on to the bar.', 'Now bend your knees at a 90 degree angle and bring the upper legs forward so that the calves are perpendicular to the floor while the thighs remain parallel to it. This will be your starting position.', 'Pull your legs up as you exhale until you almost touch your shins with the bar above you. Tip: Try to straighten your legs as much as possible while at the top.', 'Lower your legs as slowly as possible until you reach the starting position. Tip: Avoid swinging and using momentum at all times.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Hanging_Pike/0.jpg', 'Hanging_Pike/1.jpg']::text[], 'hanging pike gap nguoi chu v treo xa pike colgado'),
  (NULL, 'Heaving Snatch Balance', 'Heaving Snatch Balance', 'Heaving Snatch Balance', 'Equilibrio de arrancada con impulso', 'legs', 'barbell', 'compound', 'free_exercise_db', 'Heaving_Snatch_Balance', ARRAY['This drill helps you learn the snatch. Begin by holding a light weight across the back of the shoulders. Your feet should be slightly wider than hip width apart with the feet turned out, the same position that you would perform a squat with.', 'Begin by dipping with the knees slightly, and popping back up to briefly unload the bar. Drive yourself underneath the bar, elevating it overhead as you descend into a full squat.', 'Return to a standing position.']::text[], ARRAY['Heaving_Snatch_Balance/0.jpg', 'Heaving_Snatch_Balance/1.jpg']::text[], 'heaving snatch balance snatch balance bat equilibrio de arrancada con impulso'),
  (NULL, 'Heavy Bag Thrust', 'Đẩy bao cát', 'Heavy Bag Thrust', 'Empuje de saco pesado', 'chest', 'other', 'compound', 'free_exercise_db', 'Heavy_Bag_Thrust', ARRAY['Utilize a heavy bag for this exercise. Assume an upright stance next to the bag, with your feet staggered, fairly wide apart. Place your hand on the bag at about chest height. This will be your starting position.', 'Begin by twisting at the waist, pushing the bag forward as hard as possible. Perform this move quickly, pushing the bag away from your body.', 'Receive the bag as it swings back by reversing these steps.']::text[], ARRAY['Heavy_Bag_Thrust/0.jpg', 'Heavy_Bag_Thrust/1.jpg']::text[], 'heavy bag thrust day bao cat empuje de saco pesado'),
  (NULL, 'High Cable Curls', 'High Cable Curls', 'High Cable Curls', 'Curl en polea alta', 'biceps', 'cable', 'compound', 'free_exercise_db', 'High_Cable_Curls', ARRAY['Stand between a couple of high pulleys and grab a handle in each arm. Position your upper arms in a way that they are parallel to the floor with the palms of your hands facing you. This will be your starting position.', 'Curl the handles towards you until they are next to your ears. Make sure that as you do so you flex your biceps and exhale. The upper arms should remain stationary and only the forearms should move. Hold for a second in the contracted position as you squeeze the biceps.', 'Slowly bring back the arms to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['High_Cable_Curls/0.jpg', 'High_Cable_Curls/1.jpg']::text[], 'high cable curls cuon tay truoc cap cao curl en polea alta'),
  (NULL, 'Hip Circles (prone)', 'Xoay hông nằm sấp', 'Hip Circles (prone)', 'Círculos de cadera boca abajo', 'legs', 'bodyweight', 'timed', 'free_exercise_db', 'Hip_Circles_prone', ARRAY['Position yourself on your hands and knees on the ground. Maintaining good posture, raise one bent knee off of the ground. This will be your starting position.', 'Keeping the knee in a bent position, rotate the femur in an arc, attempting to make a big circle with your knee.', 'Perform this slowly for a number of repetitions, and repeat on the other side.']::text[], ARRAY['Hip_Circles_prone/0.jpg', 'Hip_Circles_prone/1.jpg']::text[], 'hip circles (prone) xoay hong nam sap circulos de cadera boca abajo'),
  (NULL, 'Hip Extension with Bands', 'Duỗi hông dây kháng lực', 'Hip Extension with Bands', 'Extensión de cadera con banda', 'glutes', 'band', 'compound', 'free_exercise_db', 'Hip_Extension_with_Bands', ARRAY['Secure one end of the band to the lower portion of a post and attach the other to one ankle.', 'Facing the attachment point of the band, hold on to the column to stabilize yourself.', 'Keeping your head and your chest up, move the resisted leg back as far as you can while keeping the knee straight.', 'Return the leg to the starting position.']::text[], ARRAY['Hip_Extension_with_Bands/0.jpg', 'Hip_Extension_with_Bands/1.jpg']::text[], 'hip extension with bands duoi hong day khang luc extension de cadera con banda'),
  (NULL, 'Hip Flexion with Band', 'Gập hông dây kháng lực', 'Hip Flexion with Band', 'Flexión de cadera con banda', 'legs', 'band', 'compound', 'free_exercise_db', 'Hip_Flexion_with_Band', ARRAY['Secure one end of the band to the lower portion of a post and attach the other to one ankle.', 'Face away from the attachment point of the band.', 'Keeping your head and your chest up, raise your knee up to 90 degrees and pause.', 'Return the leg to the starting position.']::text[], ARRAY['Hip_Flexion_with_Band/0.jpg', 'Hip_Flexion_with_Band/1.jpg']::text[], 'hip flexion with band gap hong day khang luc flexion de cadera con banda'),
  (NULL, 'Hip Lift with Band', 'Nâng hông dây kháng lực', 'Hip Lift with Band', 'Elevación de cadera con banda', 'glutes', 'band', 'compound', 'free_exercise_db', 'Hip_Lift_with_Band', ARRAY['After choosing a suitable band, lay down in the middle of the rack, after securing the band on either side of you. If your rack doesn''t have pegs, the band can be secured using heavy dumbbells or similar objects, just ensure they won''t move.', 'Adjust your position so that the band is directly over your hips. Bend your knees and place your feet flat on the floor. Your hands can be on the floor or holding the band in position.', 'Keeping your shoulders on the ground, drive through your heels to raise your hips, pushing into the band as high as you can.', 'Pause at the top of the motion, and return to the starting position.']::text[], ARRAY['Hip_Lift_with_Band/0.jpg', 'Hip_Lift_with_Band/1.jpg']::text[], 'hip lift with band nang hong day khang luc elevacion de cadera con banda'),
  (NULL, 'Hug A Ball', 'Ôm bóng giãn lưng', 'Hug A Ball', 'Abrazar el balón', 'back', 'exercise ball', 'timed', 'free_exercise_db', 'Hug_A_Ball', ARRAY['Seat yourself on the floor.', 'Straddle an exercise ball between both legs and lower your hips down toward the floor.', 'Hug your arms around the ball to support your body. Adjust your legs so that your feet are flat on the floor and your knees line up over your ankles. Keep a good grip on the ball so it doesn''t roll away from you and send you back onto your buttocks.']::text[], ARRAY['Hug_A_Ball/0.jpg', 'Hug_A_Ball/1.jpg']::text[], 'hug a ball om bong gian lung abrazar el balon'),
  (NULL, 'Hug Knees To Chest', 'Ôm gối vào ngực', 'Hug Knees To Chest', 'Abrazar rodillas al pecho', 'back', 'other', 'timed', 'free_exercise_db', 'Hug_Knees_To_Chest', ARRAY['Lie down on your back and pull both knees up to your chest.', 'Hold your arms under the knees, not over (that would put to much pressure on your knee joints).', 'Slowly pull the knees toward your shoulders. This also stretches your buttocks muscles.']::text[], ARRAY['Hug_Knees_To_Chest/0.jpg', 'Hug_Knees_To_Chest/1.jpg']::text[], 'hug knees to chest om goi vao nguc abrazar rodillas al pecho'),
  (NULL, 'Hurdle Hops', 'Bật nhảy qua rào', 'Hurdle Hops', 'Saltos de vallas', 'legs', 'other', 'compound', 'free_exercise_db', 'Hurdle_Hops', ARRAY['Set up a row of hurdles or other small barriers, placing them a few feet apart.', 'Stand in front of the first hurdle with your feet shoulder width apart. This will be your starting position.', 'Begin by jumping with both feet over the first hurdle, swinging both arms as you jump.', 'Absorb the impact of landing by bending the knees, rebounding out of the first leap by jumping over the next hurdle. Continue until you have jumped over all of the hurdles.']::text[], ARRAY['Hurdle_Hops/0.jpg', 'Hurdle_Hops/1.jpg']::text[], 'hurdle hops bat nhay qua rao saltos de vallas'),
  (NULL, 'Hyperextensions (Back Extensions)', 'Gập lưng ngược', 'Hyperextensions (Back Extensions)', 'Hiperextensiones', 'back', 'other', 'isolation', 'free_exercise_db', 'Hyperextensions_Back_Extensions', ARRAY['Lie face down on a hyperextension bench, tucking your ankles securely under the footpads.', 'Adjust the upper pad if possible so your upper thighs lie flat across the wide pad, leaving enough room for you to bend at the waist without any restriction.', 'With your body straight, cross your arms in front of you (my preference) or behind your head. This will be your starting position. Tip: You can also hold a weight plate for extra resistance in front of you under your crossed arms.', 'Start bending forward slowly at the waist as far as you can while keeping your back flat. Inhale as you perform this movement. Keep moving forward until you feel a nice stretch on the hamstrings and you can no longer keep going without a rounding of the back. Tip: Never round the back as you perform this exercise. Also, some people can go farther than others. The key thing is that you go as far as your body allows you to without rounding the back.', 'Slowly raise your torso back to the initial position as you inhale. Tip: Avoid the temptation to arch your back past a straight line. Also, do not swing the torso at any time in order to protect the back from injury.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Hyperextensions_Back_Extensions/0.jpg', 'Hyperextensions_Back_Extensions/1.jpg']::text[], 'hyperextensions (back extensions) gap lung nguoc hiperextensiones'),
  (NULL, 'Hyperextensions With No Hyperextension Bench', 'Gập lưng ngược không cần ghế', 'Hyperextensions With No Hyperextension Bench', 'Hiperextensiones sin banco', 'back', 'bodyweight', 'bodyweight', 'free_exercise_db', 'Hyperextensions_With_No_Hyperextension_Bench', ARRAY['With someone holding down your legs, slide yourself down to the edge a flat bench until your hips hang off the end of the bench. Tip: Your entire upper body should be hanging down towards the floor. Also, you will be in the same position as if you were on a hyperextension bench but the range of motion will be shorter due to the height of the flat bench vs. that of the hyperextension bench.', 'With your body straight, cross your arms in front of you (my preference) or behind your head. This will be your starting position. Tip: You can also hold a weight plate for extra resistance in front of you under your crossed arms.', 'Start bending forward slowly at the waist as far as you can while keeping your back flat. Inhale as you perform this movement. Keep moving forward until you almost touch the floor or you feel a nice stretch on the hamstrings (whichever comes first). Tip: Never round the back as you perform this exercise.', 'Slowly raise your torso back to the initial position as you exhale. Tip: Avoid the temptation to arch your back past a straight line. Also, do not swing the torso at any time in order to protect the back from injury.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Hyperextensions_With_No_Hyperextension_Bench/0.jpg', 'Hyperextensions_With_No_Hyperextension_Bench/1.jpg']::text[], 'hyperextensions with no hyperextension bench gap lung nguoc khong can ghe hiperextensiones sin banco'),
  (NULL, 'IT Band and Glute Stretch', 'Giãn dải chậu chày và mông', 'IT Band and Glute Stretch', 'Estiramiento de banda IT y glúteo', 'legs', 'other', 'timed', 'free_exercise_db', 'IT_Band_and_Glute_Stretch', ARRAY['Loop a belt, rope, or band around one of your feet, and swing that leg across your body to the opposite side, keeping the leg extended as you lay on the ground. This will be your starting position.', 'Keeping your foot off of the floor, pull on the belt, using the tension to pull the toes up. Hold for 10-20 seconds, and repeat on the other side.']::text[], ARRAY['IT_Band_and_Glute_Stretch/0.jpg', 'IT_Band_and_Glute_Stretch/1.jpg']::text[], 'it band and glute stretch gian dai chau chay va mong estiramiento de banda it y gluteo'),
  (NULL, 'Iliotibial Tract-SMR', 'Lăn giãn dải chậu chày', 'Iliotibial Tract-SMR', 'Liberación de banda iliotibial', 'legs', 'foam roll', 'timed', 'free_exercise_db', 'Iliotibial_Tract-SMR', ARRAY['Lay on your side, with the bottom leg placed onto a foam roller between the hip and the knee. The other leg can be crossed in front of you.', 'Place as much of your weight as is tolerable onto your bottom leg; there is no need to keep your bottom leg in contact with the ground. Be sure to relax the muscles of the leg you are stretching.', 'Roll your leg over the foam from you hip to your knee, pausing for 10-30 seconds at points of tension. Repeat with the opposite leg.']::text[], ARRAY['Iliotibial_Tract-SMR/0.jpg', 'Iliotibial_Tract-SMR/1.jpg']::text[], 'iliotibial tract-smr lan gian dai chau chay liberacion de banda iliotibial'),
  (NULL, 'Inchworm', 'Sâu đo', 'Inchworm', 'Gusano', 'legs', 'bodyweight', 'timed', 'free_exercise_db', 'Inchworm', ARRAY['Stand with your feet close together. Keeping your legs straight, stretch down and put your hands on the floor directly in front of you. This will be your starting position.', 'Begin by walking your hands forward slowly, alternating your left and your right. As you do so, bend only at the hip, keeping your legs straight.', 'Keep going until your body is parallel to the ground in a pushup position.', 'Now, keep your hands in place and slowly take short steps with your feet, moving only a few inches at a time.', 'Continue walking until your feet are by hour hands, keeping your legs straight as you do so.']::text[], ARRAY['Inchworm/0.jpg', 'Inchworm/1.jpg']::text[], 'inchworm sau do gusano'),
  (NULL, 'Incline Barbell Triceps Extension', 'Duỗi tay sau tạ đòn ghế dốc', 'Incline Barbell Triceps Extension', 'Extensión de tríceps inclinado con barra', 'triceps', 'barbell', 'isolation', 'free_exercise_db', 'Incline_Barbell_Triceps_Extension', ARRAY['Hold a barbell with an overhand grip (palms down) that is a little closer together than shoulder width.', 'Lie back on an incline bench set at any angle between 45-75-degrees.', 'Bring the bar overhead with your arms extended and elbows in. The arms should be in line with the torso above the head. This will be your starting position.', 'Now lower the bar in a semicircular motion behind your head until your forearms touch your biceps. Inhale as you perform this movement. Tip: Keep your upper arms stationary and close to your head at all times. Only the forearms should move.', 'Return to the starting position as you breathe out and you contract the triceps. Hold the contraction for a second.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Incline_Barbell_Triceps_Extension/0.jpg', 'Incline_Barbell_Triceps_Extension/1.jpg']::text[], 'incline barbell triceps extension duoi tay sau ta don ghe doc extension de triceps inclinado con barra'),
  (NULL, 'Incline Bench Pull', 'Kéo tạ đòn nằm ghế dốc', 'Incline Bench Pull', 'Remo tumbado en banco inclinado', 'back', 'barbell', 'isolation', 'free_exercise_db', 'Incline_Bench_Pull', ARRAY['Grab a dumbbell in each hand and lie face down on an incline bench that is set to an incline that is approximately 30 degrees.', 'Let the arms hang to your sides fully extended as they point to the floor.', 'Turn the wrists until your hands have a pronated (palms down) grip.', 'Now flare the elbows out. This will be your starting position.', 'As you breathe out, start to pull the dumbbells up as if you are doing a reverse bench press. You will do this by bending at the elbows and bringing the upper arms up as you let the forearms hang. Continue this motion until the upper arms are at the same level as your back. Tip: The elbows will come out to the side and your upper arms and torso should make the letter "T" at the top of the movement. Hold the contraction at the top for a second.', 'Slowly go back down to the starting position as you breathe in.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Incline_Bench_Pull/0.jpg', 'Incline_Bench_Pull/1.jpg']::text[], 'incline bench pull keo ta don nam ghe doc remo tumbado en banco inclinado'),
  (NULL, 'Incline Cable Chest Press', 'Đẩy ngực cáp ghế dốc', 'Incline Cable Chest Press', 'Press inclinado en polea', 'chest', 'cable', 'compound', 'free_exercise_db', 'Incline_Cable_Chest_Press', ARRAY['Adjust the weight to an appropriate amount and be seated, grasping the handles. Your upper arms should be about 45 degrees to the body, with your head and chest up. The elbows should be bent to about 90 degrees. This will be your starting position.', 'Begin by extending through the elbow, pressing the handles together straight in front of you. Keep your shoulder blades retracted as you execute the movement.', 'After pausing at full extension, return to the starting position, keeping tension on the cables.']::text[], ARRAY['Incline_Cable_Chest_Press/0.jpg', 'Incline_Cable_Chest_Press/1.jpg']::text[], 'incline cable chest press day nguc cap ghe doc press inclinado en polea'),
  (NULL, 'Incline Cable Flye', 'Incline Cable Flye', 'Incline Cable Flye', 'Aperturas inclinadas en polea', 'chest', 'cable', 'isolation', 'free_exercise_db', 'Incline_Cable_Flye', ARRAY['To get yourself into the starting position, set the pulleys at the floor level (lowest level possible on the machine that is below your torso).', 'Place an incline bench (set at 45 degrees) in between the pulleys, select a weight on each one and grab a pulley on each hand.', 'With a handle on each hand, lie on the incline bench and bring your hands together at arms length in front of your face. This will be your starting position.', 'With a slight bend of your elbows (in order to prevent stress at the biceps tendon), lower your arms out at both sides in a wide arc until you feel a stretch on your chest. Breathe in as you perform this portion of the movement. Tip: Keep in mind that throughout the movement, the arms should remain stationary. The movement should only occur at the shoulder joint.', 'Return your arms back to the starting position as you squeeze your chest muscles and exhale. Hold the contracted position for a second. Tip: Make sure to use the same arc of motion used to lower the weights.', 'Repeat the movement for the prescribed amount of repetitions.']::text[], ARRAY['Incline_Cable_Flye/0.jpg', 'Incline_Cable_Flye/1.jpg']::text[], 'incline cable flye ep nguc cap ghe doc aperturas inclinadas en polea'),
  (NULL, 'Incline Dumbbell Bench With Palms Facing In', 'Đẩy ngực dốc lên tạ đơn lòng tay hướng vào', 'Incline Dumbbell Bench With Palms Facing In', 'Press inclinado con mancuernas agarre neutro', 'chest', 'dumbbell', 'compound', 'free_exercise_db', 'Incline_Dumbbell_Bench_With_Palms_Facing_In', ARRAY['Lie back on an incline bench with a dumbbell on each hand on top of your thighs. The palms of your hand will be facing each other.', 'By using your thighs to help you get the dumbbells up, clean the dumbbells one arm at a time so that you can hold them at shoulder width.', 'Once at shoulder width, keep the palms of your hands with a neutral grip (palms facing each other). Keep your elbows flared out with the upper arms in line with the shoulders (perpendicular to the torso) and the elbows bent creating a 90-degree angle between the upper arm and the forearm. This will be your starting position.', 'Now bring down the weights slowly to your side as you breathe in. Keep full control of the dumbbells at all times.', 'As you breathe out, push the dumbbells up using your pectoral muscles. Lock your arms in the contracted position, hold for a second and then start coming down slowly. Tip: It should take at least twice as long to go down than to come up.', 'Repeat the movement for the prescribed amount of repetitions.', 'When you are done, place the dumbbells back in your thighs and then on the floor. This is the safest manner to dispose of the dumbbells.']::text[], ARRAY['Incline_Dumbbell_Bench_With_Palms_Facing_In/0.jpg', 'Incline_Dumbbell_Bench_With_Palms_Facing_In/1.jpg']::text[], 'incline dumbbell bench with palms facing in day nguc doc len ta don long tay huong vao press inclinado con mancuernas agarre neutro'),
  (NULL, 'Incline Dumbbell Curl', 'Incline Dumbbell Curl', 'Incline Dumbbell Curl', 'Curl inclinado con mancuernas', 'biceps', 'dumbbell', 'isolation', 'free_exercise_db', 'Incline_Dumbbell_Curl', ARRAY['Sit back on an incline bench with a dumbbell in each hand held at arms length. Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward. This will be your starting position.', 'While holding the upper arm stationary, curl the weights forward while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a second.', 'Slowly begin to bring the dumbbells back to starting position as your breathe in.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Incline_Dumbbell_Curl/0.jpg', 'Incline_Dumbbell_Curl/1.jpg']::text[], 'incline dumbbell curl cuon ta don ghe doc curl inclinado con mancuernas'),
  (NULL, 'Incline Dumbbell Flyes', 'Incline Dumbbell Flyes', 'Incline Dumbbell Flyes', 'Aperturas inclinadas con mancuernas', 'chest', 'dumbbell', 'compound', 'free_exercise_db', 'Incline_Dumbbell_Flyes', ARRAY['Hold a dumbbell on each hand and lie on an incline bench that is set to an incline angle of no more than 30 degrees.', 'Extend your arms above you with a slight bend at the elbows.', 'Now rotate the wrists so that the palms of your hands are facing you. Tip: The pinky fingers should be next to each other. This will be your starting position.', 'As you breathe in, start to slowly lower the arms to the side while keeping the arms extended and while rotating the wrists until the palms of the hand are facing each other. Tip: At the end of the movement the arms will be by your side with the palms facing the ceiling.', 'As you exhale start to bring the dumbbells back up to the starting position by reversing the motion and rotating the hands so that the pinky fingers are next to each other again. Tip: Keep in mind that the movement will only happen at the shoulder joint and at the wrist. There is no motion that happens at the elbow joint.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Incline_Dumbbell_Flyes/0.jpg', 'Incline_Dumbbell_Flyes/1.jpg']::text[], 'incline dumbbell flyes ep nguc doc len ta don aperturas inclinadas con mancuernas'),
  (NULL, 'Incline Dumbbell Flyes - With A Twist', 'Incline Dumbbell Flyes - With A Twist', 'Incline Dumbbell Flyes - With A Twist', 'Aperturas inclinadas con giro', 'chest', 'dumbbell', 'compound', 'free_exercise_db', 'Incline_Dumbbell_Flyes_-_With_A_Twist', ARRAY['Hold a dumbbell in each hand and lie on an incline bench that is set to an incline angle of no more than 30 degrees.', 'Extend your arms above you with a slight bend at the elbows.', 'Now rotate the wrists so that the palms of your hands are facing you. Tip: The pinky fingers should be next to each other. This will be your starting position.', 'As you breathe in, start to slowly lower the arms to the side while keeping the arms extended and while rotating the wrists until the palms of the hand are facing each other. Tip: At the end of the movement the arms will be by your side with the palms facing the ceiling.', 'As you exhale start to bring the dumbbells back up to the starting position by reversing the motion and rotating the hands so that the pinky fingers are next to each other again. Tip: Keep in mind that the movement will only happen at the shoulder joint and at the wrist. There is no motion that happens at the elbow joint.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Incline_Dumbbell_Flyes_-_With_A_Twist/0.jpg', 'Incline_Dumbbell_Flyes_-_With_A_Twist/1.jpg']::text[], 'incline dumbbell flyes - with a twist ep nguc doc len ta don co xoay aperturas inclinadas con giro'),
  (NULL, 'Incline Dumbbell Press', 'Đẩy ngực dốc lên tạ đơn', 'Incline Dumbbell Press', 'Press inclinado con mancuernas', 'chest', 'dumbbell', 'compound', 'free_exercise_db', 'Incline_Dumbbell_Press', ARRAY['Lie back on an incline bench with a dumbbell in each hand atop your thighs. The palms of your hands will be facing each other.', 'Then, using your thighs to help push the dumbbells up, lift the dumbbells one at a time so that you can hold them at shoulder width.', 'Once you have the dumbbells raised to shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. This will be your starting position.', 'Be sure to keep full control of the dumbbells at all times. Then breathe out and push the dumbbells up with your chest.', 'Lock your arms at the top, hold for a second, and then start slowly lowering the weight. Tip Ideally, lowering the weights should take about twice as long as raising them.', 'Repeat the movement for the prescribed amount of repetitions.', 'When you are done, place the dumbbells back on your thighs and then on the floor. This is the safest manner to release the dumbbells.']::text[], ARRAY['Incline_Dumbbell_Press/0.jpg', 'Incline_Dumbbell_Press/1.jpg']::text[], 'incline dumbbell press day nguc doc len ta don press inclinado con mancuernas'),
  (NULL, 'Incline Hammer Curls', 'Incline Hammer Curls', 'Incline Hammer Curls', 'Curl martillo inclinado', 'biceps', 'dumbbell', 'isolation', 'free_exercise_db', 'Incline_Hammer_Curls', ARRAY['Seat yourself on an incline bench with a dumbbell in each hand. You should pressed firmly against he back with your feet together. Allow the dumbbells to hang straight down at your side, holding them with a neutral grip. This will be your starting position.', 'Initiate the movement by flexing at the elbow, attempting to keep the upper arm stationary.', 'Continue to the top of the movement and pause, then slowly return to the start position.']::text[], ARRAY['Incline_Hammer_Curls/0.jpg', 'Incline_Hammer_Curls/1.jpg']::text[], 'incline hammer curls cuon bua ghe doc curl martillo inclinado'),
  (NULL, 'Incline Inner Biceps Curl', 'Incline Inner Biceps Curl', 'Incline Inner Biceps Curl', 'Curl interno inclinado', 'biceps', 'dumbbell', 'isolation', 'free_exercise_db', 'Incline_Inner_Biceps_Curl', ARRAY['Hold a dumbbell in each hand and lie back on an incline bench.', 'The dumbbells should be at arm''s length hanging at your sides and your palms should be facing out. This will be your starting position.', 'Now as you exhale curl the weight outward and up while keeping your forearms in line with your side deltoids. Continue the curl until the dumbbells are at shoulder height and to the sides of your deltoids. Tip: The end of the movement should look similar to a double biceps pose.', 'After a second contraction at the top of the movement, start to inhale and slowly lower the weights back to the starting position using the same path used to bring them up.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Incline_Inner_Biceps_Curl/0.jpg', 'Incline_Inner_Biceps_Curl/1.jpg']::text[], 'incline inner biceps curl cuon tay truoc trong ghe doc curl interno inclinado'),
  (NULL, 'Incline Push-Up', 'Hít đất tay trên cao', 'Incline Push-Up', 'Flexiones inclinadas', 'chest', 'bodyweight', 'bodyweight', 'free_exercise_db', 'Incline_Push-Up', ARRAY['Stand facing bench or sturdy elevated platform. Place hands on edge of bench or platform, slightly wider than shoulder width.', 'Position forefoot back from bench or platform with arms and body straight. Arms should be perpendicular to body. Keeping body straight, lower chest to edge of box or platform by bending arms.', 'Push body up until arms are extended. Repeat.']::text[], ARRAY['Incline_Push-Up/0.jpg', 'Incline_Push-Up/1.jpg']::text[], 'incline push-up hit dat tay tren cao flexiones inclinadas'),
  (NULL, 'Incline Push-Up Close-Grip', 'Hít đất tay trên cao nắm hẹp', 'Incline Push-Up Close-Grip', 'Flexiones inclinadas agarre cerrado', 'triceps', 'bodyweight', 'bodyweight', 'free_exercise_db', 'Incline_Push-Up_Close-Grip', ARRAY['Stand facing a Smith machine bar or sturdy elevated platform at an appropriate height.', 'Place your hands next to one another on the bar.', 'Position your feet back from the bar with arms and body straight. This will be your starting position.', 'Keeping your body straight, lower your chest to the bar by bending the arms.', 'Return to the starting position by extending the elbows, pressing yourself back up.']::text[], ARRAY['Incline_Push-Up_Close-Grip/0.jpg', 'Incline_Push-Up_Close-Grip/1.jpg']::text[], 'incline push-up close-grip hit dat tay tren cao nam hep flexiones inclinadas agarre cerrado'),
  (NULL, 'Incline Push-Up Depth Jump', 'Hít đất tay trên cao bật xuống', 'Incline Push-Up Depth Jump', 'Flexiones inclinadas con salto', 'chest', 'other', 'compound', 'free_exercise_db', 'Incline_Push-Up_Depth_Jump', ARRAY['For this drill you will need a box about 12 inches high, and two thick mats or aerobics steps.', 'Place the steps just outside of your shoulders, and place your feet on top of the box so that you are in an incline pushup position, your hands just inside the steps. This will be your starting position.', 'Begin by bending at the elbows to lower your body, quickly reversing position to push your body off of the ground. As you leave the ground, move your hands onto the steps, bending your elbows to absorb the impact.', 'Repeat the motion to return to the starting position.']::text[], ARRAY['Incline_Push-Up_Depth_Jump/0.jpg', 'Incline_Push-Up_Depth_Jump/1.jpg']::text[], 'incline push-up depth jump hit dat tay tren cao bat xuong flexiones inclinadas con salto'),
  (NULL, 'Incline Push-Up Medium', 'Hít đất tay trên cao nắm vừa', 'Incline Push-Up Medium', 'Flexiones inclinadas agarre medio', 'chest', 'bodyweight', 'bodyweight', 'free_exercise_db', 'Incline_Push-Up_Medium', ARRAY['Stand facing a Smith machine bar or sturdy elevated platform at an appropriate height.', 'Place your hands on the bar, with your hands about shoulder width apart.', 'Position your feet back from the bar with arms and body straight. This will be your starting position.', 'Keeping your body straight, lower your chest to the bar by bending the arms.', 'Return to the starting position by extending the elbows, pressing yourself back up.']::text[], ARRAY['Incline_Push-Up_Medium/0.jpg', 'Incline_Push-Up_Medium/1.jpg']::text[], 'incline push-up medium hit dat tay tren cao nam vua flexiones inclinadas agarre medio'),
  (NULL, 'Incline Push-Up Reverse Grip', 'Hít đất tay trên cao nắm ngược', 'Incline Push-Up Reverse Grip', 'Flexiones inclinadas agarre invertido', 'chest', 'bodyweight', 'bodyweight', 'free_exercise_db', 'Incline_Push-Up_Reverse_Grip', ARRAY['Stand facing a Smith machine bar or sturdy elevated platform at an appropriate height.', 'Place your hands on the bar palms up, with your hands about shoulder width apart.', 'Position your feet back from the bar with arms and body straight. This will be your starting position.', 'Keeping your body straight, lower your chest to the bar by bending the arms.', 'Return to the starting position by extending the elbows, pressing yourself back up.']::text[], ARRAY['Incline_Push-Up_Reverse_Grip/0.jpg', 'Incline_Push-Up_Reverse_Grip/1.jpg']::text[], 'incline push-up reverse grip hit dat tay tren cao nam nguoc flexiones inclinadas agarre invertido'),
  (NULL, 'Incline Push-Up Wide', 'Hít đất tay trên cao nắm rộng', 'Incline Push-Up Wide', 'Flexiones inclinadas agarre ancho', 'chest', 'bodyweight', 'bodyweight', 'free_exercise_db', 'Incline_Push-Up_Wide', ARRAY['Stand facing a Smith machine bar or sturdy elevated platform at an appropriate height.', 'Place your hands on the bar, with your hands wider than shoulder width.', 'Position your feet back from the bar with arms and body straight. Your arms should be perpendicular to the body. This will be your starting position.', 'Keeping your body straight, lower your chest to the bar by bending the arms.', 'Return to the starting position by extending the elbows, pressing yourself back up.']::text[], ARRAY['Incline_Push-Up_Wide/0.jpg', 'Incline_Push-Up_Wide/1.jpg']::text[], 'incline push-up wide hit dat tay tren cao nam rong flexiones inclinadas agarre ancho'),
  (NULL, 'Intermediate Groin Stretch', 'Giãn háng mức trung bình', 'Intermediate Groin Stretch', 'Estiramiento de ingle intermedio', 'legs', 'other', 'timed', 'free_exercise_db', 'Intermediate_Groin_Stretch', ARRAY['Lie on your back with your legs extended. Loop a belt, rope, or band around one of your feet, and swing that leg as far to the side as you can. This will be your starting position.', 'Pull gently on the belt to create tension in your groin and hamstring muscles. Hold for 10-20 seconds, and repeat on the other side.']::text[], ARRAY['Intermediate_Groin_Stretch/0.jpg', 'Intermediate_Groin_Stretch/1.jpg']::text[], 'intermediate groin stretch gian hang muc trung binh estiramiento de ingle intermedio'),
  (NULL, 'Intermediate Hip Flexor and Quad Stretch', 'Giãn gấp hông và đùi trước mức trung bình', 'Intermediate Hip Flexor and Quad Stretch', 'Estiramiento intermedio de flexor de cadera y cuádriceps', 'legs', 'other', 'timed', 'free_exercise_db', 'Intermediate_Hip_Flexor_and_Quad_Stretch', ARRAY['Lie face down on the floor, with a rope, belt, or band looped around one foot.', 'Flex the knee and extend the hip of the leg to be stretched, using both hands to pull on the belt. Your knee and your hip should come off of the floor, creating tension in the hip flexors and quadriceps. Hold the stretch for 10-20 seconds, and repeat on the other leg.']::text[], ARRAY['Intermediate_Hip_Flexor_and_Quad_Stretch/0.jpg', 'Intermediate_Hip_Flexor_and_Quad_Stretch/1.jpg']::text[], 'intermediate hip flexor and quad stretch gian gap hong va dui truoc muc trung binh estiramiento intermedio de flexor de cadera y cuadriceps'),
  (NULL, 'Internal Rotation with Band', 'Xoay vai trong dây kháng lực', 'Internal Rotation with Band', 'Rotación interna con banda', 'shoulders', 'band', 'isolation', 'free_exercise_db', 'Internal_Rotation_with_Band', ARRAY['Choke the band around a post. The band should be at the same height as your elbow. Stand with your right side to the band a couple of feet away.', 'Grasp the end of the band with your right hand, and keep your elbow pressed firmly to your side. We recommend you hold a pad or foam roll in place with your elbow to keep it firmly in position.', 'With your upper arm in position, your elbow should be flexed to 90 degrees with your hand reaching away from your torso. This will be your starting position.', 'Execute the movement by rotating your arm in a forehand motion, keeping your elbow in place.', 'Continue as far as you are able, pause, and then return to the starting position.']::text[], ARRAY['Internal_Rotation_with_Band/0.jpg', 'Internal_Rotation_with_Band/1.jpg']::text[], 'internal rotation with band xoay vai trong day khang luc rotacion interna con banda'),
  (NULL, 'Inverted Row', 'Chèo người ngược (inverted row)', 'Inverted Row', 'Remo invertido', 'back', 'other', 'bodyweight', 'free_exercise_db', 'Inverted_Row', ARRAY['Position a bar in a rack to about waist height. You can also use a smith machine.', 'Take a wider than shoulder width grip on the bar and position yourself hanging underneath the bar. Your body should be straight with your heels on the ground with your arms fully extended. This will be your starting position.', 'Begin by flexing the elbow, pulling your chest towards the bar. Retract your shoulder blades as you perform the movement.', 'Pause at the top of the motion, and return yourself to the start position.', 'Repeat for the desired number of repetitions.']::text[], ARRAY['Inverted_Row/0.jpg', 'Inverted_Row/1.jpg']::text[], 'inverted row cheo nguoi nguoc (inverted row) remo invertido'),
  (NULL, 'Inverted Row with Straps', 'Chèo người ngược với dây treo', 'Inverted Row with Straps', 'Remo invertido con correas', 'back', 'other', 'compound', 'free_exercise_db', 'Inverted_Row_with_Straps', ARRAY['Hang a rope or suspension straps from a rack or other stable object. Grasp the ends and position yourself in a supine position hanging from the ropes. Your body should be straight with your heels on the ground with your arms fully extended. This will be your starting position.', 'Begin by flexing the elbow, pulling your chest to your hands. Retract your shoulder blades as you perform the movement.', 'Pause at the top of the motion, and return yourself to the start position.', 'Repeat for the desired number of repetitions.']::text[], ARRAY['Inverted_Row_with_Straps/0.jpg', 'Inverted_Row_with_Straps/1.jpg']::text[], 'inverted row with straps cheo nguoi nguoc voi day treo remo invertido con correas'),
  (NULL, 'Iron Cross', 'Thập tự sắt tạ đơn', 'Iron Cross', 'Cruz de hierro con mancuernas', 'shoulders', 'dumbbell', 'compound', 'free_exercise_db', 'Iron_Cross', ARRAY[]::text[], ARRAY['Iron_Cross/0.jpg', 'Iron_Cross/1.jpg']::text[], 'iron cross thap tu sat ta don cruz de hierro con mancuernas'),
  (NULL, 'Iron Crosses (stretch)', 'Giãn cơ thập tự sắt', 'Iron Crosses (stretch)', 'Cruces de hierro (estiramiento)', 'legs', 'other', 'timed', 'free_exercise_db', 'Iron_Crosses_stretch', ARRAY['Lie face down on the floor, with your arms extended out to your side, palms pressed to the floor. This will be your starting position.', 'To begin, flex one knee and bring that leg across the back of your body, attempting to touch it to the ground near the opposite hand.', 'Promptly return the leg to the starting postion, and quickly repeat with the other leg. Continue alternating for 10-20 repetitions.']::text[], ARRAY['Iron_Crosses_stretch/0.jpg', 'Iron_Crosses_stretch/1.jpg']::text[], 'iron crosses (stretch) gian co thap tu sat cruces de hierro (estiramiento)'),
  (NULL, 'Isometric Chest Squeezes', 'Ép ngực giữ tĩnh', 'Isometric Chest Squeezes', 'Apretón isométrico de pecho', 'chest', 'bodyweight', 'bodyweight', 'free_exercise_db', 'Isometric_Chest_Squeezes', ARRAY['While either seating or standing, bend your arms at a 90-degree angle and place the palms of your hands together in front of your chest. Tip: Your hands should be open with the palms together and fingers facing forward (perpendicular to your torso).', 'Push both hands against each other as you contract your chest. Start with slow tension and increase slowly. Keep breathing normally as you execute this contraction.', 'Hold for the recommended number of seconds.', 'Now release the tension slowly.', 'Rest for the recommended amount of time and repeat.']::text[], ARRAY['Isometric_Chest_Squeezes/0.jpg', 'Isometric_Chest_Squeezes/1.jpg']::text[], 'isometric chest squeezes ep nguc giu tinh apreton isometrico de pecho'),
  (NULL, 'Isometric Neck Exercise - Front And Back', 'Giữ tĩnh cổ trước sau', 'Isometric Neck Exercise - Front And Back', 'Ejercicio isométrico de cuello adelante y atrás', 'shoulders', 'bodyweight', 'bodyweight', 'free_exercise_db', 'Isometric_Neck_Exercise_-_Front_And_Back', ARRAY['With your head and neck in a neutral position (normal position with head erect facing forward), place both of your hands on the front side of your head.', 'Now gently push forward as you contract the neck muscles but resisting any movement of your head. Start with slow tension and increase slowly. Keep breathing normally as you execute this contraction.', 'Hold for the recommended number of seconds.', 'Now release the tension slowly.', 'Rest for the recommended amount of time and repeat with your hands placed on the back side of your head.']::text[], ARRAY['Isometric_Neck_Exercise_-_Front_And_Back/0.jpg', 'Isometric_Neck_Exercise_-_Front_And_Back/1.jpg']::text[], 'isometric neck exercise - front and back giu tinh co truoc sau ejercicio isometrico de cuello adelante y atras'),
  (NULL, 'Isometric Neck Exercise - Sides', 'Giữ tĩnh cổ hai bên', 'Isometric Neck Exercise - Sides', 'Ejercicio isométrico de cuello lateral', 'shoulders', 'bodyweight', 'bodyweight', 'free_exercise_db', 'Isometric_Neck_Exercise_-_Sides', ARRAY['With your head and neck in a neutral position (normal position with head erect facing forward), place your left hand on the left side of your head.', 'Now gently push towards the left as you contract the left neck muscles but resisting any movement of your head. Start with slow tension and increase slowly. Keep breathing normally as you execute this contraction.', 'Hold for the recommended number of seconds.', 'Now release the tension slowly.', 'Rest for the recommended amount of time and repeat with your right hand placed on the right side of your head.']::text[], ARRAY['Isometric_Neck_Exercise_-_Sides/0.jpg', 'Isometric_Neck_Exercise_-_Sides/1.jpg']::text[], 'isometric neck exercise - sides giu tinh co hai ben ejercicio isometrico de cuello lateral'),
  (NULL, 'Isometric Wipers', 'Gạt nước giữ tĩnh', 'Isometric Wipers', 'Limpiaparabrisas isométrico', 'chest', 'bodyweight', 'bodyweight', 'free_exercise_db', 'Isometric_Wipers', ARRAY['Assume a push-up position, supporting your weight on your hands and toes while keeping your body straight. Your hands should be just outside of shoulder width. This will be your starting position.', 'Begin by shifting your body weight as far to one side as possible, allowing the elbow on that side to flex as you lower your body.', 'Reverse the motion by extending the flexed arm, pushing yourself up and then dropping to the other side.', 'Repeat for the desired number of repetitions.']::text[], ARRAY['Isometric_Wipers/0.jpg', 'Isometric_Wipers/1.jpg']::text[], 'isometric wipers gat nuoc giu tinh limpiaparabrisas isometrico'),
  (NULL, 'JM Press', 'Đẩy JM', 'JM Press', 'Press JM', 'triceps', 'barbell', 'compound', 'free_exercise_db', 'JM_Press', ARRAY['Start the exercise the same way you would a close grip bench press. You will lie on a flat bench while holding a barbell at arms length (fully extended) with the elbows in. However, instead of having the arms perpendicular to the torso, make sure the bar is set in a direct line above the upper chest. This will be your starting position.', 'Now beginning from a fully extended position lower the bar down as if performing a lying triceps extension. Inhale as you perform this movement. When you reach the half way point, let the bar roll back about one inch by moving the upper arms towards your legs until they are perpendicular to the torso. Tip: Keep the bend at the elbows constant as you bring the upper arms forward.', 'As you exhale, press the bar back up by using the triceps to perform a close grip bench press.', 'Now go back to the starting position and start over.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['JM_Press/0.jpg', 'JM_Press/1.jpg']::text[], 'jm press day jm press jm'),
  (NULL, 'Jackknife Sit-Up', 'Gập bụng dao gấp', 'Jackknife Sit-Up', 'Abdominales navaja', 'abs', 'bodyweight', 'bodyweight', 'free_exercise_db', 'Jackknife_Sit-Up', ARRAY['Lie flat on the floor (or exercise mat) on your back with your arms extended straight back behind your head and your legs extended also. This will be your starting position.', 'As you exhale, bend at the waist while simultaneously raising your legs and arms to meet in a jackknife position. Tip: The legs should be extended and lifted at approximately a 35-45 degree angle from the floor and the arms should be extended and parallel to your legs. The upper torso should be off the floor.', 'While inhaling, lower your arms and legs back to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Jackknife_Sit-Up/0.jpg', 'Jackknife_Sit-Up/1.jpg']::text[], 'jackknife sit-up gap bung dao gap abdominales navaja'),
  (NULL, 'Janda Sit-Up', 'Gập bụng Janda', 'Janda Sit-Up', 'Abdominales Janda', 'abs', 'bodyweight', 'bodyweight', 'free_exercise_db', 'Janda_Sit-Up', ARRAY['Position your body on the floor in the basic sit-up position; knees to a ninety degree angle with feet flat on the floor and arms either crossed over your chest or to the sides. This will be your starting position.', 'As you strongly tighten your glutes and hamstrings, fill your lungs with air and in a slow (three to six second count) ascent, slowly exhale. Tip: It is important to tighten the glutes and hamstrings as this will cause the hip flexors to be inactivated in a process called reciprocal inhibition, which basically means that opposite muscles to the contracted ones will relax.', 'As you inhale, slowly go back in a controlled manner to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Janda_Sit-Up/0.jpg', 'Janda_Sit-Up/1.jpg']::text[], 'janda sit-up gap bung janda abdominales janda'),
  (NULL, 'Jefferson Squats', 'Jefferson Squats', 'Jefferson Squats', 'Sentadilla Jefferson', 'legs', 'barbell', 'compound', 'free_exercise_db', 'Jefferson_Squats', ARRAY['Place a barbell on the floor.', 'Stand in the middle of the bar length wise.', 'Bend down by bending at the knees and keeping your back straight and grasp the front of the bar with your right hand. Your palm should be in (neutral grip) facing the left side.', 'Grasp the rear of the bar with your left hand. The palm of your hand should be in neutral grip alignment (palms facing the right side). Tip: Ensure that your grip is even on the bar. Your torso should be positioned right in the middle of the bar and the distance between your torso and your right hand (which should be at the front) should be the same as the distance between your torso and your left hand (which should be to your back).', 'Now stand straight up with the weight. Tip: Your feet should be shoulder width apart and your toes slightly pointed out.', 'Squat down by bending at the knees and keeping your back straight until your upper thighs are parallel with the floor. Tip: Keep your back as vertical as possible with the floor and your head up. Also remember to not let your knees go past your toes. Inhale during this portion of the movement.', 'Now drive yourself back up to the starting position by pushing with the feet . Tip: Keep the bar hanging at arm''s length and your elbows locked with a slight bend. The arms only serve as hooks. Avoid doing any lifting with them. Do the lifting with your thighs; not your arms.']::text[], ARRAY['Jefferson_Squats/0.jpg', 'Jefferson_Squats/1.jpg']::text[], 'jefferson squats squat jefferson sentadilla jefferson'),
  (NULL, 'Jerk Balance', 'Jerk Balance', 'Jerk Balance', 'Equilibrio de envión', 'shoulders', 'barbell', 'compound', 'free_exercise_db', 'Jerk_Balance', ARRAY['This drill helps you learn to drive yourself low enough during the jerk and corrects those who move backward during the movement. Begin with the bar racked in the jerk position, with the shoulders forward, torso upright, and the feet split slightly apart.', 'Initiate the movement as you would a normal jerk, dipping at the knees while keeping your torso vertical, and driving back up forcefully, using momentum and not your arms to elevate the weight.', 'Keep the rear foot in place, using it to drive your body forward into a full split as you jerk the weight. Recover by standing up with the weight overhead.']::text[], ARRAY['Jerk_Balance/0.jpg', 'Jerk_Balance/1.jpg']::text[], 'jerk balance jerk balance equilibrio de envion'),
  (NULL, 'Jerk Dip Squat', 'Jerk Dip Squat', 'Jerk Dip Squat', 'Flexión de envión', 'legs', 'barbell', 'compound', 'free_exercise_db', 'Jerk_Dip_Squat', ARRAY['This movement strengthens the dip portion of the jerk. Begin with the bar racked in the jerk position, with the shoulders forward to create a shelf and the bar lightly contacting the throat. The feet should be directly under the hips, with the feet turned out as is comfortable.', 'Keeping the torso vertical, dip by flexing the knees, allowing them to travel forward and without moving the hips to the rear. The dip should not be excessive. Return the weight to the starting position by driving forcefully though the feet.']::text[], ARRAY['Jerk_Dip_Squat/0.jpg', 'Jerk_Dip_Squat/1.jpg']::text[], 'jerk dip squat squat nhun kieu jerk flexion de envion'),
  (NULL, 'Jogging, Treadmill', 'Chạy chậm máy chạy bộ', 'Jogging, Treadmill', 'Trotar en cinta', 'cardio', 'machine', 'timed', 'free_exercise_db', 'Jogging_Treadmill', ARRAY['To begin, step onto the treadmill and select the desired option from the menu. Most treadmills have a manual setting, or you can select a program to run. Typically, you can enter your age and weight to estimate the amount of calories burned during exercise. Elevation can be adjusted to change the intensity of the workout.', 'Treadmills offer convenience, cardiovascular benefits, and usually have less impact than jogging outside. A 150 lb person will burn almost 250 calories jogging for 30 minutes, compared to more than 450 calories running. Maintain proper posture as you jog, and only hold onto the handles when necessary, such as when dismounting or checking your heart rate.']::text[], ARRAY['Jogging_Treadmill/0.jpg', 'Jogging_Treadmill/1.jpg']::text[], 'jogging, treadmill chay cham may chay bo trotar en cinta'),
  (NULL, 'Keg Load', 'Nâng thùng tạ', 'Keg Load', 'Carga de barril', 'back', 'other', 'compound', 'free_exercise_db', 'Keg_Load', ARRAY['To load kegs, place the desired number a distance from the loading platform, typically 30-50 feet.', 'Begin by grabbing the close handle of the first keg, tilting it onto its side to grab the opposite edge of the bottom of the keg. Lift the keg up to your chest.', 'The higher you can place the keg, the faster you should be able to move to the platform. Shouldering is usually not allowed. Be sure to keep a firm hold on the keg. Move as quickly as possible to the platform, and load it, extending through your hips, knees, and ankles to get it as high as possible.', 'Return to the starting position to retrieve the next keg, and repeat until the event is completed.']::text[], ARRAY['Keg_Load/0.jpg', 'Keg_Load/1.jpg']::text[], 'keg load nang thung ta carga de barril'),
  (NULL, 'Kettlebell Arnold Press', 'Kettlebell Arnold Press', 'Kettlebell Arnold Press', 'Press Arnold con pesa rusa', 'shoulders', 'kettlebell', 'compound', 'free_exercise_db', 'Kettlebell_Arnold_Press', ARRAY['Clean a kettlebell to your shoulder. Clean the kettlebell to your shoulder by extending through the legs and hips as you raise the kettlebell towards your shoulder. The palm should be facing inward.', 'Looking straight ahead, press the kettlebell out and overhead, rotating your wrist so that your palm faces forward at the top of the motion.', 'Return the kettlebell to the starting position, with the palm facing in.']::text[], ARRAY['Kettlebell_Arnold_Press/0.jpg', 'Kettlebell_Arnold_Press/1.jpg']::text[], 'kettlebell arnold press day vai arnold kettlebell press arnold con pesa rusa'),
  (NULL, 'Kettlebell Dead Clean', 'Kettlebell Dead Clean', 'Kettlebell Dead Clean', 'Cargada muerta con pesa rusa', 'legs', 'kettlebell', 'compound', 'free_exercise_db', 'Kettlebell_Dead_Clean', ARRAY['Place kettlebell between your feet. To get in the starting position, push your butt back and look straight ahead.', 'Clean the kettlebell to your shoulder. Clean the kettlebell to your shoulders by extending through the legs and hips as you raise the kettlebell towards your shoulder. The wrist should rotate as you do so.', 'Lower the kettlebell, keeping the hamstrings loaded by keeping your back straight and your butt out.']::text[], ARRAY['Kettlebell_Dead_Clean/0.jpg', 'Kettlebell_Dead_Clean/1.jpg']::text[], 'kettlebell dead clean dead clean kettlebell cargada muerta con pesa rusa'),
  (NULL, 'Kettlebell Figure 8', 'Số 8 kettlebell', 'Kettlebell Figure 8', 'Ocho con pesa rusa', 'abs', 'kettlebell', 'compound', 'free_exercise_db', 'Kettlebell_Figure_8', ARRAY['Place one kettlebell between your legs and take a wider than shoulder width stance. Bend over by pushing your butt out and keeping your back flat.', 'Pick up a kettlebell and pass it to your other hand between your legs. The receiving hand should reach from behind the legs. Go back and forth for several repetitions.']::text[], ARRAY['Kettlebell_Figure_8/0.jpg', 'Kettlebell_Figure_8/1.jpg']::text[], 'kettlebell figure 8 so 8 kettlebell ocho con pesa rusa'),
  (NULL, 'Kettlebell Halo', 'Vòng hào quang kettlebell', 'Kettlebell Halo', 'Halo con pesa rusa', 'shoulders', 'kettlebell', 'compound', 'free_exercise_db', 'Kettlebell_Halo', ARRAY['Stand tall with your feet hip-width apart. Hold a kettlebell upside down by the horns, with the bell above your hands and close to your chest. Brace your abdominals and squeeze your glutes so your ribcage stays down. This is your starting position.', 'Keeping your elbows close to your head, move the kettlebell up past one ear and around behind your head.', 'Continue the circle past the opposite ear and back down to the starting position in front of your chest, letting the bell pass close to your body throughout.', 'Complete the prescribed number of circles in one direction, then repeat the same number in the opposite direction.', 'Move slowly and keep your head, hips and lower back still. If your lower back arches or the bell drifts far from your head, use a lighter weight.']::text[], ARRAY[]::text[], 'kettlebell halo vong hao quang kettlebell halo con pesa rusa'),
  (NULL, 'Kettlebell Halo with Overhead Extension', 'Vòng hào quang kettlebell kèm duỗi qua đầu', 'Kettlebell Halo with Overhead Extension', 'Halo con pesa rusa y extensión', 'shoulders', 'kettlebell', 'compound', 'free_exercise_db', 'Kettlebell_Halo_With_Overhead_Extension', ARRAY['Stand tall with your feet hip-width apart. Hold a kettlebell upside down by the horns, with the bell above your hands and close to your chest. Brace your abdominals and squeeze your glutes so your ribcage stays down. This is your starting position.', 'Keeping your elbows close to your head, move the kettlebell up past one ear and around until it sits behind your head. Pause here.', 'From this position, extend your elbows to press the kettlebell up and overhead until your arms are straight, keeping your upper arms alongside your head.', 'Bend your elbows to lower the kettlebell back to the pause position behind your head, under control.', 'Continue the circle past the opposite ear and back down to the starting position in front of your chest to complete one repetition.', 'Alternate the direction of the circle on each repetition. Keep your head, hips and lower back still throughout; if your lower back arches or you cannot reach the overhead position without leaning back, use a lighter weight or perform the halo and the extension as separate exercises.']::text[], ARRAY[]::text[], 'kettlebell halo with overhead extension vong hao quang kettlebell kem duoi qua dau halo con pesa rusa y extension'),
  (NULL, 'Kettlebell Hang Clean', 'Kettlebell Hang Clean', 'Kettlebell Hang Clean', 'Cargada colgante con pesa rusa', 'legs', 'kettlebell', 'compound', 'free_exercise_db', 'Kettlebell_Hang_Clean', ARRAY['Place kettlebell between your feet. To get in the starting position, push your butt back and look straight ahead.', 'Clean kettlebell to your shoulder. Clean the kettlebell to your shoulders by extending through the legs and hips as you raise the kettlebell towards your shoulder. The wrist should rotate as you do so.', 'Lower kettlebell to a hanging position between your legs while keeping the hamstrings loaded. Keep your head up at all times.']::text[], ARRAY['Kettlebell_Hang_Clean/0.jpg', 'Kettlebell_Hang_Clean/1.jpg']::text[], 'kettlebell hang clean hang clean kettlebell cargada colgante con pesa rusa'),
  (NULL, 'Kettlebell One-Legged Deadlift', 'Kettlebell One-Legged Deadlift', 'Kettlebell One-Legged Deadlift', 'Peso muerto a una pierna con pesa rusa', 'legs', 'kettlebell', 'compound', 'free_exercise_db', 'Kettlebell_One-Legged_Deadlift', ARRAY['Hold a kettlebell by the handle in one hand. Stand on one leg, on the same side that you hold the kettlebell.', 'Keeping that knee slightly bent, perform a stiff legged deadlift by bending at the hip, extending your free leg behind you for balance.', 'Continue lowering the kettlebell until you are parallel to the ground, and then return to the upright position.']::text[], ARRAY['Kettlebell_One-Legged_Deadlift/0.jpg', 'Kettlebell_One-Legged_Deadlift/1.jpg']::text[], 'kettlebell one-legged deadlift deadlift mot chan kettlebell peso muerto a una pierna con pesa rusa'),
  (NULL, 'Kettlebell Overhead Triceps Extension', 'Duỗi tay sau qua đầu kettlebell', 'Kettlebell Overhead Triceps Extension', 'Extensión de tríceps sobre la cabeza con pesa rusa', 'triceps', 'kettlebell', 'isolation', 'free_exercise_db', 'Kettlebell_Overhead_Triceps_Extension', ARRAY['Stand with your feet hip-width apart, holding a kettlebell by the horns with both hands. Press it overhead until your arms are extended, with the bell hanging behind your hands.', 'Brace your abdominals and keep your upper arms vertical and close to your head. This is your starting position.', 'Bend at the elbows to lower the kettlebell behind your head, going as far as your shoulder mobility allows without your elbows flaring outward.', 'Extend your elbows to press the kettlebell back to the starting position, keeping your upper arms still throughout.', 'Keep your ribcage down and avoid arching your lower back as you extend.']::text[], ARRAY[]::text[], 'kettlebell overhead triceps extension duoi tay sau qua dau kettlebell extension de triceps sobre la cabeza con pesa rusa'),
  (NULL, 'Kettlebell Pass Between The Legs', 'Chuyền kettlebell qua chân', 'Kettlebell Pass Between The Legs', 'Pase de pesa rusa entre las piernas', 'abs', 'kettlebell', 'compound', 'free_exercise_db', 'Kettlebell_Pass_Between_The_Legs', ARRAY['Place one kettlebell between your legs and take a comfortable stance. Bend over by pushing your butt out and keeping your back flat.', 'Pick up a kettlebell and pass it to your other hand between your legs, in the fashion of a "W". Go back and forth for several repetitions.']::text[], ARRAY['Kettlebell_Pass_Between_The_Legs/0.jpg', 'Kettlebell_Pass_Between_The_Legs/1.jpg']::text[], 'kettlebell pass between the legs chuyen kettlebell qua chan pase de pesa rusa entre las piernas'),
  (NULL, 'Kettlebell Pirate Ships', 'Lắc thuyền kettlebell', 'Kettlebell Pirate Ships', 'Barco pirata con pesa rusa', 'shoulders', 'kettlebell', 'compound', 'free_exercise_db', 'Kettlebell_Pirate_Ships', ARRAY['With a wide stance, hold a kettlebell with both hands. Allow it to hang at waist level with your arms extended. This will be your starting position.', 'Initiate the movement by turning to one side, swinging the kettlebell to head height. Briefly pause at the top of the motion.', 'Allow the bell to drop as you rotate to the opposite side, again raising the kettlebell to head height.', 'Repeat for the desired amount of repetitions.']::text[], ARRAY['Kettlebell_Pirate_Ships/0.jpg', 'Kettlebell_Pirate_Ships/1.jpg']::text[], 'kettlebell pirate ships lac thuyen kettlebell barco pirata con pesa rusa'),
  (NULL, 'Kettlebell Pistol Squat', 'Kettlebell Pistol Squat', 'Kettlebell Pistol Squat', 'Sentadilla pistol con pesa rusa', 'legs', 'kettlebell', 'compound', 'free_exercise_db', 'Kettlebell_Pistol_Squat', ARRAY['Pick up a kettlebell with two hands and hold it by the horns. Hold one leg off of the floor and squat down on the other.', 'Squat down by flexing the knee and sitting back with the hips, holding the kettlebell up in front of you.', 'Hold the bottom position for a second and then reverse the motion, driving through the heel and keeping your head and chest up.', 'Lower yourself again and repeat.']::text[], ARRAY['Kettlebell_Pistol_Squat/0.jpg', 'Kettlebell_Pistol_Squat/1.jpg']::text[], 'kettlebell pistol squat squat mot chan kettlebell sentadilla pistol con pesa rusa'),
  (NULL, 'Kettlebell Seated Press', 'Đẩy vai ngồi kettlebell', 'Kettlebell Seated Press', 'Press sentado con pesa rusa', 'shoulders', 'kettlebell', 'compound', 'free_exercise_db', 'Kettlebell_Seated_Press', ARRAY['Sit on the floor and spread your legs out comfortably.', 'Clean one kettlebell to your shoulder.', 'Press the kettlebell up and out until it is locked out overhead. Return to the starting position.']::text[], ARRAY['Kettlebell_Seated_Press/0.jpg', 'Kettlebell_Seated_Press/1.jpg']::text[], 'kettlebell seated press day vai ngoi kettlebell press sentado con pesa rusa'),
  (NULL, 'Kettlebell Seesaw Press', 'Đẩy vai bập bênh kettlebell', 'Kettlebell Seesaw Press', 'Press balancín con pesas rusas', 'shoulders', 'kettlebell', 'compound', 'free_exercise_db', 'Kettlebell_Seesaw_Press', ARRAY['Clean two kettlebells two your shoulders.', 'Press one kettlebell.', 'Lower the kettlebell and immediately press the other kettlebell. Make sure to do the same amount of reps on both sides.']::text[], ARRAY['Kettlebell_Seesaw_Press/0.jpg', 'Kettlebell_Seesaw_Press/1.jpg']::text[], 'kettlebell seesaw press day vai bap benh kettlebell press balancin con pesas rusas'),
  (NULL, 'Kettlebell Sumo High Pull', 'Kéo cao sumo kettlebell', 'Kettlebell Sumo High Pull', 'Tirón alto sumo con pesa rusa', 'shoulders', 'kettlebell', 'compound', 'free_exercise_db', 'Kettlebell_Sumo_High_Pull', ARRAY['Place a kettlebell on the ground between your feet. Position your feet in a wide stance, and grasp the kettlebell with two hands. Set your hips back as far as possible, with your knees bent. Keep your chest and head up. This will be your starting position.', 'Begin by extending the hips and knees, simultaneously pulling the kettlebell to your shoulders, raising your elbows as you do so. Reverse the motion to return to the starting position.']::text[], ARRAY['Kettlebell_Sumo_High_Pull/0.jpg', 'Kettlebell_Sumo_High_Pull/1.jpg']::text[], 'kettlebell sumo high pull keo cao sumo kettlebell tiron alto sumo con pesa rusa'),
  (NULL, 'Kettlebell Thruster', 'Kettlebell Thruster', 'Kettlebell Thruster', 'Thruster con pesa rusa', 'shoulders', 'kettlebell', 'compound', 'free_exercise_db', 'Kettlebell_Thruster', ARRAY['Clean two kettlebells to your shoulders. Clean the kettlebells to your shoulders by extending through the legs and hips as you pull the kettlebells towards your shoulders. Rotate your wrists as you do so. This will be your starting position.', 'Begin to squat by flexing your hips and knees, lowering your hips between your legs. Maintain an upright, straight back as you descend as low as you can.', 'At the bottom, reverse direction and squat by extending your knees and hips, driving through your heels. As you do so, press both kettlebells overhead by extending your arms straight up, using the momentum from the squat to help drive the weights upward.', 'As you begin the next repetition, return the weights to the shoulders.']::text[], ARRAY['Kettlebell_Thruster/0.jpg', 'Kettlebell_Thruster/1.jpg']::text[], 'kettlebell thruster thruster kettlebell thruster con pesa rusa'),
  (NULL, 'Kettlebell Turkish Get-Up (Lunge style)', 'Kettlebell Turkish Get-Up (Lunge style)', 'Kettlebell Turkish Get-Up (Lunge style)', 'Levantamiento turco con pesa rusa (zancada)', 'shoulders', 'kettlebell', 'compound', 'free_exercise_db', 'Kettlebell_Turkish_Get-Up_Lunge_style', ARRAY['Lie on your back on the floor and press a kettlebell to the top position by extending the elbow. Bend the knee on the same side as the kettlebell.', 'Keeping the kettlebell locked out at all times, pivot to the opposite side and use your non- working arm to assist you in driving forward to the lunge position. Using your free hand, push yourself to a seated position, then progressing to one knee.', 'While looking up at the kettlebell, slowly stand up. Reverse the motion back to the starting position and repeat.']::text[], ARRAY['Kettlebell_Turkish_Get-Up_Lunge_style/0.jpg', 'Kettlebell_Turkish_Get-Up_Lunge_style/1.jpg']::text[], 'kettlebell turkish get-up (lunge style) turkish get-up kettlebell (kieu chung chan) levantamiento turco con pesa rusa (zancada)'),
  (NULL, 'Kettlebell Turkish Get-Up (Squat style)', 'Kettlebell Turkish Get-Up (Squat style)', 'Kettlebell Turkish Get-Up (Squat style)', 'Levantamiento turco con pesa rusa (sentadilla)', 'shoulders', 'kettlebell', 'compound', 'free_exercise_db', 'Kettlebell_Turkish_Get-Up_Squat_style', ARRAY['Lie on your back on the floor and press a kettlebell to the top position by extending the elbow. Bend the knee on the same side as the kettlebell.', 'Keeping the kettlebell locked out at all times, pivot to the opposite side and use your non- working arm to assist you in driving forward to the lunge position.', 'Using your free hand, push yourself to a seated position, then progressing to your feet. While looking up at the kettlebell, slowly stand up. Reverse the motion back to the starting position and repeat.']::text[], ARRAY['Kettlebell_Turkish_Get-Up_Squat_style/0.jpg', 'Kettlebell_Turkish_Get-Up_Squat_style/1.jpg']::text[], 'kettlebell turkish get-up (squat style) turkish get-up kettlebell (kieu squat) levantamiento turco con pesa rusa (sentadilla)'),
  (NULL, 'Kettlebell Windmill', 'Cối xay gió kettlebell', 'Kettlebell Windmill', 'Molino con pesa rusa', 'abs', 'kettlebell', 'compound', 'free_exercise_db', 'Kettlebell_Windmill', ARRAY['Place a kettlebell in front of your lead foot and clean and press it overhead with your opposite arm. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulders. Rotate your wrist as you do so, so that the palm faces forward. Press it overhead by extending the elbow.', 'Keeping the kettlebell locked out at all times, push your butt out in the direction of the locked out kettlebell. Turn your feet out at a forty-five degree angle from the arm with the locked out kettlebell. Bending at the hip to one side, sticking your butt out, slowly lean until you can touch the floor with your free hand. Keep your eyes on the kettlebell that you hold over your head at all times.', 'Pause for a second after reaching the ground and reverse the motion back to the starting position.']::text[], ARRAY['Kettlebell_Windmill/0.jpg', 'Kettlebell_Windmill/1.jpg']::text[], 'kettlebell windmill coi xay gio kettlebell molino con pesa rusa'),
  (NULL, 'Kipping Muscle Up', 'Kipping Muscle Up', 'Kipping Muscle Up', 'Muscle up con impulso', 'back', 'other', 'compound', 'free_exercise_db', 'Kipping_Muscle_Up', ARRAY['Grip the rings using a false grip, with the base of your palms on top of the rings.', 'Begin with a movement swinging your legs backward slightly.', 'Counter that movement by swinging your legs forward and up, jerking your chin and chest back, pulling yourself up with both arms as you do so. As you reach the top position of the pull-up, pull the rings to your armpits as you roll your shoulders forward, allowing your elbows to move straight back behind you. This puts you into the proper position to continue into the dip portion of the movement.', 'Maintaining control and stability, extend through the elbow to complete the motion.', 'Use care when lowering yourself to the ground.']::text[], ARRAY['Kipping_Muscle_Up/0.jpg', 'Kipping_Muscle_Up/1.jpg']::text[], 'kipping muscle up muscle up co da muscle up con impulso'),
  (NULL, 'Knee Across The Body', 'Kéo gối chéo người', 'Knee Across The Body', 'Rodilla cruzada sobre el cuerpo', 'glutes', 'other', 'timed', 'free_exercise_db', 'Knee_Across_The_Body', ARRAY['Lie down on the floor with your right leg straight. Bend your left leg and lower it across your body, holding the knee down toward the floor with your right hand. (The knee doesn''t need to touch the floor if you''re tight.)', 'Place your left arm comfortably beside you and turn your head to the left. Imagine you have a weight tied to your tailbone. let your tailbone fall back toward the floor as your chest reaches in the opposite direction to stretch your lower back. Switch sides.']::text[], ARRAY['Knee_Across_The_Body/0.jpg', 'Knee_Across_The_Body/1.jpg']::text[], 'knee across the body keo goi cheo nguoi rodilla cruzada sobre el cuerpo'),
  (NULL, 'Knee Circles', 'Xoay gối', 'Knee Circles', 'Círculos de rodilla', 'calves', 'bodyweight', 'timed', 'free_exercise_db', 'Knee_Circles', ARRAY['Stand with your legs together and hands by your waist.', 'Now move your knees in a circular motion as you breathe normally.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Knee_Circles/0.jpg', 'Knee_Circles/1.jpg']::text[], 'knee circles xoay goi circulos de rodilla'),
  (NULL, 'Knee/Hip Raise On Parallel Bars', 'Nâng gối trên xà kép', 'Knee/Hip Raise On Parallel Bars', 'Elevación de rodillas en paralelas', 'abs', 'other', 'isolation', 'free_exercise_db', 'Knee_Hip_Raise_On_Parallel_Bars', ARRAY['Position your body on the vertical leg raise bench so that your forearms are resting on the pads next to the torso and holding on to the handles. Your arms will be bent at a 90 degree angle.', 'The torso should be straight with the lower back pressed against the pad of the machine and the legs extended pointing towards the floor. This will be your starting position.', 'Now as you breathe out, lift your legs up as you keep them extended. Continue this movement until your legs are roughly parallel to the floor and then hold the contraction for a second. Tip: Do not use any momentum or swinging as you perform this exercise.', 'Slowly go back to the starting position as you breathe in.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Knee_Hip_Raise_On_Parallel_Bars/0.jpg', 'Knee_Hip_Raise_On_Parallel_Bars/1.jpg']::text[], 'knee/hip raise on parallel bars nang goi tren xa kep elevacion de rodillas en paralelas'),
  (NULL, 'Knee Tuck Jump', 'Bật nhảy co gối', 'Knee Tuck Jump', 'Salto con rodillas al pecho', 'legs', 'bodyweight', 'bodyweight', 'free_exercise_db', 'Knee_Tuck_Jump', ARRAY['Begin in a comfortable standing position with your knees slightly bent. Hold your hands in front of you, palms down with your fingertips together at chest height. This will be your starting position.', 'Rapidly dip down into a quarter squat and immediately explode upward. Drive the knees towards the chest, attempting to touch them to the palms of the hands.', 'Jump as high as you can, raising your knees up, and then ensure a good land be re-extending your legs, absorbing impact through be allowing the knees to rebend.']::text[], ARRAY['Knee_Tuck_Jump/0.jpg', 'Knee_Tuck_Jump/1.jpg']::text[], 'knee tuck jump bat nhay co goi salto con rodillas al pecho'),
  (NULL, 'Kneeling Arm Drill', 'Tập vung tay tư thế quỳ', 'Kneeling Arm Drill', 'Ejercicio de brazos de rodillas', 'shoulders', 'other', 'bodyweight', 'free_exercise_db', 'Kneeling_Arm_Drill', ARRAY['This drill helps increase arm efficiency during the run. Begin kneeling, left foot in front, right knee down. Apply pressure through the front heel to keep your glutes and hamstrings activated.', 'Begin by blocking the arms in long, pendulum like swings. Close the arm angle, blocking with the arms as you would when jogging, progressing to a run and finally a sprint.', 'As soon as your hands pass the hip, accelerate them forward during the sprinting motion to move them as quickly as possible.', 'Switch knees and repeat.']::text[], ARRAY['Kneeling_Arm_Drill/0.jpg', 'Kneeling_Arm_Drill/1.jpg']::text[], 'kneeling arm drill tap vung tay tu the quy ejercicio de brazos de rodillas'),
  (NULL, 'Kneeling Cable Crunch With Alternating Oblique Twists', 'Kneeling Cable Crunch With Alternating Oblique Twists', 'Kneeling Cable Crunch With Alternating Oblique Twists', 'Crunch en polea de rodillas con giro oblicuo alterno', 'abs', 'cable', 'isolation', 'free_exercise_db', 'Kneeling_Cable_Crunch_With_Alternating_Oblique_Twists', ARRAY['Connect a rope attachment to a high pulley cable and position a mat on the floor in front of it.', 'Grab the rope with both hands and kneel approximately two feet back from the tower.', 'Position the rope behind your head with your hands by your ears.', 'Keep your hands in the same place, contract your abs and pull downward on the rope in a crunching movement until your elbows reach your knees.', 'Pause briefly at the bottom and rise up in a slow and controlled manner until you reach the starting position.', 'Repeat the same downward movement until you''re halfway down, at which time you''ll begin rotating one of your elbows to the opposite knee.', 'Again, pause briefly at the bottom and rise up in a slow and controlled manner until you reach the starting position.', 'Repeat the same movement as before, but alternate the other elbow to the opposite knee.', 'Continue this series of movements to failure.']::text[], ARRAY['Kneeling_Cable_Crunch_With_Alternating_Oblique_Twists/0.jpg', 'Kneeling_Cable_Crunch_With_Alternating_Oblique_Twists/1.jpg']::text[], 'kneeling cable crunch with alternating oblique twists gap bung cap quy xoay xien luan phien crunch en polea de rodillas con giro oblicuo alterno'),
  (NULL, 'Kneeling Cable Triceps Extension', 'Duỗi tay sau cáp quỳ', 'Kneeling Cable Triceps Extension', 'Extensión de tríceps de rodillas en polea', 'triceps', 'cable', 'isolation', 'free_exercise_db', 'Kneeling_Cable_Triceps_Extension', ARRAY['Place a bench sideways in front of a high pulley machine.', 'Hold a straight bar attachment above your head with your hands about 6 inches apart with your palms facing down.', 'Face away from the machine and kneel.', 'Place your head and the back of your upper arms on the bench. Your elbows should be bent with the forearms pointing towards the high pulley. This will be your starting position.', 'While keeping your upper arms close to your head at all times with the elbows in, press the bar out in a semicircular motion until the elbows are locked and your arms are parallel to the floor. Contract the triceps hard and keep this position for a second. Exhale as you perform this movement.', 'Slowly return to the starting position as you breathe in.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Kneeling_Cable_Triceps_Extension/0.jpg', 'Kneeling_Cable_Triceps_Extension/1.jpg']::text[], 'kneeling cable triceps extension duoi tay sau cap quy extension de triceps de rodillas en polea'),
  (NULL, 'Kneeling Forearm Stretch', 'Giãn cẳng tay tư thế quỳ', 'Kneeling Forearm Stretch', 'Estiramiento de antebrazo de rodillas', 'biceps', 'other', 'timed', 'free_exercise_db', 'Kneeling_Forearm_Stretch', ARRAY['Start by kneeling on a mat with your palms flat and your fingers pointing back toward your knees.', 'Slowly lean back keeping your palms flat on the floor until you feel a stretch in your wrists and forearms. Hold for 20-30 seconds.']::text[], ARRAY['Kneeling_Forearm_Stretch/0.jpg', 'Kneeling_Forearm_Stretch/1.jpg']::text[], 'kneeling forearm stretch gian cang tay tu the quy estiramiento de antebrazo de rodillas'),
  (NULL, 'Kneeling High Pulley Row', 'Chèo cáp cao tư thế quỳ', 'Kneeling High Pulley Row', 'Remo en polea alta de rodillas', 'back', 'cable', 'compound', 'free_exercise_db', 'Kneeling_High_Pulley_Row', ARRAY['Select the appropriate weight using a pulley that is above your head. Attach a rope to the cable and kneel a couple of feet away, holding the rope out in front of you with both arms extended. This will be your starting position.', 'Initiate the movement by flexing the elbows and fully retracting your shoulders, pulling the rope toward your upper chest with your elbows out.', 'After pausing briefly, slowly return to the starting position.']::text[], ARRAY['Kneeling_High_Pulley_Row/0.jpg', 'Kneeling_High_Pulley_Row/1.jpg']::text[], 'kneeling high pulley row cheo cap cao tu the quy remo en polea alta de rodillas'),
  (NULL, 'Kneeling Hip Flexor', 'Giãn cơ gấp hông tư thế quỳ', 'Kneeling Hip Flexor', 'Estiramiento de flexor de cadera de rodillas', 'legs', 'other', 'timed', 'free_exercise_db', 'Kneeling_Hip_Flexor', ARRAY['Kneel on a mat and bring your right knee up so the bottom of your foot is on the floor and extend your left leg out behind you so the top of your foot is on the floor.', 'Shift your weight forward until you feel a stretch in your hip. Hold for 15 seconds, then repeat for your other side.']::text[], ARRAY['Kneeling_Hip_Flexor/0.jpg', 'Kneeling_Hip_Flexor/1.jpg']::text[], 'kneeling hip flexor gian co gap hong tu the quy estiramiento de flexor de cadera de rodillas'),
  (NULL, 'Kneeling Jump Squat', 'Kneeling Jump Squat', 'Kneeling Jump Squat', 'Sentadilla con salto desde rodillas', 'glutes', 'barbell', 'compound', 'free_exercise_db', 'Kneeling_Jump_Squat', ARRAY['Begin kneeling on the floor with a barbell racked across the back of your shoulders, or you can use your body weight for this exercise. This can be done inside of a power rack to make unracking easier.', 'Sit back with your hips until your glutes touch your feet, keeping your head and chest up.', 'Explode up with your hips, generating enough power to land with your feet flat on the floor.', 'Continue with the squat by driving through your heels and extending the knees to come to a standing position.']::text[], ARRAY['Kneeling_Jump_Squat/0.jpg', 'Kneeling_Jump_Squat/1.jpg']::text[], 'kneeling jump squat squat bat nhay tu tu the quy sentadilla con salto desde rodillas'),
  (NULL, 'Kneeling Single-Arm High Pulley Row', 'Chèo cáp cao một tay tư thế quỳ', 'Kneeling Single-Arm High Pulley Row', 'Remo en polea alta a una mano de rodillas', 'back', 'cable', 'compound', 'free_exercise_db', 'Kneeling_Single-Arm_High_Pulley_Row', ARRAY['Attach a single handle to a high pulley and make your weight selection.', 'Kneel in front of the cable tower, taking the cable with one hand with your arm extended. This will be your starting position.', 'Starting with your palm facing forward, pull the weight down to your torso by flexing the elbow and retract the shoulder blade. As you do so, rotate the wrist so that at the completion of the movement, your palm is now facing you.', 'After a brief pause, return to the starting position.']::text[], ARRAY['Kneeling_Single-Arm_High_Pulley_Row/0.jpg', 'Kneeling_Single-Arm_High_Pulley_Row/1.jpg']::text[], 'kneeling single-arm high pulley row cheo cap cao mot tay tu the quy remo en polea alta a una mano de rodillas'),
  (NULL, 'Kneeling Squat', 'Kneeling Squat', 'Kneeling Squat', 'Sentadilla de rodillas', 'glutes', 'barbell', 'compound', 'free_exercise_db', 'Kneeling_Squat', ARRAY['Set the bar to the proper height in a power rack. Kneel behind the bar; it may be beneficial to put a mat down to pad your knees. Slide under the bar, racking it across the back of your shoulders. Your shoulder blades should be retracted and the bar tight across your back. Unrack the weight.', 'With your head looking forward, sit back with your butt until you touch your calves.', 'Reverse the motion, returning the torso to an upright position.']::text[], ARRAY['Kneeling_Squat/0.jpg', 'Kneeling_Squat/1.jpg']::text[], 'kneeling squat squat quy sentadilla de rodillas'),
  (NULL, 'Landmine 180''s', 'Xoay landmine 180', 'Landmine 180''s', 'Landmine 180', 'abs', 'barbell', 'compound', 'free_exercise_db', 'Landmine_180s', ARRAY['Position a bar into a landmine or securely anchor it in a corner. Load the bar to an appropriate weight.', 'Raise the bar from the floor, taking it to shoulder height with both hands with your arms extended in front of you. Adopt a wide stance. This will be your starting position.', 'Perform the movement by rotating the trunk and hips as you swing the weight all the way down to one side. Keep your arms extended throughout the exercise.', 'Reverse the motion to swing the weight all the way to the opposite side.', 'Continue alternating the movement until the set is complete.']::text[], ARRAY['Landmine_180s/0.jpg', 'Landmine_180s/1.jpg']::text[], 'landmine 180''s xoay landmine 180 landmine 180'),
  (NULL, 'Landmine Linear Jammer', 'Đẩy landmine thẳng', 'Landmine Linear Jammer', 'Landmine empuje lineal', 'shoulders', 'barbell', 'compound', 'free_exercise_db', 'Landmine_Linear_Jammer', ARRAY['Position a bar into landmine or, lacking one, securely anchor it in a corner. Load the bar to an appropriate weight and position the handle attachment on the bar.', 'Raise the bar from the floor, taking the handles to your shoulders. This will be your starting position.', 'In an athletic stance, squat by flexing your hips and setting your hips back, keeping your arms flexed.', 'Reverse the motion by powerfully extending through the hips, knees, and ankles, while also extending the elbows to straighten the arms. This movement should be done explosively, coming out of the squat to full extension as powerfully as possible.', 'Return to the starting position.']::text[], ARRAY['Landmine_Linear_Jammer/0.jpg', 'Landmine_Linear_Jammer/1.jpg']::text[], 'landmine linear jammer day landmine thang landmine empuje lineal'),
  (NULL, 'Lateral Bound', 'Bật nhảy ngang', 'Lateral Bound', 'Salto lateral', 'legs', 'bodyweight', 'bodyweight', 'free_exercise_db', 'Lateral_Bound', ARRAY['Assume a half squat position facing 90 degrees from your direction of travel. This will be your starting position.', 'Allow your lead leg to do a countermovement inward as you shift your weight to the outside leg.', 'Immediately push off and extend, attempting to bound to the side as far as possible.', 'Upon landing, immediately push off in the opposite direction, returning to your original start position.', 'Continue back and forth for several repetitions.']::text[], ARRAY['Lateral_Bound/0.jpg', 'Lateral_Bound/1.jpg']::text[], 'lateral bound bat nhay ngang salto lateral'),
  (NULL, 'Lateral Box Jump', 'Lateral Box Jump', 'Lateral Box Jump', 'Salto lateral al cajón', 'legs', 'other', 'compound', 'free_exercise_db', 'Lateral_Box_Jump', ARRAY['Assume a comfortable standing position, with a short box positioned next to you. This will be your starting position.', 'Quickly dip into a quarter squat to initiate the stretch reflex, and immediately reverse direction to jump up and to the side.', 'Bring your knees high enough to ensure your feet have good clearance over the box.', 'Land on the center of the box, using your legs to absorb the impact.', 'Carefully jump down to the other side of the box, and continue going back and forth for several repetitions.']::text[], ARRAY['Lateral_Box_Jump/0.jpg', 'Lateral_Box_Jump/1.jpg']::text[], 'lateral box jump bat nhay len buc ngang salto lateral al cajon'),
  (NULL, 'Lateral Cone Hops', 'Bật nhảy ngang qua cọc', 'Lateral Cone Hops', 'Saltos laterales de conos', 'legs', 'other', 'compound', 'free_exercise_db', 'Lateral_Cone_Hops', ARRAY['Position a number of cones in a row several feet apart.', 'Stand next to the end of the cones, facing 90 degrees to the direction of travel. This will be your starting position.', 'Begin the jump by dipping with the knees to initiate a stretch reflex, and immediately reverse direction to push off the ground, jumping up and sideways over the cone.', 'Use your legs to absorb impact upon landing, and rebound into the next jump, continuing down the row of cones.']::text[], ARRAY['Lateral_Cone_Hops/0.jpg', 'Lateral_Cone_Hops/1.jpg']::text[], 'lateral cone hops bat nhay ngang qua coc saltos laterales de conos'),
  (NULL, 'Lateral Raise - With Bands', 'Nâng tạ ngang dây kháng lực', 'Lateral Raise - With Bands', 'Elevación lateral con banda', 'shoulders', 'band', 'isolation', 'free_exercise_db', 'Lateral_Raise_-_With_Bands', ARRAY['To begin, stand on an exercise band so that tension begins at arm''s length. Grasp the handles using a pronated (palms facing your thighs) grip that is slightly less than shoulder width. The handles should be resting on the sides of your thighs. Your arms should be extended with a slight bend at the elbows and your back should be straight. This will be your starting position.', 'Use your side shoulders to lift the handles to the sides as you exhale. Continue to lift the handles until they are slightly above parallel. Tip: As you lift the handles, slightly tilt the hand as if you were pouring water and keep your arms extended. Also, keep your torso stationary and pause for a second at the top of the movement.', 'Lower the handles back down slowly to the starting position. Inhale as you perform this portion of the movement.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Lateral_Raise_-_With_Bands/0.jpg', 'Lateral_Raise_-_With_Bands/1.jpg']::text[], 'lateral raise - with bands nang ta ngang day khang luc elevacion lateral con banda'),
  (NULL, 'Latissimus Dorsi-SMR', 'Lăn giãn cơ xô', 'Latissimus Dorsi-SMR', 'Liberación del dorsal ancho', 'back', 'foam roll', 'timed', 'free_exercise_db', 'Latissimus_Dorsi-SMR', ARRAY['While lying on the floor, place a foam roll under your back and to one side, just behind your arm pit. This will be your starting position.', 'Keep the arm of the side being stretched behind and to the side of you as you shift your weight onto your lats, keeping your upper body off of the ground. Hold for 10-30 seconds, and switch sides.']::text[], ARRAY['Latissimus_Dorsi-SMR/0.jpg', 'Latissimus_Dorsi-SMR/1.jpg']::text[], 'latissimus dorsi-smr lan gian co xo liberacion del dorsal ancho'),
  (NULL, 'Leg-Over Floor Press', 'Đẩy sàn kettlebell vắt chân', 'Leg-Over Floor Press', 'Press en el suelo con pierna cruzada', 'chest', 'kettlebell', 'compound', 'free_exercise_db', 'Leg-Over_Floor_Press', ARRAY['Lie on the floor with one kettlebell in place on your chest, holding it by the handle. Extend leg on working side over leg on non-working side.Your free arm can be extended out to your side for support.', 'Press the kettlebll into a locked out position.', 'Lower the weight until the elbow touches the ground, keeping the kettlebell above the elbow. Repeat for the desired number of repetitions.']::text[], ARRAY['Leg-Over_Floor_Press/0.jpg', 'Leg-Over_Floor_Press/1.jpg']::text[], 'leg-over floor press day san kettlebell vat chan press en el suelo con pierna cruzada'),
  (NULL, 'Leg-Up Hamstring Stretch', 'Giãn đùi sau nâng chân', 'Leg-Up Hamstring Stretch', 'Estiramiento de isquios con pierna elevada', 'legs', 'other', 'timed', 'free_exercise_db', 'Leg-Up_Hamstring_Stretch', ARRAY['Lie flat on your back, bend one knee, and put that foot flat on the floor to stabilize your spine.', 'Extend the other leg in the air. If you''re tight, you wont be able to straighten it. That''s okay. Extend the knee so that the sole of the lifted foot faces the ceiling (or as close as you can get it).', 'Slowly straighten the legs as much as possible and then pull the leg toward your nose. Switch sides.']::text[], ARRAY['Leg-Up_Hamstring_Stretch/0.jpg', 'Leg-Up_Hamstring_Stretch/1.jpg']::text[], 'leg-up hamstring stretch gian dui sau nang chan estiramiento de isquios con pierna elevada'),
  (NULL, 'Leg Extensions', 'Duỗi đùi', 'Leg Extensions', 'Extensión de piernas', 'legs', 'machine', 'isolation', 'free_exercise_db', 'Leg_Extensions', ARRAY['For this exercise you will need to use a leg extension machine. First choose your weight and sit on the machine with your legs under the pad (feet pointed forward) and the hands holding the side bars. This will be your starting position. Tip: You will need to adjust the pad so that it falls on top of your lower leg (just above your feet). Also, make sure that your legs form a 90-degree angle between the lower and upper leg. If the angle is less than 90-degrees then that means the knee is over the toes which in turn creates undue stress at the knee joint. If the machine is designed that way, either look for another machine or just make sure that when you start executing the exercise you stop going down once you hit the 90-degree angle.', 'Using your quadriceps, extend your legs to the maximum as you exhale. Ensure that the rest of the body remains stationary on the seat. Pause a second on the contracted position.', 'Slowly lower the weight back to the original position as you inhale, ensuring that you do not go past the 90-degree angle limit.', 'Repeat for the recommended amount of times.']::text[], ARRAY['Leg_Extensions/0.jpg', 'Leg_Extensions/1.jpg']::text[], 'leg extensions duoi dui extension de piernas'),
  (NULL, 'Leg Lift', 'Nâng chân', 'Leg Lift', 'Elevación de pierna', 'glutes', 'bodyweight', 'bodyweight', 'free_exercise_db', 'Leg_Lift', ARRAY['While standing up straight with both feet next to each other at around shoulder width, grab a sturdy surface such as the sides of a squat rack or the top of a chair to brace yourself and keep balance.', 'With or without an ankle weight, lift one leg behind you as if performing a leg curl but standing up while keeping the other leg straight. Breathe out as you perform this movement.', 'Slowly bring the raised leg back to the floor as you breathe in.', 'Repeat for the recommended amount of repetitions.', 'Repeat the movement with the opposite leg.']::text[], ARRAY['Leg_Lift/0.jpg', 'Leg_Lift/1.jpg']::text[], 'leg lift nang chan elevacion de pierna'),
  (NULL, 'Leg Pull-In', 'Kéo gối', 'Leg Pull-In', 'Encogimiento de piernas', 'abs', 'bodyweight', 'bodyweight', 'free_exercise_db', 'Leg_Pull-In', ARRAY['Lie on an exercise mat with your legs extended and your hands either palms facing down next to you or under your glutes. Tip: My preference is with the hands next to me. This will be your starting position.', 'Bend your knees and pull your upper thighs into your midsection as you breathe out. Continue the motion until your knees are around chest level. Contract your abs as you execute this movement and hold for a second at the top. Tip: As you perform the motion, the lower legs (calves) should always remain parallel to the floor.', 'Return to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Leg_Pull-In/0.jpg', 'Leg_Pull-In/1.jpg']::text[], 'leg pull-in keo goi encogimiento de piernas'),
  (NULL, 'Leverage Chest Press', 'Đẩy ngực máy đòn bẩy', 'Leverage Chest Press', 'Press de pecho en máquina de palanca', 'chest', 'machine', 'compound', 'free_exercise_db', 'Leverage_Chest_Press', ARRAY['Load an appropriate weight onto the pins and adjust the seat for your height. The handles should be near the bottom or middle of the pectorals at the beginning of the motion.', 'Your chest and head should be up and your shoulder blades retracted. This will be your starting position.', 'Press the handles forward by extending through the elbow.', 'After a brief pause at the top, return the weight just above the start position, keeping tension on the muscles by not returning the weight to the stops until the set is complete.']::text[], ARRAY['Leverage_Chest_Press/0.jpg', 'Leverage_Chest_Press/1.jpg']::text[], 'leverage chest press day nguc may don bay press de pecho en maquina de palanca'),
  (NULL, 'Leverage Deadlift', 'Leverage Deadlift', 'Leverage Deadlift', 'Peso muerto en máquina de palanca', 'legs', 'machine', 'compound', 'free_exercise_db', 'Leverage_Deadlift', ARRAY['Load the pins to an appropriate weight. Position yourself directly between the handles. Grasp the bottom handles with a comfortable grip, and then lower your hips as you take a breath. Look forward with your head and keep your chest up. This will be your starting position.', 'Return the weight to the starting position.']::text[], ARRAY['Leverage_Deadlift/0.jpg', 'Leverage_Deadlift/1.jpg']::text[], 'leverage deadlift deadlift may don bay peso muerto en maquina de palanca'),
  (NULL, 'Leverage Decline Chest Press', 'Đẩy ngực dốc xuống máy đòn bẩy', 'Leverage Decline Chest Press', 'Press declinado en máquina de palanca', 'chest', 'machine', 'compound', 'free_exercise_db', 'Leverage_Decline_Chest_Press', ARRAY['Load an appropriate weight onto the pins and adjust the seat for your height. The handles should be near the bottom of the pectorals at the beginning of the motion. Your chest and head should be up and your shoulder blades retracted. This will be your starting position.', 'Press the handles forward by extending through the elbow.', 'After a brief pause at the top, return the weight just above the start position, keeping tension on the muscles by not returning the weight to the stops until the set is complete.']::text[], ARRAY['Leverage_Decline_Chest_Press/0.jpg', 'Leverage_Decline_Chest_Press/1.jpg']::text[], 'leverage decline chest press day nguc doc xuong may don bay press declinado en maquina de palanca'),
  (NULL, 'Leverage High Row', 'Chèo cao máy đòn bẩy', 'Leverage High Row', 'Remo alto en máquina de palanca', 'back', 'machine', 'compound', 'free_exercise_db', 'Leverage_High_Row', ARRAY['Load an appropriate weight onto the pins and adjust the seat height so that you can just reach the handles above you. Adjust the knee pad to help keep you down. Grasp the handles with a pronated grip. This will be your starting position.', 'Pull the handles towards your torso, retracting your shoulder blades as you flex the elbow.', 'Pause at the bottom of the motion, and then slowly return the handles to the starting position.', 'For multiple repetitions, avoid completely returning the weight to the stops to keep tension on the muscles being worked.']::text[], ARRAY['Leverage_High_Row/0.jpg', 'Leverage_High_Row/1.jpg']::text[], 'leverage high row cheo cao may don bay remo alto en maquina de palanca'),
  (NULL, 'Leverage Incline Chest Press', 'Đẩy ngực dốc lên máy đòn bẩy', 'Leverage Incline Chest Press', 'Press inclinado en máquina de palanca', 'chest', 'machine', 'compound', 'free_exercise_db', 'Leverage_Incline_Chest_Press', ARRAY['Load an appropriate weight onto the pins and adjust the seat for your height. The handles should be near the top of the pectorals at the beginning of the motion. Your chest and head should be up and your shoulder blades retracted. This will be your starting position.', 'Press the handles forward by extending through the elbow.', 'After a brief pause at the top, return the weight just above the start position, keeping tension on the muscles by not returning the weight to the stops until the set is complete.']::text[], ARRAY['Leverage_Incline_Chest_Press/0.jpg', 'Leverage_Incline_Chest_Press/1.jpg']::text[], 'leverage incline chest press day nguc doc len may don bay press inclinado en maquina de palanca'),
  (NULL, 'Leverage Iso Row', 'Chèo máy đòn bẩy từng tay', 'Leverage Iso Row', 'Remo iso en máquina de palanca', 'back', 'machine', 'compound', 'free_exercise_db', 'Leverage_Iso_Row', ARRAY['Load an appropriate weight onto the pins and adjust the seat height so that the handles are at chest level. Grasp the handles with either a neutral or pronated grip. This will be your starting position.', 'Pull the handles towards your torso, retracting your shoulder blades as you flex the elbow.', 'Pause at the bottom of the motion, and then slowly return the handles to the starting position. For multiple repetitions, avoid completely returning the weight to the stops to keep tension on the muscles being worked.']::text[], ARRAY['Leverage_Iso_Row/0.jpg', 'Leverage_Iso_Row/1.jpg']::text[], 'leverage iso row cheo may don bay tung tay remo iso en maquina de palanca'),
  (NULL, 'Leverage Shoulder Press', 'Đẩy vai máy đòn bẩy', 'Leverage Shoulder Press', 'Press de hombros en máquina de palanca', 'shoulders', 'machine', 'compound', 'free_exercise_db', 'Leverage_Shoulder_Press', ARRAY['Load an appropriate weight onto the pins and adjust the seat for your height. The handles should be near the top of the shoulders at the beginning of the motion. Your chest and head should be up and handles held with a pronated grip. This will be your starting position.', 'Press the handles upward by extending through the elbow.', 'After a brief pause at the top, return the weight to just above the start position, keeping tension on the muscles by not returning the weight to the stops until the set is complete.']::text[], ARRAY['Leverage_Shoulder_Press/0.jpg', 'Leverage_Shoulder_Press/1.jpg']::text[], 'leverage shoulder press day vai may don bay press de hombros en maquina de palanca'),
  (NULL, 'Leverage Shrug', 'Leverage Shrug', 'Leverage Shrug', 'Encogimiento en máquina de palanca', 'shoulders', 'machine', 'isolation', 'free_exercise_db', 'Leverage_Shrug', ARRAY['Load the pins to an appropriate weight. Position yourself directly between the handles.', 'Grasp the top handles with a comfortable grip, and then lower your hips as you take a breath. Look forward with your head and keep your chest up.', 'Drive through the floor with your heels, extending your hips and knees as you rise to a standing position. Keep your arms straight throughout the movement, finishing with your shoulders back. This will be your starting position.', 'Raise the weight by shrugging the shoulders towards your ears, moving straight up and down.', 'Pause at the top of the motion, and then return the weight to the starting position.']::text[], ARRAY['Leverage_Shrug/0.jpg', 'Leverage_Shrug/1.jpg']::text[], 'leverage shrug nhun vai may don bay encogimiento en maquina de palanca'),
  (NULL, 'Linear 3-Part Start Technique', 'Kỹ thuật xuất phát 3 bước', 'Linear 3-Part Start Technique', 'Técnica de salida en 3 fases', 'legs', 'other', 'bodyweight', 'free_exercise_db', 'Linear_3-Part_Start_Technique', ARRAY['This drill helps you accelerate as quickly as possible into a sprint from a dead stop. It helps to use a line to start from. Begin with two feet on the line. Place your left foot with the toe next to your right ankle. Place your right foot 4-6 inches behind the left.', 'Place your right hand onto the line, and thing bring your nose close to your left knee.', 'Squat down as you lean foward, your head being lower than your hips and your weight loaded onto the left leg. This will be your starting position.', 'Take your left hand up so that it is parallel to the ground, pointing behind you, and explode out when ready.']::text[], ARRAY['Linear_3-Part_Start_Technique/0.jpg', 'Linear_3-Part_Start_Technique/1.jpg']::text[], 'linear 3-part start technique ky thuat xuat phat 3 buoc tecnica de salida en 3 fases'),
  (NULL, 'Linear Acceleration Wall Drill', 'Tập tăng tốc chống tường', 'Linear Acceleration Wall Drill', 'Ejercicio de aceleración en pared', 'legs', 'other', 'bodyweight', 'free_exercise_db', 'Linear_Acceleration_Wall_Drill', ARRAY['Lean at around 45 degrees against a wall. Your feet should be together, glutes contracted.', 'Begin by lifting your right knee quickly, pausing, and then driving it straight down into the ground.', 'Switch legs, raising the opposite knee, and then attacking the ground straight down.', 'Repeat once more with your right leg, and as soon as the right foot strikes the ground hammer them out rapidly, alternating left and right as fast as you can.']::text[], ARRAY['Linear_Acceleration_Wall_Drill/0.jpg', 'Linear_Acceleration_Wall_Drill/1.jpg']::text[], 'linear acceleration wall drill tap tang toc chong tuong ejercicio de aceleracion en pared'),
  (NULL, 'Linear Depth Jump', 'Nhảy sâu thẳng', 'Linear Depth Jump', 'Salto en profundidad lineal', 'legs', 'other', 'compound', 'free_exercise_db', 'Linear_Depth_Jump', ARRAY['You will need two boxes or benches spaced a few feet away from each other. Begin by standing on one box facing towards the other platform.', 'To initiate the movement, gently drop down to the ground between your platforms, allowing the knees and hips to flex.', 'Reverse the motion by exploding, extending through the hips, knees, and ankles to jump onto the other platform.', 'Land softly, asborbing the impact through the legs.']::text[], ARRAY['Linear_Depth_Jump/0.jpg', 'Linear_Depth_Jump/1.jpg']::text[], 'linear depth jump nhay sau thang salto en profundidad lineal'),
  (NULL, 'Log Lift', 'Nâng khúc gỗ', 'Log Lift', 'Levantamiento de tronco', 'shoulders', 'other', 'compound', 'free_exercise_db', 'Log_Lift', ARRAY['Begin standing with the log in front of you. Grasp the handles, and begin to clean the log. As you are bent over to start the clean, attempt to get the log as high as possible, pulling it into your chest. Extend through the hips and knees to bring it up to complete the clean.', 'Push your head back and look up, creating a shelf on your chest to rest the log. Begin the press by dipping, flexing slightly through the knees and reversing the motion. This push press will generate momentum to start the log moving vertically. Continue by extending through the elbows to press the log above your head. There are no strict rules on form, so use whatever techniques you are most efficient with. As the log is pressed, ensure that you push your head through on each repetition, looking forward.', 'Repeat as many times as possible. Attempt to control the descent of the log as it is returned to the ground.']::text[], ARRAY['Log_Lift/0.jpg', 'Log_Lift/1.jpg']::text[], 'log lift nang khuc go levantamiento de tronco'),
  (NULL, 'London Bridges', 'Quăng dây cầu London', 'London Bridges', 'Puentes de Londres', 'back', 'other', 'compound', 'free_exercise_db', 'London_Bridges', ARRAY['Attach a climbing rope to a high beam or cross member. Below it, ensure that the smith machine bar is locked in place with the safeties and cannot move. Alternatively, a secure box could also be utilized.', 'Stand on the bar, using the rope to balance yourself. This will be your starting position.', 'Keeping your body straight, lean back and lower your body by slowly going hand over hand with the rope. Continue until you are perpendicular to the ground.', 'Keeping your body straight, reverse the motion, going hand over hand back to the starting position.']::text[], ARRAY['London_Bridges/0.jpg', 'London_Bridges/1.jpg']::text[], 'london bridges quang day cau london puentes de londres'),
  (NULL, 'Looking At Ceiling', 'Ngửa cổ nhìn trần', 'Looking At Ceiling', 'Mirar al techo', 'legs', 'other', 'timed', 'free_exercise_db', 'Looking_At_Ceiling', ARRAY['Kneel on the floor, holding your heels with both hands.', 'Lift your buttocks up and forward while bringing your head back to look up at the ceiling, to give an arch in your back.']::text[], ARRAY['Looking_At_Ceiling/0.jpg', 'Looking_At_Ceiling/1.jpg']::text[], 'looking at ceiling ngua co nhin tran mirar al techo'),
  (NULL, 'Low Cable Crossover', 'Low Cable Crossover', 'Low Cable Crossover', 'Cruce de poleas bajo', 'chest', 'cable', 'isolation', 'free_exercise_db', 'Low_Cable_Crossover', ARRAY['To move into the starting position, place the pulleys at the low position, select the resistance to be used and grasp a handle in each hand.', 'Step forward, gaining tension in the pulleys. Your palms should be facing forward, hands below the waist, and your arms straight. This will be your starting position.', 'With a slight bend in your arms, draw your hands upward and toward the midline of your body. Your hands should come together in front of your chest, palms facing up.', 'Return your arms back to the starting position after a brief pause.']::text[], ARRAY['Low_Cable_Crossover/0.jpg', 'Low_Cable_Crossover/1.jpg']::text[], 'low cable crossover ep nguc cap cheo tu thap cruce de poleas bajo'),
  (NULL, 'Low Cable Triceps Extension', 'Duỗi tay sau cáp thấp', 'Low Cable Triceps Extension', 'Extensión de tríceps en polea baja', 'triceps', 'cable', 'isolation', 'free_exercise_db', 'Low_Cable_Triceps_Extension', ARRAY['Select the desired weight and lay down face up on the bench of a seated row machine that has a rope attached to it. Your head should be pointing towards the attachment.', 'Grab the outside of the rope ends with your palms facing each other (neutral grip).', 'Position your elbows so that they are bent at a 90 degree angle and your upper arms are perpendicular (90 degree angle) to your torso. Tip: Keep the elbows in and make sure that the upper arms point to the ceiling while your forearms point towards the pulley above your head. This will be your starting position.', 'As you breathe out, extend your lower arms until they are straight and vertical. The upper arms and elbows remain stationary throughout the movement. Only the forearms should move. Contract the triceps hard for a second.', 'As you breathe in slowly return to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Low_Cable_Triceps_Extension/0.jpg', 'Low_Cable_Triceps_Extension/1.jpg']::text[], 'low cable triceps extension duoi tay sau cap thap extension de triceps en polea baja'),
  (NULL, 'Low Pulley Row To Neck', 'Chèo cáp thấp lên cổ', 'Low Pulley Row To Neck', 'Remo en polea baja al cuello', 'shoulders', 'cable', 'compound', 'free_exercise_db', 'Low_Pulley_Row_To_Neck', ARRAY['Sit on a low pulley row machine with a rope attachment.', 'Grab the ends of the rope using a palms-down grip and sit with your back straight and your knees slightly bent. Tip: Keep your back almost completely vertical and your arms fully extended in front of you. This will be your starting position.', 'While keeping your torso stationary, lift your elbows and start bending them as you pull the rope towards your neck while exhaling. Throughout the movement your upper arms should remain parallel to the floor. Tip: Continue this motion until your hands are almost next to your ears (the forearms will not be parallel to the floor at the end of the movement as they will be angled a bit upwards) and your elbows are out away from your sides.', 'After holding for a second or so at the contracted position, come back slowly to the starting position as you inhale. Tip: Again, during no part of the movement should the torso move.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Low_Pulley_Row_To_Neck/0.jpg', 'Low_Pulley_Row_To_Neck/1.jpg']::text[], 'low pulley row to neck cheo cap thap len co remo en polea baja al cuello'),
  (NULL, 'Lower Back-SMR', 'Lăn giãn lưng dưới', 'Lower Back-SMR', 'Liberación lumbar con rodillo', 'back', 'foam roll', 'timed', 'free_exercise_db', 'Lower_Back-SMR', ARRAY['In a seated position, place a foam roll under your lower back. Cross your arms in front of you and protract your shoulders. This will be your starting position.', 'Raise your hips off of the floor and lean back, keeping your weight on your lower back. Now shift your weight slightly to one side, keeping your weight off of the spine and on the muscles to the side of it. Roll over your lower back, holding points of tension for 10-30 seconds. Repeat on the other side.']::text[], ARRAY['Lower_Back-SMR/0.jpg', 'Lower_Back-SMR/1.jpg']::text[], 'lower back-smr lan gian lung duoi liberacion lumbar con rodillo'),
  (NULL, 'Lower Back Curl', 'Lower Back Curl', 'Lower Back Curl', 'Curl lumbar', 'abs', 'bodyweight', 'timed', 'free_exercise_db', 'Lower_Back_Curl', ARRAY['Lie on your stomach with your arms out to your sides. This will be your starting position.', 'Using your lower back muscles, extend your spine lifting your chest off of the ground. Do not use your arms to push yourself up. Keep your head up during the movement. Repeat for 10-20 repetitions.']::text[], ARRAY['Lower_Back_Curl/0.jpg', 'Lower_Back_Curl/1.jpg']::text[], 'lower back curl cuon lung duoi curl lumbar'),
  (NULL, 'Lunge Pass Through', 'Lunge Pass Through', 'Lunge Pass Through', 'Zancada con pase de pesa', 'legs', 'kettlebell', 'compound', 'free_exercise_db', 'Lunge_Pass_Through', ARRAY['Stand with your torso upright holding a kettlebell in your right hand. This will be your starting position.', 'Step forward with your left foot and lower your upper body down by flexing the hip and the knee, keeping the torso upright. Lower your back knee until it nearly touches the ground.', 'As you lunge, pass the kettlebell under your front leg to your opposite hand.', 'Pressing through the heel of your foot, return to the starting position.', 'Repeat the movement for the recommended amount of repetitions, alternating legs.']::text[], ARRAY['Lunge_Pass_Through/0.jpg', 'Lunge_Pass_Through/1.jpg']::text[], 'lunge pass through chung chan chuyen ta zancada con pase de pesa'),
  (NULL, 'Lunge Sprint', 'Lunge Sprint', 'Lunge Sprint', 'Sprint con zancada', 'legs', 'machine', 'compound', 'free_exercise_db', 'Lunge_Sprint', ARRAY['Adjust a bar in a Smith machine to an appropriate height. Position yourself under the bar, racking it across the back of your shoulders. Unrack the bar, and then split your feet, moving one foot forward and one foot back. This will be your starting position.', 'Lower your back knee nearly to the ground, flexing the knees and lowering your hips as you do so.', 'At the bottom of the descent, immediately reverse direction. Explosively drive through the heel of your front foot with light pressure from your back foot. Jump up and reverse the position of your legs.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Lunge_Sprint/0.jpg', 'Lunge_Sprint/1.jpg']::text[], 'lunge sprint chay nuoc rut chung chan sprint con zancada'),
  (NULL, 'Lying Bent Leg Groin', 'Giãn háng nằm gối cong', 'Lying Bent Leg Groin', 'Estiramiento de ingle tumbado con piernas flexionadas', 'legs', 'other', 'timed', 'free_exercise_db', 'Lying_Bent_Leg_Groin', ARRAY['Lie on your back with your knees bent and the soles of the feet pressed together. Have your partner hold your knees. This will be your starting position.', 'Attempt to squeeze your knees together, while your partner prevents any movement from occurring.', 'After 10-20 seconds, relax your muscles as your partner gently pushes your knees towards the floor. Be sure to inform your helper when the stretch is adequate to prevent injury or overstretching.']::text[], ARRAY['Lying_Bent_Leg_Groin/0.jpg', 'Lying_Bent_Leg_Groin/1.jpg']::text[], 'lying bent leg groin gian hang nam goi cong estiramiento de ingle tumbado con piernas flexionadas'),
  (NULL, 'Lying Cable Curl', 'Lying Cable Curl', 'Lying Cable Curl', 'Curl tumbado en polea', 'biceps', 'cable', 'isolation', 'free_exercise_db', 'Lying_Cable_Curl', ARRAY['Grab a straight bar or E-Z bar attachment that is attached to the low pulley with both hands, using an underhand (palms facing up) shoulder-width grip.', 'Lie flat on your back on top of an exercise mat in front of the weight stack with your feet flat against the frame of the pulley machine and your legs straight.', 'With your arms extended and your elbows close to your body slightly bend your arms. This will be your starting position.', 'While keeping your upper arms stationary and the elbows close to your body, curl the bar up slowly toward your chest as you breathe out and you squeeze the biceps.', 'After a second squeeze at the top of the movement, slowly return to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Lying_Cable_Curl/0.jpg', 'Lying_Cable_Curl/1.jpg']::text[], 'lying cable curl cuon tay truoc cap nam curl tumbado en polea'),
  (NULL, 'Lying Cambered Barbell Row', 'Chèo tạ đòn cong nằm sấp', 'Lying Cambered Barbell Row', 'Remo tumbado con barra curvada', 'back', 'barbell', 'isolation', 'free_exercise_db', 'Lying_Cambered_Barbell_Row', ARRAY['Place a cambered bar underneath an exercise bench.', 'Lie face down on the exercise bench and grab the bar using a palms down (pronated grip) that is wider than shoulder width. This will be your starting position.', 'As you exhale row the bar up as you keep the elbows close to your body to either your chest, in order to target the upper mid back, or to your stomach if targeting the lats is your goal.', 'After a second hold at the top, lower back down to the starting position slowly as you inhale.']::text[], ARRAY['Lying_Cambered_Barbell_Row/0.jpg', 'Lying_Cambered_Barbell_Row/1.jpg']::text[], 'lying cambered barbell row cheo ta don cong nam sap remo tumbado con barra curvada'),
  (NULL, 'Lying Close-Grip Bar Curl On High Pulley', 'Lying Close-Grip Bar Curl On High Pulley', 'Lying Close-Grip Bar Curl On High Pulley', 'Curl tumbado agarre cerrado en polea alta', 'biceps', 'cable', 'isolation', 'free_exercise_db', 'Lying_Close-Grip_Bar_Curl_On_High_Pulley', ARRAY['Place a flat bench in front of a high pulley or lat pulldown machine.', 'Hold the straight bar attachment using an underhand grip (palms up) that is about shoulder width.', 'Lie on your back with your head over the end of the bench.', 'Now extend your arms straight above your shoulders. Your torso and your arms should make a 90-degree angle and the elbows should be in. This will be your starting position.', 'As you breathe out, curl the bar down in a semicircular motion until it touches your chin. Squeeze the biceps for a second at the top contracted position. Tip: As you execute this motion only the forearms should move. At no time should the upper arms be moving at all. They are to remain perpendicular throughout the movement.', 'Return to starting position slowly.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Lying_Close-Grip_Bar_Curl_On_High_Pulley/0.jpg', 'Lying_Close-Grip_Bar_Curl_On_High_Pulley/1.jpg']::text[], 'lying close-grip bar curl on high pulley cuon thanh nam hep nam voi cap cao curl tumbado agarre cerrado en polea alta'),
  (NULL, 'Lying Close-Grip Barbell Triceps Extension Behind The Head', 'Duỗi tay sau tạ đòn nắm hẹp nằm qua đầu', 'Lying Close-Grip Barbell Triceps Extension Behind The Head', 'Extensión de tríceps tumbado con barra tras la cabeza', 'triceps', 'barbell', 'isolation', 'free_exercise_db', 'Lying_Close-Grip_Barbell_Triceps_Extension_Behind_The_Head', ARRAY['While holding a barbell or EZ Curl bar with a pronated grip (palms facing forward), lie on your back on a flat bench with your head close to the end of the bench. Tip: If you are holding a barbell grab it using a shoulder-width grip and if you are using an E-Z Bar grab it on the inner handles.', 'Extend your arms in front of you and slowly bring the bar back in a semi circular motion (while keeping the arms extended) to a position over your head. At the end of this step your arms should be overhead and parallel to the floor. This will be your starting position. Tip: Keep your elbows in at all times.', 'As you inhale, lower the bar by bending at the elbows and while keeping the upper arm stationary. Keep lowering the bar until your forearms are perpendicular to the floor.', 'As you exhale bring the bar back up to the starting position by pushing the bar up in a semi-circular motion until the lower arms are also parallel to the floor. Contract the triceps hard at the top of the movement for a second. Tip: Again, only the forearms should move. The upper arms should remain stationary at all times.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Lying_Close-Grip_Barbell_Triceps_Extension_Behind_The_Head/0.jpg', 'Lying_Close-Grip_Barbell_Triceps_Extension_Behind_The_Head/1.jpg']::text[], 'lying close-grip barbell triceps extension behind the head duoi tay sau ta don nam hep nam qua dau extension de triceps tumbado con barra tras la cabeza'),
  (NULL, 'Lying Close-Grip Barbell Triceps Press To Chin', 'Đẩy tay sau tạ đòn nắm hẹp nằm về cằm', 'Lying Close-Grip Barbell Triceps Press To Chin', 'Press de tríceps tumbado al mentón', 'triceps', 'ez bar', 'isolation', 'free_exercise_db', 'Lying_Close-Grip_Barbell_Triceps_Press_To_Chin', ARRAY['While holding a barbell or EZ Curl bar with a pronated grip (palms facing forward), lie on your back on a flat bench with your head off the end of the bench. Tip: If you are holding a barbell grab it using a shoulder-width grip and if you are using an E-Z Bar grab it on the inner handles.', 'Extend your arms in front of you as you hold the barbell over your chest. The arms should be perpendicular to your torso (90-degree angle). This will be your starting position.', 'As you inhale, lower the bar in a semi-circular motion by bending at the elbows and while keeping the upper arm stationary and elbows in. Keep lowering the bar until it lightly touches your chin.', 'As you exhale bring the bar back up to the starting position by pushing the bar up in a semi-circular motion. Contract the triceps hard at the top of the movement for a second. Tip: Again, only the forearms should move. The upper arms should remain stationary at all times.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Lying_Close-Grip_Barbell_Triceps_Press_To_Chin/0.jpg', 'Lying_Close-Grip_Barbell_Triceps_Press_To_Chin/1.jpg']::text[], 'lying close-grip barbell triceps press to chin day tay sau ta don nam hep nam ve cam press de triceps tumbado al menton'),
  (NULL, 'Lying Crossover', 'Lying Crossover', 'Lying Crossover', 'Cruce tumbado', 'legs', 'bodyweight', 'timed', 'free_exercise_db', 'Lying_Crossover', ARRAY['Lie on your back with your legs extended.', 'Cross one leg over your body with the knee bent, attempting to touch the knee to the ground. Your partner should kneel beside you, holding your shoulder down with one hand and controlling the crossed leg with the other. this will be your starting position.', 'Attempt to raise the bent knee off of the ground as your partner prevents any actual movement.', 'After 10-20 seconds, relax the leg as your partner gently presses the knee towards the floor. Repeat with the other side.']::text[], ARRAY['Lying_Crossover/0.jpg', 'Lying_Crossover/1.jpg']::text[], 'lying crossover vat cheo chan nam cruce tumbado'),
  (NULL, 'Lying Dumbbell Tricep Extension', 'Duỗi tay sau tạ đơn nằm', 'Lying Dumbbell Tricep Extension', 'Extensión de tríceps tumbado con mancuernas', 'triceps', 'dumbbell', 'isolation', 'free_exercise_db', 'Lying_Dumbbell_Tricep_Extension', ARRAY['Lie on a flat bench while holding two dumbbells directly in front of you. Your arms should be fully extended at a 90-degree angle from your torso and the floor. The palms should be facing in and the elbows should be tucked in. This is the starting position.', 'As you breathe in and you keep the upper arms stationary with the elbows in, slowly lower the weight until the dumbbells are near your ears.', 'At that point, while keeping the elbows in and the upper arms stationary, use the triceps to bring the weight back up to the starting position as you breathe out.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Lying_Dumbbell_Tricep_Extension/0.jpg', 'Lying_Dumbbell_Tricep_Extension/1.jpg']::text[], 'lying dumbbell tricep extension duoi tay sau ta don nam extension de triceps tumbado con mancuernas'),
  (NULL, 'Lying Face Down Plate Neck Resistance', 'Kháng lực cổ đĩa tạ nằm sấp', 'Lying Face Down Plate Neck Resistance', 'Resistencia de cuello boca abajo con disco', 'shoulders', 'other', 'isolation', 'free_exercise_db', 'Lying_Face_Down_Plate_Neck_Resistance', ARRAY['Lie face down with your whole body straight on a flat bench while holding a weight plate behind your head. Tip: You will need to position yourself so that your shoulders are slightly above the end of a flat bench in order for the upper chest, neck and face to be off the bench. This will be your starting position.', 'While keeping the plate secure on the back of your head slowly lower your head (as in saying "yes") as you breathe in.', 'Raise your head back up to the starting position in a semi-circular motion as you breathe out. Hold the contraction for a second.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Lying_Face_Down_Plate_Neck_Resistance/0.jpg', 'Lying_Face_Down_Plate_Neck_Resistance/1.jpg']::text[], 'lying face down plate neck resistance khang luc co dia ta nam sap resistencia de cuello boca abajo con disco'),
  (NULL, 'Lying Face Up Plate Neck Resistance', 'Kháng lực cổ đĩa tạ nằm ngửa', 'Lying Face Up Plate Neck Resistance', 'Resistencia de cuello boca arriba con disco', 'shoulders', 'other', 'isolation', 'free_exercise_db', 'Lying_Face_Up_Plate_Neck_Resistance', ARRAY['Lie face up with your whole body straight on a flat bench while holding a weight plate on top of your forehead. Tip: You will need to position yourself so that your shoulders are slightly above the end of a flat bench in order for the traps, neck and head to be off the bench. This will be your starting position.', 'While keeping the plate secure on your forehead slowly lower your head back in a semi-circular motion as you breathe in.', 'Raise your head back up to the starting position in a semi-circular motion as you breathe out. Hold the contraction for a second.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Lying_Face_Up_Plate_Neck_Resistance/0.jpg', 'Lying_Face_Up_Plate_Neck_Resistance/1.jpg']::text[], 'lying face up plate neck resistance khang luc co dia ta nam ngua resistencia de cuello boca arriba con disco'),
  (NULL, 'Lying Glute', 'Giãn mông nằm', 'Lying Glute', 'Estiramiento de glúteo tumbado', 'glutes', 'bodyweight', 'timed', 'free_exercise_db', 'Lying_Glute', ARRAY['Lie on your back with your partner kneeling beside you.', 'Flex the hip of one leg, raising it off of the floor. Rotate the leg so the foot is over the opposite hip, the lower leg perpendicular to your body. Your partner should hold the knee and ankle in place. This will be your starting position.', 'Attempt to push your leg towards your partner, who should be preventing any actual movement of the leg.', 'After 10-20 seconds, completely relax as your partner gently pushes the ankle and knee towards your chest. Be sure to inform your helper when the stretch is adequate to prevent injury or overstretching.']::text[], ARRAY['Lying_Glute/0.jpg', 'Lying_Glute/1.jpg']::text[], 'lying glute gian mong nam estiramiento de gluteo tumbado'),
  (NULL, 'Lying Hamstring', 'Giãn đùi sau nằm', 'Lying Hamstring', 'Estiramiento de isquios tumbado', 'legs', 'other', 'timed', 'free_exercise_db', 'Lying_Hamstring', ARRAY['Lie on your back with your legs extended. Your partner should be kneeling beside you. Raise one leg up towards the ceiling and have your partner hold the ankle. Your partner can use their shoulder to brace your leg if necessary. This will be your starting position.', 'With your partner holding your leg in place, attempt to flex the knee, contracting the hamstrings for 10-20 seconds.', 'Then relax your leg, allowing your partner to gently push the leg towards your head. Be sure to inform your helper when the stretch is adequate to prevent injury or overstretching. Switch sides once complete.']::text[], ARRAY['Lying_Hamstring/0.jpg', 'Lying_Hamstring/1.jpg']::text[], 'lying hamstring gian dui sau nam estiramiento de isquios tumbado'),
  (NULL, 'Lying High Bench Barbell Curl', 'Lying High Bench Barbell Curl', 'Lying High Bench Barbell Curl', 'Curl tumbado en banco alto con barra', 'biceps', 'barbell', 'isolation', 'free_exercise_db', 'Lying_High_Bench_Barbell_Curl', ARRAY['Lie face forward on a tall flat bench while holding a barbell with a supinated grip (palms facing up). Tip: If you are holding a barbell grab it using a shoulder-width grip and if you are using an E-Z Bar grab it on the inner handles. Your upper body should be positioned in a way that the upper chest is over the end of the bench and the barbell is hanging in front of you with the arms extended and perpendicular to the floor. This will be your starting position.', 'While keeping the elbows in and the upper arms stationary, curl the weight up in a semi-circular motion as you contract the biceps and exhale. Hold at the top of the movement for a second.', 'As you inhale, slowly go back to the starting position. Tip: Maintain full control of the weight at all times and avoid any swinging. Remember, only the forearms should move throughout the movement.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Lying_High_Bench_Barbell_Curl/0.jpg', 'Lying_High_Bench_Barbell_Curl/1.jpg']::text[], 'lying high bench barbell curl cuon ta don nam ghe cao curl tumbado en banco alto con barra'),
  (NULL, 'Lying Leg Curls', 'Lying Leg Curls', 'Lying Leg Curls', 'Curl femoral tumbado', 'legs', 'machine', 'isolation', 'free_exercise_db', 'Lying_Leg_Curls', ARRAY['Adjust the machine lever to fit your height and lie face down on the leg curl machine with the pad of the lever on the back of your legs (just a few inches under the calves). Tip: Preferably use a leg curl machine that is angled as opposed to flat since an angled position is more favorable for hamstrings recruitment.', 'Keeping the torso flat on the bench, ensure your legs are fully stretched and grab the side handles of the machine. Position your toes straight (or you can also use any of the other two stances described on the foot positioning section). This will be your starting position.', 'As you exhale, curl your legs up as far as possible without lifting the upper legs from the pad. Once you hit the fully contracted position, hold it for a second.', 'As you inhale, bring the legs back to the initial position. Repeat for the recommended amount of repetitions.']::text[], ARRAY['Lying_Leg_Curls/0.jpg', 'Lying_Leg_Curls/1.jpg']::text[], 'lying leg curls cuon dui sau nam curl femoral tumbado'),
  (NULL, 'Lying Machine Squat', 'Lying Machine Squat', 'Lying Machine Squat', 'Sentadilla tumbado en máquina', 'legs', 'machine', 'compound', 'free_exercise_db', 'Lying_Machine_Squat', ARRAY['Adjust the leg machine to a height that will allow you to get inside it with your knees bent and the thighs slightly below parallel.', 'Once you select the weight, position yourself inside the machine face up with the knees bent and thighs slightly below parallel to the platform. Make sure that the knees do not go past the toes. The angle created between the hamstrings and the calves should be one that is slightly less than 90 degrees (since your starting position requires you to start slightly below parallel). Your back and your head should be resting on the machine while your shoulders are pressed under the shoulder pads.', 'Place your hands by the handles and position your feet slightly pointing out at a shoulder width position. This will be your starting position.', 'While pressing with the balls of the feet as you breathe out, make your whole body erect as you squeeze the quads. Hold the contracted position for a second. Tip: Since you are starting below parallel, you can opt to use your hands to help you up by pressing on your thighs only on the first repetition.', 'Slowly squat down as you inhale but instead of going all the way down to the starting position, just stop once your thighs are parallel to the platform. The angle between your hamstrings and calves should be a 90-degree angle.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Lying_Machine_Squat/0.jpg', 'Lying_Machine_Squat/1.jpg']::text[], 'lying machine squat squat may nam sentadilla tumbado en maquina'),
  (NULL, 'Lying One-Arm Lateral Raise', 'Nâng tạ ngang một tay nằm', 'Lying One-Arm Lateral Raise', 'Elevación lateral a una mano tumbado', 'shoulders', 'dumbbell', 'isolation', 'free_exercise_db', 'Lying_One-Arm_Lateral_Raise', ARRAY['While holding a dumbbell in one hand, lay with your chest down on a flat bench. The other hand can be used to hold to the leg of the bench for stability.', 'Position the palm of the hand that is holding the dumbbell in a neutral manner (palms facing your torso) as you keep the arm extended with the elbow slightly bent. This will be your starting position.', 'Now raise the arm with the dumbbell to the side until your elbow is at shoulder height and your arm is roughly parallel to the floor as you exhale. Tip: Maintain your arm perpendicular to the torso while keeping your arm extended throughout the movement. Also, keep the contraction at the top for a second.', 'Slowly lower the dumbbell to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Lying_One-Arm_Lateral_Raise/0.jpg', 'Lying_One-Arm_Lateral_Raise/1.jpg']::text[], 'lying one-arm lateral raise nang ta ngang mot tay nam elevacion lateral a una mano tumbado'),
  (NULL, 'Lying Prone Quadriceps', 'Giãn đùi trước nằm sấp', 'Lying Prone Quadriceps', 'Estiramiento de cuádriceps boca abajo', 'legs', 'bodyweight', 'timed', 'free_exercise_db', 'Lying_Prone_Quadriceps', ARRAY['Lay face down on the floor with your partner kneeling beside you. Flex one knee and raise that leg off the ground, attempting to touch your glutes with your foot. Your partner should hold the knee and ankle. This will be your starting position.', 'Attempt to extend your knee while your partner prevents any actual movement.', 'After 10-20 seconds, relax your muscles as your partner gently pushes the foot towards your glutes, further stretching the quadriceps and hip flexors.', 'After 10-20 seconds, switch sides.']::text[], ARRAY['Lying_Prone_Quadriceps/0.jpg', 'Lying_Prone_Quadriceps/1.jpg']::text[], 'lying prone quadriceps gian dui truoc nam sap estiramiento de cuadriceps boca abajo'),
  (NULL, 'Lying Rear Delt Raise', 'Nâng vai sau nằm', 'Lying Rear Delt Raise', 'Elevación posterior tumbado', 'shoulders', 'dumbbell', 'isolation', 'free_exercise_db', 'Lying_Rear_Delt_Raise', ARRAY['While holding a dumbbell in each hand, lay with your chest down on a flat bench.', 'Position the palms of the hands in a neutral manner (palms facing your torso) as you keep the arms extended with the elbows slightly bent. This will be your starting position.', 'Now raise the arms to the side until your elbows are at shoulder height and your arms are roughly parallel to the floor as you exhale. Tip: Maintain your arms perpendicular to the torso while keeping them extended throughout the movement. Also, keep the contraction at the top for a second.', 'Slowly lower the dumbbells to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions and then switch to the other arm.']::text[], ARRAY['Lying_Rear_Delt_Raise/0.jpg', 'Lying_Rear_Delt_Raise/1.jpg']::text[], 'lying rear delt raise nang vai sau nam elevacion posterior tumbado'),
  (NULL, 'Lying Supine Dumbbell Curl', 'Lying Supine Dumbbell Curl', 'Lying Supine Dumbbell Curl', 'Curl tumbado boca arriba con mancuernas', 'biceps', 'dumbbell', 'isolation', 'free_exercise_db', 'Lying_Supine_Dumbbell_Curl', ARRAY['Lie down on a flat bench face up while holding a dumbbell in each arm on top of your thighs.', 'Bring the dumbbells to the sides with the arms extended and the palms of the hands facing your thighs (neutral grip).', 'While keeping the arms close to your torso and elbows in, slowly lower your arms (as you keep them extended with a slight bend at the elbows) as far down towards the floor as you can go. Once you cannot go down any further, lock your upper arms in that position and that will be your starting position.', 'As you breathe out, slowly begin to curl the weights up as you simultaneously rotate your wrists so that the palms of the hands face up. Continue curling the weight until your biceps are fully contracted and squeeze hard at the top position for a second. Tip: Only the forearms should move. Upper arms should remain stationary and elbows should stay in throughout the movement.', 'Return back to the starting position very slowly.']::text[], ARRAY['Lying_Supine_Dumbbell_Curl/0.jpg', 'Lying_Supine_Dumbbell_Curl/1.jpg']::text[], 'lying supine dumbbell curl cuon ta don nam ngua curl tumbado boca arriba con mancuernas'),
  (NULL, 'Lying T-Bar Row', 'Lying T-Bar Row', 'Lying T-Bar Row', 'Remo en T tumbado', 'back', 'machine', 'compound', 'free_exercise_db', 'Lying_T-Bar_Row', ARRAY['Load up the T-bar Row Machine with the desired weight and adjust the leg height so that your upper chest is at the top of the pad. Tip: In some machines all you can do is stand on the appropriate step that allows you to be at a height that has the upper chest at the top of the pad.', 'Lay face down on the pad and grab the handles. You can either use a palms down, palms up, or palms in position depending on what part of your back you want to emphasize.', 'Lift the bar off the rack and extend your arms in front of you. This will be your starting position.', 'As you exhale slowly pull the weight up and squeeze your back at the top of the movement. Tip: Keep the upper arms as close to the torso as possible throughout the movement in order to better engage the back muscles. Also, do not lift your body off of the pad at any time and refrain from using the biceps to lift the weight.', 'After a second contraction at the top of the movement, as you inhale, slowly go back down to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Lying_T-Bar_Row/0.jpg', 'Lying_T-Bar_Row/1.jpg']::text[], 'lying t-bar row cheo t-bar nam remo en t tumbado'),
  (NULL, 'Lying Triceps Press', 'Đẩy tay sau nằm', 'Lying Triceps Press', 'Press de tríceps tumbado', 'triceps', 'ez bar', 'isolation', 'free_exercise_db', 'Lying_Triceps_Press', ARRAY['Lie on a flat bench with either an e-z bar (my preference) or a straight bar placed on the floor behind your head and your feet on the floor.', 'Grab the bar behind you, using a medium overhand (pronated) grip, and raise the bar in front of you at arms length. Tip: The arms should be perpendicular to the torso and the floor. The elbows should be tucked in. This is the starting position.', 'As you breathe in, slowly lower the weight until the bar lightly touches your forehead while keeping the upper arms and elbows stationary.', 'At that point, use the triceps to bring the weight back up to the starting position as you breathe out.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Lying_Triceps_Press/0.jpg', 'Lying_Triceps_Press/1.jpg']::text[], 'lying triceps press day tay sau nam press de triceps tumbado'),
  (NULL, 'Machine Bench Press', 'Machine Bench Press', 'Machine Bench Press', 'Press de banca en máquina', 'chest', 'machine', 'compound', 'free_exercise_db', 'Machine_Bench_Press', ARRAY['Sit down on the Chest Press Machine and select the weight.', 'Step on the lever provided by the machine since it will help you to bring the handles forward so that you can grab the handles and fully extend the arms.', 'Grab the handles with a palms-down grip and lift your elbows so that your upper arms are parallel to the floor to the sides of your torso. Tip: Your forearms will be pointing forward since you are grabbing the handles. Once you bring the handles forward and extend the arms you will be at the starting position.', 'Now bring the handles back towards you as you breathe in.', 'Push the handles away from you as you flex your pecs and you breathe out. Hold the contraction for a second before going back to the starting position.', 'Repeat for the recommended amount of reps.', 'When finished step on the lever again and slowly get the handles back to their original place.']::text[], ARRAY['Machine_Bench_Press/0.jpg', 'Machine_Bench_Press/1.jpg']::text[], 'machine bench press day nguc may press de banca en maquina'),
  (NULL, 'Machine Bicep Curl', 'Machine Bicep Curl', 'Machine Bicep Curl', 'Curl de bíceps en máquina', 'biceps', 'machine', 'isolation', 'free_exercise_db', 'Machine_Bicep_Curl', ARRAY['Adjust the seat to the appropriate height and make your weight selection. Place your upper arms against the pads and grasp the handles. This will be your starting position.', 'Perform the movement by flexing the elbow, pulling your lower arm towards your upper arm.', 'Pause at the top of the movement, and then slowly return the weight to the starting position.', 'Avoid returning the weight all the way to the stops until the set is complete to keep tension on the muscles being worked.']::text[], ARRAY['Machine_Bicep_Curl/0.jpg', 'Machine_Bicep_Curl/1.jpg']::text[], 'machine bicep curl cuon tay truoc may curl de biceps en maquina'),
  (NULL, 'Machine Preacher Curls', 'Machine Preacher Curls', 'Machine Preacher Curls', 'Curl predicador en máquina', 'biceps', 'machine', 'isolation', 'free_exercise_db', 'Machine_Preacher_Curls', ARRAY['Sit down on the Preacher Curl Machine and select the weight.', 'Place the back of your upper arms (your triceps) on the preacher pad provided and grab the handles using an underhand grip (palms facing up). Tip: Make sure that when you place the arms on the pad you keep the elbows in. This will be your starting position.', 'Now lift the handles as you exhale and you contract the biceps. At the top of the position make sure that you hold the contraction for a second. Tip: Only the forearms should move. The upper arms should remain stationary and on the pad at all times.', 'Lower the handles slowly back to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Machine_Preacher_Curls/0.jpg', 'Machine_Preacher_Curls/1.jpg']::text[], 'machine preacher curls cuon tay truoc may ghe doc curl predicador en maquina'),
  (NULL, 'Machine Shoulder (Military) Press', 'Đẩy vai máy', 'Machine Shoulder (Military) Press', 'Press militar en máquina', 'shoulders', 'machine', 'compound', 'free_exercise_db', 'Machine_Shoulder_Military_Press', ARRAY['Sit down on the Shoulder Press Machine and select the weight.', 'Grab the handles to your sides as you keep the elbows bent and in line with your torso. This will be your starting position.', 'Now lift the handles as you exhale and you extend the arms fully. At the top of the position make sure that you hold the contraction for a second.', 'Lower the handles slowly back to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Machine_Shoulder_Military_Press/0.jpg', 'Machine_Shoulder_Military_Press/1.jpg']::text[], 'machine shoulder (military) press day vai may press militar en maquina'),
  (NULL, 'Machine Triceps Extension', 'Duỗi tay sau máy', 'Machine Triceps Extension', 'Extensión de tríceps en máquina', 'triceps', 'machine', 'isolation', 'free_exercise_db', 'Machine_Triceps_Extension', ARRAY['Adjust the seat to the appropriate height and make your weight selection. Place your upper arms against the pads and grasp the handles. This will be your starting position.', 'Perform the movement by extending the elbow, pulling your lower arm away from your upper arm.', 'Pause at the completion of the movement, and then slowly return the weight to the starting position.', 'Avoid returning the weight all the way to the stops until the set is complete to keep tension on the muscles being worked.']::text[], ARRAY['Machine_Triceps_Extension/0.jpg', 'Machine_Triceps_Extension/1.jpg']::text[], 'machine triceps extension duoi tay sau may extension de triceps en maquina'),
  (NULL, 'Medicine Ball Chest Pass', 'Chuyền bóng tạ trước ngực', 'Medicine Ball Chest Pass', 'Pase de pecho con balón medicinal', 'chest', 'medicine ball', 'compound', 'free_exercise_db', 'Medicine_Ball_Chest_Pass', ARRAY['You will need a partner for this exercise. Lacking one, this movement can be performed against a wall.', 'Begin facing your partner holding the medicine ball at your torso with both hands.', 'Pull the ball to your chest, and reverse the motion by extending through the elbows. For sports applications, you can take a step as you throw.', 'Your partner should catch the ball, and throw it back to you.', 'Receive the throw with both hands at chest height.']::text[], ARRAY['Medicine_Ball_Chest_Pass/0.jpg', 'Medicine_Ball_Chest_Pass/1.jpg']::text[], 'medicine ball chest pass chuyen bong ta truoc nguc pase de pecho con balon medicinal'),
  (NULL, 'Medicine Ball Full Twist', 'Xoay người hết vòng với bóng tạ', 'Medicine Ball Full Twist', 'Giro completo con balón medicinal', 'abs', 'medicine ball', 'compound', 'free_exercise_db', 'Medicine_Ball_Full_Twist', ARRAY['For this exercise you will need a medicine ball and a partner. Stand back to back with your partner, spaced 2-3 feet apart. This will be your starting position.', 'Hold the ball in front of the trunk. Open the hips and turn the shoulders at the same time as your partner.', 'For full rotation, you and your partner should twist in the same direction, i.e. counter-clockwise.', 'Pass the ball to your partner, and both of you can now twist in the opposite direction to repeat the procedure.']::text[], ARRAY['Medicine_Ball_Full_Twist/0.jpg', 'Medicine_Ball_Full_Twist/1.jpg']::text[], 'medicine ball full twist xoay nguoi het vong voi bong ta giro completo con balon medicinal'),
  (NULL, 'Medicine Ball Scoop Throw', 'Ném hất bóng tạ', 'Medicine Ball Scoop Throw', 'Lanzamiento de cuchara con balón medicinal', 'shoulders', 'medicine ball', 'compound', 'free_exercise_db', 'Medicine_Ball_Scoop_Throw', ARRAY['Assume a semisquat stance with a medicine ball in your hands. Your arms should hang so the ball is near your feet.', 'Begin by thrusting the hips forward as you extend through the legs, jumping up.', 'As you do, swing your arms up and over your head, keeping them extended, releasing the ball at the peak of your movement. The goal is to throw the ball the greatest distance behind you.']::text[], ARRAY['Medicine_Ball_Scoop_Throw/0.jpg', 'Medicine_Ball_Scoop_Throw/1.jpg']::text[], 'medicine ball scoop throw nem hat bong ta lanzamiento de cuchara con balon medicinal'),
  (NULL, 'Middle Back Shrug', 'Middle Back Shrug', 'Middle Back Shrug', 'Encogimiento de espalda media', 'back', 'dumbbell', 'isolation', 'free_exercise_db', 'Middle_Back_Shrug', ARRAY['Lie facedown on an incline bench while holding a dumbbell in each hand. Your arms should be fully extended hanging down and pointing towards the floor. The palms of your hands should be facing each other. This will be your starting position.', 'As you exhale, squeeze your shoulder blades together and hold the contraction for a full second. Tip: This movement is just like the reverse action of a hug, or trying to perform rear laterals as if you had no arms.', 'As you inhale go back to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Middle_Back_Shrug/0.jpg', 'Middle_Back_Shrug/1.jpg']::text[], 'middle back shrug nhun lung giua encogimiento de espalda media'),
  (NULL, 'Middle Back Stretch', 'Giãn lưng giữa', 'Middle Back Stretch', 'Estiramiento de espalda media', 'back', 'other', 'timed', 'free_exercise_db', 'Middle_Back_Stretch', ARRAY['Stand so your feet are shoulder width apart and your hands are on your hips.', 'Twist at your waist until you feel a stretch. Hold for 10 to 15 seconds, then twist to the other side.']::text[], ARRAY['Middle_Back_Stretch/0.jpg', 'Middle_Back_Stretch/1.jpg']::text[], 'middle back stretch gian lung giua estiramiento de espalda media'),
  (NULL, 'Mixed Grip Chin', 'Hít xà nắm hỗn hợp', 'Mixed Grip Chin', 'Dominadas agarre mixto', 'back', 'other', 'compound', 'free_exercise_db', 'Mixed_Grip_Chin', ARRAY['Using a spacing that is just about 1 inch wider than shoulder width, grab a pull-up bar with the palms of one hand facing forward and the palms of the other hand facing towards you. This will be your starting position.', 'Now start to pull yourself up as you exhale. Tip: With the arm that has the palms facing up concentrate on using the back muscles in order to perform the movement. The elbow of that arm should remain close to the torso. With the other arm that has the palms facing forward, the elbows will be away but in line with the torso. You will concentrate on using the lats to pull your body up.', 'After a second contraction at the top, start to slowly come down as you inhale.', 'Repeat for the recommended amount of repetitions.', 'On the following set, switch grips; so if you had the right hand with the palms facing you and the left one with the palms facing forward, on the next set you will have the palms facing forward for the right hand and facing you for the left.']::text[], ARRAY['Mixed_Grip_Chin/0.jpg', 'Mixed_Grip_Chin/1.jpg']::text[], 'mixed grip chin hit xa nam hon hop dominadas agarre mixto'),
  (NULL, 'Monster Walk', 'Bước quái vật dây kháng lực', 'Monster Walk', 'Caminata de monstruo con banda', 'legs', 'band', 'compound', 'free_exercise_db', 'Monster_Walk', ARRAY['Place a band around both ankles and another around both knees. There should be enough tension that they are tight when your feet are shoulder width apart.', 'To begin, take short steps forward alternating your left and right foot.', 'After several steps, do just the opposite and walk backward to where you started.']::text[], ARRAY['Monster_Walk/0.jpg', 'Monster_Walk/1.jpg']::text[], 'monster walk buoc quai vat day khang luc caminata de monstruo con banda'),
  (NULL, 'Mountain Climbers', 'Mountain Climbers', 'Mountain Climbers', 'Escaladores', 'legs', 'other', 'bodyweight', 'free_exercise_db', 'Mountain_Climbers', ARRAY['Begin in a pushup position, with your weight supported by your hands and toes. Flexing the knee and hip, bring one leg until the knee is approximately under the hip. This will be your starting position.', 'Explosively reverse the positions of your legs, extending the bent leg until the leg is straight and supported by the toe, and bringing the other foot up with the hip and knee flexed. Repeat in an alternating fashion for 20-30 seconds.']::text[], ARRAY['Mountain_Climbers/0.jpg', 'Mountain_Climbers/1.jpg']::text[], 'mountain climbers leo nui escaladores'),
  (NULL, 'Moving Claw Series', 'Chuỗi bài cào móng', 'Moving Claw Series', 'Serie de garra en movimiento', 'legs', 'other', 'bodyweight', 'free_exercise_db', 'Moving_Claw_Series', ARRAY['This move helps prepare your running form to help you excel at sprinting. As you run, be sure to flex the knee, aiming to kick your glutes as the hip extends.', 'Reload the quad as the leg moves back forward, attacking the ground on the next step.', 'Ensure that as you run, you block with the arms, punching through in a rapid 1-2 motion.']::text[], ARRAY['Moving_Claw_Series/0.jpg', 'Moving_Claw_Series/1.jpg']::text[], 'moving claw series chuoi bai cao mong serie de garra en movimiento'),
  (NULL, 'Muscle Snatch', 'Muscle Snatch', 'Muscle Snatch', 'Arrancada de fuerza', 'legs', 'barbell', 'compound', 'free_exercise_db', 'Muscle_Snatch', ARRAY['Begin with a loaded barbell held at the mid thigh position with a wide grip. The feet should be directly below the hips, with the feet turned out as needed. Lower the hips, with the chest up and the head looking forward. The shoulders should be just in front of the bar. This will be the starting position.', 'Begin the pull by driving through the front of the heels, raising the bar. Transition into the second pull by extending through the hips knees and ankles, driving the bar up as quickly as possible. The bar should be close to the body.', 'Continue raising the bar to the overhead position, without rebending the knees.']::text[], ARRAY['Muscle_Snatch/0.jpg', 'Muscle_Snatch/1.jpg']::text[], 'muscle snatch muscle snatch arrancada de fuerza'),
  (NULL, 'Muscle Up', 'Muscle Up', 'Muscle Up', 'Muscle up', 'back', 'other', 'compound', 'free_exercise_db', 'Muscle_Up', ARRAY['Grip the rings using a false grip, with the base of your palms on top of the rings. Initiate a pull up by pulling the elbows down to your side, flexing the elbows.', 'As you reach the top position of the pull-up, pull the rings to your armpits as you roll your shoulders forward, allowing your elbows to move straight back behind you. This puts you into the proper position to continue into the dip portion of the movement.', 'Maintaining control and stability, extend through the elbow to complete the motion.', 'Use care when lowering yourself to the ground.']::text[], ARRAY['Muscle_Up/0.jpg', 'Muscle_Up/1.jpg']::text[], 'muscle up muscle up muscle up'),
  (NULL, 'Narrow Stance Hack Squats', 'Narrow Stance Hack Squats', 'Narrow Stance Hack Squats', 'Sentadilla hack postura estrecha', 'legs', 'machine', 'compound', 'free_exercise_db', 'Narrow_Stance_Hack_Squats', ARRAY['Place the back of your torso against the back pad of the machine and hook your shoulders under the shoulder pads provided.', 'Position your legs in the platform using a less than shoulder width narrow stance with the toes slightly pointed out. Your feet should be around 3 inches or less apart. Tip: Keep your head up at all times and also maintain the back on the pad at all times.', 'Place your arms on the side handles of the machine and disengage the safety bars (which on most designs is done by moving the side handles from a facing front position to a diagonal position).', 'Now straighten your legs without locking the knees. This will be your starting position.', 'Begin to slowly lower the unit by bending the knees as you maintain a straight posture with the head up (back on the pad at all times). Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to the floor). Inhale as you perform this portion of the movement.', 'Begin to raise the unit as you exhale by pushing the floor with mainly with the heels of your feet as you straighten the legs again and go back to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Narrow_Stance_Hack_Squats/0.jpg', 'Narrow_Stance_Hack_Squats/1.jpg']::text[], 'narrow stance hack squats hack squat dung hep sentadilla hack postura estrecha'),
  (NULL, 'Narrow Stance Leg Press', 'Narrow Stance Leg Press', 'Narrow Stance Leg Press', 'Prensa de piernas postura estrecha', 'legs', 'machine', 'compound', 'free_exercise_db', 'Narrow_Stance_Leg_Press', ARRAY['Using a leg press machine, sit down on the machine and place your legs on the platform directly in front of you at a less-than-shoulder-width narrow stance with the toes slightly pointed out. Your feet should be around 3 inches or less apart. Tip: Keep your head up at all times and also maintain the back on the pad at all times.', 'Lower the safety bars holding the weighted platform in place and press the platform all the way up until your legs are fully extended in front of you. Tip: Make sure that you do not lock your knees. Your torso and the legs should make a perfect 90-degree angle. This will be your starting position.', 'As you inhale, slowly lower the platform until your upper and lower legs make a 90-degree angle.', 'Pushing mainly with the heels of your feet and using the quadriceps go back to the starting position as you exhale.', 'Repeat for the recommended amount of repetitions and ensure to lock the safety pins properly once you are done. You do not want that platform falling on you fully loaded.']::text[], ARRAY['Narrow_Stance_Leg_Press/0.jpg', 'Narrow_Stance_Leg_Press/1.jpg']::text[], 'narrow stance leg press dap dui dung hep prensa de piernas postura estrecha'),
  (NULL, 'Narrow Stance Squats', 'Narrow Stance Squats', 'Narrow Stance Squats', 'Sentadilla postura estrecha', 'legs', 'barbell', 'compound', 'free_exercise_db', 'Narrow_Stance_Squats', ARRAY['This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.', 'Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.', 'Step away from the rack and position your legs using a less-than-shoulder-width narrow stance with the toes slightly pointed out. Feet should be around 3-6 inches apart. Keep your head up at all times (looking down will get you off balance) and maintain a straight back. This will be your starting position. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances discussed in the foot stances section).', 'Begin to slowly lower the bar by bending the knees as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to the floor). Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.', 'Begin to raise the bar as you exhale by pushing the floor with the heel of your foot mainly as you straighten the legs again and go back to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Narrow_Stance_Squats/0.jpg', 'Narrow_Stance_Squats/1.jpg']::text[], 'narrow stance squats squat dung hep sentadilla postura estrecha'),
  (NULL, 'Natural Glute Ham Raise', 'Nâng thân đùi sau tự nhiên', 'Natural Glute Ham Raise', 'Glute-ham natural', 'legs', 'bodyweight', 'bodyweight', 'free_exercise_db', 'Natural_Glute_Ham_Raise', ARRAY['Using the leg pad of a lat pulldown machine or a preacher bench, position yourself so that your ankles are under the pads, knees on the seat, and you are facing away from the machine. You should be upright and maintaining good posture.', 'This will be your starting position. Lower yourself under control until your knees are almost completely straight.', 'Remaining in control, raise yourself back up to the starting position.', 'If you are unable to complete a rep, use a band, a partner, or push off of a box to aid in completing a repetition.']::text[], ARRAY['Natural_Glute_Ham_Raise/0.jpg', 'Natural_Glute_Ham_Raise/1.jpg']::text[], 'natural glute ham raise nang than dui sau tu nhien glute-ham natural'),
  (NULL, 'Neck-SMR', 'Lăn giãn cổ', 'Neck-SMR', 'Liberación de cuello', 'shoulders', 'other', 'timed', 'free_exercise_db', 'Neck-SMR', ARRAY['Using a muscle roller or a rolling pin, place the roller behind your head and against your neck. Make sure that you do not place the roller directly against the spine, but turned slightly so that the roller is pressed against the muscles to either side of the spine. This will be your starting position.', 'Starting at the top of your neck, slowly roll down the muscles of your neck, pausing at points of tension for 10-30 seconds.']::text[], ARRAY['Neck-SMR/0.jpg', 'Neck-SMR/1.jpg']::text[], 'neck-smr lan gian co liberacion de cuello'),
  (NULL, 'Neck Press', 'Đẩy ngực về cổ', 'Neck Press', 'Press al cuello', 'chest', 'barbell', 'compound', 'free_exercise_db', 'Neck_Press', ARRAY['Lie back on a flat bench. Using a medium-width grip (a grip that creates a 90-degree angle in the middle of the movement between the forearms and the upper arms), lift the bar from the rack and hold it straight over your neck with your arms locked. This will be your starting position.', 'As you breathe in, come down slowly until you feel the bar on your neck.', 'After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles. Lock your arms and squeeze your chest in the contracted position, hold for a second and then start coming down slowly again. Tip: It should take at least twice as long to go down than to come up).', 'Repeat the movement for the prescribed amount of repetitions.', 'When you are done, place the bar back in the rack.']::text[], ARRAY['Neck_Press/0.jpg', 'Neck_Press/1.jpg']::text[], 'neck press day nguc ve co press al cuello'),
  (NULL, 'Oblique Crunches', 'Oblique Crunches', 'Oblique Crunches', 'Crunch oblicuo', 'abs', 'bodyweight', 'bodyweight', 'free_exercise_db', 'Oblique_Crunches', ARRAY['Lie flat on the floor with your lower back pressed to the ground. For this exercise, you will need to put one hand beside your head and the other to the side against the floor.', 'Make sure your feet are elevated and resting on a flat surface.', 'Now lift the shoulder in which your hand is touching your head.', 'Simply elevate your shoulder and body upward until you touch your knee. For example, if you have your right hand besides your head, then you want to elevate your body upwards until your right elbow touches your left knee. The same variation can be applied doing the inverse and using your left elbow to touch your right knee.', 'After your knee touches your elbow, lower your body until you have reached the starting position.', 'Remember to breathe in during the eccentric (lowering) part of the exercise and to breathe out during the concentric (upward) part of the exercise.', 'Continue alternating in this manner until all of the recommended repetitions for each side have been completed.']::text[], ARRAY['Oblique_Crunches/0.jpg', 'Oblique_Crunches/1.jpg']::text[], 'oblique crunches gap bung xien crunch oblicuo'),
  (NULL, 'Oblique Crunches - On The Floor', 'Oblique Crunches - On The Floor', 'Oblique Crunches - On The Floor', 'Crunch oblicuo en el suelo', 'abs', 'bodyweight', 'bodyweight', 'free_exercise_db', 'Oblique_Crunches_-_On_The_Floor', ARRAY['Start out by lying on your right side with your legs lying on top of each other. Make sure your knees are bent a little bit.', 'Place your left hand behind your head.', 'Once you are in this set position, begin by moving your left elbow up as you would perform a normal crunch except this time the main emphasis is on your obliques.', 'Crunch as high as you can, hold the contraction for a second and then slowly drop back down into the starting position.', 'Remember to breathe in during the eccentric (lowering) part of the exercise and to breathe out during the concentric (elevation) part of the exercise.']::text[], ARRAY['Oblique_Crunches_-_On_The_Floor/0.jpg', 'Oblique_Crunches_-_On_The_Floor/1.jpg']::text[], 'oblique crunches - on the floor gap bung xien tren san crunch oblicuo en el suelo'),
  (NULL, 'Olympic Squat', 'Olympic Squat', 'Olympic Squat', 'Sentadilla olímpica', 'legs', 'barbell', 'compound', 'free_exercise_db', 'Olympic_Squat', ARRAY['Begin with a barbell supported on top of the traps. The chest should be up, and the head facing forward. Adopt a hip width stance with the feet turned out as needed.', 'Descend by flexing the knees, refraining from moving the hips back as much as possible. This requires that the knees travel forward; ensure that they stay aligned with the feet. The goal is to keep the torso as upright as possible. Continue all the way down, keeping the weight on the front of the heel.', 'At the moment the upper legs contact the lower, reverse the motion, driving the weight upward.']::text[], ARRAY['Olympic_Squat/0.jpg', 'Olympic_Squat/1.jpg']::text[], 'olympic squat squat kieu olympic sentadilla olimpica'),
  (NULL, 'On-Your-Back Quad Stretch', 'Giãn đùi trước nằm ngửa', 'On-Your-Back Quad Stretch', 'Estiramiento de cuádriceps boca arriba', 'legs', 'other', 'timed', 'free_exercise_db', 'On-Your-Back_Quad_Stretch', ARRAY['Lie on a flat bench or step, and hang one leg and arm over the side.', 'Bend the knee and hold the top of the foot. As you do this, be careful not to arch your lower back.', 'Pull the belly button to the spine to stay in neutral. Press your foot down and into your hand. To add the hip stretch, lift the hip of the leg you''re holding up toward the ceiling.', 'Switch sides.']::text[], ARRAY['On-Your-Back_Quad_Stretch/0.jpg', 'On-Your-Back_Quad_Stretch/1.jpg']::text[], 'on-your-back quad stretch gian dui truoc nam ngua estiramiento de cuadriceps boca arriba'),
  (NULL, 'On Your Side Quad Stretch', 'Giãn đùi trước nằm nghiêng', 'On Your Side Quad Stretch', 'Estiramiento de cuádriceps de lado', 'legs', 'other', 'timed', 'free_exercise_db', 'On_Your_Side_Quad_Stretch', ARRAY['Start off by lying on your right side, with your right knee bent at a 90-degree angle resting on the floor in front of you (this stabilizes the torso).', 'Bend your left knee behind you and hold your left foot with your left hand. To stretch your hip flexor, press your left hip forward as you push your left foot back into your hand. Switch sides.']::text[], ARRAY['On_Your_Side_Quad_Stretch/0.jpg', 'On_Your_Side_Quad_Stretch/1.jpg']::text[], 'on your side quad stretch gian dui truoc nam nghieng estiramiento de cuadriceps de lado'),
  (NULL, 'One-Arm Dumbbell Row', 'Chèo một tay tạ đơn', 'One-Arm Dumbbell Row', 'Remo a una mano con mancuerna', 'back', 'dumbbell', 'compound', 'free_exercise_db', 'One-Arm_Dumbbell_Row', ARRAY['Choose a flat bench and place a dumbbell on each side of it.', 'Place the right leg on top of the end of the bench, bend your torso forward from the waist until your upper body is parallel to the floor, and place your right hand on the other end of the bench for support.', 'Use the left hand to pick up the dumbbell on the floor and hold the weight while keeping your lower back straight. The palm of the hand should be facing your torso. This will be your starting position.', 'Pull the resistance straight up to the side of your chest, keeping your upper arm close to your side and keeping the torso stationary. Breathe out as you perform this step. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. Also, make sure that the force is performed with the back muscles and not the arms. Finally, the upper torso should remain stationary and only the arms should move. The forearms should do no other work except for holding the dumbbell; therefore do not try to pull the dumbbell up using the forearms.', 'Lower the resistance straight down to the starting position. Breathe in as you perform this step.', 'Repeat the movement for the specified amount of repetitions.', 'Switch sides and repeat again with the other arm.']::text[], ARRAY['One-Arm_Dumbbell_Row/0.jpg', 'One-Arm_Dumbbell_Row/1.jpg']::text[], 'one-arm dumbbell row cheo mot tay ta don remo a una mano con mancuerna'),
  (NULL, 'One-Arm Flat Bench Dumbbell Flye', 'One-Arm Flat Bench Dumbbell Flye', 'One-Arm Flat Bench Dumbbell Flye', 'Apertura a una mano con mancuerna en banco plano', 'chest', 'dumbbell', 'isolation', 'free_exercise_db', 'One-Arm_Flat_Bench_Dumbbell_Flye', ARRAY['Lie down on a flat bench with a dumbbell in one hand resting on top of your thigh. The palm of your hand with the dumbbell in it should be at a neutral grip.', 'By using your thighs to help you get the dumbbell up, clean the dumbbell so that you can hold it in front of you with your lifting arm being fully extended. Remember to maintain a neutral grip with this exercise. Your non lifting hand should be to the side holding the flat bench for better support. This will be your starting position.', 'Your arm with the weight should have a slight bend on your elbow in order to prevent stress at the biceps tendon. Begin by lowering your arm with the weight in it out in a wide arc until you feel a stretch on your chest. Breathe in as you perform this portion of the movement. Tip: Keep in mind that throughout the movement, your lifting arm should remain stationary; the movement should only occur at the shoulder joint.', 'Return your lifting arm back to the starting position as you squeeze your chest muscles and breathe out. Tip: Make sure to use the same arc of motion used to lower the weights.', 'Hold for a second at the contracted position and repeat the movement for the prescribed amount of repetitions.', 'Switch arms and repeat the exercise.']::text[], ARRAY['One-Arm_Flat_Bench_Dumbbell_Flye/0.jpg', 'One-Arm_Flat_Bench_Dumbbell_Flye/1.jpg']::text[], 'one-arm flat bench dumbbell flye ep nguc mot tay ta don ghe phang apertura a una mano con mancuerna en banco plano'),
  (NULL, 'One-Arm High-Pulley Cable Side Bends', 'Nghiêng lườn một tay cáp cao', 'One-Arm High-Pulley Cable Side Bends', 'Flexiones laterales a una mano en polea alta', 'abs', 'cable', 'isolation', 'free_exercise_db', 'One-Arm_High-Pulley_Cable_Side_Bends', ARRAY['Connect a standard handle to a tower. Move cable to highest pulley position.', 'Stand with side to cable. With one hand, reach up and grab handle with underhand grip.', 'Pull down cable until elbow touches your side and the handle is by your shoulder.', 'Position feet hip-width apart. Place free hand on hip to help gauge pivot point.', 'Keep arm in static position. Contract oblique to bring the weight down in a side crunch.', 'Once you reach maximum contraction, slowly release the weight to the starting position. The weight stack should never be unloaded in a resting position. The aim is constant tension during the set.', 'Repeat to failure.', 'Then, reposition and repeat the same series of movements on the opposite side.']::text[], ARRAY['One-Arm_High-Pulley_Cable_Side_Bends/0.jpg', 'One-Arm_High-Pulley_Cable_Side_Bends/1.jpg']::text[], 'one-arm high-pulley cable side bends nghieng luon mot tay cap cao flexiones laterales a una mano en polea alta'),
  (NULL, 'One-Arm Incline Lateral Raise', 'Nâng tạ ngang một tay ghế dốc', 'One-Arm Incline Lateral Raise', 'Elevación lateral inclinado a una mano', 'shoulders', 'dumbbell', 'isolation', 'free_exercise_db', 'One-Arm_Incline_Lateral_Raise', ARRAY['Lie down sideways on an incline bench press with a dumbbell in the hand. Make sure the shoulder is pressing against the incline bench and the arm is lying across your body with the palm around your navel.', 'Hold a dumbbell in your uppermost arm while keeping it extended in front of you parallel to the floor. This is your starting position.', 'While keeping the dumbbell parallel to the floor at all times, perform a lateral raise. Your arm should travel straight up until it is pointing at the ceiling. Tip: Exhale as you perform this movement. Hold the dumbbell in the position and feel the contraction in the shoulders for a second.', 'While inhaling lower the weight across your body back into the starting position.', 'Repeat the movement for the prescribed amount of repetitions.', 'Switch arms and repeat the movement.']::text[], ARRAY['One-Arm_Incline_Lateral_Raise/0.jpg', 'One-Arm_Incline_Lateral_Raise/1.jpg']::text[], 'one-arm incline lateral raise nang ta ngang mot tay ghe doc elevacion lateral inclinado a una mano'),
  (NULL, 'One-Arm Kettlebell Clean', 'One-Arm Kettlebell Clean', 'One-Arm Kettlebell Clean', 'Cargada a una mano con pesa rusa', 'legs', 'kettlebell', 'compound', 'free_exercise_db', 'One-Arm_Kettlebell_Clean', ARRAY['Place a kettlebell between your feet. As you bend down to grab the kettlebell, push your butt back and keep your eyes looking forward.', 'Clean the kettlebell to your shoulders by extending through the legs and hips as you raise the kettlebell towards your shoulder. The wrist should rotate as you do so.', 'Return the weight to the starting position.']::text[], ARRAY['One-Arm_Kettlebell_Clean/0.jpg', 'One-Arm_Kettlebell_Clean/1.jpg']::text[], 'one-arm kettlebell clean clean kettlebell mot tay cargada a una mano con pesa rusa'),
  (NULL, 'One-Arm Kettlebell Clean and Jerk', 'One-Arm Kettlebell Clean and Jerk', 'One-Arm Kettlebell Clean and Jerk', 'Dos tiempos a una mano con pesa rusa', 'shoulders', 'kettlebell', 'compound', 'free_exercise_db', 'One-Arm_Kettlebell_Clean_and_Jerk', ARRAY['Hold a kettlebell by the handle.', 'Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulder. Rotate your wrist as you do so, so that the palm faces forward.', 'Dip your body by bending the knees, keeping your torso upright.', 'Immediately reverse direction, driving through the heels, in essence jumping to create momentum. As you do so, press the kettlebell overhead to lockout by extending the arms, using your body''s momentum to move the weight.', 'Receive the weight overhead by returning to a squat position underneath the weight.', 'Keeping the weight overhead, return to a standing position. Lower the weight to the floor to perform the next repetition.']::text[], ARRAY['One-Arm_Kettlebell_Clean_and_Jerk/0.jpg', 'One-Arm_Kettlebell_Clean_and_Jerk/1.jpg']::text[], 'one-arm kettlebell clean and jerk clean and jerk kettlebell mot tay dos tiempos a una mano con pesa rusa'),
  (NULL, 'One-Arm Kettlebell Floor Press', 'Đẩy sàn kettlebell một tay', 'One-Arm Kettlebell Floor Press', 'Press en el suelo a una mano con pesa rusa', 'chest', 'kettlebell', 'compound', 'free_exercise_db', 'One-Arm_Kettlebell_Floor_Press', ARRAY['Lie on the floor holding a kettlebell with one hand, with your upper arm supported by the floor. The palm should be facing in.', 'Press the kettlebell straight up toward the ceiling, rotating your wrist.', 'Lower the kettlebell back to the starting position and repeat.']::text[], ARRAY['One-Arm_Kettlebell_Floor_Press/0.jpg', 'One-Arm_Kettlebell_Floor_Press/1.jpg']::text[], 'one-arm kettlebell floor press day san kettlebell mot tay press en el suelo a una mano con pesa rusa'),
  (NULL, 'One-Arm Kettlebell Jerk', 'One-Arm Kettlebell Jerk', 'One-Arm Kettlebell Jerk', 'Envión a una mano con pesa rusa', 'shoulders', 'kettlebell', 'compound', 'free_exercise_db', 'One-Arm_Kettlebell_Jerk', ARRAY['Hold a kettlebell by the handle. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulder. Rotate your wrist as you do so, so that the palm faces forward. This will be your starting position.', 'Dip your body by bending the knees, keeping your torso upright.', 'Immediately reverse direction, driving through the heels, in essence jumping to create momentum. As you do so, press the kettlebell overhead to lockout by extending the arms, using your body''s momentum to move the weight. Receive the weight overhead by returning to a squat position underneath the weight. Keeping the weight overhead, return to a standing position.', 'Lower the weight to perform the next repetition.']::text[], ARRAY['One-Arm_Kettlebell_Jerk/0.jpg', 'One-Arm_Kettlebell_Jerk/1.jpg']::text[], 'one-arm kettlebell jerk jerk kettlebell mot tay envion a una mano con pesa rusa'),
  (NULL, 'One-Arm Kettlebell Military Press To The Side', 'Đẩy vai nghiêng kettlebell một tay', 'One-Arm Kettlebell Military Press To The Side', 'Press militar lateral a una mano con pesa rusa', 'shoulders', 'kettlebell', 'compound', 'free_exercise_db', 'One-Arm_Kettlebell_Military_Press_To_The_Side', ARRAY['Clean a kettlebell to your shoulder. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulder. Rotate your wrist as you do so, so that the palm faces inward. This will be your starting position.', 'Look at the kettlebell and press it up and out until it is locked out overhead.', 'Lower the kettlebell back to your shoulder under control and repeat. Make sure to contract your lat, butt, and stomach forcefully for added stability and strength.']::text[], ARRAY['One-Arm_Kettlebell_Military_Press_To_The_Side/0.jpg', 'One-Arm_Kettlebell_Military_Press_To_The_Side/1.jpg']::text[], 'one-arm kettlebell military press to the side day vai nghieng kettlebell mot tay press militar lateral a una mano con pesa rusa'),
  (NULL, 'One-Arm Kettlebell Para Press', 'Para press kettlebell một tay', 'One-Arm Kettlebell Para Press', 'Para press a una mano con pesa rusa', 'shoulders', 'kettlebell', 'compound', 'free_exercise_db', 'One-Arm_Kettlebell_Para_Press', ARRAY['Clean a kettlebell to your shoulder. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulder. Rotate your wrist as you do so, so that the palm faces forward. This will be your starting position.', 'Hold the kettlebell with the elbow out to the side, and press it up and out until it is locked out overhead.', 'Lower the kettlebell back to your shoulder under control and repeat. Make sure to contract your lat, butt, and stomach forcefully for added stability and strength.']::text[], ARRAY['One-Arm_Kettlebell_Para_Press/0.jpg', 'One-Arm_Kettlebell_Para_Press/1.jpg']::text[], 'one-arm kettlebell para press para press kettlebell mot tay para press a una mano con pesa rusa'),
  (NULL, 'One-Arm Kettlebell Push Press', 'One-Arm Kettlebell Push Press', 'One-Arm Kettlebell Push Press', 'Push press a una mano con pesa rusa', 'shoulders', 'kettlebell', 'compound', 'free_exercise_db', 'One-Arm_Kettlebell_Push_Press', ARRAY['Hold a kettlebell by the handle. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulder. Rotate your wrist as you do so, so that the palm faces forward. This will be your starting position.', 'Dip your body by bending the knees, keeping your torso upright.', 'Immediately reverse direction, driving through the heels, in essence jumping to create momentum. As you do so, press the kettlebell overhead to lockout by extending the arms, using your body''s momentum to move the weight. Lower the weight to perform the next repetition.']::text[], ARRAY['One-Arm_Kettlebell_Push_Press/0.jpg', 'One-Arm_Kettlebell_Push_Press/1.jpg']::text[], 'one-arm kettlebell push press push press kettlebell mot tay push press a una mano con pesa rusa'),
  (NULL, 'One-Arm Kettlebell Row', 'Chèo kettlebell một tay', 'One-Arm Kettlebell Row', 'Remo a una mano con pesa rusa', 'back', 'kettlebell', 'compound', 'free_exercise_db', 'One-Arm_Kettlebell_Row', ARRAY['Place a kettlebell in front of your feet. Bend your knees slightly and then push your butt out as much as possible as you bend over to get in the starting position. Grab the kettlebell and pull it to your stomach, retracting your shoulder blade and flexing the elbow. Keep your back straight. Lower and repeat.']::text[], ARRAY['One-Arm_Kettlebell_Row/0.jpg', 'One-Arm_Kettlebell_Row/1.jpg']::text[], 'one-arm kettlebell row cheo kettlebell mot tay remo a una mano con pesa rusa'),
  (NULL, 'One-Arm Kettlebell Snatch', 'One-Arm Kettlebell Snatch', 'One-Arm Kettlebell Snatch', 'Arrancada a una mano con pesa rusa', 'shoulders', 'kettlebell', 'compound', 'free_exercise_db', 'One-Arm_Kettlebell_Snatch', ARRAY['Place a kettlebell between your feet. Bend your knees and push your butt back to get in the proper starting position.', 'Look straight ahead and swing the kettlebell back between your legs.', 'Immediately reverse the direction and drive through with your hips and knees, accelerating the kettlebell upward. As the kettlebell rises to your shoulder rotate your hand and punch straight up, using momentum to receive the weight locked out overhead.']::text[], ARRAY['One-Arm_Kettlebell_Snatch/0.jpg', 'One-Arm_Kettlebell_Snatch/1.jpg']::text[], 'one-arm kettlebell snatch snatch kettlebell mot tay arrancada a una mano con pesa rusa'),
  (NULL, 'One-Arm Kettlebell Split Jerk', 'One-Arm Kettlebell Split Jerk', 'One-Arm Kettlebell Split Jerk', 'Envión en tijera a una mano con pesa rusa', 'shoulders', 'kettlebell', 'compound', 'free_exercise_db', 'One-Arm_Kettlebell_Split_Jerk', ARRAY['Hold a kettlebell by the handle. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulder. Rotate your wrist as you do so, so that the palm faces forward. This will be your starting position.', 'Dip your body by bending the knees, keeping your torso upright.', 'Immediately reverse direction, driving through the heels, in essence jumping to create momentum. As you do so, press the kettlebell overhead to lockout by extending the arms, using your body''s momentum to move the weight.', 'Receive the weight overhead by returning to a squat position underneath the weight, positioning one leg in front of you and one leg behind you.', 'Keeping the weight overhead, return to a standing position and bring your feet together. Lower the weight to perform the next repetition.']::text[], ARRAY['One-Arm_Kettlebell_Split_Jerk/0.jpg', 'One-Arm_Kettlebell_Split_Jerk/1.jpg']::text[], 'one-arm kettlebell split jerk split jerk kettlebell mot tay envion en tijera a una mano con pesa rusa'),
  (NULL, 'One-Arm Kettlebell Split Snatch', 'One-Arm Kettlebell Split Snatch', 'One-Arm Kettlebell Split Snatch', 'Arrancada en tijera a una mano con pesa rusa', 'shoulders', 'kettlebell', 'compound', 'free_exercise_db', 'One-Arm_Kettlebell_Split_Snatch', ARRAY['Hold a kettlebell in one hand by the handle.', 'Squat towards the floor, and then reverse the motion, extending the hips, knees, and finally the ankles, to raise the kettlebell overhead.', 'After fully extending the body, descend into a lunge position to receive the weights overhead, one leg forward and one leg back. Ensure you drive through with your hips and lock the ketttlebells overhead in one uninterrupted motion.', 'Return to a standing position, holding the weight overhead, and bring the feet together. Lower the weight to return to the starting position.']::text[], ARRAY['One-Arm_Kettlebell_Split_Snatch/0.jpg', 'One-Arm_Kettlebell_Split_Snatch/1.jpg']::text[], 'one-arm kettlebell split snatch split snatch kettlebell mot tay arrancada en tijera a una mano con pesa rusa'),
  (NULL, 'One-Arm Kettlebell Swings', 'One-Arm Kettlebell Swings', 'One-Arm Kettlebell Swings', 'Balanceo a una mano con pesa rusa', 'legs', 'kettlebell', 'compound', 'free_exercise_db', 'One-Arm_Kettlebell_Swings', ARRAY[]::text[], ARRAY['One-Arm_Kettlebell_Swings/0.jpg', 'One-Arm_Kettlebell_Swings/1.jpg']::text[], 'one-arm kettlebell swings vung kettlebell mot tay balanceo a una mano con pesa rusa'),
  (NULL, 'One-Arm Long Bar Row', 'Chèo thanh dài một tay', 'One-Arm Long Bar Row', 'Remo con barra larga a una mano', 'back', 'barbell', 'compound', 'free_exercise_db', 'One-Arm_Long_Bar_Row', ARRAY['Position a bar into a landmine or in a corner to keep it from moving. Load an appropriate weight onto your end.', 'Stand next to the bar, and take a grip with one hand close to the collar. Using your hips and legs, rise to a standing position.', 'Assume a bent-knee stance with your hips back and your chest up. Your arm should be extended. This will be your starting position.', 'Pull the weight to your side by retracting the shoulder and flexing the elbow. Do not jerk the weight or cheat during the movement.', 'After a brief pause, return to the starting position.']::text[], ARRAY['One-Arm_Long_Bar_Row/0.jpg', 'One-Arm_Long_Bar_Row/1.jpg']::text[], 'one-arm long bar row cheo thanh dai mot tay remo con barra larga a una mano'),
  (NULL, 'One-Arm Medicine Ball Slam', 'Đập bóng tạ một tay', 'One-Arm Medicine Ball Slam', 'Golpe de balón medicinal a una mano', 'abs', 'medicine ball', 'compound', 'free_exercise_db', 'One-Arm_Medicine_Ball_Slam', ARRAY['Start in a standing position with a staggered, athletic stance. Hold a medicine ball in one hand, on the same side as your back leg. This will be your starting position.', 'Begin by winding the arm, raising the medicine ball above your head. As you do so, extend through the hips, knees, and ankles to load up for the slam.', 'At peak extension, flex the shoulders, spine, and hips to throw the ball hard into the ground directly in front of you.', 'Catch the ball on the bounce and continue for the desired number of repetitions.']::text[], ARRAY['One-Arm_Medicine_Ball_Slam/0.jpg', 'One-Arm_Medicine_Ball_Slam/1.jpg']::text[], 'one-arm medicine ball slam dap bong ta mot tay golpe de balon medicinal a una mano'),
  (NULL, 'One-Arm Open Palm Kettlebell Clean', 'One-Arm Open Palm Kettlebell Clean', 'One-Arm Open Palm Kettlebell Clean', 'Cargada a una mano palma abierta con pesa rusa', 'legs', 'kettlebell', 'compound', 'free_exercise_db', 'One-Arm_Open_Palm_Kettlebell_Clean', ARRAY['Place one kettlebell between your feet.', 'Grab the handle with one hand and raise the kettlebell rapidly, let it flip so that the ball of the kettlebell lands in the palm of your hand.', 'Throw the kettlebell out in front of you and catch the handle with one hand.', 'Take the kettlebell to the floor and repeat. Make sure to work both arms.']::text[], ARRAY['One-Arm_Open_Palm_Kettlebell_Clean/0.jpg', 'One-Arm_Open_Palm_Kettlebell_Clean/1.jpg']::text[], 'one-arm open palm kettlebell clean clean kettlebell mot tay xoe long ban tay cargada a una mano palma abierta con pesa rusa'),
  (NULL, 'One-Arm Overhead Kettlebell Squats', 'One-Arm Overhead Kettlebell Squats', 'One-Arm Overhead Kettlebell Squats', 'Sentadilla sobre la cabeza a una mano con pesa rusa', 'legs', 'kettlebell', 'compound', 'free_exercise_db', 'One-Arm_Overhead_Kettlebell_Squats', ARRAY['Clean and press a kettlebell with one arm. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulder. Rotate your wrist as you do so. Press the weight overhead by extending through the elbow.This will be your starting position.', 'Looking straight ahead and keeping a kettlebell locked out above you, flex the knees and hips and lower your torso between your legs, keeping your head and chest up.', 'Pause at the bottom position for a second before rising back to the top, driving through the heels of your feet.']::text[], ARRAY['One-Arm_Overhead_Kettlebell_Squats/0.jpg', 'One-Arm_Overhead_Kettlebell_Squats/1.jpg']::text[], 'one-arm overhead kettlebell squats squat kettlebell mot tay qua dau sentadilla sobre la cabeza a una mano con pesa rusa'),
  (NULL, 'One-Arm Side Deadlift', 'One-Arm Side Deadlift', 'One-Arm Side Deadlift', 'Peso muerto lateral a una mano', 'legs', 'barbell', 'compound', 'free_exercise_db', 'One-Arm_Side_Deadlift', ARRAY['Stand to the side of a barbell next to its center. Bend your knees and lower your body until you are able to reach the barbell.', 'Grasp the bar as if you were grabbing a briefcase (palms facing you since the bar is sideways). You may need a wrist wrap if you are using a significant amount of weight. This is your starting position.', 'Use your legs to help lift the barbell up while exhaling. Your arms should extend fully as bring the barbell up until you are in a standing position.', 'Slowly bring the barbell back down while inhaling. Tip: Make sure to bend your knees while lowering the weight to avoid any injury from occurring.', 'Repeat for the recommended amount of repetitions.', 'Switch arms and repeat the movement.']::text[], ARRAY['One-Arm_Side_Deadlift/0.jpg', 'One-Arm_Side_Deadlift/1.jpg']::text[], 'one-arm side deadlift deadlift ben hong mot tay peso muerto lateral a una mano'),
  (NULL, 'One-Arm Side Laterals', 'Nâng tạ ngang một tay', 'One-Arm Side Laterals', 'Elevación lateral a una mano', 'shoulders', 'dumbbell', 'isolation', 'free_exercise_db', 'One-Arm_Side_Laterals', ARRAY['Pick a dumbbell and place it in one of your hands. Your non lifting hand should be used to grab something steady such as an incline bench press. Lean towards your lifting arm and away from the hand that is gripping the incline bench as this will allow you to keep your balance.', 'Stand with a straight torso and have the dumbbell by your side at arm''s length with the palm of the hand facing you. This will be your starting position.', 'While maintaining the torso stationary (no swinging), lift the dumbbell to your side with a slight bend on the elbow and your hand slightly tilted forward as if pouring water in a glass. Continue to go up until you arm is parallel to the floor. Exhale as you execute this movement and pause for a second at the top.', 'Lower the dumbbell back down slowly to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions.', 'Switch arms and repeat the exercise.']::text[], ARRAY['One-Arm_Side_Laterals/0.jpg', 'One-Arm_Side_Laterals/1.jpg']::text[], 'one-arm side laterals nang ta ngang mot tay elevacion lateral a una mano'),
  (NULL, 'One-Legged Cable Kickback', 'Đá chân sau cáp một chân', 'One-Legged Cable Kickback', 'Patada trasera en polea a una pierna', 'glutes', 'cable', 'isolation', 'free_exercise_db', 'One-Legged_Cable_Kickback', ARRAY['Hook a leather ankle cuff to a low cable pulley and then attach the cuff to your ankle.', 'Face the weight stack from a distance of about two feet, grasping the steel frame for support.', 'While keeping your knees and hips bent slightly and your abs tight, contract your glutes to slowly "kick" the working leg back in a semicircular arc as high as it will comfortably go as you breathe out. Tip: At full extension, squeeze your glutes for a second in order to achieve a peak contraction.', 'Now slowly bring your working leg forward, resisting the pull of the cable until you reach the starting position.', 'Repeat for the recommended amount of repetitions.', 'Switch legs and repeat the movement for the other side.']::text[], ARRAY['One-Legged_Cable_Kickback/0.jpg', 'One-Legged_Cable_Kickback/1.jpg']::text[], 'one-legged cable kickback da chan sau cap mot chan patada trasera en polea a una pierna'),
  (NULL, 'One Arm Against Wall', 'Giãn vai một tay vào tường', 'One Arm Against Wall', 'Estiramiento de brazo contra la pared', 'back', 'other', 'timed', 'free_exercise_db', 'One_Arm_Against_Wall', ARRAY['From a standing position, place a bent arm against a wall or doorway.', 'Slowly lean toward your arm until you feel a stretch in your lats.']::text[], ARRAY['One_Arm_Against_Wall/0.jpg', 'One_Arm_Against_Wall/1.jpg']::text[], 'one arm against wall gian vai mot tay vao tuong estiramiento de brazo contra la pared'),
  (NULL, 'One Arm Chin-Up', 'Hít xà một tay', 'One Arm Chin-Up', 'Dominada a una mano', 'back', 'other', 'compound', 'free_exercise_db', 'One_Arm_Chin-Up', ARRAY['For this exercise, start out by placing a towel around a chin up bar.', 'Grab the chin-up bar with your palm facing you. One hand will be grabbing the chin-up bar and the other will be grabbing the towel.', 'Bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.v', 'Pull your torso up until the bar touches your upper chest by drawing the shoulders and the upper arms down and back. Exhale as you perform this portion of the movement. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary as it moves through space and only the arms should move. The forearms should do no other work other than hold the bar.', 'After a second on the contracted position, start to inhale and slowly lower your torso back to the starting position when your arms are fully extended and the lats are fully stretched.', 'Repeat this motion for the prescribed amount of repetitions.', 'Switch arms and repeat the movement.']::text[], ARRAY['One_Arm_Chin-Up/0.jpg', 'One_Arm_Chin-Up/1.jpg']::text[], 'one arm chin-up hit xa mot tay dominada a una mano'),
  (NULL, 'One Arm Dumbbell Bench Press', 'One Arm Dumbbell Bench Press', 'One Arm Dumbbell Bench Press', 'Press de banca a una mano con mancuerna', 'chest', 'dumbbell', 'compound', 'free_exercise_db', 'One_Arm_Dumbbell_Bench_Press', ARRAY['Lie down on a flat bench with a dumbbell in one hand on top of your thigh.', 'By using your thigh to help you get the dumbbell up, clean the dumbbell up so that you can hold it in front of you at shoulder width. Use the hand you are not lifting with to help position the dumbbell over you properly.', 'Once at shoulder width, rotate your wrist forward so that the palm of your hand is facing away from you. This will be your starting position.', 'Bring down the weights slowly to your side as you breathe in. Keep full control of the dumbbell at all times. Tip: Use the hand that you are not lifting with to help keep the dumbbell balance as you may struggle a bit at first. Only use your non-lifting hand if it is needed. Otherwise, keep it resting to the side.', 'As you breathe out, push the dumbbells up using your pectoral muscles. Lock your arms in the contracted position, squeeze your chest, hold for a second and then start coming down slowly. Tip: It should take at least twice as long to go down than to come up.', 'Repeat the movement for the prescribed amount of repetitions of your training program.', 'Switch arms and repeat the movement.']::text[], ARRAY['One_Arm_Dumbbell_Bench_Press/0.jpg', 'One_Arm_Dumbbell_Bench_Press/1.jpg']::text[], 'one arm dumbbell bench press day nguc ta don mot tay press de banca a una mano con mancuerna'),
  (NULL, 'One Arm Dumbbell Preacher Curl', 'One Arm Dumbbell Preacher Curl', 'One Arm Dumbbell Preacher Curl', 'Curl predicador a una mano con mancuerna', 'biceps', 'dumbbell', 'isolation', 'free_exercise_db', 'One_Arm_Dumbbell_Preacher_Curl', ARRAY['Grab a dumbbell with the right arm and place the upper arm on top of the preacher bench or the incline bench. The dumbbell should be held at shoulder length. This will be your starting position.', 'As you breathe in, slowly lower the dumbbell until your upper arm is extended and the biceps is fully stretched.', 'As you exhale, use the biceps to curl the weight up until your biceps is fully contracted and the dumbbell is at shoulder height. Again, remember that to ensure full contraction you need to bring that small finger higher than the thumb.', 'Squeeze the biceps hard for a second at the contracted position and repeat for the recommended amount of repetitions.', 'Switch arms and repeat the movement.']::text[], ARRAY['One_Arm_Dumbbell_Preacher_Curl/0.jpg', 'One_Arm_Dumbbell_Preacher_Curl/1.jpg']::text[], 'one arm dumbbell preacher curl cuon tay truoc ghe doc mot tay ta don curl predicador a una mano con mancuerna'),
  (NULL, 'One Arm Floor Press', 'Đẩy sàn một tay', 'One Arm Floor Press', 'Press en el suelo a una mano', 'triceps', 'barbell', 'compound', 'free_exercise_db', 'One_Arm_Floor_Press', ARRAY['Lie down on a flat surface with your back pressing against the floor or an exercise mat. Make sure your knees are bent.', 'Have a partner hand you the bar on one hand. When starting, your arm should be just about fully extended, similar to the starting position of a barbell bench press. However, this time your grip will be neutral (palms facing your torso).', 'Make sure the hand you are not using to lift the weight is placed by your side.', 'Begin the exercise by lowering the barbell until your elbow touches the ground. Make sure to breathe in as this is the eccentric (lowering part of the exercise).', 'Then start lifting the barbell back up to the original starting position. Remember to breathe out during the concentric (lifting part of the exercise).', 'Repeat until you have performed your recommended repetitions.', 'Switch arms and repeat the movement.']::text[], ARRAY['One_Arm_Floor_Press/0.jpg', 'One_Arm_Floor_Press/1.jpg']::text[], 'one arm floor press day san mot tay press en el suelo a una mano'),
  (NULL, 'One Arm Lat Pulldown', 'One Arm Lat Pulldown', 'One Arm Lat Pulldown', 'Jalón a una mano', 'back', 'cable', 'compound', 'free_exercise_db', 'One_Arm_Lat_Pulldown', ARRAY['Select an appropriate weight and adjust the knee pad to help keep you down. Grasp the handle with a pronated grip. This will be your starting position.', 'Pull the handle down, squeezing your elbow to your side as you flex the elbow.', 'Pause at the bottom of the motion, and then slowly return the handle to the starting position.', 'For multiple repetitions, avoid completely returning the weight to keep tension on the muscles being worked.']::text[], ARRAY['One_Arm_Lat_Pulldown/0.jpg', 'One_Arm_Lat_Pulldown/1.jpg']::text[], 'one arm lat pulldown keo xa xuong mot tay jalon a una mano'),
  (NULL, 'One Arm Pronated Dumbbell Triceps Extension', 'Duỗi tay sau một tay tạ đơn nắm úp', 'One Arm Pronated Dumbbell Triceps Extension', 'Extensión de tríceps a una mano agarre prono', 'triceps', 'dumbbell', 'isolation', 'free_exercise_db', 'One_Arm_Pronated_Dumbbell_Triceps_Extension', ARRAY['Lie flat on a bench while holding a dumbbell at arms length. Your arm should be perpendicular to your body. The palm of your hand should be facing towards your feet as a pronated grip is required to perform this exercise.', 'Place your non lifting hand on your bicep for support.', 'Slowly begin to lower the dumbbell down as you breathe in.', 'Then, begin lifting the dumbbell upward as you contract the triceps. Remember to breathe out during the concentric (lifting part of the exercise).', 'Repeat until you have performed your set repetitions.', 'Switch arms and repeat the movement.']::text[], ARRAY['One_Arm_Pronated_Dumbbell_Triceps_Extension/0.jpg', 'One_Arm_Pronated_Dumbbell_Triceps_Extension/1.jpg']::text[], 'one arm pronated dumbbell triceps extension duoi tay sau mot tay ta don nam up extension de triceps a una mano agarre prono'),
  (NULL, 'One Arm Supinated Dumbbell Triceps Extension', 'Duỗi tay sau một tay tạ đơn nắm ngửa', 'One Arm Supinated Dumbbell Triceps Extension', 'Extensión de tríceps a una mano agarre supino', 'triceps', 'dumbbell', 'isolation', 'free_exercise_db', 'One_Arm_Supinated_Dumbbell_Triceps_Extension', ARRAY['Lie flat on a bench while holding a dumbbell at arms length. Your arm should be perpendicular to your body. The palm of your hand should be facing towards your face as a supinated grip is required to perform this exercise.', 'Place your non lifting hand on your bicep for support.', 'Slowly begin to lower the dumbbell down as you breathe in.', 'Then, begin lifting the dumbbell upward as you contract the triceps. Remember to breathe out during the concentric (lifting part of the exercise).', 'Repeat until you have performed your set repetitions.', 'Switch arms and repeat the movement.', 'Switch arms again and repeat the movement.']::text[], ARRAY['One_Arm_Supinated_Dumbbell_Triceps_Extension/0.jpg', 'One_Arm_Supinated_Dumbbell_Triceps_Extension/1.jpg']::text[], 'one arm supinated dumbbell triceps extension duoi tay sau mot tay ta don nam ngua extension de triceps a una mano agarre supino'),
  (NULL, 'One Half Locust', 'Tư thế châu chấu một nửa', 'One Half Locust', 'Media langosta', 'legs', 'other', 'timed', 'free_exercise_db', 'One_Half_Locust', ARRAY['Lie facedown on the floor.', 'Put your left hand under your left hipbone to pad your hip and pubic bone.', 'Bend your right knee so you can hold the foot in your right hand.', 'Lift the foot in the air and simultaneously lift your shoulders off the floor. This also stretches the right hip flexor and the chest and shoulders. Switch sides. If it doesn''t bother your back, you can try it with both arms and legs at the same time.']::text[], ARRAY['One_Half_Locust/0.jpg', 'One_Half_Locust/1.jpg']::text[], 'one half locust tu the chau chau mot nua media langosta'),
  (NULL, 'One Handed Hang', 'Treo xà một tay', 'One Handed Hang', 'Colgarse con una mano', 'back', 'other', 'timed', 'free_exercise_db', 'One_Handed_Hang', ARRAY['Grab onto a chinup bar with one hand, using a pronated grip. Keep your feet on the floor or a step. Allow the majority of your weight to hang from that hand, while keeping your feet on the ground. Hold for 10-20 seconds and switch sides.']::text[], ARRAY['One_Handed_Hang/0.jpg', 'One_Handed_Hang/1.jpg']::text[], 'one handed hang treo xa mot tay colgarse con una mano'),
  (NULL, 'One Knee To Chest', 'Kéo một gối vào ngực', 'One Knee To Chest', 'Una rodilla al pecho', 'glutes', 'other', 'timed', 'free_exercise_db', 'One_Knee_To_Chest', ARRAY['Start off by lying on the floor.', 'Extend one leg straight and pull the other knee to your chest. Hold under the knee joint to protect the kneecap.', 'Gently tug that knee toward your nose.', 'Switch sides. This stretches the buttocks and lower back of the bent leg and the hip flexor of the straight leg.']::text[], ARRAY['One_Knee_To_Chest/0.jpg', 'One_Knee_To_Chest/1.jpg']::text[], 'one knee to chest keo mot goi vao nguc una rodilla al pecho'),
  (NULL, 'One Leg Barbell Squat', 'One Leg Barbell Squat', 'One Leg Barbell Squat', 'Sentadilla a una pierna con barra', 'legs', 'barbell', 'compound', 'free_exercise_db', 'One_Leg_Barbell_Squat', ARRAY['Start by standing about 2 to 3 feet in front of a flat bench with your back facing the bench. Have a barbell in front of you on the floor. Tip: Your feet should be shoulder width apart from each other.', 'Bend the knees and use a pronated grip with your hands being wider than shoulder width apart from each other to lift the barbell up until you can rest it on your chest.', 'Then lift the barbell over your head and rest it on the base of your neck. Move one foot back so that your toe is resting on the flat bench. Your other foot should be stationary in front of you. Keep your head up at all times as looking down will get you off balance and also maintain a straight back. Tip: Make sure your back is straight and chest is out while performing this exercise.', 'As you inhale, slowly lower your leg until your thigh is parallel to the floor. At this point, your knee should be over your toes. Your chest should be directly above the middle of your thigh.', 'Leading with the chest and hips and contracting the quadriceps, elevate your leg back to the starting position as you exhale.', 'Repeat for the recommended amount of repetitions.', 'Switch legs and repeat the movement.']::text[], ARRAY['One_Leg_Barbell_Squat/0.jpg', 'One_Leg_Barbell_Squat/1.jpg']::text[], 'one leg barbell squat squat mot chan ta don sentadilla a una pierna con barra'),
  (NULL, 'Open Palm Kettlebell Clean', 'Open Palm Kettlebell Clean', 'Open Palm Kettlebell Clean', 'Cargada palma abierta con pesa rusa', 'legs', 'kettlebell', 'compound', 'free_exercise_db', 'Open_Palm_Kettlebell_Clean', ARRAY['Place one kettlebell between your feet. Clean the kettlebell by extending through the legs and hips as you raise the kettlebell towards your shoulders.', 'Release the kettlebell as it comes up, and let it flip so that the ball of the kettlebell lands in the palms of your hands.', 'Release the kettlebell out in front of you and catch the handle with both hands. Lower the kettlebell to the starting position and repeat.']::text[], ARRAY['Open_Palm_Kettlebell_Clean/0.jpg', 'Open_Palm_Kettlebell_Clean/1.jpg']::text[], 'open palm kettlebell clean clean kettlebell xoe long ban tay cargada palma abierta con pesa rusa'),
  (NULL, 'Otis-Up', 'Gập bụng Otis-up', 'Otis-Up', 'Otis-up', 'abs', 'other', 'compound', 'free_exercise_db', 'Otis-Up', ARRAY['Secure your feet and lay back on the floor. Your knees should be bent. Hold a weight with both hands to your chest. This will be your starting position.', 'Initiate the movement by flexing the hips and spine to raise your torso up from the ground.', 'As you move up, press the weight up so that it is above your head at the top of the movement.', 'Return the weight to your chest as you reverse the sit-up motion, ensuring not to go all the way down to the floor.']::text[], ARRAY['Otis-Up/0.jpg', 'Otis-Up/1.jpg']::text[], 'otis-up gap bung otis-up otis-up'),
  (NULL, 'Overhead Cable Curl', 'Overhead Cable Curl', 'Overhead Cable Curl', 'Curl en polea sobre la cabeza', 'biceps', 'cable', 'isolation', 'free_exercise_db', 'Overhead_Cable_Curl', ARRAY['To begin, set a weight that is comfortable on each side of the pulley machine. Note: Make sure that the amount of weight selected is the same on each side.', 'Now adjust the height of the pulleys on each side and make sure that they are positioned at a height higher than that of your shoulders.', 'Stand in the middle of both sides and use an underhand grip (palms facing towards the ceiling) to grab each handle. Your arms should be fully extended and parallel to the floor with your feet positioned shoulder width apart from each other. Your body should be evenly aligned the handles. This is the starting position.', 'While exhaling, slowly squeeze the biceps on each side until your forearms and biceps touch.', 'While inhaling, move your forearms back to the starting position. Note: Your entire body is stationary during this exercise except for the forearms.', 'Repeat for the recommended amount of repetitions prescribed in your program.']::text[], ARRAY['Overhead_Cable_Curl/0.jpg', 'Overhead_Cable_Curl/1.jpg']::text[], 'overhead cable curl cuon tay truoc cap qua dau curl en polea sobre la cabeza'),
  (NULL, 'Overhead Lat', 'Giãn xô qua đầu', 'Overhead Lat', 'Estiramiento de dorsal sobre la cabeza', 'back', 'other', 'timed', 'free_exercise_db', 'Overhead_Lat', ARRAY['Sit upright on the floor with your partner behind you. Raise one arm straight up, and flex the elbow, attempting to touch your hand to your back. Your parner should hold your tricep and wrist. This will be your starting position.', 'Attempt to pull your upper arm to your side as your partner prevents you from doing actually doing so.', 'After 10-20 seconds, relax the arm and allow your partner to further stretch the lat by applying gentle pressure to the tricep. Hold for 10-20 seconds, and then switch sides.']::text[], ARRAY['Overhead_Lat/0.jpg', 'Overhead_Lat/1.jpg']::text[], 'overhead lat gian xo qua dau estiramiento de dorsal sobre la cabeza'),
  (NULL, 'Overhead Slam', 'Đập bóng qua đầu', 'Overhead Slam', 'Golpe por encima de la cabeza', 'back', 'medicine ball', 'compound', 'free_exercise_db', 'Overhead_Slam', ARRAY['Hold a medine ball with both hands and stand with your feet at shoulder width. This will be your starting position.', 'Initiate the countermovement by raising the ball above your head and fully extending your body.', 'Reverse the motion, slamming the ball into the ground directly in front of you as hard as you can.', 'Receive the ball with both hands on the bounce and repeat the movement.']::text[], ARRAY['Overhead_Slam/0.jpg', 'Overhead_Slam/1.jpg']::text[], 'overhead slam dap bong qua dau golpe por encima de la cabeza'),
  (NULL, 'Overhead Squat', 'Overhead Squat', 'Overhead Squat', 'Sentadilla sobre la cabeza', 'legs', 'barbell', 'compound', 'free_exercise_db', 'Overhead_Squat', ARRAY['Start out by having a barbell in front of you on the floor. Your feet should be wider than shoulder width apart from each other.', 'Bend the knees and use a pronated grip (palms facing you) to grab the barbell. Your hands should be at a wider than shoulder width apart from each other before lifting. Once you are positioned, lift the barbell up until you can rest it on your chest.', 'Move the barbell over and slightly behind your head and make sure your arms are fully extended. Keep your head up at all times and also maintain a straight back. Retract your shoulder blades. This is your starting position.', 'Slowly lower the weight by bending your knees until your thighs are parallel to the ground while inhaling. Tip: Keep your back straight while performing this exercise to avoid any injuries and your arms should remain extended and over your head at all times.', 'Now use your feet and legs to help bring the weight back up to the starting position while exhaling.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Overhead_Squat/0.jpg', 'Overhead_Squat/1.jpg']::text[], 'overhead squat squat ta qua dau sentadilla sobre la cabeza'),
  (NULL, 'Overhead Stretch', 'Giãn cơ qua đầu', 'Overhead Stretch', 'Estiramiento por encima de la cabeza', 'abs', 'other', 'timed', 'free_exercise_db', 'Overhead_Stretch', ARRAY['Standing straight up, lace your fingers together and open your palms to the ceiling. Keep your shoulders down as you extend your arms up.', 'To create a full torso stretch, pull your tailbone down and stabilize your torso as you do this. Stretch the muscles on both the front and the back of the torso.']::text[], ARRAY['Overhead_Stretch/0.jpg', 'Overhead_Stretch/1.jpg']::text[], 'overhead stretch gian co qua dau estiramiento por encima de la cabeza'),
  (NULL, 'Overhead Triceps', 'Giãn tay sau qua đầu', 'Overhead Triceps', 'Estiramiento de tríceps sobre la cabeza', 'triceps', 'bodyweight', 'timed', 'free_exercise_db', 'Overhead_Triceps', ARRAY['Sit upright on the floor with your partner behind you. Raise one arm straight up, and flex the elbow, attempting to touch your hand to your back. Your parner should hold your elbow and wrist. This will be your starting position.', 'Attempt to extend the arm straight into the air as your partner prevents you from doing actually doing so.', 'After 10-20 seconds, relax the arm and allow your partner to further stretch the tricep by applying gentle pressure to the wrist. Hold for 10-20 seconds, and then switch sides.']::text[], ARRAY['Overhead_Triceps/0.jpg', 'Overhead_Triceps/1.jpg']::text[], 'overhead triceps gian tay sau qua dau estiramiento de triceps sobre la cabeza'),
  (NULL, 'Pallof Press', 'Pallof press', 'Pallof Press', 'Press Pallof', 'abs', 'cable', 'isolation', 'free_exercise_db', 'Pallof_Press', ARRAY['Connect a standard handle to a tower, and—if possible—position the cable to shoulder height. If not, a low pulley will suffice.', 'With your side to the cable, grab the handle with both hands and step away from the tower. You should be approximately arm''s length away from the pulley, with the tension of the weight on the cable.', 'With your feet positioned hip-width apart and knees slightly bent, hold the cable to the middle of your chest. This will be your starting position.', 'Press the cable away from your chest, fully extending both arms. You core should be tight and engaged.', 'Hold the repetition for several seconds before returning to the starting position.', 'At the conclusion of the set, repeat facing the other direction.']::text[], ARRAY['Pallof_Press/0.jpg', 'Pallof_Press/1.jpg']::text[], 'pallof press pallof press press pallof'),
  (NULL, 'Pallof Press With Rotation', 'Pallof press kèm xoay', 'Pallof Press With Rotation', 'Press Pallof con rotación', 'abs', 'cable', 'compound', 'free_exercise_db', 'Pallof_Press_With_Rotation', ARRAY['Connect a standard handle to a tower, and position the cable to shoulder height.', 'With your side to the cable, grab the handle with one hand and step away from the tower. You should be approximately arm''s length away from the pulley, with the tension of the weight on the cable. Align outstretched arm with cable.', 'With your feet positioned hip-width apart, pull the cable into your chest and grab the handle with your other hand. Both hands should be on the handle at this time.', 'Facing forward, press the cable away from your chest. You core should be tight and engaged.', 'Keeping your hips straight, twist your torso away from the pulley until you get a full quarter rotation.', 'Maintain your rigid stance and straight arms. Return to the neutral position in a slow and controlled manner. Your arms should be extended in front of you.', 'With the side tension still engaging your core, bring your hands to your chest and immediately press outward to a fully extended position. This constitutes one rep.', 'Repeat to failure.', 'Then, reposition and repeat the same series of movements on the opposite side.']::text[], ARRAY['Pallof_Press_With_Rotation/0.jpg', 'Pallof_Press_With_Rotation/1.jpg']::text[], 'pallof press with rotation pallof press kem xoay press pallof con rotacion'),
  (NULL, 'Palms-Down Dumbbell Wrist Curl Over A Bench', 'Palms-Down Dumbbell Wrist Curl Over A Bench', 'Palms-Down Dumbbell Wrist Curl Over A Bench', 'Curl de muñeca prono con mancuerna en banco', 'biceps', 'dumbbell', 'isolation', 'free_exercise_db', 'Palms-Down_Dumbbell_Wrist_Curl_Over_A_Bench', ARRAY['Start out by placing two dumbbells on one side of a flat bench.', 'Kneel down on both of your knees so that your body is facing the flat bench.', 'Use your arms to grab both of the dumbbells with a pronated grip (palms facing down) and bring them up so that your forearms are resting against the flat bench. Your wrists should be hanging over the edge.', 'Start out by curling your wrist upwards and exhaling.', 'Slowly lower your wrists back down to the starting position while inhaling.', 'Your forearms should be stationary as your wrist is the only movement needed to perform this exercise.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Palms-Down_Dumbbell_Wrist_Curl_Over_A_Bench/0.jpg', 'Palms-Down_Dumbbell_Wrist_Curl_Over_A_Bench/1.jpg']::text[], 'palms-down dumbbell wrist curl over a bench cuon co tay nam up ta don tren ghe curl de muneca prono con mancuerna en banco'),
  (NULL, 'Palms-Down Wrist Curl Over A Bench', 'Palms-Down Wrist Curl Over A Bench', 'Palms-Down Wrist Curl Over A Bench', 'Curl de muñeca prono en banco', 'biceps', 'barbell', 'isolation', 'free_exercise_db', 'Palms-Down_Wrist_Curl_Over_A_Bench', ARRAY['Start out by placing a barbell on one side of a flat bench.', 'Kneel down on both of your knees so that your body is facing the flat bench.', 'Use your arms to grab the barbell with a pronated grip (palms down) and bring them up so that your forearms are resting against the flat bench. Your wrists should be hanging over the edge.', 'Start out by curling your wrist upwards and exhaling.', 'Slowly lower your wrists back down to the starting position while inhaling.', 'Your forearms should be stationary as your wrist is the only movement needed to perform this exercise.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Palms-Down_Wrist_Curl_Over_A_Bench/0.jpg', 'Palms-Down_Wrist_Curl_Over_A_Bench/1.jpg']::text[], 'palms-down wrist curl over a bench cuon co tay nam up tren ghe curl de muneca prono en banco'),
  (NULL, 'Palms-Up Barbell Wrist Curl Over A Bench', 'Palms-Up Barbell Wrist Curl Over A Bench', 'Palms-Up Barbell Wrist Curl Over A Bench', 'Curl de muñeca supino con barra en banco', 'biceps', 'barbell', 'isolation', 'free_exercise_db', 'Palms-Up_Barbell_Wrist_Curl_Over_A_Bench', ARRAY['Start out by placing a barbell on one side of a flat bench.', 'Kneel down on both of your knees so that your body is facing the flat bench.', 'Use your arms to grab the barbell with a supinated grip (palms up) and bring them up so that your forearms are resting against the flat bench. Your wrists should be hanging over the edge.', 'Start out by curling your wrist upwards and exhaling.', 'Slowly lower your wrists back down to the starting position while inhaling.', 'Your forearms should be stationary as your wrist is the only movement needed to perform this exercise.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Palms-Up_Barbell_Wrist_Curl_Over_A_Bench/0.jpg', 'Palms-Up_Barbell_Wrist_Curl_Over_A_Bench/1.jpg']::text[], 'palms-up barbell wrist curl over a bench cuon co tay nam ngua ta don tren ghe curl de muneca supino con barra en banco'),
  (NULL, 'Palms-Up Dumbbell Wrist Curl Over A Bench', 'Palms-Up Dumbbell Wrist Curl Over A Bench', 'Palms-Up Dumbbell Wrist Curl Over A Bench', 'Curl de muñeca supino con mancuerna en banco', 'biceps', 'dumbbell', 'isolation', 'free_exercise_db', 'Palms-Up_Dumbbell_Wrist_Curl_Over_A_Bench', ARRAY['Start out by placing two dumbbells on one side of a flat bench.', 'Kneel down on both of your knees so that your body is facing the flat bench.', 'Use your arms to grab both of the dumbbells with a supinated grip (palms up) and bring them up so that your forearms are resting against the flat bench. Your wrists should be hanging over the edge.', 'Start out by curling your wrist upwards and exhaling.', 'Slowly lower your wrists back down to the starting position while inhaling. Make sure to inhale during this part of the exercise.', 'Your forearms should be stationary as your wrist is the only movement needed to perform this exercise.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Palms-Up_Dumbbell_Wrist_Curl_Over_A_Bench/0.jpg', 'Palms-Up_Dumbbell_Wrist_Curl_Over_A_Bench/1.jpg']::text[], 'palms-up dumbbell wrist curl over a bench cuon co tay nam ngua ta don tren ghe curl de muneca supino con mancuerna en banco'),
  (NULL, 'Parallel Bar Dip', 'Parallel Bar Dip', 'Parallel Bar Dip', 'Fondos en paralelas', 'triceps', 'other', 'compound', 'free_exercise_db', 'Parallel_Bar_Dip', ARRAY['Stand between a set of parallel bars. Place a hand on each bar, and then take a small jump to help you get into the starting position with your arms locked out.', 'Begin by flexing the elbow, lowering your body until your arms break 90 degrees. Avoid swinging, and maintain good posture throughout the descent.', 'Reverse the motion by extending the elbow, pushing yourself back up into the starting position.', 'Repeat for the desired number of repetitions.']::text[], ARRAY['Parallel_Bar_Dip/0.jpg', 'Parallel_Bar_Dip/1.jpg']::text[], 'parallel bar dip dips xa kep fondos en paralelas'),
  (NULL, 'Pelvic Tilt Into Bridge', 'Nghiêng chậu rồi nâng cầu', 'Pelvic Tilt Into Bridge', 'Inclinación pélvica a puente', 'back', 'other', 'timed', 'free_exercise_db', 'Pelvic_Tilt_Into_Bridge', ARRAY['Lie down with your feet on the floor, heels directly under your knees.', 'Lift only your tailbone to the ceiling to stretch your lower back. (Don''t lift the entire spine yet.) Pull in your stomach.', 'To go into a bridge, lift the entire spine except the neck.']::text[], ARRAY['Pelvic_Tilt_Into_Bridge/0.jpg', 'Pelvic_Tilt_Into_Bridge/1.jpg']::text[], 'pelvic tilt into bridge nghieng chau roi nang cau inclinacion pelvica a puente'),
  (NULL, 'Peroneals-SMR', 'Lăn giãn cơ mác', 'Peroneals-SMR', 'Liberación de peroneos', 'calves', 'foam roll', 'timed', 'free_exercise_db', 'Peroneals-SMR', ARRAY['Lay on your side, supporting your weight on your forearm and on a foam roller placed on the outside of your lower leg. Your upper leg can either be on top of your lower leg, or you can cross it in front of you. This will be your starting position.', 'Raise your hips off of the ground and begin to roll from below the knee to above the ankle on the side of your leg, pausing at points of tension for 10-30 seconds. Repeat on the other leg.']::text[], ARRAY['Peroneals-SMR/0.jpg', 'Peroneals-SMR/1.jpg']::text[], 'peroneals-smr lan gian co mac liberacion de peroneos'),
  (NULL, 'Peroneals Stretch', 'Giãn cơ mác', 'Peroneals Stretch', 'Estiramiento de peroneos', 'calves', 'other', 'timed', 'free_exercise_db', 'Peroneals_Stretch', ARRAY['In a seated position, loop a belt, rope, or band around one foot. This will be your starting position.', 'With the leg extended and the heel off of the ground, pull on the belt so that the foot is inverted, with the inside of the foot being pulled towards you. Hold for 10-20 seconds, and then switch sides.']::text[], ARRAY['Peroneals_Stretch/0.jpg', 'Peroneals_Stretch/1.jpg']::text[], 'peroneals stretch gian co mac estiramiento de peroneos'),
  (NULL, 'Physioball Hip Bridge', 'Cầu hông trên bóng tập', 'Physioball Hip Bridge', 'Puente de cadera en fitball', 'glutes', 'exercise ball', 'compound', 'free_exercise_db', 'Physioball_Hip_Bridge', ARRAY['Lay on a ball so that your upper back is on the ball with your hips unsupported. Both feet should be flat on the floor, hip width apart or wider. This will be your starting position.', 'Begin by extending the hips using your glutes and hamstrings, raising your hips upward as you bridge.', 'Pause at the top of the motion and return to the starting position.']::text[], ARRAY['Physioball_Hip_Bridge/0.jpg', 'Physioball_Hip_Bridge/1.jpg']::text[], 'physioball hip bridge cau hong tren bong tap puente de cadera en fitball'),
  (NULL, 'Pin Presses', 'Đẩy ngực từ giá đỡ', 'Pin Presses', 'Press desde soportes', 'triceps', 'barbell', 'compound', 'free_exercise_db', 'Pin_Presses', ARRAY['Pin presses remove the eccentric phase of the bench press, developing starting strength. They also allow you to train a desired range of motion.', 'The bench should be set up in a power rack. Set the pins to the desired point in your range of motion, whether it just be lockout or an inch off of your chest. The bar should be moved to the pins and prepared for lifting.', 'Begin by lying on the bench, with the bar directly above the contact point during your regular bench. Tuck your feet underneath you and arch your back. Using the bar to help support your weight, lift your shoulder off the bench and retract them, squeezing the shoulder blades together. Use your feet to drive your traps into the bench. Maintain this tight body position throughout the movement.', 'You can take a standard bench grip, or shoulder width to focus on the triceps. The bar, wrist, and elbow should stay in line at all times. Focus on squeezing the bar and trying to pull it apart.', 'Drive the bar up with as much force as possible. The elbows should be tucked in until lockout.', 'Return the bar to the pins, pausing before beginning the next repetition.']::text[], ARRAY['Pin_Presses/0.jpg', 'Pin_Presses/1.jpg']::text[], 'pin presses day nguc tu gia do press desde soportes'),
  (NULL, 'Piriformis-SMR', 'Lăn giãn cơ hình lê', 'Piriformis-SMR', 'Liberación del piriforme', 'glutes', 'foam roll', 'timed', 'free_exercise_db', 'Piriformis-SMR', ARRAY['Sit with your buttocks on top of a foam roll. Bend your knees, and then cross one leg so that the ankle is over the knee. This will be your starting position.', 'Shift your weight to the side of the crossed leg, rolling over the buttocks until you feel tension in your upper glute. You may assist the stretch by using one hand to pull the bent knee towards your chest. Hold this position for 10-30 seconds, and then switch sides.']::text[], ARRAY['Piriformis-SMR/0.jpg', 'Piriformis-SMR/1.jpg']::text[], 'piriformis-smr lan gian co hinh le liberacion del piriforme'),
  (NULL, 'Plank', 'Plank', 'Plank', 'Plancha', 'abs', 'bodyweight', 'bodyweight', 'free_exercise_db', 'Plank', ARRAY['Get into a prone position on the floor, supporting your weight on your toes and your forearms. Your arms are bent and directly below the shoulder.', 'Keep your body straight at all times, and hold this position as long as possible. To increase difficulty, an arm or leg can be raised.']::text[], ARRAY['Plank/0.jpg', 'Plank/1.jpg']::text[], 'plank plank plancha'),
  (NULL, 'Plate Pinch', 'Kẹp đĩa tạ', 'Plate Pinch', 'Pinza de discos', 'biceps', 'other', 'isolation', 'free_exercise_db', 'Plate_Pinch', ARRAY['Grab two wide-rimmed plates and put them together with the smooth sides facing outward', 'Use your fingers to grip the outside part of the plate and your thumb for the other side thus holding both plates together. This is the starting position.', 'Squeeze the plate with your fingers and thumb. Hold this position for as long as you can.', 'Repeat for the recommended amount of sets prescribed in your program.', 'Switch arms and repeat the movements.']::text[], ARRAY['Plate_Pinch/0.jpg', 'Plate_Pinch/1.jpg']::text[], 'plate pinch kep dia ta pinza de discos'),
  (NULL, 'Plate Twist', 'Xoay đĩa tạ', 'Plate Twist', 'Giro con disco', 'abs', 'other', 'compound', 'free_exercise_db', 'Plate_Twist', ARRAY['Lie down on the floor or an exercise mat with your legs fully extended and your upper body upright. Grab the plate by its sides with both hands out in front of your abdominals with your arms slightly bent.', 'Slowly cross your legs near your ankles and lift them up off the ground. Your knees should also be bent slightly. Note: Move your upper body back slightly to help keep you balanced turning this exercise. This is the starting position.', 'Move the plate to the left side and touch the floor with it. Breathe out as you perform that movement.', 'Come back to the starting position as you breathe in and then repeat the movement but this time to the right side of the body. Tip: Use a slow controlled movement at all times. Jerking motions can injure the back.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Plate_Twist/0.jpg', 'Plate_Twist/1.jpg']::text[], 'plate twist xoay dia ta giro con disco'),
  (NULL, 'Platform Hamstring Slides', 'Trượt đùi sau trên bục', 'Platform Hamstring Slides', 'Deslizamientos de isquios en plataforma', 'legs', 'other', 'isolation', 'free_exercise_db', 'Platform_Hamstring_Slides', ARRAY['For this movement a wooden floor or similar is needed. Lay on your back with your legs extended. Place a gym towel or a light weight underneath your heel. This will be your starting position.', 'Begin the movement by flexing the knee, keeping your other leg straight.', 'Continue bringing the heel closer to you, sliding it on the floor.', 'At full knee flexion, reverse the movement to return to the starting position.']::text[], ARRAY['Platform_Hamstring_Slides/0.jpg', 'Platform_Hamstring_Slides/1.jpg']::text[], 'platform hamstring slides truot dui sau tren buc deslizamientos de isquios en plataforma'),
  (NULL, 'Plie Dumbbell Squat', 'Plie Dumbbell Squat', 'Plie Dumbbell Squat', 'Sentadilla plié con mancuerna', 'legs', 'dumbbell', 'compound', 'free_exercise_db', 'Plie_Dumbbell_Squat', ARRAY['Hold a dumbbell at the base with both hands and stand straight up. Move your legs so that they are wider than shoulder width apart from each other with your knees slightly bent.', 'Your toes should be facing out. Note: Your arms should be stationary while performing the exercise. This is the starting position.', 'Slowly bend the knees and lower your legs until your thighs are parallel to the floor. Make sure to inhale as this is the eccentric part of the exercise.', 'Press mainly with the heel of the foot to bring the body back to the starting position while exhaling.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Plie_Dumbbell_Squat/0.jpg', 'Plie_Dumbbell_Squat/1.jpg']::text[], 'plie dumbbell squat squat plie ta don sentadilla plie con mancuerna'),
  (NULL, 'Plyo Kettlebell Pushups', 'Hít đất bật trên kettlebell', 'Plyo Kettlebell Pushups', 'Flexiones pliométricas con pesas rusas', 'chest', 'kettlebell', 'compound', 'free_exercise_db', 'Plyo_Kettlebell_Pushups', ARRAY['Place a kettlebell on the floor. Place yourself in a pushup position, on your toes with one hand on the ground and one hand holding the kettlebell, with your elbows extended. This will be your starting position.', 'Begin by lowering yourself as low as you can, keeping your back straight.', 'Quickly and forcefully reverse direction, pushing yourself up to the other side of the kettlebell, switching hands as you do so. Continue the movement by descending and repeating the movement back and forth.']::text[], ARRAY['Plyo_Kettlebell_Pushups/0.jpg', 'Plyo_Kettlebell_Pushups/1.jpg']::text[], 'plyo kettlebell pushups hit dat bat tren kettlebell flexiones pliometricas con pesas rusas'),
  (NULL, 'Plyo Push-up', 'Hít đất bật', 'Plyo Push-up', 'Flexión pliométrica', 'chest', 'bodyweight', 'bodyweight', 'free_exercise_db', 'Plyo_Push-up', ARRAY['Move into a prone position on the floor, supporting your weight on your hands and toes.', 'Your arms should be fully extended with the hands around shoulder width. Keep your body straight throughout the movement. This will be your starting position.', 'Descend by flexing at the elbow, lowering your chest towards the ground.', 'At the bottom, reverse the motion by pushing yourself up through elbow extension as quickly as possible. Attempt to push your upper body up until your hands leave the ground.', 'Return to the starting position and repeat the exercise.', 'For added difficulty, add claps into the movement while you are air borne.']::text[], ARRAY['Plyo_Push-up/0.jpg', 'Plyo_Push-up/1.jpg']::text[], 'plyo push-up hit dat bat flexion pliometrica'),
  (NULL, 'Posterior Tibialis Stretch', 'Giãn cơ chày sau', 'Posterior Tibialis Stretch', 'Estiramiento del tibial posterior', 'calves', 'other', 'timed', 'free_exercise_db', 'Posterior_Tibialis_Stretch', ARRAY['In a seated position, loop a belt, rope, or band around one foot. This will be your starting position.', 'With the leg extended and the heel off of the ground, pull on the belt so that the foot is everted, with the outside of the foot being pulled towards you. Hold for 10-20 seconds, and then switch sides.']::text[], ARRAY['Posterior_Tibialis_Stretch/0.jpg', 'Posterior_Tibialis_Stretch/1.jpg']::text[], 'posterior tibialis stretch gian co chay sau estiramiento del tibial posterior'),
  (NULL, 'Power Clean', 'Power Clean', 'Power Clean', 'Cargada de potencia', 'legs', 'barbell', 'compound', 'free_exercise_db', 'Power_Clean', ARRAY['Stand with your feet slightly wider than shoulder width apart and toes pointing out slightly.', 'Squat down and grasp bar with a closed, pronated grip. Your hands should be slightly wider than shoulder width apart outside knees with elbows fully extended.', 'Place the bar about 1 inch in front of your shins and over the balls of your feet.', 'Your back should be flat or slightly arched, your chest held up and out and your shoulder blades should be retracted.', 'Keep your head in a neutral position (in line with vertebral column and not tilted or rotated) with your eyes focused straight ahead. Inhale during this phase.', 'Lift the bar from the floor by forcefully extending the hips and the knees as you exhale. Tip: The upper torso should maintain the same angle. Do not bend at the waist yet and do not let the hips rise before the shoulders (this would have the effect of pushing the glutes in the air and stretching the hamstrings.', 'Keep elbows fully extended with the head in a neutral position and the shoulders over the bar.', 'As the bar raises keep it as close to the shins as possible.', 'As the bar passes the knees, thrust your hips forward and slightly bend the knees to avoid locking them. Tip: At this point your thighs should be against the bar.', 'Keep the back flat or slightly arched, elbows fully extended and your head neutral. Tip: You will hold your breath until the next phase.', 'Inhale and then forcefully and quickly extend your hips and knees and stand on your toes.', 'Keep the bar as close to your body as possible. Tip: Your back should be flat with the elbows pointed out to the sides and your head in a neutral position. Also, keep your shoulders over the bar and arms straight as long as possible.', 'When your lower body joints are fully extended, shrug the shoulders upward rapidly without letting the elbows flex yet. Exhale during this portion of the movement.', 'As the shoulders reach their highest elevation flex your elbows to begin pulling your body under the bar.', 'Continue to pull the arms as high and as long as possible. Tip: Due to the explosive nature of this phase, your torso will be erect or with an arched back, your head will be tilted back slightly and your feet may lose contact with the floor.', 'After the lower body has fully extended and the bar reaches near maximal height, pull your body under the bar and rotate the arms around and under the bar.', 'Simultaneously, flex the hips and knees into a quarter squat position.', 'Once the arms are under the bar, inhale and then lift your elbows to position the upper arms parallel to the floor. Rack the bar across the front of your collar bones and front shoulder muscles.', 'Catch the bar with an erect and tight torso, a neutral head position and flat feet. Exhale during this movement.', 'Stand up by extending the hips and knees to a fully erect position.', 'Lower the bar by gradually reducing the muscular tension of the arms to allow a controlled descent of the bar to the thighs. Inhale during this movement.', 'Simultaneously flex the hips and knees to cushion the impact of the bar on the thighs.', 'Squat down with the elbows fully extended until the bar touches the floor.', 'Start over at Phase 1 and repeat for the recommended amount of repetitions.']::text[], ARRAY['Power_Clean/0.jpg', 'Power_Clean/1.jpg']::text[], 'power clean power clean cargada de potencia'),
  (NULL, 'Power Clean from Blocks', 'Power Clean from Blocks', 'Power Clean from Blocks', 'Cargada de potencia desde bloques', 'legs', 'barbell', 'compound', 'free_exercise_db', 'Power_Clean_from_Blocks', ARRAY['With a barbell on boxes of the desired height, take a grip just outside the legs. Lower your hips with the weight focused on the heels, back straight, head facing forward, chest up, with your shoulders just in front of the bar. This will be your starting position.', 'Begin the first pull by driving through the heels, extending your knees. Your back angle should stay the same, and your arms should remain straight. As the bar approaches the mid-thigh position, begin extending through the hips.', 'In a jumping motion, accelerate by extending the hips, knees, and ankles, using speed to move the bar upward. There should be no need to actively pull through the arms to accelerate the weight. At the end of the second pull, the body should be fully extended, leaning slightly back, with the arms still extended.', 'As full extension is achieved, transition into the third pull by aggressively shrugging and flexing the arms with the elbows up and out. At peak extension, pull yourself under the bar far enough that it can be racked onto the shoulders, rotating your elbows under the bar as you do so. The bar should be racked onto the protracted shoulders, lightly touching the throat with the hands relaxed.', 'Immediately recover by driving through the heels, keeping the torso upright and elbows up. Continue until you have risen to a standing position, and complete the repetition by returning the weight to the boxes.']::text[], ARRAY['Power_Clean_from_Blocks/0.jpg', 'Power_Clean_from_Blocks/1.jpg']::text[], 'power clean from blocks power clean tu buc cargada de potencia desde bloques'),
  (NULL, 'Power Jerk', 'Power Jerk', 'Power Jerk', 'Envión de potencia', 'legs', 'barbell', 'compound', 'free_exercise_db', 'Power_Jerk', ARRAY['Standing with the weight racked on the front of the shoulders, begin with the dip. With your feet directly under your hips, flex the knees without moving the hips backward. Go down only slightly, and reverse direction as powerfully as possible.', 'Drive through the heels create as much speed and force as possible, and be sure to move your head out of the way as the bar leaves the shoulders.', 'At this moment as the feet leave the floor, the feet must be placed into the receiving position as quickly as possible. In the brief moment the feet are not actively driving against the platform, the athletes effort to push the bar up will drive them down. The feet should be moved to a slightly wider stance, with the knees partially bent.', 'Receive the bar with the arms locked out overhead.', 'Return to a standing position.']::text[], ARRAY['Power_Jerk/0.jpg', 'Power_Jerk/1.jpg']::text[], 'power jerk power jerk envion de potencia'),
  (NULL, 'Power Partials', 'Biên độ ngắn mạnh với tạ đơn', 'Power Partials', 'Parciales de potencia', 'shoulders', 'dumbbell', 'isolation', 'free_exercise_db', 'Power_Partials', ARRAY['Stand up with your torso upright and a dumbbell on each hand being held at arms length. The elbows should be close to the torso.', 'The palms of the hands should be facing your torso. Your feet should be about shoulder width apart. This will be your starting position.', 'Keeping your arms straight and the torso stationary, lift the weights out to your sides until they are about shoulder level height while exhaling.', 'Feel the contraction for a second and begin to lower the weights back down to the starting position while inhaling. Tip: Keep the palms facing down with the little finger slightly higher while lifting and lowering the weights as it will concentrate the stress on your shoulders mainly.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Power_Partials/0.jpg', 'Power_Partials/1.jpg']::text[], 'power partials bien do ngan manh voi ta don parciales de potencia'),
  (NULL, 'Power Snatch', 'Power Snatch', 'Power Snatch', 'Arrancada de potencia', 'legs', 'barbell', 'compound', 'free_exercise_db', 'Power_Snatch', ARRAY['Begin with a loaded barbell on the floor. The bar should be close to or touching the shins, and a wide grip should be taken on the bar. The feet should be directly below the hips, with the feet turned out as needed. Lower the hips, with the chest up and the head looking forward. The shoulders should be just in front of the bar. This will be the starting position.', 'Begin the first pull by driving through the front of the heels, raising the bar from the ground. The back angle should stay the same until the bar passes the knees.', 'Transition into the second pull by extending through the hips knees and ankles, driving the bar up as quickly as possible. The bar should be close to the body. At peak extension, shrug the shoulders and allow the elbows to flex to the side.', 'As you move your feet into the receiving position, a slightly wider position, pull yourself below the bar as you elevate the bar overhead. The bar should be received in a partial squat. Continue raising the bar to the overhead position, receiving the bar locked out overhead.', 'Return to a standing position with the weight over head.']::text[], ARRAY['Power_Snatch/0.jpg', 'Power_Snatch/1.jpg']::text[], 'power snatch power snatch arrancada de potencia'),
  (NULL, 'Power Snatch from Blocks', 'Power Snatch from Blocks', 'Power Snatch from Blocks', 'Arrancada de potencia desde bloques', 'legs', 'barbell', 'compound', 'free_exercise_db', 'Power_Snatch_from_Blocks', ARRAY['Begin with a loaded barbell on boxes or stands of the desired height. A wide grip should be taken on the bar. The feet should be directly below the hips, with the feet turned out as needed. Lower the hips, with the chest up and the head looking forward. The shoulders should be just in front of the bar, with the elbows pointed out. This will be the starting position.', 'Begin the first pull by driving through the front of the heels, raising the bar from the boxes.', 'Transition into the second pull by extending through the hips knees and ankles, driving the bar up as quickly as possible. The bar should be close to the body. At peak extension, shrug the shoulders and allow the elbows to flex to the side.', 'As you move your feet into the receiving position, forcefully pull yourself below the bar as you elevate the bar overhead. The feet should move to just outside the hips, turned out as necessary. Receive the bar above a full squat and with the arms fully extended overhead.', 'Keeping the bar aligned over the front of the heels, your head and chest up, drive through heels of the feet to move to a standing position. Carefully return the weight to the boxes.']::text[], ARRAY['Power_Snatch_from_Blocks/0.jpg', 'Power_Snatch_from_Blocks/1.jpg']::text[], 'power snatch from blocks power snatch tu buc arrancada de potencia desde bloques'),
  (NULL, 'Power Stairs', 'Leo cầu thang tạ', 'Power Stairs', 'Escaleras de potencia', 'legs', 'other', 'compound', 'free_exercise_db', 'Power_Stairs', ARRAY['In the power stairs, implements are moved up a staircase. For training purposes, these can be performed with a tire or box.', 'Begin by taking the implement with both hands. Set your feet wide, with your head and chest up. Drive through the ground with your heels, extending your knees and hips to raise the weight from the ground.', 'As you lean back, attempt to swing the weight onto the stairs, which are usually around 16-18" high. You can use your legs to help push the weight onto the stair.', 'Repeat for 3-5 repetitions, and continue with a heavier weight, moving as fast as possible.']::text[], ARRAY['Power_Stairs/0.jpg', 'Power_Stairs/1.jpg']::text[], 'power stairs leo cau thang ta escaleras de potencia'),
  (NULL, 'Preacher Curl', 'Preacher Curl', 'Preacher Curl', 'Curl predicador', 'biceps', 'barbell', 'isolation', 'free_exercise_db', 'Preacher_Curl', ARRAY['To perform this movement you will need a preacher bench and an E-Z bar. Grab the E-Z curl bar at the close inner handle (either have someone hand you the bar which is preferable or grab the bar from the front bar rest provided by most preacher benches). The palm of your hands should be facing forward and they should be slightly tilted inwards due to the shape of the bar.', 'With the upper arms positioned against the preacher bench pad and the chest against it, hold the E-Z Curl Bar at shoulder length. This will be your starting position.', 'As you breathe in, slowly lower the bar until your upper arm is extended and the biceps is fully stretched.', 'As you exhale, use the biceps to curl the weight up until your biceps is fully contracted and the bar is at shoulder height. Squeeze the biceps hard and hold this position for a second.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Preacher_Curl/0.jpg', 'Preacher_Curl/1.jpg']::text[], 'preacher curl cuon tay truoc ghe doc curl predicador'),
  (NULL, 'Preacher Hammer Dumbbell Curl', 'Preacher Hammer Dumbbell Curl', 'Preacher Hammer Dumbbell Curl', 'Curl martillo predicador con mancuerna', 'biceps', 'dumbbell', 'isolation', 'free_exercise_db', 'Preacher_Hammer_Dumbbell_Curl', ARRAY['Place the upper part of both arms on top of the preacher bench as you hold a dumbbell in each hand with the palms facing each other (neutral grip).', 'As you breathe in, slowly lower the dumbbells until your upper arm is extended and the biceps is fully stretched.', 'As you exhale, use the biceps to curl the weight up until your biceps is fully contracted and the dumbbells are at shoulder height.', 'Squeeze the biceps hard for a second at the contracted position and repeat for the recommended amount of repetitions.']::text[], ARRAY['Preacher_Hammer_Dumbbell_Curl/0.jpg', 'Preacher_Hammer_Dumbbell_Curl/1.jpg']::text[], 'preacher hammer dumbbell curl cuon bua ta don ghe doc curl martillo predicador con mancuerna'),
  (NULL, 'Press Sit-Up', 'Gập bụng kèm đẩy tạ', 'Press Sit-Up', 'Abdominal con press', 'abs', 'barbell', 'compound', 'free_exercise_db', 'Press_Sit-Up', ARRAY['To begin, lie down on a bench with a barbell resting on your chest. Position your legs so they are secure on the extension of the abdominal bench. This is the starting position.', 'While inhaling, tighten your abdominals and glutes. Simultaneously curl your torso as you do when performing a sit-up and press the barbell to an overhead position while exhaling. Tip: Use your arms to push the barbell out as you perform this exercise while still focusing on the abdominal muscles.', 'Lower your upper body back down to the starting position while bringing the barbell back down to your torso. Remember to breathe in while lowering the body.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Press_Sit-Up/0.jpg', 'Press_Sit-Up/1.jpg']::text[], 'press sit-up gap bung kem day ta abdominal con press'),
  (NULL, 'Prone Manual Hamstring', 'Giãn đùi sau nằm sấp có hỗ trợ', 'Prone Manual Hamstring', 'Estiramiento manual de isquios boca abajo', 'legs', 'other', 'bodyweight', 'free_exercise_db', 'Prone_Manual_Hamstring', ARRAY['You will need a partner for this exercise. Lay face down with your legs straight. Your assistant will place their hand on your heel.', 'To begin, flex the knee to curl your leg up. Your partner should provide resistance, starting light and increasing the pressure as the movement is completed. Communicate with your partner to monitor appropriate resistance levels.', 'Pause at the top, returning the leg to the starting position as your partner provides resistance going the other direction.']::text[], ARRAY['Prone_Manual_Hamstring/0.jpg', 'Prone_Manual_Hamstring/1.jpg']::text[], 'prone manual hamstring gian dui sau nam sap co ho tro estiramiento manual de isquios boca abajo'),
  (NULL, 'Prowler Sprint', 'Chạy đẩy xe prowler', 'Prowler Sprint', 'Sprint con trineo prowler', 'cardio', 'other', 'compound', 'free_exercise_db', 'Prowler_Sprint', ARRAY['Place your sled on an appropriate surface, loaded to a suitable weight. The sled should provide enough resistance to require effort, but not so heavy that you are significantly slowed down.', 'You may use the upright or the low handles for this exercise. Place your hands on the handles with your arms extended, leaning into the implement.', 'With good posture, drive through the ground with alternating, short steps. Move as fast as you can for a short distance.']::text[], ARRAY['Prowler_Sprint/0.jpg', 'Prowler_Sprint/1.jpg']::text[], 'prowler sprint chay day xe prowler sprint con trineo prowler'),
  (NULL, 'Pull Through', 'Kéo cáp qua chân', 'Pull Through', 'Pull through en polea', 'glutes', 'cable', 'compound', 'free_exercise_db', 'Pull_Through', ARRAY['Begin standing a few feet in front of a low pulley with a rope or handle attached. Face away from the machine, straddling the cable, with your feet set wide apart.', 'Begin the movement by reaching through your legs as far as possible, bending at the hips. Keep your knees slightly bent. Keeping your arms straight, extend through the hip to stand straight up. Avoid pulling upward through the shoulders; all of the motion should originate through the hips.']::text[], ARRAY['Pull_Through/0.jpg', 'Pull_Through/1.jpg']::text[], 'pull through keo cap qua chan pull through en polea'),
  (NULL, 'Pullups', 'Hít xà', 'Pullups', 'Dominadas', 'back', 'bodyweight', 'bodyweight', 'free_exercise_db', 'Pullups', ARRAY['Grab the pull-up bar with the palms facing forward using the prescribed grip. Note on grips: For a wide grip, your hands need to be spaced out at a distance wider than your shoulder width. For a medium grip, your hands need to be spaced out at a distance equal to your shoulder width and for a close grip at a distance smaller than your shoulder width.', 'As you have both arms extended in front of you holding the bar at the chosen grip width, bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.', 'Pull your torso up until the bar touches your upper chest by drawing the shoulders and the upper arms down and back. Exhale as you perform this portion of the movement. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary as it moves through space and only the arms should move. The forearms should do no other work other than hold the bar.', 'After a second on the contracted position, start to inhale and slowly lower your torso back to the starting position when your arms are fully extended and the lats are fully stretched.', 'Repeat this motion for the prescribed amount of repetitions.']::text[], ARRAY['Pullups/0.jpg', 'Pullups/1.jpg']::text[], 'pullups hit xa dominadas'),
  (NULL, 'Push-Up Wide', 'Hít đất nắm rộng', 'Push-Up Wide', 'Flexiones agarre ancho', 'chest', 'bodyweight', 'bodyweight', 'free_exercise_db', 'Push-Up_Wide', ARRAY['With your hands wide apart, support your body on your toes and hands in a plank position. Your elbows should be extended and your body straight. Do not allow your hips to sag. This will be your starting position.', 'To begin, allow the elbows to flex, lowering your chest to the floor as you inhale.', 'Using your pectoral muscles, press your upper body back up to the starting position by extending the elbows. Exhale as you perform this step.', 'After pausing at the contracted position, repeat the movement for the prescribed amount of repetitions.']::text[], ARRAY['Push-Up_Wide/0.jpg', 'Push-Up_Wide/1.jpg']::text[], 'push-up wide hit dat nam rong flexiones agarre ancho'),
  (NULL, 'Push-Ups - Close Triceps Position', 'Hít đất khép tay (tay sau)', 'Push-Ups - Close Triceps Position', 'Flexiones cerradas para tríceps', 'triceps', 'bodyweight', 'bodyweight', 'free_exercise_db', 'Push-Ups_-_Close_Triceps_Position', ARRAY['Lie on the floor face down and place your hands closer than shoulder width for a close hand position. Make sure that you are holding your torso up at arms'' length.', 'Lower yourself until your chest almost touches the floor as you inhale.', 'Using your triceps and some of your pectoral muscles, press your upper body back up to the starting position and squeeze your chest. Breathe out as you perform this step.', 'After a second pause at the contracted position, repeat the movement for the prescribed amount of repetitions.']::text[], ARRAY['Push-Ups_-_Close_Triceps_Position/0.jpg', 'Push-Ups_-_Close_Triceps_Position/1.jpg']::text[], 'push-ups - close triceps position hit dat khep tay (tay sau) flexiones cerradas para triceps'),
  (NULL, 'Push-Ups With Feet Elevated', 'Hít đất kê chân cao', 'Push-Ups With Feet Elevated', 'Flexiones con pies elevados', 'chest', 'bodyweight', 'bodyweight', 'free_exercise_db', 'Push-Ups_With_Feet_Elevated', ARRAY['Lie on the floor face down and place your hands about 36 inches apart from each other holding your torso up at arms length.', 'Place your toes on top of a flat bench. This will allow your body to be elevated. Note: The higher the elevation of the flat bench, the higher the resistance of the exercise is.', 'Lower yourself until your chest almost touches the floor as you inhale.', 'Using your pectoral muscles, press your upper body back up to the starting position and squeeze your chest. Breathe out as you perform this step.', 'After a second pause at the contracted position, repeat the movement for the prescribed amount of repetitions.']::text[], ARRAY['Push-Ups_With_Feet_Elevated/0.jpg', 'Push-Ups_With_Feet_Elevated/1.jpg']::text[], 'push-ups with feet elevated hit dat ke chan cao flexiones con pies elevados'),
  (NULL, 'Push-Ups With Feet On An Exercise Ball', 'Hít đất chân trên bóng tập', 'Push-Ups With Feet On An Exercise Ball', 'Flexiones con pies en fitball', 'chest', 'exercise ball', 'compound', 'free_exercise_db', 'Push-Ups_With_Feet_On_An_Exercise_Ball', ARRAY['Lie on the floor face down and place your hands about 36 inches apart from each other holding your torso up at arms length.', 'Place your toes on top of an exercise ball. This will allow your body to be elevated.', 'Lower yourself until your chest almost touches the floor as you inhale.', 'Using your pectoral muscles, press your upper body back up to the starting position and squeeze your chest. Breathe out as you perform this step.', 'After a second pause at the contracted position, repeat the movement for the prescribed amount of repetitions.']::text[], ARRAY['Push-Ups_With_Feet_On_An_Exercise_Ball/0.jpg', 'Push-Ups_With_Feet_On_An_Exercise_Ball/1.jpg']::text[], 'push-ups with feet on an exercise ball hit dat chan tren bong tap flexiones con pies en fitball'),
  (NULL, 'Push Press', 'Push Press', 'Push Press', 'Push press', 'shoulders', 'barbell', 'compound', 'free_exercise_db', 'Push_Press', ARRAY[]::text[], ARRAY['Push_Press/0.jpg', 'Push_Press/1.jpg']::text[], 'push press push press push press'),
  (NULL, 'Push Press - Behind the Neck', 'Push Press - Behind the Neck', 'Push Press - Behind the Neck', 'Push press tras nuca', 'shoulders', 'barbell', 'compound', 'free_exercise_db', 'Push_Press_-_Behind_the_Neck', ARRAY['Standing with the weight racked on the back of the shoulders, begin with the dip. With your feet directly under your hips, flex the knees without moving the hips backward. Go down only slightly, and reverse direction as powerfully as possible. Drive through the heels create as much speed and force as possible, moving the bar in a vertical path.', 'Using the momentum generated, finish pressing the weight overhead be extending through the arms.', 'Return to the starting position, using your legs to absorb the impact.']::text[], ARRAY['Push_Press_-_Behind_the_Neck/0.jpg', 'Push_Press_-_Behind_the_Neck/1.jpg']::text[], 'push press - behind the neck push press sau gay push press tras nuca'),
  (NULL, 'Push Up to Side Plank', 'Push Up to Side Plank', 'Push Up to Side Plank', 'Flexión a plancha lateral', 'chest', 'bodyweight', 'bodyweight', 'free_exercise_db', 'Push_Up_to_Side_Plank', ARRAY['Get into pushup position on the toes with your hands just outside of shoulder width.', 'Perform a pushup by allowing the elbows to flex. As you descend, keep your body straight.', 'Do one pushup and as you come up, shift your weight on the left side of the body, twist to the side while bringing the right arm up towards the ceiling in a side plank.', 'Lower the arm back to the floor for another pushup and then twist to the other side.', 'Repeat the series, alternating each side, for 10 or more reps.']::text[], ARRAY['Push_Up_to_Side_Plank/0.jpg', 'Push_Up_to_Side_Plank/1.jpg']::text[], 'push up to side plank hit dat chuyen plank nghieng flexion a plancha lateral'),
  (NULL, 'Pushups', 'Hít đất', 'Pushups', 'Flexiones', 'chest', 'bodyweight', 'bodyweight', 'free_exercise_db', 'Pushups', ARRAY['Lie on the floor face down and place your hands about 36 inches apart while holding your torso up at arms length.', 'Next, lower yourself downward until your chest almost touches the floor as you inhale.', 'Now breathe out and press your upper body back up to the starting position while squeezing your chest.', 'After a brief pause at the top contracted position, you can begin to lower yourself downward again for as many repetitions as needed.']::text[], ARRAY['Pushups/0.jpg', 'Pushups/1.jpg']::text[], 'pushups hit dat flexiones'),
  (NULL, 'Pushups (Close and Wide Hand Positions)', 'Hít đất (tay hẹp và rộng)', 'Pushups (Close and Wide Hand Positions)', 'Flexiones (manos cerradas y abiertas)', 'chest', 'bodyweight', 'bodyweight', 'free_exercise_db', 'Pushups_Close_and_Wide_Hand_Positions', ARRAY['Lie on the floor face down and body straight with your toes on the floor and the hands wider than shoulder width for a wide hand position and closer than shoulder width for a close hand position. Make sure you are holding your torso up at arms length.', 'Lower yourself until your chest almost touches the floor as you inhale.', 'Using your pectoral muscles, press your upper body back up to the starting position and squeeze your chest. Breathe out as you perform this step.', 'After a second pause at the contracted position, repeat the movement for the prescribed amount of repetitions.']::text[], ARRAY['Pushups_Close_and_Wide_Hand_Positions/0.jpg', 'Pushups_Close_and_Wide_Hand_Positions/1.jpg']::text[], 'pushups (close and wide hand positions) hit dat (tay hep va rong) flexiones (manos cerradas y abiertas)'),
  (NULL, 'Pyramid', 'Kim tự tháp trên bóng tập', 'Pyramid', 'Pirámide en fitball', 'back', 'exercise ball', 'timed', 'free_exercise_db', 'Pyramid', ARRAY['Start off by rolling your torso forward onto the ball so your hips rest on top of the ball and become the highest point of your body.', 'Rest your hands and feet on the floor. Your arms and legs can be slightly bent or straight, depending on the size of the ball, your flexibility, and the length of your limbs. This also helps develop stabilizing strength in your torso and shoulders.']::text[], ARRAY['Pyramid/0.jpg', 'Pyramid/1.jpg']::text[], 'pyramid kim tu thap tren bong tap piramide en fitball'),
  (NULL, 'Quad Stretch', 'Giãn đùi trước', 'Quad Stretch', 'Estiramiento de cuádriceps', 'legs', 'other', 'timed', 'free_exercise_db', 'Quad_Stretch', ARRAY['Lay on your side. Loop a belt, rope, or band around your top foot. Flex the knee and extend your hip, attempting to touch your glutes with your foot, and holding the belt with your hands. This will be your starting position.', 'With the belt being held over the shoulder or overhead, gently pull to increase the stretch in the quadriceps. Hold for 10-20 seconds, and then switch sides.']::text[], ARRAY['Quad_Stretch/0.jpg', 'Quad_Stretch/1.jpg']::text[], 'quad stretch gian dui truoc estiramiento de cuadriceps'),
  (NULL, 'Quadriceps-SMR', 'Lăn giãn đùi trước', 'Quadriceps-SMR', 'Liberación de cuádriceps', 'legs', 'foam roll', 'timed', 'free_exercise_db', 'Quadriceps-SMR', ARRAY['Lay facedown on the floor with your weight supported by your hands or forearms. Place a foam roll underneath one leg on the quadriceps, and keep the foot off of the ground. Make sure to relax the leg as much as possible. This will be your starting position.', 'Shifting as much weight onto the leg to be stretched as is tolerable, roll over the foam from above the knee to below the hip, holding points of tension for 10-30 seconds. Switch sides.']::text[], ARRAY['Quadriceps-SMR/0.jpg', 'Quadriceps-SMR/1.jpg']::text[], 'quadriceps-smr lan gian dui truoc liberacion de cuadriceps'),
  (NULL, 'Quick Leap', 'Bật nhanh', 'Quick Leap', 'Salto rápido', 'legs', 'other', 'compound', 'free_exercise_db', 'Quick_Leap', ARRAY['You will need a box for this exerise.', 'Begin facing the box standing 1-2 feet from its edge.', 'By utilizing your hips, hop onto the box, landing on both legs. Ensure that you land with your legs bent and your feet flat.', 'Immediately upon landing, fully extend through the entire body and swing your arms overhead to explode off of the box. Use your legs to absorb the impact of landing.']::text[], ARRAY['Quick_Leap/0.jpg', 'Quick_Leap/1.jpg']::text[], 'quick leap bat nhanh salto rapido'),
  (NULL, 'Rack Delivery', 'Đỡ tạ lên giá', 'Rack Delivery', 'Entrega al rack', 'shoulders', 'barbell', 'compound', 'free_exercise_db', 'Rack_Delivery', ARRAY['This drill teaches the delivery of the barbell to the rack position on the shoulders. Begin holding a bar in the scarecrow position, with the upper arms parallel to the floor, and the forearms hanging down. Use a hook grip, with your fingers wrapped over your thumbs.', 'Begin by rotating the elbows around the bar, delivering the bar to the shoulders. As your elbows come forward, relax your grip. The shoulders should be protracted, providing a shelf for the bar, which should lightly contact the throat.', 'It is important that the bar stay close to the body at all times, as with a heavier load any distance will result in an unwanted collision. As the movement becomes smoother, speed and load can be increased before progressing further.']::text[], ARRAY['Rack_Delivery/0.jpg', 'Rack_Delivery/1.jpg']::text[], 'rack delivery do ta len gia entrega al rack'),
  (NULL, 'Rack Pull with Bands', 'Rack pull dây kháng lực', 'Rack Pull with Bands', 'Rack pull con bandas', 'back', 'barbell', 'compound', 'free_exercise_db', 'Rack_Pull_with_Bands', ARRAY['Set up in a power rack with the bar on the pins. The pins should be set to the desired point; just below the knees, just above, or in the mid thigh position. Attach bands to the base of the rack, or secure them with dumbbells. Attach the other end to the bar. You may need to choke the bands to provide tension.', 'Position yourself against the bar in proper deadlifting position. Your feet should be under your hips, your grip shoulder width, back arched, and hips back to engage the hamstrings. Since the weight is typically heavy, you may use a mixed grip, a hook grip, or use straps to aid in holding the weight.', 'With your head looking forward, extend through the hips and knees, pulling the weight up and back until lockout. Be sure to pull your shoulders back as you complete the movement. Return the weight to the pins and repeat.']::text[], ARRAY['Rack_Pull_with_Bands/0.jpg', 'Rack_Pull_with_Bands/1.jpg']::text[], 'rack pull with bands rack pull day khang luc rack pull con bandas'),
  (NULL, 'Rack Pulls', 'Rack pull', 'Rack Pulls', 'Rack pull', 'back', 'barbell', 'compound', 'free_exercise_db', 'Rack_Pulls', ARRAY['Set up in a power rack with the bar on the pins. The pins should be set to the desired point; just below the knees, just above, or in the mid thigh position. Position yourself against the bar in proper deadlifting position. Your feet should be under your hips, your grip shoulder width, back arched, and hips back to engage the hamstrings. Since the weight is typically heavy, you may use a mixed grip, a hook grip, or use straps to aid in holding the weight.', 'With your head looking forward, extend through the hips and knees, pulling the weight up and back until lockout. Be sure to pull your shoulders back as you complete the movement.', 'Return the weight to the pins and repeat.']::text[], ARRAY['Rack_Pulls/0.jpg', 'Rack_Pulls/1.jpg']::text[], 'rack pulls rack pull rack pull'),
  (NULL, 'Rear Leg Raises', 'Nâng chân ra sau', 'Rear Leg Raises', 'Elevaciones de pierna hacia atrás', 'legs', 'bodyweight', 'timed', 'free_exercise_db', 'Rear_Leg_Raises', ARRAY['Place yourself on your hands knees on an exercise mat. Your head should be looking forward and the bend of the knees should create a 90-degree angle between the hamstrings and the calves. This will be your starting position.', 'Extend one leg up and behind you. The knee and hip should both extend. Repeat for 5-10 repetitions, and then switch sides.']::text[], ARRAY['Rear_Leg_Raises/0.jpg', 'Rear_Leg_Raises/1.jpg']::text[], 'rear leg raises nang chan ra sau elevaciones de pierna hacia atras'),
  (NULL, 'Recumbent Bike', 'Xe đạp ngả lưng', 'Recumbent Bike', 'Bicicleta reclinada', 'cardio', 'machine', 'timed', 'free_exercise_db', 'Recumbent_Bike', ARRAY['To begin, seat yourself on the bike and adjust the seat to your height.', 'Select the desired option from the menu. You may have to start pedaling to turn it on. You can use the manual setting, or you can select a program to use. Typically, you can enter your age and weight to estimate the amount of calories burned during exercise. The level of resistance can be changed throughout the workout. The handles can be used to monitor your heart rate to help you stay at an appropriate intensity.', 'Recumbent bikes offer convenience, cardiovascular benefits, and have less impact than other activities. A 150 lb person will burn about 230 calories cycling at a moderate rate for 30 minutes, compared to 450 calories or more running.']::text[], ARRAY['Recumbent_Bike/0.jpg', 'Recumbent_Bike/1.jpg']::text[], 'recumbent bike xe dap nga lung bicicleta reclinada'),
  (NULL, 'Return Push from Stance', 'Đẩy bóng trở về từ thế đứng', 'Return Push from Stance', 'Empuje de retorno desde postura', 'shoulders', 'medicine ball', 'compound', 'free_exercise_db', 'Return_Push_from_Stance', ARRAY['You will need a partner for this drill.', 'Begin in an athletic 2 or 3 point stance.', 'At the signal, move into a position to receive the pass from your partner.', 'Catch the medicine ball with both hands and immediately throw it back to your partner.', 'You can modify this drill by running different routes.']::text[], ARRAY['Return_Push_from_Stance/0.jpg', 'Return_Push_from_Stance/1.jpg']::text[], 'return push from stance day bong tro ve tu the dung empuje de retorno desde postura'),
  (NULL, 'Reverse Band Bench Press', 'Reverse Band Bench Press', 'Reverse Band Bench Press', 'Press de banca con banda invertida', 'triceps', 'barbell', 'compound', 'free_exercise_db', 'Reverse_Band_Bench_Press', ARRAY['Position a bench inside a power rack, with the bar set to the correct height. Begin by anchoring bands either to band pegs or to the top of the rack. Ensure that you will be position properly under the bands. Attach the other end to the barbell.', 'Lie on the bench, tuck your feet underneath you and arch your back. Using the bar to help support your weight, lift your shoulder off the bench and retract them, squeezing the shoulder blades together. Use your feet to drive your traps into the bench. Maintain this tight body position throughout the movement. However wide your grip, it should cover the ring on the bar.', 'Pull the bar out of the rack without protracting your shoulders. Focus on squeezing the bar and trying to pull it apart. Lower the bar to your lower chest or upper stomach. The bar, wrist, and elbow should stay in line at all times.', 'Pause when the barbell touches your torso, and then drive the bar up with as much force as possible. The elbows should be tucked in until lockout.']::text[], ARRAY['Reverse_Band_Bench_Press/0.jpg', 'Reverse_Band_Bench_Press/1.jpg']::text[], 'reverse band bench press day nguc day khang luc nguoc press de banca con banda invertida'),
  (NULL, 'Reverse Band Box Squat', 'Reverse Band Box Squat', 'Reverse Band Box Squat', 'Sentadilla al cajón con banda invertida', 'legs', 'barbell', 'compound', 'free_exercise_db', 'Reverse_Band_Box_Squat', ARRAY['Begin in a power rack with a box at the appropriate height behind you. Set up the bands either on band pegs or attached to the top of the rack, ensuring they will be directly above the bar during the squat. Attach the other end to the bar.', 'Begin by stepping under the bar and placing it across the back of the shoulders. Squeeze your shoulder blades together and rotate your elbows forward, attempting to bend the bar across your shoulders. Remove the bar from the rack, creating a tight arch in your lower back, and step back into position. Place your feet wider for more emphasis on the back, glutes, adductors, and hamstrings, or closer together for more quad development. Keep your head facing forward.', 'With your back, shoulders, and core tight, push your knees and butt out and you begin your descent. Sit back with your hips until you are seated on the box. Ideally, your shins should be perpendicular to the ground. Pause when you reach the box, and relax the hip flexors. Never bounce off of a box.', 'Keeping the weight on your heels and pushing your feet and knees out, drive upward off of the box as you lead the movement with your head. Continue upward, maintaining tightness head to toe. Use care to return the barbell to the rack.']::text[], ARRAY['Reverse_Band_Box_Squat/0.jpg', 'Reverse_Band_Box_Squat/1.jpg']::text[], 'reverse band box squat squat xuong buc day khang luc nguoc sentadilla al cajon con banda invertida'),
  (NULL, 'Reverse Band Deadlift', 'Reverse Band Deadlift', 'Reverse Band Deadlift', 'Peso muerto con banda invertida', 'back', 'barbell', 'compound', 'free_exercise_db', 'Reverse_Band_Deadlift', ARRAY['Set the bar up in a power rack. Attach bands to the top of the rack, using either bands pegs or the frame itself. Attach the other end of the bands to the bar.', 'Approach the bar so that it is centered over your feet. You feet should be about hip width apart. Bend at the hip to grip the bar at shoulder width, allowing your shoulder blades to protract. Typically, you would use an overhand grip or an over/under grip on heavier sets.', 'With your feet, and your grip set, take a big breath and then lower your hips and bend the knees until your shins contact the bar. Look forward with your head, keep your chest up and your back arched, and begin driving through the heels to move the weight upward.', 'After the bar passes the knees, aggressively pull the bar back, pulling your shoulder blades together as you drive your hips forward into the bar.', 'Lower the bar by bending at the hips and guiding it to the floor.']::text[], ARRAY['Reverse_Band_Deadlift/0.jpg', 'Reverse_Band_Deadlift/1.jpg']::text[], 'reverse band deadlift deadlift day khang luc nguoc peso muerto con banda invertida'),
  (NULL, 'Reverse Band Power Squat', 'Reverse Band Power Squat', 'Reverse Band Power Squat', 'Sentadilla de potencia con banda invertida', 'legs', 'barbell', 'compound', 'free_exercise_db', 'Reverse_Band_Power_Squat', ARRAY['Begin in a power rack with the pins and bar set at the appropriate height. After loading the bar, attach bands to the top of the rack, using either pegs or the frame itself. Attach the other end of the bands to the bar.', 'Begin by stepping under the bar and placing it across the back of the shoulders. Squeeze your shoulder blades together and rotate your elbows forward, attempting to bend the bar across your shoulders. Remove the bar from the rack, creating a tight arch in your lower back, and step back into position. Place your feet wide for more emphasis on the back, glutes, adductors, and hamstrings.', 'Keep your head facing forward. With your back, shoulders, and core tight, push your knees and butt out and you begin your descent. Sit back with your hips as much as possible. Ideally, your shins should be perpendicular to the ground. Lower bar position necessitates a greater torso lean to keep the bar over the heels. Continue until you break parallel, which is defined as the crease of the hip being in line with the top of the knee.', 'Keeping the weight on your heels and pushing your feet and knees out, drive upward as you lead the movement with your head. Continue upward, maintaining tightness head to toe, until you have returned to the starting position.']::text[], ARRAY['Reverse_Band_Power_Squat/0.jpg', 'Reverse_Band_Power_Squat/1.jpg']::text[], 'reverse band power squat power squat day khang luc nguoc sentadilla de potencia con banda invertida'),
  (NULL, 'Reverse Band Sumo Deadlift', 'Reverse Band Sumo Deadlift', 'Reverse Band Sumo Deadlift', 'Peso muerto sumo con banda invertida', 'legs', 'barbell', 'compound', 'free_exercise_db', 'Reverse_Band_Sumo_Deadlift', ARRAY['Begin with a bar loaded on the floor inside of a power rack. Attach bands to the top of the rack, using either pegs or the frame itself. Attach the other end to the barbell.', 'Approach the bar so that the bar intersects the middle of the feet. The feet should be set very wide, near the collars. Bend at the hips to grip the bar. The arms should be directly below the shoulders, inside the legs, and you can use a pronated grip, a mixed grip, or hook grip. Relax the shoulders, which in effect lengthens your arms.', 'Take a breath, and then lower your hips, looking forward with your head with your chest up. Drive through the floor, spreading your feet apart, with your weight on the back half of your feet. Extend through the hips and knees.', 'As the bar passes through the knees, lean back and drive the hips into the bar, pulling your shoulder blades together.', 'Return the weight to the ground by bending at the hips and controlling the weight on the way down.']::text[], ARRAY['Reverse_Band_Sumo_Deadlift/0.jpg', 'Reverse_Band_Sumo_Deadlift/1.jpg']::text[], 'reverse band sumo deadlift deadlift sumo day khang luc nguoc peso muerto sumo con banda invertida'),
  (NULL, 'Reverse Barbell Curl', 'Reverse Barbell Curl', 'Reverse Barbell Curl', 'Curl invertido con barra', 'biceps', 'barbell', 'isolation', 'free_exercise_db', 'Reverse_Barbell_Curl', ARRAY['Stand up with your torso upright while holding a barbell at shoulder width with the elbows close to the torso. The palm of your hands should be facing down (pronated grip). This will be your starting position.', 'While holding the upper arms stationary, curl the weights while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a second as you squeeze the muscle.', 'Slowly begin to bring the bar back to starting position as your breathe in.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Reverse_Barbell_Curl/0.jpg', 'Reverse_Barbell_Curl/1.jpg']::text[], 'reverse barbell curl cuon ta don nam nguoc curl invertido con barra'),
  (NULL, 'Reverse Barbell Preacher Curls', 'Reverse Barbell Preacher Curls', 'Reverse Barbell Preacher Curls', 'Curl predicador invertido con barra EZ', 'biceps', 'ez bar', 'isolation', 'free_exercise_db', 'Reverse_Barbell_Preacher_Curls', ARRAY['Grab an EZ-bar using a shoulder width and palms down (pronated) grip.', 'Now place the upper part of both arms on top of the preacher bench and have your arms extended. This will be your starting position.', 'As you exhale, use the biceps to curl the weight up until your biceps are fully contracted and the barbell is at shoulder height. Squeeze the biceps hard for a second at the contracted position.', 'As you breathe in, slowly lower the barbell until your upper arms are extended and the biceps is fully stretched.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Reverse_Barbell_Preacher_Curls/0.jpg', 'Reverse_Barbell_Preacher_Curls/1.jpg']::text[], 'reverse barbell preacher curls cuon ghe doc ta don nam nguoc curl predicador invertido con barra ez'),
  (NULL, 'Reverse Cable Curl', 'Reverse Cable Curl', 'Reverse Cable Curl', 'Curl invertido en polea', 'biceps', 'cable', 'isolation', 'free_exercise_db', 'Reverse_Cable_Curl', ARRAY['Stand up with your torso upright while holding a bar attachment that is attached to a low pulley using a pronated (palms down) and shoulder width grip. Make sure also that you keep the elbows close to the torso. This will be your starting position.', 'While holding the upper arms stationary, curl the weights while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a second as you squeeze the muscle.', 'Slowly begin to bring the bar back to starting position as your breathe in.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Reverse_Cable_Curl/0.jpg', 'Reverse_Cable_Curl/1.jpg']::text[], 'reverse cable curl cuon cap nam nguoc curl invertido en polea'),
  (NULL, 'Reverse Crunch', 'Reverse Crunch', 'Reverse Crunch', 'Crunch inverso', 'abs', 'bodyweight', 'bodyweight', 'free_exercise_db', 'Reverse_Crunch', ARRAY['Lie down on the floor with your legs fully extended and arms to the side of your torso with the palms on the floor. Your arms should be stationary for the entire exercise.', 'Move your legs up so that your thighs are perpendicular to the floor and feet are together and parallel to the floor. This is the starting position.', 'While inhaling, move your legs towards the torso as you roll your pelvis backwards and you raise your hips off the floor. At the end of this movement your knees will be touching your chest.', 'Hold the contraction for a second and move your legs back to the starting position while exhaling.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Reverse_Crunch/0.jpg', 'Reverse_Crunch/1.jpg']::text[], 'reverse crunch gap bung nguoc crunch inverso'),
  (NULL, 'Reverse Flyes', 'Reverse Flyes', 'Reverse Flyes', 'Aperturas invertidas con mancuernas', 'shoulders', 'dumbbell', 'isolation', 'free_exercise_db', 'Reverse_Flyes', ARRAY['To begin, lie down on an incline bench with the chest and stomach pressing against the incline. Have the dumbbells in each hand with the palms facing each other (neutral grip).', 'Extend the arms in front of you so that they are perpendicular to the angle of the bench. The legs should be stationary while applying pressure with the ball of your toes. This is the starting position.', 'Maintaining the slight bend of the elbows, move the weights out and away from each other (to the side) in an arc motion while exhaling. Tip: Try to squeeze your shoulder blades together to get the best results from this exercise.', 'The arms should be elevated until they are parallel to the floor.', 'Feel the contraction and slowly lower the weights back down to the starting position while inhaling.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Reverse_Flyes/0.jpg', 'Reverse_Flyes/1.jpg']::text[], 'reverse flyes bay vai sau ta don aperturas invertidas con mancuernas'),
  (NULL, 'Reverse Flyes With External Rotation', 'Reverse Flyes With External Rotation', 'Reverse Flyes With External Rotation', 'Aperturas invertidas con rotación externa', 'shoulders', 'dumbbell', 'isolation', 'free_exercise_db', 'Reverse_Flyes_With_External_Rotation', ARRAY['To begin, lie down on an incline bench set at a 30-degree angle with the chest and stomach pressing against the incline.', 'Have the dumbbells in each hand with the palms facing down to the floor. Your arms should be in front of you so that they are perpendicular to the angle of the bench. Tip: Your elbows should have a slight bend. The legs should be stationary while applying pressure with the ball of your toes (your heels should not be touching the floor). This is the starting position.', 'Maintaining the slight bend of the elbows, move the weights out and away from each other in an arc motion while exhaling.', 'As you lift the weight, your wrist should externally rotate by 90-degrees so that you go from a palms down (pronated) grip to a palms facing each other (neutral) grip. Tip: Try to squeeze your shoulder blades together to get the best results from this exercise.', 'The arms should be elevated until they are level with the head.', 'Feel the contraction and slowly lower the weights back down to the starting position while inhaling.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Reverse_Flyes_With_External_Rotation/0.jpg', 'Reverse_Flyes_With_External_Rotation/1.jpg']::text[], 'reverse flyes with external rotation bay vai sau kem xoay ngoai aperturas invertidas con rotacion externa'),
  (NULL, 'Reverse Grip Bent-Over Rows', 'Chèo cúi người nắm ngược', 'Reverse Grip Bent-Over Rows', 'Remo inclinado agarre invertido', 'back', 'barbell', 'compound', 'free_exercise_db', 'Reverse_Grip_Bent-Over_Rows', ARRAY['Stand erect while holding a barbell with a supinated grip (palms facing up).', 'Bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Tip: Make sure that you keep the head up. The barbell should hang directly in front of you as your arms hang perpendicular to the floor and your torso. This is your starting position.', 'While keeping the torso stationary, lift the barbell as you breathe out, keeping the elbows close to the body and not doing any force with the forearm other than holding the weights. On the top contracted position, squeeze the back muscles and hold for a second.', 'Slowly lower the weight again to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Reverse_Grip_Bent-Over_Rows/0.jpg', 'Reverse_Grip_Bent-Over_Rows/1.jpg']::text[], 'reverse grip bent-over rows cheo cui nguoi nam nguoc remo inclinado agarre invertido'),
  (NULL, 'Reverse Grip Triceps Pushdown', 'Đẩy cáp tay sau nắm ngược', 'Reverse Grip Triceps Pushdown', 'Jalón de tríceps agarre invertido', 'triceps', 'cable', 'isolation', 'free_exercise_db', 'Reverse_Grip_Triceps_Pushdown', ARRAY['Start by setting a bar attachment (straight or e-z) on a high pulley machine.', 'Facing the bar attachment, grab it with the palms facing up (supinated grip) at shoulder width. Lower the bar by using your lats until your arms are fully extended by your sides. Tip: Elbows should be in by your sides and your feet should be shoulder width apart from each other. This is the starting position.', 'Slowly elevate the bar attachment up as you inhale so it is aligned with your chest. Only the forearms should move and the elbows/upper arms should be stationary by your side at all times.', 'Then begin to lower the cable bar back down to the original staring position while exhaling and contracting the triceps hard.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Reverse_Grip_Triceps_Pushdown/0.jpg', 'Reverse_Grip_Triceps_Pushdown/1.jpg']::text[], 'reverse grip triceps pushdown day cap tay sau nam nguoc jalon de triceps agarre invertido'),
  (NULL, 'Reverse Hyperextension', 'Gập lưng ngược (máy)', 'Reverse Hyperextension', 'Hiperextensión inversa', 'legs', 'machine', 'compound', 'free_exercise_db', 'Reverse_Hyperextension', ARRAY['Place your feet between the pads after loading an appropriate weight. Lay on the top pad, allowing your hips to hang off the back, while grasping the handles to hold your position.', 'To begin the movement, flex the hips, pulling the legs forward.', 'Reverse the motion by extending the hips, kicking the leg back. It is very important not to over-extend the hip on this movement, stopping short of your full range of motion.', 'Return by again flexing the hip, pulling the carriage forward as far as you can.', 'Repeat for the desired number of repetitions.']::text[], ARRAY['Reverse_Hyperextension/0.jpg', 'Reverse_Hyperextension/1.jpg']::text[], 'reverse hyperextension gap lung nguoc (may) hiperextension inversa'),
  (NULL, 'Reverse Machine Flyes', 'Reverse Machine Flyes', 'Reverse Machine Flyes', 'Aperturas invertidas en máquina', 'shoulders', 'machine', 'isolation', 'free_exercise_db', 'Reverse_Machine_Flyes', ARRAY['Adjust the handles so that they are fully to the rear. Make an appropriate weight selection and adjust the seat height so the handles are at shoulder level. Grasp the handles with your hands facing inwards. This will be your starting position.', 'In a semicircular motion, pull your hands out to your side and back, contracting your rear delts.', 'Keep your arms slightly bent throughout the movement, with all of the motion occurring at the shoulder joint.', 'Pause at the rear of the movement, and slowly return the weight to the starting position.']::text[], ARRAY['Reverse_Machine_Flyes/0.jpg', 'Reverse_Machine_Flyes/1.jpg']::text[], 'reverse machine flyes bay vai sau may aperturas invertidas en maquina'),
  (NULL, 'Reverse Plate Curls', 'Reverse Plate Curls', 'Reverse Plate Curls', 'Curl invertido con disco', 'biceps', 'other', 'isolation', 'free_exercise_db', 'Reverse_Plate_Curls', ARRAY['Start by standing straight with a weighted plate held by both hands and arms fully extended. Use a pronated grip (palms facing down) and make sure your fingers grab the rough side of the plate while your thumb grabs the smooth side. Note: For the best results, grab the weighted plate at an 11:00 and 1:00 o''clock position.', 'Your feet should be shoulder width apart from each other and the weighted plate should be near the groin area. This is the starting position.', 'Slowly lift the plate up while keeping the elbows in and the upper arms stationary until your biceps and forearms touch while exhaling. The plate should be evenly aligned with your torso at this point.', 'Feel the contraction for a second and begin to lower the weight back down to the starting position while inhaling', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Reverse_Plate_Curls/0.jpg', 'Reverse_Plate_Curls/1.jpg']::text[], 'reverse plate curls cuon dia ta nam nguoc curl invertido con disco'),
  (NULL, 'Reverse Triceps Bench Press', 'Reverse Triceps Bench Press', 'Reverse Triceps Bench Press', 'Press de banca invertido para tríceps', 'triceps', 'barbell', 'compound', 'free_exercise_db', 'Reverse_Triceps_Bench_Press', ARRAY['Lie back on a flat bench. Using a close, supinated grip (around shoulder width), lift the bar from the rack and hold it straight over you with your arms locked extended in front of you and perpendicular to the floor. This will be your starting position.', 'As you breathe in, come down slowly until you feel the bar on your middle chest. Tip: Make sure that as opposed to a regular bench press, you keep the elbows close to the torso at all times in order to maximize triceps involvement.', 'After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your triceps muscles. Lock your arms in the contracted position, hold for a second and then start coming down slowly again. Tip: It should take at least twice as long to go down than to come up.', 'Repeat the movement for the prescribed amount of repetitions.', 'When you are done, place the bar back in the rack.']::text[], ARRAY['Reverse_Triceps_Bench_Press/0.jpg', 'Reverse_Triceps_Bench_Press/1.jpg']::text[], 'reverse triceps bench press day nguc tay sau nam nguoc press de banca invertido para triceps'),
  (NULL, 'Rhomboids-SMR', 'Lăn giãn cơ trám', 'Rhomboids-SMR', 'Liberación de romboides', 'back', 'foam roll', 'timed', 'free_exercise_db', 'Rhomboids-SMR', ARRAY['Lay down with your back on the floor. Place a foam roll underneath your upper back, and cross your arms in front of you, protracting your shoulders. This will be your starting position.', 'Raise your hips off of the ground, placing your weight onto the foam roll. Shift your weight to one side at a time, rolling over your middle and upper back. Pause at points of tension for 10-30 seconds.']::text[], ARRAY['Rhomboids-SMR/0.jpg', 'Rhomboids-SMR/1.jpg']::text[], 'rhomboids-smr lan gian co tram liberacion de romboides'),
  (NULL, 'Rickshaw Carry', 'Kéo xe kéo tay', 'Rickshaw Carry', 'Acarreo de rickshaw', 'biceps', 'other', 'compound', 'free_exercise_db', 'Rickshaw_Carry', ARRAY['Position the frame at the starting point, and load with the appropriate weight. Standing in the center of the frame, begin by gripping the handles and driving through your heels to lift the frame. Ensure your chest and head are up and your back is straight.', 'Immediately begin walking briskly with quick, controlled steps. Keep your chest up and head forward, and make sure you continue breathing. Bring the frame to the ground after you have reached the end point.']::text[], ARRAY['Rickshaw_Carry/0.jpg', 'Rickshaw_Carry/1.jpg']::text[], 'rickshaw carry keo xe keo tay acarreo de rickshaw'),
  (NULL, 'Rickshaw Deadlift', 'Rickshaw Deadlift', 'Rickshaw Deadlift', 'Peso muerto rickshaw', 'legs', 'other', 'compound', 'free_exercise_db', 'Rickshaw_Deadlift', ARRAY['Load the frame with the desired weight. Center yourself between the handles. You feet should be about hip width apart. Bend at the hips to grip the handles, allowing your shoulder blades to protract.', 'With your feet and your grip set, take a big breath and then lower your hips and flex the knees. Look forward with your head, keep your chest up and your back arched, and begin driving through the heels to move the weight upward. As the weight comes up, pull your shoulder blades together as you drive your hips forward.', 'Lower the weight by bending at the hips and guiding it to the ground.']::text[], ARRAY['Rickshaw_Deadlift/0.jpg', 'Rickshaw_Deadlift/1.jpg']::text[], 'rickshaw deadlift deadlift xe keo tay peso muerto rickshaw'),
  (NULL, 'Ring Dips', 'Ring Dips', 'Ring Dips', 'Fondos en anillas', 'triceps', 'other', 'compound', 'free_exercise_db', 'Ring_Dips', ARRAY['Grip a ring in each hand, and then take a small jump to help you get into the starting position with your arms locked out.', 'Begin by flexing the elbow, lowering your body until your arms break 90 degrees. Avoid swinging, and maintain good posture throughout the descent.', 'Reverse the motion by extending the elbow, pushing yourself back up into the starting position.', 'Repeat for the desired number of repetitions.']::text[], ARRAY['Ring_Dips/0.jpg', 'Ring_Dips/1.jpg']::text[], 'ring dips dips tren vong treo fondos en anillas'),
  (NULL, 'Rocket Jump', 'Bật nhảy tên lửa', 'Rocket Jump', 'Salto cohete', 'legs', 'bodyweight', 'bodyweight', 'free_exercise_db', 'Rocket_Jump', ARRAY['Begin in a relaxed stance with your feet shoulder width apart and hold your arms close to the body.', 'To initiate the move, squat down halfway and explode back up as high as possible.', 'Fully extend your entire body, reaching overhead as far as possible. As you land, absorb your impact through the legs.']::text[], ARRAY['Rocket_Jump/0.jpg', 'Rocket_Jump/1.jpg']::text[], 'rocket jump bat nhay ten lua salto cohete'),
  (NULL, 'Rocking Standing Calf Raise', 'Nhón bắp chân đứng bập bênh', 'Rocking Standing Calf Raise', 'Elevación de gemelos de pie balanceando', 'calves', 'barbell', 'isolation', 'free_exercise_db', 'Rocking_Standing_Calf_Raise', ARRAY['This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place it on the back of your shoulders (slightly below the neck).', 'Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.', 'Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance. Also maintain a straight back and keep the knees with a slight bend; never locked. This will be your starting position.', 'Raise your heels as you breathe out by extending your ankles as high as possible and flexing your calf. Ensure that the knee is kept stationary at all times. There should be no bending (other than the slight initial bend we created during positioning) at any time. Hold the contracted position by a second before you start to go back down.', 'Go back slowly to the starting position as you breathe in by lowering your heels as you bend the ankles until calves are stretched.', 'Now lift your toes by contracting the tibia muscles in the front of the calves as you breathe out.', 'Hold for a second and bring them back down as you breathe in.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Rocking_Standing_Calf_Raise/0.jpg', 'Rocking_Standing_Calf_Raise/1.jpg']::text[], 'rocking standing calf raise nhon bap chan dung bap benh elevacion de gemelos de pie balanceando'),
  (NULL, 'Rocky Pull-Ups/Pulldowns', 'Hít xà / kéo xà Rocky', 'Rocky Pull-Ups/Pulldowns', 'Dominadas / jalones Rocky', 'back', 'other', 'compound', 'free_exercise_db', 'Rocky_Pull-Ups_Pulldowns', ARRAY['Grab the pull-up bar with the palms facing forward using a wide grip.', 'As you have both arms extended in front of you holding the bar at the chosen grip width, bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.', 'Pull your torso up until the bar touches your upper chest by drawing the shoulders and the upper arms down and back. Exhale as you perform this portion of the movement. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary as it moves through space and only the arms should move. The forearms should do no other work other than hold the bar.', 'After a second on the contracted position, start to inhale and slowly lower your torso back to the starting position when your arms are fully extended and the lats are fully stretched.', 'Now repeat the same movements as described above except this time your torso will remain straight as you go up and the bar will touch the back of the neck instead of the upper chest. Tip: Use the head to lean forward slightly as it will help you properly execute this portion of the exercise.', 'Once you have lowered yourself back down to the starting position, repeat the exercise for the prescribed amount of repetitions in your program.']::text[], ARRAY['Rocky_Pull-Ups_Pulldowns/0.jpg', 'Rocky_Pull-Ups_Pulldowns/1.jpg']::text[], 'rocky pull-ups/pulldowns hit xa / keo xa rocky dominadas / jalones rocky'),
  (NULL, 'Romanian Deadlift from Deficit', 'Romanian Deadlift from Deficit', 'Romanian Deadlift from Deficit', 'Peso muerto rumano en déficit', 'legs', 'barbell', 'compound', 'free_exercise_db', 'Romanian_Deadlift_from_Deficit', ARRAY['Begin standing while holding a bar at arm''s length in front of you. You can stand on a raised platform to increase the range of motion.', 'Begin by flexing the knees slightly, and then flex at the hip, moving your butt back as far as possible, lowering the torso as far as flexibility allows. The back should remain in absolute extension at all times, and the bar should remain in contact with the legs. If done properly, there should be heavy tension felt in the hamstrings.', 'Reverse the motion to return to the starting position.']::text[], ARRAY['Romanian_Deadlift_from_Deficit/0.jpg', 'Romanian_Deadlift_from_Deficit/1.jpg']::text[], 'romanian deadlift from deficit deadlift kieu romania dung tren buc peso muerto rumano en deficit'),
  (NULL, 'Rope Climb', 'Leo dây', 'Rope Climb', 'Trepar la cuerda', 'back', 'other', 'compound', 'free_exercise_db', 'Rope_Climb', ARRAY['Grab the rope with both hands above your head. Pull down on the rope as you take a small jump.', 'Wrap the rope around one leg, using your feet to pinch the rope. Reach up as high as possible with your arms, gripping the rope tightly.', 'Release the rope from your feet as you pull yourself up with your arms, bringing your knees towards your chest.', 'Resecure your feet on the rope, and then stand up to take another high hold on the rope. Continue until you reach the top of the rope.', 'To lower yourself, loosen the grip of your feet on the rope as you slide down using a hand over hand motion.']::text[], ARRAY['Rope_Climb/0.jpg', 'Rope_Climb/1.jpg']::text[], 'rope climb leo day trepar la cuerda'),
  (NULL, 'Rope Crunch', 'Rope Crunch', 'Rope Crunch', 'Crunch con cuerda', 'abs', 'cable', 'isolation', 'free_exercise_db', 'Rope_Crunch', ARRAY['Kneel 1-2 feet in front of a cable system with a rope attached.', 'After selecting an appropriate weight, grasp the rope with both hands reaching overhead. Your torso should be upright in the starting position.', 'To begin, flex at the spine, attempting to bring your rib cage to your legs as you pull the cable down.', 'Pause at the bottom of the motion, and then slowly return to the starting position.', 'These can be done with twists or to the side to hit the obliques.']::text[], ARRAY['Rope_Crunch/0.jpg', 'Rope_Crunch/1.jpg']::text[], 'rope crunch gap bung cap day thung crunch con cuerda'),
  (NULL, 'Rope Jumping', 'Nhảy dây', 'Rope Jumping', 'Saltar la cuerda', 'cardio', 'other', 'timed', 'free_exercise_db', 'Rope_Jumping', ARRAY['Hold an end of the rope in each hand. Position the rope behind you on the ground. Raise your arms up and turn the rope over your head bringing it down in front of you. When it reaches the ground, jump over it. Find a good turning pace that can be maintained. Different speeds and techniques can be used to introduce variation.', 'Rope jumping is exciting, challenges your coordination, and requires a lot of energy. A 150 lb person will burn about 350 calories jumping rope for 30 minutes, compared to over 450 calories running.']::text[], ARRAY['Rope_Jumping/0.jpg', 'Rope_Jumping/1.jpg']::text[], 'rope jumping nhay day saltar la cuerda'),
  (NULL, 'Rope Straight-Arm Pulldown', 'Kéo cáp tay thẳng dây thừng', 'Rope Straight-Arm Pulldown', 'Jalón con brazos rectos con cuerda', 'back', 'cable', 'isolation', 'free_exercise_db', 'Rope_Straight-Arm_Pulldown', ARRAY['Attach a rope to a high pulley and make your weight selection. Stand a couple feet back from the pulley with your feet staggered and take the rope with both hands. Lean forward from the hip, keeping your back straight, with your arms extended up in front of you. This will be your starting position.', 'Keeping your arms straight, extend the shoulder to pull the rope down to your thighs.', 'Pause at the bottom of the motion, squeezing your lats.', 'Return to the starting position without allowing the weight to fully rest on the stack.']::text[], ARRAY['Rope_Straight-Arm_Pulldown/0.jpg', 'Rope_Straight-Arm_Pulldown/1.jpg']::text[], 'rope straight-arm pulldown keo cap tay thang day thung jalon con brazos rectos con cuerda'),
  (NULL, 'Round The World Shoulder Stretch', 'Giãn vai xoay vòng', 'Round The World Shoulder Stretch', 'Estiramiento de hombro alrededor del mundo', 'shoulders', 'other', 'timed', 'free_exercise_db', 'Round_The_World_Shoulder_Stretch', ARRAY['Stand up straight with your legs together, holding a bodybar or broomstick.', 'Hold the pole behind your hips with a wider than shoulder width grip. Your palms should be down and your thumbs facing out.', 'Slowly lift your arms up behind your head. Don''t force it if it gets hard to lift further.']::text[], ARRAY['Round_The_World_Shoulder_Stretch/0.jpg', 'Round_The_World_Shoulder_Stretch/1.jpg']::text[], 'round the world shoulder stretch gian vai xoay vong estiramiento de hombro alrededor del mundo'),
  (NULL, 'Rowing, Stationary', 'Chèo thuyền tại chỗ', 'Rowing, Stationary', 'Remo estático', 'cardio', 'machine', 'timed', 'free_exercise_db', 'Rowing_Stationary', ARRAY['To begin, seat yourself on the rower. Make sure that your heels are resting comfortably against the base of the foot pedals and that the straps are secured. Select the program that you wish to use, if applicable. Sit up straight and bend forward at the hips.', 'There are three phases of movement when using a rower. The first phase is when you come forward on the rower. Your knees are bent and against your chest. Your upper body is leaning slightly forward while still maintaining good posture. Next, push against the foot pedals and extend your legs while bringing your hands to your upper abdominal area, squeezing your shoulders back as you do so. To avoid straining your back, use primarily your leg and hip muscles.', 'The recovery phase simply involves straightening your arms, bending the knees, and bringing your body forward again as you transition back into the first phase.']::text[], ARRAY['Rowing_Stationary/0.jpg', 'Rowing_Stationary/1.jpg']::text[], 'rowing, stationary cheo thuyen tai cho remo estatico'),
  (NULL, 'Runner''s Stretch', 'Giãn cơ của người chạy', 'Runner''s Stretch', 'Estiramiento del corredor', 'legs', 'other', 'timed', 'free_exercise_db', 'Runners_Stretch', ARRAY['It''s easiest to get into this stretch if you start standing up, put one leg behind you, and slowly lower your torso down to the floor.', 'Keep the front heel on the floor (if it lifts up, scoot your other leg further back).', 'Place your hands on either side of your front leg. To get more out of this stretch, push your butt up toward the ceiling, and then gradually lower it back toward the floor. You''ll Stretch the hip flexor of the back leg and the hamstring and buttocks of the front.']::text[], ARRAY['Runners_Stretch/0.jpg', 'Runners_Stretch/1.jpg']::text[], 'runner''s stretch gian co cua nguoi chay estiramiento del corredor'),
  (NULL, 'Running, Treadmill', 'Chạy bộ máy chạy bộ', 'Running, Treadmill', 'Correr en cinta', 'cardio', 'machine', 'timed', 'free_exercise_db', 'Running_Treadmill', ARRAY['To begin, step onto the treadmill and select the desired option from the menu. Most treadmills have a manual setting, or you can select a program to run. Typically, you can enter your age and weight to estimate the amount of calories burned during exercise. Elevation can be adjusted to change the intensity of the workout.', 'Treadmills offer convenience, cardiovascular benefits, and usually have less impact than running outside. A 150 lb person will burn over 450 calories running 8 miles per hour for 30 minutes. Maintain proper posture as you run, and only hold onto the handles when necessary, such as when dismounting or checking your heart rate.']::text[], ARRAY['Running_Treadmill/0.jpg', 'Running_Treadmill/1.jpg']::text[], 'running, treadmill chay bo may chay bo correr en cinta'),
  (NULL, 'Russian Twist', 'Russian Twist', 'Russian Twist', 'Giro ruso', 'abs', 'bodyweight', 'bodyweight', 'free_exercise_db', 'Russian_Twist', ARRAY['Lie down on the floor placing your feet either under something that will not move or by having a partner hold them. Your legs should be bent at the knees.', 'Elevate your upper body so that it creates an imaginary V-shape with your thighs. Your arms should be fully extended in front of you perpendicular to your torso and with the hands clasped. This is the starting position.', 'Twist your torso to the right side until your arms are parallel with the floor while breathing out.', 'Hold the contraction for a second and move back to the starting position while breathing out. Now move to the opposite side performing the same techniques you applied to the right side.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Russian_Twist/0.jpg', 'Russian_Twist/1.jpg']::text[], 'russian twist xoay nguoi kieu nga giro ruso'),
  (NULL, 'Sandbag Load', 'Nâng bao cát', 'Sandbag Load', 'Carga de saco de arena', 'legs', 'other', 'compound', 'free_exercise_db', 'Sandbag_Load', ARRAY['To load sandbags or other objects, begin with the implements placed a distance from the loading platform, typically 50 feet.', 'Begin by lifting the sandbag. Sandbags are extremely awkward, and the manner of lifting them can vary depending on the particular sandbag used. Reach as far around it as possible, extending through the hips and knees to pull it up high. Shouldering is usually not allowed.', 'Move as quickly as possible to the platform, and load it, extending through your hips, knees, and ankles to get it as high as possible. Place it onto the platform, ensuring it doesn''t fall off.', 'Return to the starting position to retrieve the next sandbag, and repeat until the event is completed.']::text[], ARRAY['Sandbag_Load/0.jpg', 'Sandbag_Load/1.jpg']::text[], 'sandbag load nang bao cat carga de saco de arena'),
  (NULL, 'Scapular Pull-Up', 'Hít xà bả vai', 'Scapular Pull-Up', 'Dominadas escapulares', 'shoulders', 'other', 'bodyweight', 'free_exercise_db', 'Scapular_Pull-Up', ARRAY['Take a pronated grip on a pull-up bar.', 'From a hanging position, raise yourself a few inches without using your arms. Do this by depressing your shoulder girdle in a reverse shrugging motion.', 'Pause at the completion of the movement, and then slowly return to the starting position before performing more repetitions.']::text[], ARRAY['Scapular_Pull-Up/0.jpg', 'Scapular_Pull-Up/1.jpg']::text[], 'scapular pull-up hit xa ba vai dominadas escapulares'),
  (NULL, 'Scissor Kick', 'Đá kéo', 'Scissor Kick', 'Patada de tijera', 'abs', 'bodyweight', 'timed', 'free_exercise_db', 'Scissor_Kick', ARRAY['To begin, lie down with your back pressed against the floor or on an exercise mat (optional). Your arms should be fully extended to the sides with your palms facing down. Note: The arms should be stationary the entire time.', 'With a slight bend at the knees, lift your legs up so that your heels are about 6 inches off the ground. This is the starting position.', 'Now lift your left leg up to about a 45 degree angle while your right leg is lowered until the heel is about 2-3 inches from the ground.', 'Switch movements by raising your right leg up and lowering your left leg. Remember to breathe while performing this exercise.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Scissor_Kick/0.jpg', 'Scissor_Kick/1.jpg']::text[], 'scissor kick da keo patada de tijera'),
  (NULL, 'Scissors Jump', 'Bật nhảy tách chân', 'Scissors Jump', 'Salto de tijera', 'legs', 'bodyweight', 'bodyweight', 'free_exercise_db', 'Scissors_Jump', ARRAY['Assume a lunge stance position with one foot forward with the knee bent, and the rear knee nearly touching the ground.', 'Ensure that the front knee is over the midline of the foot. Extending through both legs, jump as high as possible, swinging your arms to gain lift.', 'As you jump as high as you can, switch the position of your legs, moving your front leg to the back and the rear leg to the front.', 'As you land, absorb the impact through the legs by adopting the lunge position, and repeat.']::text[], ARRAY['Scissors_Jump/0.jpg', 'Scissors_Jump/1.jpg']::text[], 'scissors jump bat nhay tach chan salto de tijera'),
  (NULL, 'Seated Band Hamstring Curl', 'Seated Band Hamstring Curl', 'Seated Band Hamstring Curl', 'Curl femoral sentado con banda', 'legs', 'other', 'isolation', 'free_exercise_db', 'Seated_Band_Hamstring_Curl', ARRAY['Secure a band close to the ground and place a bench a couple feet away from it.', 'Seat yourself on the bench and secure the band behind your ankles, beginning with your legs straight. This will be your starting position.', 'Flex the knees, bringing your feet towards the bench. You may need to lean back slightly to keep your feet from striking the floor.', 'Pause at the completion of the movement, and then slowly return to the starting position.']::text[], ARRAY['Seated_Band_Hamstring_Curl/0.jpg', 'Seated_Band_Hamstring_Curl/1.jpg']::text[], 'seated band hamstring curl cuon dui sau ngoi day khang luc curl femoral sentado con banda'),
  (NULL, 'Seated Barbell Military Press', 'Đẩy vai ngồi tạ đòn', 'Seated Barbell Military Press', 'Press militar sentado con barra', 'shoulders', 'barbell', 'compound', 'free_exercise_db', 'Seated_Barbell_Military_Press', ARRAY['Sit on a Military Press Bench with a bar behind your head and either have a spotter give you the bar (better on the rotator cuff this way) or pick it up yourself carefully with a pronated grip (palms facing forward). Tip: Your grip should be wider than shoulder width and it should create a 90-degree angle between the forearm and the upper arm as the barbell goes down.', 'Once you pick up the barbell with the correct grip length, lift the bar up over your head by locking your arms. Hold at about shoulder level and slightly in front of your head. This is your starting position.', 'Lower the bar down to the collarbone slowly as you inhale.', 'Lift the bar back up to the starting position as you exhale.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Seated_Barbell_Military_Press/0.jpg', 'Seated_Barbell_Military_Press/1.jpg']::text[], 'seated barbell military press day vai ngoi ta don press militar sentado con barra'),
  (NULL, 'Seated Barbell Twist', 'Xoay người ngồi tạ đòn', 'Seated Barbell Twist', 'Giro sentado con barra', 'abs', 'barbell', 'isolation', 'free_exercise_db', 'Seated_Barbell_Twist', ARRAY['Start out by sitting at the end of a flat bench with a barbell placed on top of your thighs. Your feet should be shoulder width apart from each other.', 'Grip the bar with your palms facing down and make sure your hands are wider than shoulder width apart from each other. Begin to lift the barbell up over your head until your arms are fully extended.', 'Now lower the barbell behind your head until it is resting along the base of your neck. This is the starting position.', 'While keeping your feet and head stationary, move your waist from side to side so that your oblique muscles feel the contraction. Only move from side to side as far as your waist will allow you to go. Stretching or moving too far can cause an injury to occur. Tip: Use a slow and controlled motion.', 'Remember to breathe out while twisting your body to the side and in when moving back to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Seated_Barbell_Twist/0.jpg', 'Seated_Barbell_Twist/1.jpg']::text[], 'seated barbell twist xoay nguoi ngoi ta don giro sentado con barra'),
  (NULL, 'Seated Bent-Over One-Arm Dumbbell Triceps Extension', 'Duỗi tay sau một tay tạ đơn ngồi cúi người', 'Seated Bent-Over One-Arm Dumbbell Triceps Extension', 'Extensión de tríceps sentado inclinado a una mano', 'triceps', 'dumbbell', 'isolation', 'free_exercise_db', 'Seated_Bent-Over_One-Arm_Dumbbell_Triceps_Extension', ARRAY['Sit down at the end of a flat bench with a dumbbell in one arm using a neutral grip (palms of the hand facing you).', 'Bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Make sure that you keep the head up.', 'The upper arm with the dumbbell should be close to the torso and aligned with it (lifted up until it is parallel to the floor while the forearms are pointing towards the floor as the hands hold the weights). Tip: There should be a 90-degree angle between the forearms and the upper arm. This is your starting position.', 'Keeping the upper arm stationary, use the triceps to lift the weight as you exhale until the forearm is parallel to the floor and the whole arm is extended. Like many other arm exercises, only the forearm moves.', 'After a second contraction at the top, slowly lower the dumbbell back to the starting position as you inhale.', 'Repeat the movement for the prescribed amount of repetitions.', 'Switch arms and repeat the exercise.']::text[], ARRAY['Seated_Bent-Over_One-Arm_Dumbbell_Triceps_Extension/0.jpg', 'Seated_Bent-Over_One-Arm_Dumbbell_Triceps_Extension/1.jpg']::text[], 'seated bent-over one-arm dumbbell triceps extension duoi tay sau mot tay ta don ngoi cui nguoi extension de triceps sentado inclinado a una mano'),
  (NULL, 'Seated Bent-Over Rear Delt Raise', 'Nâng vai sau ngồi cúi người', 'Seated Bent-Over Rear Delt Raise', 'Elevación posterior sentado inclinado', 'shoulders', 'dumbbell', 'isolation', 'free_exercise_db', 'Seated_Bent-Over_Rear_Delt_Raise', ARRAY['Place a couple of dumbbells looking forward in front of a flat bench.', 'Sit on the end of the bench with your legs together and the dumbbells behind your calves.', 'Bend at the waist while keeping the back straight in order to pick up the dumbbells. The palms of your hands should be facing each other as you pick them. This will be your starting position.', 'Keeping your torso forward and stationary, and the arms slightly bent at the elbows, lift the dumbbells straight to the side until both arms are parallel to the floor. Exhale as you lift the weights. (Note: avoid swinging the torso or bringing the arms back as opposed to the side.)', 'After a one second contraction at the top, slowly lower the dumbbells back to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Seated_Bent-Over_Rear_Delt_Raise/0.jpg', 'Seated_Bent-Over_Rear_Delt_Raise/1.jpg']::text[], 'seated bent-over rear delt raise nang vai sau ngoi cui nguoi elevacion posterior sentado inclinado'),
  (NULL, 'Seated Bent-Over Two-Arm Dumbbell Triceps Extension', 'Duỗi tay sau hai tay tạ đơn ngồi cúi người', 'Seated Bent-Over Two-Arm Dumbbell Triceps Extension', 'Extensión de tríceps sentado inclinado a dos manos', 'triceps', 'dumbbell', 'isolation', 'free_exercise_db', 'Seated_Bent-Over_Two-Arm_Dumbbell_Triceps_Extension', ARRAY['Sit down at the end of a flat bench with a dumbbell in both arms using a neutral grip (palms of the hand facing you).', 'Bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Make sure that you keep the head up.', 'The upper arms with the dumbbells should be close to the torso and aligned with it (lifted up until they are parallel to the floor while the forearms are pointing towards the floor as the hands hold the weights). Tip: There should be a 90-degree angle between the forearms and the upper arm. This is your starting position.', 'Keeping the upper arms stationary, use the triceps to lift the weight as you exhale until the forearms are parallel to the floor and the whole arm is extended. Like many other arm exercises, only the forearm moves.', 'After a second contraction at the top, slowly lower the dumbbells back to the starting position as you inhale.', 'Repeat the movement for the prescribed amount of repetitions.']::text[], ARRAY['Seated_Bent-Over_Two-Arm_Dumbbell_Triceps_Extension/0.jpg', 'Seated_Bent-Over_Two-Arm_Dumbbell_Triceps_Extension/1.jpg']::text[], 'seated bent-over two-arm dumbbell triceps extension duoi tay sau hai tay ta don ngoi cui nguoi extension de triceps sentado inclinado a dos manos'),
  (NULL, 'Seated Biceps', 'Giãn tay trước ngồi', 'Seated Biceps', 'Estiramiento de bíceps sentado', 'biceps', 'bodyweight', 'timed', 'free_exercise_db', 'Seated_Biceps', ARRAY['Sit on the floor with your knees bent and your partner standing behind you. Extend your arms straight behind you with your palms facing each other. Your partner will hold your wrists for you. This will be the starting position.', 'Attempt to flex your elbows, while your partner prevents any actual movement.', 'After 10-20 seconds, relax your arms while your partner gently pulls your wrists up to stretch your biceps. Be sure to let your partner know when the stretch is appropriate to prevent injury or overstretching.']::text[], ARRAY['Seated_Biceps/0.jpg', 'Seated_Biceps/1.jpg']::text[], 'seated biceps gian tay truoc ngoi estiramiento de biceps sentado'),
  (NULL, 'Seated Cable Rows', 'Chèo cáp ngồi', 'Seated Cable Rows', 'Remo sentado en polea', 'back', 'cable', 'compound', 'free_exercise_db', 'Seated_Cable_Rows', ARRAY['For this exercise you will need access to a low pulley row machine with a V-bar. Note: The V-bar will enable you to have a neutral grip where the palms of your hands face each other. To get into the starting position, first sit down on the machine and place your feet on the front platform or crossbar provided making sure that your knees are slightly bent and not locked.', 'Lean over as you keep the natural alignment of your back and grab the V-bar handles.', 'With your arms extended pull back until your torso is at a 90-degree angle from your legs. Your back should be slightly arched and your chest should be sticking out. You should be feeling a nice stretch on your lats as you hold the bar in front of you. This is the starting position of the exercise.', 'Keeping the torso stationary, pull the handles back towards your torso while keeping the arms close to it until you touch the abdominals. Breathe out as you perform that movement. At that point you should be squeezing your back muscles hard. Hold that contraction for a second and slowly go back to the original position while breathing in.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Seated_Cable_Rows/0.jpg', 'Seated_Cable_Rows/1.jpg']::text[], 'seated cable rows cheo cap ngoi remo sentado en polea'),
  (NULL, 'Seated Cable Shoulder Press', 'Đẩy vai cáp ngồi', 'Seated Cable Shoulder Press', 'Press de hombros sentado en polea', 'shoulders', 'cable', 'compound', 'free_exercise_db', 'Seated_Cable_Shoulder_Press', ARRAY['Adjust the weight to an appropriate amount and be seated, grasping the handles. Your upper arms should be about 90 degrees to the body, with your head and chest up. The elbows should also be bent to about 90 degrees. This will be your starting position.', 'Begin by extending through the elbow, pressing the handles together above your head.', 'After pausing at the top, return the handles to the starting position. Ensure that you maintain tension on the cables.', 'You can also execute this movement with your back off the pad and alternate hands.']::text[], ARRAY['Seated_Cable_Shoulder_Press/0.jpg', 'Seated_Cable_Shoulder_Press/1.jpg']::text[], 'seated cable shoulder press day vai cap ngoi press de hombros sentado en polea'),
  (NULL, 'Seated Calf Raise', 'Nhón bắp chân ngồi', 'Seated Calf Raise', 'Elevación de gemelos sentado', 'calves', 'machine', 'isolation', 'free_exercise_db', 'Seated_Calf_Raise', ARRAY['Sit on the machine and place your toes on the lower portion of the platform provided with the heels extending off. Choose the toe positioning of your choice (forward, in, or out) as per the beginning of this chapter.', 'Place your lower thighs under the lever pad, which will need to be adjusted according to the height of your thighs. Now place your hands on top of the lever pad in order to prevent it from slipping forward.', 'Lift the lever slightly by pushing your heels up and release the safety bar. This will be your starting position.', 'Slowly lower your heels by bending at the ankles until the calves are fully stretched. Inhale as you perform this movement.', 'Raise the heels by extending the ankles as high as possible as you contract the calves and breathe out. Hold the top contraction for a second.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Seated_Calf_Raise/0.jpg', 'Seated_Calf_Raise/1.jpg']::text[], 'seated calf raise nhon bap chan ngoi elevacion de gemelos sentado'),
  (NULL, 'Seated Calf Stretch', 'Giãn bắp chân ngồi', 'Seated Calf Stretch', 'Estiramiento de gemelos sentado', 'calves', 'other', 'timed', 'free_exercise_db', 'Seated_Calf_Stretch', ARRAY['Sit up straight on an exercise mat.', 'Bend one knee and put that foot on the floor to stabilize the torso.', 'Straighten your other leg and flex your ankle.', 'Using a band, towel, or your hand if you can reach, pull the toes toward you. Hold for 10 to 20 seconds, then switch sides.']::text[], ARRAY['Seated_Calf_Stretch/0.jpg', 'Seated_Calf_Stretch/1.jpg']::text[], 'seated calf stretch gian bap chan ngoi estiramiento de gemelos sentado'),
  (NULL, 'Seated Close-Grip Concentration Barbell Curl', 'Seated Close-Grip Concentration Barbell Curl', 'Seated Close-Grip Concentration Barbell Curl', 'Curl concentrado sentado con barra agarre cerrado', 'biceps', 'barbell', 'isolation', 'free_exercise_db', 'Seated_Close-Grip_Concentration_Barbell_Curl', ARRAY['Sit down on a flat bench with a barbell or E-Z Bar in front of you in between your legs. Your legs should be spread with the knees bent and the feet on the floor.', 'Use your arms to pick the barbell up and place the back of your upper arms on top of your inner thighs (around three and a half inches away from the front of the knee). A supinated grip closer than shoulder width is needed to perform this exercise. Tip: Your arm should be extended at arms length and the barbell should be above the floor. This will be your starting position.', 'While holding the upper arms stationary, curl the weights forward while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a second as you squeeze the biceps.', 'Slowly begin to bring the barbell back to starting position as your breathe in. Tip: Avoid swinging motions at any time.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Seated_Close-Grip_Concentration_Barbell_Curl/0.jpg', 'Seated_Close-Grip_Concentration_Barbell_Curl/1.jpg']::text[], 'seated close-grip concentration barbell curl cuon ta don tap trung nam hep ngoi curl concentrado sentado con barra agarre cerrado'),
  (NULL, 'Seated Dumbbell Curl', 'Seated Dumbbell Curl', 'Seated Dumbbell Curl', 'Curl sentado con mancuernas', 'biceps', 'dumbbell', 'isolation', 'free_exercise_db', 'Seated_Dumbbell_Curl', ARRAY['Sit on a flat bench with a dumbbell on each hand being held at arms length. The elbows should be close to the torso.', 'Rotate the palms of the hands so that they are facing your torso. This will be your starting position.', 'While holding the upper arm stationary, curl the weights and start twisting the wrists once the dumbbells pass your thighs so that the palms of your hands face forward at the end of the movement. Make sure that you contract the biceps as you breathe out and make sure that only the forearms move. Continue the movement until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a second as you squeeze the biceps.', 'Slowly begin to bring the dumbbells back to the starting position as your breathe in and as you rotate the wrists back to a neutral grip.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Seated_Dumbbell_Curl/0.jpg', 'Seated_Dumbbell_Curl/1.jpg']::text[], 'seated dumbbell curl cuon ta don ngoi curl sentado con mancuernas'),
  (NULL, 'Seated Dumbbell Inner Biceps Curl', 'Seated Dumbbell Inner Biceps Curl', 'Seated Dumbbell Inner Biceps Curl', 'Curl interno sentado con mancuernas', 'biceps', 'dumbbell', 'isolation', 'free_exercise_db', 'Seated_Dumbbell_Inner_Biceps_Curl', ARRAY['Sit on the end of a flat bench with a dumbbell in each hand being held at arms length. The elbows should be close to the torso.', 'Rotate the palms of the hands so that they are facing inward in a neutral position. This will be your starting position.', 'While holding the upper arms stationary, curl the dumbbells out and up, turning the palms out as you lift and keeping your forearms in line with your outer deltoids. Tips:', 'Only the forearms should move. Continue the movement until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a second as you squeeze the biceps.', 'Slowly begin to bring the dumbbells back to the starting position as your breathe in. Remember to rotate your arms as you lower the dumbbells so that you can switch back to a neutral grip.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Seated_Dumbbell_Inner_Biceps_Curl/0.jpg', 'Seated_Dumbbell_Inner_Biceps_Curl/1.jpg']::text[], 'seated dumbbell inner biceps curl cuon tay truoc trong ta don ngoi curl interno sentado con mancuernas'),
  (NULL, 'Seated Dumbbell Palms-Down Wrist Curl', 'Seated Dumbbell Palms-Down Wrist Curl', 'Seated Dumbbell Palms-Down Wrist Curl', 'Curl de muñeca prono sentado con mancuerna', 'biceps', 'dumbbell', 'isolation', 'free_exercise_db', 'Seated_Dumbbell_Palms-Down_Wrist_Curl', ARRAY['Start out by placing two dumbbells on the floor in front of a flat bench.', 'Sit down on the edge of the flat bench with your legs at about shoulder width apart. Make sure to keep your feet on the floor.', 'Use your arms to grab both of the dumbbells and bring them up so that your forearms are resting against your thighs with the palms of the hands facing down. Your wrists should be hanging over the edge of your thighs.', 'Start out by curling your wrist upwards and exhaling.', 'Slowly lower your wrists back down to the starting position while inhaling. Make sure to inhale during this part of the exercise. Tip: Your forearms should be stationary as your wrist is the only movement needed to perform this exercise.', 'Repeat for the recommended amount of repetitions.', 'When finished, simply lower the dumbbells to the floor.']::text[], ARRAY['Seated_Dumbbell_Palms-Down_Wrist_Curl/0.jpg', 'Seated_Dumbbell_Palms-Down_Wrist_Curl/1.jpg']::text[], 'seated dumbbell palms-down wrist curl cuon co tay nam up ta don ngoi curl de muneca prono sentado con mancuerna'),
  (NULL, 'Seated Dumbbell Palms-Up Wrist Curl', 'Seated Dumbbell Palms-Up Wrist Curl', 'Seated Dumbbell Palms-Up Wrist Curl', 'Curl de muñeca supino sentado con mancuerna', 'biceps', 'dumbbell', 'isolation', 'free_exercise_db', 'Seated_Dumbbell_Palms-Up_Wrist_Curl', ARRAY['Start out by placing two dumbbells on the floor in front of a flat bench.', 'Sit down on the edge of the flat bench with your legs at about shoulder width apart. Make sure to keep your feet on the floor.', 'Use your arms to grab both of the dumbbells and bring them up so that your forearms are resting against your thighs with the palms of the hands facing up. Your wrists should be hanging over the edge of your thighs.', 'Start out by curling your wrist upwards and exhaling.', 'Slowly lower your wrists back down to the starting position while inhaling. Make sure to inhale during this part of the exercise. Tip: Your forearms should be stationary as your wrist is the only movement needed to perform this exercise.', 'Repeat for the recommended amount of repetitions.', 'When finished, simply lower the dumbbells to the floor.']::text[], ARRAY['Seated_Dumbbell_Palms-Up_Wrist_Curl/0.jpg', 'Seated_Dumbbell_Palms-Up_Wrist_Curl/1.jpg']::text[], 'seated dumbbell palms-up wrist curl cuon co tay nam ngua ta don ngoi curl de muneca supino sentado con mancuerna'),
  (NULL, 'Seated Dumbbell Press', 'Đẩy vai tạ đơn ngồi', 'Seated Dumbbell Press', 'Press sentado con mancuernas', 'shoulders', 'dumbbell', 'compound', 'free_exercise_db', 'Seated_Dumbbell_Press', ARRAY['Grab a couple of dumbbells and sit on a military press bench or a utility bench that has a back support on it as you place the dumbbells upright on top of your thighs.', 'Clean the dumbbells up one at a time by using your thighs to bring the dumbbells up to shoulder height at each side.', 'Rotate the wrists so that the palms of your hands are facing forward. This is your starting position.', 'As you exhale, push the dumbbells up until they touch at the top.', 'After a second pause, slowly come down back to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Seated_Dumbbell_Press/0.jpg', 'Seated_Dumbbell_Press/1.jpg']::text[], 'seated dumbbell press day vai ta don ngoi press sentado con mancuernas'),
  (NULL, 'Seated Flat Bench Leg Pull-In', 'Kéo gối ngồi trên ghế phẳng', 'Seated Flat Bench Leg Pull-In', 'Encogimiento de piernas sentado en banco plano', 'abs', 'bodyweight', 'bodyweight', 'free_exercise_db', 'Seated_Flat_Bench_Leg_Pull-In', ARRAY['Sit on a bench with the legs stretched out in front of you slightly below parallel and your arms holding on to the sides of the bench. Your torso should be leaning backwards around a 45-degree angle from the bench. This will be your starting position.', 'Bring the knees in toward you as you move your torso closer to them at the same time. Breathe out as you perform this movement.', 'After a second pause, go back to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Seated_Flat_Bench_Leg_Pull-In/0.jpg', 'Seated_Flat_Bench_Leg_Pull-In/1.jpg']::text[], 'seated flat bench leg pull-in keo goi ngoi tren ghe phang encogimiento de piernas sentado en banco plano'),
  (NULL, 'Seated Floor Hamstring Stretch', 'Giãn đùi sau ngồi trên sàn', 'Seated Floor Hamstring Stretch', 'Estiramiento de isquios sentado en el suelo', 'legs', 'other', 'timed', 'free_exercise_db', 'Seated_Floor_Hamstring_Stretch', ARRAY['Sit on a mat with your right leg extended in front of you and your left leg bent with your foot against your right inner thigh.', 'Lean forward from your hips and reach for your ankle until you feel a stretch in your hamstring. Hold for 15 seconds, then repeat for your other side.']::text[], ARRAY['Seated_Floor_Hamstring_Stretch/0.jpg', 'Seated_Floor_Hamstring_Stretch/1.jpg']::text[], 'seated floor hamstring stretch gian dui sau ngoi tren san estiramiento de isquios sentado en el suelo'),
  (NULL, 'Seated Front Deltoid', 'Giãn vai trước ngồi', 'Seated Front Deltoid', 'Estiramiento de deltoides frontal sentado', 'shoulders', 'bodyweight', 'timed', 'free_exercise_db', 'Seated_Front_Deltoid', ARRAY['Sit upright on the floor with your legs bent, your partner standing behind you. Stick your arms straight out to your sides, with your palms facing the ground. Attempt to move them as far behind you as possible, as your assistant holds your wrists. This will be your starting position.', 'Keeping your elbows straight, attempt to move your arms to the front, with your partner gently restraining you to prevent any actual movement for 10-20 seconds.', 'Now, relax your muscles and allow your partner to gently increase the stretch on the shoulders and chest. Hold for 10 to 20 seconds.']::text[], ARRAY['Seated_Front_Deltoid/0.jpg', 'Seated_Front_Deltoid/1.jpg']::text[], 'seated front deltoid gian vai truoc ngoi estiramiento de deltoides frontal sentado'),
  (NULL, 'Seated Glute', 'Giãn mông ngồi', 'Seated Glute', 'Estiramiento de glúteo sentado', 'glutes', 'bodyweight', 'timed', 'free_exercise_db', 'Seated_Glute', ARRAY['In a seated position with your knees bent, cross one ankle over the opposite knee. Your partner will stand behind you. Now, lean forward as your partner braces your shoulders with their hands. This will be your starting position.', 'Attempt to push your torso back for 10-20 seconds, as your partner prevents any actual movement of your torso.', 'Now relax your muscles as your partner increases the stretch by gently pushing your torso forward for 10-20 seconds.']::text[], ARRAY['Seated_Glute/0.jpg', 'Seated_Glute/1.jpg']::text[], 'seated glute gian mong ngoi estiramiento de gluteo sentado'),
  (NULL, 'Seated Good Mornings', 'Seated Good Mornings', 'Seated Good Mornings', 'Buenos días sentado', 'back', 'barbell', 'compound', 'free_exercise_db', 'Seated_Good_Mornings', ARRAY['Set up a box in a power rack. The pins should be set at an appropriate height. Begin by stepping under the bar and placing it across the back of the shoulders, not on top of your traps. Squeeze your shoulder blades together and rotate your elbows forward, attempting to bend the bar across your shoulders.', 'Remove the bar from the rack, creating a tight arch in your lower back. Keep your head facing forward. With your back, shoulders, and core tight, push your knees and butt out and you begin your descent. Sit back with your hips until you are seated on the box. This will be your starting position.', 'Keeping the bar tight, bend forward at the hips as much as possible. If you set the pins to what would be parallel, you not only have a safety if you fail, but know when to stop.', 'Pause just above the pins and reverse the motion until your torso it upright.']::text[], ARRAY['Seated_Good_Mornings/0.jpg', 'Seated_Good_Mornings/1.jpg']::text[], 'seated good mornings good morning ngoi buenos dias sentado'),
  (NULL, 'Seated Hamstring', 'Giãn đùi sau ngồi', 'Seated Hamstring', 'Estiramiento de isquios sentado', 'legs', 'other', 'timed', 'free_exercise_db', 'Seated_Hamstring', ARRAY['In a seated position with your legs extended, have your partner stand behind you. Now, lean forward as your partner braces your shoulders with their hands. This will be your starting position.', 'Attempt to push your torso back for 10-20 seconds, as your partner prevents any actual movement of your torso.', 'Now relax your muscles as your partner increases the stretch by gently pushing your torso forward for 10-20 seconds.']::text[], ARRAY['Seated_Hamstring/0.jpg', 'Seated_Hamstring/1.jpg']::text[], 'seated hamstring gian dui sau ngoi estiramiento de isquios sentado'),
  (NULL, 'Seated Hamstring and Calf Stretch', 'Giãn đùi sau và bắp chân ngồi', 'Seated Hamstring and Calf Stretch', 'Estiramiento de isquios y gemelos sentado', 'legs', 'other', 'timed', 'free_exercise_db', 'Seated_Hamstring_and_Calf_Stretch', ARRAY['Loop a belt, rope, or band around one foot. Sit down with both legs extended . This will be your starting position.', 'Leaning forward slightly, pull on the belt to draw the toes of your foot back. Hold this position for 10-20 seconds and then repeat with the other leg.']::text[], ARRAY['Seated_Hamstring_and_Calf_Stretch/0.jpg', 'Seated_Hamstring_and_Calf_Stretch/1.jpg']::text[], 'seated hamstring and calf stretch gian dui sau va bap chan ngoi estiramiento de isquios y gemelos sentado'),
  (NULL, 'Seated Head Harness Neck Resistance', 'Kháng lực cổ với dây đeo đầu ngồi', 'Seated Head Harness Neck Resistance', 'Resistencia de cuello con arnés sentado', 'shoulders', 'other', 'isolation', 'free_exercise_db', 'Seated_Head_Harness_Neck_Resistance', ARRAY['Place a neck strap on the floor at the end of a flat bench. Once you have selected the weights, sit at the end of the flat bench with your feet wider than shoulder width apart from each other. Your toes should be pointed out.', 'Slowly move your torso forward until it is almost parallel with the floor. Using both hands, securely position the neck strap around your head. Tip: Make sure the weights are still lying on the floor to prevent any strain on the neck. Now grab the weight with both hands while elevating your torso back until it is almost perpendicular to the floor. Note: Your head and torso needs to be slightly tilted forward to perform this exercise.', 'Now place both hands on top of your knees. This is the starting position.', 'Slowly lower your neck down until your chin touches the upper part of your chest while breathing in.', 'While exhaling, bring your neck back to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Seated_Head_Harness_Neck_Resistance/0.jpg', 'Seated_Head_Harness_Neck_Resistance/1.jpg']::text[], 'seated head harness neck resistance khang luc co voi day deo dau ngoi resistencia de cuello con arnes sentado'),
  (NULL, 'Seated Leg Curl', 'Seated Leg Curl', 'Seated Leg Curl', 'Curl femoral sentado', 'legs', 'machine', 'isolation', 'free_exercise_db', 'Seated_Leg_Curl', ARRAY['Adjust the machine lever to fit your height and sit on the machine with your back against the back support pad.', 'Place the back of lower leg on top of padded lever (just a few inches under the calves) and secure the lap pad against your thighs, just above the knees. Then grasp the side handles on the machine as you point your toes straight (or you can also use any of the other two stances) and ensure that the legs are fully straight right in front of you. This will be your starting position.', 'As you exhale, pull the machine lever as far as possible to the back of your thighs by flexing at the knees. Keep your torso stationary at all times. Hold the contracted position for a second.', 'Slowly return to the starting position as you breathe in.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Seated_Leg_Curl/0.jpg', 'Seated_Leg_Curl/1.jpg']::text[], 'seated leg curl cuon dui sau ngoi curl femoral sentado'),
  (NULL, 'Seated Leg Tucks', 'Co chân ngồi', 'Seated Leg Tucks', 'Encogimiento de piernas sentado', 'abs', 'bodyweight', 'bodyweight', 'free_exercise_db', 'Seated_Leg_Tucks', ARRAY['Sit on a bench with the legs stretched out in front of you slightly below parallel and your arms holding on to the sides of the bench. Your torso should be leaning backwards around a 45-degree angle from the bench. This will be your starting position.', 'Bring the knees in toward you as you move your torso closer to them at the same time. Breathe out as you perform this movement.', 'After a second pause, go back to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Seated_Leg_Tucks/0.jpg', 'Seated_Leg_Tucks/1.jpg']::text[], 'seated leg tucks co chan ngoi encogimiento de piernas sentado'),
  (NULL, 'Seated One-Arm Dumbbell Palms-Down Wrist Curl', 'Seated One-Arm Dumbbell Palms-Down Wrist Curl', 'Seated One-Arm Dumbbell Palms-Down Wrist Curl', 'Curl de muñeca prono a una mano sentado', 'biceps', 'dumbbell', 'isolation', 'free_exercise_db', 'Seated_One-Arm_Dumbbell_Palms-Down_Wrist_Curl', ARRAY['Sit on a flat bench with a dumbbell in your right hand.', 'Place your feet flat on the floor, at a distance that is slightly wider than shoulder width apart.', 'Lean forward and place your right forearm on top of your upper right thigh with your palm down. Tip: Make sure that the back of the wrist lies on top of your knees. This will be your starting position.', 'Lower the dumbbell as far as possible as you keep a tight grip on the dumbbell. Inhale as you perform this movement.', 'Now curl the dumbbell as high as possible as you contract the forearms and as you exhale. Keep the contraction for a second before you lower again. Tip: The only movement should happen at the wrist.', 'Perform for the recommended amount of repetitions, switch arms and repeat the movement.']::text[], ARRAY['Seated_One-Arm_Dumbbell_Palms-Down_Wrist_Curl/0.jpg', 'Seated_One-Arm_Dumbbell_Palms-Down_Wrist_Curl/1.jpg']::text[], 'seated one-arm dumbbell palms-down wrist curl cuon co tay nam up mot tay ta don ngoi curl de muneca prono a una mano sentado'),
  (NULL, 'Seated One-Arm Dumbbell Palms-Up Wrist Curl', 'Seated One-Arm Dumbbell Palms-Up Wrist Curl', 'Seated One-Arm Dumbbell Palms-Up Wrist Curl', 'Curl de muñeca supino a una mano sentado', 'biceps', 'dumbbell', 'isolation', 'free_exercise_db', 'Seated_One-Arm_Dumbbell_Palms-Up_Wrist_Curl', ARRAY['Sit on a flat bench with a dumbbell in your right hand.', 'Place your feet flat on the floor, at a distance that is slightly wider than shoulder width apart.', 'Lean forward and place your right forearm on top of your upper right thigh with your palm up. Tip: Make sure that the front of the wrist lies on top of your knees. This will be your starting position.', 'Lower the dumbbell as far as possible as you keep a tight grip on the dumbbell. Inhale as you perform this movement.', 'Now curl the dumbbell as high as possible as you contract the forearms and as you exhale. Keep the contraction for a second before you lower again. Tip: The only movement should happen at the wrist.', 'Perform for the recommended amount of repetitions, switch arms and repeat the movement.']::text[], ARRAY['Seated_One-Arm_Dumbbell_Palms-Up_Wrist_Curl/0.jpg', 'Seated_One-Arm_Dumbbell_Palms-Up_Wrist_Curl/1.jpg']::text[], 'seated one-arm dumbbell palms-up wrist curl cuon co tay nam ngua mot tay ta don ngoi curl de muneca supino a una mano sentado'),
  (NULL, 'Seated One-arm Cable Pulley Rows', 'Chèo cáp một tay ngồi', 'Seated One-arm Cable Pulley Rows', 'Remo sentado a una mano en polea', 'back', 'cable', 'compound', 'free_exercise_db', 'Seated_One-arm_Cable_Pulley_Rows', ARRAY['To get into the starting position, first sit down on the machine and place your feet on the front platform or crossbar provided making sure that your knees are slightly bent and not locked.', 'Lean over as you keep the natural alignment of your back and grab the single handle attachment with your left arm using a palms-down grip.', 'With your arm extended pull back until your torso is at a 90-degree angle from your legs. Your back should be slightly arched and your chest should be sticking out. You should be feeling a nice stretch on your lat as you hold the bar in front of you. The right arm can be kept by the waist. This is the starting position of the exercise.', 'Keeping the torso stationary, pull the handles back towards your torso while keeping the arms close to it as you rotate the wrist, so that by the time your hand is by your abdominals it is in a neutral position (palms facing the torso). Breathe out as you perform that movement. At that point you should be squeezing your back muscles hard.', 'Hold that contraction for a second and slowly go back to the original position while breathing in. Tip: Remember to rotate the wrist as you go back to the starting position so that the palms are facing down again.', 'Repeat for the recommended amount of repetitions and then perform the same movement with the right hand.']::text[], ARRAY['Seated_One-arm_Cable_Pulley_Rows/0.jpg', 'Seated_One-arm_Cable_Pulley_Rows/1.jpg']::text[], 'seated one-arm cable pulley rows cheo cap mot tay ngoi remo sentado a una mano en polea'),
  (NULL, 'Seated Overhead Stretch', 'Giãn cơ qua đầu ngồi', 'Seated Overhead Stretch', 'Estiramiento sentado sobre la cabeza', 'abs', 'other', 'timed', 'free_exercise_db', 'Seated_Overhead_Stretch', ARRAY['Sit up straight on an exercise mat.', 'Touch the soles of your feet together with your feet six to eight inches in front of your hips.', 'Place one hand on the floor beside you and your other hand behind your head.', 'Lift your elbow to the ceiling as you incline your torso to the other side. Hold for 10 to 20 seconds, then switch sides.']::text[], ARRAY['Seated_Overhead_Stretch/0.jpg', 'Seated_Overhead_Stretch/1.jpg']::text[], 'seated overhead stretch gian co qua dau ngoi estiramiento sentado sobre la cabeza'),
  (NULL, 'Seated Palm-Up Barbell Wrist Curl', 'Seated Palm-Up Barbell Wrist Curl', 'Seated Palm-Up Barbell Wrist Curl', 'Curl de muñeca supino sentado con barra', 'biceps', 'barbell', 'isolation', 'free_exercise_db', 'Seated_Palm-Up_Barbell_Wrist_Curl', ARRAY['Hold a barbell with both hands and your palms facing up; hands spaced about shoulder width.', 'Place your feet flat on the floor, at a distance that is slightly wider than shoulder width apart.', 'Lean forward and place your forearms on top of your upper thighs with your palms up. Tip: Make sure that the front of the wrists lay on top of your knees. This will be your starting position.', 'Lower the bar as far as possible while inhaling and keeping a tight grip.', 'Now curl bar up as high as possible while flexing the forearms and exhaling. Hold the contraction at the top for a second and Tip: Only the wrist should move.']::text[], ARRAY['Seated_Palm-Up_Barbell_Wrist_Curl/0.jpg', 'Seated_Palm-Up_Barbell_Wrist_Curl/1.jpg']::text[], 'seated palm-up barbell wrist curl cuon co tay nam ngua ta don ngoi curl de muneca supino sentado con barra'),
  (NULL, 'Seated Palms-Down Barbell Wrist Curl', 'Seated Palms-Down Barbell Wrist Curl', 'Seated Palms-Down Barbell Wrist Curl', 'Curl de muñeca prono sentado con barra', 'biceps', 'barbell', 'isolation', 'free_exercise_db', 'Seated_Palms-Down_Barbell_Wrist_Curl', ARRAY['Hold a barbell with both hands and your palms facing down; hands spaced about shoulder width.', 'Place your feet flat on the floor, at a distance that is slightly wider than shoulder width apart.', 'Lean forward and place your forearms on top of your upper thighs with your palms down. Tip: Make sure that the back of the wrists lay on top of your knees. This will be your starting position.', 'Lower the bar as far as possible while inhaling and keeping a tight grip.', 'Now curl bar up as high as possible while flexing the forearms and exhaling. Hold the contraction at the top for a second and Tip: Only the wrist should move.']::text[], ARRAY['Seated_Palms-Down_Barbell_Wrist_Curl/0.jpg', 'Seated_Palms-Down_Barbell_Wrist_Curl/1.jpg']::text[], 'seated palms-down barbell wrist curl cuon co tay nam up ta don ngoi curl de muneca prono sentado con barra'),
  (NULL, 'Seated Side Lateral Raise', 'Nâng tạ ngang ngồi', 'Seated Side Lateral Raise', 'Elevación lateral sentado', 'shoulders', 'dumbbell', 'isolation', 'free_exercise_db', 'Seated_Side_Lateral_Raise', ARRAY['Pick a couple of dumbbells and sit at the end of a flat bench with your feet firmly on the floor. Hold the dumbbells with your palms facing in and your arms straight down at your sides at arms'' length. This will be your starting position.', 'While maintaining the torso stationary (no swinging), lift the dumbbells to your side with a slight bend on the elbow and the hands slightly tilted forward as if pouring water in a glass. Continue to go up until you arms are parallel to the floor. Exhale as you execute this movement and pause for a second at the top.', 'Lower the dumbbells back down slowly to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Seated_Side_Lateral_Raise/0.jpg', 'Seated_Side_Lateral_Raise/1.jpg']::text[], 'seated side lateral raise nang ta ngang ngoi elevacion lateral sentado'),
  (NULL, 'Seated Triceps Press', 'Đẩy tay sau ngồi', 'Seated Triceps Press', 'Press de tríceps sentado', 'triceps', 'dumbbell', 'isolation', 'free_exercise_db', 'Seated_Triceps_Press', ARRAY['Sit down on a bench with back support and grasp a dumbbell with both hands and hold it overhead at arm''s length. Tip: a better way is to have somebody hand it to you especially if it is very heavy. The resistance should be resting in the palms of your hands with your thumbs around it. The palm of the hand should be facing inward. This will be your starting position.', 'Keeping your upper arms close to your head (elbows in) and perpendicular to the floor, lower the resistance in a semi-circular motion behind your head until your forearms touch your biceps. Tip: The upper arms should remain stationary and only the forearms should move. Breathe in as you perform this step.', 'Go back to the starting position by using the triceps to raise the dumbbell. Breathe out as you perform this step.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Seated_Triceps_Press/0.jpg', 'Seated_Triceps_Press/1.jpg']::text[], 'seated triceps press day tay sau ngoi press de triceps sentado'),
  (NULL, 'Seated Two-Arm Palms-Up Low-Pulley Wrist Curl', 'Seated Two-Arm Palms-Up Low-Pulley Wrist Curl', 'Seated Two-Arm Palms-Up Low-Pulley Wrist Curl', 'Curl de muñeca supino sentado en polea baja', 'biceps', 'cable', 'isolation', 'free_exercise_db', 'Seated_Two-Arm_Palms-Up_Low-Pulley_Wrist_Curl', ARRAY['Put a bench in front of a low pulley machine that has a barbell or EZ Curl attachment on it.', 'Move the bench far enough away so that when you bring the handle to the top of your thighs tension is created on the cable due to the weight stack being moved up.', 'Now hold the handle with both hands, palms up, using a shoulder-width grip.', 'Step back and sit on the bench with your feet about shoulder width apart, firmly on the floor.', 'Lean forward and place the forearms on your thighs with the back of your wrists over your knees. This will be your starting position.', 'Lower the bar as far as possible, while inhaling and keeping a tight grip.', 'Now curl the bar up as high as possible while contracting the forearms. Tip: Only the wrist should move; not the forearms.', 'After a second contraction at the top go back to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Seated_Two-Arm_Palms-Up_Low-Pulley_Wrist_Curl/0.jpg', 'Seated_Two-Arm_Palms-Up_Low-Pulley_Wrist_Curl/1.jpg']::text[], 'seated two-arm palms-up low-pulley wrist curl cuon co tay nam ngua cap thap ngoi curl de muneca supino sentado en polea baja'),
  (NULL, 'See-Saw Press (Alternating Side Press)', 'Đẩy vai bập bênh (luân phiên)', 'See-Saw Press (Alternating Side Press)', 'Press balancín (alterno)', 'shoulders', 'dumbbell', 'compound', 'free_exercise_db', 'See-Saw_Press_Alternating_Side_Press', ARRAY['Grab a dumbbell with each hand and stand up erect.', 'Clean (lift) the dumbbells to the chest/shoulder level and then rotate your wrists so that your palms are facing towards you as if you were getting ready to perform an Arnold Press. This will be your starting position.', 'Now start extending your left arm overhead as you rotate the wrist so that the palm of your hand faces forward as you go up. Your elbows should come out also as you lift the weight. Simultaneously, you will also be bending from your hip to your opposite side. Tip: If you perform the exercise correctly, is should look as if you are trying to reach for something overhead on the right hand side of your body, but with your left arm. Breathe out as you perform this movement.', 'Once you reach the top position breathe in. Then, with the weight fully extended overhead and you bent over to your right hand side, begin the movement to the left side.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['See-Saw_Press_Alternating_Side_Press/0.jpg', 'See-Saw_Press_Alternating_Side_Press/1.jpg']::text[], 'see-saw press (alternating side press) day vai bap benh (luan phien) press balancin (alterno)'),
  (NULL, 'Shotgun Row', 'Chèo cáp kiểu shotgun', 'Shotgun Row', 'Remo shotgun', 'back', 'cable', 'compound', 'free_exercise_db', 'Shotgun_Row', ARRAY['Attach a single handle to a low cable.', 'After selecting the correct weight, stand a couple feet back with a wide-split stance. Your arm should be extended and your shoulder forward. This will be your starting position.', 'Perform the movement by retracting the shoulder and flexing the elbow. As you pull, supinate the wrist, turning the palm upward as you go.', 'After a brief pause, return to the starting position.']::text[], ARRAY['Shotgun_Row/0.jpg', 'Shotgun_Row/1.jpg']::text[], 'shotgun row cheo cap kieu shotgun remo shotgun'),
  (NULL, 'Shoulder Circles', 'Xoay vai', 'Shoulder Circles', 'Círculos de hombros', 'shoulders', 'other', 'timed', 'free_exercise_db', 'Shoulder_Circles', ARRAY['With shoulders relaxed and arms resting loosely at your sides (or in your lap if you''re seated), gently roll your shoulders forward, up, back, and down.', 'Reverse direction. You can do this exercise alternating shoulders or both at the same time.']::text[], ARRAY['Shoulder_Circles/0.jpg', 'Shoulder_Circles/1.jpg']::text[], 'shoulder circles xoay vai circulos de hombros'),
  (NULL, 'Shoulder Press - With Bands', 'Đẩy vai dây kháng lực', 'Shoulder Press - With Bands', 'Press de hombros con bandas', 'shoulders', 'band', 'compound', 'free_exercise_db', 'Shoulder_Press_-_With_Bands', ARRAY['To begin, stand on an exercise band so that tension begins at arm''s length. Grasp the handles and lift them so that the hands are at shoulder height at each side.', 'Rotate the wrists so that the palms of your hands are facing forward. Your elbows should be bent, with the upper arms and forearms in line to the torso. This is your starting position.', 'As you exhale, lift the handles up until your arms are fully extended overhead.']::text[], ARRAY['Shoulder_Press_-_With_Bands/0.jpg', 'Shoulder_Press_-_With_Bands/1.jpg']::text[], 'shoulder press - with bands day vai day khang luc press de hombros con bandas'),
  (NULL, 'Shoulder Raise', 'Nâng vai', 'Shoulder Raise', 'Elevación de hombros', 'shoulders', 'other', 'timed', 'free_exercise_db', 'Shoulder_Raise', ARRAY['Relax your arms to your sides and raise your shoulders up toward your ears, then back down.']::text[], ARRAY['Shoulder_Raise/0.jpg', 'Shoulder_Raise/1.jpg']::text[], 'shoulder raise nang vai elevacion de hombros'),
  (NULL, 'Shoulder Stretch', 'Giãn vai', 'Shoulder Stretch', 'Estiramiento de hombro', 'shoulders', 'other', 'timed', 'free_exercise_db', 'Shoulder_Stretch', ARRAY['Reach your left arm across your body and hold it straight.']::text[], ARRAY['Shoulder_Stretch/0.jpg', 'Shoulder_Stretch/1.jpg']::text[], 'shoulder stretch gian vai estiramiento de hombro'),
  (NULL, 'Side-Lying Floor Stretch', 'Giãn cơ nằm nghiêng trên sàn', 'Side-Lying Floor Stretch', 'Estiramiento de lado en el suelo', 'back', 'other', 'timed', 'free_exercise_db', 'Side-Lying_Floor_Stretch', ARRAY['First lie on your left side, bending your left knee in front of you to stabilize your torso (use your abdominal muscles as well to hold you upright).', 'Straighten your right leg and rest the right foot on the floor behind your left. Straighten your right arm over your head and gently pull on your right wrist to stretch the entire right side of the body. Switch sides.']::text[], ARRAY['Side-Lying_Floor_Stretch/0.jpg', 'Side-Lying_Floor_Stretch/1.jpg']::text[], 'side-lying floor stretch gian co nam nghieng tren san estiramiento de lado en el suelo'),
  (NULL, 'Side Bridge', 'Plank nghiêng', 'Side Bridge', 'Plancha lateral', 'abs', 'bodyweight', 'bodyweight', 'free_exercise_db', 'Side_Bridge', ARRAY[]::text[], ARRAY['Side_Bridge/0.jpg', 'Side_Bridge/1.jpg']::text[], 'side bridge plank nghieng plancha lateral'),
  (NULL, 'Side Hop-Sprint', 'Bật nhảy ngang rồi chạy nước rút', 'Side Hop-Sprint', 'Salto lateral y sprint', 'legs', 'other', 'compound', 'free_exercise_db', 'Side_Hop-Sprint', ARRAY['Stand to the side of a cone or hurdle.', 'Begin this drill by hopping sideways over the obstacle, rebounding out of your landing to hop back to where you started.', 'Hop for a prescribed number or repetitions as quickly as possible, and finish this drill by sprinting a short distance upon landing the last hop.']::text[], ARRAY['Side_Hop-Sprint/0.jpg', 'Side_Hop-Sprint/1.jpg']::text[], 'side hop-sprint bat nhay ngang roi chay nuoc rut salto lateral y sprint'),
  (NULL, 'Side Jackknife', 'Gập bụng dao gấp nghiêng', 'Side Jackknife', 'Navaja lateral', 'abs', 'bodyweight', 'bodyweight', 'free_exercise_db', 'Side_Jackknife', ARRAY[]::text[], ARRAY['Side_Jackknife/0.jpg', 'Side_Jackknife/1.jpg']::text[], 'side jackknife gap bung dao gap nghieng navaja lateral'),
  (NULL, 'Side Lateral Raise', 'Nâng tạ ngang', 'Side Lateral Raise', 'Elevación lateral', 'shoulders', 'dumbbell', 'isolation', 'free_exercise_db', 'Side_Lateral_Raise', ARRAY['Pick a couple of dumbbells and stand with a straight torso and the dumbbells by your side at arms length with the palms of the hand facing you. This will be your starting position.', 'While maintaining the torso in a stationary position (no swinging), lift the dumbbells to your side with a slight bend on the elbow and the hands slightly tilted forward as if pouring water in a glass. Continue to go up until you arms are parallel to the floor. Exhale as you execute this movement and pause for a second at the top.', 'Lower the dumbbells back down slowly to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Side_Lateral_Raise/0.jpg', 'Side_Lateral_Raise/1.jpg']::text[], 'side lateral raise nang ta ngang elevacion lateral'),
  (NULL, 'Side Laterals to Front Raise', 'Nâng tạ ngang chuyển ra trước', 'Side Laterals to Front Raise', 'Elevación lateral a frontal', 'shoulders', 'dumbbell', 'isolation', 'free_exercise_db', 'Side_Laterals_to_Front_Raise', ARRAY['In a standing position, hold a pair of dumbbells at your side. This will be your starting position.', 'Keeping your elbows slightly bent, raise the weights directly in front of you to shoulder height, avoiding any swinging or cheating.', 'At the top of the exercise move the weights out in front of you, keeping your arms extended.', 'Lower the weights with a controlled motion.', 'On the next repetition, raise the weights in front of you to shoulder height before moving the weights laterally to your sides.', 'Lower the weights to the starting position.']::text[], ARRAY['Side_Laterals_to_Front_Raise/0.jpg', 'Side_Laterals_to_Front_Raise/1.jpg']::text[], 'side laterals to front raise nang ta ngang chuyen ra truoc elevacion lateral a frontal'),
  (NULL, 'Side Leg Raises', 'Nâng chân ngang', 'Side Leg Raises', 'Elevaciones laterales de pierna', 'legs', 'bodyweight', 'timed', 'free_exercise_db', 'Side_Leg_Raises', ARRAY['Stand next to a chair, which you may hold onto as a support. Stand on one leg. This will be your starting position.', 'Keeping your leg straight, raise it as far out to the side as possible, and swing it back down, allowing it to cross the opposite leg.', 'Repeat this swinging motion 5-10 times, increasing the range of motion as you do so.']::text[], ARRAY['Side_Leg_Raises/0.jpg', 'Side_Leg_Raises/1.jpg']::text[], 'side leg raises nang chan ngang elevaciones laterales de pierna'),
  (NULL, 'Side Lying Groin Stretch', 'Giãn háng nằm nghiêng', 'Side Lying Groin Stretch', 'Estiramiento de ingle de lado', 'legs', 'other', 'timed', 'free_exercise_db', 'Side_Lying_Groin_Stretch', ARRAY['Start off by lying on your right side and bend your right knee in front of you to stabilize the torso.', 'Rest your head on your right hand or shoulder. Lift your left leg upward and hold it by the back of the knee (easier) or the foot (harder).', 'Pull your left knee in toward your left shoulder and simultaneously press your foot or knee down to the floor. To intensify this stretch, straighten your left leg. Switch sides.']::text[], ARRAY['Side_Lying_Groin_Stretch/0.jpg', 'Side_Lying_Groin_Stretch/1.jpg']::text[], 'side lying groin stretch gian hang nam nghieng estiramiento de ingle de lado'),
  (NULL, 'Side Neck Stretch', 'Giãn cổ nghiêng', 'Side Neck Stretch', 'Estiramiento lateral de cuello', 'shoulders', 'other', 'timed', 'free_exercise_db', 'Side_Neck_Stretch', ARRAY['Start with your shoulders relaxed, gently tilt your head towards your shoulder.', 'Assist stretch with a gentle pull on the side of the head.']::text[], ARRAY['Side_Neck_Stretch/0.jpg', 'Side_Neck_Stretch/1.jpg']::text[], 'side neck stretch gian co nghieng estiramiento lateral de cuello'),
  (NULL, 'Side Standing Long Jump', 'Bật xa ngang tại chỗ', 'Side Standing Long Jump', 'Salto largo lateral de pie', 'legs', 'other', 'bodyweight', 'free_exercise_db', 'Side_Standing_Long_Jump', ARRAY['Begin standing with your feet hip width apart in an athletic stance. Your head and chest should be up, knees and hips slightly bent. This will be your starting position.', 'Leaning to your right, extend through your hips, knees, and ankles to jump into the air. Block with the arms to lead the movement, jumping as far to your right as you can.', 'Land facing the same direction with your feet hip width apart, absorbing the impact through your lower body.']::text[], ARRAY['Side_Standing_Long_Jump/0.jpg', 'Side_Standing_Long_Jump/1.jpg']::text[], 'side standing long jump bat xa ngang tai cho salto largo lateral de pie'),
  (NULL, 'Side To Side Chins', 'Hít xà dịch hai bên', 'Side To Side Chins', 'Dominadas de lado a lado', 'back', 'other', 'compound', 'free_exercise_db', 'Side_To_Side_Chins', ARRAY['Grab the pull-up bar with the palms facing forward using a wide grip.', 'As you have both arms extended in front of you holding the bar at a wide grip, bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.', 'Pull your torso up while leaning to the left hand side until the bar almost touches your upper chest by drawing the shoulders and the upper arms down and back. Exhale as you perform this portion of the movement. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary as it moves through space (no swinging) and only the arms should move. The forearms should do no other work other than hold the bar.', 'After a second of contraction, inhale as you go back to the starting position.', 'Now, pull your torso up while leaning to the right hand side until the bar almost touches your upper chest by drawing the shoulders and the upper arms down and back. Exhale as you perform this portion of the movement. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary as it moves through space and only the arms should move. The forearms should do no other work other than hold the bar.', 'After a second of contraction, inhale as you go back to the starting position.', 'Repeat steps 3-6 until you have performed the prescribed amount of repetitions for each side.']::text[], ARRAY['Side_To_Side_Chins/0.jpg', 'Side_To_Side_Chins/1.jpg']::text[], 'side to side chins hit xa dich hai ben dominadas de lado a lado'),
  (NULL, 'Side Wrist Pull', 'Kéo cổ tay nghiêng', 'Side Wrist Pull', 'Tirón lateral de muñeca', 'shoulders', 'other', 'timed', 'free_exercise_db', 'Side_Wrist_Pull', ARRAY['This stretch works best standing. Cross your left arm over the midline of your body and hold the left wrist in your right hand down at the level of your hips. Start the stretch with a bent left arm.', 'Slowly straighten, pull, and lift it up to shoulder height, as pictured. Feel this stretch originate in your back, not your shoulders, and don''t pull too hard on the shoulders joint. Switch sides.']::text[], ARRAY['Side_Wrist_Pull/0.jpg', 'Side_Wrist_Pull/1.jpg']::text[], 'side wrist pull keo co tay nghieng tiron lateral de muneca'),
  (NULL, 'Side to Side Box Shuffle', 'Bước chạm bục qua lại', 'Side to Side Box Shuffle', 'Desplazamiento lateral sobre cajón', 'legs', 'other', 'compound', 'free_exercise_db', 'Side_to_Side_Box_Shuffle', ARRAY['Stand to one side of the box with your left foot resting on the middle of it.', 'To begin, jump up and over to the other side of the box, landing with your right foot on top of the box and your left foot on the floor. Swing your arms to aid your movement.', 'Continue shuffling back and forth across the box.']::text[], ARRAY['Side_to_Side_Box_Shuffle/0.jpg', 'Side_to_Side_Box_Shuffle/1.jpg']::text[], 'side to side box shuffle buoc cham buc qua lai desplazamiento lateral sobre cajon'),
  (NULL, 'Single-Arm Cable Crossover', 'Single-Arm Cable Crossover', 'Single-Arm Cable Crossover', 'Cruce de poleas a una mano', 'chest', 'cable', 'isolation', 'free_exercise_db', 'Single-Arm_Cable_Crossover', ARRAY['Begin by moving the pulleys to the high position, select the resistance to be used, and take a handle in each hand.', 'Step forward in front of both pulleys with your arms extended in front of you, bringing your hands together. Your head and chest should be up as you lean forward, while your feet should be staggered. This will be your starting position.', 'Keeping your left arm in place, allow your right arm to extend out to the side, maintaining a slight bend at the elbow. The right arm should be perpendicular to the body at approximately shoulder level.', 'Return your arm back to the starting position by pulling your hand back to the midline of the body.', 'Hold for a second at the starting position and repeat the movement on the opposite side. Continue alternating back and forth for the prescribed number of repetitions.']::text[], ARRAY['Single-Arm_Cable_Crossover/0.jpg', 'Single-Arm_Cable_Crossover/1.jpg']::text[], 'single-arm cable crossover ep nguc cap cheo mot tay cruce de poleas a una mano'),
  (NULL, 'Single-Arm Linear Jammer', 'Đẩy landmine một tay', 'Single-Arm Linear Jammer', 'Landmine a una mano', 'shoulders', 'barbell', 'compound', 'free_exercise_db', 'Single-Arm_Linear_Jammer', ARRAY['Position a bar into a landmine or securely anchor it in a corner. Load the bar to an appropriate weight.', 'Raise the bar from the floor, taking it to your shoulders with one or both hands. Adopt a wide stance. This will be your starting position.', 'Perform the movement by extending the elbow, pressing the weight up. Move explosively, extending the hips and knees fully to produce maximal force.', 'Return to the starting position.']::text[], ARRAY['Single-Arm_Linear_Jammer/0.jpg', 'Single-Arm_Linear_Jammer/1.jpg']::text[], 'single-arm linear jammer day landmine mot tay landmine a una mano'),
  (NULL, 'Single-Arm Push-Up', 'Hít đất một tay', 'Single-Arm Push-Up', 'Flexión a una mano', 'chest', 'bodyweight', 'bodyweight', 'free_exercise_db', 'Single-Arm_Push-Up', ARRAY['Begin laying prone on the ground. Move yourself into a position supporting your weight on your toes and one arm. Your working arm should be placed directly under the shoulder, fully extended. Your legs should be extended, and for this movement you may need a wider base, placing your feet further apart than in a normal push-up.', 'Maintain good posture, and place your free hand behind your back. This will be your starting position.', 'Lower yourself by allowing the elbow to flex until you touch the ground.', 'Descend slowly, and reverse direction be extending the arm to return to the starting position.']::text[], ARRAY['Single-Arm_Push-Up/0.jpg', 'Single-Arm_Push-Up/1.jpg']::text[], 'single-arm push-up hit dat mot tay flexion a una mano'),
  (NULL, 'Single-Cone Sprint Drill', 'Chạy nước rút quanh một cọc', 'Single-Cone Sprint Drill', 'Sprint alrededor de un cono', 'legs', 'other', 'compound', 'free_exercise_db', 'Single-Cone_Sprint_Drill', ARRAY['This drill teaches quick foot action. You need a single cone. Begin standing next to the cone with one arm back and one arm forward.', 'Chop the feet as quickly as possible, blocking with the arms. Circle the cone, keep your knees up, with violent foot action.', 'Rest after three trips around the cone.']::text[], ARRAY['Single-Cone_Sprint_Drill/0.jpg', 'Single-Cone_Sprint_Drill/1.jpg']::text[], 'single-cone sprint drill chay nuoc rut quanh mot coc sprint alrededor de un cono'),
  (NULL, 'Single-Leg High Box Squat', 'Single-Leg High Box Squat', 'Single-Leg High Box Squat', 'Sentadilla a una pierna en cajón alto', 'legs', 'other', 'compound', 'free_exercise_db', 'Single-Leg_High_Box_Squat', ARRAY['Position a box in a rack. Secure a band or rope in place above the box.', 'Standing in front of it, step onto the box to a full standing position, letting your other leg remain unsupported. Hold onto the band for balance', '. Continue stepping up and down on the same leg before switching to the opposite side.']::text[], ARRAY['Single-Leg_High_Box_Squat/0.jpg', 'Single-Leg_High_Box_Squat/1.jpg']::text[], 'single-leg high box squat squat mot chan xuong buc cao sentadilla a una pierna en cajon alto'),
  (NULL, 'Single-Leg Hop Progression', 'Tiến trình bật nhảy một chân', 'Single-Leg Hop Progression', 'Progresión de saltos a una pierna', 'legs', 'other', 'compound', 'free_exercise_db', 'Single-Leg_Hop_Progression', ARRAY['Arrange a line of cones in front of you. Assume a relaxed standing position, balanced on one leg. Raise the knee of your opposite leg. This will be your starting position.', 'Hop forward, jumping and landing with the same leg over the cone.', 'Use a countermovement jump to hop from cone to cone.', 'At the end, turn around and go back on the other leg.']::text[], ARRAY['Single-Leg_Hop_Progression/0.jpg', 'Single-Leg_Hop_Progression/1.jpg']::text[], 'single-leg hop progression tien trinh bat nhay mot chan progresion de saltos a una pierna'),
  (NULL, 'Single-Leg Lateral Hop', 'Bật ngang một chân', 'Single-Leg Lateral Hop', 'Salto lateral a una pierna', 'legs', 'other', 'compound', 'free_exercise_db', 'Single-Leg_Lateral_Hop', ARRAY['Stand to the side of a cone or hurdle. To get into the start position, stand on one leg with your knee slightly bent.', 'To begin, execute a counterjump to hop sideways over the cone.', 'Land on your jumping leg, and immediately rebound out of it by jumping back to the start position.', 'Continue hopping back and forth.']::text[], ARRAY['Single-Leg_Lateral_Hop/0.jpg', 'Single-Leg_Lateral_Hop/1.jpg']::text[], 'single-leg lateral hop bat ngang mot chan salto lateral a una pierna'),
  (NULL, 'Single-Leg Leg Extension', 'Duỗi đùi một chân', 'Single-Leg Leg Extension', 'Extensión de pierna a una pierna', 'legs', 'machine', 'isolation', 'free_exercise_db', 'Single-Leg_Leg_Extension', ARRAY['Seat yourself in the machine and adjust it so that you are positioned properly. The pad should be against the lower part of the shin but not in contact with the ankle. Adjust the seat so that the pivot point is in line with your knee. Select a weight appropriate for your abilities.', 'Maintaining good posture, fully extend one leg, pausing at the top of the motion.', 'Return to the starting position without letting the weight stop, keeping tension on the muscle.', 'Repeat for the desired number of repetitions.']::text[], ARRAY['Single-Leg_Leg_Extension/0.jpg', 'Single-Leg_Leg_Extension/1.jpg']::text[], 'single-leg leg extension duoi dui mot chan extension de pierna a una pierna'),
  (NULL, 'Single-Leg Stride Jump', 'Bật sải một chân', 'Single-Leg Stride Jump', 'Salto de zancada a una pierna', 'legs', 'other', 'compound', 'free_exercise_db', 'Single-Leg_Stride_Jump', ARRAY['Stand to the side of a box with your inside foot on top of it, close to the edge.', 'Begin by swinging the arms upward as you push through the top leg, jumping upward as high as possible. Attempt to drive the opposite knee upward.', 'Land in the same position that you started, using your inside leg to decelerate the impact.']::text[], ARRAY['Single-Leg_Stride_Jump/0.jpg', 'Single-Leg_Stride_Jump/1.jpg']::text[], 'single-leg stride jump bat sai mot chan salto de zancada a una pierna'),
  (NULL, 'Single Dumbbell Raise', 'Nâng một tạ đơn', 'Single Dumbbell Raise', 'Elevación con una mancuerna', 'shoulders', 'dumbbell', 'isolation', 'free_exercise_db', 'Single_Dumbbell_Raise', ARRAY['With a wide stance, hold a dumbell with both hands, grasping the head of the dumbbell instead of the handle. Your arms should be extended and hanging at the waist. This will be your starting position.', 'Raise the weight until it is above shoulder level, keeping your arms extended. Your torso and hips should remain stationary throughout the movement.', 'Return to the starting position and repeat for the recommended amount of repetitions.']::text[], ARRAY['Single_Dumbbell_Raise/0.jpg', 'Single_Dumbbell_Raise/1.jpg']::text[], 'single dumbbell raise nang mot ta don elevacion con una mancuerna'),
  (NULL, 'Single Leg Butt Kick', 'Đá gót chạm mông một chân', 'Single Leg Butt Kick', 'Patada al glúteo a una pierna', 'legs', 'bodyweight', 'bodyweight', 'free_exercise_db', 'Single_Leg_Butt_Kick', ARRAY['Begin by standing on one leg, with the bent knee raised. This will be your start position.', 'Using a countermovement jump, take off upward by extending the hip, knee, and ankle of the grounded leg.', 'Immediately flex the knee and attempt to touch your butt with the heel of your jumping leg.', 'Return the leg to a partially bent position underneath the hips and land. Your opposite leg should stay in relatively the same position throughout the drill.']::text[], ARRAY['Single_Leg_Butt_Kick/0.jpg', 'Single_Leg_Butt_Kick/1.jpg']::text[], 'single leg butt kick da got cham mong mot chan patada al gluteo a una pierna'),
  (NULL, 'Single Leg Glute Bridge', 'Single Leg Glute Bridge', 'Single Leg Glute Bridge', 'Puente de glúteos a una pierna', 'glutes', 'bodyweight', 'bodyweight', 'free_exercise_db', 'Single_Leg_Glute_Bridge', ARRAY['Lay on the floor with your feet flat and knees bent.', 'Raise one leg off of the ground, pulling the knee to your chest. This will be your starting position.', 'Execute the movement by driving through the heel, extending your hip upward and raising your glutes off of the ground.', 'Extend as far as possible, pause and then return to the starting position.']::text[], ARRAY['Single_Leg_Glute_Bridge/0.jpg', 'Single_Leg_Glute_Bridge/1.jpg']::text[], 'single leg glute bridge cau mong mot chan puente de gluteos a una pierna'),
  (NULL, 'Single Leg Push-off', 'Đạp bật một chân', 'Single Leg Push-off', 'Impulso a una pierna', 'legs', 'other', 'compound', 'free_exercise_db', 'Single_Leg_Push-off', ARRAY['Stand on the ground with one foot resting on the box, heel close to the edge.', 'Push off with your foot on top of the box, trying to gain as much height as possible by extending through the hip and knee.', 'Land with the same foot on top of the box, returning your other foot back to the start position.']::text[], ARRAY['Single_Leg_Push-off/0.jpg', 'Single_Leg_Push-off/1.jpg']::text[], 'single leg push-off dap bat mot chan impulso a una pierna'),
  (NULL, 'Sit-Up', 'Gập bụng ngồi dậy', 'Sit-Up', 'Abdominales', 'abs', 'bodyweight', 'bodyweight', 'free_exercise_db', 'Sit-Up', ARRAY['Lie down on the floor placing your feet either under something that will not move or by having a partner hold them. Your legs should be bent at the knees.', 'Place your hands behind your head and lock them together by clasping your fingers. This is the starting position.', 'Elevate your upper body so that it creates an imaginary V-shape with your thighs. Breathe out when performing this part of the exercise.', 'Once you feel the contraction for a second, lower your upper body back down to the starting position while inhaling.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Sit-Up/0.jpg', 'Sit-Up/1.jpg']::text[], 'sit-up gap bung ngoi day abdominales'),
  (NULL, 'Sit Squats', 'Sit Squats', 'Sit Squats', 'Sentadilla sentada', 'legs', 'other', 'timed', 'free_exercise_db', 'Sit_Squats', ARRAY['Stand with your feet shoulder width apart. This will be your starting position.', 'Begin the movement by flexing your knees and hips, sitting back with your hips.', 'Continue until you have squatted a portion of the way down, but are above parallel, and quickly reverse the motion until you return to the starting position. Repeat for 5-10 repetitions.']::text[], ARRAY['Sit_Squats/0.jpg', 'Sit_Squats/1.jpg']::text[], 'sit squats squat ngoi xuong sentadilla sentada'),
  (NULL, 'Skating', 'Trượt patin (bật ngang)', 'Skating', 'Patinador', 'cardio', 'other', 'timed', 'free_exercise_db', 'Skating', ARRAY['Roller skating is a fun activity which can be effective in improving cardiorespiratory fitness and muscular endurance. It requires relatively good balance and coordination. It is necessary to learn the basics of skating including turning and stopping and to wear protective gear to avoid possible injury.', 'You can skate at a comfortable pace for 30 minutes straight. If you want a cardio challenge, do interval skating — speed skate two minutes of every five minutes, using the remaining three minutes to recover. A 150 lb person will typically burn about 175 calories in 30 minutes skating at a comfortable pace, similar to brisk walking.']::text[], ARRAY['Skating/0.jpg', 'Skating/1.jpg']::text[], 'skating truot patin (bat ngang) patinador'),
  (NULL, 'Sled Drag - Harness', 'Kéo xe trượt bằng đai', 'Sled Drag - Harness', 'Arrastre de trineo con arnés', 'legs', 'other', 'compound', 'free_exercise_db', 'Sled_Drag_-_Harness', ARRAY['To begin, load the sled with the desired weight and attach the pulling strap. You can pull with handles, use a harness, or attach the pulling strap to a weight belt.', 'Whether pulling forwards or backwards, lean in the direction of travel and progress by extending through the hips and knees.']::text[], ARRAY['Sled_Drag_-_Harness/0.jpg', 'Sled_Drag_-_Harness/1.jpg']::text[], 'sled drag - harness keo xe truot bang dai arrastre de trineo con arnes'),
  (NULL, 'Sled Overhead Backward Walk', 'Kéo xe trượt qua đầu đi lùi', 'Sled Overhead Backward Walk', 'Caminata hacia atrás con trineo sobre la cabeza', 'shoulders', 'other', 'compound', 'free_exercise_db', 'Sled_Overhead_Backward_Walk', ARRAY['Attach dual handles to a sled connected by a rope or chain. Load the sled to a light weight.', 'Face the sled, backing up until there is some tension in the line. Hold your hands directly above your head with your elbows extended. This will be your starting position.', 'Walk backwards, keeping your arms raised above your head. Avoid jerky movements.']::text[], ARRAY['Sled_Overhead_Backward_Walk/0.jpg', 'Sled_Overhead_Backward_Walk/1.jpg']::text[], 'sled overhead backward walk keo xe truot qua dau di lui caminata hacia atras con trineo sobre la cabeza'),
  (NULL, 'Sled Overhead Triceps Extension', 'Duỗi tay sau qua đầu với xe trượt', 'Sled Overhead Triceps Extension', 'Extensión de tríceps sobre la cabeza con trineo', 'triceps', 'other', 'isolation', 'free_exercise_db', 'Sled_Overhead_Triceps_Extension', ARRAY['Attach dual handles to a sled using a chain or rope. Load the sled to an appropriate load.', 'Facing away from the sled, step away until there is tension in the line. Raise your hands above your head, keeping them together, palms facing each other. Your elbows should be pointed upward with the elbows flexed. This will be your starting position.', 'Extend through the elbow to straighten the arm. Ensure that your upper arm stays in position to isolate the triceps.', 'Upon full extension, step forward to take the slack out of the line. You may keep your feet staggered for more stability.']::text[], ARRAY['Sled_Overhead_Triceps_Extension/0.jpg', 'Sled_Overhead_Triceps_Extension/1.jpg']::text[], 'sled overhead triceps extension duoi tay sau qua dau voi xe truot extension de triceps sobre la cabeza con trineo'),
  (NULL, 'Sled Push', 'Đẩy xe trượt', 'Sled Push', 'Empuje de trineo', 'legs', 'other', 'compound', 'free_exercise_db', 'Sled_Push', ARRAY['Load your pushing sled with the desired weight.', 'Take an athletic posture, leaning into the sled with your arms fully extended, grasping the handles. Push the sled as fast as possible, focusing on extending your hips and knees to strengthen your posterior chain.']::text[], ARRAY['Sled_Push/0.jpg', 'Sled_Push/1.jpg']::text[], 'sled push day xe truot empuje de trineo'),
  (NULL, 'Sled Reverse Flye', 'Sled Reverse Flye', 'Sled Reverse Flye', 'Aperturas invertidas con trineo', 'shoulders', 'other', 'isolation', 'free_exercise_db', 'Sled_Reverse_Flye', ARRAY['Attach dual handles to a sled connected by a rope or chain. Load the sled to a light weight.', 'Face the sled, backing up until there is some tension in the line. Take both handles at arms length at about waist level. Bend the knees slightly and keep your chest and head up. This will be your starting position.', 'Without flexing the elbow, pull the handles upward and apart, performing a reverse fly with some external rotation. Your palms should be facing forward as you do this.', 'Return to the starting position, taking a couple steps back to take the slack out of the line.']::text[], ARRAY['Sled_Reverse_Flye/0.jpg', 'Sled_Reverse_Flye/1.jpg']::text[], 'sled reverse flye bay vai sau voi xe truot aperturas invertidas con trineo'),
  (NULL, 'Sled Row', 'Chèo với xe trượt', 'Sled Row', 'Remo con trineo', 'back', 'other', 'compound', 'free_exercise_db', 'Sled_Row', ARRAY['Attach dual handles to a sled connected by a rope or chain. Load the sled to an appropriate weight. Face the sled, backing up until there is some tension in the line.', 'With a handle in each hand, bend the knees slightly, keep your head and chest up, and begin with your arms extended.', 'To initiate the movement, flex the elbow as you retract your shoulder blades, pulling the sled towards you.', 'Take a step or two back to get tension in the line and repeat.']::text[], ARRAY['Sled_Row/0.jpg', 'Sled_Row/1.jpg']::text[], 'sled row cheo voi xe truot remo con trineo'),
  (NULL, 'Sledgehammer Swings', 'Sledgehammer Swings', 'Sledgehammer Swings', 'Golpes con mazo', 'abs', 'other', 'compound', 'free_exercise_db', 'Sledgehammer_Swings', ARRAY['You will need a tire and a sledgehammer for this exercise. Stand in front of the tire about two feet away from it with a staggered stance. Grip the sledgehammer.', 'If you are right handed, your left hand should be at the bottom of the handle, and your right hand should be choking up closer to the head.', 'As you bring the sledge up, your right hand slides toward the head; as you swing down, your right hand will slide down to join your left hand. Slam it down as hard as you can against the tire. Control the bounce of the hammer off of the tire.', 'Repeat on the other side.']::text[], ARRAY['Sledgehammer_Swings/0.jpg', 'Sledgehammer_Swings/1.jpg']::text[], 'sledgehammer swings vung bua ta golpes con mazo'),
  (NULL, 'Smith Incline Shoulder Raise', 'Nâng vai ghế dốc máy Smith', 'Smith Incline Shoulder Raise', 'Elevación de hombros inclinado en Smith', 'shoulders', 'barbell', 'isolation', 'free_exercise_db', 'Smith_Incline_Shoulder_Raise', ARRAY['Place an incline bench underneath the smith machine. Place the barbell at a height that you can reach when lying down and your arms are almost fully extended. Once the weight you need is selected, lie down on the incline bench and make sure your shoulders are aligned right under the barbell.', 'Using a shoulder width pronated (palms forward) grip, lift the bar from the rack and hold it straight over you with a slight bend at the elbows. This will be your starting position.', 'As you breathe out, lift the bar up until your arms are fully extended. Note: The contraction should be felt around the shoulders.', 'After a second pause, bring the bar back down to the starting position as you breathe in.', 'Repeat the movement for the prescribed amount of repetitions.', 'When you are done, place the bar back in the rack.']::text[], ARRAY['Smith_Incline_Shoulder_Raise/0.jpg', 'Smith_Incline_Shoulder_Raise/1.jpg']::text[], 'smith incline shoulder raise nang vai ghe doc may smith elevacion de hombros inclinado en smith'),
  (NULL, 'Smith Machine Behind the Back Shrug', 'Smith Machine Behind the Back Shrug', 'Smith Machine Behind the Back Shrug', 'Encogimiento por detrás en máquina Smith', 'shoulders', 'machine', 'isolation', 'free_exercise_db', 'Smith_Machine_Behind_the_Back_Shrug', ARRAY['With the bar at thigh level, load an appropriate weight.', 'Stand with the bar behind you, taking a shoulder-width, pronated grip on the bar and unhook the weight. You should be standing up straight with your head and chest up and your arms extended. This will be your starting position.', 'Initiate the movement by shrugging your shoulders straight up. Do not flex the arms or wrist during the movement.', 'After a brief pause return the weight to the starting position.', 'Repeat for the desired number of repetitions before engaging the hooks to rack the weight.']::text[], ARRAY['Smith_Machine_Behind_the_Back_Shrug/0.jpg', 'Smith_Machine_Behind_the_Back_Shrug/1.jpg']::text[], 'smith machine behind the back shrug nhun vai sau lung may smith encogimiento por detras en maquina smith'),
  (NULL, 'Smith Machine Bench Press', 'Smith Machine Bench Press', 'Smith Machine Bench Press', 'Press de banca en máquina Smith', 'chest', 'machine', 'compound', 'free_exercise_db', 'Smith_Machine_Bench_Press', ARRAY['Place a flat bench underneath the smith machine. Now place the barbell at a height that you can reach when lying down and your arms are almost fully extended. Once the weight you need is selected, lie down on the flat bench. Using a pronated grip that is wider than shoulder width, unlock the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.', 'As you breathe in, come down slowly until you feel the bar on your middle chest.', 'After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles. Lock your arms in the contracted position, hold for a second and then start coming down slowly again. Tip: It should take at least twice as long to go down than to come up.', 'Repeat the movement for the prescribed amount of repetitions.', 'When you are done, lock the bar back in the rack.']::text[], ARRAY['Smith_Machine_Bench_Press/0.jpg', 'Smith_Machine_Bench_Press/1.jpg']::text[], 'smith machine bench press day nguc may smith press de banca en maquina smith'),
  (NULL, 'Smith Machine Bent Over Row', 'Chèo cúi người máy Smith', 'Smith Machine Bent Over Row', 'Remo inclinado en máquina Smith', 'back', 'machine', 'compound', 'free_exercise_db', 'Smith_Machine_Bent_Over_Row', ARRAY['Set the barbell attached to the smith machine to a height that is about 2 inches below your knees.', 'Bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Tip: Make sure that you keep the head up.', 'Now grasp the barbell using an overhand (pronated) grip and unlock it from the smith machine rack. Then let it hang directly in front of you as your arms hang extended perpendicular to the floor and your torso. This is your starting position.', 'While keeping the torso stationary, lift the barbell as you breathe out, keeping the elbows close to the body and not doing any force with the forearm other than holding the weights. On the top contracted position, squeeze the back muscles and hold for a second.', 'Slowly lower the weight again to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Smith_Machine_Bent_Over_Row/0.jpg', 'Smith_Machine_Bent_Over_Row/1.jpg']::text[], 'smith machine bent over row cheo cui nguoi may smith remo inclinado en maquina smith'),
  (NULL, 'Smith Machine Calf Raise', 'Nhón bắp chân máy Smith', 'Smith Machine Calf Raise', 'Elevación de gemelos en máquina Smith', 'calves', 'machine', 'isolation', 'free_exercise_db', 'Smith_Machine_Calf_Raise', ARRAY['Place a block or weight plate below the bar on the Smith machine. Set the bar to a position that best matches your height. Once the correct height is chosen and the bar is loaded, step onto the plates with the balls of your feet and place the bar on the back of your shoulders.', 'Take the bar with both hands facing forward. Rotate the bar to unrack it. This will be your starting position.', 'Raise your heels as high as possible by pushing off of the balls of your feet, flexing your calf at the top of the contraction. Your knees should remain extended. Hold the contracted position for a second before you start to go back down.', 'Return slowly to the starting position as you breathe in while lowering your heels.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Smith_Machine_Calf_Raise/0.jpg', 'Smith_Machine_Calf_Raise/1.jpg']::text[], 'smith machine calf raise nhon bap chan may smith elevacion de gemelos en maquina smith'),
  (NULL, 'Smith Machine Close-Grip Bench Press', 'Smith Machine Close-Grip Bench Press', 'Smith Machine Close-Grip Bench Press', 'Press de banca agarre cerrado en máquina Smith', 'triceps', 'machine', 'compound', 'free_exercise_db', 'Smith_Machine_Close-Grip_Bench_Press', ARRAY['Place a flat bench underneath the smith machine. Place the barbell at a height that you can reach when lying down and your arms are almost fully extended. Once the weight you need is selected, lie down on the flat bench. Using a close and pronated grip (palms facing forward) that is around shoulder width, unlock the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.', 'As you breathe in, come down slowly until you feel the bar on your middle chest. Tip: Make sure that as opposed to a regular bench press, you keep the elbows close to the torso at all times in order to maximize triceps involvement.', 'After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your triceps muscles. Lock your arms in the contracted position, hold for a second and then start coming down slowly again. Tip: It should take at least twice as long to go down than to come up.', 'Repeat the movement for the prescribed amount of repetitions.', 'When you are done, lock the bar back in the rack.']::text[], ARRAY['Smith_Machine_Close-Grip_Bench_Press/0.jpg', 'Smith_Machine_Close-Grip_Bench_Press/1.jpg']::text[], 'smith machine close-grip bench press day nguc nam hep may smith press de banca agarre cerrado en maquina smith'),
  (NULL, 'Smith Machine Decline Press', 'Đẩy ngực dốc xuống (máy Smith)', 'Smith Machine Decline Press', 'Press declinado en máquina Smith', 'chest', 'machine', 'compound', 'free_exercise_db', 'Smith_Machine_Decline_Press', ARRAY['Position a decline bench in the rack so that the bar will be above your chest. Load an appropriate weight and take your place on the bench.', 'Rotate the bar to unhook it from the rack and fully extend your arms. Your back should be slightly arched and your shoulder blades retracted. This will be your starting position.', 'Begin the movement by flexing your arms, lowering the bar to your chest.', 'Pause briefly, and then extend your arms to push the weight back to the starting position.', 'After completing the desired number of repetitions, rotate the bar to rack the weight.']::text[], ARRAY['Smith_Machine_Decline_Press/0.jpg', 'Smith_Machine_Decline_Press/1.jpg']::text[], 'smith machine decline press day nguc doc xuong (may smith) press declinado en maquina smith'),
  (NULL, 'Smith Machine Hang Power Clean', 'Smith Machine Hang Power Clean', 'Smith Machine Hang Power Clean', 'Cargada colgante de potencia en Smith', 'legs', 'machine', 'compound', 'free_exercise_db', 'Smith_Machine_Hang_Power_Clean', ARRAY['Position the bar at knee height and load it to an appropriate weight.', 'Take a pronated grip on the bar outside of shoulder width and unhook the bar from the machine. Your arms should be fully extended with your head and chest up. Your elbows should be pointed out with your shoulders back and down. Your hips should be back, loading the tension into the hamstrings. This will be your starting position.', 'Initate the movement by forcefully extending the hips and knees, accelerating into the bar. Ensure that you keep your arms straight during this part of the motion.', 'Upon full extension, rebend the hips and knees to lower your receiving position.', 'Allow the arms to flex at this point, rotating the elbows around the bar to receive it on your shoulders.', 'Extend through the hips and knees to come to a standing position with the bar racked on your shoulders to complete the movement.']::text[], ARRAY['Smith_Machine_Hang_Power_Clean/0.jpg', 'Smith_Machine_Hang_Power_Clean/1.jpg']::text[], 'smith machine hang power clean hang power clean may smith cargada colgante de potencia en smith'),
  (NULL, 'Smith Machine Hip Raise', 'Nâng hông máy Smith', 'Smith Machine Hip Raise', 'Elevación de cadera en máquina Smith', 'abs', 'machine', 'isolation', 'free_exercise_db', 'Smith_Machine_Hip_Raise', ARRAY['Position a bench in the rack and load the bar to an appropriate weight. Lie down on the bench, placing the bottom of your feet against the bar. Unlock the bar and extend your legs. You may need to use your hands to assist you. For added stability grasp the sides of the Smith Machine. This will be your starting position.', 'Initiate the movement by rotating your pelvis, flexing your spine to raise your hips off of the bench. Maintain a slight bend in the knees throughout the motion.', 'After a brief pause, return the hips to the bench.', 'Repeat for the desired number of repetitions.']::text[], ARRAY['Smith_Machine_Hip_Raise/0.jpg', 'Smith_Machine_Hip_Raise/1.jpg']::text[], 'smith machine hip raise nang hong may smith elevacion de cadera en maquina smith'),
  (NULL, 'Smith Machine Incline Bench Press', 'Smith Machine Incline Bench Press', 'Smith Machine Incline Bench Press', 'Press inclinado en máquina Smith', 'chest', 'machine', 'compound', 'free_exercise_db', 'Smith_Machine_Incline_Bench_Press', ARRAY['Place an incline bench underneath the smith machine. Place the barbell at a height that you can reach when lying down and your arms are almost fully extended. Once the weight you need is selected, lie down on the incline bench and make sure your upper chest is aligned with the barbell. Using a pronated grip (palms facing forward) that is wider than shoulder width, unlock the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.', 'As you breathe in, come down slowly until you feel the bar on your upper chest.', 'After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles. Lock your arms in the contracted position, hold for a second and then start coming down slowly again. Tip: It should take at least twice as long to go down than to come up.', 'Repeat the movement for the prescribed amount of repetitions.', 'When you are done, place the bar back in the rack.']::text[], ARRAY['Smith_Machine_Incline_Bench_Press/0.jpg', 'Smith_Machine_Incline_Bench_Press/1.jpg']::text[], 'smith machine incline bench press day nguc doc len may smith press inclinado en maquina smith'),
  (NULL, 'Smith Machine Leg Press', 'Smith Machine Leg Press', 'Smith Machine Leg Press', 'Prensa de piernas en máquina Smith', 'legs', 'machine', 'compound', 'free_exercise_db', 'Smith_Machine_Leg_Press', ARRAY['Position a Smith machine bar a couple feet off of the ground. Ensure that it is resting on the safeties. After loading the bar to an appropriate weight, lie underneath the bar. Place the middle of your feet on the bar, tucking your knees to your chest. This will be your starting position.', 'Begin the movement by driving through your feet to move the bar upward, extending the hips and knees. Do not lock out your knees.', 'At the top of the motion, pause briefly before returning to the starting position.']::text[], ARRAY['Smith_Machine_Leg_Press/0.jpg', 'Smith_Machine_Leg_Press/1.jpg']::text[], 'smith machine leg press dap dui may smith prensa de piernas en maquina smith'),
  (NULL, 'Smith Machine One-Arm Upright Row', 'Kéo thẳng đứng một tay máy Smith', 'Smith Machine One-Arm Upright Row', 'Remo al mentón a una mano en Smith', 'shoulders', 'machine', 'compound', 'free_exercise_db', 'Smith_Machine_One-Arm_Upright_Row', ARRAY['With the bar at thigh level, load an appropriate weight.', 'Take a wide grip on the bar and unhook the weight, removing your off hand from the bar. Your arm should be extended as you stand up straight with your head and chest up. This will be your starting position.', 'Begin the movement by flexing the elbow, raising the upper arm with the elbow pointed out. Continue until your upper arm is parallel to the floor.', 'After a brief pause, return the weight to the starting position.', 'Repeat for the desired number of repetitions before engaging the hooks to rack the weight.']::text[], ARRAY['Smith_Machine_One-Arm_Upright_Row/0.jpg', 'Smith_Machine_One-Arm_Upright_Row/1.jpg']::text[], 'smith machine one-arm upright row keo thang dung mot tay may smith remo al menton a una mano en smith'),
  (NULL, 'Smith Machine Overhead Shoulder Press', 'Đẩy vai qua đầu máy Smith', 'Smith Machine Overhead Shoulder Press', 'Press de hombros en máquina Smith', 'shoulders', 'machine', 'compound', 'free_exercise_db', 'Smith_Machine_Overhead_Shoulder_Press', ARRAY['To begin, place a flat bench (or preferably one with back support) underneath a smith machine. Position the barbell at a height so that when seated on the flat bench, the arms must be almost fully extended to reach the barbell.', 'Once you have the correct height, sit slightly in behind the barbell so that there is an imaginary straight line from the tip of your nose to the barbell. Your feet should be stationary. Grab the barbell with the palms facing forward, unlock it and lift it up so that your arms are fully extended. This is the starting position.', 'Slowly begin to lower the barbell until it is level with your chin while inhaling.', 'Then lift the barbell back to the starting position using your shoulders while exhaling.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Smith_Machine_Overhead_Shoulder_Press/0.jpg', 'Smith_Machine_Overhead_Shoulder_Press/1.jpg']::text[], 'smith machine overhead shoulder press day vai qua dau may smith press de hombros en maquina smith'),
  (NULL, 'Smith Machine Pistol Squat', 'Smith Machine Pistol Squat', 'Smith Machine Pistol Squat', 'Sentadilla pistol en máquina Smith', 'legs', 'machine', 'compound', 'free_exercise_db', 'Smith_Machine_Pistol_Squat', ARRAY['To begin, first set the bar to a position that best matches your height. Step under it and position the bar across the back of your shoulders.', 'Take the bar with your hands facing forward, unlock it and lift it off the rack by extending your legs. 3', 'Move one foot forward about 12 inches in front of the bar. Extend the other leg out in front of you, holding it off the ground. Look forward at all times and maintain a neutral or slightly arched spine. This will be your starting position.', 'Maintaining good posture, lower yourself by flexing the knee and hip, going down as far as flexibility allows.', 'Pause briefly at the bottom and then return to the starting position by driving through the heel of your foot, extending the knee and hip.']::text[], ARRAY['Smith_Machine_Pistol_Squat/0.jpg', 'Smith_Machine_Pistol_Squat/1.jpg']::text[], 'smith machine pistol squat squat mot chan may smith sentadilla pistol en maquina smith'),
  (NULL, 'Smith Machine Reverse Calf Raises', 'Nhón mũi chân ngược máy Smith', 'Smith Machine Reverse Calf Raises', 'Elevación de gemelos inversa en Smith', 'calves', 'machine', 'isolation', 'free_exercise_db', 'Smith_Machine_Reverse_Calf_Raises', ARRAY['Adjust the barbell on the smith machine to fit your height and align a raised platform right under the bar.', 'Stand on the platform with the heels of your feet secured on top of it with the balls of your feet extending off it. Position your toes facing forward with a shoulder width stance.', 'Now, place your shoulders under the barbell while maintaining the foot positioning described and push the barbell up by extending your hips and knees until your torso is standing erect. The knees should be kept with a slight bend; never locked. This will be your starting position. Tip: The barbell on your back is only for balance purposes.', 'Raise the balls of your feet as you breathe out by extending your toes as high as possible and flexing your calf. Ensure that the knee is kept stationary at all times. There should be no bending at any time. Hold the contracted position for a second before you start to go back down.', 'Slowly go back down to the starting position as you breathe in by lowering the balls of your feet and toes.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Smith_Machine_Reverse_Calf_Raises/0.jpg', 'Smith_Machine_Reverse_Calf_Raises/1.jpg']::text[], 'smith machine reverse calf raises nhon mui chan nguoc may smith elevacion de gemelos inversa en smith'),
  (NULL, 'Smith Machine Squat', 'Smith Machine Squat', 'Smith Machine Squat', 'Sentadilla en máquina Smith', 'legs', 'machine', 'compound', 'free_exercise_db', 'Smith_Machine_Squat', ARRAY['To begin, first set the bar on the height that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.', 'Hold on to the bar using both arms at each side (palms facing forward), unlock it and lift it off the rack by first pushing with your legs and at the same time straightening your torso.', 'Position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times and also maintain a straight back. This will be your starting position. (Note: For the purposes of this discussion we will use the medium stance which targets overall development; however you can choose any of the three stances discussed in the foot stances section).', 'Begin to slowly lower the bar by bending the knees as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to the floor). Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.', 'Begin to raise the bar as you exhale by pushing the floor with the heel of your foot as you straighten the legs again and go back to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Smith_Machine_Squat/0.jpg', 'Smith_Machine_Squat/1.jpg']::text[], 'smith machine squat squat may smith sentadilla en maquina smith'),
  (NULL, 'Smith Machine Stiff-Legged Deadlift', 'Smith Machine Stiff-Legged Deadlift', 'Smith Machine Stiff-Legged Deadlift', 'Peso muerto piernas rígidas en Smith', 'legs', 'machine', 'compound', 'free_exercise_db', 'Smith_Machine_Stiff-Legged_Deadlift', ARRAY['To begin, set the bar on the smith machine to a height that is around the middle of your thighs. Once the correct height is chosen and the bar is loaded, grasp the bar using a pronated (palms forward) grip that is shoulder width apart. You may need some wrist wraps if using a significant amount of weight.', 'Lift the bar up by fully extending your arms while keeping your back straight. Stand with your torso straight and your legs spaced using a shoulder width or narrower stance. The knees should be slightly bent. This is your starting position.', 'Keeping the knees stationary, lower the barbell to over the top of your feet by bending at the waist while keeping your back straight. Keep moving forward as if you were going to pick something from the floor until you feel a stretch on the hamstrings. Exhale as you perform this movement', 'Start bringing your torso up straight again as soon as you feel the hamstrings stretch by extending your hips and waist until you are back at the starting position. Inhale as you perform this movement.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Smith_Machine_Stiff-Legged_Deadlift/0.jpg', 'Smith_Machine_Stiff-Legged_Deadlift/1.jpg']::text[], 'smith machine stiff-legged deadlift deadlift chan thang may smith peso muerto piernas rigidas en smith'),
  (NULL, 'Smith Machine Upright Row', 'Kéo thẳng đứng máy Smith', 'Smith Machine Upright Row', 'Remo al mentón en máquina Smith', 'shoulders', 'machine', 'compound', 'free_exercise_db', 'Smith_Machine_Upright_Row', ARRAY['To begin, set the bar on the smith machine to a height that is around the middle of your thighs. Once the correct height is chosen and the bar is loaded, grasp the bar using a pronated (palms forward) grip that is shoulder width apart. You may need some wrist wraps if using a significant amount of weight.', 'Lift the barbell up and fully extend your arms with your back straight. There should be a slight bend at the elbows. This is the starting position.', 'Use your side shoulders to lift the bar as you exhale. The bar should be close to the body as you move it up. Continue to lift it until it nearly touches your chin. Tip: Your elbows should drive the motion. As you lift the bar, your elbows should always be higher than your forearms. Also, keep your torso stationary and pause for a second at the top of the movement.', 'Lower the bar back down slowly to the starting position. Inhale as you perform this portion of the movement.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Smith_Machine_Upright_Row/0.jpg', 'Smith_Machine_Upright_Row/1.jpg']::text[], 'smith machine upright row keo thang dung may smith remo al menton en maquina smith'),
  (NULL, 'Smith Single-Leg Split Squat', 'Smith Single-Leg Split Squat', 'Smith Single-Leg Split Squat', 'Sentadilla dividida a una pierna en Smith', 'legs', 'machine', 'compound', 'free_exercise_db', 'Smith_Single-Leg_Split_Squat', ARRAY['To begin, place a flat bench 2-3 feet behind the smith machine. Then, set the bar on the height that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.', 'Hold on to the bar using both arms at each side (palms facing forward), unlock it and lift it off the rack by first pushing with your legs and at the same time straightening your torso.', 'Position your legs by placing one foot slightly forward under the bar and extending your other leg back and place the top of your foot on the bench. This will be your starting position', 'Begin to slowly lower the bar by bending the knee as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the calf becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to the floor). Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knee should make an imaginary straight line with the toes that is perpendicular to the front. If your knee is past that imaginary line (if it is past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.', 'Begin to raise the bar as you exhale by pushing the floor with the heel of your foot mainly as you straighten your leg again and go back to the starting position.', 'Repeat for the recommended amount of repetitions.', 'Switch legs and repeat the movement.']::text[], ARRAY['Smith_Single-Leg_Split_Squat/0.jpg', 'Smith_Single-Leg_Split_Squat/1.jpg']::text[], 'smith single-leg split squat squat tach chan mot chan may smith sentadilla dividida a una pierna en smith'),
  (NULL, 'Snatch', 'Snatch', 'Snatch', 'Arrancada', 'legs', 'barbell', 'compound', 'free_exercise_db', 'Snatch', ARRAY['Place your feet at a shoulder width stance with the barbell resting right above the connection between the toes and the rest of the foot.', 'With a palms facing down grip, bend at the knees and keeping the back flat grab the bar using a wider than shoulder width grip. Bring the hips down and make sure that your body drops as if you were going to sit on a chair. This will be your starting position.', 'Start pushing the floor as if it were a moving platform with your feet and simultaneously start lifting the barbell keeping it close to your legs.', 'As the bar reaches the middle of your thighs, push the floor with your legs and lift your body to a complete extension in an explosive motion.', 'Lift your shoulders back in a shrugging movement as you bring the bar up while lifting your elbows out to the side and keeping them above the bar for as long as possible.', 'Now in a very quick but powerful motion, you have to get your body under the barbell when it has reached a high enough point where it can be controlled and drop while locking your arms and holding the barbell overhead as you assume a squat position.', 'Finalize the movement by rising up out of the squat position to finish the lift. At the end of the lift both feet should be on line and the arms fully extended holding the barbell overhead.']::text[], ARRAY['Snatch/0.jpg', 'Snatch/1.jpg']::text[], 'snatch snatch arrancada'),
  (NULL, 'Snatch Balance', 'Snatch Balance', 'Snatch Balance', 'Equilibrio de arrancada', 'legs', 'barbell', 'compound', 'free_exercise_db', 'Snatch_Balance', ARRAY['Begin with the feet in the pulling position, the bar racked across the back of the shoulders, and the hands placed in a wide snatch grip.', 'Pop the bar with an abrupt dip and drive of the knees, and aggressively drive under the bar, transitioning the feet into the receiving position.', 'Receive the bar locked out overhead near the bottom of the squat. The torso should remain vertical, lowering the hips between the legs.', 'Continue to descend to full depth, and return to a standing position. Carefully lower the weight.']::text[], ARRAY['Snatch_Balance/0.jpg', 'Snatch_Balance/1.jpg']::text[], 'snatch balance snatch balance equilibrio de arrancada'),
  (NULL, 'Snatch Deadlift', 'Snatch Deadlift', 'Snatch Deadlift', 'Peso muerto de arrancada', 'legs', 'barbell', 'compound', 'free_exercise_db', 'Snatch_Deadlift', ARRAY['The snatch deadlift strengthens the first pull of the snatch. Begin with a wide snatch grip with the barbell placed on the platform. The feet should be directly under the hips, with the feet turned out. Squat down to the bar, keeping the back in absolute extension with the head facing forward.', 'Initiate the movement by driving through the heels, raising the hips. The back angle should remain the same until the bar passes the knees.', 'At that point, drive your hips through the bar as you lay back. Return the bar to the platform by reversing the motion.']::text[], ARRAY['Snatch_Deadlift/0.jpg', 'Snatch_Deadlift/1.jpg']::text[], 'snatch deadlift deadlift kieu snatch peso muerto de arrancada'),
  (NULL, 'Snatch Pull', 'Snatch Pull', 'Snatch Pull', 'Tirón de arrancada', 'legs', 'barbell', 'compound', 'free_exercise_db', 'Snatch_Pull', ARRAY['With a barbell on the floor close to the shins, take a wide snatch grip. Lower your hips with the weight focused on the heels, back straight, head facing forward, chest up, with your shoulders just in front of the bar. This will be your starting position.', 'Begin the first pull by driving through the heels, extending your knees. Your back angle should stay the same, and your arms should remain straight. Move the weight with control as you continue to above the knees.', 'Next comes the second pull, the main source of acceleration for the pull. As the bar approaches the mid-thigh position, begin extending through the hips. In a jumping motion, accelerate by extending the hips, knees, and ankles, using speed to move the bar upward.', 'There should be no need to actively pull through the arms to accelerate the weight; at the end of the second pull, the body should be fully extended, leaning slightly back. Full extension should be violent and abrupt, and ensure that you do not prolong the extension for longer than necessary.']::text[], ARRAY['Snatch_Pull/0.jpg', 'Snatch_Pull/1.jpg']::text[], 'snatch pull keo snatch tiron de arrancada'),
  (NULL, 'Snatch Shrug', 'Snatch Shrug', 'Snatch Shrug', 'Encogimiento de arrancada', 'shoulders', 'barbell', 'compound', 'free_exercise_db', 'Snatch_Shrug', ARRAY['Begin with a wide grip, with the bar hanging at the mid thigh position. You can use a hook or overhand grip. Your back should be straight and inclined slightly forward.', 'Shrug your shoulders towards your ears. While this exercise can usually by loaded with heavier weight than a snatch, avoid overloading to the point that the execution slows down.']::text[], ARRAY['Snatch_Shrug/0.jpg', 'Snatch_Shrug/1.jpg']::text[], 'snatch shrug nhun vai kieu snatch encogimiento de arrancada'),
  (NULL, 'Snatch from Blocks', 'Snatch from Blocks', 'Snatch from Blocks', 'Arrancada desde bloques', 'legs', 'barbell', 'compound', 'free_exercise_db', 'Snatch_from_Blocks', ARRAY['Begin with a loaded barbell on boxes or stands of the desired height. A wide grip should be taken on the bar. The feet should be directly below the hips, with the feet turned out as needed. Lower the hips, with the chest up and the head looking forward. The shoulders should be just in front of the bar, with the elbows pointed out. This will be the starting position.', 'Begin the first pull by driving through the front of the heels, raising the bar from the boxes.', 'Transition into the second pull by extending through the hips knees and ankles, driving the bar up as quickly as possible. The bar should be close to the body. At peak extension, shrug the shoulders and allow the elbows to flex to the side.', 'As you move your feet into the receiving position, forcefully pull yourself below the bar as you elevate the bar overhead. The feet should move to just outside the hips, turned out as necessary. Receive the bar with your body as low as possible and the arms fully extended overhead.', 'Keeping the bar aligned over the front of the heels, your head and chest up, drive through heels of the feet to move to a standing position. Carefully return the weight to the boxes.']::text[], ARRAY['Snatch_from_Blocks/0.jpg', 'Snatch_from_Blocks/1.jpg']::text[], 'snatch from blocks snatch tu buc arrancada desde bloques'),
  (NULL, 'Speed Band Overhead Triceps', 'Duỗi tay sau qua đầu nhanh với dây kháng lực', 'Speed Band Overhead Triceps', 'Tríceps sobre la cabeza rápido con banda', 'triceps', 'band', 'isolation', 'free_exercise_db', 'Speed_Band_Overhead_Triceps', ARRAY['For this exercise anchor a band to the ground. We used an incline bench and anchored the band to the base, standing over the bench. Alternatively, this could be performed standing on the band.', 'To begin, pull the band behind your head, holding it with a pronated grip and your elbows up. This will be your starting position.', 'To perform the movement, extend through the elbow to to straighten your arms, ensuring that you keep your upper arm in place.', 'Pause, and then return to the starting position.']::text[], ARRAY['Speed_Band_Overhead_Triceps/0.jpg', 'Speed_Band_Overhead_Triceps/1.jpg']::text[], 'speed band overhead triceps duoi tay sau qua dau nhanh voi day khang luc triceps sobre la cabeza rapido con banda'),
  (NULL, 'Speed Box Squat', 'Speed Box Squat', 'Speed Box Squat', 'Sentadilla al cajón de velocidad', 'legs', 'barbell', 'compound', 'free_exercise_db', 'Speed_Box_Squat', ARRAY['Attach bands to the bar that are securely anchored near the ground. You may need to choke the bands to get adequate tension.', 'Use a box of an appropriate height for this exercise. Load the bar to a weight that still requires effort, but isn''t so heavy that speed is compromised. Typically, that will be between 50-70% of your one rep max.', 'Position the bar on your upper back, shoulder blades retracted, back arched and everything tight head to toe. This will be the starting position.', 'Unrack the bar and position yourself in front of the box. Sit back with your hips until you are seated on the box, ensuring that you descend under control and don''t crash onto the surface.', 'Pause briefly, and explode off of the box, extending through the hips and knees.']::text[], ARRAY['Speed_Box_Squat/0.jpg', 'Speed_Box_Squat/1.jpg']::text[], 'speed box squat squat xuong buc toc do sentadilla al cajon de velocidad'),
  (NULL, 'Speed Squats', 'Speed Squats', 'Speed Squats', 'Sentadillas de velocidad', 'legs', 'barbell', 'compound', 'free_exercise_db', 'Speed_Squats', ARRAY['This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.', 'Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.', 'Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance and also maintain a straight back. This will be your starting position. (Note: For the purposes of this discussion we will use the medium stance which targets overall development; however you can choose any of the three stances discussed in the foot stances section).', 'Begin to lower the bar by bending the knees as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to the floor). Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.', 'Begin to raise the bar as fast as possible without involving momentum as you exhale by pushing the floor with the heel of your foot mainly as you straighten the legs again and go back to the starting position. Note: You should perform these exercises as fast as possible but without breaking perfect form and without involving momentum.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Speed_Squats/0.jpg', 'Speed_Squats/1.jpg']::text[], 'speed squats squat toc do sentadillas de velocidad'),
  (NULL, 'Spell Caster', 'Vung tạ phù thủy', 'Spell Caster', 'Lanzador de hechizos', 'abs', 'dumbbell', 'compound', 'free_exercise_db', 'Spell_Caster', ARRAY['Hold a dumbbell in each hand with a pronated grip. Your feet should be wide with your hips and knees extended. This will be your starting position.', 'Begin the movement by pulling both of the dumbbells to one side next to your hip, rotating your torso.', 'Keeping your arms straight and the dumbbells parallel to the ground, rotate your torso to swing the weights to your opposite side.', 'Continue alternating, rotating from one side to the other until the set is complete.']::text[], ARRAY['Spell_Caster/0.jpg', 'Spell_Caster/1.jpg']::text[], 'spell caster vung ta phu thuy lanzador de hechizos'),
  (NULL, 'Spider Crawl', 'Bò kiểu nhện', 'Spider Crawl', 'Gateo de araña', 'abs', 'bodyweight', 'bodyweight', 'free_exercise_db', 'Spider_Crawl', ARRAY['Begin in a prone position on the floor. Support your weight on your hands and toes, with your feet together and your body straight. Your arms should be bent to 90 degrees. This will be your starting position.', 'Initiate the movement by raising one foot off of the ground. Externally rotate the leg and bring the knee toward your elbow, as far forward as possible.', 'Return this leg to the starting position and repeat on the opposite side.']::text[], ARRAY['Spider_Crawl/0.jpg', 'Spider_Crawl/1.jpg']::text[], 'spider crawl bo kieu nhen gateo de arana'),
  (NULL, 'Spider Curl', 'Spider Curl', 'Spider Curl', 'Curl araña', 'biceps', 'ez bar', 'isolation', 'free_exercise_db', 'Spider_Curl', ARRAY['Start out by setting the bar on the part of the preacher bench that you would normally sit on. Make sure to align the barbell properly so that it is balanced and will not fall off.', 'Move to the front side of the preacher bench (the part where the arms usually lay) and position yourself to lay at a 45 degree slant with your torso and stomach pressed against the front side of the preacher bench.', 'Make sure that your feet (especially the toes) are well positioned on the floor and place your upper arms on top of the pad located on the inside part of the preacher bench.', 'Use your arms to grab the barbell with a supinated grip (palms facing up) at about shoulder width apart or slightly closer from each other.', 'Slowly begin to lift the barbell upwards and exhale. Hold the contracted position for a second as you squeeze the biceps.', 'Slowly begin to bring the barbell back to the starting position as your breathe in. .', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Spider_Curl/0.jpg', 'Spider_Curl/1.jpg']::text[], 'spider curl cuon tay truoc kieu nhen curl arana'),
  (NULL, 'Spinal Stretch', 'Giãn cột sống', 'Spinal Stretch', 'Estiramiento de columna', 'back', 'other', 'timed', 'free_exercise_db', 'Spinal_Stretch', ARRAY['Sit in a chair so your back is straight and your feet planted on the floor.', 'Interlace your fingers behind your head, elbows out and your chin down.', 'Twist your upper body to one side about 3 times as far as you can. Then lean forward and twist your torso to reach your elbow to the floor on the inside of your knee.', 'Return to upright position and then repeat for your other side.']::text[], ARRAY['Spinal_Stretch/0.jpg', 'Spinal_Stretch/1.jpg']::text[], 'spinal stretch gian cot song estiramiento de columna'),
  (NULL, 'Split Clean', 'Split Clean', 'Split Clean', 'Cargada en tijera', 'legs', 'barbell', 'compound', 'free_exercise_db', 'Split_Clean', ARRAY['With a barbell on the floor close to the shins, take an overhand grip just outside the legs. Lower your hips with the weight focused on the heels, back straight, head facing forward, chest up, with your shoulders just in front of the bar. This will be your starting position.', 'Begin the first pull by driving through the heels, extending your knees. Your back angle should stay the same, and your arms should remain straight. Move the weight with control as you continue to above the knees.', 'Next comes the second pull, the main source of acceleration for the clean. As the bar approaches the mid-thigh position, begin extending through the hips. In a jumping motion, accelerate by extending the hips, knees, and ankles, using speed to move the bar upward. There should be no need to actively pull through the arms to accelerate the weight; at the end of the second pull, the body should be fully extended, leaning slightly back, with the arms still extended.', 'As full extension is achieved, transition into the third pull by aggressively shrugging and flexing the arms with the elbows up and out. At peak extension, aggressively pull yourself down, rotating your elbows under the bar as you do so.', 'Receive the bar with the feet split, aggressively moving one foot forward and one foot back. The bar should be racked onto the protracted shoulders, lightly touching the throat with the hands relaxed. Continue to descend to the bottom position, which will help in the recovery.', 'Immediately recover by driving through the heels, keeping the torso upright and elbows up. Bring the feet together as you stand up.']::text[], ARRAY['Split_Clean/0.jpg', 'Split_Clean/1.jpg']::text[], 'split clean split clean cargada en tijera'),
  (NULL, 'Split Jerk', 'Split Jerk', 'Split Jerk', 'Envión en tijera', 'legs', 'barbell', 'compound', 'free_exercise_db', 'Split_Jerk', ARRAY['Standing with the weight racked on the front of the shoulders, begin with the dip. With your feet directly under your hips, flex the knees without moving the hips backward.', 'Go down only slightly, and reverse direction as powerfully as possible. Drive through the heels create as much speed and force as possible, and be sure to move your head out of the way as the bar leaves the shoulders. At this moment as the feet leave the floor, the feet must be placed into the receiving position as quickly as possible.', 'In the brief moment the feet are not actively driving against the platform, the athlete''s effort to push the bar up will drive them down. The feet should be moved to a split stance, one foot forward, one foot back, with the knees partially bent. Receive the bar with the arms locked out overhead.', 'Return to a standing position, bringing the feet together.']::text[], ARRAY['Split_Jerk/0.jpg', 'Split_Jerk/1.jpg']::text[], 'split jerk split jerk envion en tijera'),
  (NULL, 'Split Jump', 'Bật nhảy đổi chân', 'Split Jump', 'Salto en tijera', 'legs', 'bodyweight', 'bodyweight', 'free_exercise_db', 'Split_Jump', ARRAY['Assume a lunge stance position with one foot forward with the knee bent, and the rear knee nearly touching the ground.', 'Ensure that the front knee is over the midline of the foot.', 'Extending through both legs, jump as high as possible, swinging your arms to gain lift.', 'As you jump, bring your feet together, and move them back to their initial positions as you land.', 'Absorb the impact by reverting back to the starting position.']::text[], ARRAY['Split_Jump/0.jpg', 'Split_Jump/1.jpg']::text[], 'split jump bat nhay doi chan salto en tijera'),
  (NULL, 'Split Snatch', 'Split Snatch', 'Split Snatch', 'Arrancada en tijera', 'legs', 'barbell', 'compound', 'free_exercise_db', 'Split_Snatch', ARRAY['Begin with a loaded barbell on the floor. The bar should be close to or touching the shins, and a wide grip should be taken on the bar. The feet should be directly below the hips, with the feet turned out as needed. Lower the hips, with the chest up and the head looking forward. The shoulders should be just in front of the bar. This will be the starting position.', 'Begin the first pull by driving through the front of the heels, raising the bar from the ground. The back angle should stay the same until the bar passes the knees.', 'Transition into the second pull by extending through the hips knees and ankles, driving the bar up as quickly as possible. The bar should be close to the body. At peak extension, shrug the shoulders and allow the elbows to flex to the side.', 'As you move your feet into the receiving position, forcefully pull yourself below the bar as you elevate the bar overhead. The feet should move forcefully to a split position, one foot forward one foot back. Receive the bar with your body as low as possible and the arms fully extended overhead.', 'Keeping the bar aligned over the front of the heels, your head and chest up, drive through heels of the feet to move to a standing position, bringing your feet together.', 'Carefully return the weight to floor.']::text[], ARRAY['Split_Snatch/0.jpg', 'Split_Snatch/1.jpg']::text[], 'split snatch split snatch arrancada en tijera'),
  (NULL, 'Split Squat with Dumbbells', 'Split Squat with Dumbbells', 'Split Squat with Dumbbells', 'Sentadilla dividida con mancuernas', 'legs', 'dumbbell', 'compound', 'free_exercise_db', 'Split_Squat_with_Dumbbells', ARRAY['Position yourself into a staggered stance with the rear foot elevated and front foot forward.', 'Hold a dumbbell in each hand, letting them hang at the sides. This will be your starting position.', 'Begin by descending, flexing your knee and hip to lower your body down. Maintain good posture througout the movement. Keep the front knee in line with the foot as you perform the exercise.', 'At the bottom of the movement, drive through the heel to extend the knee and hip to return to the starting position.']::text[], ARRAY['Split_Squat_with_Dumbbells/0.jpg', 'Split_Squat_with_Dumbbells/1.jpg']::text[], 'split squat with dumbbells squat tach chan ta don sentadilla dividida con mancuernas'),
  (NULL, 'Split Squats', 'Split Squats', 'Split Squats', 'Sentadillas divididas', 'legs', 'other', 'timed', 'free_exercise_db', 'Split_Squats', ARRAY['Being in a standing position. Jump into a split leg position, with one leg forward and one leg back, flexing the knees and lowering your hips slightly as you do so.', 'As you descend, immediately reverse direction, standing back up and jumping, reversing the position of your legs. Repeat 5-10 times on each leg.']::text[], ARRAY['Split_Squats/0.jpg', 'Split_Squats/1.jpg']::text[], 'split squats squat tach chan sentadillas divididas'),
  (NULL, 'Squat Jerk', 'Squat Jerk', 'Squat Jerk', 'Envión en sentadilla', 'legs', 'barbell', 'compound', 'free_exercise_db', 'Squat_Jerk', ARRAY['Standing with the weight racked on the front of the shoulders, begin with the dip. With your feet directly under your hips, flex the knees without moving the hips backward. Go down only slightly, and reverse direction as powerfully as possible. Drive through the heels create as much speed and force as possible, and be sure to move your head out of the way as the bar leaves the shoulders.', 'At this moment as the feet leave the floor, the feet must be placed into the receiving position as quickly as possible. In the brief moment the feet are not actively driving against the platform, the athlete''s effort to push the bar up will drive them down. The feet should move forcefully to just outside the hips, turned out as necessary. Receive the bar with your body in a full squat and the arms fully extended overhead.', 'Keeping the bar aligned over the front of the heels, your head and chest up, drive throught heels of the feet to move to a standing position. Carefully return the weight to floor.']::text[], ARRAY['Squat_Jerk/0.jpg', 'Squat_Jerk/1.jpg']::text[], 'squat jerk squat jerk envion en sentadilla'),
  (NULL, 'Squat with Bands', 'Squat with Bands', 'Squat with Bands', 'Sentadilla con bandas', 'legs', 'barbell', 'compound', 'free_exercise_db', 'Squat_with_Bands', ARRAY['Set up the bands on the sleeves, secured to either band pegs, the rack, or dumbbells so that there is appropriate tension.', 'Begin by stepping under the bar and placing it across the back of the shoulders. Squeeze your shoulder blades together and rotate your elbows forward, attempting to bend the bar across your shoulders. Remove the bar from the rack, creating a tight arch in your lower back, and step back into position. Place your feet wide for more emphasis on the back, glutes, adductors, and hamstrings. Keep your head facing forward.', 'With your back, shoulders, and core tight, push your knees and butt out and you begin your descent. Sit back with your hips as much as possible. Ideally, your shins should be perpendicular to the ground. Lower bar position necessitates a greater torso lean to keep the bar over the heels. Continue until you break parallel, which is defined as the crease of the hip being in line with the top of the knee.', 'Keeping the weight on your heels and pushing your feet and knees out, drive upward as you lead the movement with your head. Continue upward, maintaining tightness head to toe, until you have returned to the starting position.']::text[], ARRAY['Squat_with_Bands/0.jpg', 'Squat_with_Bands/1.jpg']::text[], 'squat with bands squat day khang luc sentadilla con bandas'),
  (NULL, 'Squat with Chains', 'Squat with Chains', 'Squat with Chains', 'Sentadilla con cadenas', 'legs', 'barbell', 'compound', 'free_exercise_db', 'Squat_with_Chains', ARRAY['To set up the chains, begin by looping the leader chain over the sleeves of the bar. The heavy chain should be attached using a snap hook. Adjust the length of the lead chain so that a few links are still on the floor at the top of the movement.', 'Begin by stepping under the bar and placing it across the back of the shoulders. Squeeze your shoulder blades together and rotate your elbows forward, attempting to bend the bar across your shoulders. Remove the bar from the rack, creating a tight arch in your lower back, and step back into position. Place your feet wide for more emphasis on the back, glutes, adductors, and hamstrings. Keep your head facing forward.', 'With your back, shoulders, and core tight, push your knees and butt out and you begin your descent. Sit back with your hips as much as possible. Ideally, your shins should be perpendicular to the ground. Lower bar position necessitates a greater torso lean to keep the bar over the heels. Continue until you break parallel, which is defined as the crease of the hip being in line with the top of the knee.', 'Keeping the weight on your heels and pushing your feet and knees out, drive upward as you lead the movement with your head. Continue upward, maintaining tightness head to toe, until you have returned to the starting position.']::text[], ARRAY['Squat_with_Chains/0.jpg', 'Squat_with_Chains/1.jpg']::text[], 'squat with chains squat co xich sentadilla con cadenas'),
  (NULL, 'Squat with Plate Movers', 'Squat with Plate Movers', 'Squat with Plate Movers', 'Sentadilla moviendo discos', 'legs', 'barbell', 'compound', 'free_exercise_db', 'Squat_with_Plate_Movers', ARRAY['To begin, first set the bar on a rack to just below shoulder level. Position a weight plate on the ground a couple feet back from the rack. Once the bar is loaded, step under it and place the back of your shoulders across it.', 'Hold on to the bar with both hands and lift it off the rack by first pushing with your legs and at the same time straighten your torso.', 'Step away from the rack and adopt a wide stance with the toes slightly pointed out, with one foot on the weight plate. Keep your head up at all times. This will be your starting position.', 'Begin to slowly lower the bar by bending the knees and hips. Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees.', 'Raise the bar as you exhale by pushing the floor with the heels of your feet as you extend the hips and knees.', 'At the top of the movement, side step, bringing your feet together on the opposite side of the plate.', 'Using your inside foot, push the weight plate, sliding it across the floor to where you were just standing.', 'Place your inside foot on the weight plate, adopting a wide stance for the next repetition.']::text[], ARRAY['Squat_with_Plate_Movers/0.jpg', 'Squat_with_Plate_Movers/1.jpg']::text[], 'squat with plate movers squat kem chuyen dia ta sentadilla moviendo discos'),
  (NULL, 'Squats - With Bands', 'Squats - With Bands', 'Squats - With Bands', 'Sentadillas con bandas', 'legs', 'band', 'compound', 'free_exercise_db', 'Squats_-_With_Bands', ARRAY['To start out, make sure that the exercise band is at an even split between both the left and right side of the body. To do this, use your hands to grab both sides of the band and place both feet in the middle of the band. Your feet should be shoulder width apart from each other.', 'When holding the bands, they should be the same height on each side. You should be using a pronated grip (palms facing forward) and have the handles of the bands next to your face for this exercise. This is the starting position.', 'Slowly start to bend the knees and lower the legs so that your thighs are parallel to the floor while exhaling.', 'Use the heel of your feet to push your body up to the starting position as you exhale.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Squats_-_With_Bands/0.jpg', 'Squats_-_With_Bands/1.jpg']::text[], 'squats - with bands squat voi day khang luc sentadillas con bandas'),
  (NULL, 'Stairmaster', 'Leo bậc (stairmaster)', 'Stairmaster', 'Escaladora', 'cardio', 'machine', 'timed', 'free_exercise_db', 'Stairmaster', ARRAY['To begin, step onto the stairmaster and select the desired option from the menu. You can choose a manual setting, or you can select a program to run. Typically, you can enter your age and weight to estimate the amount of calories burned during exercise.', 'Pump your legs up and down in an established rhythm, driving the pedals down but not all the way to the floor. It is recommended that you maintain your grip on the handles so that you don''t fall. The handles can be used to monitor your heart rate to help you stay at an appropriate intensity.', 'Stairmasters offer convenience, cardiovascular benefits, and usually have less impact than running outside. They are typically much harder than other cardio equipment. A 150 lb person will typically burn over 300 calories in 30 minutes, compared to about 175 calories walking.']::text[], ARRAY['Stairmaster/0.jpg', 'Stairmaster/1.jpg']::text[], 'stairmaster leo bac (stairmaster) escaladora'),
  (NULL, 'Standing Alternating Dumbbell Press', 'Đẩy vai đứng tạ đơn luân phiên', 'Standing Alternating Dumbbell Press', 'Press de pie alterno con mancuernas', 'shoulders', 'dumbbell', 'compound', 'free_exercise_db', 'Standing_Alternating_Dumbbell_Press', ARRAY['Stand with a dumbbell in each hand. Raise the dumbbells to your shoulders with your palms facing forward and your elbows pointed out. This will be your starting position.', 'Extend one arm to press the dumbbell straight up, keeping your off hand in place. Do not lean or jerk the weight during the movement.', 'After a brief pause, return the weight to the starting position.', 'Repeat for the opposite side, continuing to alternate between arms.']::text[], ARRAY['Standing_Alternating_Dumbbell_Press/0.jpg', 'Standing_Alternating_Dumbbell_Press/1.jpg']::text[], 'standing alternating dumbbell press day vai dung ta don luan phien press de pie alterno con mancuernas'),
  (NULL, 'Standing Barbell Calf Raise', 'Nhón bắp chân đứng tạ đòn', 'Standing Barbell Calf Raise', 'Elevación de gemelos de pie con barra', 'calves', 'barbell', 'isolation', 'free_exercise_db', 'Standing_Barbell_Calf_Raise', ARRAY['This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the bar on the back of your shoulders (slightly below the neck).', 'Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.', 'Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance and also maintain a straight back. The knees should be kept with a slight bend; never locked. This will be your starting position. Tip: For better range of motion you may also place the ball of your feet on a wooden block but be careful as this option requires more balance and a sturdy block.', 'Raise your heels as you breathe out by extending your ankles as high as possible and flexing your calf. Ensure that the knee is kept stationary at all times. There should be no bending at any time. Hold the contracted position by a second before you start to go back down.', 'Go back slowly to the starting position as you breathe in by lowering your heels as you bend the ankles until calves are stretched.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Standing_Barbell_Calf_Raise/0.jpg', 'Standing_Barbell_Calf_Raise/1.jpg']::text[], 'standing barbell calf raise nhon bap chan dung ta don elevacion de gemelos de pie con barra'),
  (NULL, 'Standing Barbell Press Behind Neck', 'Đẩy vai sau gáy đứng tạ đòn', 'Standing Barbell Press Behind Neck', 'Press tras nuca de pie con barra', 'shoulders', 'barbell', 'compound', 'free_exercise_db', 'Standing_Barbell_Press_Behind_Neck', ARRAY['This exercise is best performed inside a squat rack for easier pick up of the bar. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.', 'Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.', 'Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Your back should be kept straight while performing this exercise. This will be your starting position.', 'Elevate the barbell overhead by fully extending your arms while breathing out.', 'Hold the contraction for a second and lower the barbell back down to the starting position by inhaling.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Standing_Barbell_Press_Behind_Neck/0.jpg', 'Standing_Barbell_Press_Behind_Neck/1.jpg']::text[], 'standing barbell press behind neck day vai sau gay dung ta don press tras nuca de pie con barra'),
  (NULL, 'Standing Bent-Over One-Arm Dumbbell Triceps Extension', 'Duỗi tay sau một tay tạ đơn đứng cúi người', 'Standing Bent-Over One-Arm Dumbbell Triceps Extension', 'Extensión de tríceps de pie inclinado a una mano', 'triceps', 'dumbbell', 'isolation', 'free_exercise_db', 'Standing_Bent-Over_One-Arm_Dumbbell_Triceps_Extension', ARRAY['With a dumbbell in one hand and the palm facing your torso, bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Make sure that you keep the head up.', 'The upper arm should be close to the torso and parallel to the floor while the forearm is pointing towards the floor as the hand holds the weight. Tip: There should be a 90-degree angle between the forearm and the upper arm. This is your starting position.', 'Keeping the upper arms stationary, use the triceps to lift the weights as you exhale until the forearms are parallel to the floor and the whole arm is extended. Like many other arm exercises, only the forearm moves.', 'After a second contraction at the top, slowly lower the dumbbell back to the starting position as you inhale.', 'Repeat the movement for the prescribed amount of repetitions.', 'Switch arms and repeat the exercise.']::text[], ARRAY['Standing_Bent-Over_One-Arm_Dumbbell_Triceps_Extension/0.jpg', 'Standing_Bent-Over_One-Arm_Dumbbell_Triceps_Extension/1.jpg']::text[], 'standing bent-over one-arm dumbbell triceps extension duoi tay sau mot tay ta don dung cui nguoi extension de triceps de pie inclinado a una mano'),
  (NULL, 'Standing Bent-Over Two-Arm Dumbbell Triceps Extension', 'Duỗi tay sau hai tay tạ đơn đứng cúi người', 'Standing Bent-Over Two-Arm Dumbbell Triceps Extension', 'Extensión de tríceps de pie inclinado a dos manos', 'triceps', 'dumbbell', 'isolation', 'free_exercise_db', 'Standing_Bent-Over_Two-Arm_Dumbbell_Triceps_Extension', ARRAY['With a dumbbell in each hand and the palms facing your torso, bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Make sure that you keep the head up. The upper arms should be close to the torso and parallel to the floor while the forearms are pointing towards the floor as the hands hold the weights. Tip: There should be a 90-degree angle between the forearms and the upper arm. This is your starting position.', 'Keeping the upper arms stationary, use the triceps to lift the weights as you exhale until the forearms are parallel to the floor and the whole arms are extended. Like many other arm exercises, only the forearm moves.', 'After a second contraction at the top, slowly lower the dumbbells back to their starting position as you inhale.', 'Repeat the movement for the prescribed amount of repetitions.']::text[], ARRAY['Standing_Bent-Over_Two-Arm_Dumbbell_Triceps_Extension/0.jpg', 'Standing_Bent-Over_Two-Arm_Dumbbell_Triceps_Extension/1.jpg']::text[], 'standing bent-over two-arm dumbbell triceps extension duoi tay sau hai tay ta don dung cui nguoi extension de triceps de pie inclinado a dos manos'),
  (NULL, 'Standing Biceps Cable Curl', 'Standing Biceps Cable Curl', 'Standing Biceps Cable Curl', 'Curl de bíceps de pie en polea', 'biceps', 'cable', 'isolation', 'free_exercise_db', 'Standing_Biceps_Cable_Curl', ARRAY['Stand up with your torso upright while holding a cable curl bar that is attached to a low pulley. Grab the cable bar at shoulder width and keep the elbows close to the torso. The palm of your hands should be facing up (supinated grip). This will be your starting position.', 'While holding the upper arms stationary, curl the weights while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a second as you squeeze the muscle.', 'Slowly begin to bring the curl bar back to starting position as your breathe in.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Standing_Biceps_Cable_Curl/0.jpg', 'Standing_Biceps_Cable_Curl/1.jpg']::text[], 'standing biceps cable curl cuon tay truoc cap dung curl de biceps de pie en polea'),
  (NULL, 'Standing Biceps Stretch', 'Giãn tay trước đứng', 'Standing Biceps Stretch', 'Estiramiento de bíceps de pie', 'biceps', 'other', 'timed', 'free_exercise_db', 'Standing_Biceps_Stretch', ARRAY['Clasp your hands behind your back with your palms together, straighten arms and then rotate them so your palms face downward.', 'Raise your arms up and hold until you feel a stretch in your biceps.']::text[], ARRAY['Standing_Biceps_Stretch/0.jpg', 'Standing_Biceps_Stretch/1.jpg']::text[], 'standing biceps stretch gian tay truoc dung estiramiento de biceps de pie'),
  (NULL, 'Standing Bradford Press', 'Đẩy vai Bradford đứng', 'Standing Bradford Press', 'Press Bradford de pie', 'shoulders', 'barbell', 'compound', 'free_exercise_db', 'Standing_Bradford_Press', ARRAY['Place a loaded bar at shoulder level in a rack. With a pronated grip at shoulder width, begin with the bar racked across the front of your shoulders. This is your starting position.', 'Initiate the lift by extending the elbows to press the bar overhead. Avoid locking out the elbow as you move the weight behind your head.', 'Lower the bar down to the back of the head until your elbow forms a right angle.', 'Lift the bar back over your head by extending the elbows', 'Lower the bar down to the starting position.', 'Alternate in this manner until you complete the recommended amount of repetitions.']::text[], ARRAY['Standing_Bradford_Press/0.jpg', 'Standing_Bradford_Press/1.jpg']::text[], 'standing bradford press day vai bradford dung press bradford de pie'),
  (NULL, 'Standing Cable Chest Press', 'Đẩy ngực cáp đứng', 'Standing Cable Chest Press', 'Press de pecho de pie en polea', 'chest', 'cable', 'compound', 'free_exercise_db', 'Standing_Cable_Chest_Press', ARRAY['Position dual pulleys to chest height and select an appropriate weight. Stand a foot or two in front of the cables, holding one in each hand. You can stagger your stance for better stability.', 'Position the upper arm at a 90 degree angle with the shoulder blades together. This will be your starting position.', 'Keeping the rest of the body stationary, extend through the elbows to press the handles forward, drawing them together in front of you.', 'Pause at the top of the motion, and return to the starting position.']::text[], ARRAY['Standing_Cable_Chest_Press/0.jpg', 'Standing_Cable_Chest_Press/1.jpg']::text[], 'standing cable chest press day nguc cap dung press de pecho de pie en polea'),
  (NULL, 'Standing Cable Lift', 'Kéo cáp chéo từ dưới lên', 'Standing Cable Lift', 'Elevación diagonal en polea', 'abs', 'cable', 'compound', 'free_exercise_db', 'Standing_Cable_Lift', ARRAY['Connect a standard handle on a tower, and move the cable to the lowest pulley position.', 'With your side to the cable, grab the handle with one hand and step away from the tower. You should be approximately arm''s length away from the pulley, with the tension of the weight on the cable. Your outstretched arm should be aligned with the cable.', 'With your feet positioned shoulder width apart, squat down and grab the handle with both hands. Your arms should still be fully extended.', 'In one motion, pull the handle up and across your body until your arms are in a fully-extended position above your head.', 'Keep your back straight and your arms close to your body as you pivot your back foot and straighten your legs to get a full range of motion.', 'Retract your arms and then your body. Return to the neutral position in a slow and controlled manner.', 'Repeat to failure.', 'Then, reposition and repeat the same series of movements on the opposite side.']::text[], ARRAY['Standing_Cable_Lift/0.jpg', 'Standing_Cable_Lift/1.jpg']::text[], 'standing cable lift keo cap cheo tu duoi len elevacion diagonal en polea'),
  (NULL, 'Standing Cable Wood Chop', 'Chặt củi cáp đứng', 'Standing Cable Wood Chop', 'Leñador en polea de pie', 'abs', 'cable', 'compound', 'free_exercise_db', 'Standing_Cable_Wood_Chop', ARRAY['Connect a standard handle to a tower, and move the cable to the highest pulley position.', 'With your side to the cable, grab the handle with one hand and step away from the tower. You should be approximately arm''s length away from the pulley, with the tension of the weight on the cable. Your outstretched arm should be aligned with the cable.', 'With your feet positioned shoulder width apart, reach upward with your other hand and grab the handle with both hands. Your arms should still be fully extended.', 'In one motion, pull the handle down and across your body to your front knee while rotating your torso.', 'Keep your back and arms straight and core tight while you pivot your back foot and bend your knees to get a full range of motion.', 'Maintain your stance and straight arms. Return to the neutral position in a slow and controlled manner.', 'Repeat to failure.', 'Then, reposition and repeat the same series of movements on the opposite side.']::text[], ARRAY['Standing_Cable_Wood_Chop/0.jpg', 'Standing_Cable_Wood_Chop/1.jpg']::text[], 'standing cable wood chop chat cui cap dung lenador en polea de pie'),
  (NULL, 'Standing Calf Raises', 'Nhón bắp chân đứng', 'Standing Calf Raises', 'Elevación de gemelos de pie', 'calves', 'machine', 'isolation', 'free_exercise_db', 'Standing_Calf_Raises', ARRAY['Adjust the padded lever of the calf raise machine to fit your height.', 'Place your shoulders under the pads provided and position your toes facing forward (or using any of the two other positions described at the beginning of the chapter). The balls of your feet should be secured on top of the calf block with the heels extending off it. Push the lever up by extending your hips and knees until your torso is standing erect. The knees should be kept with a slight bend; never locked. Toes should be facing forward, outwards or inwards as described at the beginning of the chapter. This will be your starting position.', 'Raise your heels as you breathe out by extending your ankles as high as possible and flexing your calf. Ensure that the knee is kept stationary at all times. There should be no bending at any time. Hold the contracted position by a second before you start to go back down.', 'Go back slowly to the starting position as you breathe in by lowering your heels as you bend the ankles until calves are stretched.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Standing_Calf_Raises/0.jpg', 'Standing_Calf_Raises/1.jpg']::text[], 'standing calf raises nhon bap chan dung elevacion de gemelos de pie'),
  (NULL, 'Standing Concentration Curl', 'Standing Concentration Curl', 'Standing Concentration Curl', 'Curl concentrado de pie', 'biceps', 'dumbbell', 'isolation', 'free_exercise_db', 'Standing_Concentration_Curl', ARRAY['Taking a dumbbell in your working hand, lean forward. Allow your working arm to hang perpendicular to the ground with the elbow pointing out. This will be your starting position.', 'Flex the elbow to curl the weight, keeping the upper arm stationary. At the top of the repetition, flex the biceps and pause.', 'Lower the dumbbell back to the starting position.', 'Repeat the movement for the prescribed amount of repetitions.']::text[], ARRAY['Standing_Concentration_Curl/0.jpg', 'Standing_Concentration_Curl/1.jpg']::text[], 'standing concentration curl cuon tay truoc tap trung dung curl concentrado de pie'),
  (NULL, 'Standing Dumbbell Calf Raise', 'Nhón bắp chân đứng tạ đơn', 'Standing Dumbbell Calf Raise', 'Elevación de gemelos de pie con mancuernas', 'calves', 'dumbbell', 'isolation', 'free_exercise_db', 'Standing_Dumbbell_Calf_Raise', ARRAY['Stand with your torso upright holding two dumbbells in your hands by your sides. Place the ball of the foot on a sturdy and stable wooden board (that is around 2-3 inches tall) while your heels extend off and touch the floor. This will be your starting position.', 'With the toes pointing either straight (to hit all parts equally), inwards (for emphasis on the outer head) or outwards (for emphasis on the inner head), raise the heels off the floor as you exhale by contracting the calves. Hold the top contraction for a second.', 'As you inhale, go back to the starting position by slowly lowering the heels.', 'Repeat for the recommended amount of times.']::text[], ARRAY['Standing_Dumbbell_Calf_Raise/0.jpg', 'Standing_Dumbbell_Calf_Raise/1.jpg']::text[], 'standing dumbbell calf raise nhon bap chan dung ta don elevacion de gemelos de pie con mancuernas'),
  (NULL, 'Standing Dumbbell Press', 'Đẩy vai đứng tạ đơn', 'Standing Dumbbell Press', 'Press de pie con mancuernas', 'shoulders', 'dumbbell', 'compound', 'free_exercise_db', 'Standing_Dumbbell_Press', ARRAY['Standing with your feet shoulder width apart, take a dumbbell in each hand. Raise the dumbbells to head height, the elbows out and about 90 degrees. This will be your starting position.', 'Maintaining strict technique with no leg drive or leaning back, extend through the elbow to raise the weights together directly above your head.', 'Pause, and slowly return the weight to the starting position.']::text[], ARRAY['Standing_Dumbbell_Press/0.jpg', 'Standing_Dumbbell_Press/1.jpg']::text[], 'standing dumbbell press day vai dung ta don press de pie con mancuernas'),
  (NULL, 'Standing Dumbbell Reverse Curl', 'Standing Dumbbell Reverse Curl', 'Standing Dumbbell Reverse Curl', 'Curl invertido de pie con mancuernas', 'biceps', 'dumbbell', 'isolation', 'free_exercise_db', 'Standing_Dumbbell_Reverse_Curl', ARRAY['To begin, stand straight with a dumbbell in each hand using a pronated grip (palms facing down). Your arms should be fully extended while your feet are shoulder width apart from each other. This is the starting position.', 'While holding the upper arms stationary, curl the weights while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a second as you squeeze the muscle.', 'Slowly begin to bring the dumbbells back to starting position as your breathe in.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Standing_Dumbbell_Reverse_Curl/0.jpg', 'Standing_Dumbbell_Reverse_Curl/1.jpg']::text[], 'standing dumbbell reverse curl cuon ta don nam nguoc dung curl invertido de pie con mancuernas'),
  (NULL, 'Standing Dumbbell Straight-Arm Front Delt Raise Above Head', 'Nâng tạ đơn tay thẳng qua đầu', 'Standing Dumbbell Straight-Arm Front Delt Raise Above Head', 'Elevación frontal con brazos rectos sobre la cabeza', 'shoulders', 'dumbbell', 'isolation', 'free_exercise_db', 'Standing_Dumbbell_Straight-Arm_Front_Delt_Raise_Above_Head', ARRAY['Hold the dumbbells in front of your thighs, palms facing your thighs.', 'Keep your arms straight with a slight bend at the elbows but keep them locked. This will be your starting position.', 'Raise the dumbbells in a semicircular motion to arm''s length overhead as you exhale.', 'Slowly return to the starting position using the same path as you inhale.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Standing_Dumbbell_Straight-Arm_Front_Delt_Raise_Above_Head/0.jpg', 'Standing_Dumbbell_Straight-Arm_Front_Delt_Raise_Above_Head/1.jpg']::text[], 'standing dumbbell straight-arm front delt raise above head nang ta don tay thang qua dau elevacion frontal con brazos rectos sobre la cabeza'),
  (NULL, 'Standing Dumbbell Triceps Extension', 'Duỗi tay sau tạ đơn đứng', 'Standing Dumbbell Triceps Extension', 'Extensión de tríceps de pie con mancuerna', 'triceps', 'dumbbell', 'isolation', 'free_exercise_db', 'Standing_Dumbbell_Triceps_Extension', ARRAY['To begin, stand up with a dumbbell held by both hands. Your feet should be about shoulder width apart from each other. Slowly use both hands to grab the dumbbell and lift it over your head until both arms are fully extended.', 'The resistance should be resting in the palms of your hands with your thumbs around it. The palm of the hands should be facing up towards the ceiling. This will be your starting position.', 'Keeping your upper arms close to your head with elbows in and perpendicular to the floor, lower the resistance in a semicircular motion behind your head until your forearms touch your biceps. Tip: The upper arms should remain stationary and only the forearms should move. Breathe in as you perform this step.', 'Go back to the starting position by using the triceps to raise the dumbbell. Breathe out as you perform this step.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Standing_Dumbbell_Triceps_Extension/0.jpg', 'Standing_Dumbbell_Triceps_Extension/1.jpg']::text[], 'standing dumbbell triceps extension duoi tay sau ta don dung extension de triceps de pie con mancuerna'),
  (NULL, 'Standing Dumbbell Upright Row', 'Kéo thẳng đứng tạ đơn', 'Standing Dumbbell Upright Row', 'Remo al mentón con mancuernas', 'shoulders', 'dumbbell', 'compound', 'free_exercise_db', 'Standing_Dumbbell_Upright_Row', ARRAY['Grasp a dumbbell in each hand with a pronated (palms forward) grip that is slightly less than shoulder width. The dumbbells should be resting on top of your thighs. Your arms should be extended with a slight bend at the elbows and your back should be straight. This will be your starting position.', 'Use your side shoulders to lift the dumbbells as you exhale. The dumbbells should be close to the body as you move it up and the elbows should drive the motion. Continue to lift them until they nearly touch your chin. Tip: Your elbows should drive the motion. As you lift the dumbbells, your elbows should always be higher than your forearms. Also, keep your torso stationary and pause for a second at the top of the movement.', 'Lower the dumbbells back down slowly to the starting position. Inhale as you perform this portion of the movement.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Standing_Dumbbell_Upright_Row/0.jpg', 'Standing_Dumbbell_Upright_Row/1.jpg']::text[], 'standing dumbbell upright row keo thang dung ta don remo al menton con mancuernas'),
  (NULL, 'Standing Elevated Quad Stretch', 'Giãn đùi trước đứng gác chân cao', 'Standing Elevated Quad Stretch', 'Estiramiento de cuádriceps de pie con pierna elevada', 'legs', 'other', 'timed', 'free_exercise_db', 'Standing_Elevated_Quad_Stretch', ARRAY['Start by standing with your back about two to three feet away from a bench or step.', 'Lift one leg behind you and rest your foot on the step,either on your instep or the ball of your foot, whichever you find most comfortable.', 'Keep your supporting knee slightly bent and avoid letting that knee extend out beyond your toes. Switch sides.']::text[], ARRAY['Standing_Elevated_Quad_Stretch/0.jpg', 'Standing_Elevated_Quad_Stretch/1.jpg']::text[], 'standing elevated quad stretch gian dui truoc dung gac chan cao estiramiento de cuadriceps de pie con pierna elevada'),
  (NULL, 'Standing Front Barbell Raise Over Head', 'Nâng tạ đòn trước qua đầu', 'Standing Front Barbell Raise Over Head', 'Elevación frontal con barra sobre la cabeza', 'shoulders', 'barbell', 'isolation', 'free_exercise_db', 'Standing_Front_Barbell_Raise_Over_Head', ARRAY['To begin, stand straight with a barbell in your hands. You should grip the bar with palms facing down and a closer than shoulder width grip apart from each other.', 'Your feet should be shoulder width apart from each other. Your elbows should be slightly bent. This is the starting position.', 'Lift the barbell up until it is directly over your head while exhaling. Make sure to keep your elbows slightly bent when performing each repetition.', 'Once you feel the contraction, begin to lower the barbell back down to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Standing_Front_Barbell_Raise_Over_Head/0.jpg', 'Standing_Front_Barbell_Raise_Over_Head/1.jpg']::text[], 'standing front barbell raise over head nang ta don truoc qua dau elevacion frontal con barra sobre la cabeza'),
  (NULL, 'Standing Gastrocnemius Calf Stretch', 'Giãn bắp chân đứng', 'Standing Gastrocnemius Calf Stretch', 'Estiramiento de gastrocnemio de pie', 'calves', 'other', 'timed', 'free_exercise_db', 'Standing_Gastrocnemius_Calf_Stretch', ARRAY['Place your right heel on a step with your knee extended and lean forward to grab your right toe with your right hand. Your left knee should be slightly bent and your back should be straight.', 'Support your weight on your left leg and place your left hand on your left thigh.', 'Pull your right toes toward your knee until you feel a stretch in your calf.']::text[], ARRAY['Standing_Gastrocnemius_Calf_Stretch/0.jpg', 'Standing_Gastrocnemius_Calf_Stretch/1.jpg']::text[], 'standing gastrocnemius calf stretch gian bap chan dung estiramiento de gastrocnemio de pie'),
  (NULL, 'Standing Hamstring and Calf Stretch', 'Giãn đùi sau và bắp chân đứng', 'Standing Hamstring and Calf Stretch', 'Estiramiento de isquios y gemelos de pie', 'legs', 'other', 'timed', 'free_exercise_db', 'Standing_Hamstring_and_Calf_Stretch', ARRAY['Being by looping a belt, band, or rope around one foot. While standing, place that foot forward.', 'Bend your back leg, while keeping the front one straight. Now raise the toes of your front foot off of the ground and lean forward.', 'Using the belt, pull on the top of the foot to increase the stretch in the calf. Hold for 10-20 seconds and repeat with the other foot.']::text[], ARRAY['Standing_Hamstring_and_Calf_Stretch/0.jpg', 'Standing_Hamstring_and_Calf_Stretch/1.jpg']::text[], 'standing hamstring and calf stretch gian dui sau va bap chan dung estiramiento de isquios y gemelos de pie'),
  (NULL, 'Standing Hip Circles', 'Xoay hông đứng', 'Standing Hip Circles', 'Círculos de cadera de pie', 'legs', 'bodyweight', 'timed', 'free_exercise_db', 'Standing_Hip_Circles', ARRAY['Begin standing on one leg, holding to a vertical support.', 'Raise the unsupported knee to 90 degrees. This will be your starting position.', 'Open the hip as far as possible, attempting to make a big circle with your knee.', 'Perform this movement slowly for a number of repetitions, and repeat on the other side.']::text[], ARRAY['Standing_Hip_Circles/0.jpg', 'Standing_Hip_Circles/1.jpg']::text[], 'standing hip circles xoay hong dung circulos de cadera de pie'),
  (NULL, 'Standing Hip Flexors', 'Giãn cơ gấp hông đứng', 'Standing Hip Flexors', 'Estiramiento de flexores de cadera de pie', 'legs', 'other', 'timed', 'free_exercise_db', 'Standing_Hip_Flexors', ARRAY['Stand up straight with the spine vertical, the left foot slightly in front of the right.', 'Bend both knees and lift the back heel off the floor as you press the right hip forward. You can''t get a thorough, deep stretch in this position, however, because it''s hard to relax the hip flexor and stand on it at the same time. Switch sides.']::text[], ARRAY['Standing_Hip_Flexors/0.jpg', 'Standing_Hip_Flexors/1.jpg']::text[], 'standing hip flexors gian co gap hong dung estiramiento de flexores de cadera de pie'),
  (NULL, 'Standing Inner-Biceps Curl', 'Standing Inner-Biceps Curl', 'Standing Inner-Biceps Curl', 'Curl interno de bíceps de pie', 'biceps', 'dumbbell', 'isolation', 'free_exercise_db', 'Standing_Inner-Biceps_Curl', ARRAY['Stand up with a dumbbell in each hand being held at arms length. The elbows should be close to the torso. Your legs should be at about shoulder''s width apart from each other.', 'Rotate the palms of the hands so that they are facing inward in a neutral position. This will be your starting position.', 'While holding the upper arms stationary, curl the weights out while contracting the biceps as you breathe out. Your wrist should turn so that when the weights are fully elevated you have supinated grip (palms facing up).', 'Only the forearms should move. Continue the movement until your biceps are fully contracted and the dumbbells are at shoulder level. Tip: Keep the forearms aligned with your outer deltoids.', 'Hold the contracted position for a second as you squeeze the biceps.', 'Slowly begin to bring the dumbbells back to the starting position as your breathe in. Remember to rotate the wrists as you lower the weight in order to switch back to a neutral grip.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Standing_Inner-Biceps_Curl/0.jpg', 'Standing_Inner-Biceps_Curl/1.jpg']::text[], 'standing inner-biceps curl cuon tay truoc trong dung curl interno de biceps de pie'),
  (NULL, 'Standing Lateral Stretch', 'Giãn hông nghiêng đứng', 'Standing Lateral Stretch', 'Estiramiento lateral de pie', 'abs', 'other', 'timed', 'free_exercise_db', 'Standing_Lateral_Stretch', ARRAY['Take a slightly wider than hip distance stance with your knees slightly bent.', 'Place your right hand on your right hip to support the spine.', 'Raise your left arm in a vertical line and place your left hand behind your head. Keep it there as you incline your torso to the right.', 'Keep your weight evenly distributed between both legs (don''t lean into your left hip). Switch sides.']::text[], ARRAY['Standing_Lateral_Stretch/0.jpg', 'Standing_Lateral_Stretch/1.jpg']::text[], 'standing lateral stretch gian hong nghieng dung estiramiento lateral de pie'),
  (NULL, 'Standing Leg Curl', 'Standing Leg Curl', 'Standing Leg Curl', 'Curl femoral de pie', 'legs', 'machine', 'isolation', 'free_exercise_db', 'Standing_Leg_Curl', ARRAY['Adjust the machine lever to fit your height and lie with your torso bent at the waist facing forward around 30-45 degrees (since an angled position is more favorable for hamstrings recruitment) with the pad of the lever on the back of your right leg (just a few inches under the calves) and the front of the right leg on top of the machine pad.', 'Keeping the torso bent forward, ensure your leg is fully stretched and grab the side handles of the machine. Position your toes straight. This will be your starting position.', 'As you exhale, curl your right leg up as far as possible without lifting the upper leg from the pad. Once you hit the fully contracted position, hold it for a second.', 'As you inhale, bring the legs back to the initial position. Repeat for the recommended amount of repetitions.', 'Perform the same exercise now for the left leg.']::text[], ARRAY['Standing_Leg_Curl/0.jpg', 'Standing_Leg_Curl/1.jpg']::text[], 'standing leg curl cuon dui sau dung curl femoral de pie'),
  (NULL, 'Standing Long Jump', 'Bật xa tại chỗ', 'Standing Long Jump', 'Salto largo de pie', 'legs', 'bodyweight', 'bodyweight', 'free_exercise_db', 'Standing_Long_Jump', ARRAY['This drill is best done in sand or other soft landing surface. Ensure that you are able to measure distance. Stand in a partial squat stance with feet shoulder width apart.', 'Utilizing a big arm swing and a countermovement of the legs, jump forward as far as you can.', 'Attempt to land with your feet out in front you, reaching as far as possible with your legs.', 'Measure the distance from your landing point to the starting point and track results.']::text[], ARRAY['Standing_Long_Jump/0.jpg', 'Standing_Long_Jump/1.jpg']::text[], 'standing long jump bat xa tai cho salto largo de pie'),
  (NULL, 'Standing Low-Pulley Deltoid Raise', 'Nâng vai cáp thấp đứng', 'Standing Low-Pulley Deltoid Raise', 'Elevación de deltoides en polea baja de pie', 'shoulders', 'cable', 'isolation', 'free_exercise_db', 'Standing_Low-Pulley_Deltoid_Raise', ARRAY['Start by standing to the right side of a low pulley row. Use your left hand to come across the body and grab a single handle attached to the low pulley with a pronated grip (palms facing down). Rest your arm in front of you. Your right hand should grab the machine for better support and balance.', 'Make sure that your back is erect and your feet are shoulder width apart from each other. This is the starting position.', 'Begin to use the left hand and come across your body out until it is elevated to shoulder height while exhaling.', 'Feel the contraction at the top for a second and begin to slowly lower the handle back down to the original starting position while inhaling.', 'Repeat for the recommended amount of repetitions.', 'Switch arms and repeat the exercise.']::text[], ARRAY['Standing_Low-Pulley_Deltoid_Raise/0.jpg', 'Standing_Low-Pulley_Deltoid_Raise/1.jpg']::text[], 'standing low-pulley deltoid raise nang vai cap thap dung elevacion de deltoides en polea baja de pie'),
  (NULL, 'Standing Low-Pulley One-Arm Triceps Extension', 'Duỗi tay sau một tay cáp thấp đứng', 'Standing Low-Pulley One-Arm Triceps Extension', 'Extensión de tríceps a una mano en polea baja', 'triceps', 'cable', 'isolation', 'free_exercise_db', 'Standing_Low-Pulley_One-Arm_Triceps_Extension', ARRAY['Grab a single handle with your left arm next to the low pulley machine. Turn away from the machine keeping the handle to the side of your body with your arm fully extended. Now use both hands to elevate the single handle directly above the head with the palm facing forward. Keep your upper arm completely vertical (perpendicular to the floor) and put your right hand on your left elbow to help keep it steady. This is the starting position.', 'Keeping your upper arms close to your head (elbows in) and perpendicular to the floor, lower the resistance in a semicircular motion behind your head until your forearms touch your biceps. Tip: The upper arms should remain stationary and only the forearms should move. Breathe in as you perform this step.', 'Go back to the starting position by using the triceps to raise the single handle. Breathe out as you perform this step.', 'Repeat for the recommended amount of repetitions.', 'Switch arms and repeat the exercise.']::text[], ARRAY['Standing_Low-Pulley_One-Arm_Triceps_Extension/0.jpg', 'Standing_Low-Pulley_One-Arm_Triceps_Extension/1.jpg']::text[], 'standing low-pulley one-arm triceps extension duoi tay sau mot tay cap thap dung extension de triceps a una mano en polea baja'),
  (NULL, 'Standing Military Press', 'Đẩy vai đứng tạ đòn', 'Standing Military Press', 'Press militar de pie', 'shoulders', 'barbell', 'compound', 'free_exercise_db', 'Standing_Military_Press', ARRAY['Start by placing a barbell that is about chest high on a squat rack. Once you have selected the weights, grab the barbell using a pronated (palms facing forward) grip. Make sure to grip the bar wider than shoulder width apart from each other.', 'Slightly bend the knees and place the barbell on your collar bone. Lift the barbell up keeping it lying on your chest. Take a step back and position your feet shoulder width apart from each other.', 'Once you pick up the barbell with the correct grip length, lift the bar up over your head by locking your arms. Hold at about shoulder level and slightly in front of your head. This is your starting position.', 'Lower the bar down to the collarbone slowly as you inhale.', 'Lift the bar back up to the starting position as you exhale.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Standing_Military_Press/0.jpg', 'Standing_Military_Press/1.jpg']::text[], 'standing military press day vai dung ta don press militar de pie'),
  (NULL, 'Standing Olympic Plate Hand Squeeze', 'Bóp đĩa tạ Olympic đứng', 'Standing Olympic Plate Hand Squeeze', 'Apretón de disco olímpico de pie', 'biceps', 'other', 'isolation', 'free_exercise_db', 'Standing_Olympic_Plate_Hand_Squeeze', ARRAY['To begin, stand straight while holding a weight plate by the ridge at arm''s length in each hand using a neutral grip (palms facing in). You feet should be shoulder width apart from each other. This will be your starting position.', 'Lower the plates until the fingers are nearly extended but can still hold weights. Inhale as you lower the plates.', 'Now raise the plates back to the starting position as you exhale by closing your hands.', 'Repeat for the recommended amount of repetitions prescribed in your program.']::text[], ARRAY['Standing_Olympic_Plate_Hand_Squeeze/0.jpg', 'Standing_Olympic_Plate_Hand_Squeeze/1.jpg']::text[], 'standing olympic plate hand squeeze bop dia ta olympic dung apreton de disco olimpico de pie'),
  (NULL, 'Standing One-Arm Cable Curl', 'Standing One-Arm Cable Curl', 'Standing One-Arm Cable Curl', 'Curl a una mano en polea de pie', 'biceps', 'cable', 'isolation', 'free_exercise_db', 'Standing_One-Arm_Cable_Curl', ARRAY['Start out by grabbing single handle next to the low pulley machine. Make sure you are far enough from the machine so that your arm is supporting the weight.', 'Make sure that your upper arm is stationary, perpendicular to the floor with elbows in and palms facing forward. Your non lifting arm should be grabbing your waist. This will allow you to keep your balance.', 'Slowly begin to curl the single handle upwards while keeping the upper arm stationary until your forearm touches your bicep while exhaling. Tip: Only the forearm should move.', 'Hold the contraction position as you squeeze the bicep and then lower the single handle back down to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions.', 'Switch arms while performing this exercise.']::text[], ARRAY['Standing_One-Arm_Cable_Curl/0.jpg', 'Standing_One-Arm_Cable_Curl/1.jpg']::text[], 'standing one-arm cable curl cuon tay truoc cap mot tay dung curl a una mano en polea de pie'),
  (NULL, 'Standing One-Arm Dumbbell Curl Over Incline Bench', 'Standing One-Arm Dumbbell Curl Over Incline Bench', 'Standing One-Arm Dumbbell Curl Over Incline Bench', 'Curl a una mano sobre banco inclinado de pie', 'biceps', 'dumbbell', 'isolation', 'free_exercise_db', 'Standing_One-Arm_Dumbbell_Curl_Over_Incline_Bench', ARRAY['Stand on the back side of an incline bench as if you were going to be a spotter for someone. Have a dumbbell in one hand and rest it across the incline bench with a supinated (palms up) grip.', 'Position your non lifting hand at the corner or side of the incline bench. The chest should be pressed against the top part of the incline and your feet should be pressed against the floor at a wide stance. This is the starting position.', 'While holding the upper arm stationary, curl the dumbbell upward while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the dumbbell is at shoulder level. Hold the contracted position for a second.', 'Slowly begin to bring the dumbbells back to starting position as your breathe in.', 'Repeat for the recommended amount of repetitions.', 'Switch arms while performing this exercise.']::text[], ARRAY['Standing_One-Arm_Dumbbell_Curl_Over_Incline_Bench/0.jpg', 'Standing_One-Arm_Dumbbell_Curl_Over_Incline_Bench/1.jpg']::text[], 'standing one-arm dumbbell curl over incline bench cuon ta don mot tay dung tua ghe doc curl a una mano sobre banco inclinado de pie'),
  (NULL, 'Standing One-Arm Dumbbell Triceps Extension', 'Duỗi tay sau một tay tạ đơn đứng', 'Standing One-Arm Dumbbell Triceps Extension', 'Extensión de tríceps a una mano de pie', 'triceps', 'dumbbell', 'isolation', 'free_exercise_db', 'Standing_One-Arm_Dumbbell_Triceps_Extension', ARRAY['To begin, stand up with a dumbbell held in one hand. Your feet should be about shoulder width apart from each other. Now fully extend the arm with the dumbbell over your head. Tip: The small finger of your hand should be facing the ceiling and the palm of your hand should be facing forward. The dumbbell should be above your head.', 'This will be your starting position.', 'Keeping your upper arm close to your head (elbows in) and perpendicular to the floor, lower the resistance in a semicircular motion behind your head until your forearm touch your bicep. Tip: The upper arm should remain stationary and only the forearm should move. Breathe in as you perform this step.', 'Go back to the starting position by using the triceps to raise the dumbbell. Breathe out as you perform this step.', 'Repeat for the recommended amount of repetitions.', 'Switch arms and repeat the exercise.']::text[], ARRAY['Standing_One-Arm_Dumbbell_Triceps_Extension/0.jpg', 'Standing_One-Arm_Dumbbell_Triceps_Extension/1.jpg']::text[], 'standing one-arm dumbbell triceps extension duoi tay sau mot tay ta don dung extension de triceps a una mano de pie'),
  (NULL, 'Standing Overhead Barbell Triceps Extension', 'Duỗi tay sau qua đầu tạ đòn đứng', 'Standing Overhead Barbell Triceps Extension', 'Extensión de tríceps sobre la cabeza con barra de pie', 'triceps', 'barbell', 'isolation', 'free_exercise_db', 'Standing_Overhead_Barbell_Triceps_Extension', ARRAY['To begin, stand up holding a barbell or e-z bar using a pronated grip (palms facing forward) with your hands closer than shoulder width apart from each other. Your feet should be about shoulder width apart.', 'Now elevate the barbell above your head until your arms are fully extended. Keep your elbows in. This will be your starting position.', 'Keeping your upper arms close to your head and elbows in, perpendicular to the floor, lower the resistance in a semicircular motion behind your head until your forearms touch your biceps. Tip: The upper arms should remain stationary and only the forearms should move. Breathe in as you perform this step.', 'Go back to the starting position by using the triceps to raise the barbell. Breathe out as you perform this step.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Standing_Overhead_Barbell_Triceps_Extension/0.jpg', 'Standing_Overhead_Barbell_Triceps_Extension/1.jpg']::text[], 'standing overhead barbell triceps extension duoi tay sau qua dau ta don dung extension de triceps sobre la cabeza con barra de pie'),
  (NULL, 'Standing Palm-In One-Arm Dumbbell Press', 'Đẩy vai một tay tạ đơn lòng tay hướng vào', 'Standing Palm-In One-Arm Dumbbell Press', 'Press a una mano con mancuerna agarre neutro', 'shoulders', 'dumbbell', 'compound', 'free_exercise_db', 'Standing_Palm-In_One-Arm_Dumbbell_Press', ARRAY['Start by having a dumbbell in one hand with your arm fully extended to the side using a neutral grip. Use your other arm to hold on to an incline bench to keep your balance.', 'Your feet should be shoulder width apart from each other. Now slowly lift the dumbbell up until you create a 90 degree angle with your arm. Note: Your forearm should be perpendicular to the floor. Continue to maintain a neutral grip throughout the entire exercise.', 'Slowly lift the dumbbell up until your arm is fully extended. This the starting position.', 'While inhaling lower the weight down until your arm is at a 90 degree angle again.', 'Feel the contraction for a second and then lift the weight back up towards the starting position while exhaling. Remember to hold on to the incline bench and keep your feet positioned to keep balance during the exercise.', 'Repeat for the recommended amount of repetitions.', 'Switch arms and repeat the exercise.']::text[], ARRAY['Standing_Palm-In_One-Arm_Dumbbell_Press/0.jpg', 'Standing_Palm-In_One-Arm_Dumbbell_Press/1.jpg']::text[], 'standing palm-in one-arm dumbbell press day vai mot tay ta don long tay huong vao press a una mano con mancuerna agarre neutro'),
  (NULL, 'Standing Palms-In Dumbbell Press', 'Đẩy vai tạ đơn lòng tay hướng vào', 'Standing Palms-In Dumbbell Press', 'Press con mancuernas agarre neutro de pie', 'shoulders', 'dumbbell', 'compound', 'free_exercise_db', 'Standing_Palms-In_Dumbbell_Press', ARRAY['Start by having a dumbbell in each hand with your arm fully extended to the side using a neutral grip. Your feet should be shoulder width apart from each other. Now slowly lift the dumbbells up until you create a 90 degree angle with your arms. Note: Your forearms should be perpendicular to the floor. This the starting position.', 'Continue to maintain a neutral grip throughout the entire exercise. Slowly lift the dumbbells up until your arms are fully extended.', 'While inhaling lower the weights down until your arm is at a 90 degree angle again.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Standing_Palms-In_Dumbbell_Press/0.jpg', 'Standing_Palms-In_Dumbbell_Press/1.jpg']::text[], 'standing palms-in dumbbell press day vai ta don long tay huong vao press con mancuernas agarre neutro de pie'),
  (NULL, 'Standing Palms-Up Barbell Behind The Back Wrist Curl', 'Standing Palms-Up Barbell Behind The Back Wrist Curl', 'Standing Palms-Up Barbell Behind The Back Wrist Curl', 'Curl de muñeca con barra tras la espalda', 'biceps', 'barbell', 'isolation', 'free_exercise_db', 'Standing_Palms-Up_Barbell_Behind_The_Back_Wrist_Curl', ARRAY['Start by standing straight and holding a barbell behind your glutes at arm''s length while using a pronated grip (palms will be facing back away from the glutes) and having your hands shoulder width apart from each other.', 'You should be looking straight forward while your feet are shoulder width apart from each other. This is the starting position.', 'While exhaling, slowly elevate the barbell up by curling your wrist in a semi-circular motion towards the ceiling. Note: Your wrist should be the only body part moving for this exercise.', 'Hold the contraction for a second and lower the barbell back down to the starting position while inhaling.', 'Repeat for the recommended amount of repetitions.', 'When finished, lower the barbell down to the squat rack or the floor by bending the knees. Tip: It is easiest to either pick it up from a squat rack or have a partner hand it to you.']::text[], ARRAY['Standing_Palms-Up_Barbell_Behind_The_Back_Wrist_Curl/0.jpg', 'Standing_Palms-Up_Barbell_Behind_The_Back_Wrist_Curl/1.jpg']::text[], 'standing palms-up barbell behind the back wrist curl cuon co tay nam ngua ta don sau lung curl de muneca con barra tras la espalda'),
  (NULL, 'Standing Pelvic Tilt', 'Nghiêng chậu đứng', 'Standing Pelvic Tilt', 'Inclinación pélvica de pie', 'back', 'other', 'timed', 'free_exercise_db', 'Standing_Pelvic_Tilt', ARRAY['Start off with your feet hip-distance apart.', 'Bend your knees slightly to keep them soft and springy.', 'You may want to move your pelvis forward and backward and back few times before holding the tailbone forward in this stretch.']::text[], ARRAY['Standing_Pelvic_Tilt/0.jpg', 'Standing_Pelvic_Tilt/1.jpg']::text[], 'standing pelvic tilt nghieng chau dung inclinacion pelvica de pie'),
  (NULL, 'Standing Rope Crunch', 'Standing Rope Crunch', 'Standing Rope Crunch', 'Crunch de pie con cuerda', 'abs', 'cable', 'isolation', 'free_exercise_db', 'Standing_Rope_Crunch', ARRAY['Attach a rope to a high pulley and select an appropriate weight.', 'Stand with your back to the cable tower. Take the rope with both hands over your shoulders, holding it to your upper chest. This will be your starting position.', 'Perform the movement by flexing the spine, crunching the weight down as far as you can.', 'Hold the peak contraction for a moment before returning to the starting position.']::text[], ARRAY['Standing_Rope_Crunch/0.jpg', 'Standing_Rope_Crunch/1.jpg']::text[], 'standing rope crunch gap bung cap day thung dung crunch de pie con cuerda'),
  (NULL, 'Standing Soleus And Achilles Stretch', 'Giãn cơ dép và gân gót đứng', 'Standing Soleus And Achilles Stretch', 'Estiramiento de sóleo y Aquiles de pie', 'calves', 'other', 'timed', 'free_exercise_db', 'Standing_Soleus_And_Achilles_Stretch', ARRAY['Stand with your feet hip-distance apart, one foot slightly in front of the other.', 'Bend both knees, keeping your back heel on the floor. Switch sides.']::text[], ARRAY['Standing_Soleus_And_Achilles_Stretch/0.jpg', 'Standing_Soleus_And_Achilles_Stretch/1.jpg']::text[], 'standing soleus and achilles stretch gian co dep va gan got dung estiramiento de soleo y aquiles de pie'),
  (NULL, 'Standing Toe Touches', 'Chạm mũi chân đứng', 'Standing Toe Touches', 'Tocar las puntas de pie', 'legs', 'other', 'timed', 'free_exercise_db', 'Standing_Toe_Touches', ARRAY['Stand with some space in front and behind you.', 'Bend at the waist, keeping your legs straight, until you can relax and let your upper body hang down in front of you. Let your arms and hands hang down naturally. Hold for 10 to 20 seconds.']::text[], ARRAY['Standing_Toe_Touches/0.jpg', 'Standing_Toe_Touches/1.jpg']::text[], 'standing toe touches cham mui chan dung tocar las puntas de pie'),
  (NULL, 'Standing Towel Triceps Extension', 'Duỗi tay sau với khăn đứng', 'Standing Towel Triceps Extension', 'Extensión de tríceps con toalla de pie', 'triceps', 'bodyweight', 'bodyweight', 'free_exercise_db', 'Standing_Towel_Triceps_Extension', ARRAY['To begin, stand up with both arms fully extended above the head holding one end of a towel with both hands. Your elbows should be in and the arms perpendicular to the floor with the palms facing each other while your feet should be shoulder width apart from each other. This is the starting position.', 'Now communicate with your partner so that he/she can grip the other side of the towel to apply resistance. Keeping your upper arms close to your head (elbows in) and perpendicular to the floor, lower the resistance in a semicircular motion behind your head until your forearms touch your biceps. Tip: The upper arms should remain stationary and only the forearms should move. Breathe in as you perform this step.', 'Go back to the starting position by using the triceps to raise the towel. Breathe out as you perform this step.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Standing_Towel_Triceps_Extension/0.jpg', 'Standing_Towel_Triceps_Extension/1.jpg']::text[], 'standing towel triceps extension duoi tay sau voi khan dung extension de triceps con toalla de pie'),
  (NULL, 'Standing Two-Arm Overhead Throw', 'Ném bóng tạ qua đầu hai tay', 'Standing Two-Arm Overhead Throw', 'Lanzamiento sobre la cabeza a dos manos', 'shoulders', 'medicine ball', 'compound', 'free_exercise_db', 'Standing_Two-Arm_Overhead_Throw', ARRAY['Stand with your feet shoulder width apart holding a medicine ball in both hands. To begin, reach the medicine ball deep behind your head as you bend the knees slightly and lean back.', 'Violently throw the ball forward, flexing at the hip and using your whole body to complete the movement.', 'The medicine ball can be thrown to a partner or to a wall, receiving it as it bounces back.']::text[], ARRAY['Standing_Two-Arm_Overhead_Throw/0.jpg', 'Standing_Two-Arm_Overhead_Throw/1.jpg']::text[], 'standing two-arm overhead throw nem bong ta qua dau hai tay lanzamiento sobre la cabeza a dos manos'),
  (NULL, 'Star Jump', 'Bật nhảy hình sao', 'Star Jump', 'Salto estrella', 'legs', 'bodyweight', 'bodyweight', 'free_exercise_db', 'Star_Jump', ARRAY['Begin in a relaxed stance with your feet shoulder width apart and hold your arms close to the body.', 'To initiate the move, squat down halfway and explode back up as high as possible. Fully extend your entire body, spreading your legs and arms away from the body.', 'As you land, bring your limbs back in and absorb your impact through the legs.']::text[], ARRAY['Star_Jump/0.jpg', 'Star_Jump/1.jpg']::text[], 'star jump bat nhay hinh sao salto estrella'),
  (NULL, 'Step-up with Knee Raise', 'Bước bục kèm nâng gối', 'Step-up with Knee Raise', 'Subida al cajón con elevación de rodilla', 'glutes', 'bodyweight', 'bodyweight', 'free_exercise_db', 'Step-up_with_Knee_Raise', ARRAY['Stand facing a box or bench of an appropriate height with your feet together. This will be your starting position.', 'Begin the movement by stepping up, putting your left foot on the top of the bench. Extend through the hip and knee of your front leg to stand up on the box. As you stand on the box with your left leg, flex your right knee and hip, bringing your knee as high as you can.', 'Reverse this motion to step down off the box, and then repeat the sequence on the opposite leg.']::text[], ARRAY['Step-up_with_Knee_Raise/0.jpg', 'Step-up_with_Knee_Raise/1.jpg']::text[], 'step-up with knee raise buoc buc kem nang goi subida al cajon con elevacion de rodilla'),
  (NULL, 'Step Mill', 'Máy leo bậc thang', 'Step Mill', 'Escaladora de peldaños', 'cardio', 'machine', 'timed', 'free_exercise_db', 'Step_Mill', ARRAY['To begin, step onto the stepmill and select the desired option from the menu. You can choose a manual setting, or you can select a program to run. Typically, you can enter your age and weight to estimate the amount of calories burned during exercise. Use caution so that you don''t trip as you climb the stairs. It is recommended that you maintain your grip on the handles so that you don''t fall.', 'Stepmills offer convenience, cardiovascular benefits, and usually have less impact than running outside while offering a similar rate of calories burned. They are typically much harder than other cardio equipment. A 150 lb person will typically burn over 300 calories in 30 minutes, compared to about 175 calories walking.']::text[], ARRAY['Step_Mill/0.jpg', 'Step_Mill/1.jpg']::text[], 'step mill may leo bac thang escaladora de peldanos'),
  (NULL, 'Stiff-Legged Barbell Deadlift', 'Stiff-Legged Barbell Deadlift', 'Stiff-Legged Barbell Deadlift', 'Peso muerto piernas rígidas con barra', 'legs', 'barbell', 'compound', 'free_exercise_db', 'Stiff-Legged_Barbell_Deadlift', ARRAY['Grasp a bar using an overhand grip (palms facing down). You may need some wrist wraps if using a significant amount of weight.', 'Stand with your torso straight and your legs spaced using a shoulder width or narrower stance. The knees should be slightly bent. This is your starting position.', 'Keeping the knees stationary, lower the barbell to over the top of your feet by bending at the hips while keeping your back straight. Keep moving forward as if you were going to pick something from the floor until you feel a stretch on the hamstrings. Inhale as you perform this movement.', 'Start bringing your torso up straight again by extending your hips until you are back at the starting position. Exhale as you perform this movement.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Stiff-Legged_Barbell_Deadlift/0.jpg', 'Stiff-Legged_Barbell_Deadlift/1.jpg']::text[], 'stiff-legged barbell deadlift deadlift chan thang ta don peso muerto piernas rigidas con barra'),
  (NULL, 'Stiff-Legged Dumbbell Deadlift', 'Stiff-Legged Dumbbell Deadlift', 'Stiff-Legged Dumbbell Deadlift', 'Peso muerto piernas rígidas con mancuernas', 'legs', 'dumbbell', 'compound', 'free_exercise_db', 'Stiff-Legged_Dumbbell_Deadlift', ARRAY['Grasp a couple of dumbbells holding them by your side at arm''s length.', 'Stand with your torso straight and your legs spaced using a shoulder width or narrower stance. The knees should be slightly bent. This is your starting position.', 'Keeping the knees stationary, lower the dumbbells to over the top of your feet by bending at the waist while keeping your back straight. Keep moving forward as if you were going to pick something from the floor until you feel a stretch on the hamstrings. Exhale as you perform this movement', 'Start bringing your torso up straight again by extending your hips and waist until you are back at the starting position. Inhale as you perform this movement.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Stiff-Legged_Dumbbell_Deadlift/0.jpg', 'Stiff-Legged_Dumbbell_Deadlift/1.jpg']::text[], 'stiff-legged dumbbell deadlift deadlift chan thang ta don peso muerto piernas rigidas con mancuernas'),
  (NULL, 'Stiff Leg Barbell Good Morning', 'Stiff Leg Barbell Good Morning', 'Stiff Leg Barbell Good Morning', 'Buenos días con piernas rígidas', 'back', 'barbell', 'compound', 'free_exercise_db', 'Stiff_Leg_Barbell_Good_Morning', ARRAY['This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.', 'Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.', 'Step away from the rack and position your legs using a shoulder width medium stance. Keep your head up at all times as looking down will get you off balance and also maintain a straight back. This will be your starting position.', 'Keeping your legs stationary, move your torso forward by bending at the hips while inhaling. Lower your torso until it is parallel with the floor.', 'Begin to raise the bar as you exhale by elevating your torso back to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Stiff_Leg_Barbell_Good_Morning/0.jpg', 'Stiff_Leg_Barbell_Good_Morning/1.jpg']::text[], 'stiff leg barbell good morning good morning chan thang ta don buenos dias con piernas rigidas'),
  (NULL, 'Stomach Vacuum', 'Hóp bụng chân không', 'Stomach Vacuum', 'Vacío abdominal', 'abs', 'bodyweight', 'timed', 'free_exercise_db', 'Stomach_Vacuum', ARRAY['To begin, stand straight with your feet shoulder width apart from each other. Place your hands on your hips. This is the starting position.', 'Now slowly inhale as much air as possible and then start to exhale as much as possible while bringing your stomach in as much as possible and hold this position. Try to visualize your navel touching your backbone.', 'One isometric contraction is around 20 seconds. During the 20 second hold, try to breathe normally. Then inhale and bring your stomach back to the starting position.', 'Once you have practiced this exercise, try to perform this exercise for longer than 20 seconds. Tip: You can work your way up to 40-60 seconds.', 'Repeat for the recommended amount of sets.']::text[], ARRAY['Stomach_Vacuum/0.jpg', 'Stomach_Vacuum/1.jpg']::text[], 'stomach vacuum hop bung chan khong vacio abdominal'),
  (NULL, 'Straight-Arm Dumbbell Pullover', 'Straight-Arm Dumbbell Pullover', 'Straight-Arm Dumbbell Pullover', 'Pullover con mancuerna brazos rectos', 'chest', 'dumbbell', 'compound', 'free_exercise_db', 'Straight-Arm_Dumbbell_Pullover', ARRAY['Place a dumbbell standing up on a flat bench.', 'Ensuring that the dumbbell stays securely placed at the top of the bench, lie perpendicular to the bench (torso across it as in forming a cross) with only your shoulders lying on the surface. Hips should be below the bench and legs bent with feet firmly on the floor. The head will be off the bench as well.', 'Grasp the dumbbell with both hands and hold it straight over your chest at arms length. Both palms should be pressing against the underside one of the sides of the dumbbell. This will be your starting position.
Caution: Always ensure that the dumbbell used for this exercise is secure. Using a dumbbell with loose plates can result in the dumbbell falling apart and falling on your face.', 'While keeping your arms straight, lower the weight slowly in an arc behind your head while breathing in until you feel a stretch on the chest.', 'At that point, bring the dumbbell back to the starting position using the arc through which the weight was lowered and exhale as you perform this movement.', 'Hold the weight on the initial position for a second and repeat the motion for the prescribed number of repetitions.']::text[], ARRAY['Straight-Arm_Dumbbell_Pullover/0.jpg', 'Straight-Arm_Dumbbell_Pullover/1.jpg']::text[], 'straight-arm dumbbell pullover keo ta don qua dau tay thang pullover con mancuerna brazos rectos'),
  (NULL, 'Straight-Arm Pulldown', 'Kéo cáp tay thẳng', 'Straight-Arm Pulldown', 'Jalón con brazos rectos', 'back', 'cable', 'isolation', 'free_exercise_db', 'Straight-Arm_Pulldown', ARRAY['You will start by grabbing the wide bar from the top pulley of a pulldown machine and using a wider than shoulder-width pronated (palms down) grip. Step backwards two feet or so.', 'Bend your torso forward at the waist by around 30-degrees with your arms fully extended in front of you and a slight bend at the elbows. If your arms are not fully extended then you need to step a bit more backwards until they are. Once your arms are fully extended and your torso is slightly bent at the waist, tighten the lats and then you are ready to begin.', 'While keeping the arms straight, pull the bar down by contracting the lats until your hands are next to the side of the thighs. Breathe out as you perform this step.', 'While keeping the arms straight, go back to the starting position while breathing in.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Straight-Arm_Pulldown/0.jpg', 'Straight-Arm_Pulldown/1.jpg']::text[], 'straight-arm pulldown keo cap tay thang jalon con brazos rectos'),
  (NULL, 'Straight Bar Bench Mid Rows', 'Chèo thanh thẳng trên ghế', 'Straight Bar Bench Mid Rows', 'Remo con barra recta en banco', 'back', 'barbell', 'compound', 'free_exercise_db', 'Straight_Bar_Bench_Mid_Rows', ARRAY['Place a loaded barbell on the end of a bench. Standing on the bench behind the bar, take a medium, pronated grip. Stand with your hips back and chest up, maintaining a neutral spine. This will be your starting position.', 'Row the bar to your torso by retracting the shoulder blades and flexing the elbows. Use a controlled movement with no jerking.', 'After a brief pause, slowly return the bar to the starting position, ensuring to go all the way down.']::text[], ARRAY['Straight_Bar_Bench_Mid_Rows/0.jpg', 'Straight_Bar_Bench_Mid_Rows/1.jpg']::text[], 'straight bar bench mid rows cheo thanh thang tren ghe remo con barra recta en banco'),
  (NULL, 'Straight Raises on Incline Bench', 'Nâng tạ tay thẳng trên ghế dốc', 'Straight Raises on Incline Bench', 'Elevaciones rectas en banco inclinado', 'shoulders', 'barbell', 'isolation', 'free_exercise_db', 'Straight_Raises_on_Incline_Bench', ARRAY['Place a bar on the ground behind the head of an incline bench.', 'Lay on the bench face down. With a pronated grip, pick the barbell up from the floor, keeping your arms straight. Allow the bar to hang straight down. This will be your starting position.', 'To begin, raise the barbell out in front of your head while keeping your arms extended.', 'Return to the starting position.']::text[], ARRAY['Straight_Raises_on_Incline_Bench/0.jpg', 'Straight_Raises_on_Incline_Bench/1.jpg']::text[], 'straight raises on incline bench nang ta tay thang tren ghe doc elevaciones rectas en banco inclinado'),
  (NULL, 'Stride Jump Crossover', 'Stride Jump Crossover', 'Stride Jump Crossover', 'Salto de zancada cruzado', 'legs', 'other', 'compound', 'free_exercise_db', 'Stride_Jump_Crossover', ARRAY['Stand to the side of a box with your inside foot on top of it, close to the edge.', 'Begin by swinging the arms upward as you push through the top leg, jumping upward as high as possible. Attempt to drive the opposite knee upward.', 'Land in the opposite position that you started, on the opposite side of the box. The foot that was initially on the box will now be on the ground, with the opposite foot now on the box.', 'Repeat the movement, crossing back over to the other side.']::text[], ARRAY['Stride_Jump_Crossover/0.jpg', 'Stride_Jump_Crossover/1.jpg']::text[], 'stride jump crossover bat sai bat cheo salto de zancada cruzado'),
  (NULL, 'Sumo Deadlift', 'Sumo Deadlift', 'Sumo Deadlift', 'Peso muerto sumo', 'legs', 'barbell', 'compound', 'free_exercise_db', 'Sumo_Deadlift', ARRAY['Begin with a bar loaded on the ground. Approach the bar so that the bar intersects the middle of the feet. The feet should be set very wide, near the collars. Bend at the hips to grip the bar. The arms should be directly below the shoulders, inside the legs, and you can use a pronated grip, a mixed grip, or hook grip. Relax the shoulders, which in effect lengthens your arms.', 'Take a breath, and then lower your hips, looking forward with your head with your chest up. Drive through the floor, spreading your feet apart, with your weight on the back half of your feet. Extend through the hips and knees.', 'As the bar passes through the knees, lean back and drive the hips into the bar, pulling your shoulder blades together.', 'Return the weight to the ground by bending at the hips and controlling the weight on the way down.']::text[], ARRAY['Sumo_Deadlift/0.jpg', 'Sumo_Deadlift/1.jpg']::text[], 'sumo deadlift deadlift sumo peso muerto sumo'),
  (NULL, 'Sumo Deadlift with Bands', 'Sumo Deadlift with Bands', 'Sumo Deadlift with Bands', 'Peso muerto sumo con bandas', 'legs', 'barbell', 'compound', 'free_exercise_db', 'Sumo_Deadlift_with_Bands', ARRAY['To deadlift with short bands, simply loop them over the bar before you start, and step into them to set up. Ensure that they under the back half of your foot, directly where you are driving into the floor.', 'Begin with a bar loaded on the ground. Approach the bar so that the bar intersects the middle of the feet. The feet should be set very wide, near the collars. Bend at the hips to grip the bar. The arms should be directly below the shoulders, inside the legs, and you can use a pronated grip, a mixed grip, or hook grip.', 'Take a breath, and then lower your hips, looking forward with your head with your chest up. Drive through the floor, spreading your feet apart, with your weight on the back half of your feet. Extend through the hips and knees.', 'As the bar passes through the knees, lean back and drive the hips into the bar, pulling your shoulder blades together.', 'Return the weight to the ground by bending at the hips and controlling the weight on the way down.']::text[], ARRAY['Sumo_Deadlift_with_Bands/0.jpg', 'Sumo_Deadlift_with_Bands/1.jpg']::text[], 'sumo deadlift with bands deadlift sumo day khang luc peso muerto sumo con bandas'),
  (NULL, 'Sumo Deadlift with Chains', 'Sumo Deadlift with Chains', 'Sumo Deadlift with Chains', 'Peso muerto sumo con cadenas', 'legs', 'barbell', 'compound', 'free_exercise_db', 'Sumo_Deadlift_with_Chains', ARRAY['You can attach the chains to the sleeves of the bar, or just drape the middle over the bar so there is a greater weight increase as you lift. Attempt to keep the ends of the chains away from the plates so you don''t hit them when you lower the weight.', 'Begin with a bar loaded on the ground. Approach the bar so that the bar intersects the middle of the feet. The feet should be set very wide, near the collars. Bend at the hips to grip the bar. The arms should be directly below the shoulders, inside the legs, and you can use a pronated grip, a mixed grip, or hook grip. Relax the shoulders, which in effect lengthens your arms.', 'Take a breath, and then lower your hips, looking forward with your head with your chest up. Drive through the floor, spreading your feet apart, with your weight on the back half of your feet. Extend through the hips and knees.', 'As the bar passes through the knees, lean back and drive the hips into the bar, pulling your shoulder blades together.', 'Return the weight to the ground by bending at the hips and controlling the weight on the way down.']::text[], ARRAY['Sumo_Deadlift_with_Chains/0.jpg', 'Sumo_Deadlift_with_Chains/1.jpg']::text[], 'sumo deadlift with chains deadlift sumo co xich peso muerto sumo con cadenas'),
  (NULL, 'Superman', 'Superman', 'Superman', 'Superman', 'back', 'bodyweight', 'timed', 'free_exercise_db', 'Superman', ARRAY['To begin, lie straight and face down on the floor or exercise mat. Your arms should be fully extended in front of you. This is the starting position.', 'Simultaneously raise your arms, legs, and chest off of the floor and hold this contraction for 2 seconds. Tip: Squeeze your lower back to get the best results from this exercise. Remember to exhale during this movement. Note: When holding the contracted position, you should look like superman when he is flying.', 'Slowly begin to lower your arms, legs and chest back down to the starting position while inhaling.', 'Repeat for the recommended amount of repetitions prescribed in your program.']::text[], ARRAY['Superman/0.jpg', 'Superman/1.jpg']::text[], 'superman sieu nhan superman'),
  (NULL, 'Supine Chest Throw', 'Ném bóng tạ từ ngực nằm ngửa', 'Supine Chest Throw', 'Lanzamiento de pecho tumbado', 'triceps', 'medicine ball', 'compound', 'free_exercise_db', 'Supine_Chest_Throw', ARRAY['This drill is great for chest passes when you lack a partner or a wall of sufficient strength. Lay on the ground on your back with your knees bent.', 'Begin with the ball on your chest, held with both hands on the bottom.', 'Explode up, extending through the elbow to throw the ball directly above you as high as possible.', 'Catch the ball with both hands as it comes down.']::text[], ARRAY['Supine_Chest_Throw/0.jpg', 'Supine_Chest_Throw/1.jpg']::text[], 'supine chest throw nem bong ta tu nguc nam ngua lanzamiento de pecho tumbado'),
  (NULL, 'Supine One-Arm Overhead Throw', 'Ném bóng tạ qua đầu một tay nằm ngửa', 'Supine One-Arm Overhead Throw', 'Lanzamiento sobre la cabeza a una mano tumbado', 'abs', 'medicine ball', 'compound', 'free_exercise_db', 'Supine_One-Arm_Overhead_Throw', ARRAY['Lay on the ground on your back with your knees bent. Hold the ball with one hand, extending the arm fully behind your head. This will be your starting position.', 'Initiate the movement at the shoulder, throwing the ball directly forward of you as you sit up, attempting to go for maximum distance.', 'The ball can be thrown to a partner or bounced off of a wall.']::text[], ARRAY['Supine_One-Arm_Overhead_Throw/0.jpg', 'Supine_One-Arm_Overhead_Throw/1.jpg']::text[], 'supine one-arm overhead throw nem bong ta qua dau mot tay nam ngua lanzamiento sobre la cabeza a una mano tumbado'),
  (NULL, 'Supine Two-Arm Overhead Throw', 'Ném bóng tạ qua đầu hai tay nằm ngửa', 'Supine Two-Arm Overhead Throw', 'Lanzamiento sobre la cabeza a dos manos tumbado', 'abs', 'medicine ball', 'compound', 'free_exercise_db', 'Supine_Two-Arm_Overhead_Throw', ARRAY['Lay on the ground on your back with your knees bent.', 'Hold the ball with both hands, extending the arms fully behind your head. This will be your starting position.', 'Initiate the movement at the shoulder, throwing the ball directly forward of you as you sit up, attempting to go for maximum distance.', 'The ball can be thrown to a partner or bounced off of a wall.']::text[], ARRAY['Supine_Two-Arm_Overhead_Throw/0.jpg', 'Supine_Two-Arm_Overhead_Throw/1.jpg']::text[], 'supine two-arm overhead throw nem bong ta qua dau hai tay nam ngua lanzamiento sobre la cabeza a dos manos tumbado'),
  (NULL, 'Suspended Fallout', 'Đổ người với dây treo', 'Suspended Fallout', 'Caída suspendida', 'abs', 'other', 'isolation', 'free_exercise_db', 'Suspended_Fallout', ARRAY['Adjust the straps so the handles are at an appropriate height, below waist level.', 'Begin standing and grasping the handles. Lean into the straps, moving to an incline push-up position. This will be your starting position.', 'Keeping your arms straight, lean further into the suspension straps, bringing your body closer to the ground, allowing your shoulders to extend, raising your arms up and over your head.', 'Maintain a neutral spine and keep the rest of your body straight, your shoulders being the only joints allowed to move.', 'Pause during the peak contraction, and then return to the starting position.']::text[], ARRAY['Suspended_Fallout/0.jpg', 'Suspended_Fallout/1.jpg']::text[], 'suspended fallout do nguoi voi day treo caida suspendida'),
  (NULL, 'Suspended Push-Up', 'Hít đất với dây treo', 'Suspended Push-Up', 'Flexiones suspendidas', 'chest', 'other', 'compound', 'free_exercise_db', 'Suspended_Push-Up', ARRAY['Anchor your suspension straps securely to the top of a rack or other object.', 'Leaning into the straps, take a handle in each hand and move into a push-up plank position. You should be as close to parallel to the ground as you can manage with your arms fully extended, maintaining good posture.', 'Maintaining a straight, rigid torso, descend slowly by allowing the elbows to flex.', 'Continue until your elbows break 90 degrees, pausing before you extend to return to the starting position.']::text[], ARRAY['Suspended_Push-Up/0.jpg', 'Suspended_Push-Up/1.jpg']::text[], 'suspended push-up hit dat voi day treo flexiones suspendidas'),
  (NULL, 'Suspended Reverse Crunch', 'Suspended Reverse Crunch', 'Suspended Reverse Crunch', 'Crunch inverso suspendido', 'abs', 'other', 'isolation', 'free_exercise_db', 'Suspended_Reverse_Crunch', ARRAY['Secure a set of suspension straps with the handles hanging about a foot off of the ground. Move yourself into a pushup plank position facing away from the rack.', 'Place your feet into the handles. You should maintain a straight posture, not allowing the hips to sag. This will be your starting position.', 'Begin the movement by flexing the knees and hips, drawing the knees to your torso. As you do so, anteriorly tilt your pelvis, allowing your spine to flex.', 'At the top of the controlled motion, return to the starting position.']::text[], ARRAY['Suspended_Reverse_Crunch/0.jpg', 'Suspended_Reverse_Crunch/1.jpg']::text[], 'suspended reverse crunch gap bung nguoc voi day treo crunch inverso suspendido'),
  (NULL, 'Suspended Row', 'Chèo với dây treo', 'Suspended Row', 'Remo suspendido', 'back', 'other', 'compound', 'free_exercise_db', 'Suspended_Row', ARRAY['Suspend your straps at around chest height. Take a handle in each hand and lean back. Keep your body erect and your head and chest up. Your arms should be fully extended. This will be your starting position.', 'Begin by flexing the elbow to initiate the movement. Protract your shoulder blades as you do so.', 'At the completion of the motion pause, and then return to the starting position.']::text[], ARRAY['Suspended_Row/0.jpg', 'Suspended_Row/1.jpg']::text[], 'suspended row cheo voi day treo remo suspendido'),
  (NULL, 'Suspended Split Squat', 'Suspended Split Squat', 'Suspended Split Squat', 'Sentadilla dividida suspendida', 'legs', 'other', 'compound', 'free_exercise_db', 'Suspended_Split_Squat', ARRAY['Suspend your straps so the handles are 18-30 inches from the floor.', 'Facing away from the setup, place your rear foot into the handle behind you. Keep your head looking forward and your chest up, with your knee slightly bent. This will be your starting position.', 'Descend by flexing the knee and hips, lowering yourself to the ground. Keep your weight on the heel of your foot and maintain your posture throughout the exercise.', 'At the bottom of the movement, reverse the motion, extending through the hip and knee to return to the starting position.']::text[], ARRAY['Suspended_Split_Squat/0.jpg', 'Suspended_Split_Squat/1.jpg']::text[], 'suspended split squat squat tach chan voi day treo sentadilla dividida suspendida'),
  (NULL, 'Svend Press', 'Ép đĩa tạ trước ngực (Svend press)', 'Svend Press', 'Press Svend', 'chest', 'other', 'compound', 'free_exercise_db', 'Svend_Press', ARRAY['Begin in a standing position.', 'Press two lightweight plates together with your hands. Hold the plates together close to your chest to create an isometric contraction in your chest muscles. Your fingers should be pointed forward. This is your starting position.', 'Squeeze the plates between your palms and extend your arms directly out in front of you in a controlled motion.', 'Pause at the top of the motion, and then slowly return to the starting position.']::text[], ARRAY['Svend_Press/0.jpg', 'Svend_Press/1.jpg']::text[], 'svend press ep dia ta truoc nguc (svend press) press svend'),
  (NULL, 'T-Bar Row with Handle', 'T-Bar Row with Handle', 'T-Bar Row with Handle', 'Remo en T con asa', 'back', 'barbell', 'compound', 'free_exercise_db', 'T-Bar_Row_with_Handle', ARRAY['Position a bar into a landmine or in a corner to keep it from moving. Load an appropriate weight onto your end.', 'Stand over the bar, and position a Double D row handle around the bar next to the collar. Using your hips and legs, rise to a standing position.', 'Assume a wide stance with your hips back and your chest up. Your arms should be extended. This will be your starting position.', 'Pull the weight to your upper abdomen by retracting the shoulder blades and flexing the elbows. Do not jerk the weight or cheat during the movement.', 'After a brief pause, return to the starting position.']::text[], ARRAY['T-Bar_Row_with_Handle/0.jpg', 'T-Bar_Row_with_Handle/1.jpg']::text[], 't-bar row with handle cheo t-bar co tay cam remo en t con asa'),
  (NULL, 'Tate Press', 'Đẩy Tate', 'Tate Press', 'Press Tate', 'triceps', 'dumbbell', 'isolation', 'free_exercise_db', 'Tate_Press', ARRAY['Lie down on a flat bench with a dumbbell in each hand on top of your thighs. The palms of your hand will be facing each other.', 'By using your thighs to help you get the dumbbells up, clean the dumbbells one arm at a time so that you can hold them in front of you at shoulder width. Note: when holding the dumbbells in front of you, make sure your arms are wider than shoulder width apart from each other using a pronated (palms forward) grip. Allow your elbows to point out. This is your starting position.', 'Keeping the upper arms stationary, slowly move the dumbbells in and down in a semi circular motion until they touch the upper chest while inhaling. Keep full control of the dumbbells at all times and do not move the upper arms nor rest the dumbbells on the chest.', 'As you breathe out, move the dumbbells up using your triceps and the same semi-circular motion but in reverse. Attempt to keep the dumbbells together as they move up. Lock your arms in the contracted position, hold for a second and then start coming down again slowly again. Tip: It should take at least twice as long to go down than to come up.', 'Repeat the movement for the prescribed amount of repetitions of your training program.']::text[], ARRAY['Tate_Press/0.jpg', 'Tate_Press/1.jpg']::text[], 'tate press day tate press tate'),
  (NULL, 'The Straddle', 'Giãn háng dạng chân', 'The Straddle', 'Estiramiento en straddle', 'legs', 'other', 'timed', 'free_exercise_db', 'The_Straddle', ARRAY['Begin in a seated, upright position. Start by extending your legs in front of you in a V.', 'With your hands on the floor, lean forward as far as possible. Hold for 10 to 20 seconds.']::text[], ARRAY['The_Straddle/0.jpg', 'The_Straddle/1.jpg']::text[], 'the straddle gian hang dang chan estiramiento en straddle'),
  (NULL, 'Thigh Abductor', 'Dạng đùi (máy)', 'Thigh Abductor', 'Abducción de cadera en máquina', 'legs', 'machine', 'isolation', 'free_exercise_db', 'Thigh_Abductor', ARRAY['To begin, sit down on the abductor machine and select a weight you are comfortable with. When your legs are positioned properly, grip the handles on each side. Your entire upper body (from the waist up) should be stationary. This is the starting position.', 'Slowly press against the machine with your legs to move them away from each other while exhaling.', 'Feel the contraction for a second and begin to move your legs back to the starting position while breathing in. Note: Remember to keep your upper body stationary to prevent any injuries from occurring.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Thigh_Abductor/0.jpg', 'Thigh_Abductor/1.jpg']::text[], 'thigh abductor dang dui (may) abduccion de cadera en maquina'),
  (NULL, 'Thigh Adductor', 'Khép đùi (máy)', 'Thigh Adductor', 'Aducción de cadera en máquina', 'legs', 'machine', 'isolation', 'free_exercise_db', 'Thigh_Adductor', ARRAY['To begin, sit down on the adductor machine and select a weight you are comfortable with. When your legs are positioned properly on the leg pads of the machine, grip the handles on each side. Your entire upper body (from the waist up) should be stationary. This is the starting position.', 'Slowly press against the machine with your legs to move them towards each other while exhaling.', 'Feel the contraction for a second and begin to move your legs back to the starting position while breathing in. Note: Remember to keep your upper body stationary and avoid fast jerking motions in order to prevent any injuries from occurring.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Thigh_Adductor/0.jpg', 'Thigh_Adductor/1.jpg']::text[], 'thigh adductor khep dui (may) aduccion de cadera en maquina'),
  (NULL, 'Tire Flip', 'Lật lốp xe', 'Tire Flip', 'Volteo de neumático', 'legs', 'other', 'compound', 'free_exercise_db', 'Tire_Flip', ARRAY['Begin by gripping the bottom of the tire on the tread, and position your feet back a bit. Your chest should be driving into the tire.', 'To lift the tire, extend through the hips, knees, and ankles, driving into the tire and up.', 'As the tire reaches a 45 degree angle, step forward and drive a knee into the tire. As you do so adjust your grip to the upper portion of the tire and push it forward as hard as possible to complete the turn. Repeat as necessary.']::text[], ARRAY['Tire_Flip/0.jpg', 'Tire_Flip/1.jpg']::text[], 'tire flip lat lop xe volteo de neumatico'),
  (NULL, 'Toe Touchers', 'Chạm mũi chân nằm', 'Toe Touchers', 'Toques de punta', 'abs', 'bodyweight', 'timed', 'free_exercise_db', 'Toe_Touchers', ARRAY['To begin, lie down on the floor or an exercise mat with your back pressed against the floor. Your arms should be lying across your sides with the palms facing down.', 'Your legs should be touching each other. Slowly elevate your legs up in the air until they are almost perpendicular to the floor with a slight bend at the knees. Your feet should be parallel to the floor.', 'Move your arms so that they are fully extended at a 45 degree angle from the floor. This is the starting position.', 'While keeping your lower back pressed against the floor, slowly lift your torso and use your hands to try and touch your toes. Remember to exhale while perform this part of the exercise.', 'Slowly begin to lower your torso and arms back down to the starting position while inhaling. Remember to keep your arms straight out pointing towards your toes.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Toe_Touchers/0.jpg', 'Toe_Touchers/1.jpg']::text[], 'toe touchers cham mui chan nam toques de punta'),
  (NULL, 'Torso Rotation', 'Xoay thân trên bóng tập', 'Torso Rotation', 'Rotación de torso en fitball', 'abs', 'exercise ball', 'timed', 'free_exercise_db', 'Torso_Rotation', ARRAY['Stand upright holding an exercise ball with both hands. Extend your arms so the ball is straight out in front of you. This will be your starting position.', 'Rotate your torso to one side, keeping your eyes on the ball as you move. Now, rotate back to the opposite direction. Repeat for 10-20 repetitions.']::text[], ARRAY['Torso_Rotation/0.jpg', 'Torso_Rotation/1.jpg']::text[], 'torso rotation xoay than tren bong tap rotacion de torso en fitball'),
  (NULL, 'Trail Running/Walking', 'Chạy/đi bộ đường mòn', 'Trail Running/Walking', 'Correr/caminar por sendero', 'cardio', 'other', 'timed', 'free_exercise_db', 'Trail_Running_Walking', ARRAY['Running or hiking on trails will get the blood pumping and heart beating almost immediately. Make sure you have good shoes. While you use the muscles in your calves and buttocks to pull yourself up a hill, the knees, joints and ankles absorb the bulk of the pounding coming back down. Take smaller steps as you walk downhill, keep your knees bent to reduce the impact and slow down to avoid falling.', 'A 150 lb person can burn over 200 calories for 30 minutes walking uphill, compared to 175 on a flat surface. If running the trail, a 150 lb person can burn well over 500 calories in 30 minutes.']::text[], ARRAY['Trail_Running_Walking/0.jpg', 'Trail_Running_Walking/1.jpg']::text[], 'trail running/walking chay/di bo duong mon correr/caminar por sendero'),
  (NULL, 'Trap Bar Deadlift', 'Trap Bar Deadlift', 'Trap Bar Deadlift', 'Peso muerto con barra hexagonal', 'legs', 'other', 'compound', 'free_exercise_db', 'Trap_Bar_Deadlift', ARRAY['For this exercise load a trap bar, also known as a hex bar, to an appropriate weight resting on the ground. Stand in the center of the apparatus and grasp both handles.', 'Lower your hips, look forward with your head and keep your chest up.', 'Begin the movement by driving through the heels and extend your hips and knees. Avoid rounding your back at all times.', 'At the completion of the movement, lower the weight back to the ground under control.']::text[], ARRAY['Trap_Bar_Deadlift/0.jpg', 'Trap_Bar_Deadlift/1.jpg']::text[], 'trap bar deadlift deadlift thanh luc giac peso muerto con barra hexagonal'),
  (NULL, 'Tricep Dumbbell Kickback', 'Đá tay sau tạ đơn', 'Tricep Dumbbell Kickback', 'Patada de tríceps con mancuerna', 'triceps', 'dumbbell', 'isolation', 'free_exercise_db', 'Tricep_Dumbbell_Kickback', ARRAY['Start with a dumbbell in each hand and your palms facing your torso. Keep your back straight with a slight bend in the knees and bend forward at the waist. Your torso should be almost parallel to the floor. Make sure to keep your head up. Your upper arms should be close to your torso and parallel to the floor. Your forearms should be pointed towards the floor as you hold the weights. There should be a 90-degree angle formed between your forearm and upper arm. This is your starting position.', 'Now, while keeping your upper arms stationary, exhale and use your triceps to lift the weights until the arm is fully extended. Focus on moving the forearm.', 'After a brief pause at the top contraction, inhale and slowly lower the dumbbells back down to the starting position.', 'Repeat the movement for the prescribed amount of repetitions.']::text[], ARRAY['Tricep_Dumbbell_Kickback/0.jpg', 'Tricep_Dumbbell_Kickback/1.jpg']::text[], 'tricep dumbbell kickback da tay sau ta don patada de triceps con mancuerna'),
  (NULL, 'Tricep Side Stretch', 'Giãn tay sau nghiêng', 'Tricep Side Stretch', 'Estiramiento lateral de tríceps', 'triceps', 'other', 'timed', 'free_exercise_db', 'Tricep_Side_Stretch', ARRAY['Bring right arm across your body and over your left shoulder, holding your elbow with your left hand, until you feel a stretch in your tricep. Then repeat for your other arm.']::text[], ARRAY['Tricep_Side_Stretch/0.jpg', 'Tricep_Side_Stretch/1.jpg']::text[], 'tricep side stretch gian tay sau nghieng estiramiento lateral de triceps'),
  (NULL, 'Triceps Overhead Extension with Rope', 'Duỗi tay sau qua đầu với dây thừng', 'Triceps Overhead Extension with Rope', 'Extensión de tríceps sobre la cabeza con cuerda', 'triceps', 'cable', 'isolation', 'free_exercise_db', 'Triceps_Overhead_Extension_with_Rope', ARRAY['Attach a rope to a low pulley. After selecting an appropriate weight, grasp the rope with both hands and face away from the cable.', 'Position your hands behind your head with your elbows point straight up. Your elbows should start out flexed, and you can stagger your stance and lean gently away from the machine to create greater stability. This will be your starting position.', 'To perform the movement, extend through the elbow while keeping the upper arm in position, raising your hands above your head.', 'Squeeze your triceps at the top of the movement, and slowly lower the weight back to the start position.']::text[], ARRAY['Triceps_Overhead_Extension_with_Rope/0.jpg', 'Triceps_Overhead_Extension_with_Rope/1.jpg']::text[], 'triceps overhead extension with rope duoi tay sau qua dau voi day thung extension de triceps sobre la cabeza con cuerda'),
  (NULL, 'Triceps Pushdown', 'Đẩy cáp tay sau', 'Triceps Pushdown', 'Jalón de tríceps', 'triceps', 'cable', 'isolation', 'free_exercise_db', 'Triceps_Pushdown', ARRAY['Attach a straight or angled bar to a high pulley and grab with an overhand grip (palms facing down) at shoulder width.', 'Standing upright with the torso straight and a very small inclination forward, bring the upper arms close to your body and perpendicular to the floor. The forearms should be pointing up towards the pulley as they hold the bar. This is your starting position.', 'Using the triceps, bring the bar down until it touches the front of your thighs and the arms are fully extended perpendicular to the floor. The upper arms should always remain stationary next to your torso and only the forearms should move. Exhale as you perform this movement.', 'After a second hold at the contracted position, bring the bar slowly up to the starting point. Breathe in as you perform this step.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Triceps_Pushdown/0.jpg', 'Triceps_Pushdown/1.jpg']::text[], 'triceps pushdown day cap tay sau jalon de triceps'),
  (NULL, 'Triceps Pushdown - Rope Attachment', 'Đẩy cáp tay sau dây thừng', 'Triceps Pushdown - Rope Attachment', 'Jalón de tríceps con cuerda', 'triceps', 'cable', 'isolation', 'free_exercise_db', 'Triceps_Pushdown_-_Rope_Attachment', ARRAY['Attach a rope attachment to a high pulley and grab with a neutral grip (palms facing each other).', 'Standing upright with the torso straight and a very small inclination forward, bring the upper arms close to your body and perpendicular to the floor. The forearms should be pointing up towards the pulley as they hold the rope with the palms facing each other. This is your starting position.', 'Using the triceps, bring the rope down as you bring each side of the rope to the side of your thighs. At the end of the movement the arms are fully extended and perpendicular to the floor. The upper arms should always remain stationary next to your torso and only the forearms should move. Exhale as you perform this movement.', 'After holding for a second, at the contracted position, bring the rope slowly up to the starting point. Breathe in as you perform this step.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Triceps_Pushdown_-_Rope_Attachment/0.jpg', 'Triceps_Pushdown_-_Rope_Attachment/1.jpg']::text[], 'triceps pushdown - rope attachment day cap tay sau day thung jalon de triceps con cuerda'),
  (NULL, 'Triceps Pushdown - V-Bar Attachment', 'Đẩy cáp tay sau thanh chữ V', 'Triceps Pushdown - V-Bar Attachment', 'Jalón de tríceps con barra en V', 'triceps', 'cable', 'isolation', 'free_exercise_db', 'Triceps_Pushdown_-_V-Bar_Attachment', ARRAY['Attach a V-Bar to a high pulley and grab with an overhand grip (palms facing down) at shoulder width.', 'Standing upright with the torso straight and a very small inclination forward, bring the upper arms close to your body and perpendicular to the floor. The forearms should be pointing up towards the pulley as they hold the bar. The thumbs should be higher than the small finger. This is your starting position.', 'Using the triceps, bring the bar down until it touches the front of your thighs and the arms are fully extended perpendicular to the floor. The upper arms should always remain stationary next to your torso and only the forearms should move. Exhale as you perform this movement.', 'After a second hold at the contracted position, bring the V-Bar slowly up to the starting point. Breathe in as you perform this step.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Triceps_Pushdown_-_V-Bar_Attachment/0.jpg', 'Triceps_Pushdown_-_V-Bar_Attachment/1.jpg']::text[], 'triceps pushdown - v-bar attachment day cap tay sau thanh chu v jalon de triceps con barra en v'),
  (NULL, 'Triceps Stretch', 'Giãn tay sau', 'Triceps Stretch', 'Estiramiento de tríceps', 'triceps', 'other', 'timed', 'free_exercise_db', 'Triceps_Stretch', ARRAY['Reach your hand behind your head, grasp your elbow and gently pull. Hold for 10 to 20 seconds, then switch sides.']::text[], ARRAY['Triceps_Stretch/0.jpg', 'Triceps_Stretch/1.jpg']::text[], 'triceps stretch gian tay sau estiramiento de triceps'),
  (NULL, 'Tuck Crunch', 'Tuck Crunch', 'Tuck Crunch', 'Crunch con rodillas recogidas', 'abs', 'bodyweight', 'bodyweight', 'free_exercise_db', 'Tuck_Crunch', ARRAY['To begin, lie down on the floor or an exercise mat with your back pressed against the floor. Your arms should be lying across your sides with the palms facing down.', 'Your legs should be crossed by wrapping one ankle around the other. Slowly elevate your legs up in the air until your thighs are perpendicular to the floor with a slight bend at the knees. Note: Your knees and toes should be parallel to the floor as opposed to the thighs.', 'Move your arms from the floor and cross them so they are resting on your chest. This is the starting position.', 'While keeping your lower back pressed against the floor, slowly lift your torso. Remember to exhale while perform this part of the exercise.', 'Slowly begin to lower your torso back down to the starting position while inhaling.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Tuck_Crunch/0.jpg', 'Tuck_Crunch/1.jpg']::text[], 'tuck crunch gap bung co goi crunch con rodillas recogidas'),
  (NULL, 'Two-Arm Dumbbell Preacher Curl', 'Two-Arm Dumbbell Preacher Curl', 'Two-Arm Dumbbell Preacher Curl', 'Curl predicador a dos manos con mancuernas', 'biceps', 'dumbbell', 'isolation', 'free_exercise_db', 'Two-Arm_Dumbbell_Preacher_Curl', ARRAY['Grab a dumbbell with each arm and place the upper arms on top of the preacher bench or the incline bench. The dumbbell should be held at shoulder length. This will be your starting position.', 'As you breathe in, slowly lower the dumbbells until your upper arm is extended and the biceps is fully stretched.', 'As you exhale, use the biceps to curl the weights up until your biceps is fully contracted and the dumbbells are at shoulder height.', 'Squeeze the biceps hard for a second at the contracted position and repeat for the recommended amount of repetitions.']::text[], ARRAY['Two-Arm_Dumbbell_Preacher_Curl/0.jpg', 'Two-Arm_Dumbbell_Preacher_Curl/1.jpg']::text[], 'two-arm dumbbell preacher curl cuon ta don ghe doc hai tay curl predicador a dos manos con mancuernas'),
  (NULL, 'Two-Arm Kettlebell Clean', 'Two-Arm Kettlebell Clean', 'Two-Arm Kettlebell Clean', 'Cargada con dos pesas rusas', 'shoulders', 'kettlebell', 'compound', 'free_exercise_db', 'Two-Arm_Kettlebell_Clean', ARRAY['Place two kettlebells between your feet. To get in the starting position, push your butt back and look straight ahead.', 'Clean the kettlebells to your shoulders by extending through the legs and hips as you raise the kettlebells towards your shoulders. Rotate your wrists as you do so.', 'Lower the kettlebells back to the starting position and repeat.']::text[], ARRAY['Two-Arm_Kettlebell_Clean/0.jpg', 'Two-Arm_Kettlebell_Clean/1.jpg']::text[], 'two-arm kettlebell clean clean hai kettlebell cargada con dos pesas rusas'),
  (NULL, 'Two-Arm Kettlebell Jerk', 'Two-Arm Kettlebell Jerk', 'Two-Arm Kettlebell Jerk', 'Envión con dos pesas rusas', 'shoulders', 'kettlebell', 'compound', 'free_exercise_db', 'Two-Arm_Kettlebell_Jerk', ARRAY['Clean two kettlebells to your shoulders. Clean the kettlebells to your shoulders by extending through the legs and hips as you swing the kettlebells towards your shoulders. Rotate your wrists as you do so, so that the palms face forward. Squat down a few inches and reverse the motion rapidly driving both kettlebells overhead. Immediately after the initial push, squat down again and get under the kettlebells. Once the kettlebells are locked out, stand upright to complete the exercise.']::text[], ARRAY['Two-Arm_Kettlebell_Jerk/0.jpg', 'Two-Arm_Kettlebell_Jerk/1.jpg']::text[], 'two-arm kettlebell jerk jerk hai tay kettlebell envion con dos pesas rusas'),
  (NULL, 'Two-Arm Kettlebell Military Press', 'Đẩy vai hai kettlebell', 'Two-Arm Kettlebell Military Press', 'Press militar con dos pesas rusas', 'shoulders', 'kettlebell', 'compound', 'free_exercise_db', 'Two-Arm_Kettlebell_Military_Press', ARRAY['Clean two kettlebells to your shoulders. Clean the kettlebells to your shoulders by extending through the legs and hips as you swing the kettlebells towards your shoulders. Rotate your wrists as you do so, so that the palms face forward.', 'Press the kettlebells up and out. As the kettlebells pass your head, lean into the weights so that the kettlebells are racked behind your head. Make sure to contract your lats, butt, and stomach for added stability.']::text[], ARRAY['Two-Arm_Kettlebell_Military_Press/0.jpg', 'Two-Arm_Kettlebell_Military_Press/1.jpg']::text[], 'two-arm kettlebell military press day vai hai kettlebell press militar con dos pesas rusas'),
  (NULL, 'Two-Arm Kettlebell Row', 'Chèo hai kettlebell', 'Two-Arm Kettlebell Row', 'Remo con dos pesas rusas', 'back', 'kettlebell', 'compound', 'free_exercise_db', 'Two-Arm_Kettlebell_Row', ARRAY['Place two kettlebells in front of your feet. Bend your knees slightly and then push your butt out as much as possible as you bend over to get in the starting position.', 'Grab both kettlebells and pull them to your stomach, retracting your shoulder blades and flexing the elbows. Keep your back straight. Lower and repeat.']::text[], ARRAY['Two-Arm_Kettlebell_Row/0.jpg', 'Two-Arm_Kettlebell_Row/1.jpg']::text[], 'two-arm kettlebell row cheo hai kettlebell remo con dos pesas rusas'),
  (NULL, 'Underhand Cable Pulldowns', 'Kéo cáp xuống nắm ngửa', 'Underhand Cable Pulldowns', 'Jalones en polea agarre supino', 'back', 'cable', 'compound', 'free_exercise_db', 'Underhand_Cable_Pulldowns', ARRAY['Sit down on a pull-down machine with a wide bar attached to the top pulley. Adjust the knee pad of the machine to fit your height. These pads will prevent your body from being raised by the resistance attached to the bar.', 'Grab the pull-down bar with the palms facing your torso (a supinated grip). Make sure that the hands are placed closer than the shoulder width.', 'As you have both arms extended in front of you holding the bar at the chosen grip width, bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.', 'As you breathe out, pull the bar down until it touches your upper chest by drawing the shoulders and the upper arms down and back. Tip: Concentrate on squeezing the back muscles once you reach the fully contracted position and keep the elbows close to your body. The upper torso should remain stationary as your bring the bar to you and only the arms should move. The forearms should do no other work other than hold the bar.', 'After a second on the contracted position, while breathing in, slowly bring the bar back to the starting position when your arms are fully extended and the lats are fully stretched.', 'Repeat this motion for the prescribed amount of repetitions.']::text[], ARRAY['Underhand_Cable_Pulldowns/0.jpg', 'Underhand_Cable_Pulldowns/1.jpg']::text[], 'underhand cable pulldowns keo cap xuong nam ngua jalones en polea agarre supino'),
  (NULL, 'Upper Back-Leg Grab', 'Giãn lưng trên ôm chân', 'Upper Back-Leg Grab', 'Estiramiento de espalda alta agarrando piernas', 'legs', 'other', 'timed', 'free_exercise_db', 'Upper_Back-Leg_Grab', ARRAY['While seated, bend forward to hug your thighs from underneath with both arms.', 'Keep your knees together and your legs extended out as you bring your chest down to your knees. You can also stretch your middle back by pulling your back away from your knees as your hugging them.']::text[], ARRAY['Upper_Back-Leg_Grab/0.jpg', 'Upper_Back-Leg_Grab/1.jpg']::text[], 'upper back-leg grab gian lung tren om chan estiramiento de espalda alta agarrando piernas'),
  (NULL, 'Upper Back Stretch', 'Giãn lưng trên', 'Upper Back Stretch', 'Estiramiento de espalda alta', 'back', 'other', 'timed', 'free_exercise_db', 'Upper_Back_Stretch', ARRAY['Clasp fingers together with your thumbs pointing down, round your shoulders as you reach your hands forward.']::text[], ARRAY['Upper_Back_Stretch/0.jpg', 'Upper_Back_Stretch/1.jpg']::text[], 'upper back stretch gian lung tren estiramiento de espalda alta'),
  (NULL, 'Upright Barbell Row', 'Kéo thẳng đứng tạ đòn', 'Upright Barbell Row', 'Remo al mentón con barra', 'shoulders', 'barbell', 'compound', 'free_exercise_db', 'Upright_Barbell_Row', ARRAY['Grasp a barbell with an overhand grip that is slightly less than shoulder width. The bar should be resting on the top of your thighs with your arms extended and a slight bend in your elbows. Your back should also be straight. This will be your starting position.', 'Now exhale and use the sides of your shoulders to lift the bar, raising your elbows up and to the side. Keep the bar close to your body as you raise it. Continue to lift the bar until it nearly touches your chin. Tip: Your elbows should drive the motion, and should always be higher than your forearms. Remember to keep your torso stationary and pause for a second at the top of the movement.', 'Lower the bar back down slowly to the starting position. Inhale as you perform this portion of the movement.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Upright_Barbell_Row/0.jpg', 'Upright_Barbell_Row/1.jpg']::text[], 'upright barbell row keo thang dung ta don remo al menton con barra'),
  (NULL, 'Upright Cable Row', 'Kéo thẳng đứng cáp', 'Upright Cable Row', 'Remo al mentón en polea', 'shoulders', 'cable', 'compound', 'free_exercise_db', 'Upright_Cable_Row', ARRAY['Grasp a straight bar cable attachment that is attached to a low pulley with a pronated (palms facing your thighs) grip that is slightly less than shoulder width. The bar should be resting on top of your thighs. Your arms should be extended with a slight bend at the elbows and your back should be straight. This will be your starting position.', 'Use your side shoulders to lift the cable bar as you exhale. The bar should be close to the body as you move it up. Continue to lift it until it nearly touches your chin. Tip: Your elbows should drive the motion. As you lift the bar, your elbows should always be higher than your forearms. Also, keep your torso stationary and pause for a second at the top of the movement.', 'Lower the bar back down slowly to the starting position. Inhale as you perform this portion of the movement.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Upright_Cable_Row/0.jpg', 'Upright_Cable_Row/1.jpg']::text[], 'upright cable row keo thang dung cap remo al menton en polea'),
  (NULL, 'Upright Row - With Bands', 'Kéo thẳng đứng dây kháng lực', 'Upright Row - With Bands', 'Remo al mentón con banda', 'shoulders', 'band', 'compound', 'free_exercise_db', 'Upright_Row_-_With_Bands', ARRAY['To begin, stand on an exercise band so that tension begins at arm''s length. Grasp the handles using a pronated (palms facing your thighs) grip that is slightly less than shoulder width. The handles should be resting on top of your thighs. Your arms should be extended with a slight bend at the elbows and your back should be straight. This will be your starting position.', 'Use your side shoulders to lift the handles as you exhale. The handles should be close to the body as you move them up. Continue to lift the handles until they nearly touches your chin. Tip: Your elbows should drive the motion. As you lift the handles, your elbows should always be higher than your forearms. Also, keep your torso stationary and pause for a second at the top of the movement.', 'Lower the handles back down slowly to the starting position. Inhale as you perform this portion of the movement.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Upright_Row_-_With_Bands/0.jpg', 'Upright_Row_-_With_Bands/1.jpg']::text[], 'upright row - with bands keo thang dung day khang luc remo al menton con banda'),
  (NULL, 'Upward Stretch', 'Vươn người giãn cơ', 'Upward Stretch', 'Estiramiento hacia arriba', 'shoulders', 'other', 'timed', 'free_exercise_db', 'Upward_Stretch', ARRAY['Extend both hands straight above your head, palms touching.', 'Slowly push your hands up and back, keeping your back straight.']::text[], ARRAY['Upward_Stretch/0.jpg', 'Upward_Stretch/1.jpg']::text[], 'upward stretch vuon nguoi gian co estiramiento hacia arriba'),
  (NULL, 'V-Bar Pulldown', 'Kéo xà xuống thanh chữ V', 'V-Bar Pulldown', 'Jalón con barra en V', 'back', 'cable', 'compound', 'free_exercise_db', 'V-Bar_Pulldown', ARRAY['Sit down on a pull-down machine with a V-Bar attached to the top pulley.', 'Adjust the knee pad of the machine to fit your height. These pads will prevent your body from being raised by the resistance attached to the bar.', 'Grab the V-bar with the palms facing each other (a neutral grip). Stick your chest out and lean yourself back slightly (around 30-degrees) in order to better engage the lats. This will be your starting position.', 'Using your lats, pull the bar down as you squeeze your shoulder blades. Continue until your chest nearly touches the V-bar. Exhale as you execute this motion. Tip: Keep the torso stationary throughout the movement.', 'After a second hold on the contracted position, slowly bring the bar back to the starting position as you breathe in.', 'Repeat for the prescribed number of repetitions.']::text[], ARRAY['V-Bar_Pulldown/0.jpg', 'V-Bar_Pulldown/1.jpg']::text[], 'v-bar pulldown keo xa xuong thanh chu v jalon con barra en v'),
  (NULL, 'V-Bar Pullup', 'Hít xà thanh chữ V', 'V-Bar Pullup', 'Dominadas con barra en V', 'back', 'bodyweight', 'bodyweight', 'free_exercise_db', 'V-Bar_Pullup', ARRAY['Start by placing the middle of the V-bar in the middle of the pull-up bar (assuming that the pull-up station you are using does not have neutral grip handles). The V-Bar handles will be facing down so that you can hang from the pull-up bar through the use of the handles.', 'Once you securely place the V-bar, take a hold of the bar from each side and hang from it. Stick your chest out and lean yourself back slightly in order to better engage the lats. This will be your starting position.', 'Using your lats, pull your torso up while leaning your head back slightly so that you do not hit yourself with the chin-up bar. Continue until your chest nearly touches the V-bar. Exhale as you execute this motion.', 'After a second hold on the contracted position, slowly lower your body back to the starting position as you breathe in.', 'Repeat for the prescribed number of repetitions.']::text[], ARRAY['V-Bar_Pullup/0.jpg', 'V-Bar_Pullup/1.jpg']::text[], 'v-bar pullup hit xa thanh chu v dominadas con barra en v'),
  (NULL, 'Vertical Swing', 'Vertical Swing', 'Vertical Swing', 'Balanceo vertical con mancuerna', 'legs', 'dumbbell', 'compound', 'free_exercise_db', 'Vertical_Swing', ARRAY['Allow the dumbbell to hang at arms length between your legs, holding it with both hands. Keep your back straight and your head up.', 'Swing the dumbbell between your legs, flexing at the hips and bending the knees slightly.', 'Powerfully reverse the motion by extending at the hips, knees, and ankles to propel yourself upward, swinging the dumbell over your head.', 'As you land, absorb the impact through your legs and draw the dumbbell to your torso before the next repetition.']::text[], ARRAY['Vertical_Swing/0.jpg', 'Vertical_Swing/1.jpg']::text[], 'vertical swing vung ta don thang dung balanceo vertical con mancuerna'),
  (NULL, 'Walking, Treadmill', 'Đi bộ máy chạy bộ', 'Walking, Treadmill', 'Caminar en cinta', 'cardio', 'machine', 'timed', 'free_exercise_db', 'Walking_Treadmill', ARRAY['To begin, step onto the treadmill and select the desired option from the menu. Most treadmills have a manual setting, or you can select a program to run. Typically, you can enter your age and weight to estimate the amount of calories burned during exercise. Elevation can be adjusted to change the intensity of the workout.', 'Treadmills offer convenience, cardiovascular benefits, and usually have less impact than walking outside. When walking, you should move at a moderate to fast pace, not a leisurely one. Being an activity of lower intensity, walking doesn''t burn as many calories as some other activities, but still provides great benefit. A 150 lb person will burn about 175 calories walking 4 miles per hour for 30 minutes, compared to 450 calories running twice as fast. Maintain proper posture as you walk, and only hold onto the handles when necessary, such as when dismounting or checking your heart rate.']::text[], ARRAY['Walking_Treadmill/0.jpg', 'Walking_Treadmill/1.jpg']::text[], 'walking, treadmill di bo may chay bo caminar en cinta'),
  (NULL, 'Weighted Ball Hyperextension', 'Gập lưng ngược trên bóng có tạ', 'Weighted Ball Hyperextension', 'Hiperextensión en balón con peso', 'back', 'exercise ball', 'compound', 'free_exercise_db', 'Weighted_Ball_Hyperextension', ARRAY['To begin, lie down on an exercise ball with your torso pressing against the ball and parallel to the floor. The ball of your feet should be pressed against the floor to help keep you balanced. Place a weighted plate under your chin or behind your neck. This is the starting position.', 'Slowly raise your torso up by bending at the waist and lower back. Remember to exhale during this movement.', 'Hold the contraction on your lower back for a second and lower your torso back down to the starting position while inhaling.', 'Repeat for the recommended amount of repetitions prescribed in your program.']::text[], ARRAY['Weighted_Ball_Hyperextension/0.jpg', 'Weighted_Ball_Hyperextension/1.jpg']::text[], 'weighted ball hyperextension gap lung nguoc tren bong co ta hiperextension en balon con peso'),
  (NULL, 'Weighted Ball Side Bend', 'Nghiêng lườn trên bóng có tạ', 'Weighted Ball Side Bend', 'Flexión lateral en balón con peso', 'abs', 'exercise ball', 'isolation', 'free_exercise_db', 'Weighted_Ball_Side_Bend', ARRAY['To begin, lie down on an exercise ball with your left side of the torso (waist, hips and shoulder) pressed against the ball.', 'Your feet should be on the floor while your legs are crossed and hanging from the ball. Hold a weighted plate with your right hand directly to the right side of your head. Tip: Make sure the smooth side of the plate is resting against your head.', 'Place your left arm across your torso so that your palm is on your obliques. There should be a right angle between your left forearm and upper arm. This is the starting position.', 'Raise the side of your torso up by laterally flexing at the waist while exhaling.', 'Hold the contraction for a second and slowly lower yourself back down to the starting position while inhaling.', 'Repeat for the recommended amount of repetitions.', 'Switch sides and repeat the exercise.']::text[], ARRAY['Weighted_Ball_Side_Bend/0.jpg', 'Weighted_Ball_Side_Bend/1.jpg']::text[], 'weighted ball side bend nghieng luon tren bong co ta flexion lateral en balon con peso'),
  (NULL, 'Weighted Bench Dip', 'Weighted Bench Dip', 'Weighted Bench Dip', 'Fondos en banco con peso', 'triceps', 'other', 'compound', 'free_exercise_db', 'Weighted_Bench_Dip', ARRAY['For this exercise you will need to place a bench behind your back and another one in front of you. With the benches perpendicular to your body, hold on to one bench on its edge with the hands close to your body, separated at shoulder width. Your arms should be fully extended.', 'The legs will be extended forward on top of the other bench. Your legs should be parallel to the floor while your torso is to be perpendicular to the floor. Have your partner place the dumbbell on your lap. Note: This exercise is best performed with a partner as placing the weight on your lap can be challenging and cause injury without assistance. This will be your starting position.', 'Slowly lower your body as you inhale by bending at the elbows until you lower yourself far enough to where there is an angle slightly smaller than 90 degrees between the upper arm and the forearm. Tip: Keep the elbows as close as possible throughout the movement. Forearms should always be pointing down.', 'Using your triceps to bring your torso up again, lift yourself back to the starting position while exhaling.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Weighted_Bench_Dip/0.jpg', 'Weighted_Bench_Dip/1.jpg']::text[], 'weighted bench dip dips tren ghe co ta fondos en banco con peso'),
  (NULL, 'Weighted Crunches', 'Weighted Crunches', 'Weighted Crunches', 'Crunch con peso', 'abs', 'medicine ball', 'isolation', 'free_exercise_db', 'Weighted_Crunches', ARRAY['Lie flat on your back with your feet flat on the ground or resting on a bench with your knees bent at a 90 degree angle.', 'Hold a weight to your chest, or you may hold it extended above your torso. This will be your starting position.', 'Now, exhale and slowly begin to roll your shoulders off the floor. Your shoulders should come up off the floor about 4 inches while your lower back remains on the floor.', 'At the top of the movement, flex your abdominals and hold for a brief pause.', 'Then inhale and slowly lower yourself back down to the starting position.']::text[], ARRAY['Weighted_Crunches/0.jpg', 'Weighted_Crunches/1.jpg']::text[], 'weighted crunches gap bung co ta crunch con peso'),
  (NULL, 'Weighted Jump Squat', 'Weighted Jump Squat', 'Weighted Jump Squat', 'Sentadilla con salto con peso', 'legs', 'barbell', 'compound', 'free_exercise_db', 'Weighted_Jump_Squat', ARRAY['Position a lightly loaded barbell across the back of your shoulders. You could also use a weighted vest, sandbag, or other type of resistance for this exercise.', 'The weight should be light enough that it doesn''t slow you down significantly. Your feet should be just outside of shoulder width with your head and chest up. This will be your starting position.', 'Using a countermovement, squat partially down and immediately reverse your direction to explode off of the ground, extending through your hips, knees, and ankles. Maintain good posture throughout the jump.', 'As you return to the ground, absorb the impact through your legs.']::text[], ARRAY['Weighted_Jump_Squat/0.jpg', 'Weighted_Jump_Squat/1.jpg']::text[], 'weighted jump squat squat bat nhay co ta sentadilla con salto con peso'),
  (NULL, 'Weighted Pull Ups', 'Hít xà có tạ', 'Weighted Pull Ups', 'Dominadas con peso', 'back', 'other', 'compound', 'free_exercise_db', 'Weighted_Pull_Ups', ARRAY['Attach a weight to a dip belt and secure it around your waist. Grab the pull-up bar with the palms of your hands facing forward. For a medium grip, your hands should be spaced at shoulder width. Both arms should be extended in front of you holding the bar at the chosen grip.', 'You''ll want to bring your torso back about 30 degrees while creating a curvature in your lower back and sticking your chest out. This will be your starting position.', 'Now, exhale and pull your torso up until your head is above your hands. Concentrate on squeezing yourshoulder blades back and down as you reach the top contracted position.', 'After a brief moment at the top contracted position, inhale and slowly lower your torso back to the starting position with your arms extended and your lats fully stretched.']::text[], ARRAY['Weighted_Pull_Ups/0.jpg', 'Weighted_Pull_Ups/1.jpg']::text[], 'weighted pull ups hit xa co ta dominadas con peso'),
  (NULL, 'Weighted Sissy Squat', 'Weighted Sissy Squat', 'Weighted Sissy Squat', 'Sentadilla sissy con peso', 'legs', 'barbell', 'compound', 'free_exercise_db', 'Weighted_Sissy_Squat', ARRAY['Standing upright, with feet at shoulder width and toes raised, use one hand to hold onto the beams of a squat rack and the opposite arm to hold a plate on top of your chest. This is your starting position.', 'As you use one arm to hold yourself, bend at the knees and slowly lower your torso toward the ground by bringing your pelvis and knees forward. Inhale as you go down and stop when your upper and lower legs almost create a 90-degree angle. Hold the stretch position for a second.', 'After your one second hold, use your thigh muscles to bring your torso back up to the starting position. Exhale as you move up.', 'Repeat for the recommended amount of times.']::text[], ARRAY['Weighted_Sissy_Squat/0.jpg', 'Weighted_Sissy_Squat/1.jpg']::text[], 'weighted sissy squat sissy squat co ta sentadilla sissy con peso'),
  (NULL, 'Weighted Sit-Ups - With Bands', 'Gập bụng ngồi dậy có tạ và dây', 'Weighted Sit-Ups - With Bands', 'Abdominales con peso y bandas', 'abs', 'other', 'isolation', 'free_exercise_db', 'Weighted_Sit-Ups_-_With_Bands', ARRAY['Start out by strapping the bands around the base of the decline bench. Place the handles towards the inside of the decline bench so that when lying down, you can reach for both of them.', 'Position your legs through the decline machine until they are secured. Now reach for the exercise bands with both hands. Use a pronated (palms forward) grip to grasp the handles. Position them near your collar bone and rotate your wrist to a neutral grip (palms facing the torso). Note: Your arms should remain stationary throughout the exercise. This is the starting position.', 'Move your torso upward until your upper body is perpendicular to the floor while exhaling. Hold the contraction for a second and lower your upper body back down to the starting position while inhaling.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Weighted_Sit-Ups_-_With_Bands/0.jpg', 'Weighted_Sit-Ups_-_With_Bands/1.jpg']::text[], 'weighted sit-ups - with bands gap bung ngoi day co ta va day abdominales con peso y bandas'),
  (NULL, 'Weighted Squat', 'Weighted Squat', 'Weighted Squat', 'Sentadilla con peso', 'legs', 'other', 'compound', 'free_exercise_db', 'Weighted_Squat', ARRAY['Start by positioning two flat benches shoulder width apart from each other. Stand on top of them and wrap the weighted belt around your waist with the amount of weight you feel comfortable with. Make sure your toes are facing out.', 'Once you are standing straight up with the weight hanging in between your legs, position your arms so that they are fully extended to the side of your body. This is the starting position.', 'Begin by bending the knees as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to the floor). Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that are perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.', 'Begin to move the body back up by pushing the floor of the flat bench with the ball of your foot mainly as you straighten the legs again and go back to the starting position. Exhale as you perform this portion of the exercise.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Weighted_Squat/0.jpg', 'Weighted_Squat/1.jpg']::text[], 'weighted squat squat co ta sentadilla con peso'),
  (NULL, 'Wide-Grip Barbell Bench Press', 'Wide-Grip Barbell Bench Press', 'Wide-Grip Barbell Bench Press', 'Press de banca con barra agarre ancho', 'chest', 'barbell', 'compound', 'free_exercise_db', 'Wide-Grip_Barbell_Bench_Press', ARRAY['Lie back on a flat bench with feet firm on the floor. Using a wide, pronated (palms forward) grip that is around 3 inches away from shoulder width (for each hand), lift the bar from the rack and hold it straight over you with your arms locked. The bar will be perpendicular to the torso and the floor. This will be your starting position.', 'As you breathe in, come down slowly until you feel the bar on your middle chest.', 'After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles. Lock your arms and squeeze your chest in the contracted position, hold for a second and then start coming down slowly again. Tip: It should take at least twice as long to go down than to come up.', 'Repeat the movement for the prescribed amount of repetitions.']::text[], ARRAY['Wide-Grip_Barbell_Bench_Press/0.jpg', 'Wide-Grip_Barbell_Bench_Press/1.jpg']::text[], 'wide-grip barbell bench press day nguc ta don nam rong press de banca con barra agarre ancho'),
  (NULL, 'Wide-Grip Decline Barbell Bench Press', 'Wide-Grip Decline Barbell Bench Press', 'Wide-Grip Decline Barbell Bench Press', 'Press declinado con barra agarre ancho', 'chest', 'barbell', 'compound', 'free_exercise_db', 'Wide-Grip_Decline_Barbell_Bench_Press', ARRAY['Lie back on a decline bench with the feet securely locked at the front of the bench. Using a wide, pronated (palms forward) grip that is around 3 inches away from shoulder width (for each hand), lift the bar from the rack and hold it straight over you with your arms locked. The bar will be perpendicular to the torso and the floor. This will be your starting position.', 'As you breathe in, come down slowly until you feel the bar on your lower chest.', 'After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles. Lock your arms and squeeze your chest in the contracted position, hold for a second and then start coming down slowly again. Tip: It should take at least twice as long to go down than to come up.', 'Repeat the movement for the prescribed amount of repetitions.']::text[], ARRAY['Wide-Grip_Decline_Barbell_Bench_Press/0.jpg', 'Wide-Grip_Decline_Barbell_Bench_Press/1.jpg']::text[], 'wide-grip decline barbell bench press day nguc doc xuong ta don nam rong press declinado con barra agarre ancho'),
  (NULL, 'Wide-Grip Decline Barbell Pullover', 'Wide-Grip Decline Barbell Pullover', 'Wide-Grip Decline Barbell Pullover', 'Pullover declinado con barra agarre ancho', 'chest', 'barbell', 'compound', 'free_exercise_db', 'Wide-Grip_Decline_Barbell_Pullover', ARRAY['Lie down on a decline bench with both legs securely locked in position. Reach for the barbell behind the head using a pronated grip (palms facing out). Make sure to grab the barbell wider than shoulder width apart for this exercise. Slowly lift the barbell up from the floor by using your arms.', 'When positioned properly, your arms should be fully extended and perpendicular to the floor. This is the starting position.', 'Begin by moving the barbell back down in a semicircular motion as if you were going to place it on the floor, but instead, stop when the arms are parallel to the floor. Tip: Keep the arms fully extended at all times. The movement should only happen at the shoulder joint. Inhale as you perform this portion of the movement.', 'Now bring the barbell up while exhaling until you are back at the starting position. Remember to keep full control of the barbell at all times.', 'Repeat the movement for the prescribed amount of repetitions of your training program.', 'When finished with your set, slowly lower the barbell back down until it is level with your head and release it.']::text[], ARRAY['Wide-Grip_Decline_Barbell_Pullover/0.jpg', 'Wide-Grip_Decline_Barbell_Pullover/1.jpg']::text[], 'wide-grip decline barbell pullover keo ta don qua dau doc xuong nam rong pullover declinado con barra agarre ancho'),
  (NULL, 'Wide-Grip Lat Pulldown', 'Wide-Grip Lat Pulldown', 'Wide-Grip Lat Pulldown', 'Jalón al pecho agarre ancho', 'back', 'cable', 'compound', 'free_exercise_db', 'Wide-Grip_Lat_Pulldown', ARRAY['Sit down on a pull-down machine with a wide bar attached to the top pulley. Make sure that you adjust the knee pad of the machine to fit your height. These pads will prevent your body from being raised by the resistance attached to the bar.', 'Grab the bar with the palms facing forward using the prescribed grip. Note on grips: For a wide grip, your hands need to be spaced out at a distance wider than shoulder width. For a medium grip, your hands need to be spaced out at a distance equal to your shoulder width and for a close grip at a distance smaller than your shoulder width.', 'As you have both arms extended in front of you holding the bar at the chosen grip width, bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.', 'As you breathe out, bring the bar down until it touches your upper chest by drawing the shoulders and the upper arms down and back. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary and only the arms should move. The forearms should do no other work except for holding the bar; therefore do not try to pull down the bar using the forearms.', 'After a second at the contracted position squeezing your shoulder blades together, slowly raise the bar back to the starting position when your arms are fully extended and the lats are fully stretched. Inhale during this portion of the movement.', 'Repeat this motion for the prescribed amount of repetitions.']::text[], ARRAY['Wide-Grip_Lat_Pulldown/0.jpg', 'Wide-Grip_Lat_Pulldown/1.jpg']::text[], 'wide-grip lat pulldown keo xa xuong nam rong jalon al pecho agarre ancho'),
  (NULL, 'Wide-Grip Pulldown Behind The Neck', 'Kéo xà xuống sau gáy nắm rộng', 'Wide-Grip Pulldown Behind The Neck', 'Jalón tras nuca agarre ancho', 'back', 'cable', 'compound', 'free_exercise_db', 'Wide-Grip_Pulldown_Behind_The_Neck', ARRAY['Sit down on a pull-down machine with a wide bar attached to the top pulley. Make sure that you adjust the knee pad of the machine to fit your height. These pads will prevent your body from being raised by the resistance attached to the bar.', 'Grab the bar with the palms facing forward using the prescribed grip. Note on grips: For a wide grip, your hands need to be spaced out at a distance wider than your shoulder width. For a medium grip, your hands need to be spaced out at a distance equal to your shoulder width and for a close grip at a distance smaller than your shoulder width.', 'As you have both arms extended in front of you holding the bar at the chosen grip width, bring your torso and head forward. Think of an imaginary line from the center of the bar down to the back of your neck. This is your starting position.', 'As you breathe out, bring the bar down until it touches the back of your neck by drawing the shoulders and the upper arms down and back. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary and only the arms should move. The forearms should do no other work except for holding the bar; therefore do not try to pull down the bar using the forearms.', 'After a second on the contracted position squeezing your shoulder blades together, slowly raise the bar back to the starting position when your arms are fully extended and the lats are fully stretched. Inhale during this portion of the movement.', 'Repeat this motion for the prescribed amount of repetitions.']::text[], ARRAY['Wide-Grip_Pulldown_Behind_The_Neck/0.jpg', 'Wide-Grip_Pulldown_Behind_The_Neck/1.jpg']::text[], 'wide-grip pulldown behind the neck keo xa xuong sau gay nam rong jalon tras nuca agarre ancho'),
  (NULL, 'Wide-Grip Rear Pull-Up', 'Hít xà sau gáy nắm rộng', 'Wide-Grip Rear Pull-Up', 'Dominadas tras nuca agarre ancho', 'back', 'bodyweight', 'bodyweight', 'free_exercise_db', 'Wide-Grip_Rear_Pull-Up', ARRAY['Grab the pull-up bar with the palms facing forward using a wide grip.', 'As you have both arms extended in front of you holding the bar, bring your torso forward and head so that there is an imaginary line from the pull-up bar to the back of your neck. This is your starting position.', 'Pull your torso up until the bar is near the back of your neck. To do this, draw the shoulders and upper arms down and back while slightly leaning your head forward. Exhale as you perform this portion of the movement. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary as it moves through space and only the arms should move. The forearms should do no other work other than hold the bar.', 'After a second on the contracted position, start to inhale and slowly lower your torso back to the starting position when your arms are fully extended and the lats are fully stretched.', 'Repeat this motion for the prescribed amount of repetitions.']::text[], ARRAY['Wide-Grip_Rear_Pull-Up/0.jpg', 'Wide-Grip_Rear_Pull-Up/1.jpg']::text[], 'wide-grip rear pull-up hit xa sau gay nam rong dominadas tras nuca agarre ancho'),
  (NULL, 'Wide-Grip Standing Barbell Curl', 'Wide-Grip Standing Barbell Curl', 'Wide-Grip Standing Barbell Curl', 'Curl de pie con barra agarre ancho', 'biceps', 'barbell', 'isolation', 'free_exercise_db', 'Wide-Grip_Standing_Barbell_Curl', ARRAY['Stand up with your torso upright while holding a barbell at the wide outer handle. The palm of your hands should be facing forward. The elbows should be close to the torso. This will be your starting position.', 'While holding the upper arms stationary, curl the weights forward while contracting the biceps as you breathe out. Tip: Only the forearms should move.', 'Continue the movement until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a second and squeeze the biceps hard.', 'Slowly begin to bring the bar back to starting position as your breathe in.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Wide-Grip_Standing_Barbell_Curl/0.jpg', 'Wide-Grip_Standing_Barbell_Curl/1.jpg']::text[], 'wide-grip standing barbell curl cuon ta don dung nam rong curl de pie con barra agarre ancho'),
  (NULL, 'Wide Stance Barbell Squat', 'Wide Stance Barbell Squat', 'Wide Stance Barbell Squat', 'Sentadilla con barra postura amplia', 'legs', 'barbell', 'compound', 'free_exercise_db', 'Wide_Stance_Barbell_Squat', ARRAY['This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.', 'Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.', 'Step away from the rack and position your legs using a wider-than-shoulder-width stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance, and also maintain a straight back. This will be your starting position.', 'Begin to slowly lower the bar by bending the knees as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to the floor). Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.', 'Begin to raise the bar as you exhale by pushing the floor with the heel of your foot as you straighten the legs again and go back to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Wide_Stance_Barbell_Squat/0.jpg', 'Wide_Stance_Barbell_Squat/1.jpg']::text[], 'wide stance barbell squat squat ta don dung rong sentadilla con barra postura amplia'),
  (NULL, 'Wide Stance Stiff Legs', 'Deadlift chân thẳng đứng rộng', 'Wide Stance Stiff Legs', 'Peso muerto piernas rígidas postura amplia', 'legs', 'barbell', 'compound', 'free_exercise_db', 'Wide_Stance_Stiff_Legs', ARRAY['Begin with a barbell loaded on the floor. Adopt a wide stance, and then bend at the hips to grab the bar. Your hips should be as far back as possible, and your legs nearly straight. Keep your back straight, and your head and chest up. This will be your starting position.', 'Begin the movement be engaging the hips, driving them forward as you allow the arms to hang straight. Continue until you are standing straight up, and then slowly return the weight to the starting position. For successive reps, the weight need not touch the floor.']::text[], ARRAY['Wide_Stance_Stiff_Legs/0.jpg', 'Wide_Stance_Stiff_Legs/1.jpg']::text[], 'wide stance stiff legs deadlift chan thang dung rong peso muerto piernas rigidas postura amplia'),
  (NULL, 'Wind Sprints', 'Chạy nước rút ngắn', 'Wind Sprints', 'Sprints de viento', 'abs', 'bodyweight', 'bodyweight', 'free_exercise_db', 'Wind_Sprints', ARRAY['Hang from a pull-up bar using a pronated grip. Your arms and legs should be extended. This will be your starting position.', 'Begin by quickly raising one knee as high as you can. Do not swing your body or your legs. 3', 'Immediately reverse the motion, returning that leg to the starting position. Simultaneously raise the opposite knee as high as possible.', 'Continue alternating between legs until the set is complete.']::text[], ARRAY['Wind_Sprints/0.jpg', 'Wind_Sprints/1.jpg']::text[], 'wind sprints chay nuoc rut ngan sprints de viento'),
  (NULL, 'Windmills', 'Cối xay gió', 'Windmills', 'Molinos', 'legs', 'other', 'timed', 'free_exercise_db', 'Windmills', ARRAY['Lie on your back with your arms extended out to the sides and your legs straight. This will be your starting position.', 'Lift one leg and quickly cross it over your body, attempting to touch the ground near the opposite hand.', 'Return to the starting position, and repeat with the opposite leg. Continue to alternate for 10-20 repetitions.']::text[], ARRAY['Windmills/0.jpg', 'Windmills/1.jpg']::text[], 'windmills coi xay gio molinos'),
  (NULL, 'World''s Greatest Stretch', 'Bài giãn cơ toàn thân tốt nhất', 'World''s Greatest Stretch', 'El mejor estiramiento del mundo', 'legs', 'other', 'timed', 'free_exercise_db', 'Worlds_Greatest_Stretch', ARRAY['This is a three-part stretch. Begin by lunging forward, with your front foot flat on the ground and on the toes of your back foot. With your knees bent, squat down until your knee is almost touching the ground. Keep your torso erect, and hold this position for 10-20 seconds.', 'Now, place the arm on the same side as your front leg on the ground, with the elbow next to the foot. Your other hand should be placed on the ground, parallel to your lead leg, to help support you during this portion of the stretch.', 'After 10-20 seconds, place your hands on either side of your front foot. Raise the toes of the front foot off of the ground, and straighten your leg. You may need to reposition your rear leg to do so. Hold for 10-20 seconds, and then repeat the entire sequence for the other side.']::text[], ARRAY['Worlds_Greatest_Stretch/0.jpg', 'Worlds_Greatest_Stretch/1.jpg']::text[], 'world''s greatest stretch bai gian co toan than tot nhat el mejor estiramiento del mundo'),
  (NULL, 'Wrist Circles', 'Xoay cổ tay', 'Wrist Circles', 'Círculos de muñeca', 'biceps', 'bodyweight', 'timed', 'free_exercise_db', 'Wrist_Circles', ARRAY['Start by standing straight with your feet being shoulder width apart from each other. Elevate your arms to the side of you until they are fully extended and parallel to the floor at a height that is evenly aligned with your shoulders. Tip: Your torso and arms should form the letter "T: Your palms should be facing down. This is the starting position.', 'Keeping your entire body stationary except for the wrists, begin to rotate both wrists forward in a circular motion. Tip: Pretend that you are trying to draw circles by using your hands as the brush. Breathe normally as you perform this exercise.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Wrist_Circles/0.jpg', 'Wrist_Circles/1.jpg']::text[], 'wrist circles xoay co tay circulos de muneca'),
  (NULL, 'Wrist Roller', 'Cuộn dây cổ tay', 'Wrist Roller', 'Rodillo de muñeca', 'biceps', 'other', 'isolation', 'free_exercise_db', 'Wrist_Roller', ARRAY['To begin, stand straight up grabbing a wrist roller using a pronated grip (palms facing down). Your feet should be shoulder width apart.', 'Slowly lift both arms until they are fully extended and parallel to the floor in front of you. Note: Make sure the rope is not wrapped around the roller. Your entire body should be stationary except for the forearms. This is the starting position.', 'Rotate one wrist at a time in an upward motion to bring the weight up to the bar by rolling the rope around the roller.', 'Once the weight has reached the bar, slowly begin to lower the weight back down by rotating the wrist in a downward motion until the weight reaches the starting position.', 'Repeat for the prescribed amount of repetitions in your program.']::text[], ARRAY['Wrist_Roller/0.jpg', 'Wrist_Roller/1.jpg']::text[], 'wrist roller cuon day co tay rodillo de muneca'),
  (NULL, 'Wrist Rotations with Straight Bar', 'Xoay cổ tay với thanh thẳng', 'Wrist Rotations with Straight Bar', 'Rotaciones de muñeca con barra recta', 'biceps', 'barbell', 'isolation', 'free_exercise_db', 'Wrist_Rotations_with_Straight_Bar', ARRAY['Hold a barbell with both hands and your palms facing down; hands spaced about shoulder width. This will be your starting position.', 'Alternating between each of your hands, perform the movement by extending the wrist as though you were rolling up a newspaper. Continue alternating back and forth until failure.', 'Reverse the motion by flexing the wrist, rolling the opposite direction. Continue the alternating motion until failure.']::text[], ARRAY['Wrist_Rotations_with_Straight_Bar/0.jpg', 'Wrist_Rotations_with_Straight_Bar/1.jpg']::text[], 'wrist rotations with straight bar xoay co tay voi thanh thang rotaciones de muneca con barra recta'),
  (NULL, 'Yoke Walk', 'Gánh đòn đi bộ', 'Yoke Walk', 'Caminata con yugo', 'legs', 'other', 'compound', 'free_exercise_db', 'Yoke_Walk', ARRAY['The yoke is usually done with a yoke apparatus, but is sometimes seen with refrigerators or other heavy objects.', 'Begin by racking the apparatus across the back of the shoulders. With your head looking forward and back arched, lift the yoke by driving through the heels.', 'Begin walking as quickly as possible using short, quick steps. You may hold the side posts of the yoke to help steady it and hold it in position. Continue for the given distance as fast as possible, usually 75-100 feet.']::text[], ARRAY['Yoke_Walk/0.jpg', 'Yoke_Walk/1.jpg']::text[], 'yoke walk ganh don di bo caminata con yugo'),
  (NULL, 'Zercher Squats', 'Zercher Squats', 'Zercher Squats', 'Sentadilla Zercher', 'legs', 'barbell', 'compound', 'free_exercise_db', 'Zercher_Squats', ARRAY['This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. The correct height should be anywhere above the waist but below the chest. Once the correct height is chosen and the bar is loaded, lock your hands together and place the bar on top of your arms in between the forearm and upper arm.', 'Lift the bar up so that it is resting on top of your forearms. If you are holding the bar properly, it should look as if you have your arms crossed but with a bar running across them.', 'Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance and also maintain a straight back. This will be your starting position. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances discussed in the foot stances section).', 'Begin to lower the bar by bending the knees as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to the floor). Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.', 'Begin to raise the bar as you exhale by pushing the floor with the ball of your foot mainly as you straighten the legs again and go back to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Zercher_Squats/0.jpg', 'Zercher_Squats/1.jpg']::text[], 'zercher squats squat zercher sentadilla zercher'),
  (NULL, 'Zottman Curl', 'Zottman Curl', 'Zottman Curl', 'Curl Zottman', 'biceps', 'dumbbell', 'isolation', 'free_exercise_db', 'Zottman_Curl', ARRAY['Stand up with your torso upright and a dumbbell in each hand being held at arms length. The elbows should be close to the torso.', 'Make sure the palms of the hands are facing each other. This will be your starting position.', 'While holding the upper arm stationary, curl the weights while contracting the biceps as you breathe out. Only the forearms should move. Your wrist should rotate so that you have a supinated (palms up) grip. Continue the movement until your biceps are fully contracted and the dumbbells are at shoulder level.', 'Hold the contracted position for a second as you squeeze the biceps.', 'Now during the contracted position, rotate your wrist until you now have a pronated (palms facing down) grip with the thumb at a higher position than the pinky.', 'Slowly begin to bring the dumbbells back down using the pronated grip.', 'As the dumbbells close your thighs, start rotating the wrist so that you go back to a neutral (palms facing your body) grip.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Zottman_Curl/0.jpg', 'Zottman_Curl/1.jpg']::text[], 'zottman curl cuon zottman curl zottman'),
  (NULL, 'Zottman Preacher Curl', 'Zottman Preacher Curl', 'Zottman Preacher Curl', 'Curl Zottman predicador', 'biceps', 'dumbbell', 'isolation', 'free_exercise_db', 'Zottman_Preacher_Curl', ARRAY['Grab a dumbbell in each hand and place your upper arms on top of the preacher bench or the incline bench. The dumbbells should be held at shoulder height and the elbows should be flexed. Hold the dumbbells with the palms of your hands facing down. This will be your starting position.', 'As you breathe in, slowly lower the dumbbells keeping the palms down until your upper arm is extended and your biceps are fully stretched.', 'Now rotate your wrists once you are at the bottom of the movement so that the palms of the hands are facing up.', 'As you exhale, use your biceps to curl the weights up until they are fully contracted and the dumbbells are at shoulder height. Again, remember that to ensure full contraction you need to bring that small finger higher than the thumb.', 'Squeeze the biceps hard for a second at the contracted position and rotate your wrists so that the palms are facing down again.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['Zottman_Preacher_Curl/0.jpg', 'Zottman_Preacher_Curl/1.jpg']::text[], 'zottman preacher curl cuon zottman ghe doc curl zottman predicador')
ON CONFLICT (source, source_ref) WHERE source IS NOT NULL DO UPDATE SET
  name_vi = EXCLUDED.name_vi, name_en = EXCLUDED.name_en, name_es = EXCLUDED.name_es,
  muscle_group = EXCLUDED.muscle_group, equipment = EXCLUDED.equipment, exercise_kind = EXCLUDED.exercise_kind,
  instructions_en = EXCLUDED.instructions_en, image_paths = EXCLUDED.image_paths,
  search_text = EXCLUDED.search_text, updated_at = now();

-- Loại động tác khai báo theo tên (luật gate `exercise-intelligence` #14: mọi bài
-- seed phải được một câu SET exercise_kind gọi tên). Trùng với giá trị INSERT ở trên;
-- chạy lại vô hại.
